schema.sql:
-- SPDX-License-Identifier: 0BSD
-- DesKilo core schema (Epic #2, issue #23).
-- Applied to the hosted reference project on 2026-07-07 as migration
-- "core_profiles_workspaces_members". Self-hosters apply this file.
create extension if not exists pgcrypto;

-- profiles: 1:1 with auth.users, created by trigger on signup
create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  display_name text not null default '' check (char_length(display_name) <= 80),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, display_name)
  values (
    new.id,
    coalesce(new.raw_user_meta_data->>'display_name', split_part(new.email, '@', 1), '')
  );
  return new;
end;
$$;

create trigger on_auth_user_created
after insert on auth.users
for each row execute function public.handle_new_user();

-- invite code: 10 chars from an unambiguous alphabet
create or replace function public.gen_invite_code()
returns text
language sql
volatile
set search_path = public
as $$
  select string_agg(substr('ABCDEFGHJKLMNPQRSTUVWXYZ23456789', (floor(random()*32))::int + 1, 1), '')
  from generate_series(1, 10);
$$;

create table public.workspaces (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 1 and 120),
  country_code text not null check (country_code ~ '^[A-Z]{2}$'),
  currency_code text not null check (currency_code ~ '^[A-Z]{3}$'),
  timezone text not null,
  invite_code text not null unique default public.gen_invite_code(),
  created_by uuid not null references auth.users(id),
  created_at timestamptz not null default now()
);

create table public.members (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  is_admin boolean not null default false,
  is_owner boolean not null default false,
  status text not null default 'active' check (status in ('active','paused','exited')),
  joined_at timestamptz not null default now(),
  unique (workspace_id, user_id)
);
create index members_user_idx on public.members (user_id);
create index members_workspace_idx on public.members (workspace_id);

-- role helpers (security definer: also used by RLS policies without recursion)
create or replace function public.is_member_of(ws uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.members m
    where m.workspace_id = ws and m.user_id = auth.uid() and m.status <> 'exited'
  );
$$;

create or replace function public.is_admin_of(ws uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.members m
    where m.workspace_id = ws and m.user_id = auth.uid()
      and m.status = 'active' and (m.is_admin or m.is_owner)
  );
$$;

create or replace function public.is_owner_of(ws uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.members m
    where m.workspace_id = ws and m.user_id = auth.uid()
      and m.status = 'active' and m.is_owner
  );
$$;

create or replace function public.shares_workspace_with(other uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1
    from public.members me
    join public.members them on me.workspace_id = them.workspace_id
    where me.user_id = auth.uid() and them.user_id = other
      and me.status <> 'exited' and them.status <> 'exited'
  );
$$;

-- a workspace must never lose its last active owner (spec §2)
create or replace function public.protect_last_owner()
returns trigger language plpgsql security definer set search_path = public as $$
declare remaining int;
begin
  if old.is_owner and old.status = 'active'
     and (tg_op = 'DELETE' or (not new.is_owner or new.status <> 'active')) then
    select count(*) into remaining from public.members
    where workspace_id = old.workspace_id and is_owner and status = 'active' and id <> old.id;
    if remaining = 0 then
      raise exception 'cannot remove the last owner of a workspace';
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;

create trigger members_protect_last_owner
before update or delete on public.members
for each row execute function public.protect_last_owner();

-- RPCs (the only write path for workspaces/members besides owner updates)
create or replace function public.create_workspace(
  p_name text, p_country_code text, p_currency_code text, p_timezone text
) returns uuid language plpgsql security definer set search_path = public as $$
declare ws_id uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  insert into public.workspaces (name, country_code, currency_code, timezone, created_by)
  values (p_name, upper(p_country_code), upper(p_currency_code), p_timezone, auth.uid())
  returning id into ws_id;
  insert into public.members (workspace_id, user_id, is_admin, is_owner)
  values (ws_id, auth.uid(), true, true);
  return ws_id;
end;
$$;

create or replace function public.join_workspace(p_invite_code text)
returns uuid language plpgsql security definer set search_path = public as $$
declare ws_id uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select id into ws_id from public.workspaces where invite_code = upper(trim(p_invite_code));
  if ws_id is null then raise exception 'invalid invite code'; end if;
  insert into public.members (workspace_id, user_id)
  values (ws_id, auth.uid())
  on conflict (workspace_id, user_id)
    do update set status = 'active' where public.members.status = 'exited';
  return ws_id;
end;
$$;

create or replace function public.leave_workspace(p_workspace_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  update public.members set status = 'exited'
  where workspace_id = p_workspace_id and user_id = auth.uid();
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- DesKilo RLS (Epic #2, issue #24). Applied to the hosted reference project
-- on 2026-07-07 as migration "rls_core_tables".
--
-- Writes to workspaces/members happen via SECURITY DEFINER RPCs except
-- owner-managed member updates. No insert policies on purpose: default-deny.
alter table public.profiles enable row level security;
alter table public.workspaces enable row level security;
alter table public.members enable row level security;

-- profiles: self + people who share a workspace with you
create policy profiles_select on public.profiles
  for select using (id = auth.uid() or public.shares_workspace_with(id));
create policy profiles_update on public.profiles
  for update using (id = auth.uid()) with check (id = auth.uid());

-- workspaces: members read; owners update/delete
create policy workspaces_select on public.workspaces
  for select using (public.is_member_of(id));
create policy workspaces_update on public.workspaces
  for update using (public.is_owner_of(id)) with check (public.is_owner_of(id));
create policy workspaces_delete on public.workspaces
  for delete using (public.is_owner_of(id));

-- members: co-members read; owners manage (last-owner trigger still guards)
create policy members_select on public.members
  for select using (public.is_member_of(workspace_id));
create policy members_update_owner on public.members
  for update using (public.is_owner_of(workspace_id))
  with check (public.is_owner_of(workspace_id));
create policy members_delete_owner on public.members
  for delete using (public.is_owner_of(workspace_id));

-- SPDX-License-Identifier: 0BSD
-- DesKilo floor-plan schema (Epic #3, issue #31). Applied to the hosted
-- reference project on 2026-07-07 as "floor_plan_levels_offices_desks_seats".
-- Grid-cell geometry per ADR 0005; workspace_id denormalized for cheap RLS.

create table public.levels (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  name text not null check (char_length(name) between 1 and 80),
  sort_order int not null default 0,
  created_at timestamptz not null default now()
);
create index levels_workspace_idx on public.levels (workspace_id);

create table public.offices (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  level_id uuid not null references public.levels(id) on delete cascade,
  name text not null check (char_length(name) between 1 and 80),
  color int not null default 0,
  bookable_as_whole boolean not null default false,
  x int not null check (x >= 0),
  y int not null check (y >= 0),
  w int not null check (w > 0),
  h int not null check (h > 0),
  created_at timestamptz not null default now()
);
create index offices_level_idx on public.offices (level_id);
create index offices_workspace_idx on public.offices (workspace_id);

create table public.desks (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  office_id uuid not null references public.offices(id) on delete cascade,
  name text not null default '' check (char_length(name) <= 80),
  x int not null check (x >= 0),
  y int not null check (y >= 0),
  w int not null check (w > 0),
  h int not null check (h > 0),
  created_at timestamptz not null default now()
);
create index desks_office_idx on public.desks (office_id);
create index desks_workspace_idx on public.desks (workspace_id);

-- seat: THE bookable unit (spec §3). Footprint is always 6 cells along the
-- sitting edge × 4 cells deep; orientation n/e/s/w = where the sitter faces,
-- so n/s footprints are 6w×4h and e/w footprints are 4w×6h.
create table public.seats (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  desk_id uuid not null references public.desks(id) on delete cascade,
  name text not null default '' check (char_length(name) <= 80),
  x int not null check (x >= 0),
  y int not null check (y >= 0),
  orientation text not null default 'n' check (orientation in ('n','e','s','w')),
  chair text not null default '',
  amenities text[] not null default '{}',
  blocked_from timestamptz,
  blocked_to timestamptz,
  created_at timestamptz not null default now()
);
create index seats_desk_idx on public.seats (desk_id);
create index seats_workspace_idx on public.seats (workspace_id);

alter table public.levels enable row level security;
alter table public.offices enable row level security;
alter table public.desks enable row level security;
alter table public.seats enable row level security;

create policy levels_select on public.levels
  for select using (public.is_member_of(workspace_id));
create policy levels_write on public.levels
  for all using (public.is_owner_of(workspace_id))
  with check (public.is_owner_of(workspace_id));

create policy offices_select on public.offices
  for select using (public.is_member_of(workspace_id));
create policy offices_write on public.offices
  for all using (public.is_owner_of(workspace_id))
  with check (public.is_owner_of(workspace_id));

create policy desks_select on public.desks
  for select using (public.is_member_of(workspace_id));
create policy desks_write on public.desks
  for all using (public.is_owner_of(workspace_id))
  with check (public.is_owner_of(workspace_id));

create policy seats_select on public.seats
  for select using (public.is_member_of(workspace_id));
create policy seats_write on public.seats
  for all using (public.is_owner_of(workspace_id))
  with check (public.is_owner_of(workspace_id));

-- SPDX-License-Identifier: 0BSD
-- DesKilo hardening (issue #31, driven by Supabase security advisors).
-- Applied to the hosted reference project on 2026-07-07.
--
-- Principle: trigger functions are not callable at all; helper predicates and
-- RPCs are callable by authenticated only (they are the intended API surface);
-- nothing SECURITY DEFINER is callable by anon.

alter extension btree_gist set schema extensions;

-- trigger-only functions: no direct execution by any API role
revoke execute on function public.handle_new_user() from public, anon, authenticated;
revoke execute on function public.protect_last_owner() from public, anon, authenticated;
-- server-side default helper: not an API
revoke execute on function public.gen_invite_code() from public, anon, authenticated;

-- RLS helper predicates: authenticated only (policies evaluate as the caller)
revoke execute on function public.is_member_of(uuid) from public, anon;
revoke execute on function public.is_admin_of(uuid) from public, anon;
revoke execute on function public.is_owner_of(uuid) from public, anon;
revoke execute on function public.shares_workspace_with(uuid) from public, anon;

-- RPCs: authenticated only (they raise on missing auth.uid() anyway)
revoke execute on function public.create_workspace(text, text, text, text) from public, anon;
revoke execute on function public.join_workspace(text) from public, anon;
revoke execute on function public.leave_workspace(uuid) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- DesKilo reservations (Epic #4, issue #41). Applied to the hosted reference
-- project on 2026-07-07 as "reservations_schema_and_rpcs".
-- The exclusion constraint is the hard guarantee against double-booking
-- (spec §4.2 pitfall); RPCs are the only write path and run the softer
-- business checks.

create table public.reservations (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  -- on delete RESTRICT: the editor must resolve reservations before removing
  -- a seat/office (spec §10 guarded deletion)
  seat_id uuid references public.seats(id) on delete restrict,
  office_id uuid references public.offices(id) on delete restrict,
  member_id uuid not null references public.members(id) on delete restrict,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  status text not null default 'reserved'
    check (status in ('reserved','checked_in','completed','cancelled','released')),
  series_id uuid,
  checked_in_at timestamptz,
  checked_out_at timestamptz,
  created_at timestamptz not null default now(),
  constraint reservations_time_valid check (ends_at > starts_at),
  constraint reservations_one_target check ((seat_id is null) <> (office_id is null))
);
create index reservations_workspace_time_idx
  on public.reservations (workspace_id, starts_at);
create index reservations_member_idx on public.reservations (member_id);
create index reservations_seat_idx on public.reservations (seat_id);

-- No two active bookings may overlap on the same seat / same office.
alter table public.reservations add constraint reservations_seat_no_overlap
  exclude using gist (seat_id with =, tstzrange(starts_at, ends_at) with &&)
  where (status in ('reserved','checked_in') and seat_id is not null);
alter table public.reservations add constraint reservations_office_no_overlap
  exclude using gist (office_id with =, tstzrange(starts_at, ends_at) with &&)
  where (status in ('reserved','checked_in') and office_id is not null);

alter table public.reservations enable row level security;
create policy reservations_select on public.reservations
  for select using (public.is_member_of(workspace_id));
-- writes via SECURITY DEFINER RPCs only (default-deny)

-- Creates a reservation for the CALLER (admin-for-others goes through the
-- Epic-#6 confirmation protocol, never directly here). p_check_in makes it
-- an atomic walk-up: reservation + check-in in one transaction (spec §4.2).
create or replace function public.create_reservation(
  p_workspace_id uuid,
  p_seat_id uuid,
  p_office_id uuid,
  p_starts_at timestamptz,
  p_ends_at timestamptz,
  p_check_in boolean default false
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_seat public.seats;
  v_office_id uuid;
  v_id uuid;
begin
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if (p_seat_id is null) = (p_office_id is null) then
    raise exception 'exactly one of seat or office required';
  end if;

  if p_seat_id is not null then
    select * into v_seat from public.seats
      where id = p_seat_id and workspace_id = p_workspace_id;
    if v_seat.id is null then raise exception 'unknown seat'; end if;
    -- blocked for maintenance?
    if tstzrange(coalesce(v_seat.blocked_from, '-infinity'::timestamptz),
                 coalesce(v_seat.blocked_to, 'infinity'::timestamptz))
       && tstzrange(p_starts_at, p_ends_at)
       and (v_seat.blocked_from is not null or v_seat.blocked_to is not null) then
      raise exception 'seat is blocked in that period';
    end if;
    -- the seat's office booked as a whole?
    select d.office_id into v_office_id from public.desks d where d.id = v_seat.desk_id;
    if exists (
      select 1 from public.reservations r
      where r.office_id = v_office_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'office is reserved as a whole in that period';
    end if;
  else
    if not exists (
      select 1 from public.offices o
      where o.id = p_office_id and o.workspace_id = p_workspace_id
        and o.bookable_as_whole
    ) then
      raise exception 'office not bookable as a whole';
    end if;
    -- any seat inside already booked?
    if exists (
      select 1 from public.reservations r
      join public.seats s on s.id = r.seat_id
      join public.desks d on d.id = s.desk_id
      where d.office_id = p_office_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'a seat in this office is already reserved in that period';
    end if;
  end if;

  insert into public.reservations
    (workspace_id, seat_id, office_id, member_id, starts_at, ends_at, status, checked_in_at)
  values (
    p_workspace_id, p_seat_id, p_office_id, v_member.id, p_starts_at, p_ends_at,
    case when p_check_in then 'checked_in' else 'reserved' end,
    case when p_check_in then now() end
  )
  returning id into v_id;
  return v_id;
end;
$$;

create or replace function public.check_in_reservation(p_reservation_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare v_res public.reservations;
begin
  select r.* into v_res from public.reservations r
    join public.members m on m.id = r.member_id
    where r.id = p_reservation_id and m.user_id = auth.uid();
  if v_res.id is null then raise exception 'not your reservation'; end if;
  if v_res.status <> 'reserved' then raise exception 'not in reserved state'; end if;
  update public.reservations
    set status = 'checked_in', checked_in_at = now()
    where id = p_reservation_id;
end;
$$;

-- Check-out truncates ends_at to now so the seat frees immediately.
create or replace function public.check_out_reservation(p_reservation_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare v_res public.reservations;
begin
  select r.* into v_res from public.reservations r
    join public.members m on m.id = r.member_id
    where r.id = p_reservation_id and m.user_id = auth.uid();
  if v_res.id is null then raise exception 'not your reservation'; end if;
  if v_res.status <> 'checked_in' then raise exception 'not checked in'; end if;
  update public.reservations
    set status = 'completed',
        checked_out_at = now(),
        ends_at = least(ends_at, now())
    where id = p_reservation_id;
end;
$$;

create or replace function public.cancel_reservation(p_reservation_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare v_res public.reservations;
begin
  select r.* into v_res from public.reservations r
    join public.members m on m.id = r.member_id
    where r.id = p_reservation_id and m.user_id = auth.uid();
  if v_res.id is null then raise exception 'not your reservation'; end if;
  if v_res.status not in ('reserved','checked_in') then
    raise exception 'not cancellable';
  end if;
  update public.reservations set status = 'cancelled' where id = p_reservation_id;
end;
$$;

revoke execute on function public.create_reservation(uuid, uuid, uuid, timestamptz, timestamptz, boolean) from public, anon;
revoke execute on function public.check_in_reservation(uuid) from public, anon;
revoke execute on function public.check_out_reservation(uuid) from public, anon;
revoke execute on function public.cancel_reservation(uuid) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- DesKilo booking rules + recurring series (Epic #5, issue #50). Applied to
-- the hosted reference project on 2026-07-07 as "booking_rules_and_series".

-- Owner-editable rules with sane defaults (spec §5.3, subset delivered now).
alter table public.workspaces add column booking_rules jsonb not null default
  '{"advance_horizon_days": 90, "max_series_days": 180, "min_duration_minutes": 30, "max_duration_minutes": 1440}'::jsonb;

create or replace function public.enforce_booking_rules(
  p_workspace_id uuid, p_starts_at timestamptz, p_ends_at timestamptz
) returns void language plpgsql stable security definer set search_path = public as $$
declare rules jsonb; horizon int; min_min int; max_min int; dur int;
begin
  select booking_rules into rules from public.workspaces where id = p_workspace_id;
  horizon := coalesce((rules->>'advance_horizon_days')::int, 90);
  min_min := coalesce((rules->>'min_duration_minutes')::int, 30);
  max_min := coalesce((rules->>'max_duration_minutes')::int, 1440);
  if p_starts_at > now() + make_interval(days => horizon) then
    raise exception 'beyond the advance-booking horizon of % days', horizon;
  end if;
  dur := extract(epoch from (p_ends_at - p_starts_at))::int / 60;
  if dur < min_min then
    raise exception 'below the minimum duration of % minutes', min_min;
  end if;
  if dur > max_min then
    raise exception 'above the maximum duration of % minutes', max_min;
  end if;
end;
$$;
revoke execute on function public.enforce_booking_rules(uuid, timestamptz, timestamptz) from public, anon, authenticated;

-- Wire rules into single-reservation creation: recreate create_reservation
-- with the rules call (body otherwise identical to migration 0005).
create or replace function public.create_reservation(
  p_workspace_id uuid,
  p_seat_id uuid,
  p_office_id uuid,
  p_starts_at timestamptz,
  p_ends_at timestamptz,
  p_check_in boolean default false
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_seat public.seats;
  v_office_id uuid;
  v_id uuid;
begin
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if (p_seat_id is null) = (p_office_id is null) then
    raise exception 'exactly one of seat or office required';
  end if;
  perform public.enforce_booking_rules(p_workspace_id, p_starts_at, p_ends_at);

  if p_seat_id is not null then
    select * into v_seat from public.seats
      where id = p_seat_id and workspace_id = p_workspace_id;
    if v_seat.id is null then raise exception 'unknown seat'; end if;
    if tstzrange(coalesce(v_seat.blocked_from, '-infinity'::timestamptz),
                 coalesce(v_seat.blocked_to, 'infinity'::timestamptz))
       && tstzrange(p_starts_at, p_ends_at)
       and (v_seat.blocked_from is not null or v_seat.blocked_to is not null) then
      raise exception 'seat is blocked in that period';
    end if;
    select d.office_id into v_office_id from public.desks d where d.id = v_seat.desk_id;
    if exists (
      select 1 from public.reservations r
      where r.office_id = v_office_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'office is reserved as a whole in that period';
    end if;
  else
    if not exists (
      select 1 from public.offices o
      where o.id = p_office_id and o.workspace_id = p_workspace_id
        and o.bookable_as_whole
    ) then
      raise exception 'office not bookable as a whole';
    end if;
    if exists (
      select 1 from public.reservations r
      join public.seats s on s.id = r.seat_id
      join public.desks d on d.id = s.desk_id
      where d.office_id = p_office_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'a seat in this office is already reserved in that period';
    end if;
  end if;

  insert into public.reservations
    (workspace_id, seat_id, office_id, member_id, starts_at, ends_at, status, checked_in_at)
  values (
    p_workspace_id, p_seat_id, p_office_id, v_member.id, p_starts_at, p_ends_at,
    case when p_check_in then 'checked_in' else 'reserved' end,
    case when p_check_in then now() end
  )
  returning id into v_id;
  return v_id;
end;
$$;

-- Series creation (spec §5.2): expands the pattern server-side, books free
-- instances, returns booked and skipped starts — never silently partial.
-- p_pattern: 'daily' | 'weekdays' | 'weekly'
create or replace function public.create_series(
  p_workspace_id uuid,
  p_seat_id uuid,
  p_first_start timestamptz,
  p_first_end timestamptz,
  p_pattern text,
  p_until timestamptz
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_rules jsonb;
  v_max_days int;
  v_series_id uuid := gen_random_uuid();
  v_start timestamptz := p_first_start;
  v_end timestamptz := p_first_end;
  v_tz text;
  v_booked jsonb := '[]'::jsonb;
  v_skipped jsonb := '[]'::jsonb;
  v_step interval;
  v_dow int;
begin
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if p_pattern not in ('daily','weekdays','weekly') then
    raise exception 'unknown pattern';
  end if;
  select booking_rules, timezone into v_rules, v_tz
    from public.workspaces where id = p_workspace_id;
  v_max_days := coalesce((v_rules->>'max_series_days')::int, 180);
  if p_until > p_first_start + make_interval(days => v_max_days) then
    raise exception 'series exceeds the maximum of % days', v_max_days;
  end if;
  perform public.enforce_booking_rules(p_workspace_id, p_first_start, p_first_end);

  v_step := case when p_pattern = 'weekly' then interval '7 days' else interval '1 day' end;

  while v_start <= p_until loop
    -- weekday filter recurs in workspace-local time (spec §11 DST rule)
    v_dow := extract(isodow from v_start at time zone v_tz)::int;
    if p_pattern <> 'weekdays' or v_dow between 1 and 5 then
      begin
        insert into public.reservations
          (workspace_id, seat_id, member_id, starts_at, ends_at, status, series_id)
        values (p_workspace_id, p_seat_id, v_member.id, v_start, v_end, 'reserved', v_series_id);
        v_booked := v_booked || to_jsonb(v_start);
      exception when others then
        v_skipped := v_skipped || to_jsonb(v_start);
      end;
    end if;
    v_start := v_start + v_step;
    v_end := v_end + v_step;
  end loop;

  return jsonb_build_object(
    'series_id', v_series_id,
    'booked', v_booked,
    'skipped', v_skipped
  );
end;
$$;

-- Cancel a whole series or this-and-following from an instant.
create or replace function public.cancel_series(
  p_series_id uuid,
  p_from timestamptz default null
) returns int language plpgsql security definer set search_path = public as $$
declare v_count int;
begin
  update public.reservations r
    set status = 'cancelled'
    from public.members m
    where r.series_id = p_series_id
      and m.id = r.member_id
      and m.user_id = auth.uid()
      and r.status = 'reserved'
      and (p_from is null or r.starts_at >= p_from);
  get diagnostics v_count = row_count;
  if v_count = 0 then raise exception 'nothing to cancel'; end if;
  return v_count;
end;
$$;

revoke execute on function public.create_series(uuid, uuid, timestamptz, timestamptz, text, timestamptz) from public, anon;
revoke execute on function public.cancel_series(uuid, timestamptz) from public, anon;

