-- SPDX-License-Identifier: 0BSD
-- DesKilo billing v2 core: percentage subscriptions + fee bands
-- (epic #121 task 4, issue #128, ADR 0008). Fee bands REPLACE the plan
-- model: a member's subscription is an integer percentage 1-100; the
-- monthly fee is the band (from_pct, to_pct] the percentage falls into;
-- entitlement = ceil(open_days x 2 x pct / 100) half-days, overage at the
-- band rate. Plans stay on disk for history but are no longer seeded,
-- assigned, or billed.

-- Owner-curated subscription levels (ADR 0008): presets each individually
-- enabled, extra owner-defined values, optional negotiated free value.
alter table public.workspaces add column subscription_levels jsonb not null default
  '{"enabled_presets": [25, 50, 75, 100], "extra_levels": [], "allow_custom": false}'::jsonb;

alter table public.members add column subscription_pct int not null default 100
  check (subscription_pct between 1 and 100);

-- Migrate plan holders: unlimited plan -> 100, zero-base (Flex) -> 25,
-- quota+overage (Half) -> 50. Members without a plan keep the 100 default.
update public.members m
  set subscription_pct = case
    when p.included_half_days is null then 100
    when p.base_fee_cents = 0 then 25
    else 50
  end
  from public.plans p
  where m.plan_id = p.id;

create table public.fee_bands (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  -- band is (from_pct, to_pct]: inclusive-upper (ADR 0008)
  from_pct int not null check (from_pct between 0 and 99),
  to_pct int not null check (to_pct between 1 and 100),
  fee_cents int not null default 0 check (fee_cents >= 0),
  overage_fee_cents int not null default 0 check (overage_fee_cents >= 0),
  check (from_pct < to_pct),
  unique (workspace_id, from_pct)
);
create index fee_bands_workspace_idx on public.fee_bands (workspace_id);

alter table public.fee_bands enable row level security;
create policy fee_bands_select on public.fee_bands
  for select using (public.is_member_of(workspace_id));
create policy fee_bands_write on public.fee_bands
  for all using (public.is_owner_of(workspace_id))
  with check (public.is_owner_of(workspace_id));

-- Contiguity guard: at commit time every workspace's band set must tile
-- (0, 100] with no gaps or overlaps. Deferred so replace_fee_bands (and any
-- multi-statement owner edit in one transaction) can rebuild freely.
create or replace function public.assert_fee_bands_contiguous()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_ws uuid;
  v_expected int;
  r record;
begin
  v_ws := coalesce(new.workspace_id, old.workspace_id);
  -- a workspace may have zero bands only while it also has no members
  -- (freshly deleted); billing requires full coverage otherwise
  if not exists (select 1 from public.fee_bands where workspace_id = v_ws) then
    return null;
  end if;
  v_expected := 0;
  for r in select from_pct, to_pct from public.fee_bands
             where workspace_id = v_ws order by from_pct loop
    if r.from_pct <> v_expected then
      raise exception 'fee bands must be contiguous: expected a band starting at %, found %', v_expected, r.from_pct;
    end if;
    v_expected := r.to_pct;
  end loop;
  if v_expected <> 100 then
    raise exception 'fee bands must cover up to 100, last band ends at %', v_expected;
  end if;
  return null;
end;
$$;
revoke execute on function public.assert_fee_bands_contiguous() from public, anon, authenticated;

create constraint trigger fee_bands_contiguous
after insert or update or delete on public.fee_bands
deferrable initially deferred
for each row execute function public.assert_fee_bands_contiguous();

-- Atomic full replace with friendly validation (the owner band editor's
-- write path). p_bands: [{"from_pct":0,"to_pct":50,"fee_cents":12000,
-- "overage_fee_cents":500}, ...]
create or replace function public.replace_fee_bands(
  p_workspace_id uuid,
  p_bands jsonb
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_expected int := 0;
  b record;
begin
  if not public.is_owner_of(p_workspace_id) then
    raise exception 'only the owner may edit fee bands';
  end if;
  if p_bands is null or jsonb_typeof(p_bands) <> 'array' or jsonb_array_length(p_bands) = 0 then
    raise exception 'at least one band is required';
  end if;
  for b in
    select (x->>'from_pct')::int as from_pct, (x->>'to_pct')::int as to_pct,
           (x->>'fee_cents')::int as fee_cents,
           (x->>'overage_fee_cents')::int as overage_fee_cents
    from jsonb_array_elements(p_bands) x
    order by (x->>'from_pct')::int
  loop
    if b.from_pct <> v_expected then
      raise exception 'bands must be contiguous from 0 to 100 (gap or overlap at %)', b.from_pct;
    end if;
    if b.fee_cents < 0 or b.overage_fee_cents < 0 then
      raise exception 'fees must be >= 0';
    end if;
    v_expected := b.to_pct;
  end loop;
  if v_expected <> 100 then
    raise exception 'bands must cover up to 100 (last band ends at %)', v_expected;
  end if;

  delete from public.fee_bands where workspace_id = p_workspace_id;
  insert into public.fee_bands (workspace_id, from_pct, to_pct, fee_cents, overage_fee_cents)
  select p_workspace_id, (x->>'from_pct')::int, (x->>'to_pct')::int,
         coalesce((x->>'fee_cents')::int, 0), coalesce((x->>'overage_fee_cents')::int, 0)
  from jsonb_array_elements(p_bands) x;
end;
$$;
revoke execute on function public.replace_fee_bands(uuid, jsonb) from public, anon;

-- Seed bands mapping the old default plans' pricing intent:
-- (0,25] Flex-like, (25,50] Half-like, (50,100] Full-like.
insert into public.fee_bands (workspace_id, from_pct, to_pct, fee_cents, overage_fee_cents)
select w.id, b.from_pct, b.to_pct, b.fee_cents, b.overage_fee_cents
from public.workspaces w
cross join (values (0, 25, 0, 1500), (25, 50, 15000, 800), (50, 100, 25000, 0))
  as b(from_pct, to_pct, fee_cents, overage_fee_cents)
where not exists (select 1 from public.fee_bands f where f.workspace_id = w.id);

-- New workspaces get default bands instead of plans (trigger name and
-- wiring from 0008 kept; plans are legacy from here on).
create or replace function public.seed_default_plans()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.fee_bands (workspace_id, from_pct, to_pct, fee_cents, overage_fee_cents) values
    (new.id, 0, 25, 0, 1500),
    (new.id, 25, 50, 15000, 800),
    (new.id, 50, 100, 25000, 0);
  return new;
end;
$$;

-- Statement v2: band fee + availability-scaled entitlement (ADR 0008).
-- Same auth rules and half-day usage counting as 0008.
create or replace function public.member_statement(
  p_member_id uuid,
  p_period text
) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_member public.members;
  v_caller_is_admin boolean;
  v_band public.fee_bands;
  v_tz text;
  v_open int[];
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_month_first date;
  v_open_days int;
  v_pct int;
  v_included int;
  v_used int;
  v_base int := 0;
  v_overage int := 0;
  v_overage_rate int := 0;
  v_credits int;
  v_extra_half_days int := 0;
begin
  select * into v_member from public.members where id = p_member_id;
  if v_member.id is null then raise exception 'unknown member'; end if;
  v_caller_is_admin := public.is_admin_of(v_member.workspace_id);
  if not v_caller_is_admin and not exists (
    select 1 from public.members m
    where m.id = p_member_id and m.user_id = auth.uid()
  ) then
    raise exception 'not your statement';
  end if;

  select timezone,
         coalesce((select array_agg(x::int)
                     from jsonb_array_elements_text(booking_rules->'open_weekdays') x),
                  array[1,2,3,4,5])
    into v_tz, v_open
    from public.workspaces where id = v_member.workspace_id;
  v_period_start := to_timestamp(p_period || '-01', 'YYYY-MM-DD') at time zone v_tz;
  v_period_end := (to_timestamp(p_period || '-01', 'YYYY-MM-DD') + interval '1 month') at time zone v_tz;
  v_month_first := to_date(p_period || '-01', 'YYYY-MM-DD');

  v_pct := coalesce(v_member.subscription_pct, 100);
  select * into v_band from public.fee_bands
    where workspace_id = v_member.workspace_id
      and from_pct < v_pct and v_pct <= to_pct;
  if v_band.id is not null then
    v_base := v_band.fee_cents;
    v_overage_rate := v_band.overage_fee_cents;
  end if;

  -- entitlement basis: open weekdays minus closure days, x2 half-day slots
  select count(*) into v_open_days
  from generate_series(v_month_first,
                       (v_month_first + interval '1 month' - interval '1 day')::date,
                       interval '1 day') d
  where extract(isodow from d)::int = any(v_open)
    and not exists (select 1 from public.closure_days c
                     where c.workspace_id = v_member.workspace_id and c.day = d::date);
  v_included := ceil(v_open_days * 2 * v_pct / 100.0)::int;

  select count(distinct (date_trunc('day', r.starts_at at time zone v_tz)::date, s.slot))
  into v_used
  from public.reservations r
  cross join lateral (
    select case when extract(hour from r.starts_at at time zone v_tz) < 13 then 0 else 1 end as slot
  ) s
  where r.member_id = p_member_id
    and r.status in ('reserved','checked_in','completed')
    and r.starts_at >= v_period_start and r.starts_at < v_period_end;

  v_extra_half_days := greatest(0, v_used - v_included);
  v_overage := v_extra_half_days * v_overage_rate;

  select coalesce(sum(case when kind = 'credit' then amount_cents else -amount_cents end), 0)
  into v_credits
  from public.ledger_entries
  where member_id = p_member_id and period = p_period;

  return jsonb_build_object(
    'period', p_period,
    'subscription_pct', v_pct,
    'fee_cents', v_base,
    'included_half_days', v_included,
    'open_days', v_open_days,
    'used_half_days', v_used,
    'extra_half_days', v_extra_half_days,
    'overage_cents', v_overage,
    'credits_cents', v_credits,
    'balance_cents', v_credits - v_base - v_overage
  );
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- DesKilo service consumption on the monthly bill (epic #121 task 5,
-- issue #129, ADR 0008). Members self-report consumed services; admins/
-- owner add for any member. A pending 'service_charge' event carries a
-- name+price snapshot; the ledger charge posts only on confirmation.
-- Decider (single-confirmer protocol, quorum arrives in 0017):
--   member self-reports  -> an admin decides (no self-approval, #107
--                           solo-admin escape hatch applies)
--   admin adds for member -> the member (subject) decides

alter table public.events drop constraint events_type_check;
alter table public.events add constraint events_type_check
  check (type in ('reservation','payment','expense','adjustment','service_charge'));

alter table public.ledger_entries drop constraint ledger_entries_category_check;
alter table public.ledger_entries add constraint ledger_entries_category_check
  check (category in ('subscription','overage','expense','payment','adjustment','service'));

create or replace function public.record_service_charge(
  p_workspace_id uuid,
  p_subject_member_id uuid,
  p_service_id uuid,
  p_quantity int,
  p_period text default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_service public.services;
  v_period text;
  v_event_id uuid;
begin
  select * into v_actor from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_actor.id is null then raise exception 'not an active member'; end if;
  if v_actor.id <> p_subject_member_id and not (v_actor.is_admin or v_actor.is_owner) then
    raise exception 'only admins may add services for other members';
  end if;
  if not exists (
    select 1 from public.members
    where id = p_subject_member_id and workspace_id = p_workspace_id and status = 'active'
  ) then raise exception 'unknown subject member'; end if;

  select * into v_service from public.services
    where id = p_service_id and workspace_id = p_workspace_id;
  if v_service.id is null then raise exception 'unknown service'; end if;
  if not v_service.active then raise exception 'service is inactive'; end if;
  if p_quantity is null or p_quantity < 1 or p_quantity > 999 then
    raise exception 'quantity must be between 1 and 999';
  end if;
  v_period := coalesce(p_period, to_char(now(), 'YYYY-MM'));
  if v_period !~ '^\d{4}-\d{2}$' then raise exception 'period must be YYYY-MM'; end if;

  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id, payload, status)
  values (
    p_workspace_id, 'service_charge', 'submitted', v_actor.id, p_subject_member_id,
    jsonb_build_object(
      'service_id', v_service.id,
      'name', v_service.name,
      'price_cents', v_service.price_cents,
      'quantity', p_quantity,
      'amount_cents', v_service.price_cents * p_quantity,
      'period', v_period
    ),
    'pending'
  ) returning id into v_event_id;
  return v_event_id;
end;
$$;
revoke execute on function public.record_service_charge(uuid, uuid, uuid, int, text) from public, anon;

-- respond_to_event learns 'service_charge' (0011 body otherwise kept):
-- self-reported charges need an admin, admin-added ones need the subject;
-- on accept the ledger gets a CHARGE (kind) in category 'service' for the
-- snapshot amount, booked to the payload period.
create or replace function public.respond_to_event(
  p_event_id uuid,
  p_accept boolean
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_event public.events;
  v_caller public.members;
  v_needs_admin boolean;
  v_other_admin boolean;
begin
  select e.* into v_event from public.events e where e.id = p_event_id;
  if v_event.id is null then raise exception 'unknown event'; end if;
  if v_event.status <> 'pending' then raise exception 'already decided'; end if;

  select m.* into v_caller from public.members m
    where m.workspace_id = v_event.workspace_id and m.user_id = auth.uid()
      and m.status = 'active';
  if v_caller.id is null then raise exception 'not a member'; end if;

  v_needs_admin := v_event.type = 'expense'
    or (v_event.type in ('payment','service_charge')
        and v_event.actor_member_id = v_event.subject_member_id);

  if v_needs_admin then
    if not (v_caller.is_admin or v_caller.is_owner) then
      raise exception 'an admin must decide this event';
    end if;
    if v_caller.id = v_event.actor_member_id then
      select exists (
        select 1 from public.members m
        where m.workspace_id = v_event.workspace_id
          and m.status = 'active' and (m.is_admin or m.is_owner)
          and m.id <> v_caller.id
      ) into v_other_admin;
      if v_other_admin then
        raise exception 'another admin must decide this event';
      end if;
      -- solo-admin workspace: self-decision allowed (documented, #107)
    end if;
  else
    if v_caller.id <> v_event.subject_member_id then
      raise exception 'not the subject of this event';
    end if;
  end if;

  update public.events
    set status = case when p_accept then 'confirmed' else 'rejected' end,
        decided_at = now()
    where id = p_event_id;

  if not p_accept and v_event.reservation_id is not null then
    update public.reservations set status = 'cancelled'
      where id = v_event.reservation_id and status in ('reserved','checked_in');
  end if;

  if p_accept and v_event.type in ('payment','expense') then
    insert into public.ledger_entries
      (workspace_id, member_id, kind, category, amount_cents, description, period, event_id)
    values (
      v_event.workspace_id, v_event.subject_member_id, 'credit',
      case when v_event.type = 'payment' then 'payment' else 'expense' end,
      (v_event.payload->>'amount_cents')::int,
      coalesce(v_event.payload->>'note', ''),
      to_char(now(), 'YYYY-MM'),
      v_event.id
    );
  end if;

  if p_accept and v_event.type = 'service_charge' then
    insert into public.ledger_entries
      (workspace_id, member_id, kind, category, amount_cents, description, period, event_id)
    values (
      v_event.workspace_id, v_event.subject_member_id, 'charge', 'service',
      (v_event.payload->>'amount_cents')::int,
      (v_event.payload->>'name') || ' x' || (v_event.payload->>'quantity'),
      coalesce(v_event.payload->>'period', to_char(now(), 'YYYY-MM')),
      v_event.id
    );
  end if;
end;
$$;
revoke execute on function public.respond_to_event(uuid, boolean) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- DesKilo quorum validation with per-validator audit trail (epic #121
-- task 6, issue #130, ADR 0008). The single-confirmer protocol of
-- 0007/0011/0016 generalizes to an owner-configurable quorum:
--   validation_policies — per event type (fallback row event_type null;
--     absent rows behave like today: 1 decision, all admins, owner not
--     required)
--   event_decisions — WHO decided WHAT and WHEN; sweeps write system rows
--     so the audit trail never has gaps.
-- Semantics preserved from before: no self-approval (with the #107
-- solo-admin escape hatch), subject-must-accept for admin-initiated
-- events (their accept counts toward the quorum), rejects close
-- immediately, ledger side effects post once on confirmation.

create table public.validation_policies (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  -- null = workspace default for types without their own row
  event_type text check (event_type in
    ('reservation','payment','expense','adjustment','service_charge')),
  required_count int not null default 1 check (required_count between 1 and 10),
  admins_may_validate boolean not null default true,
  -- empty = every admin; otherwise only these member ids (owners always may)
  eligible_admin_ids uuid[] not null default '{}',
  owner_required boolean not null default false,
  unique nulls not distinct (workspace_id, event_type)
);
create index validation_policies_workspace_idx on public.validation_policies (workspace_id);

alter table public.validation_policies enable row level security;
create policy validation_policies_select on public.validation_policies
  for select using (public.is_member_of(workspace_id));
create policy validation_policies_write on public.validation_policies
  for all using (public.is_owner_of(workspace_id))
  with check (public.is_owner_of(workspace_id));

create table public.event_decisions (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references public.events(id) on delete cascade,
  -- null = system (sweep timeout) decision
  member_id uuid references public.members(id) on delete restrict,
  decision text not null check (decision in ('accept','reject')),
  decided_by_system boolean not null default false,
  decided_at timestamptz not null default now()
);
create unique index event_decisions_one_per_member
  on public.event_decisions (event_id, member_id) where member_id is not null;
create index event_decisions_event_idx on public.event_decisions (event_id);

alter table public.event_decisions enable row level security;
create policy event_decisions_select on public.event_decisions
  for select using (exists (
    select 1 from public.events e
    where e.id = event_decisions.event_id and public.is_member_of(e.workspace_id)
  ));
-- writes via RPCs only

-- Quorum-aware decision RPC (replaces the 0016 body).
create or replace function public.respond_to_event(
  p_event_id uuid,
  p_accept boolean
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_event public.events;
  v_caller public.members;
  v_policy record;
  v_subject_decides boolean;
  v_in_pool boolean;
  v_pool_size int;
  v_required int;
  v_accepts int;
  v_subject_ok boolean;
  v_owner_ok boolean;
begin
  select e.* into v_event from public.events e where e.id = p_event_id;
  if v_event.id is null then raise exception 'unknown event'; end if;
  if v_event.status <> 'pending' then raise exception 'already decided'; end if;

  select m.* into v_caller from public.members m
    where m.workspace_id = v_event.workspace_id and m.user_id = auth.uid()
      and m.status = 'active';
  if v_caller.id is null then raise exception 'not a member'; end if;
  if exists (select 1 from public.event_decisions d
              where d.event_id = p_event_id and d.member_id = v_caller.id) then
    raise exception 'you already decided this event';
  end if;

  select * into v_policy from public.validation_policies
    where workspace_id = v_event.workspace_id and event_type = v_event.type;
  if v_policy is null then
    select * into v_policy from public.validation_policies
      where workspace_id = v_event.workspace_id and event_type is null;
  end if;
  if v_policy is null then
    -- pre-0017 behavior
    select null::uuid as id, v_event.workspace_id as workspace_id,
           null::text as event_type, 1 as required_count,
           true as admins_may_validate, '{}'::uuid[] as eligible_admin_ids,
           false as owner_required
      into v_policy;
  end if;

  -- admin-initiated events are accepted by their subject; self-initiated
  -- money events need validators
  v_subject_decides := v_event.type = 'reservation'
    or (v_event.type in ('payment','service_charge')
        and v_event.actor_member_id <> v_event.subject_member_id);

  -- validator pool: owners always; admins per policy; never the actor or
  -- subject. #107 escape hatch: an actor-admin alone in the pool may
  -- self-decide.
  select count(*) into v_pool_size from public.members m
    where m.workspace_id = v_event.workspace_id and m.status = 'active'
      and m.id not in (v_event.actor_member_id, v_event.subject_member_id)
      and (m.is_owner or (m.is_admin and v_policy.admins_may_validate
           and (cardinality(v_policy.eligible_admin_ids) = 0
                or m.id = any(v_policy.eligible_admin_ids))));

  -- the #107 escape hatch lifts BOTH exclusions on admin-decided events
  -- (a solo admin's own expense makes them actor AND subject); on
  -- subject-decides events the subject stays out of the pool — their
  -- mandatory accept is counted separately below
  v_in_pool := (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate
                and (cardinality(v_policy.eligible_admin_ids) = 0
                     or v_caller.id = any(v_policy.eligible_admin_ids))))
    and (v_caller.id <> v_event.subject_member_id
         or (not v_subject_decides and v_pool_size = 0))
    and (v_caller.id <> v_event.actor_member_id or v_pool_size = 0);
  if v_pool_size = 0 and (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate)) then
    -- solo-admin workspaces: the pool collapses to the actor (#107)
    v_pool_size := 1;
  end if;

  if v_subject_decides and v_caller.id = v_event.subject_member_id then
    null; -- the subject's decision is always admissible (and mandatory)
  elsif v_in_pool then
    null;
  else
    raise exception 'you are not an eligible validator for this event';
  end if;

  insert into public.event_decisions (event_id, member_id, decision)
  values (p_event_id, v_caller.id, case when p_accept then 'accept' else 'reject' end);

  if not p_accept then
    update public.events set status = 'rejected', decided_at = now()
      where id = p_event_id;
    if v_event.reservation_id is not null then
      update public.reservations set status = 'cancelled'
        where id = v_event.reservation_id and status in ('reserved','checked_in');
    end if;
    return;
  end if;

  -- confirmation check: enough accepts, subject on board, owner on board
  select count(*) into v_accepts from public.event_decisions
    where event_id = p_event_id and decision = 'accept';
  v_required := greatest(1, least(v_policy.required_count,
    v_pool_size + case when v_subject_decides then 1 else 0 end));
  v_subject_ok := not v_subject_decides or exists (
    select 1 from public.event_decisions d
    where d.event_id = p_event_id and d.decision = 'accept'
      and d.member_id = v_event.subject_member_id);
  v_owner_ok := not v_policy.owner_required or exists (
    select 1 from public.event_decisions d
    join public.members m on m.id = d.member_id
    where d.event_id = p_event_id and d.decision = 'accept' and m.is_owner);

  if v_accepts >= v_required and v_subject_ok and v_owner_ok then
    update public.events set status = 'confirmed', decided_at = now()
      where id = p_event_id;

    if v_event.type in ('payment','expense') then
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description, period, event_id)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'credit',
        case when v_event.type = 'payment' then 'payment' else 'expense' end,
        (v_event.payload->>'amount_cents')::int,
        coalesce(v_event.payload->>'note', ''),
        to_char(now(), 'YYYY-MM'),
        v_event.id
      );
    elsif v_event.type = 'service_charge' then
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description, period, event_id)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'charge', 'service',
        (v_event.payload->>'amount_cents')::int,
        (v_event.payload->>'name') || ' x' || (v_event.payload->>'quantity'),
        coalesce(v_event.payload->>'period', to_char(now(), 'YYYY-MM')),
        v_event.id
      );
    end if;
  end if;
end;
$$;
revoke execute on function public.respond_to_event(uuid, boolean) from public, anon;

-- Sweep keeps its 7-day timeout but now leaves system decision rows so the
-- audit trail shows WHY an event closed.
create or replace function public.sweep_pending_events(p_workspace_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_member_of(p_workspace_id) then
    raise exception 'not a member';
  end if;
  -- non-destructive (creations/modifications): auto-confirm
  insert into public.event_decisions (event_id, member_id, decision, decided_by_system)
  select e.id, null, 'accept', true from public.events e
    where e.workspace_id = p_workspace_id and e.status = 'pending'
      and e.action in ('created','modified')
      and e.created_at < now() - interval '7 days';
  update public.events
    set status = 'confirmed', decided_at = now()
    where workspace_id = p_workspace_id and status = 'pending'
      and action in ('created','modified')
      and created_at < now() - interval '7 days';
  -- destructive (cancellations) or debits: auto-expire and undo tentative
  update public.reservations r set status = 'cancelled'
    from public.events e
    where e.workspace_id = p_workspace_id and e.status = 'pending'
      and e.action not in ('created','modified')
      and e.created_at < now() - interval '7 days'
      and r.id = e.reservation_id and r.status in ('reserved','checked_in');
  insert into public.event_decisions (event_id, member_id, decision, decided_by_system)
  select e.id, null, 'reject', true from public.events e
    where e.workspace_id = p_workspace_id and e.status = 'pending'
      and e.action not in ('created','modified')
      and e.created_at < now() - interval '7 days';
  update public.events
    set status = 'expired', decided_at = now()
    where workspace_id = p_workspace_id and status = 'pending'
      and action not in ('created','modified')
      and created_at < now() - interval '7 days';
end;
$$;
revoke execute on function public.sweep_pending_events(uuid) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- DesKilo #154 — payment method on recorded payments (spec §7: a payment
-- event = amount + date + METHOD + note; the method was missing from the
-- 0008 RPC). A defaulted extra parameter would CREATE AN OVERLOAD next to
-- the 4-arg function, so the old signature is dropped first; old clients
-- that still call with 4 args keep working through the new default.

drop function if exists public.record_payment(uuid, uuid, int, text);

create or replace function public.record_payment(
  p_workspace_id uuid,
  p_member_id uuid,
  p_amount_cents int,
  p_note text default '',
  p_method text default ''
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_event_id uuid;
begin
  select * into v_actor from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_actor.id is null then raise exception 'not an active member'; end if;
  if p_amount_cents <= 0 then raise exception 'amount must be positive'; end if;
  if v_actor.id <> p_member_id and not (v_actor.is_admin or v_actor.is_owner) then
    raise exception 'only admins record payments for others';
  end if;
  -- Free-form-but-bounded method tag; the app sends one of the
  -- PaymentMethod enum wire names ('' = not specified, old clients).
  if length(p_method) > 32 then raise exception 'method too long'; end if;
  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id, payload, status)
  values (
    p_workspace_id, 'payment', 'submitted', v_actor.id, p_member_id,
    jsonb_build_object(
      'amount_cents', p_amount_cents,
      'note', p_note,
      'method', p_method
    ),
    'pending'
  ) returning id into v_event_id;
  return v_event_id;
end;
$$;

-- Same hardening as 0004/0008: only signed-in members may call it.
revoke execute on function public.record_payment(uuid, uuid, int, text, text)
  from public, anon;

-- SPDX-License-Identifier: 0BSD
-- DesKilo seat blocking from the Plan screen (issue #161). NOT YET applied
-- to the hosted reference project.
--
-- The owner (always) — or an admin, when the owner switched the
-- 'adminSeatBlocking' feature on (#146 registry; key mirrors the Dart
-- WorkspaceFeature.adminSeatBlocking.dbKey) — sets or clears a seat's
-- maintenance block (seats.blocked_from / blocked_to from migration 0003).
-- NULL/NULL clears the block; blocked_from set + blocked_to NULL blocks
-- open-endedly, matching Seat.isBlockedAt's open-ended semantics.
--
-- create_reservation has rejected blocked seats since migration 0005 (kept
-- in 0006); admin_create_reservation_for (0007) and create_series (0013)
-- did NOT — they are re-created below with only the blocked-seat guard
-- added, bodies otherwise copied verbatim from those migrations.

-- Shared blocked-seat guard (mirrors assert_workspace_open from 0013 and
-- the inline check create_reservation carries since 0005): raises when the
-- seat is blocked for ANY part of [p_starts_at, p_ends_at). blocked_from
-- NULL = since forever, blocked_to NULL = forever; both NULL = not blocked.
create or replace function public.assert_seat_not_blocked(
  p_seat_id uuid, p_starts_at timestamptz, p_ends_at timestamptz
) returns void language plpgsql stable security definer set search_path = public as $$
declare v_seat public.seats;
begin
  select * into v_seat from public.seats where id = p_seat_id;
  if v_seat.id is null then raise exception 'unknown seat'; end if;
  if tstzrange(coalesce(v_seat.blocked_from, '-infinity'::timestamptz),
               coalesce(v_seat.blocked_to, 'infinity'::timestamptz))
     && tstzrange(p_starts_at, p_ends_at)
     and (v_seat.blocked_from is not null or v_seat.blocked_to is not null) then
    raise exception 'seat is blocked in that period';
  end if;
end;
$$;
revoke execute on function public.assert_seat_not_blocked(uuid, timestamptz, timestamptz) from public, anon, authenticated;

-- Sets (or, with NULL/NULL, clears) a seat's maintenance block. Permitted
-- for the workspace owner, or for an admin when the workspace's
-- feature_flags carry 'adminSeatBlocking' = true (absent key = the
-- registry default = OFF).
create or replace function public.set_seat_block(
  p_seat_id uuid,
  p_blocked_from timestamptz,
  p_blocked_to timestamptz
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_workspace_id uuid;
begin
  select workspace_id into v_workspace_id
    from public.seats where id = p_seat_id;
  if v_workspace_id is null then raise exception 'unknown seat'; end if;
  if p_blocked_from is not null and p_blocked_to is not null
     and p_blocked_to <= p_blocked_from then
    raise exception 'blocked_to must be after blocked_from';
  end if;
  if not (
    public.is_owner_of(v_workspace_id)
    or (
      public.is_admin_of(v_workspace_id)
      -- jsonb equality: true only for a stored JSON boolean true — junk
      -- values count as OFF, like the client's resolveEnabledFeatures.
      and coalesce((
        select w.feature_flags->'adminSeatBlocking' = 'true'::jsonb
        from public.workspaces w where w.id = v_workspace_id
      ), false)
    )
  ) then
    raise exception 'only the owner, or an admin with the adminSeatBlocking feature, may block seats';
  end if;
  update public.seats
    set blocked_from = p_blocked_from,
        blocked_to = p_blocked_to
    where id = p_seat_id;
end;
$$;
grant execute on function public.set_seat_block(uuid, timestamptz, timestamptz) to authenticated;
revoke execute on function public.set_seat_block(uuid, timestamptz, timestamptz) from public, anon;

-- admin_create_reservation_for: body copied verbatim from migration 0007;
-- the only change is the assert_seat_not_blocked guard next to
-- enforce_booking_rules.
create or replace function public.admin_create_reservation_for(
  p_workspace_id uuid,
  p_subject_member_id uuid,
  p_seat_id uuid,
  p_starts_at timestamptz,
  p_ends_at timestamptz
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_res_id uuid;
  v_event_id uuid;
begin
  select * into v_actor from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if not exists (
    select 1 from public.members
    where id = p_subject_member_id and workspace_id = p_workspace_id and status = 'active'
  ) then raise exception 'unknown subject member'; end if;
  perform public.enforce_booking_rules(p_workspace_id, p_starts_at, p_ends_at);
  perform public.assert_seat_not_blocked(p_seat_id, p_starts_at, p_ends_at);

  -- tentative reservation: blocks the slot (exclusion constraint applies)
  insert into public.reservations
    (workspace_id, seat_id, member_id, starts_at, ends_at, status)
  values (p_workspace_id, p_seat_id, p_subject_member_id, p_starts_at, p_ends_at, 'reserved')
  returning id into v_res_id;

  -- the trigger just logged an 'applied' created event attributed to the
  -- subject; repoint that audit line to the actor and park the decision
  update public.events set actor_member_id = v_actor.id, status = 'pending'
    where reservation_id = v_res_id and action = 'created';

  select id into v_event_id from public.events
    where reservation_id = v_res_id and action = 'created';
  return v_event_id;
end;
$$;

-- create_series: body copied verbatim from migration 0013; the only change
-- is the assert_seat_not_blocked guard next to assert_workspace_open, so
-- instances on a blocked seat land in the skipped report exactly like
-- closed days and seat conflicts.
create or replace function public.create_series(
  p_workspace_id uuid,
  p_seat_id uuid,
  p_first_start timestamptz,
  p_first_end timestamptz,
  p_pattern text,
  p_until timestamptz
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_rules jsonb;
  v_max_days int;
  v_series_id uuid := gen_random_uuid();
  v_start timestamptz := p_first_start;
  v_end timestamptz := p_first_end;
  v_tz text;
  v_booked jsonb := '[]'::jsonb;
  v_skipped jsonb := '[]'::jsonb;
  v_step interval;
  v_dow int;
begin
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if p_pattern not in ('daily','weekdays','weekly') then
    raise exception 'unknown pattern';
  end if;
  select booking_rules, timezone into v_rules, v_tz
    from public.workspaces where id = p_workspace_id;
  v_max_days := coalesce((v_rules->>'max_series_days')::int, 180);
  if p_until > p_first_start + make_interval(days => v_max_days) then
    raise exception 'series exceeds the maximum of % days', v_max_days;
  end if;
  perform public.enforce_booking_rules(p_workspace_id, p_first_start, p_first_end);

  v_step := case when p_pattern = 'weekly' then interval '7 days' else interval '1 day' end;

  while v_start <= p_until loop
    -- weekday filter recurs in workspace-local time (spec §11 DST rule)
    v_dow := extract(isodow from v_start at time zone v_tz)::int;
    if p_pattern <> 'weekdays' or v_dow between 1 and 5 then
      begin
        -- closed days raise here and land in the skipped report, exactly
        -- like seat conflicts
        perform public.assert_workspace_open(p_workspace_id, v_start, v_end);
        -- blocked seats too (#161)
        perform public.assert_seat_not_blocked(p_seat_id, v_start, v_end);
        insert into public.reservations
          (workspace_id, seat_id, member_id, starts_at, ends_at, status, series_id)
        values (p_workspace_id, p_seat_id, v_member.id, v_start, v_end, 'reserved', v_series_id);
        v_booked := v_booked || to_jsonb(v_start);
      exception when others then
        v_skipped := v_skipped || to_jsonb(v_start);
      end;
    end if;
    v_start := v_start + v_step;
    v_end := v_end + v_step;
  end loop;

  return jsonb_build_object(
    'series_id', v_series_id,
    'booked', v_booked,
    'skipped', v_skipped
  );
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- DesKilo accessory supplements on monthly statements (epic #163,
-- issue #170). NOT YET applied to the hosted reference project — the
-- orchestrator applies it after review.
--
-- The owner activates the `accessorySupplements` feature toggle (default
-- OFF, Dart registry) and from that moment on every reserved half-day on
-- a seat whose ACTIVE accessories carry a supplement adds the sum of
-- those supplement_cents to the member's statement. NO retroactive
-- charging (maintainer decision): only reservations STARTING at or after
-- the activation timestamp are billed, so flipping the toggle never
-- reprices half-days that were booked while it was off.

-- ---------------------------------------------------------------------
-- Activation timestamp. feature_flags stays a pure {feature: bool} map
-- (resolveEnabledFeatures ignores non-bools, and the client always
-- writes the full boolean map), so the timestamp lives in a dedicated
-- column maintained by a BEFORE UPDATE trigger: stamped when the flag
-- flips false→true, cleared when it flips true→false, untouched
-- otherwise (the features screen rewrites the whole map on every
-- toggle, so an unchanged true must NOT re-stamp — that would silently
-- un-bill half-days booked since the first activation). The client
-- write path (plain UPDATE of workspaces.feature_flags under owner RLS)
-- stays unchanged.
-- ---------------------------------------------------------------------

alter table public.workspaces
  add column accessory_supplements_since timestamptz;

create or replace function public.stamp_accessory_supplements_since()
returns trigger language plpgsql as $$
declare
  v_old boolean := coalesce(
    old.feature_flags -> 'accessorySupplements' = to_jsonb(true), false);
  v_new boolean := coalesce(
    new.feature_flags -> 'accessorySupplements' = to_jsonb(true), false);
begin
  if v_new and not v_old then
    new.accessory_supplements_since := now();
  elsif v_old and not v_new then
    new.accessory_supplements_since := null;
  end if;
  return new;
end;
$$;
revoke execute on function public.stamp_accessory_supplements_since() from public, anon, authenticated;

create trigger stamp_accessory_supplements_since
before update of feature_flags on public.workspaces
for each row execute function public.stamp_accessory_supplements_since();

-- ---------------------------------------------------------------------
-- Statement v3: v2 (0015) + the accessory-supplement term. Body copied
-- verbatim from 0015; additions are marked with "#170". Auth rules,
-- band fee, entitlement and half-day usage counting are unchanged; the
-- supplement mirrors the usage query's half-day slot definition
-- (workspace-local day, slot 0 before 13:00, slot 1 from 13:00) and its
-- status filter, so cancelled/released reservations never bill.
-- Existing execute grants survive create-or-replace (0008 revoked
-- public/anon).
-- ---------------------------------------------------------------------

create or replace function public.member_statement(
  p_member_id uuid,
  p_period text
) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_member public.members;
  v_caller_is_admin boolean;
  v_band public.fee_bands;
  v_tz text;
  v_open int[];
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_month_first date;
  v_open_days int;
  v_pct int;
  v_included int;
  v_used int;
  v_base int := 0;
  v_overage int := 0;
  v_overage_rate int := 0;
  v_credits int;
  v_extra_half_days int := 0;
  -- #170: accessory supplements
  v_supp_on boolean := false;
  v_supp_since timestamptz;
  v_supplement int := 0;
begin
  select * into v_member from public.members where id = p_member_id;
  if v_member.id is null then raise exception 'unknown member'; end if;
  v_caller_is_admin := public.is_admin_of(v_member.workspace_id);
  if not v_caller_is_admin and not exists (
    select 1 from public.members m
    where m.id = p_member_id and m.user_id = auth.uid()
  ) then
    raise exception 'not your statement';
  end if;

  select timezone,
         coalesce((select array_agg(x::int)
                     from jsonb_array_elements_text(booking_rules->'open_weekdays') x),
                  array[1,2,3,4,5]),
         -- #170: feature flag + no-retroactivity activation timestamp
         coalesce(feature_flags -> 'accessorySupplements' = to_jsonb(true), false),
         accessory_supplements_since
    into v_tz, v_open, v_supp_on, v_supp_since
    from public.workspaces where id = v_member.workspace_id;
  v_period_start := to_timestamp(p_period || '-01', 'YYYY-MM-DD') at time zone v_tz;
  v_period_end := (to_timestamp(p_period || '-01', 'YYYY-MM-DD') + interval '1 month') at time zone v_tz;
  v_month_first := to_date(p_period || '-01', 'YYYY-MM-DD');

  v_pct := coalesce(v_member.subscription_pct, 100);
  select * into v_band from public.fee_bands
    where workspace_id = v_member.workspace_id
      and from_pct < v_pct and v_pct <= to_pct;
  if v_band.id is not null then
    v_base := v_band.fee_cents;
    v_overage_rate := v_band.overage_fee_cents;
  end if;

  -- entitlement basis: open weekdays minus closure days, x2 half-day slots
  select count(*) into v_open_days
  from generate_series(v_month_first,
                       (v_month_first + interval '1 month' - interval '1 day')::date,
                       interval '1 day') d
  where extract(isodow from d)::int = any(v_open)
    and not exists (select 1 from public.closure_days c
                     where c.workspace_id = v_member.workspace_id and c.day = d::date);
  v_included := ceil(v_open_days * 2 * v_pct / 100.0)::int;

  select count(distinct (date_trunc('day', r.starts_at at time zone v_tz)::date, s.slot))
  into v_used
  from public.reservations r
  cross join lateral (
    select case when extract(hour from r.starts_at at time zone v_tz) < 13 then 0 else 1 end as slot
  ) s
  where r.member_id = p_member_id
    and r.status in ('reserved','checked_in','completed')
    and r.starts_at >= v_period_start and r.starts_at < v_period_end;

  v_extra_half_days := greatest(0, v_used - v_included);
  v_overage := v_extra_half_days * v_overage_rate;

  -- #170: accessory supplements — for each distinct reserved half-day
  -- slot on a seat (same slot definition and status filter as v_used;
  -- office reservations carry no seat, hence no supplement), add the sum
  -- of the seat's ACTIVE priced accessories. Only reservations starting
  -- at/after the activation timestamp bill (no retroactive charging).
  if v_supp_on and v_supp_since is not null then
    select coalesce(sum(seat_supp.total_cents), 0) into v_supplement
    from (
      select distinct
        r.seat_id,
        date_trunc('day', r.starts_at at time zone v_tz)::date as day,
        case when extract(hour from r.starts_at at time zone v_tz) < 13 then 0 else 1 end as slot
      from public.reservations r
      where r.member_id = p_member_id
        and r.seat_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= greatest(v_period_start, v_supp_since)
        and r.starts_at < v_period_end
    ) hd
    join (
      select sa.seat_id, sum(a.supplement_cents)::int as total_cents
      from public.seat_accessories sa
      join public.accessories a on a.id = sa.accessory_id
      where a.active and a.supplement_cents > 0
      group by sa.seat_id
    ) seat_supp on seat_supp.seat_id = hd.seat_id;
  end if;

  select coalesce(sum(case when kind = 'credit' then amount_cents else -amount_cents end), 0)
  into v_credits
  from public.ledger_entries
  where member_id = p_member_id and period = p_period;

  return jsonb_build_object(
    'period', p_period,
    'subscription_pct', v_pct,
    'fee_cents', v_base,
    'included_half_days', v_included,
    'open_days', v_open_days,
    'used_half_days', v_used,
    'extra_half_days', v_extra_half_days,
    'overage_cents', v_overage,
    'accessory_supplement_cents', v_supplement,
    'credits_cents', v_credits,
    'balance_cents', v_credits - v_base - v_overage - v_supplement
  );
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- DesKilo booking granularity (epic #199, issue #200). NOT YET applied
-- to the hosted reference project — the orchestrator applies it after
-- review.
--
-- The owner can restrict bookings to half days: booking_rules gains an
-- optional 'granularity' key ('flexible' | 'half_day'; absent or unknown
-- means flexible, no backfill needed). Under 'half_day' every booking
-- must cover exactly one canonical workspace-local window — 00:00–13:00
-- (morning), 13:00–24:00 (afternoon) or 00:00–24:00 (full day) — the
-- billing halves (13:00 pivot, spec §7). "24:00" is next-day 00:00; the
-- end instant stays exclusive, matching assert_workspace_open.
--
-- enforce_booking_rules is the shared chokepoint of create_reservation
-- (0006), admin_create_reservation_for (0021) and the first instance of
-- create_series (0021), so every booking path gets the check. Body
-- copied verbatim from migration 0013; the only changes are the timezone
-- in the select (needed for the local-time conversion) and the added
-- granularity block.
create or replace function public.enforce_booking_rules(
  p_workspace_id uuid, p_starts_at timestamptz, p_ends_at timestamptz
) returns void language plpgsql stable security definer set search_path = public as $$
declare rules jsonb; horizon int; min_min int; max_min int; dur int;
        tz text; local_start timestamp; local_end timestamp;
begin
  select booking_rules, timezone into rules, tz
    from public.workspaces where id = p_workspace_id;
  horizon := coalesce((rules->>'advance_horizon_days')::int, 90);
  min_min := coalesce((rules->>'min_duration_minutes')::int, 30);
  max_min := coalesce((rules->>'max_duration_minutes')::int, 1440);
  if p_starts_at > now() + make_interval(days => horizon) then
    raise exception 'beyond the advance-booking horizon of % days', horizon;
  end if;
  dur := extract(epoch from (p_ends_at - p_starts_at))::int / 60;
  if dur < min_min then
    raise exception 'below the minimum duration of % minutes', min_min;
  end if;
  if dur > max_min then
    raise exception 'above the maximum duration of % minutes', max_min;
  end if;
  -- Half-day granularity (#200): only the three canonical workspace-local
  -- windows pass — morning (00:00–13:00), afternoon (13:00–24:00 = next
  -- day 00:00) and full day (00:00–24:00). The client pins the substring
  -- 'half-day' of this message (BookingGranularityError.serverSubstring).
  if rules->>'granularity' = 'half_day' then
    local_start := p_starts_at at time zone tz;
    local_end := p_ends_at at time zone tz;
    if not (
      (local_start::time = time '00:00'
        and local_end::time = time '13:00'
        and local_end::date = local_start::date)
      or (local_start::time = time '13:00'
        and local_end::time = time '00:00'
        and local_end::date = local_start::date + 1)
      or (local_start::time = time '00:00'
        and local_end::time = time '00:00'
        and local_end::date = local_start::date + 1)
    ) then
      raise exception 'bookings must cover a half-day (00:00-13:00, 13:00-24:00) or the full day';
    end if;
  end if;
  perform public.assert_workspace_open(p_workspace_id, p_starts_at, p_ends_at);
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- DesKilo half-day walk-up exemption (epic #199, issue #201). NOT YET
-- applied to the hosted reference project — the orchestrator applies it
-- after review.
--
-- Issue #201 (validated): under half-day granularity a walk-up check-in
-- starts NOW and ends at the current half-day boundary (13:00, or next
-- day 00:00) — a window 0025's canonical check would reject. The rule
-- gains a p_walk_up flag: walk-ups must END exactly at the boundary of
-- the half containing their start; everything else keeps the three
-- canonical windows. Only create_reservation forwards its p_check_in;
-- admin_create_reservation_for and create_series call with three args
-- and bind to the default (strict).
--
-- The 3-arg function must be DROPPED first: keeping it alongside a
-- 4-arg-with-default overload would make every existing 3-arg call
-- ambiguous. Body below = 0025 verbatim + the p_walk_up branch.

drop function public.enforce_booking_rules(uuid, timestamptz, timestamptz);

create or replace function public.enforce_booking_rules(
  p_workspace_id uuid, p_starts_at timestamptz, p_ends_at timestamptz,
  p_walk_up boolean default false
) returns void language plpgsql stable security definer set search_path = public as $$
declare rules jsonb; horizon int; min_min int; max_min int; dur int;
        tz text; local_start timestamp; local_end timestamp;
begin
  select booking_rules, timezone into rules, tz
    from public.workspaces where id = p_workspace_id;
  horizon := coalesce((rules->>'advance_horizon_days')::int, 90);
  min_min := coalesce((rules->>'min_duration_minutes')::int, 30);
  max_min := coalesce((rules->>'max_duration_minutes')::int, 1440);
  if p_starts_at > now() + make_interval(days => horizon) then
    raise exception 'beyond the advance-booking horizon of % days', horizon;
  end if;
  dur := extract(epoch from (p_ends_at - p_starts_at))::int / 60;
  if dur < min_min then
    raise exception 'below the minimum duration of % minutes', min_min;
  end if;
  if dur > max_min then
    raise exception 'above the maximum duration of % minutes', max_min;
  end if;
  -- Half-day granularity (#200/#201): reservations must cover one of the
  -- three canonical workspace-local windows — morning (00:00–13:00),
  -- afternoon (13:00–24:00 = next day 00:00) or full day — while a
  -- walk-up (#201) starts now and must END at the boundary of the half
  -- containing its start. The client pins the substring 'half-day' of
  -- this message (BookingGranularityError.serverSubstring).
  if rules->>'granularity' = 'half_day' then
    local_start := p_starts_at at time zone tz;
    local_end := p_ends_at at time zone tz;
    if p_walk_up then
      if not (
        (local_start::time < time '13:00'
          and local_end::time = time '13:00'
          and local_end::date = local_start::date)
        or (local_start::time >= time '13:00'
          and local_end::time = time '00:00'
          and local_end::date = local_start::date + 1)
      ) then
        raise exception 'walk-ups must end at the half-day boundary (13:00 or midnight)';
      end if;
    elsif not (
      (local_start::time = time '00:00'
        and local_end::time = time '13:00'
        and local_end::date = local_start::date)
      or (local_start::time = time '13:00'
        and local_end::time = time '00:00'
        and local_end::date = local_start::date + 1)
      or (local_start::time = time '00:00'
        and local_end::time = time '00:00'
        and local_end::date = local_start::date + 1)
    ) then
      raise exception 'bookings must cover a half-day (00:00-13:00, 13:00-24:00) or the full day';
    end if;
  end if;
  perform public.assert_workspace_open(p_workspace_id, p_starts_at, p_ends_at);
end;
$$;
revoke execute on function public.enforce_booking_rules(uuid, timestamptz, timestamptz, boolean) from public, anon, authenticated;

-- create_reservation: body copied verbatim from migration 0006; the only
-- change is forwarding p_check_in as the walk-up flag to the rules check.
create or replace function public.create_reservation(
  p_workspace_id uuid,
  p_seat_id uuid,
  p_office_id uuid,
  p_starts_at timestamptz,
  p_ends_at timestamptz,
  p_check_in boolean default false
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_seat public.seats;
  v_office_id uuid;
  v_id uuid;
begin
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if (p_seat_id is null) = (p_office_id is null) then
    raise exception 'exactly one of seat or office required';
  end if;
  perform public.enforce_booking_rules(p_workspace_id, p_starts_at, p_ends_at, p_check_in);

  if p_seat_id is not null then
    select * into v_seat from public.seats
      where id = p_seat_id and workspace_id = p_workspace_id;
    if v_seat.id is null then raise exception 'unknown seat'; end if;
    if tstzrange(coalesce(v_seat.blocked_from, '-infinity'::timestamptz),
                 coalesce(v_seat.blocked_to, 'infinity'::timestamptz))
       && tstzrange(p_starts_at, p_ends_at)
       and (v_seat.blocked_from is not null or v_seat.blocked_to is not null) then
      raise exception 'seat is blocked in that period';
    end if;
    select d.office_id into v_office_id from public.desks d where d.id = v_seat.desk_id;
    if exists (
      select 1 from public.reservations r
      where r.office_id = v_office_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'office is reserved as a whole in that period';
    end if;
  else
    if not exists (
      select 1 from public.offices o
      where o.id = p_office_id and o.workspace_id = p_workspace_id
        and o.bookable_as_whole
    ) then
      raise exception 'office not bookable as a whole';
    end if;
    if exists (
      select 1 from public.reservations r
      join public.seats s on s.id = r.seat_id
      join public.desks d on d.id = s.desk_id
      where d.office_id = p_office_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'a seat in this office is already reserved in that period';
    end if;
  end if;

  insert into public.reservations
    (workspace_id, seat_id, office_id, member_id, starts_at, ends_at, status, checked_in_at)
  values (
    p_workspace_id, p_seat_id, p_office_id, v_member.id, p_starts_at, p_ends_at,
    case when p_check_in then 'checked_in' else 'reserved' end,
    case when p_check_in then now() end
  )
  returning id into v_id;
  return v_id;
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- Applied to the hosted reference project on 2026-07-18.
-- Role-scoped invites: every join carries an explicit role, derived from
-- WHICH secret code was used — never from a client-supplied parameter.
--   * workspaces.invite_code stays the member (plain-user) invite and the
--     human-readable workspace ID; printed QRs keep working.
--   * workspace_admin_invites holds one admin code per workspace,
--     readable by owners only.
--   * There is deliberately NO owner invite: ownership is only granted by
--     an owner editing the member row (members_update_owner RLS, 0002),
--     and the last-owner trigger (0001) still guards the other direction.

create table public.workspace_admin_invites (
  workspace_id uuid primary key references public.workspaces(id) on delete cascade,
  code text not null unique default public.gen_invite_code(),
  created_at timestamptz not null default now()
);

alter table public.workspace_admin_invites enable row level security;

-- owners read their workspace's admin code; no write policies on purpose
-- (default-deny) — rows are created by the RPCs below.
create policy workspace_admin_invites_select on public.workspace_admin_invites
  for select using (public.is_owner_of(workspace_id));

-- every existing workspace gets its admin code
insert into public.workspace_admin_invites (workspace_id)
select id from public.workspaces;

-- create_workspace: also mint the admin invite for new workspaces
create or replace function public.create_workspace(
  p_name text, p_country_code text, p_currency_code text, p_timezone text
) returns uuid language plpgsql security definer set search_path = public as $$
declare ws_id uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  insert into public.workspaces (name, country_code, currency_code, timezone, created_by)
  values (p_name, upper(p_country_code), upper(p_currency_code), p_timezone, auth.uid())
  returning id into ws_id;
  insert into public.members (workspace_id, user_id, is_admin, is_owner)
  values (ws_id, auth.uid(), true, true);
  insert into public.workspace_admin_invites (workspace_id) values (ws_id);
  return ws_id;
end;
$$;

-- join_workspace: the matched code decides the role. A member code joins
-- (or reactivates) as-is; the admin code additionally grants is_admin —
-- possession of that secret IS the credential. is_owner is never touched.
create or replace function public.join_workspace(p_invite_code text)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  ws_id uuid;
  v_code text;
  v_admin boolean := false;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  v_code := upper(trim(p_invite_code));
  select id into ws_id from public.workspaces where invite_code = v_code;
  if ws_id is null then
    select workspace_id into ws_id
    from public.workspace_admin_invites where code = v_code;
    if ws_id is not null then v_admin := true; end if;
  end if;
  if ws_id is null then raise exception 'invalid invite code'; end if;
  insert into public.members (workspace_id, user_id, is_admin)
  values (ws_id, auth.uid(), v_admin)
  on conflict (workspace_id, user_id) do update
    set status = 'active',
        is_admin = public.members.is_admin or excluded.is_admin
    where public.members.status = 'exited' or excluded.is_admin;
  return ws_id;
end;
$$;

-- set_workspace_code: a custom workspace ID must not collide with any
-- admin code either, or that workspace's admin invite would be shadowed
-- (member codes are matched first in join_workspace).
create or replace function public.set_workspace_code(
  p_workspace_id uuid,
  p_code text
) returns text language plpgsql security definer set search_path = public as $$
declare v_code text;
begin
  if not public.is_owner_of(p_workspace_id) then
    raise exception 'only owners may change the workspace ID';
  end if;
  v_code := upper(trim(p_code));
  if v_code !~ '^[A-Z0-9]{4,20}$' then
    raise exception 'workspace ID must be 4-20 letters or digits';
  end if;
  if exists (select 1 from public.workspace_admin_invites where code = v_code) then
    raise exception 'workspace ID already taken';
  end if;
  begin
    update public.workspaces set invite_code = v_code where id = p_workspace_id;
  exception when unique_violation then
    raise exception 'workspace ID already taken';
  end;
  return v_code;
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- Quota enforcement + quota-extension requests. Applied to the hosted
-- reference project on 2026-07-18.
--
-- Reservations must correspond to the subscription: a member's half-days
-- per month are capped at the entitlement ceil(open_days x 2 x pct / 100)
-- (ADR 0008, same formula as member_statement) PLUS any confirmed
-- quota extensions. A member who needs more requests a number of extra
-- half-days; owners/admins validate through the events spine, so the
-- owner's validation_policies rules (required_count = how many admins
-- must approve, eligible admins, owner_required) apply unchanged.
-- Approved extra half-days still bill at the band's overage rate —
-- an extension is permission to consume, not free usage.
--
-- Unanswered requests auto-EXPIRE after 7 days (action 'submitted'
-- follows the sweep's destructive/costly path — extra quota is never
-- granted silently).

-- 1. confirmed extensions, one row per approved request
create table public.quota_extensions (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  member_id uuid not null references public.members(id) on delete cascade,
  period text not null check (period ~ '^\d{4}-\d{2}$'),
  half_days int not null check (half_days between 1 and 100),
  event_id uuid references public.events(id),
  created_at timestamptz not null default now()
);
create index quota_extensions_member_period_idx
  on public.quota_extensions (member_id, period);

alter table public.quota_extensions enable row level security;
-- the member sees their own extensions; admins/owners see all. No write
-- policies on purpose — rows are created by respond_to_event on confirm.
create policy quota_extensions_select on public.quota_extensions
  for select using (
    public.is_admin_of(workspace_id)
    or exists (select 1 from public.members m
                where m.id = member_id and m.user_id = auth.uid())
  );

-- 2. the request travels the events spine as its own type
alter table public.events drop constraint events_type_check;
alter table public.events add constraint events_type_check
  check (type in ('reservation','payment','expense','adjustment','service_charge','quota'));

-- 3. a member requests N extra half-days for a period
create or replace function public.request_quota_extension(
  p_workspace_id uuid, p_period text, p_half_days int
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_id uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if p_period !~ '^\d{4}-\d{2}$' then raise exception 'period must be YYYY-MM'; end if;
  if p_half_days is null or p_half_days < 1 or p_half_days > 100 then
    raise exception 'half_days must be between 1 and 100';
  end if;
  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id, payload, status)
  values (
    p_workspace_id, 'quota', 'submitted', v_member.id, v_member.id,
    jsonb_build_object('period', p_period, 'half_days', p_half_days),
    'pending'
  )
  returning id into v_id;
  return v_id;
end;
$$;
revoke execute on function public.request_quota_extension(uuid, text, int) from public, anon;

-- 4. the entitlement guard: recount the member's month AFTER an insert;
-- violation raises and rolls the booking back. Usage counting mirrors
-- member_statement v3 exactly (distinct local day + am/pm start slot,
-- statuses reserved/checked_in/completed).
create or replace function public.assert_member_quota(
  p_member_id uuid, p_at timestamptz
) returns void language plpgsql stable security definer set search_path = public as $$
declare
  v_member public.members;
  v_tz text;
  v_open int[];
  v_pct int;
  v_period text;
  v_month_first date;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_open_days int;
  v_included int;
  v_ext int;
  v_used int;
begin
  select * into v_member from public.members where id = p_member_id;
  select timezone,
         coalesce((select array_agg(x::int)
                     from jsonb_array_elements_text(booking_rules->'open_weekdays') x),
                  array[1,2,3,4,5])
    into v_tz, v_open
    from public.workspaces where id = v_member.workspace_id;

  v_period := to_char(p_at at time zone v_tz, 'YYYY-MM');
  v_month_first := to_date(v_period || '-01', 'YYYY-MM-DD');
  v_period_start := to_timestamp(v_period || '-01', 'YYYY-MM-DD') at time zone v_tz;
  v_period_end := (to_timestamp(v_period || '-01', 'YYYY-MM-DD') + interval '1 month') at time zone v_tz;

  v_pct := coalesce(v_member.subscription_pct, 100);
  select count(*) into v_open_days
  from generate_series(v_month_first,
                       (v_month_first + interval '1 month' - interval '1 day')::date,
                       interval '1 day') d
  where extract(isodow from d)::int = any(v_open)
    and not exists (select 1 from public.closure_days c
                     where c.workspace_id = v_member.workspace_id and c.day = d::date);
  v_included := ceil(v_open_days * 2 * v_pct / 100.0)::int;

  select coalesce(sum(half_days), 0) into v_ext from public.quota_extensions
    where member_id = p_member_id and period = v_period;

  select count(distinct (date_trunc('day', r.starts_at at time zone v_tz)::date, s.slot))
  into v_used
  from public.reservations r
  cross join lateral (
    select case when extract(hour from r.starts_at at time zone v_tz) < 13 then 0 else 1 end as slot
  ) s
  where r.member_id = p_member_id
    and r.status in ('reserved','checked_in','completed')
    and r.starts_at >= v_period_start and r.starts_at < v_period_end;

  if v_used > v_included + v_ext then
    -- the client pins the substring 'half-day quota' of this message
    raise exception 'half-day quota exceeded — request additional half-days';
  end if;
end;
$$;
revoke execute on function public.assert_member_quota(uuid, timestamptz) from public, anon, authenticated;

-- 5. create_reservation: body = 0026 verbatim + the quota guard after the
-- insert (walk-ups included — beyond-quota presence needs an extension
-- like any other booking).
create or replace function public.create_reservation(
  p_workspace_id uuid,
  p_seat_id uuid,
  p_office_id uuid,
  p_starts_at timestamptz,
  p_ends_at timestamptz,
  p_check_in boolean default false
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_seat public.seats;
  v_office_id uuid;
  v_id uuid;
begin
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if (p_seat_id is null) = (p_office_id is null) then
    raise exception 'exactly one of seat or office required';
  end if;
  perform public.enforce_booking_rules(p_workspace_id, p_starts_at, p_ends_at, p_check_in);

  if p_seat_id is not null then
    select * into v_seat from public.seats
      where id = p_seat_id and workspace_id = p_workspace_id;
    if v_seat.id is null then raise exception 'unknown seat'; end if;
    if tstzrange(coalesce(v_seat.blocked_from, '-infinity'::timestamptz),
                 coalesce(v_seat.blocked_to, 'infinity'::timestamptz))
       && tstzrange(p_starts_at, p_ends_at)
       and (v_seat.blocked_from is not null or v_seat.blocked_to is not null) then
      raise exception 'seat is blocked in that period';
    end if;
    select d.office_id into v_office_id from public.desks d where d.id = v_seat.desk_id;
    if exists (
      select 1 from public.reservations r
      where r.office_id = v_office_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'office is reserved as a whole in that period';
    end if;
  else
    if not exists (
      select 1 from public.offices o
      where o.id = p_office_id and o.workspace_id = p_workspace_id
        and o.bookable_as_whole
    ) then
      raise exception 'office not bookable as a whole';
    end if;
    if exists (
      select 1 from public.reservations r
      join public.seats s on s.id = r.seat_id
      join public.desks d on d.id = s.desk_id
      where d.office_id = p_office_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'a seat in this office is already reserved in that period';
    end if;
  end if;

  insert into public.reservations
    (workspace_id, seat_id, office_id, member_id, starts_at, ends_at, status, checked_in_at)
  values (
    p_workspace_id, p_seat_id, p_office_id, v_member.id, p_starts_at, p_ends_at,
    case when p_check_in then 'checked_in' else 'reserved' end,
    case when p_check_in then now() end
  )
  returning id into v_id;
  perform public.assert_member_quota(v_member.id, p_starts_at);
  return v_id;
end;
$$;

-- 6. admin_create_reservation_for: body = 0021 verbatim + the quota guard
-- for the SUBJECT after the insert.
create or replace function public.admin_create_reservation_for(
  p_workspace_id uuid,
  p_subject_member_id uuid,
  p_seat_id uuid,
  p_starts_at timestamptz,
  p_ends_at timestamptz
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_res_id uuid;
  v_event_id uuid;
begin
  select * into v_actor from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if not exists (
    select 1 from public.members
    where id = p_subject_member_id and workspace_id = p_workspace_id and status = 'active'
  ) then raise exception 'unknown subject member'; end if;
  perform public.enforce_booking_rules(p_workspace_id, p_starts_at, p_ends_at);
  perform public.assert_seat_not_blocked(p_seat_id, p_starts_at, p_ends_at);

  -- tentative reservation: blocks the slot (exclusion constraint applies)
  insert into public.reservations
    (workspace_id, seat_id, member_id, starts_at, ends_at, status)
  values (p_workspace_id, p_seat_id, p_subject_member_id, p_starts_at, p_ends_at, 'reserved')
  returning id into v_res_id;
  perform public.assert_member_quota(p_subject_member_id, p_starts_at);

  -- the trigger just logged an 'applied' created event attributed to the
  -- subject; repoint that audit line to the actor and park the decision
  update public.events set actor_member_id = v_actor.id, status = 'pending'
    where reservation_id = v_res_id and action = 'created';

  select id into v_event_id from public.events
    where reservation_id = v_res_id and action = 'created';
  return v_event_id;
end;
$$;

-- 7. create_series: body = 0021 verbatim + the quota guard inside the
-- per-instance block — instances beyond the quota land in the skipped
-- report exactly like closed days, blocked seats and seat conflicts.
create or replace function public.create_series(
  p_workspace_id uuid,
  p_seat_id uuid,
  p_first_start timestamptz,
  p_first_end timestamptz,
  p_pattern text,
  p_until timestamptz
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_rules jsonb;
  v_max_days int;
  v_series_id uuid := gen_random_uuid();
  v_start timestamptz := p_first_start;
  v_end timestamptz := p_first_end;
  v_tz text;
  v_booked jsonb := '[]'::jsonb;
  v_skipped jsonb := '[]'::jsonb;
  v_step interval;
  v_dow int;
begin
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if p_pattern not in ('daily','weekdays','weekly') then
    raise exception 'unknown pattern';
  end if;
  select booking_rules, timezone into v_rules, v_tz
    from public.workspaces where id = p_workspace_id;
  v_max_days := coalesce((v_rules->>'max_series_days')::int, 180);
  if p_until > p_first_start + make_interval(days => v_max_days) then
    raise exception 'series exceeds the maximum of % days', v_max_days;
  end if;
  perform public.enforce_booking_rules(p_workspace_id, p_first_start, p_first_end);

  v_step := case when p_pattern = 'weekly' then interval '7 days' else interval '1 day' end;

  while v_start <= p_until loop
    -- weekday filter recurs in workspace-local time (spec §11 DST rule)
    v_dow := extract(isodow from v_start at time zone v_tz)::int;
    if p_pattern <> 'weekdays' or v_dow between 1 and 5 then
      begin
        -- closed days raise here and land in the skipped report, exactly
        -- like seat conflicts
        perform public.assert_workspace_open(p_workspace_id, v_start, v_end);
        -- blocked seats too (#161)
        perform public.assert_seat_not_blocked(p_seat_id, v_start, v_end);
        insert into public.reservations
          (workspace_id, seat_id, member_id, starts_at, ends_at, status, series_id)
        values (p_workspace_id, p_seat_id, v_member.id, v_start, v_end, 'reserved', v_series_id);
        -- beyond-quota instances are skipped, not booked
        perform public.assert_member_quota(v_member.id, v_start);
        v_booked := v_booked || to_jsonb(v_start);
      exception when others then
        v_skipped := v_skipped || to_jsonb(v_start);
      end;
    end if;
    v_start := v_start + v_step;
    v_end := v_end + v_step;
  end loop;

  return jsonb_build_object(
    'series_id', v_series_id,
    'booked', v_booked,
    'skipped', v_skipped
  );
end;
$$;

-- 8. respond_to_event: body = 0017 verbatim + the quota apply branch —
-- a confirmed request materializes as a quota_extensions row.
create or replace function public.respond_to_event(
  p_event_id uuid,
  p_accept boolean
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_event public.events;
  v_caller public.members;
  v_policy record;
  v_subject_decides boolean;
  v_in_pool boolean;
  v_pool_size int;
  v_required int;
  v_accepts int;
  v_subject_ok boolean;
  v_owner_ok boolean;
begin
  select e.* into v_event from public.events e where e.id = p_event_id;
  if v_event.id is null then raise exception 'unknown event'; end if;
  if v_event.status <> 'pending' then raise exception 'already decided'; end if;

  select m.* into v_caller from public.members m
    where m.workspace_id = v_event.workspace_id and m.user_id = auth.uid()
      and m.status = 'active';
  if v_caller.id is null then raise exception 'not a member'; end if;
  if exists (select 1 from public.event_decisions d
              where d.event_id = p_event_id and d.member_id = v_caller.id) then
    raise exception 'you already decided this event';
  end if;

  select * into v_policy from public.validation_policies
    where workspace_id = v_event.workspace_id and event_type = v_event.type;
  if v_policy is null then
    select * into v_policy from public.validation_policies
      where workspace_id = v_event.workspace_id and event_type is null;
  end if;
  if v_policy is null then
    -- pre-0017 behavior
    select null::uuid as id, v_event.workspace_id as workspace_id,
           null::text as event_type, 1 as required_count,
           true as admins_may_validate, '{}'::uuid[] as eligible_admin_ids,
           false as owner_required
      into v_policy;
  end if;

  -- admin-initiated events are accepted by their subject; self-initiated
  -- money events need validators
  v_subject_decides := v_event.type = 'reservation'
    or (v_event.type in ('payment','service_charge')
        and v_event.actor_member_id <> v_event.subject_member_id);

  -- validator pool: owners always; admins per policy; never the actor or
  -- subject. #107 escape hatch: an actor-admin alone in the pool may
  -- self-decide.
  select count(*) into v_pool_size from public.members m
    where m.workspace_id = v_event.workspace_id and m.status = 'active'
      and m.id not in (v_event.actor_member_id, v_event.subject_member_id)
      and (m.is_owner or (m.is_admin and v_policy.admins_may_validate
           and (cardinality(v_policy.eligible_admin_ids) = 0
                or m.id = any(v_policy.eligible_admin_ids))));

  -- the #107 escape hatch lifts BOTH exclusions on admin-decided events
  -- (a solo admin's own expense makes them actor AND subject); on
  -- subject-decides events the subject stays out of the pool — their
  -- mandatory accept is counted separately below
  v_in_pool := (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate
                and (cardinality(v_policy.eligible_admin_ids) = 0
                     or v_caller.id = any(v_policy.eligible_admin_ids))))
    and (v_caller.id <> v_event.subject_member_id
         or (not v_subject_decides and v_pool_size = 0))
    and (v_caller.id <> v_event.actor_member_id or v_pool_size = 0);
  if v_pool_size = 0 and (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate)) then
    -- solo-admin workspaces: the pool collapses to the actor (#107)
    v_pool_size := 1;
  end if;

  if v_subject_decides and v_caller.id = v_event.subject_member_id then
    null; -- the subject's decision is always admissible (and mandatory)
  elsif v_in_pool then
    null;
  else
    raise exception 'you are not an eligible validator for this event';
  end if;

  insert into public.event_decisions (event_id, member_id, decision)
  values (p_event_id, v_caller.id, case when p_accept then 'accept' else 'reject' end);

  if not p_accept then
    update public.events set status = 'rejected', decided_at = now()
      where id = p_event_id;
    if v_event.reservation_id is not null then
      update public.reservations set status = 'cancelled'
        where id = v_event.reservation_id and status in ('reserved','checked_in');
    end if;
    return;
  end if;

  -- confirmation check: enough accepts, subject on board, owner on board
  select count(*) into v_accepts from public.event_decisions
    where event_id = p_event_id and decision = 'accept';
  v_required := greatest(1, least(v_policy.required_count,
    v_pool_size + case when v_subject_decides then 1 else 0 end));
  v_subject_ok := not v_subject_decides or exists (
    select 1 from public.event_decisions d
    where d.event_id = p_event_id and d.decision = 'accept'
      and d.member_id = v_event.subject_member_id);
  v_owner_ok := not v_policy.owner_required or exists (
    select 1 from public.event_decisions d
    join public.members m on m.id = d.member_id
    where d.event_id = p_event_id and d.decision = 'accept' and m.is_owner);

  if v_accepts >= v_required and v_subject_ok and v_owner_ok then
    update public.events set status = 'confirmed', decided_at = now()
      where id = p_event_id;

    if v_event.type in ('payment','expense') then
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description, period, event_id)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'credit',
        case when v_event.type = 'payment' then 'payment' else 'expense' end,
        (v_event.payload->>'amount_cents')::int,
        coalesce(v_event.payload->>'note', ''),
        to_char(now(), 'YYYY-MM'),
        v_event.id
      );
    elsif v_event.type = 'service_charge' then
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description, period, event_id)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'charge', 'service',
        (v_event.payload->>'amount_cents')::int,
        (v_event.payload->>'name') || ' x' || (v_event.payload->>'quantity'),
        coalesce(v_event.payload->>'period', to_char(now(), 'YYYY-MM')),
        v_event.id
      );
    elsif v_event.type = 'quota' then
      -- the granted extension raises the member's cap for that period;
      -- consumption beyond the base entitlement still bills at the
      -- band's overage rate (member_statement is unchanged)
      insert into public.quota_extensions
        (workspace_id, member_id, period, half_days, event_id)
      values (
        v_event.workspace_id, v_event.subject_member_id,
        v_event.payload->>'period',
        (v_event.payload->>'half_days')::int,
        v_event.id
      );
    end if;
  end if;
end;
$$;
revoke execute on function public.respond_to_event(uuid, boolean) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- Configurable reservation slots. Applied to the hosted reference
-- project on 2026-07-18.
--
-- booking_rules.granularity (owner-set via set_booking_granularity's
-- merge write under workspaces_update RLS) now accepts, next to the
-- 0025 values 'flexible' and 'half_day':
--   * 'minutes_5' / 'minutes_15' / 'minutes_30' / 'minutes_60' —
--     bookings must start AND end on the N-minute grid (workspace-local
--     wall clock). Walk-ups start now and only their END must align.
--   * 'full_day' — bookings cover exactly the local 00:00→24:00 window;
--     a walk-up starts now and must END at the next local midnight.
-- 'flexible' keeps enforcing nothing (legacy), 'half_day' keeps the
-- 0026 canonical-window rules verbatim.

create or replace function public.enforce_booking_rules(
  p_workspace_id uuid, p_starts_at timestamptz, p_ends_at timestamptz,
  p_walk_up boolean default false
) returns void language plpgsql stable security definer set search_path = public as $$
declare rules jsonb; horizon int; min_min int; max_min int; dur int;
        tz text; local_start timestamp; local_end timestamp;
        gran text; slot int;
begin
  select booking_rules, timezone into rules, tz
    from public.workspaces where id = p_workspace_id;
  horizon := coalesce((rules->>'advance_horizon_days')::int, 90);
  min_min := coalesce((rules->>'min_duration_minutes')::int, 30);
  max_min := coalesce((rules->>'max_duration_minutes')::int, 1440);
  if p_starts_at > now() + make_interval(days => horizon) then
    raise exception 'beyond the advance-booking horizon of % days', horizon;
  end if;
  dur := extract(epoch from (p_ends_at - p_starts_at))::int / 60;
  if dur < min_min then
    raise exception 'below the minimum duration of % minutes', min_min;
  end if;
  if dur > max_min then
    raise exception 'above the maximum duration of % minutes', max_min;
  end if;

  gran := rules->>'granularity';
  local_start := p_starts_at at time zone tz;
  local_end := p_ends_at at time zone tz;

  -- Half-day granularity (#200/#201): unchanged from 0026 — the three
  -- canonical windows, walk-ups end at the half boundary. The client
  -- pins the substring 'half-day' (BookingGranularityError).
  if gran = 'half_day' then
    if p_walk_up then
      if not (
        (local_start::time < time '13:00'
          and local_end::time = time '13:00'
          and local_end::date = local_start::date)
        or (local_start::time >= time '13:00'
          and local_end::time = time '00:00'
          and local_end::date = local_start::date + 1)
      ) then
        raise exception 'walk-ups must end at the half-day boundary (13:00 or midnight)';
      end if;
    elsif not (
      (local_start::time = time '00:00'
        and local_end::time = time '13:00'
        and local_end::date = local_start::date)
      or (local_start::time = time '13:00'
        and local_end::time = time '00:00'
        and local_end::date = local_start::date + 1)
      or (local_start::time = time '00:00'
        and local_end::time = time '00:00'
        and local_end::date = local_start::date + 1)
    ) then
      raise exception 'bookings must cover a half-day (00:00-13:00, 13:00-24:00) or the full day';
    end if;

  -- Full-day granularity (0032): exactly the local day window. The
  -- client pins the substring 'cover the full day'.
  elsif gran = 'full_day' then
    if not (
      local_end::time = time '00:00'
      and local_end::date = local_start::date + 1
      and (p_walk_up or local_start::time = time '00:00')
    ) then
      raise exception 'bookings must cover the full day (00:00-24:00)';
    end if;

  -- Minute grid (0032): start and end align to the configured step; a
  -- walk-up's start is "now" and exempt. The client pins the substring
  -- 'minute grid'.
  elsif gran in ('minutes_5','minutes_15','minutes_30','minutes_60') then
    slot := split_part(gran, '_', 2)::int;
    if not (
      extract(second from local_end) = 0
      and extract(minute from local_end)::int % slot = 0
      and (p_walk_up or (
        extract(second from local_start) = 0
        and extract(minute from local_start)::int % slot = 0))
    ) then
      raise exception 'bookings must start and end on the %-minute grid', slot;
    end if;
  end if;

  perform public.assert_workspace_open(p_workspace_id, p_starts_at, p_ends_at);
end;
$$;
revoke execute on function public.enforce_booking_rules(uuid, timestamptz, timestamptz, boolean) from public, anon, authenticated;

-- SPDX-License-Identifier: 0BSD
-- Members edit their own reservations. Applied to the hosted reference
-- project on 2026-07-19.
--
-- The detail sheet gains Edit/Cancel everywhere (hub plan, Day, Week,
-- calendar timeline); cancel_reservation (0005) already covers delete,
-- this adds the atomic time edit: same seat, new window, every guard
-- re-checked in one transaction (the exclusion constraint re-validates
-- overlap against everyone else while ignoring the row's own old range).

-- The 0007 audit trigger only logged 'modified' on end changes; a pure
-- start move (edit) must audit too.
create or replace function public.log_reservation_event()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_action text;
begin
  if tg_op = 'INSERT' then
    v_action := 'created';
  elsif new.status = 'cancelled' and old.status <> 'cancelled' then
    v_action := 'cancelled';
  elsif new.status <> old.status
     or new.ends_at <> old.ends_at
     or new.starts_at <> old.starts_at then
    v_action := 'modified';
  else
    return new;
  end if;
  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id,
     reservation_id, payload, status)
  values
    (new.workspace_id, 'reservation', v_action, new.member_id, new.member_id,
     new.id,
     jsonb_build_object(
       'starts_at', new.starts_at, 'ends_at', new.ends_at,
       'status', new.status, 'seat_id', new.seat_id, 'office_id', new.office_id
     ),
     'applied');
  return new;
end;
$$;

-- Atomic own-reservation time edit: still 'reserved', rules + closure +
-- seat block + quota all re-checked for the NEW window.
create or replace function public.update_reservation(
  p_reservation_id uuid, p_starts_at timestamptz, p_ends_at timestamptz
) returns void language plpgsql security definer set search_path = public as $$
declare v_res public.reservations;
begin
  select r.* into v_res from public.reservations r
    join public.members m on m.id = r.member_id
    where r.id = p_reservation_id and m.user_id = auth.uid();
  if v_res.id is null then raise exception 'not your reservation'; end if;
  if v_res.status <> 'reserved' then
    raise exception 'only upcoming reservations can be edited';
  end if;
  perform public.enforce_booking_rules(
    v_res.workspace_id, p_starts_at, p_ends_at);
  if v_res.seat_id is not null then
    perform public.assert_seat_not_blocked(
      v_res.seat_id, p_starts_at, p_ends_at);
  end if;
  update public.reservations
    set starts_at = p_starts_at, ends_at = p_ends_at
    where id = p_reservation_id;
  perform public.assert_member_quota(v_res.member_id, p_starts_at);
end;
$$;
revoke execute on function public.update_reservation(uuid, timestamptz, timestamptz) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- Persist the repetition modality. Applied to the hosted reference
-- project on 2026-07-19.
--
-- Series instances only carried a grouping series_id; the PATTERN
-- (daily / weekdays / weekly) was expanded at creation and lost, so no
-- surface could tell the user HOW a booking repeats. The column rides
-- every instance; pre-0034 rows stay null and read as a generic
-- recurring booking.

alter table public.reservations
  add column series_pattern text
  check (series_pattern in ('daily','weekdays','weekly'));

-- create_series: body = 0031 verbatim + series_pattern on the insert.
create or replace function public.create_series(
  p_workspace_id uuid,
  p_seat_id uuid,
  p_first_start timestamptz,
  p_first_end timestamptz,
  p_pattern text,
  p_until timestamptz
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_rules jsonb;
  v_max_days int;
  v_series_id uuid := gen_random_uuid();
  v_start timestamptz := p_first_start;
  v_end timestamptz := p_first_end;
  v_tz text;
  v_booked jsonb := '[]'::jsonb;
  v_skipped jsonb := '[]'::jsonb;
  v_step interval;
  v_dow int;
begin
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if p_pattern not in ('daily','weekdays','weekly') then
    raise exception 'unknown pattern';
  end if;
  select booking_rules, timezone into v_rules, v_tz
    from public.workspaces where id = p_workspace_id;
  v_max_days := coalesce((v_rules->>'max_series_days')::int, 180);
  if p_until > p_first_start + make_interval(days => v_max_days) then
    raise exception 'series exceeds the maximum of % days', v_max_days;
  end if;
  perform public.enforce_booking_rules(p_workspace_id, p_first_start, p_first_end);

  v_step := case when p_pattern = 'weekly' then interval '7 days' else interval '1 day' end;

  while v_start <= p_until loop
    -- weekday filter recurs in workspace-local time (spec §11 DST rule)
    v_dow := extract(isodow from v_start at time zone v_tz)::int;
    if p_pattern <> 'weekdays' or v_dow between 1 and 5 then
      begin
        -- closed days raise here and land in the skipped report, exactly
        -- like seat conflicts
        perform public.assert_workspace_open(p_workspace_id, v_start, v_end);
        -- blocked seats too (#161)
        perform public.assert_seat_not_blocked(p_seat_id, v_start, v_end);
        insert into public.reservations
          (workspace_id, seat_id, member_id, starts_at, ends_at, status,
           series_id, series_pattern)
        values (p_workspace_id, p_seat_id, v_member.id, v_start, v_end,
                'reserved', v_series_id, p_pattern);
        -- beyond-quota instances are skipped, not booked
        perform public.assert_member_quota(v_member.id, v_start);
        v_booked := v_booked || to_jsonb(v_start);
      exception when others then
        v_skipped := v_skipped || to_jsonb(v_start);
      end;
    end if;
    v_start := v_start + v_step;
    v_end := v_end + v_step;
  end loop;

  return jsonb_build_object(
    'series_id', v_series_id,
    'booked', v_booked,
    'skipped', v_skipped
  );
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- Owner-initiated role changes, routed through the validation quorum.
-- Applied to the hosted reference project on 2026-07-19.
--
-- The owner promotes a member to admin or demotes an admin to a regular
-- member; the change does NOT apply immediately — it enters the events
-- spine as a new 'role_change' type and is confirmed by the workspace's
-- validators per its validation_policies rule (required_count, eligible
-- admins, owner_required), exactly like a payment or an expense. In a
-- solo-owner workspace the #107 escape hatch auto-applies it.

alter table public.events drop constraint events_type_check;
alter table public.events add constraint events_type_check
  check (type in ('reservation','payment','expense','adjustment',
                  'service_charge','quota','role_change'));

-- the owner requests a role change on a non-owner member
create or replace function public.request_role_change(
  p_workspace_id uuid, p_target_member_id uuid, p_make_admin boolean
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_owner public.members;
  v_target public.members;
  v_id uuid;
begin
  if not public.is_owner_of(p_workspace_id) then
    raise exception 'only owners may change roles';
  end if;
  select * into v_owner from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active';
  select * into v_target from public.members
    where id = p_target_member_id and workspace_id = p_workspace_id
      and status = 'active';
  if v_target.id is null then raise exception 'unknown member'; end if;
  if v_target.is_owner then
    raise exception 'owners keep their admin rights';
  end if;
  if v_target.is_admin = p_make_admin then
    raise exception 'member already has that role';
  end if;
  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id,
     payload, status)
  values (
    p_workspace_id, 'role_change', 'submitted', v_owner.id,
    p_target_member_id,
    jsonb_build_object('make_admin', p_make_admin),
    'pending'
  )
  returning id into v_id;
  return v_id;
end;
$$;
revoke execute on function public.request_role_change(uuid, uuid, boolean) from public, anon;

-- respond_to_event: body = 0031 verbatim + the role_change apply branch.
create or replace function public.respond_to_event(
  p_event_id uuid,
  p_accept boolean
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_event public.events;
  v_caller public.members;
  v_policy record;
  v_subject_decides boolean;
  v_in_pool boolean;
  v_pool_size int;
  v_required int;
  v_accepts int;
  v_subject_ok boolean;
  v_owner_ok boolean;
begin
  select e.* into v_event from public.events e where e.id = p_event_id;
  if v_event.id is null then raise exception 'unknown event'; end if;
  if v_event.status <> 'pending' then raise exception 'already decided'; end if;

  select m.* into v_caller from public.members m
    where m.workspace_id = v_event.workspace_id and m.user_id = auth.uid()
      and m.status = 'active';
  if v_caller.id is null then raise exception 'not a member'; end if;
  if exists (select 1 from public.event_decisions d
              where d.event_id = p_event_id and d.member_id = v_caller.id) then
    raise exception 'you already decided this event';
  end if;

  select * into v_policy from public.validation_policies
    where workspace_id = v_event.workspace_id and event_type = v_event.type;
  if v_policy is null then
    select * into v_policy from public.validation_policies
      where workspace_id = v_event.workspace_id and event_type is null;
  end if;
  if v_policy is null then
    -- pre-0017 behavior
    select null::uuid as id, v_event.workspace_id as workspace_id,
           null::text as event_type, 1 as required_count,
           true as admins_may_validate, '{}'::uuid[] as eligible_admin_ids,
           false as owner_required
      into v_policy;
  end if;

  -- admin-initiated events are accepted by their subject; self-initiated
  -- money events need validators
  v_subject_decides := v_event.type = 'reservation'
    or (v_event.type in ('payment','service_charge')
        and v_event.actor_member_id <> v_event.subject_member_id);

  -- validator pool: owners always; admins per policy; never the actor or
  -- subject. #107 escape hatch: an actor-admin alone in the pool may
  -- self-decide.
  select count(*) into v_pool_size from public.members m
    where m.workspace_id = v_event.workspace_id and m.status = 'active'
      and m.id not in (v_event.actor_member_id, v_event.subject_member_id)
      and (m.is_owner or (m.is_admin and v_policy.admins_may_validate
           and (cardinality(v_policy.eligible_admin_ids) = 0
                or m.id = any(v_policy.eligible_admin_ids))));

  -- the #107 escape hatch lifts BOTH exclusions on admin-decided events
  -- (a solo admin's own expense makes them actor AND subject); on
  -- subject-decides events the subject stays out of the pool — their
  -- mandatory accept is counted separately below
  v_in_pool := (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate
                and (cardinality(v_policy.eligible_admin_ids) = 0
                     or v_caller.id = any(v_policy.eligible_admin_ids))))
    and (v_caller.id <> v_event.subject_member_id
         or (not v_subject_decides and v_pool_size = 0))
    and (v_caller.id <> v_event.actor_member_id or v_pool_size = 0);
  if v_pool_size = 0 and (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate)) then
    -- solo-admin workspaces: the pool collapses to the actor (#107)
    v_pool_size := 1;
  end if;

  if v_subject_decides and v_caller.id = v_event.subject_member_id then
    null; -- the subject's decision is always admissible (and mandatory)
  elsif v_in_pool then
    null;
  else
    raise exception 'you are not an eligible validator for this event';
  end if;

  insert into public.event_decisions (event_id, member_id, decision)
  values (p_event_id, v_caller.id, case when p_accept then 'accept' else 'reject' end);

  if not p_accept then
    update public.events set status = 'rejected', decided_at = now()
      where id = p_event_id;
    if v_event.reservation_id is not null then
      update public.reservations set status = 'cancelled'
        where id = v_event.reservation_id and status in ('reserved','checked_in');
    end if;
    return;
  end if;

  -- confirmation check: enough accepts, subject on board, owner on board
  select count(*) into v_accepts from public.event_decisions
    where event_id = p_event_id and decision = 'accept';
  v_required := greatest(1, least(v_policy.required_count,
    v_pool_size + case when v_subject_decides then 1 else 0 end));
  v_subject_ok := not v_subject_decides or exists (
    select 1 from public.event_decisions d
    where d.event_id = p_event_id and d.decision = 'accept'
      and d.member_id = v_event.subject_member_id);
  v_owner_ok := not v_policy.owner_required or exists (
    select 1 from public.event_decisions d
    join public.members m on m.id = d.member_id
    where d.event_id = p_event_id and d.decision = 'accept' and m.is_owner);

  if v_accepts >= v_required and v_subject_ok and v_owner_ok then
    update public.events set status = 'confirmed', decided_at = now()
      where id = p_event_id;

    if v_event.type in ('payment','expense') then
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description, period, event_id)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'credit',
        case when v_event.type = 'payment' then 'payment' else 'expense' end,
        (v_event.payload->>'amount_cents')::int,
        coalesce(v_event.payload->>'note', ''),
        to_char(now(), 'YYYY-MM'),
        v_event.id
      );
    elsif v_event.type = 'service_charge' then
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description, period, event_id)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'charge', 'service',
        (v_event.payload->>'amount_cents')::int,
        (v_event.payload->>'name') || ' x' || (v_event.payload->>'quantity'),
        coalesce(v_event.payload->>'period', to_char(now(), 'YYYY-MM')),
        v_event.id
      );
    elsif v_event.type = 'quota' then
      -- the granted extension raises the member's cap for that period;
      -- consumption beyond the base entitlement still bills at the
      -- band's overage rate (member_statement is unchanged)
      insert into public.quota_extensions
        (workspace_id, member_id, period, half_days, event_id)
      values (
        v_event.workspace_id, v_event.subject_member_id,
        v_event.payload->>'period',
        (v_event.payload->>'half_days')::int,
        v_event.id
      );
    elsif v_event.type = 'role_change' then
      -- the validated decision flips the target's admin flag; owners are
      -- untouched (request_role_change refuses them) and the last-owner
      -- trigger still guards the is_owner column separately.
      update public.members
        set is_admin = (v_event.payload->>'make_admin')::boolean
        where id = v_event.subject_member_id;
    end if;
  end if;
end;
$$;
revoke execute on function public.respond_to_event(uuid, boolean) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- A background image per level — a photo or blueprint of the real
-- working space, rendered behind the seat/desk graphics so the plan
-- reads against the actual room. Applied to the hosted reference
-- project on 2026-07-19.
--
-- The image lives in the private `floor-plans` storage bucket at
-- `<workspace_id>/<level_id>`; the level row keeps the object path.
-- Reads are workspace-scoped, writes owner-only, both enforced by
-- storage.objects RLS that derives the workspace from the first path
-- segment.

alter table public.levels add column background_path text;

-- Storage RLS on the floor-plans bucket. The first folder of the object
-- name is the workspace id; membership / ownership gate access.
create policy floor_plans_select on storage.objects
  for select using (
    bucket_id = 'floor-plans'
    and public.is_member_of((storage.foldername(name))[1]::uuid)
  );

create policy floor_plans_insert on storage.objects
  for insert with check (
    bucket_id = 'floor-plans'
    and public.is_owner_of((storage.foldername(name))[1]::uuid)
  );

create policy floor_plans_update on storage.objects
  for update using (
    bucket_id = 'floor-plans'
    and public.is_owner_of((storage.foldername(name))[1]::uuid)
  );

create policy floor_plans_delete on storage.objects
  for delete using (
    bucket_id = 'floor-plans'
    and public.is_owner_of((storage.foldername(name))[1]::uuid)
  );

-- SPDX-License-Identifier: 0BSD
-- Member profile photos (avatars): each user may set one photo, shown on
-- their directory row and detail sheet, on calendar/timeline blocks and
-- everywhere the initial avatar renders today. Applied to the hosted
-- reference project on 2026-07-19.
--
-- The photo lives in a private `avatars` storage bucket at
-- `<user_id>/avatar`; the profile row keeps the object path. Reads follow
-- the profile's own visibility (self + anyone sharing a workspace, exactly
-- like profiles_select, 0002), writes are self-only — both enforced by
-- storage.objects RLS deriving the owner from the first path segment.

alter table public.profiles add column avatar_path text;

-- Private bucket for avatars (id = name; created idempotently).
insert into storage.buckets (id, name, public)
values ('avatars', 'avatars', false)
on conflict (id) do nothing;

-- The first folder of the object name is the owner's user id.
create policy avatars_select on storage.objects
  for select using (
    bucket_id = 'avatars'
    and (
      (storage.foldername(name))[1] = auth.uid()::text
      or public.shares_workspace_with((storage.foldername(name))[1]::uuid)
    )
  );

create policy avatars_insert on storage.objects
  for insert with check (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

create policy avatars_update on storage.objects
  for update using (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

create policy avatars_delete on storage.objects
  for delete using (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

-- SPDX-License-Identifier: 0BSD
-- Owner-initiated workspace reset: wipe all transactions and the entire
-- floor plan, keeping only the workspace configuration and its members.
-- Applied to the hosted reference project on 2026-07-20.
--
-- DELETES: reservations, events (+ their decisions), ledger entries, quota
-- extensions, and the whole floor plan (plan images, seat accessories,
-- seats, desks, offices, levels — including level background photos).
-- KEEPS: the workspaces row (settings / booking_rules / feature_flags /
-- availability / payment instructions / whatsapp group), members, profiles,
-- fee bands, the service and accessory catalogs, closure days, validation
-- policies and admin invites.
--
-- Guarded to owners; the client additionally requires a typed confirmation
-- ("I agree") before calling it. Irreversible.

create or replace function public.reset_workspace(p_workspace_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_owner_of(p_workspace_id) then
    raise exception 'only owners may reset the workspace';
  end if;

  -- Transactions first (events.reservation_id is ON DELETE SET NULL, and
  -- event_decisions cascade from events; delete both explicitly anyway).
  delete from public.event_decisions d
    using public.events e
    where d.event_id = e.id and e.workspace_id = p_workspace_id;
  delete from public.events where workspace_id = p_workspace_id;
  delete from public.ledger_entries where workspace_id = p_workspace_id;
  delete from public.quota_extensions where workspace_id = p_workspace_id;
  delete from public.reservations where workspace_id = p_workspace_id;

  -- The floor plan (seat_accessories cascade from seats; children before
  -- parents so the delete never trips a foreign key either way).
  delete from public.plan_images where workspace_id = p_workspace_id;
  delete from public.seat_accessories where workspace_id = p_workspace_id;
  delete from public.seats where workspace_id = p_workspace_id;
  delete from public.desks where workspace_id = p_workspace_id;
  delete from public.offices where workspace_id = p_workspace_id;
  delete from public.levels where workspace_id = p_workspace_id;
end;
$$;
revoke execute on function public.reset_workspace(uuid) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- Per-member over-consumption policy (epic: subscription over-consumption).
-- NOT YET applied to the hosted reference project — the orchestrator
-- applies it after review.
--
-- A member's monthly entitlement stays ceil(open_days x 2 x pct / 100)
-- half-days (ADR 0008). What happens once it is used up is now an owner
-- choice PER MEMBER:
--
--   'blocked' — the current behaviour and the default: no booking past
--               the entitlement (+ confirmed extensions). The member must
--               request extra half-days (0031) or buy a package.
--   'payg'    — pay-as-you-go: the member MAY book past the entitlement;
--               every extra half-day bills at the fee band's overage rate.
--   'package' — the member must buy a pre-defined package first. Until the
--               packages migration ships, this behaves like 'blocked'
--               (the guard still raises; buying is added next).
--
-- Only the overage GATE changes here. Overage PRICING already exists:
-- member_statement bills max(0, used - included) x band.overage_rate, so a
-- payg member's extra half-days are charged with no further change.

alter table public.members
  add column overage_policy text not null default 'blocked'
  check (overage_policy in ('blocked','payg','package'));

-- ---------------------------------------------------------------------
-- assert_member_quota: body = 0031 verbatim + the payg early-return. A
-- pay-as-you-go member is never blocked; their extra half-days bill at
-- the band rate (member_statement, unchanged). blocked/package still raise.
-- ---------------------------------------------------------------------
create or replace function public.assert_member_quota(
  p_member_id uuid, p_at timestamptz
) returns void language plpgsql stable security definer set search_path = public as $$
declare
  v_member public.members;
  v_tz text;
  v_open int[];
  v_pct int;
  v_period text;
  v_month_first date;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_open_days int;
  v_included int;
  v_ext int;
  v_used int;
begin
  select * into v_member from public.members where id = p_member_id;
  select timezone,
         coalesce((select array_agg(x::int)
                     from jsonb_array_elements_text(booking_rules->'open_weekdays') x),
                  array[1,2,3,4,5])
    into v_tz, v_open
    from public.workspaces where id = v_member.workspace_id;

  v_period := to_char(p_at at time zone v_tz, 'YYYY-MM');
  v_month_first := to_date(v_period || '-01', 'YYYY-MM-DD');
  v_period_start := to_timestamp(v_period || '-01', 'YYYY-MM-DD') at time zone v_tz;
  v_period_end := (to_timestamp(v_period || '-01', 'YYYY-MM-DD') + interval '1 month') at time zone v_tz;

  v_pct := coalesce(v_member.subscription_pct, 100);
  select count(*) into v_open_days
  from generate_series(v_month_first,
                       (v_month_first + interval '1 month' - interval '1 day')::date,
                       interval '1 day') d
  where extract(isodow from d)::int = any(v_open)
    and not exists (select 1 from public.closure_days c
                     where c.workspace_id = v_member.workspace_id and c.day = d::date);
  v_included := ceil(v_open_days * 2 * v_pct / 100.0)::int;

  select coalesce(sum(half_days), 0) into v_ext from public.quota_extensions
    where member_id = p_member_id and period = v_period;

  select count(distinct (date_trunc('day', r.starts_at at time zone v_tz)::date, s.slot))
  into v_used
  from public.reservations r
  cross join lateral (
    select case when extract(hour from r.starts_at at time zone v_tz) < 13 then 0 else 1 end as slot
  ) s
  where r.member_id = p_member_id
    and r.status in ('reserved','checked_in','completed')
    and r.starts_at >= v_period_start and r.starts_at < v_period_end;

  if v_used > v_included + v_ext then
    -- pay-as-you-go members may go over; the overage bills at the band rate
    if coalesce(v_member.overage_policy, 'blocked') = 'payg' then
      return;
    end if;
    -- the client pins the substring 'half-day quota' of this message
    raise exception 'half-day quota exceeded — request additional half-days';
  end if;
end;
$$;
revoke execute on function public.assert_member_quota(uuid, timestamptz) from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- Statement v4: v3 (0024) + the granted-extension sum and three new
-- fields the app needs to show "N days included · X used · Y left" and
-- pick the right call-to-action (overage_policy). Body copied verbatim
-- from 0024; additions marked with "#overage". Balance formula unchanged.
-- ---------------------------------------------------------------------
create or replace function public.member_statement(
  p_member_id uuid,
  p_period text
) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_member public.members;
  v_caller_is_admin boolean;
  v_band public.fee_bands;
  v_tz text;
  v_open int[];
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_month_first date;
  v_open_days int;
  v_pct int;
  v_included int;
  v_used int;
  v_base int := 0;
  v_overage int := 0;
  v_overage_rate int := 0;
  v_credits int;
  v_extra_half_days int := 0;
  v_supp_on boolean := false;
  v_supp_since timestamptz;
  v_supplement int := 0;
  -- #overage: granted extensions + the resulting cap/remaining
  v_granted int := 0;
  v_cap int := 0;
  v_remaining int := 0;
begin
  select * into v_member from public.members where id = p_member_id;
  if v_member.id is null then raise exception 'unknown member'; end if;
  v_caller_is_admin := public.is_admin_of(v_member.workspace_id);
  if not v_caller_is_admin and not exists (
    select 1 from public.members m
    where m.id = p_member_id and m.user_id = auth.uid()
  ) then
    raise exception 'not your statement';
  end if;

  select timezone,
         coalesce((select array_agg(x::int)
                     from jsonb_array_elements_text(booking_rules->'open_weekdays') x),
                  array[1,2,3,4,5]),
         coalesce(feature_flags -> 'accessorySupplements' = to_jsonb(true), false),
         accessory_supplements_since
    into v_tz, v_open, v_supp_on, v_supp_since
    from public.workspaces where id = v_member.workspace_id;
  v_period_start := to_timestamp(p_period || '-01', 'YYYY-MM-DD') at time zone v_tz;
  v_period_end := (to_timestamp(p_period || '-01', 'YYYY-MM-DD') + interval '1 month') at time zone v_tz;
  v_month_first := to_date(p_period || '-01', 'YYYY-MM-DD');

  v_pct := coalesce(v_member.subscription_pct, 100);
  select * into v_band from public.fee_bands
    where workspace_id = v_member.workspace_id
      and from_pct < v_pct and v_pct <= to_pct;
  if v_band.id is not null then
    v_base := v_band.fee_cents;
    v_overage_rate := v_band.overage_fee_cents;
  end if;

  select count(*) into v_open_days
  from generate_series(v_month_first,
                       (v_month_first + interval '1 month' - interval '1 day')::date,
                       interval '1 day') d
  where extract(isodow from d)::int = any(v_open)
    and not exists (select 1 from public.closure_days c
                     where c.workspace_id = v_member.workspace_id and c.day = d::date);
  v_included := ceil(v_open_days * 2 * v_pct / 100.0)::int;

  select count(distinct (date_trunc('day', r.starts_at at time zone v_tz)::date, s.slot))
  into v_used
  from public.reservations r
  cross join lateral (
    select case when extract(hour from r.starts_at at time zone v_tz) < 13 then 0 else 1 end as slot
  ) s
  where r.member_id = p_member_id
    and r.status in ('reserved','checked_in','completed')
    and r.starts_at >= v_period_start and r.starts_at < v_period_end;

  v_extra_half_days := greatest(0, v_used - v_included);
  v_overage := v_extra_half_days * v_overage_rate;

  -- #overage: confirmed extensions raise the cap; remaining = cap - used
  select coalesce(sum(half_days), 0) into v_granted from public.quota_extensions
    where member_id = p_member_id and period = p_period;
  v_cap := v_included + v_granted;
  v_remaining := greatest(0, v_cap - v_used);

  if v_supp_on and v_supp_since is not null then
    select coalesce(sum(seat_supp.total_cents), 0) into v_supplement
    from (
      select distinct
        r.seat_id,
        date_trunc('day', r.starts_at at time zone v_tz)::date as day,
        case when extract(hour from r.starts_at at time zone v_tz) < 13 then 0 else 1 end as slot
      from public.reservations r
      where r.member_id = p_member_id
        and r.seat_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= greatest(v_period_start, v_supp_since)
        and r.starts_at < v_period_end
    ) hd
    join (
      select sa.seat_id, sum(a.supplement_cents)::int as total_cents
      from public.seat_accessories sa
      join public.accessories a on a.id = sa.accessory_id
      where a.active and a.supplement_cents > 0
      group by sa.seat_id
    ) seat_supp on seat_supp.seat_id = hd.seat_id;
  end if;

  select coalesce(sum(case when kind = 'credit' then amount_cents else -amount_cents end), 0)
  into v_credits
  from public.ledger_entries
  where member_id = p_member_id and period = p_period;

  return jsonb_build_object(
    'period', p_period,
    'subscription_pct', v_pct,
    'fee_cents', v_base,
    'included_half_days', v_included,
    'open_days', v_open_days,
    'used_half_days', v_used,
    'extra_half_days', v_extra_half_days,
    'overage_cents', v_overage,
    'accessory_supplement_cents', v_supplement,
    'credits_cents', v_credits,
    'balance_cents', v_credits - v_base - v_overage - v_supplement,
    -- #overage
    'overage_policy', coalesce(v_member.overage_policy, 'blocked'),
    'overage_rate_cents', v_overage_rate,
    'granted_half_days', v_granted,
    'remaining_half_days', v_remaining
  );
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- Day packages (epic: subscription over-consumption). NOT YET applied to
-- the hosted reference project — the orchestrator applies it after review.
--
-- Completes migration 0041's 'package' over-consumption policy: the owner
-- pre-defines packages (a number of days for a price); a member whose
-- policy is 'package' buys one self-service once their monthly days run
-- out. Buying is immediate — it raises the member's cap for the current
-- period (a quota_extensions row of days x 2 half-days) and posts the
-- price as a ledger charge on their bill. No approval step: defining the
-- packages IS the owner's approval.

-- 1. the 'package' ledger category, so a purchase has an honest bill line
alter table public.ledger_entries drop constraint ledger_entries_category_check;
alter table public.ledger_entries add constraint ledger_entries_category_check
  check (category in ('subscription','overage','expense','payment','adjustment','service','package'));

-- 2. owner-defined packages
create table public.packages (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  name text not null check (char_length(name) between 1 and 80),
  days int not null check (days between 1 and 365),
  price_cents int not null check (price_cents >= 0),
  active boolean not null default true,
  created_at timestamptz not null default now()
);
create index packages_workspace_idx on public.packages (workspace_id);

alter table public.packages enable row level security;
-- members read active packages (the buy sheet); admins/owners read all
-- (the editor). Only owners write.
create policy packages_select on public.packages
  for select using (
    public.is_admin_of(workspace_id)
    or (active and exists (
      select 1 from public.members m
      where m.workspace_id = packages.workspace_id
        and m.user_id = auth.uid() and m.status = 'active'))
  );
create policy packages_write on public.packages
  for all using (public.is_owner_of(workspace_id))
  with check (public.is_owner_of(workspace_id));

-- 3. buy a package: raises the member's cap and charges the price. Only a
-- member whose over-consumption policy is 'package' may buy — that is the
-- gate the owner set in 0041. Self-service and immediate.
create or replace function public.buy_package(
  p_workspace_id uuid, p_package_id uuid
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_pkg public.packages;
  v_tz text;
  v_period text;
  v_ext_id uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if coalesce(v_member.overage_policy, 'blocked') <> 'package' then
    raise exception 'member is not on the package plan';
  end if;

  select * into v_pkg from public.packages
    where id = p_package_id and workspace_id = p_workspace_id and active;
  if v_pkg.id is null then raise exception 'unknown or inactive package'; end if;

  select timezone into v_tz from public.workspaces where id = p_workspace_id;
  v_period := to_char(now() at time zone v_tz, 'YYYY-MM');

  -- raise the cap for the current period (days x 2 half-days). Reuses the
  -- quota_extensions machinery the guard already reads (0031/0041).
  insert into public.quota_extensions
    (workspace_id, member_id, period, half_days)
  values (p_workspace_id, v_member.id, v_period, v_pkg.days * 2)
  returning id into v_ext_id;

  -- and post the price as a charge on this period's bill
  insert into public.ledger_entries
    (workspace_id, member_id, kind, category, amount_cents, description, period)
  values (
    p_workspace_id, v_member.id, 'charge', 'package', v_pkg.price_cents,
    v_pkg.name || ' (' || v_pkg.days || 'd)', v_period
  );

  return v_ext_id;
end;
$$;
revoke execute on function public.buy_package(uuid, uuid) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- Kiosk devices + member badges (epic: wall-mounted tablet mode). NOT YET
-- applied to the hosted reference project — the orchestrator applies it
-- after review.
--
-- A KIOSK is a dedicated member account signed in permanently on a
-- wall-mounted tablet. Its app locks to the plan view; it can see
-- occupancy but never act as itself. A real member acts THROUGH the kiosk
-- by presenting a BADGE (QR/barcode or NFC tag): the kiosk calls
-- kiosk_act with the badge's one-time-issued secret token, the server
-- resolves the member and performs the reserve/check-in/check-out AS that
-- member — stateless, so there is nothing to sign out of and nothing is
-- ever cached on the device.
--
-- Badge tokens are generated server-side and returned RAW exactly once
-- (the QR the owner prints / the member shows); the server stores only
-- the SHA-256 hash.

-- 1. the kiosk member type
alter table public.members
  add column is_kiosk boolean not null default false;

-- 2. badges
create table public.member_badges (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  member_id uuid not null references public.members(id) on delete cascade,
  token_hash text not null unique,
  label text not null default '' check (char_length(label) <= 60),
  created_at timestamptz not null default now(),
  revoked_at timestamptz
);
create index member_badges_member_idx on public.member_badges (member_id);

alter table public.member_badges enable row level security;
-- admins manage badges; a member sees their own (their profile shows the
-- badge QR). No direct writes — issuing goes through the RPC so the raw
-- token is minted server-side.
create policy member_badges_select on public.member_badges
  for select using (
    public.is_admin_of(workspace_id)
    or exists (select 1 from public.members m
                where m.id = member_id and m.user_id = auth.uid())
  );

-- Pure hashing helper (fully-qualified extension call, no definer needed).
create or replace function public.badge_token_hash(p_token text)
returns text language sql immutable set search_path = public as $$
  select encode(extensions.digest(p_token, 'sha256'), 'hex');
$$;
revoke execute on function public.badge_token_hash(text) from public, anon;

-- 3. issue / revoke (owner or admin)
create or replace function public.issue_member_badge(
  p_workspace_id uuid, p_member_id uuid, p_label text default ''
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_token text;
  v_id uuid;
begin
  if not public.is_admin_of(p_workspace_id) then
    raise exception 'not an admin of this workspace';
  end if;
  if not exists (select 1 from public.members
                  where id = p_member_id and workspace_id = p_workspace_id
                    and status = 'active' and not is_kiosk) then
    raise exception 'unknown member';
  end if;
  -- 32 random bytes, hex — shown once as the badge QR payload.
  v_token := encode(extensions.gen_random_bytes(32), 'hex');
  insert into public.member_badges (workspace_id, member_id, token_hash, label)
  values (p_workspace_id, p_member_id, public.badge_token_hash(v_token),
          coalesce(p_label, ''))
  returning id into v_id;
  return jsonb_build_object('badge_id', v_id, 'token', v_token);
end;
$$;
revoke execute on function public.issue_member_badge(uuid, uuid, text) from public, anon;

create or replace function public.revoke_member_badge(p_badge_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare v_ws uuid;
begin
  select workspace_id into v_ws from public.member_badges where id = p_badge_id;
  if v_ws is null then raise exception 'unknown badge'; end if;
  if not public.is_admin_of(v_ws) then
    raise exception 'not an admin of this workspace';
  end if;
  update public.member_badges set revoked_at = now()
    where id = p_badge_id and revoked_at is null;
end;
$$;
revoke execute on function public.revoke_member_badge(uuid) from public, anon;

-- 4. the kiosk toggle (owner-only, like the subscription update path the
-- members screen uses — plain UPDATE under owner RLS would also work, but
-- the RPC keeps the invariant that a kiosk holds no badges/bookings roles)
create or replace function public.set_member_kiosk(
  p_member_id uuid, p_is_kiosk boolean
) returns void language plpgsql security definer set search_path = public as $$
declare v_member public.members;
begin
  select * into v_member from public.members where id = p_member_id;
  if v_member.id is null then raise exception 'unknown member'; end if;
  if not exists (select 1 from public.members
                  where workspace_id = v_member.workspace_id
                    and user_id = auth.uid() and is_owner and status = 'active') then
    raise exception 'not the owner of this workspace';
  end if;
  if v_member.is_owner then raise exception 'the owner cannot be a kiosk'; end if;
  update public.members set is_kiosk = p_is_kiosk where id = p_member_id;
end;
$$;
revoke execute on function public.set_member_kiosk(uuid, boolean) from public, anon;

-- 5. kiosk_act: a kiosk performs one action AS the badge's member.
-- Stateless per call — the "session" begins and ends inside this function,
-- which is what "automatically checked out once the operation is done"
-- means server-side. Seat-level actions only (wall tablets don't book
-- whole offices).
create or replace function public.kiosk_act(
  p_workspace_id uuid,
  p_badge_token text,
  p_action text,             -- 'reserve' | 'check_in' | 'check_out'
  p_seat_id uuid default null,
  p_starts_at timestamptz default null,
  p_ends_at timestamptz default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_kiosk public.members;
  v_badge public.member_badges;
  v_subject public.members;
  v_seat public.seats;
  v_office_id uuid;
  v_res public.reservations;
  v_id uuid;
begin
  -- caller must be an active kiosk member of this workspace
  select * into v_kiosk from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and is_kiosk;
  if v_kiosk.id is null then raise exception 'not a kiosk of this workspace'; end if;

  -- resolve the badge → subject member
  select * into v_badge from public.member_badges
    where workspace_id = p_workspace_id
      and token_hash = public.badge_token_hash(p_badge_token)
      and revoked_at is null;
  if v_badge.id is null then
    -- the client pins this substring
    raise exception 'badge not recognized';
  end if;
  select * into v_subject from public.members
    where id = v_badge.member_id and status = 'active';
  if v_subject.id is null then raise exception 'badge member not active'; end if;

  if p_action = 'check_out' then
    -- complete the subject's current checked-in reservation (on the seat
    -- when given, else whichever is active).
    select r.* into v_res from public.reservations r
      where r.member_id = v_subject.id and r.status = 'checked_in'
        and (p_seat_id is null or r.seat_id = p_seat_id)
      order by r.checked_in_at desc limit 1;
    if v_res.id is null then raise exception 'not checked in'; end if;
    update public.reservations
      set status = 'completed', checked_out_at = now(),
          ends_at = least(ends_at, now())
      where id = v_res.id;
    return jsonb_build_object('action', 'check_out', 'reservation_id', v_res.id);
  end if;

  if p_action not in ('reserve', 'check_in') then
    raise exception 'unknown kiosk action';
  end if;
  if p_seat_id is null or p_starts_at is null or p_ends_at is null then
    raise exception 'seat and window required';
  end if;

  select * into v_seat from public.seats
    where id = p_seat_id and workspace_id = p_workspace_id;
  if v_seat.id is null then raise exception 'unknown seat'; end if;

  if p_action = 'check_in' then
    -- an existing reserved booking covering now checks in instead of
    -- creating a duplicate walk-up
    select r.* into v_res from public.reservations r
      where r.member_id = v_subject.id and r.seat_id = p_seat_id
        and r.status = 'reserved'
        and r.starts_at <= now() and r.ends_at > now()
      limit 1;
    if v_res.id is not null then
      update public.reservations
        set status = 'checked_in', checked_in_at = now()
        where id = v_res.id;
      return jsonb_build_object('action', 'check_in', 'reservation_id', v_res.id);
    end if;
  end if;

  -- fresh booking (reserve, or walk-up check-in): same guards as
  -- create_reservation's seat path
  perform public.enforce_booking_rules(
    p_workspace_id, p_starts_at, p_ends_at, p_action = 'check_in');
  if tstzrange(coalesce(v_seat.blocked_from, '-infinity'::timestamptz),
               coalesce(v_seat.blocked_to, 'infinity'::timestamptz))
     && tstzrange(p_starts_at, p_ends_at)
     and (v_seat.blocked_from is not null or v_seat.blocked_to is not null) then
    raise exception 'seat is blocked in that period';
  end if;
  select d.office_id into v_office_id from public.desks d where d.id = v_seat.desk_id;
  if exists (
    select 1 from public.reservations r
    where r.office_id = v_office_id
      and r.status in ('reserved','checked_in')
      and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
  ) then
    raise exception 'office is reserved as a whole in that period';
  end if;

  insert into public.reservations
    (workspace_id, seat_id, member_id, starts_at, ends_at, status, checked_in_at)
  values (
    p_workspace_id, p_seat_id, v_subject.id, p_starts_at, p_ends_at,
    case when p_action = 'check_in' then 'checked_in' else 'reserved' end,
    case when p_action = 'check_in' then now() end
  )
  returning id into v_id;
  perform public.assert_member_quota(v_subject.id, p_starts_at);
  return jsonb_build_object('action', p_action, 'reservation_id', v_id);
end;
$$;
revoke execute on function public.kiosk_act(uuid, text, text, uuid, timestamptz, timestamptz)
  from public, anon;

-- SPDX-License-Identifier: 0BSD
-- Per-member cap on SIMULTANEOUS open reservations. NOT YET applied to
-- the hosted reference project — the orchestrator applies it after review.
--
-- Each member can hold at most `max_active_reservations` open bookings at
-- once (status reserved/checked_in and not yet ended). NULL = unlimited,
-- the default. Owners and admins set the cap FOR OTHER members — never
-- for themselves, and members can never set their own: the number is a
-- governance knob, not a preference.
--
-- Enforcement is an AFTER INSERT trigger, not per-RPC guard calls: every
-- booking path (create_reservation, admin_create_reservation_for, series
-- instances, kiosk_act) inserts into reservations, so the trigger covers
-- them all — series instances beyond the cap land in the skipped report
-- exactly like closed days, and checking IN to an existing booking never
-- inserts, so it is never blocked.

alter table public.members
  add column max_active_reservations int
  check (max_active_reservations between 1 and 100);

-- 1. the setter: admin/owner, never self
create or replace function public.set_member_reservation_limit(
  p_member_id uuid, p_limit int
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_target public.members;
  v_caller public.members;
begin
  select * into v_target from public.members where id = p_member_id;
  if v_target.id is null then raise exception 'unknown member'; end if;
  select * into v_caller from public.members
    where workspace_id = v_target.workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_caller.id is null then
    raise exception 'not an admin of this workspace';
  end if;
  if v_caller.id = v_target.id then
    -- governance, not self-service: nobody tunes their own cap
    raise exception 'cannot set your own reservation limit';
  end if;
  if p_limit is not null and (p_limit < 1 or p_limit > 100) then
    raise exception 'limit must be between 1 and 100 (or null for none)';
  end if;
  update public.members set max_active_reservations = p_limit
    where id = p_member_id;
end;
$$;
revoke execute on function public.set_member_reservation_limit(uuid, int) from public, anon;

-- 2. the guard trigger
create or replace function public.enforce_reservation_limit()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_limit int;
  v_active int;
begin
  select max_active_reservations into v_limit
    from public.members where id = new.member_id;
  if v_limit is null then return new; end if;
  select count(*) into v_active from public.reservations r
    where r.member_id = new.member_id
      and r.status in ('reserved', 'checked_in')
      and r.ends_at > now();
  if v_active > v_limit then
    -- the client pins the substring 'reservation limit'
    raise exception 'reservation limit reached — at most % open reservations',
      v_limit;
  end if;
  return new;
end;
$$;
revoke execute on function public.enforce_reservation_limit() from public, anon, authenticated;

create trigger enforce_reservation_limit
after insert on public.reservations
for each row execute function public.enforce_reservation_limit();

-- SPDX-License-Identifier: 0BSD
-- Online-payment intents + settlement (docs/design/payments-integration.md
-- §6, now live). NOT YET applied to the hosted reference project — the
-- orchestrator applies it after review.
--
-- One row per provider order the create-payment-order Edge Function
-- starts. The provider webhook confirms the capture and calls
-- settle_online_payment with the SERVICE ROLE — idempotent on the order,
-- it marks the intent captured and posts a confirmed 'payment' ledger
-- credit. The capture is the proof of payment: no second-person
-- confirmation (that flow vouches for MANUAL claims).

create table public.payment_intents (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  member_id uuid not null references public.members(id) on delete cascade,
  provider text not null check (provider in ('paypal','stripe','mollie')),
  order_id text not null,
  capture_id text,
  period text not null check (period ~ '^\d{4}-\d{2}$'),
  amount_cents int not null check (amount_cents > 0),
  currency text not null default 'EUR',
  status text not null default 'created'
    check (status in ('created','captured','failed')),
  created_at timestamptz not null default now(),
  unique (provider, order_id)
);
create index payment_intents_member_idx on public.payment_intents (member_id);

alter table public.payment_intents enable row level security;
-- members see their own payment attempts (diagnostics); admins see all.
-- No client writes: rows are created by the Edge Function (service role)
-- and settled by the webhook (service role).
create policy payment_intents_select on public.payment_intents
  for select using (
    public.is_admin_of(workspace_id)
    or exists (select 1 from public.members m
                where m.id = member_id and m.user_id = auth.uid())
  );

-- Settlement: SERVICE ROLE ONLY (webhooks). Idempotent per order — a
-- webhook retry finds status='captured' and does nothing.
create or replace function public.settle_online_payment(
  p_provider text, p_order_id text, p_capture_id text, p_amount_cents int
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_intent public.payment_intents;
begin
  select * into v_intent from public.payment_intents
    where provider = p_provider and order_id = p_order_id
    for update;
  if v_intent.id is null then
    raise exception 'unknown payment intent %/%', p_provider, p_order_id;
  end if;
  if v_intent.status = 'captured' then return; end if;

  update public.payment_intents
    set status = 'captured', capture_id = p_capture_id
    where id = v_intent.id;

  insert into public.ledger_entries
    (workspace_id, member_id, kind, category, amount_cents, description, period)
  values (
    v_intent.workspace_id, v_intent.member_id, 'credit', 'payment',
    coalesce(p_amount_cents, v_intent.amount_cents),
    p_provider || ' online payment', v_intent.period
  );
end;
$$;
revoke execute on function public.settle_online_payment(text, text, text, int)
  from public, anon, authenticated;

-- Failure marker (webhook denial/expiry paths) — service role only.
create or replace function public.mark_payment_failed(
  p_provider text, p_order_id text
) returns void language plpgsql security definer set search_path = public as $$
begin
  update public.payment_intents set status = 'failed'
    where provider = p_provider and order_id = p_order_id
      and status = 'created';
end;
$$;
revoke execute on function public.mark_payment_failed(text, text)
  from public, anon, authenticated;

-- SPDX-License-Identifier: 0BSD
-- RFID/NFC badge credentials (kiosk slice 3). NOT YET applied to the
-- hosted reference project — the orchestrator applies it after review.
--
-- A member's physical RFID/NFC card becomes a badge: its stable tag UID
-- (normalized to lowercase hex, no separators) is the credential. The
-- server stores only the SHA-256 hash, exactly like QR badge tokens, and
-- kiosk_act needs NO change — the badge lookup is by hash regardless of
-- how the credential was presented (QR scan, wedge scanner, NFC tap).
--
-- Registration is admin-side ("tap the card once"): unlike QR badges the
-- credential comes from the physical tag, so the client sends the UID and
-- the server hashes it. A UID can be registered once across the
-- workspace (the unique token_hash); re-registering answers a dedicated
-- error the app maps.

-- 1. badge kind, for the manager UI and auditing
alter table public.member_badges
  add column kind text not null default 'qr' check (kind in ('qr','nfc'));

-- 2. register a physical tag as a member's badge
create or replace function public.register_nfc_badge(
  p_workspace_id uuid, p_member_id uuid, p_uid text, p_label text default ''
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_uid text;
  v_id uuid;
begin
  if not public.is_admin_of(p_workspace_id) then
    raise exception 'not an admin of this workspace';
  end if;
  if not exists (select 1 from public.members
                  where id = p_member_id and workspace_id = p_workspace_id
                    and status = 'active' and not is_kiosk) then
    raise exception 'unknown member';
  end if;
  -- Normalization contract (client mirrors it): lowercase hex, no
  -- separators. 4–10 tag-UID bytes → 8–20 hex chars.
  v_uid := lower(regexp_replace(coalesce(p_uid, ''), '[^0-9a-fA-F]', '', 'g'));
  if v_uid !~ '^[0-9a-f]{8,20}$' then
    raise exception 'invalid tag uid';
  end if;
  begin
    insert into public.member_badges
      (workspace_id, member_id, token_hash, label, kind)
    values (p_workspace_id, p_member_id, public.badge_token_hash(v_uid),
            coalesce(p_label, ''), 'nfc')
    returning id into v_id;
  exception when unique_violation then
    -- the client pins this substring
    raise exception 'tag already registered';
  end;
  return v_id;
end;
$$;
revoke execute on function public.register_nfc_badge(uuid, uuid, text, text) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- Per-workspace online-payment provider credentials, configurable from the
-- owner UI (previously only Edge-Function env secrets). NOT YET applied to
-- the hosted reference project — the orchestrator applies it after review.
--
-- SECURITY: secret keys (PayPal secret, Stripe key, Mollie key…) must never
-- be readable by any client. This table has RLS enabled with NO policies —
-- anon/authenticated are denied entirely. Only:
--   * SECURITY DEFINER RPCs below (owner-gated writes; status read-back that
--     returns key NAMES and non-secret fields, never the values), and
--   * the Edge Functions via the service role (which bypasses RLS),
-- ever touch it. Each community configures its OWN provider account, so a
-- leak is scoped to one workspace at worst — and the design prevents even
-- that. The Edge Functions read this table first and fall back to env, so
-- an existing CLI-secrets deployment keeps working.

create table public.payment_credentials (
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  provider text not null check (provider in ('paypal','stripe','mollie')),
  -- everything for the provider: secret keys + non-secret fields
  -- (return_url, env, webhook_id). Read only by the service role.
  config jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  primary key (workspace_id, provider)
);

alter table public.payment_credentials enable row level security;
-- Intentionally NO policies: deny-all to client roles.

-- The non-secret config fields a status read-back may echo back to the
-- owner UI. Everything else (secret, client_secret, api_key…) is a secret
-- and is only ever reported as PRESENT, never returned.
create or replace function public.payment_config_is_secret(p_key text)
returns boolean language sql immutable as $$
  select p_key not in ('return_url', 'env');
$$;

-- Owner-only: MERGE a provider's config. Non-blank fields overwrite;
-- blank/absent fields keep the existing value — so the owner can change
-- the return URL without re-typing secrets they can never read back. Use
-- clear_payment_provider to remove a provider entirely.
create or replace function public.set_payment_credentials(
  p_workspace_id uuid, p_provider text, p_config jsonb
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_clean jsonb;
begin
  if not public.is_owner_of(p_workspace_id) then
    raise exception 'not the owner of this workspace';
  end if;
  if p_provider not in ('paypal','stripe','mollie') then
    raise exception 'unknown provider';
  end if;
  -- drop null/blank entries (blank means "leave unchanged")
  select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) into v_clean
    from jsonb_each(coalesce(p_config, '{}'::jsonb))
    where value is not null and trim(both '"' from value::text) <> '';
  if v_clean = '{}'::jsonb then return; end if;

  insert into public.payment_credentials (workspace_id, provider, config, updated_at)
  values (p_workspace_id, p_provider, v_clean, now())
  on conflict (workspace_id, provider)
    do update set config = public.payment_credentials.config || v_clean,
                  updated_at = now();
end;
$$;
revoke execute on function public.set_payment_credentials(uuid, text, jsonb) from public, anon;

-- Owner-only: remove a provider's config entirely.
create or replace function public.clear_payment_provider(
  p_workspace_id uuid, p_provider text
) returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_owner_of(p_workspace_id) then
    raise exception 'not the owner of this workspace';
  end if;
  delete from public.payment_credentials
    where workspace_id = p_workspace_id and provider = p_provider;
end;
$$;
revoke execute on function public.clear_payment_provider(uuid, text) from public, anon;

-- Owner-only read-back for the config UI: per provider, whether it is
-- configured, its NON-SECRET fields, and the NAMES of the secret fields
-- that are set (never their values).
create or replace function public.payment_credentials_status(
  p_workspace_id uuid
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_result jsonb := '{}'::jsonb;
  v_row public.payment_credentials;
  v_public jsonb;
  v_secret_keys text[];
begin
  if not public.is_owner_of(p_workspace_id) then
    raise exception 'not the owner of this workspace';
  end if;
  for v_row in
    select * from public.payment_credentials where workspace_id = p_workspace_id
  loop
    -- non-secret fields, echoed back
    select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) into v_public
      from jsonb_each(v_row.config)
      where not public.payment_config_is_secret(key);
    -- names of the secret fields that are set
    select coalesce(array_agg(key), array[]::text[]) into v_secret_keys
      from jsonb_object_keys(v_row.config) key
      where public.payment_config_is_secret(key);
    v_result := v_result || jsonb_build_object(
      v_row.provider,
      jsonb_build_object(
        'configured', true,
        'public', v_public,
        'secret_keys', to_jsonb(v_secret_keys)
      )
    );
  end loop;
  return v_result;
end;
$$;
revoke execute on function public.payment_credentials_status(uuid) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- Wero as an online-payment provider. NOT YET applied to the hosted
-- reference project — the orchestrator applies it after review.
--
-- Wero (the European wallet) has no broadly-available direct merchant API,
-- so DesKilo offers it THROUGH Mollie, which lists Wero as a checkout
-- method. A 'wero' payment is a Mollie payment created with method='wero';
-- its config is a Mollie API key + return URL (Wero must be enabled in the
-- workspace's Mollie account). Settlement rides the existing Mollie webhook
-- — it now matches intents of provider 'mollie' OR 'wero'.

alter table public.payment_intents drop constraint payment_intents_provider_check;
alter table public.payment_intents add constraint payment_intents_provider_check
  check (provider in ('paypal','stripe','mollie','wero'));

alter table public.payment_credentials drop constraint payment_credentials_provider_check;
alter table public.payment_credentials add constraint payment_credentials_provider_check
  check (provider in ('paypal','stripe','mollie','wero'));

-- set_payment_credentials: allow the new provider (body = 0047 verbatim +
-- 'wero' in the guard).
create or replace function public.set_payment_credentials(
  p_workspace_id uuid, p_provider text, p_config jsonb
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_clean jsonb;
begin
  if not public.is_owner_of(p_workspace_id) then
    raise exception 'not the owner of this workspace';
  end if;
  if p_provider not in ('paypal','stripe','mollie','wero') then
    raise exception 'unknown provider';
  end if;
  select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) into v_clean
    from jsonb_each(coalesce(p_config, '{}'::jsonb))
    where value is not null and trim(both '"' from value::text) <> '';
  if v_clean = '{}'::jsonb then return; end if;

  insert into public.payment_credentials (workspace_id, provider, config, updated_at)
  values (p_workspace_id, p_provider, v_clean, now())
  on conflict (workspace_id, provider)
    do update set config = public.payment_credentials.config || v_clean,
                  updated_at = now();
end;
$$;
revoke execute on function public.set_payment_credentials(uuid, text, jsonb) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- Whole-level reservations. NOT YET applied to the hosted reference
-- project — the orchestrator applies it after review.
--
-- A level (floor) can be reserved/checked into as a whole, like an
-- office: the owner marks a level bookable and prices it per half-day.
-- WHO may book one for themselves is a per-member grant
-- (members.can_reserve_level, owner/admin-set, never self — the 0044
-- reservation-limit shape). Owners always assign level reservations to
-- members; admins do when the workspace enables the adminLevelAssign
-- feature (the adminSeatBlocking delegation idiom). The whole module
-- hides behind the levelBooking feature flag (default OFF).
--
-- Billing: a level reservation consumes half-day quota like any other
-- reservation, PLUS the level's price per distinct half-day — the
-- accessory-supplement shape, summed in member_statement v5.

-- 1. Level bookability + price.
alter table public.levels
  add column if not exists bookable_as_whole boolean not null default false,
  add column if not exists price_cents int not null default 0
    check (price_cents >= 0);

-- 2. Per-member grant.
alter table public.members
  add column if not exists can_reserve_level boolean not null default false;

create or replace function public.set_member_level_permission(
  p_member_id uuid, p_allowed boolean
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_subject public.members;
  v_actor public.members;
begin
  select * into v_subject from public.members where id = p_member_id;
  if v_subject.id is null then raise exception 'unknown member'; end if;
  select * into v_actor from public.members
    where workspace_id = v_subject.workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if v_actor.id = v_subject.id then
    raise exception 'cannot change your own level permission';
  end if;
  update public.members set can_reserve_level = p_allowed where id = p_member_id;
end;
$$;
revoke execute on function public.set_member_level_permission(uuid, boolean)
  from public, anon;

-- 3. Reservations may target a level: exactly one of seat/office/level.
alter table public.reservations
  add column if not exists level_id uuid references public.levels(id)
    on delete restrict;
alter table public.reservations drop constraint reservations_one_target;
alter table public.reservations add constraint reservations_one_target check (
  (case when seat_id is null then 0 else 1 end
   + case when office_id is null then 0 else 1 end
   + case when level_id is null then 0 else 1 end) = 1
);
alter table public.reservations add constraint reservations_level_no_overlap
  exclude using gist (
    level_id with =,
    tstzrange(starts_at, ends_at) with &&
  ) where (level_id is not null and status in ('reserved','checked_in'));

-- Helper: is the levelBooking feature on for this workspace? (Server
-- mirror of the client registry default: OFF unless explicitly true.)
create or replace function public.level_booking_enabled(p_workspace_id uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(w.feature_flags -> 'levelBooking' = to_jsonb(true), false)
    from public.workspaces w where w.id = p_workspace_id;
$$;
revoke execute on function public.level_booking_enabled(uuid) from public, anon;

-- Helper: any seat/office/level reservation overlapping the window
-- anywhere on this level? Used by the level path of every booking RPC.
create or replace function public.level_has_conflict(
  p_level_id uuid, p_starts_at timestamptz, p_ends_at timestamptz
) returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.reservations r
    left join public.seats s on s.id = r.seat_id
    left join public.desks d on d.id = s.desk_id
    left join public.offices o on o.id = coalesce(r.office_id, d.office_id)
    where r.status in ('reserved','checked_in')
      and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
      and (r.level_id = p_level_id or o.level_id = p_level_id)
  );
$$;
revoke execute on function public.level_has_conflict(uuid, timestamptz, timestamptz)
  from public, anon;

-- 4. create_reservation v4: 0031 body + the level target. The seat and
-- office paths additionally refuse when their level is reserved whole.
create or replace function public.create_reservation(
  p_workspace_id uuid,
  p_seat_id uuid,
  p_office_id uuid,
  p_starts_at timestamptz,
  p_ends_at timestamptz,
  p_check_in boolean default false,
  p_level_id uuid default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_seat public.seats;
  v_office_id uuid;
  v_level_id uuid;
  v_id uuid;
begin
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if (case when p_seat_id is null then 0 else 1 end
      + case when p_office_id is null then 0 else 1 end
      + case when p_level_id is null then 0 else 1 end) <> 1 then
    raise exception 'exactly one of seat, office or level required';
  end if;
  perform public.enforce_booking_rules(p_workspace_id, p_starts_at, p_ends_at, p_check_in);

  if p_seat_id is not null then
    select * into v_seat from public.seats
      where id = p_seat_id and workspace_id = p_workspace_id;
    if v_seat.id is null then raise exception 'unknown seat'; end if;
    if tstzrange(coalesce(v_seat.blocked_from, '-infinity'::timestamptz),
                 coalesce(v_seat.blocked_to, 'infinity'::timestamptz))
       && tstzrange(p_starts_at, p_ends_at)
       and (v_seat.blocked_from is not null or v_seat.blocked_to is not null) then
      raise exception 'seat is blocked in that period';
    end if;
    select d.office_id into v_office_id from public.desks d where d.id = v_seat.desk_id;
    if exists (
      select 1 from public.reservations r
      where r.office_id = v_office_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'office is reserved as a whole in that period';
    end if;
    select o.level_id into v_level_id from public.offices o where o.id = v_office_id;
    if exists (
      select 1 from public.reservations r
      where r.level_id = v_level_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'level is reserved as a whole in that period';
    end if;
  elsif p_office_id is not null then
    if not exists (
      select 1 from public.offices o
      where o.id = p_office_id and o.workspace_id = p_workspace_id
        and o.bookable_as_whole
    ) then
      raise exception 'office not bookable as a whole';
    end if;
    if exists (
      select 1 from public.reservations r
      join public.seats s on s.id = r.seat_id
      join public.desks d on d.id = s.desk_id
      where d.office_id = p_office_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'a seat in this office is already reserved in that period';
    end if;
    select o.level_id into v_level_id from public.offices o where o.id = p_office_id;
    if exists (
      select 1 from public.reservations r
      where r.level_id = v_level_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'level is reserved as a whole in that period';
    end if;
  else
    -- Level path: feature on, level bookable, member personally allowed.
    if not public.level_booking_enabled(p_workspace_id) then
      raise exception 'level booking is not enabled';
    end if;
    if not exists (
      select 1 from public.levels l
      where l.id = p_level_id and l.workspace_id = p_workspace_id
        and l.bookable_as_whole
    ) then
      raise exception 'level not bookable as a whole';
    end if;
    if not v_member.can_reserve_level then
      -- the client pins this substring
      raise exception 'not allowed to reserve a level';
    end if;
    if public.level_has_conflict(p_level_id, p_starts_at, p_ends_at) then
      raise exception 'the level has reservations in that period';
    end if;
  end if;

  insert into public.reservations
    (workspace_id, seat_id, office_id, level_id, member_id, starts_at, ends_at,
     status, checked_in_at)
  values (
    p_workspace_id, p_seat_id, p_office_id, p_level_id, v_member.id,
    p_starts_at, p_ends_at,
    case when p_check_in then 'checked_in' else 'reserved' end,
    case when p_check_in then now() end
  )
  returning id into v_id;
  perform public.assert_member_quota(v_member.id, p_starts_at);
  return v_id;
end;
$$;

-- 5. admin_create_reservation_for v3: 0031 body + optional level target.
-- Owners assign level reservations freely; admins need the
-- adminLevelAssign feature. The SUBJECT needs no personal grant — the
-- assignment right belongs to the actor. Confirmation protocol
-- unchanged: the created event parks pending for the subject.
create or replace function public.admin_create_reservation_for(
  p_workspace_id uuid,
  p_subject_member_id uuid,
  p_seat_id uuid,
  p_starts_at timestamptz,
  p_ends_at timestamptz,
  p_level_id uuid default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_res_id uuid;
  v_event_id uuid;
begin
  select * into v_actor from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if not exists (
    select 1 from public.members
    where id = p_subject_member_id and workspace_id = p_workspace_id and status = 'active'
  ) then raise exception 'unknown subject member'; end if;
  if (p_seat_id is null) = (p_level_id is null) then
    raise exception 'exactly one of seat or level required';
  end if;
  perform public.enforce_booking_rules(p_workspace_id, p_starts_at, p_ends_at);

  if p_level_id is not null then
    if not public.level_booking_enabled(p_workspace_id) then
      raise exception 'level booking is not enabled';
    end if;
    if not v_actor.is_owner and not coalesce(
      (select w.feature_flags -> 'adminLevelAssign' = to_jsonb(true)
         from public.workspaces w where w.id = p_workspace_id), false) then
      raise exception 'admins may not assign level reservations here';
    end if;
    if not exists (
      select 1 from public.levels l
      where l.id = p_level_id and l.workspace_id = p_workspace_id
        and l.bookable_as_whole
    ) then
      raise exception 'level not bookable as a whole';
    end if;
    if public.level_has_conflict(p_level_id, p_starts_at, p_ends_at) then
      raise exception 'the level has reservations in that period';
    end if;
  else
    perform public.assert_seat_not_blocked(p_seat_id, p_starts_at, p_ends_at);
  end if;

  insert into public.reservations
    (workspace_id, seat_id, level_id, member_id, starts_at, ends_at, status)
  values (p_workspace_id, p_seat_id, p_level_id, p_subject_member_id,
          p_starts_at, p_ends_at, 'reserved')
  returning id into v_res_id;
  perform public.assert_member_quota(p_subject_member_id, p_starts_at);

  update public.events set actor_member_id = v_actor.id, status = 'pending'
    where reservation_id = v_res_id and action = 'created';

  select id into v_event_id from public.events
    where reservation_id = v_res_id and action = 'created';
  return v_event_id;
end;
$$;

-- 6. kiosk_act v2: the wall tablet books a LEVEL too — the member taps
-- their RFID/NFC card or scans/types the badge exactly like for a seat.
-- Signature grows a parameter → drop-and-recreate.
drop function if exists public.kiosk_act(uuid, text, text, uuid, timestamptz, timestamptz);
create or replace function public.kiosk_act(
  p_workspace_id uuid,
  p_badge_token text,
  p_action text,             -- 'reserve' | 'check_in' | 'check_out'
  p_seat_id uuid default null,
  p_starts_at timestamptz default null,
  p_ends_at timestamptz default null,
  p_level_id uuid default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_kiosk public.members;
  v_badge public.member_badges;
  v_subject public.members;
  v_seat public.seats;
  v_office_id uuid;
  v_res public.reservations;
  v_id uuid;
begin
  select * into v_kiosk from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and is_kiosk;
  if v_kiosk.id is null then raise exception 'not a kiosk of this workspace'; end if;

  select * into v_badge from public.member_badges
    where workspace_id = p_workspace_id
      and token_hash = public.badge_token_hash(p_badge_token)
      and revoked_at is null;
  if v_badge.id is null then
    raise exception 'badge not recognized';
  end if;
  select * into v_subject from public.members
    where id = v_badge.member_id and status = 'active';
  if v_subject.id is null then raise exception 'badge member not active'; end if;

  if p_action = 'check_out' then
    select r.* into v_res from public.reservations r
      where r.member_id = v_subject.id and r.status = 'checked_in'
        and (p_seat_id is null or r.seat_id = p_seat_id)
        and (p_level_id is null or r.level_id = p_level_id)
      order by r.checked_in_at desc limit 1;
    if v_res.id is null then raise exception 'not checked in'; end if;
    update public.reservations
      set status = 'completed', checked_out_at = now(),
          ends_at = least(ends_at, now())
      where id = v_res.id;
    return jsonb_build_object('action', 'check_out', 'reservation_id', v_res.id);
  end if;

  if p_action not in ('reserve', 'check_in') then
    raise exception 'unknown kiosk action';
  end if;
  if (p_seat_id is null) = (p_level_id is null)
     or p_starts_at is null or p_ends_at is null then
    raise exception 'seat or level, and window required';
  end if;

  if p_level_id is not null then
    -- Level path: same gates as create_reservation — feature, bookable,
    -- the badge member's personal grant, no conflicts on the level.
    if not public.level_booking_enabled(p_workspace_id) then
      raise exception 'level booking is not enabled';
    end if;
    if not exists (
      select 1 from public.levels l
      where l.id = p_level_id and l.workspace_id = p_workspace_id
        and l.bookable_as_whole
    ) then
      raise exception 'level not bookable as a whole';
    end if;
    if not v_subject.can_reserve_level then
      raise exception 'not allowed to reserve a level';
    end if;

    if p_action = 'check_in' then
      select r.* into v_res from public.reservations r
        where r.member_id = v_subject.id and r.level_id = p_level_id
          and r.status = 'reserved'
          and r.starts_at <= now() and r.ends_at > now()
        limit 1;
      if v_res.id is not null then
        update public.reservations
          set status = 'checked_in', checked_in_at = now()
          where id = v_res.id;
        return jsonb_build_object('action', 'check_in', 'reservation_id', v_res.id);
      end if;
    end if;

    perform public.enforce_booking_rules(
      p_workspace_id, p_starts_at, p_ends_at, p_action = 'check_in');
    if public.level_has_conflict(p_level_id, p_starts_at, p_ends_at) then
      raise exception 'the level has reservations in that period';
    end if;

    insert into public.reservations
      (workspace_id, level_id, member_id, starts_at, ends_at, status, checked_in_at)
    values (
      p_workspace_id, p_level_id, v_subject.id, p_starts_at, p_ends_at,
      case when p_action = 'check_in' then 'checked_in' else 'reserved' end,
      case when p_action = 'check_in' then now() end
    )
    returning id into v_id;
    perform public.assert_member_quota(v_subject.id, p_starts_at);
    return jsonb_build_object('action', p_action, 'reservation_id', v_id);
  end if;

  select * into v_seat from public.seats
    where id = p_seat_id and workspace_id = p_workspace_id;
  if v_seat.id is null then raise exception 'unknown seat'; end if;

  if p_action = 'check_in' then
    select r.* into v_res from public.reservations r
      where r.member_id = v_subject.id and r.seat_id = p_seat_id
        and r.status = 'reserved'
        and r.starts_at <= now() and r.ends_at > now()
      limit 1;
    if v_res.id is not null then
      update public.reservations
        set status = 'checked_in', checked_in_at = now()
        where id = v_res.id;
      return jsonb_build_object('action', 'check_in', 'reservation_id', v_res.id);
    end if;
  end if;

  perform public.enforce_booking_rules(
    p_workspace_id, p_starts_at, p_ends_at, p_action = 'check_in');
  if tstzrange(coalesce(v_seat.blocked_from, '-infinity'::timestamptz),
               coalesce(v_seat.blocked_to, 'infinity'::timestamptz))
     && tstzrange(p_starts_at, p_ends_at)
     and (v_seat.blocked_from is not null or v_seat.blocked_to is not null) then
    raise exception 'seat is blocked in that period';
  end if;
  select d.office_id into v_office_id from public.desks d where d.id = v_seat.desk_id;
  if exists (
    select 1 from public.reservations r
    where r.office_id = v_office_id
      and r.status in ('reserved','checked_in')
      and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
  ) then
    raise exception 'office is reserved as a whole in that period';
  end if;
  if exists (
    select 1 from public.reservations r
    where r.level_id = (select o.level_id from public.offices o where o.id = v_office_id)
      and r.status in ('reserved','checked_in')
      and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
  ) then
    raise exception 'level is reserved as a whole in that period';
  end if;

  insert into public.reservations
    (workspace_id, seat_id, member_id, starts_at, ends_at, status, checked_in_at)
  values (
    p_workspace_id, p_seat_id, v_subject.id, p_starts_at, p_ends_at,
    case when p_action = 'check_in' then 'checked_in' else 'reserved' end,
    case when p_action = 'check_in' then now() end
  )
  returning id into v_id;
  perform public.assert_member_quota(v_subject.id, p_starts_at);
  return jsonb_build_object('action', p_action, 'reservation_id', v_id);
end;
$$;
revoke execute on function public.kiosk_act(uuid, text, text, uuid, timestamptz, timestamptz, uuid)
  from public, anon;

-- 7. member_statement v5: v4 (0041) verbatim + the level price — the
-- accessory-supplement shape: price × distinct (level, day, slot).
-- Additions marked "#level". Balance subtracts the level supplement.
create or replace function public.member_statement(
  p_member_id uuid,
  p_period text
) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_member public.members;
  v_caller_is_admin boolean;
  v_band public.fee_bands;
  v_tz text;
  v_open int[];
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_month_first date;
  v_open_days int;
  v_pct int;
  v_included int;
  v_used int;
  v_base int := 0;
  v_overage int := 0;
  v_overage_rate int := 0;
  v_credits int;
  v_extra_half_days int := 0;
  v_supp_on boolean := false;
  v_supp_since timestamptz;
  v_supplement int := 0;
  v_granted int := 0;
  v_cap int := 0;
  v_remaining int := 0;
  -- #level
  v_level_supplement int := 0;
begin
  select * into v_member from public.members where id = p_member_id;
  if v_member.id is null then raise exception 'unknown member'; end if;
  v_caller_is_admin := public.is_admin_of(v_member.workspace_id);
  if not v_caller_is_admin and not exists (
    select 1 from public.members m
    where m.id = p_member_id and m.user_id = auth.uid()
  ) then
    raise exception 'not your statement';
  end if;

  select timezone,
         coalesce((select array_agg(x::int)
                     from jsonb_array_elements_text(booking_rules->'open_weekdays') x),
                  array[1,2,3,4,5]),
         coalesce(feature_flags -> 'accessorySupplements' = to_jsonb(true), false),
         accessory_supplements_since
    into v_tz, v_open, v_supp_on, v_supp_since
    from public.workspaces where id = v_member.workspace_id;
  v_period_start := to_timestamp(p_period || '-01', 'YYYY-MM-DD') at time zone v_tz;
  v_period_end := (to_timestamp(p_period || '-01', 'YYYY-MM-DD') + interval '1 month') at time zone v_tz;
  v_month_first := to_date(p_period || '-01', 'YYYY-MM-DD');

  v_pct := coalesce(v_member.subscription_pct, 100);
  select * into v_band from public.fee_bands
    where workspace_id = v_member.workspace_id
      and from_pct < v_pct and v_pct <= to_pct;
  if v_band.id is not null then
    v_base := v_band.fee_cents;
    v_overage_rate := v_band.overage_fee_cents;
  end if;

  select count(*) into v_open_days
  from generate_series(v_month_first,
                       (v_month_first + interval '1 month' - interval '1 day')::date,
                       interval '1 day') d
  where extract(isodow from d)::int = any(v_open)
    and not exists (select 1 from public.closure_days c
                     where c.workspace_id = v_member.workspace_id and c.day = d::date);
  v_included := ceil(v_open_days * 2 * v_pct / 100.0)::int;

  select count(distinct (date_trunc('day', r.starts_at at time zone v_tz)::date, s.slot))
  into v_used
  from public.reservations r
  cross join lateral (
    select case when extract(hour from r.starts_at at time zone v_tz) < 13 then 0 else 1 end as slot
  ) s
  where r.member_id = p_member_id
    and r.status in ('reserved','checked_in','completed')
    and r.starts_at >= v_period_start and r.starts_at < v_period_end;

  v_extra_half_days := greatest(0, v_used - v_included);
  v_overage := v_extra_half_days * v_overage_rate;

  select coalesce(sum(half_days), 0) into v_granted from public.quota_extensions
    where member_id = p_member_id and period = p_period;
  v_cap := v_included + v_granted;
  v_remaining := greatest(0, v_cap - v_used);

  if v_supp_on and v_supp_since is not null then
    select coalesce(sum(seat_supp.total_cents), 0) into v_supplement
    from (
      select distinct
        r.seat_id,
        date_trunc('day', r.starts_at at time zone v_tz)::date as day,
        case when extract(hour from r.starts_at at time zone v_tz) < 13 then 0 else 1 end as slot
      from public.reservations r
      where r.member_id = p_member_id
        and r.seat_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= greatest(v_period_start, v_supp_since)
        and r.starts_at < v_period_end
    ) hd
    join (
      select sa.seat_id, sum(a.supplement_cents)::int as total_cents
      from public.seat_accessories sa
      join public.accessories a on a.id = sa.accessory_id
      where a.active and a.supplement_cents > 0
      group by sa.seat_id
    ) seat_supp on seat_supp.seat_id = hd.seat_id;
  end if;

  -- #level: price × distinct half-days per reserved level. Priced level
  -- reservations only exist while the feature is on, so no extra gate.
  select coalesce(sum(l.price_cents), 0) into v_level_supplement
  from (
    select distinct
      r.level_id,
      date_trunc('day', r.starts_at at time zone v_tz)::date as day,
      case when extract(hour from r.starts_at at time zone v_tz) < 13 then 0 else 1 end as slot
    from public.reservations r
    where r.member_id = p_member_id
      and r.level_id is not null
      and r.status in ('reserved','checked_in','completed')
      and r.starts_at >= v_period_start and r.starts_at < v_period_end
  ) lh
  join public.levels l on l.id = lh.level_id;

  select coalesce(sum(case when kind = 'credit' then amount_cents else -amount_cents end), 0)
  into v_credits
  from public.ledger_entries
  where member_id = p_member_id and period = p_period;

  return jsonb_build_object(
    'period', p_period,
    'subscription_pct', v_pct,
    'fee_cents', v_base,
    'included_half_days', v_included,
    'open_days', v_open_days,
    'used_half_days', v_used,
    'extra_half_days', v_extra_half_days,
    'overage_cents', v_overage,
    'accessory_supplement_cents', v_supplement,
    -- #level
    'level_supplement_cents', v_level_supplement,
    'credits_cents', v_credits,
    'balance_cents',
      v_credits - v_base - v_overage - v_supplement - v_level_supplement,
    'overage_policy', coalesce(v_member.overage_policy, 'blocked'),
    'overage_rate_cents', v_overage_rate,
    'granted_half_days', v_granted,
    'remaining_half_days', v_remaining
  );
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- Personal invitations (#319): an invitation code is usable ONLY once,
-- only until it expires, and only for the role it was minted with — a
-- forwarded admin code must not mint admins forever. Replaces the static
-- workspace-wide admin secret of 0030:
--   * workspaces.invite_code stays the open member-level walk-in handle
--     (the printed on-site QR and the human-readable workspace ID).
--   * workspace_admin_invites is DROPPED — the static admin code is no
--     longer honored anywhere.
--   * Admin access is now granted exclusively through a personal
--     invitation minted by an owner (create_invitation), or by an owner
--     editing the member row (members_update_owner RLS, 0002).

create table public.invitations (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  code text not null unique default public.gen_invite_code(),
  is_admin boolean not null default false,
  invited_first_name text not null default '' check (char_length(invited_first_name) <= 120),
  invited_last_name text not null default '' check (char_length(invited_last_name) <= 120),
  created_by uuid not null,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default now() + interval '14 days',
  redeemed_by uuid,
  redeemed_at timestamptz
);

alter table public.invitations enable row level security;

-- Workspace admins see their workspace's invitations (pending + redeemed,
-- for an eventual invite-audit surface). No client write policies on
-- purpose (default-deny) — rows are minted and redeemed by the RPCs only.
create policy invitations_select on public.invitations
  for select using (public.is_admin_of(workspace_id));

-- create_invitation: admins mint member invites; ONLY owners mint admin
-- invites (mirrors 0030, where the admin secret was owner-readable).
create or replace function public.create_invitation(
  p_workspace_id uuid,
  p_is_admin boolean,
  p_first_name text default '',
  p_last_name text default ''
) returns text language plpgsql security definer set search_path = public as $$
declare v_code text;
begin
  if p_is_admin then
    if not public.is_owner_of(p_workspace_id) then
      raise exception 'only owners may invite admins';
    end if;
  elsif not public.is_admin_of(p_workspace_id) then
    raise exception 'only admins may invite members';
  end if;
  insert into public.invitations
    (workspace_id, is_admin, invited_first_name, invited_last_name, created_by)
  values
    (p_workspace_id, p_is_admin,
     left(coalesce(p_first_name, ''), 120),
     left(coalesce(p_last_name, ''), 120),
     auth.uid())
  returning code into v_code;
  return v_code;
end;
$$;

revoke execute on function
  public.create_invitation(uuid, boolean, text, text) from public, anon;

-- join_workspace: the workspace member code stays an open user-level
-- join; otherwise the code must be an unredeemed, unexpired personal
-- invitation, claimed ATOMICALLY (the UPDATE is the single-use latch —
-- two concurrent redeems race on the row lock and the loser matches
-- nothing). The invitation row decides the role; is_owner is never
-- touched.
create or replace function public.join_workspace(p_invite_code text)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  ws_id uuid;
  v_code text;
  v_admin boolean := false;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  v_code := upper(trim(p_invite_code));
  select id into ws_id from public.workspaces where invite_code = v_code;
  if ws_id is null then
    update public.invitations
       set redeemed_by = auth.uid(), redeemed_at = now()
     where code = v_code
       and redeemed_at is null
       and expires_at > now()
    returning workspace_id, is_admin into ws_id, v_admin;
  end if;
  if ws_id is null then raise exception 'invalid invite code'; end if;
  insert into public.members (workspace_id, user_id, is_admin)
  values (ws_id, auth.uid(), v_admin)
  on conflict (workspace_id, user_id) do update
    set status = 'active',
        is_admin = public.members.is_admin or excluded.is_admin
    where public.members.status = 'exited' or excluded.is_admin;
  return ws_id;
end;
$$;

-- The static admin secret dies with its table. create_workspace (0030)
-- also minted a row here — recreate it without that insert.
create or replace function public.create_workspace(
  p_name text, p_country_code text, p_currency_code text, p_timezone text
) returns uuid language plpgsql security definer set search_path = public as $$
declare ws_id uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  insert into public.workspaces (name, country_code, currency_code, timezone, created_by)
  values (p_name, upper(p_country_code), upper(p_currency_code), p_timezone, auth.uid())
  returning id into ws_id;
  insert into public.members (workspace_id, user_id, is_admin, is_owner)
  values (ws_id, auth.uid(), true, true);
  return ws_id;
end;
$$;

-- set_workspace_code (0030) checked collisions against the admin table;
-- now it must not collide with any personal invitation instead.
create or replace function public.set_workspace_code(
  p_workspace_id uuid,
  p_code text
) returns text language plpgsql security definer set search_path = public as $$
declare v_code text;
begin
  if not public.is_owner_of(p_workspace_id) then
    raise exception 'only owners may change the workspace ID';
  end if;
  v_code := upper(trim(p_code));
  if v_code !~ '^[A-Z0-9]{4,20}$' then
    raise exception 'workspace ID must be 4-20 letters or digits';
  end if;
  if exists (select 1 from public.invitations where code = v_code) then
    raise exception 'workspace ID already taken';
  end if;
  begin
    update public.workspaces set invite_code = v_code where id = p_workspace_id;
  exception when unique_violation then
    raise exception 'workspace ID already taken';
  end;
  return v_code;
end;
$$;

drop table public.workspace_admin_invites;

-- SPDX-License-Identifier: 0BSD
-- New-member validation. Applied to the hosted reference project on
-- 2026-07-22 (an interim draft named 0051_single_use_invites_member_
-- validation carried parts of this earlier the same day and was
-- superseded by 0051_personal_invitations + this file; its leftover
-- invite_tokens table is dropped below).
--
-- Joining is no longer instant (field request): every join lands as a
-- PENDING membership. The new member sees only the workspace name (the
-- waiting screen) until owner/admins confirm — through the members
-- screen's quick decision or the SAME validation quorum as payments,
-- expenses and role changes (events type 'member_join', configurable
-- per workspace in Validation rules). Rejection exits the membership.

-- ---------------------------------------------------------------------
-- 0. Interim cleanup (staging-only artifacts of the superseded draft).
-- ---------------------------------------------------------------------
drop function if exists public.mint_invite_token(uuid, text);
drop table if exists public.invite_tokens;

-- ---------------------------------------------------------------------
-- 1. Pending membership status + visibility carve-outs.
-- ---------------------------------------------------------------------
alter table public.members drop constraint members_status_check;
alter table public.members add constraint members_status_check
  check (status in ('active','paused','pending','exited'));

-- Pending members are NOT members yet: no plan, no directory, no money.
create or replace function public.is_member_of(ws uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.members m
    where m.workspace_id = ws and m.user_id = auth.uid()
      and m.status in ('active','paused')
  );
$$;

create or replace function public.shares_workspace_with(other uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1
    from public.members me
    join public.members them on me.workspace_id = them.workspace_id
    where me.user_id = auth.uid() and them.user_id = other
      and me.status in ('active','paused')
      and them.status in ('active','paused')
  );
$$;

-- …but they may see the workspace's NAME (the waiting screen) and their
-- OWN membership row (status detection).
drop policy if exists workspaces_select_pending on public.workspaces;
create policy workspaces_select_pending on public.workspaces
  for select using (exists (
    select 1 from public.members m
    where m.workspace_id = workspaces.id and m.user_id = auth.uid()
      and m.status = 'pending'
  ));
drop policy if exists members_select_self on public.members;
create policy members_select_self on public.members
  for select using (user_id = auth.uid());

-- ---------------------------------------------------------------------
-- 2. The member_join event type.
-- ---------------------------------------------------------------------
alter table public.events drop constraint events_type_check;
alter table public.events add constraint events_type_check
  check (type in ('reservation','payment','expense','adjustment',
                  'service_charge','quota','role_change','member_join'));

-- ---------------------------------------------------------------------
-- 3. join_workspace v4: body = 0051 (personal invitations, atomic
--    redeem) + every join lands PENDING with a member_join event.
-- ---------------------------------------------------------------------
create or replace function public.join_workspace(p_invite_code text)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  ws_id uuid;
  v_code text;
  v_admin boolean := false;
  v_member_id uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  v_code := upper(trim(p_invite_code));
  select id into ws_id from public.workspaces where invite_code = v_code;
  if ws_id is null then
    update public.invitations
       set redeemed_by = auth.uid(), redeemed_at = now()
     where code = v_code
       and redeemed_at is null
       and expires_at > now()
    returning workspace_id, is_admin into ws_id, v_admin;
  end if;
  if ws_id is null then raise exception 'invalid invite code'; end if;

  -- Every join is PENDING until the validators confirm (re-joins of
  -- exited members included); active/paused members re-joining keep
  -- their standing.
  insert into public.members (workspace_id, user_id, is_admin, status)
  values (ws_id, auth.uid(), v_admin, 'pending')
  on conflict (workspace_id, user_id) do update
    set status = case when public.members.status = 'exited'
                      then 'pending' else public.members.status end,
        is_admin = public.members.is_admin or excluded.is_admin
  returning id into v_member_id;

  if exists (select 1 from public.members
              where id = v_member_id and status = 'pending')
     and not exists (
       select 1 from public.events
       where subject_member_id = v_member_id
         and type = 'member_join' and status = 'pending') then
    insert into public.events
      (workspace_id, type, action, actor_member_id, subject_member_id,
       payload, status)
    values (ws_id, 'member_join', 'submitted', v_member_id, v_member_id,
            jsonb_build_object('as_admin', v_admin), 'pending');
  end if;
  return ws_id;
end;
$$;

-- ---------------------------------------------------------------------
-- 4. respond_to_event: + the member_join branches (confirm → active,
--    reject → exited). Body = 0035 verbatim otherwise.
-- ---------------------------------------------------------------------
create or replace function public.respond_to_event(
  p_event_id uuid,
  p_accept boolean
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_event public.events;
  v_caller public.members;
  v_policy record;
  v_subject_decides boolean;
  v_in_pool boolean;
  v_pool_size int;
  v_required int;
  v_accepts int;
  v_subject_ok boolean;
  v_owner_ok boolean;
begin
  select e.* into v_event from public.events e where e.id = p_event_id;
  if v_event.id is null then raise exception 'unknown event'; end if;
  if v_event.status <> 'pending' then raise exception 'already decided'; end if;

  select m.* into v_caller from public.members m
    where m.workspace_id = v_event.workspace_id and m.user_id = auth.uid()
      and m.status = 'active';
  if v_caller.id is null then raise exception 'not a member'; end if;
  if exists (select 1 from public.event_decisions d
              where d.event_id = p_event_id and d.member_id = v_caller.id) then
    raise exception 'you already decided this event';
  end if;

  select * into v_policy from public.validation_policies
    where workspace_id = v_event.workspace_id and event_type = v_event.type;
  if v_policy is null then
    select * into v_policy from public.validation_policies
      where workspace_id = v_event.workspace_id and event_type is null;
  end if;
  if v_policy is null then
    select null::uuid as id, v_event.workspace_id as workspace_id,
           null::text as event_type, 1 as required_count,
           true as admins_may_validate, '{}'::uuid[] as eligible_admin_ids,
           false as owner_required
      into v_policy;
  end if;

  v_subject_decides := v_event.type = 'reservation'
    or (v_event.type in ('payment','service_charge')
        and v_event.actor_member_id <> v_event.subject_member_id);

  select count(*) into v_pool_size from public.members m
    where m.workspace_id = v_event.workspace_id and m.status = 'active'
      and m.id not in (v_event.actor_member_id, v_event.subject_member_id)
      and (m.is_owner or (m.is_admin and v_policy.admins_may_validate
           and (cardinality(v_policy.eligible_admin_ids) = 0
                or m.id = any(v_policy.eligible_admin_ids))));

  v_in_pool := (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate
                and (cardinality(v_policy.eligible_admin_ids) = 0
                     or v_caller.id = any(v_policy.eligible_admin_ids))))
    and (v_caller.id <> v_event.subject_member_id
         or (not v_subject_decides and v_pool_size = 0))
    and (v_caller.id <> v_event.actor_member_id or v_pool_size = 0);
  if v_pool_size = 0 and (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate)) then
    v_pool_size := 1;
  end if;

  if v_subject_decides and v_caller.id = v_event.subject_member_id then
    null;
  elsif v_in_pool then
    null;
  else
    raise exception 'you are not an eligible validator for this event';
  end if;

  insert into public.event_decisions (event_id, member_id, decision)
  values (p_event_id, v_caller.id, case when p_accept then 'accept' else 'reject' end);

  if not p_accept then
    update public.events set status = 'rejected', decided_at = now()
      where id = p_event_id;
    if v_event.reservation_id is not null then
      update public.reservations set status = 'cancelled'
        where id = v_event.reservation_id and status in ('reserved','checked_in');
    end if;
    if v_event.type = 'member_join' then
      -- a refused join exits the pending membership
      update public.members set status = 'exited'
        where id = v_event.subject_member_id and status = 'pending';
    end if;
    return;
  end if;

  select count(*) into v_accepts from public.event_decisions
    where event_id = p_event_id and decision = 'accept';
  v_required := greatest(1, least(v_policy.required_count,
    v_pool_size + case when v_subject_decides then 1 else 0 end));
  v_subject_ok := not v_subject_decides or exists (
    select 1 from public.event_decisions d
    where d.event_id = p_event_id and d.decision = 'accept'
      and d.member_id = v_event.subject_member_id);
  v_owner_ok := not v_policy.owner_required or exists (
    select 1 from public.event_decisions d
    join public.members m on m.id = d.member_id
    where d.event_id = p_event_id and d.decision = 'accept' and m.is_owner);

  if v_accepts >= v_required and v_subject_ok and v_owner_ok then
    update public.events set status = 'confirmed', decided_at = now()
      where id = p_event_id;

    if v_event.type in ('payment','expense') then
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description, period, event_id)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'credit',
        case when v_event.type = 'payment' then 'payment' else 'expense' end,
        (v_event.payload->>'amount_cents')::int,
        coalesce(v_event.payload->>'note', ''),
        to_char(now(), 'YYYY-MM'),
        v_event.id
      );
    elsif v_event.type = 'service_charge' then
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description, period, event_id)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'charge', 'service',
        (v_event.payload->>'amount_cents')::int,
        (v_event.payload->>'name') || ' x' || (v_event.payload->>'quantity'),
        coalesce(v_event.payload->>'period', to_char(now(), 'YYYY-MM')),
        v_event.id
      );
    elsif v_event.type = 'quota' then
      insert into public.quota_extensions
        (workspace_id, member_id, period, half_days, event_id)
      values (
        v_event.workspace_id, v_event.subject_member_id,
        v_event.payload->>'period',
        (v_event.payload->>'half_days')::int,
        v_event.id
      );
    elsif v_event.type = 'role_change' then
      update public.members
        set is_admin = (v_event.payload->>'make_admin')::boolean
        where id = v_event.subject_member_id;
    elsif v_event.type = 'member_join' then
      -- the validated welcome: the pending membership becomes active
      update public.members set status = 'active'
        where id = v_event.subject_member_id and status = 'pending';
    end if;
  end if;
end;
$$;
revoke execute on function public.respond_to_event(uuid, boolean) from public, anon;

-- ---------------------------------------------------------------------
-- 5. Owner/admin quick decision from the members screen (the #107-style
--    explicit override next to the quorum path).
-- ---------------------------------------------------------------------
create or replace function public.decide_member_join(
  p_member_id uuid, p_approve boolean
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_subject public.members;
  v_actor public.members;
begin
  select * into v_subject from public.members where id = p_member_id;
  if v_subject.id is null then raise exception 'unknown member'; end if;
  if v_subject.status <> 'pending' then
    raise exception 'member is not pending';
  end if;
  select * into v_actor from public.members
    where workspace_id = v_subject.workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;

  update public.members
    set status = case when p_approve then 'active' else 'exited' end
    where id = p_member_id;
  update public.events
    set status = case when p_approve then 'confirmed' else 'rejected' end,
        decided_at = now()
    where subject_member_id = p_member_id
      and type = 'member_join' and status = 'pending';
end;
$$;
revoke execute on function public.decide_member_join(uuid, boolean) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- Self-service badges. NOT YET applied to the hosted reference project —
-- the orchestrator applies it after review.
--
-- A member manages their OWN kiosk credentials (field request): mint the
-- printable QR badge and register their RFID/NFC card themselves, from
-- Settings — no admin needed. Bodies mirror the admin RPCs (0043/0046)
-- with the subject fixed to the caller's own active membership; the
-- admin paths stay untouched.

create or replace function public.issue_my_badge(
  p_workspace_id uuid, p_label text default ''
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_token text;
  v_id uuid;
begin
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and not is_kiosk;
  if v_member.id is null then raise exception 'not an active member'; end if;
  v_token := encode(extensions.gen_random_bytes(32), 'hex');
  insert into public.member_badges (workspace_id, member_id, token_hash, label)
  values (p_workspace_id, v_member.id, public.badge_token_hash(v_token),
          coalesce(p_label, ''))
  returning id into v_id;
  return jsonb_build_object('badge_id', v_id, 'token', v_token);
end;
$$;
revoke execute on function public.issue_my_badge(uuid, text) from public, anon;

create or replace function public.register_my_nfc_badge(
  p_workspace_id uuid, p_uid text, p_label text default ''
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_uid text;
  v_id uuid;
begin
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and not is_kiosk;
  if v_member.id is null then raise exception 'not an active member'; end if;
  -- Normalization contract (0046): lowercase hex, no separators.
  v_uid := lower(regexp_replace(coalesce(p_uid, ''), '[^0-9a-fA-F]', '', 'g'));
  if v_uid !~ '^[0-9a-f]{8,20}$' then
    raise exception 'invalid tag uid';
  end if;
  begin
    insert into public.member_badges
      (workspace_id, member_id, token_hash, label, kind)
    values (p_workspace_id, v_member.id, public.badge_token_hash(v_uid),
            coalesce(p_label, ''), 'nfc')
    returning id into v_id;
  exception when unique_violation then
    -- the client pins this substring
    raise exception 'tag already registered';
  end;
  return v_id;
end;
$$;
revoke execute on function public.register_my_nfc_badge(uuid, text, text)
  from public, anon;

-- Revoke MY badge: only badges of the caller's own membership.
create or replace function public.revoke_my_badge(p_badge_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare v_count int;
begin
  update public.member_badges b
    set revoked_at = now()
    where b.id = p_badge_id and b.revoked_at is null
      and exists (select 1 from public.members m
                   where m.id = b.member_id and m.user_id = auth.uid());
  get diagnostics v_count = row_count;
  if v_count = 0 then raise exception 'unknown badge'; end if;
end;
$$;
revoke execute on function public.revoke_my_badge(uuid) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- Kiosk identify. NOT YET applied to the hosted reference project — the
-- orchestrator applies it after review.
--
-- The confirm-step flow (field request): after the badge/QR is read the
-- kiosk CLOSES the readers and shows a summary — "«name», check in on
-- A1, 09:00–13:00 — Confirm / Reject" — before anything happens.
-- kiosk_identify resolves a badge to its member's display name WITHOUT
-- acting; the confirmed action still runs through kiosk_act unchanged.

create or replace function public.kiosk_identify(
  p_workspace_id uuid, p_badge_token text
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_kiosk public.members;
  v_badge public.member_badges;
  v_subject public.members;
  v_name text;
begin
  select * into v_kiosk from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and is_kiosk;
  if v_kiosk.id is null then raise exception 'not a kiosk of this workspace'; end if;

  select * into v_badge from public.member_badges
    where workspace_id = p_workspace_id
      and token_hash = public.badge_token_hash(p_badge_token)
      and revoked_at is null;
  if v_badge.id is null then
    -- the client pins this substring (same as kiosk_act)
    raise exception 'badge not recognized';
  end if;
  select * into v_subject from public.members
    where id = v_badge.member_id and status = 'active';
  if v_subject.id is null then raise exception 'badge member not active'; end if;

  select display_name into v_name from public.profiles
    where id = v_subject.user_id;
  return jsonb_build_object(
    'member_id', v_subject.id,
    'display_name', coalesce(v_name, '')
  );
end;
$$;
revoke execute on function public.kiosk_identify(uuid, text) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- Whole-office booking parity. NOT YET applied to the hosted reference
-- project — the orchestrator applies it after review.
--
-- Space-barcode epic (field request): reservations target desk seats,
-- whole offices, or whole levels; an office reservation covers all its
-- desks. Whole-OFFICE booking existed since 0003/0005 but ungated and
-- unpriced — this brings it to 0050's level shape: the owner declares
-- the office bookable AND prices it, the workspace enables the
-- whole-space feature (the levelBooking flag now covers office+level),
-- and the member needs the personal whole-space grant
-- (members.can_reserve_level — one grant for both shapes). The
-- seat-vs-office conflict guards (no office booking over reserved
-- seats, no seat booking under a reserved office) already exist and
-- stay verbatim.

-- 1. Office price per half-day (levels got theirs in 0050).
alter table public.offices
  add column if not exists price_cents int not null default 0
    check (price_cents >= 0);

-- 2. create_reservation v5: 0050 v4 verbatim, with the office path
-- gaining the feature gate and the personal grant — SAME pinned error
-- substrings as the level path, so clients map once.
create or replace function public.create_reservation(
  p_workspace_id uuid,
  p_seat_id uuid,
  p_office_id uuid,
  p_starts_at timestamptz,
  p_ends_at timestamptz,
  p_check_in boolean default false,
  p_level_id uuid default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_seat public.seats;
  v_office_id uuid;
  v_level_id uuid;
  v_id uuid;
begin
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if (case when p_seat_id is null then 0 else 1 end
      + case when p_office_id is null then 0 else 1 end
      + case when p_level_id is null then 0 else 1 end) <> 1 then
    raise exception 'exactly one of seat, office or level required';
  end if;
  perform public.enforce_booking_rules(p_workspace_id, p_starts_at, p_ends_at, p_check_in);

  if p_seat_id is not null then
    select * into v_seat from public.seats
      where id = p_seat_id and workspace_id = p_workspace_id;
    if v_seat.id is null then raise exception 'unknown seat'; end if;
    if tstzrange(coalesce(v_seat.blocked_from, '-infinity'::timestamptz),
                 coalesce(v_seat.blocked_to, 'infinity'::timestamptz))
       && tstzrange(p_starts_at, p_ends_at)
       and (v_seat.blocked_from is not null or v_seat.blocked_to is not null) then
      raise exception 'seat is blocked in that period';
    end if;
    select d.office_id into v_office_id from public.desks d where d.id = v_seat.desk_id;
    if exists (
      select 1 from public.reservations r
      where r.office_id = v_office_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'office is reserved as a whole in that period';
    end if;
    select o.level_id into v_level_id from public.offices o where o.id = v_office_id;
    if exists (
      select 1 from public.reservations r
      where r.level_id = v_level_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'level is reserved as a whole in that period';
    end if;
  elsif p_office_id is not null then
    -- Whole-space gates (0057): feature + personal grant, like levels.
    if not public.level_booking_enabled(p_workspace_id) then
      raise exception 'level booking is not enabled';
    end if;
    if not v_member.can_reserve_level then
      -- the client pins this substring (0050)
      raise exception 'not allowed to reserve a level';
    end if;
    if not exists (
      select 1 from public.offices o
      where o.id = p_office_id and o.workspace_id = p_workspace_id
        and o.bookable_as_whole
    ) then
      raise exception 'office not bookable as a whole';
    end if;
    if exists (
      select 1 from public.reservations r
      join public.seats s on s.id = r.seat_id
      join public.desks d on d.id = s.desk_id
      where d.office_id = p_office_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'a seat in this office is already reserved in that period';
    end if;
    select o.level_id into v_level_id from public.offices o where o.id = p_office_id;
    if exists (
      select 1 from public.reservations r
      where r.level_id = v_level_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'level is reserved as a whole in that period';
    end if;
  else
    -- Level path: feature on, level bookable, member personally allowed.
    if not public.level_booking_enabled(p_workspace_id) then
      raise exception 'level booking is not enabled';
    end if;
    if not exists (
      select 1 from public.levels l
      where l.id = p_level_id and l.workspace_id = p_workspace_id
        and l.bookable_as_whole
    ) then
      raise exception 'level not bookable as a whole';
    end if;
    if not v_member.can_reserve_level then
      -- the client pins this substring
      raise exception 'not allowed to reserve a level';
    end if;
    if public.level_has_conflict(p_level_id, p_starts_at, p_ends_at) then
      raise exception 'the level has reservations in that period';
    end if;
  end if;

  insert into public.reservations
    (workspace_id, seat_id, office_id, level_id, member_id, starts_at, ends_at,
     status, checked_in_at)
  values (
    p_workspace_id, p_seat_id, p_office_id, p_level_id, v_member.id,
    p_starts_at, p_ends_at,
    case when p_check_in then 'checked_in' else 'reserved' end,
    case when p_check_in then now() end
  )
  returning id into v_id;
  perform public.assert_member_quota(v_member.id, p_starts_at);
  return v_id;
end;
$$;

-- 3. member_statement v6: v5 (0050) verbatim + the office price — the
-- level-supplement shape over offices. Additions marked "#office".
create or replace function public.member_statement(
  p_member_id uuid,
  p_period text
) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_member public.members;
  v_caller_is_admin boolean;
  v_band public.fee_bands;
  v_tz text;
  v_open int[];
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_month_first date;
  v_open_days int;
  v_pct int;
  v_included int;
  v_used int;
  v_base int := 0;
  v_overage int := 0;
  v_overage_rate int := 0;
  v_credits int;
  v_extra_half_days int := 0;
  v_supp_on boolean := false;
  v_supp_since timestamptz;
  v_supplement int := 0;
  v_granted int := 0;
  v_cap int := 0;
  v_remaining int := 0;
  v_level_supplement int := 0;
  -- #office
  v_office_supplement int := 0;
begin
  select * into v_member from public.members where id = p_member_id;
  if v_member.id is null then raise exception 'unknown member'; end if;
  v_caller_is_admin := public.is_admin_of(v_member.workspace_id);
  if not v_caller_is_admin and not exists (
    select 1 from public.members m
    where m.id = p_member_id and m.user_id = auth.uid()
  ) then
    raise exception 'not your statement';
  end if;

  select timezone,
         coalesce((select array_agg(x::int)
                     from jsonb_array_elements_text(booking_rules->'open_weekdays') x),
                  array[1,2,3,4,5]),
         coalesce(feature_flags -> 'accessorySupplements' = to_jsonb(true), false),
         accessory_supplements_since
    into v_tz, v_open, v_supp_on, v_supp_since
    from public.workspaces where id = v_member.workspace_id;
  v_period_start := to_timestamp(p_period || '-01', 'YYYY-MM-DD') at time zone v_tz;
  v_period_end := (to_timestamp(p_period || '-01', 'YYYY-MM-DD') + interval '1 month') at time zone v_tz;
  v_month_first := to_date(p_period || '-01', 'YYYY-MM-DD');

  v_pct := coalesce(v_member.subscription_pct, 100);
  select * into v_band from public.fee_bands
    where workspace_id = v_member.workspace_id
      and from_pct < v_pct and v_pct <= to_pct;
  if v_band.id is not null then
    v_base := v_band.fee_cents;
    v_overage_rate := v_band.overage_fee_cents;
  end if;

  select count(*) into v_open_days
  from generate_series(v_month_first,
                       (v_month_first + interval '1 month' - interval '1 day')::date,
                       interval '1 day') d
  where extract(isodow from d)::int = any(v_open)
    and not exists (select 1 from public.closure_days c
                     where c.workspace_id = v_member.workspace_id and c.day = d::date);
  v_included := ceil(v_open_days * 2 * v_pct / 100.0)::int;

  select count(distinct (date_trunc('day', r.starts_at at time zone v_tz)::date, s.slot))
  into v_used
  from public.reservations r
  cross join lateral (
    select case when extract(hour from r.starts_at at time zone v_tz) < 13 then 0 else 1 end as slot
  ) s
  where r.member_id = p_member_id
    and r.status in ('reserved','checked_in','completed')
    and r.starts_at >= v_period_start and r.starts_at < v_period_end;

  v_extra_half_days := greatest(0, v_used - v_included);
  v_overage := v_extra_half_days * v_overage_rate;

  select coalesce(sum(half_days), 0) into v_granted from public.quota_extensions
    where member_id = p_member_id and period = p_period;
  v_cap := v_included + v_granted;
  v_remaining := greatest(0, v_cap - v_used);

  if v_supp_on and v_supp_since is not null then
    select coalesce(sum(seat_supp.total_cents), 0) into v_supplement
    from (
      select distinct
        r.seat_id,
        date_trunc('day', r.starts_at at time zone v_tz)::date as day,
        case when extract(hour from r.starts_at at time zone v_tz) < 13 then 0 else 1 end as slot
      from public.reservations r
      where r.member_id = p_member_id
        and r.seat_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= greatest(v_period_start, v_supp_since)
        and r.starts_at < v_period_end
    ) hd
    join (
      select sa.seat_id, sum(a.supplement_cents)::int as total_cents
      from public.seat_accessories sa
      join public.accessories a on a.id = sa.accessory_id
      where a.active and a.supplement_cents > 0
      group by sa.seat_id
    ) seat_supp on seat_supp.seat_id = hd.seat_id;
  end if;

  select coalesce(sum(l.price_cents), 0) into v_level_supplement
  from (
    select distinct
      r.level_id,
      date_trunc('day', r.starts_at at time zone v_tz)::date as day,
      case when extract(hour from r.starts_at at time zone v_tz) < 13 then 0 else 1 end as slot
    from public.reservations r
    where r.member_id = p_member_id
      and r.level_id is not null
      and r.status in ('reserved','checked_in','completed')
      and r.starts_at >= v_period_start and r.starts_at < v_period_end
  ) lh
  join public.levels l on l.id = lh.level_id;

  -- #office: price × distinct half-days per reserved office.
  select coalesce(sum(o.price_cents), 0) into v_office_supplement
  from (
    select distinct
      r.office_id,
      date_trunc('day', r.starts_at at time zone v_tz)::date as day,
      case when extract(hour from r.starts_at at time zone v_tz) < 13 then 0 else 1 end as slot
    from public.reservations r
    where r.member_id = p_member_id
      and r.office_id is not null
      and r.status in ('reserved','checked_in','completed')
      and r.starts_at >= v_period_start and r.starts_at < v_period_end
  ) oh
  join public.offices o on o.id = oh.office_id;

  select coalesce(sum(case when kind = 'credit' then amount_cents else -amount_cents end), 0)
  into v_credits
  from public.ledger_entries
  where member_id = p_member_id and period = p_period;

  return jsonb_build_object(
    'period', p_period,
    'subscription_pct', v_pct,
    'fee_cents', v_base,
    'included_half_days', v_included,
    'open_days', v_open_days,
    'used_half_days', v_used,
    'extra_half_days', v_extra_half_days,
    'overage_cents', v_overage,
    'accessory_supplement_cents', v_supplement,
    'level_supplement_cents', v_level_supplement,
    -- #office
    'office_supplement_cents', v_office_supplement,
    'credits_cents', v_credits,
    'balance_cents',
      v_credits - v_base - v_overage - v_supplement - v_level_supplement
        - v_office_supplement,
    'overage_policy', coalesce(v_member.overage_policy, 'blocked'),
    'overage_rate_cents', v_overage_rate,
    'granted_half_days', v_granted,
    'remaining_half_days', v_remaining
  );
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- Co-owners. NOT YET applied to the hosted reference project — the
-- orchestrator applies it after review.
--
-- Field request: a member/admin can become a CO-OWNER.
--   · ACTIVE co-owner — owner permissions NOW (is_owner_of counts them,
--     so every owner-gated RPC accepts them), plus automatic
--     succession.
--   · PASSIVE co-owner — no extra permissions; becomes owner when the
--     owner activates them (activate_co_owner) or when the last owner
--     leaves (succession below).
-- Succession lives INSIDE protect_last_owner: where the guard used to
-- refuse removing the last owner, it now first promotes the best
-- co-owner (active before passive) and lets the owner go — a workspace
-- never loses its last owner AND an owner with a co-owner can leave.
-- Deliberate exception: validation "owner sign-off" quorum rules keep
-- meaning LITERAL owners.

-- 1. The role flavor.
alter table public.members
  add column if not exists co_owner text not null default 'none'
    check (co_owner in ('none', 'active', 'passive'));

-- 2. Active co-owners pass every owner gate that flows through the
-- helper (that is: almost all of them).
create or replace function public.is_owner_of(ws uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.members m
    where m.workspace_id = ws and m.user_id = auth.uid()
      and m.status = 'active' and (m.is_owner or m.co_owner = 'active')
  );
$$;

-- 3. Succession in the last-owner guard.
create or replace function public.protect_last_owner()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  remaining int;
  v_successor uuid;
begin
  if old.is_owner and old.status = 'active'
     and (tg_op = 'DELETE' or (not new.is_owner or new.status <> 'active')) then
    select count(*) into remaining from public.members
    where workspace_id = old.workspace_id and is_owner and status = 'active' and id <> old.id;
    if remaining = 0 then
      -- Promote the best co-owner: active first, then passive; oldest
      -- appointment order is not tracked, so id keeps it deterministic.
      select id into v_successor from public.members
        where workspace_id = old.workspace_id and status = 'active'
          and id <> old.id and co_owner <> 'none'
        order by (co_owner = 'active') desc, id
        limit 1;
      if v_successor is null then
        raise exception 'cannot remove the last owner of a workspace';
      end if;
      update public.members
        set is_owner = true, is_admin = true, co_owner = 'none'
        where id = v_successor;
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;

-- 4. Appoint / change / clear a co-owner. Owner-gated via the extended
-- helper, so an active co-owner can manage co-owners too ("same
-- permissions as the owner").
create or replace function public.set_co_owner(
  p_member_id uuid, p_status text
) returns void language plpgsql security definer set search_path = public as $$
declare v_subject public.members;
begin
  if p_status not in ('none', 'active', 'passive') then
    raise exception 'unknown co-owner status';
  end if;
  select * into v_subject from public.members where id = p_member_id;
  if v_subject.id is null then raise exception 'unknown member'; end if;
  if not public.is_owner_of(v_subject.workspace_id) then
    raise exception 'not the owner of this workspace';
  end if;
  if v_subject.is_owner then
    raise exception 'owners need no co-owner status';
  end if;
  if v_subject.is_kiosk then raise exception 'a kiosk cannot co-own'; end if;
  if v_subject.status <> 'active' then
    raise exception 'not an active member';
  end if;
  update public.members
    set co_owner = p_status,
        -- Owner permissions NOW: the active flavor also joins the admin
        -- surfaces its new rights operate through.
        is_admin = case when p_status = 'active' then true else is_admin end
    where id = p_member_id;
end;
$$;
revoke execute on function public.set_co_owner(uuid, text) from public, anon;

-- 5. "The owner activates it": a co-owner (active or passive) becomes a
-- FULL owner right now, alongside the current owner.
create or replace function public.activate_co_owner(p_member_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare v_subject public.members;
begin
  select * into v_subject from public.members where id = p_member_id;
  if v_subject.id is null then raise exception 'unknown member'; end if;
  if not public.is_owner_of(v_subject.workspace_id) then
    raise exception 'not the owner of this workspace';
  end if;
  if v_subject.co_owner = 'none' then
    raise exception 'not a co-owner';
  end if;
  if v_subject.status <> 'active' then
    raise exception 'not an active member';
  end if;
  update public.members
    set is_owner = true, is_admin = true, co_owner = 'none'
    where id = p_member_id;
end;
$$;
revoke execute on function public.activate_co_owner(uuid) from public, anon;

-- 6. The two owner gates that check is_owner INLINE instead of through
-- the helper now accept active co-owners too.
create or replace function public.set_member_kiosk(p_member_id uuid, p_is_kiosk boolean)
returns void language plpgsql security definer set search_path = public as $$
declare v_member public.members;
begin
  select * into v_member from public.members where id = p_member_id;
  if v_member.id is null then raise exception 'unknown member'; end if;
  if not public.is_owner_of(v_member.workspace_id) then
    raise exception 'not the owner of this workspace';
  end if;
  if v_member.is_owner then raise exception 'the owner cannot be a kiosk'; end if;
  if v_member.co_owner <> 'none' then
    raise exception 'a co-owner cannot be a kiosk';
  end if;
  update public.members set is_kiosk = p_is_kiosk where id = p_member_id;
end;
$$;
revoke execute on function public.set_member_kiosk(uuid, boolean) from public, anon;

-- 7. admin_create_reservation_for v4: the level-assign OWNER bypass
-- accepts active co-owners (0050 body, one guard widened).
create or replace function public.admin_create_reservation_for(
  p_workspace_id uuid,
  p_subject_member_id uuid,
  p_seat_id uuid,
  p_starts_at timestamptz,
  p_ends_at timestamptz,
  p_level_id uuid default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_res_id uuid;
  v_event_id uuid;
begin
  select * into v_actor from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if not exists (
    select 1 from public.members
    where id = p_subject_member_id and workspace_id = p_workspace_id and status = 'active'
  ) then raise exception 'unknown subject member'; end if;
  if (p_seat_id is null) = (p_level_id is null) then
    raise exception 'exactly one of seat or level required';
  end if;
  perform public.enforce_booking_rules(p_workspace_id, p_starts_at, p_ends_at);

  if p_level_id is not null then
    if not public.level_booking_enabled(p_workspace_id) then
      raise exception 'level booking is not enabled';
    end if;
    if not (v_actor.is_owner or v_actor.co_owner = 'active')
       and not coalesce(
      (select w.feature_flags -> 'adminLevelAssign' = to_jsonb(true)
         from public.workspaces w where w.id = p_workspace_id), false) then
      raise exception 'admins may not assign level reservations here';
    end if;
    if not exists (
      select 1 from public.levels l
      where l.id = p_level_id and l.workspace_id = p_workspace_id
        and l.bookable_as_whole
    ) then
      raise exception 'level not bookable as a whole';
    end if;
    if public.level_has_conflict(p_level_id, p_starts_at, p_ends_at) then
      raise exception 'the level has reservations in that period';
    end if;
  else
    perform public.assert_seat_not_blocked(p_seat_id, p_starts_at, p_ends_at);
  end if;

  insert into public.reservations
    (workspace_id, seat_id, level_id, member_id, starts_at, ends_at, status)
  values (p_workspace_id, p_seat_id, p_level_id, p_subject_member_id,
          p_starts_at, p_ends_at, 'reserved')
  returning id into v_res_id;
  perform public.assert_member_quota(p_subject_member_id, p_starts_at);

  update public.events set actor_member_id = v_actor.id, status = 'pending'
    where reservation_id = v_res_id and action = 'created';

  select id into v_event_id from public.events
    where reservation_id = v_res_id and action = 'created';
  return v_event_id;
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- Whole-DESK (table) reservations + validation routing. NOT YET applied
-- to the hosted reference project — the orchestrator applies it after
-- review.
--
-- Field request: tables become a reservable unit like offices/levels
-- (owner declares a desk bookable + prices it; the whole-space feature
-- and the member grant gate it), and EVERY whole-space reservation
-- (desk, office, level) routes through the REGULAR validation quorum
-- when the owner configures a 'space_reservation' rule: the booking
-- blocks the space immediately, the created event parks pending, a
-- reject cancels it (respond_to_event's existing branch), the 7-day
-- sweep auto-confirms like other creations.
-- Also fixes a latent bug: validation_policies' type check never
-- learned quota/role_change/member_join, so saving those rules failed.

-- 1. Desk bookability + price (the 0050/0057 shape).
alter table public.desks
  add column if not exists bookable_as_whole boolean not null default false,
  add column if not exists price_cents int not null default 0
    check (price_cents >= 0);

-- 2. Reservations may target a desk: exactly one of four.
alter table public.reservations
  add column if not exists desk_id uuid references public.desks(id)
    on delete restrict;
alter table public.reservations drop constraint reservations_one_target;
alter table public.reservations add constraint reservations_one_target check (
  (case when seat_id is null then 0 else 1 end
   + case when desk_id is null then 0 else 1 end
   + case when office_id is null then 0 else 1 end
   + case when level_id is null then 0 else 1 end) = 1
);
alter table public.reservations add constraint reservations_desk_no_overlap
  exclude using gist (
    desk_id with =,
    tstzrange(starts_at, ends_at) with &&
  ) where (desk_id is not null and status in ('reserved','checked_in'));

-- 3. Domain constraints: the new event/policy type, plus the missing
-- later domains (bug fix — the client already writes them).
alter table public.events drop constraint events_type_check;
alter table public.events add constraint events_type_check check (type in
  ('reservation','payment','expense','adjustment','service_charge',
   'quota','role_change','member_join','space_reservation'));
alter table public.validation_policies
  drop constraint validation_policies_event_type_check;
alter table public.validation_policies
  add constraint validation_policies_event_type_check check (event_type in
    ('reservation','payment','expense','adjustment','service_charge',
     'quota','role_change','member_join','space_reservation'));

-- 4. level_has_conflict v2: desk reservations on the floor count.
create or replace function public.level_has_conflict(
  p_level_id uuid, p_starts_at timestamptz, p_ends_at timestamptz
) returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.reservations r
    left join public.seats s on s.id = r.seat_id
    left join public.desks d on d.id = coalesce(s.desk_id, r.desk_id)
    left join public.offices o on o.id = coalesce(r.office_id, d.office_id)
    where r.status in ('reserved','checked_in')
      and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
      and (r.level_id = p_level_id or o.level_id = p_level_id)
  );
$$;
revoke execute on function public.level_has_conflict(uuid, timestamptz, timestamptz)
  from public, anon;

-- 5. create_reservation v7: the desk path + desk guards + validation
-- routing for every whole-space booking.
create or replace function public.create_reservation(
  p_workspace_id uuid,
  p_seat_id uuid,
  p_office_id uuid,
  p_starts_at timestamptz,
  p_ends_at timestamptz,
  p_check_in boolean default false,
  p_level_id uuid default null,
  p_desk_id uuid default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_seat public.seats;
  v_office_id uuid;
  v_level_id uuid;
  v_id uuid;
begin
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if (case when p_seat_id is null then 0 else 1 end
      + case when p_desk_id is null then 0 else 1 end
      + case when p_office_id is null then 0 else 1 end
      + case when p_level_id is null then 0 else 1 end) <> 1 then
    raise exception 'exactly one of seat, desk, office or level required';
  end if;
  perform public.enforce_booking_rules(p_workspace_id, p_starts_at, p_ends_at, p_check_in);

  if p_seat_id is not null then
    select * into v_seat from public.seats
      where id = p_seat_id and workspace_id = p_workspace_id;
    if v_seat.id is null then raise exception 'unknown seat'; end if;
    if tstzrange(coalesce(v_seat.blocked_from, '-infinity'::timestamptz),
                 coalesce(v_seat.blocked_to, 'infinity'::timestamptz))
       && tstzrange(p_starts_at, p_ends_at)
       and (v_seat.blocked_from is not null or v_seat.blocked_to is not null) then
      raise exception 'seat is blocked in that period';
    end if;
    -- 0059: the seat's DESK reserved as a whole blocks the seat.
    if exists (
      select 1 from public.reservations r
      where r.desk_id = v_seat.desk_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'desk is reserved as a whole in that period';
    end if;
    select d.office_id into v_office_id from public.desks d where d.id = v_seat.desk_id;
    if exists (
      select 1 from public.reservations r
      where r.office_id = v_office_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'office is reserved as a whole in that period';
    end if;
    select o.level_id into v_level_id from public.offices o where o.id = v_office_id;
    if exists (
      select 1 from public.reservations r
      where r.level_id = v_level_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'level is reserved as a whole in that period';
    end if;
  elsif p_desk_id is not null then
    -- Whole-DESK path (0059): the level/office gates, desk-scale.
    if not public.level_booking_enabled(p_workspace_id) then
      raise exception 'level booking is not enabled';
    end if;
    if not v_member.can_reserve_level then
      -- the client pins this substring (0050)
      raise exception 'not allowed to reserve a level';
    end if;
    if not exists (
      select 1 from public.desks d
      where d.id = p_desk_id and d.workspace_id = p_workspace_id
        and d.bookable_as_whole
    ) then
      raise exception 'desk not bookable as a whole';
    end if;
    if exists (
      select 1 from public.reservations r
      join public.seats s on s.id = r.seat_id
      where s.desk_id = p_desk_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'a seat on this desk is already reserved in that period';
    end if;
    select d.office_id into v_office_id from public.desks d where d.id = p_desk_id;
    if exists (
      select 1 from public.reservations r
      where r.office_id = v_office_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'office is reserved as a whole in that period';
    end if;
    select o.level_id into v_level_id from public.offices o where o.id = v_office_id;
    if exists (
      select 1 from public.reservations r
      where r.level_id = v_level_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'level is reserved as a whole in that period';
    end if;
  elsif p_office_id is not null then
    -- Whole-space gates (0057): feature + personal grant, like levels.
    if not public.level_booking_enabled(p_workspace_id) then
      raise exception 'level booking is not enabled';
    end if;
    if not v_member.can_reserve_level then
      -- the client pins this substring (0050)
      raise exception 'not allowed to reserve a level';
    end if;
    if not exists (
      select 1 from public.offices o
      where o.id = p_office_id and o.workspace_id = p_workspace_id
        and o.bookable_as_whole
    ) then
      raise exception 'office not bookable as a whole';
    end if;
    if exists (
      select 1 from public.reservations r
      join public.seats s on s.id = r.seat_id
      join public.desks d on d.id = s.desk_id
      where d.office_id = p_office_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'a seat in this office is already reserved in that period';
    end if;
    -- 0059: a desk inside reserved as a whole blocks the office too.
    if exists (
      select 1 from public.reservations r
      join public.desks d on d.id = r.desk_id
      where d.office_id = p_office_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'a desk in this office is already reserved in that period';
    end if;
    select o.level_id into v_level_id from public.offices o where o.id = p_office_id;
    if exists (
      select 1 from public.reservations r
      where r.level_id = v_level_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'level is reserved as a whole in that period';
    end if;
  else
    -- Level path: feature on, level bookable, member personally allowed.
    if not public.level_booking_enabled(p_workspace_id) then
      raise exception 'level booking is not enabled';
    end if;
    if not exists (
      select 1 from public.levels l
      where l.id = p_level_id and l.workspace_id = p_workspace_id
        and l.bookable_as_whole
    ) then
      raise exception 'level not bookable as a whole';
    end if;
    if not v_member.can_reserve_level then
      -- the client pins this substring
      raise exception 'not allowed to reserve a level';
    end if;
    if public.level_has_conflict(p_level_id, p_starts_at, p_ends_at) then
      raise exception 'the level has reservations in that period';
    end if;
  end if;

  insert into public.reservations
    (workspace_id, seat_id, desk_id, office_id, level_id, member_id,
     starts_at, ends_at, status, checked_in_at)
  values (
    p_workspace_id, p_seat_id, p_desk_id, p_office_id, p_level_id,
    v_member.id, p_starts_at, p_ends_at,
    case when p_check_in then 'checked_in' else 'reserved' end,
    case when p_check_in then now() end
  )
  returning id into v_id;
  perform public.assert_member_quota(v_member.id, p_starts_at);

  -- 0059: whole-space bookings route through the REGULAR validation
  -- feature when the owner configured a rule for them — the reservation
  -- blocks the space immediately, validators confirm or reject (a
  -- reject cancels it via respond_to_event's existing branch).
  if p_desk_id is not null or p_office_id is not null
     or p_level_id is not null then
    if exists (
      select 1 from public.validation_policies vp
      where vp.workspace_id = p_workspace_id
        and vp.event_type = 'space_reservation'
    ) then
      update public.events
        set status = 'pending', type = 'space_reservation'
        where reservation_id = v_id and action = 'created';
    end if;
  end if;
  return v_id;
end;
$$;

-- 6. kiosk_act v3: the walk-up seat path refuses a whole-reserved desk.
create or replace function public.kiosk_act(
  p_workspace_id uuid,
  p_badge_token text,
  p_action text,             -- 'reserve' | 'check_in' | 'check_out'
  p_seat_id uuid default null,
  p_starts_at timestamptz default null,
  p_ends_at timestamptz default null,
  p_level_id uuid default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_kiosk public.members;
  v_badge public.member_badges;
  v_subject public.members;
  v_seat public.seats;
  v_office_id uuid;
  v_res public.reservations;
  v_id uuid;
begin
  select * into v_kiosk from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and is_kiosk;
  if v_kiosk.id is null then raise exception 'not a kiosk of this workspace'; end if;

  select * into v_badge from public.member_badges
    where workspace_id = p_workspace_id
      and token_hash = public.badge_token_hash(p_badge_token)
      and revoked_at is null;
  if v_badge.id is null then
    raise exception 'badge not recognized';
  end if;
  select * into v_subject from public.members
    where id = v_badge.member_id and status = 'active';
  if v_subject.id is null then raise exception 'badge member not active'; end if;

  if p_action = 'check_out' then
    select r.* into v_res from public.reservations r
      where r.member_id = v_subject.id and r.status = 'checked_in'
        and (p_seat_id is null or r.seat_id = p_seat_id)
        and (p_level_id is null or r.level_id = p_level_id)
      order by r.checked_in_at desc limit 1;
    if v_res.id is null then raise exception 'not checked in'; end if;
    update public.reservations
      set status = 'completed', checked_out_at = now(),
          ends_at = least(ends_at, now())
      where id = v_res.id;
    return jsonb_build_object('action', 'check_out', 'reservation_id', v_res.id);
  end if;

  if p_action not in ('reserve', 'check_in') then
    raise exception 'unknown kiosk action';
  end if;
  if (p_seat_id is null) = (p_level_id is null)
     or p_starts_at is null or p_ends_at is null then
    raise exception 'seat or level, and window required';
  end if;

  if p_level_id is not null then
    -- Level path: same gates as create_reservation — feature, bookable,
    -- the badge member's personal grant, no conflicts on the level.
    if not public.level_booking_enabled(p_workspace_id) then
      raise exception 'level booking is not enabled';
    end if;
    if not exists (
      select 1 from public.levels l
      where l.id = p_level_id and l.workspace_id = p_workspace_id
        and l.bookable_as_whole
    ) then
      raise exception 'level not bookable as a whole';
    end if;
    if not v_subject.can_reserve_level then
      raise exception 'not allowed to reserve a level';
    end if;

    if p_action = 'check_in' then
      select r.* into v_res from public.reservations r
        where r.member_id = v_subject.id and r.level_id = p_level_id
          and r.status = 'reserved'
          and r.starts_at <= now() and r.ends_at > now()
        limit 1;
      if v_res.id is not null then
        update public.reservations
          set status = 'checked_in', checked_in_at = now()
          where id = v_res.id;
        return jsonb_build_object('action', 'check_in', 'reservation_id', v_res.id);
      end if;
    end if;

    perform public.enforce_booking_rules(
      p_workspace_id, p_starts_at, p_ends_at, p_action = 'check_in');
    if public.level_has_conflict(p_level_id, p_starts_at, p_ends_at) then
      raise exception 'the level has reservations in that period';
    end if;

    insert into public.reservations
      (workspace_id, level_id, member_id, starts_at, ends_at, status, checked_in_at)
    values (
      p_workspace_id, p_level_id, v_subject.id, p_starts_at, p_ends_at,
      case when p_action = 'check_in' then 'checked_in' else 'reserved' end,
      case when p_action = 'check_in' then now() end
    )
    returning id into v_id;
    perform public.assert_member_quota(v_subject.id, p_starts_at);
    return jsonb_build_object('action', p_action, 'reservation_id', v_id);
  end if;

  select * into v_seat from public.seats
    where id = p_seat_id and workspace_id = p_workspace_id;
  if v_seat.id is null then raise exception 'unknown seat'; end if;

  if p_action = 'check_in' then
    select r.* into v_res from public.reservations r
      where r.member_id = v_subject.id and r.seat_id = p_seat_id
        and r.status = 'reserved'
        and r.starts_at <= now() and r.ends_at > now()
      limit 1;
    if v_res.id is not null then
      update public.reservations
        set status = 'checked_in', checked_in_at = now()
        where id = v_res.id;
      return jsonb_build_object('action', 'check_in', 'reservation_id', v_res.id);
    end if;
  end if;

  perform public.enforce_booking_rules(
    p_workspace_id, p_starts_at, p_ends_at, p_action = 'check_in');
  if tstzrange(coalesce(v_seat.blocked_from, '-infinity'::timestamptz),
               coalesce(v_seat.blocked_to, 'infinity'::timestamptz))
     && tstzrange(p_starts_at, p_ends_at)
     and (v_seat.blocked_from is not null or v_seat.blocked_to is not null) then
    raise exception 'seat is blocked in that period';
  end if;
  -- 0059: the seat's DESK reserved as a whole blocks the walk-up too.
  if exists (
    select 1 from public.reservations r
    where r.desk_id = v_seat.desk_id
      and r.status in ('reserved','checked_in')
      and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
  ) then
    raise exception 'desk is reserved as a whole in that period';
  end if;
  select d.office_id into v_office_id from public.desks d where d.id = v_seat.desk_id;
  if exists (
    select 1 from public.reservations r
    where r.office_id = v_office_id
      and r.status in ('reserved','checked_in')
      and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
  ) then
    raise exception 'office is reserved as a whole in that period';
  end if;
  if exists (
    select 1 from public.reservations r
    where r.level_id = (select o.level_id from public.offices o where o.id = v_office_id)
      and r.status in ('reserved','checked_in')
      and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
  ) then
    raise exception 'level is reserved as a whole in that period';
  end if;

  insert into public.reservations
    (workspace_id, seat_id, member_id, starts_at, ends_at, status, checked_in_at)
  values (
    p_workspace_id, p_seat_id, v_subject.id, p_starts_at, p_ends_at,
    case when p_action = 'check_in' then 'checked_in' else 'reserved' end,
    case when p_action = 'check_in' then now() end
  )
  returning id into v_id;
  perform public.assert_member_quota(v_subject.id, p_starts_at);
  return jsonb_build_object('action', p_action, 'reservation_id', v_id);
end;
$$;
revoke execute on function public.kiosk_act(uuid, text, text, uuid, timestamptz, timestamptz, uuid)
  from public, anon;

-- 7. member_statement v7: the desk supplement line.
create or replace function public.member_statement(
  p_member_id uuid,
  p_period text
) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_member public.members;
  v_caller_is_admin boolean;
  v_band public.fee_bands;
  v_tz text;
  v_open int[];
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_month_first date;
  v_open_days int;
  v_pct int;
  v_included int;
  v_used int;
  v_base int := 0;
  v_overage int := 0;
  v_overage_rate int := 0;
  v_credits int;
  v_extra_half_days int := 0;
  v_supp_on boolean := false;
  v_supp_since timestamptz;
  v_supplement int := 0;
  v_granted int := 0;
  v_cap int := 0;
  v_remaining int := 0;
  v_level_supplement int := 0;
  v_office_supplement int := 0;
  -- #desk (0059)
  v_desk_supplement int := 0;
begin
  select * into v_member from public.members where id = p_member_id;
  if v_member.id is null then raise exception 'unknown member'; end if;
  v_caller_is_admin := public.is_admin_of(v_member.workspace_id);
  if not v_caller_is_admin and not exists (
    select 1 from public.members m
    where m.id = p_member_id and m.user_id = auth.uid()
  ) then
    raise exception 'not your statement';
  end if;

  select timezone,
         coalesce((select array_agg(x::int)
                     from jsonb_array_elements_text(booking_rules->'open_weekdays') x),
                  array[1,2,3,4,5]),
         coalesce(feature_flags -> 'accessorySupplements' = to_jsonb(true), false),
         accessory_supplements_since
    into v_tz, v_open, v_supp_on, v_supp_since
    from public.workspaces where id = v_member.workspace_id;
  v_period_start := to_timestamp(p_period || '-01', 'YYYY-MM-DD') at time zone v_tz;
  v_period_end := (to_timestamp(p_period || '-01', 'YYYY-MM-DD') + interval '1 month') at time zone v_tz;
  v_month_first := to_date(p_period || '-01', 'YYYY-MM-DD');

  v_pct := coalesce(v_member.subscription_pct, 100);
  select * into v_band from public.fee_bands
    where workspace_id = v_member.workspace_id
      and from_pct < v_pct and v_pct <= to_pct;
  if v_band.id is not null then
    v_base := v_band.fee_cents;
    v_overage_rate := v_band.overage_fee_cents;
  end if;

  select count(*) into v_open_days
  from generate_series(v_month_first,
                       (v_month_first + interval '1 month' - interval '1 day')::date,
                       interval '1 day') d
  where extract(isodow from d)::int = any(v_open)
    and not exists (select 1 from public.closure_days c
                     where c.workspace_id = v_member.workspace_id and c.day = d::date);
  v_included := ceil(v_open_days * 2 * v_pct / 100.0)::int;

  select count(distinct (date_trunc('day', r.starts_at at time zone v_tz)::date, s.slot))
  into v_used
  from public.reservations r
  cross join lateral (
    select case when extract(hour from r.starts_at at time zone v_tz) < 13 then 0 else 1 end as slot
  ) s
  where r.member_id = p_member_id
    and r.status in ('reserved','checked_in','completed')
    and r.starts_at >= v_period_start and r.starts_at < v_period_end;

  v_extra_half_days := greatest(0, v_used - v_included);
  v_overage := v_extra_half_days * v_overage_rate;

  select coalesce(sum(half_days), 0) into v_granted from public.quota_extensions
    where member_id = p_member_id and period = p_period;
  v_cap := v_included + v_granted;
  v_remaining := greatest(0, v_cap - v_used);

  if v_supp_on and v_supp_since is not null then
    select coalesce(sum(seat_supp.total_cents), 0) into v_supplement
    from (
      select distinct
        r.seat_id,
        date_trunc('day', r.starts_at at time zone v_tz)::date as day,
        case when extract(hour from r.starts_at at time zone v_tz) < 13 then 0 else 1 end as slot
      from public.reservations r
      where r.member_id = p_member_id
        and r.seat_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= greatest(v_period_start, v_supp_since)
        and r.starts_at < v_period_end
    ) hd
    join (
      select sa.seat_id, sum(a.supplement_cents)::int as total_cents
      from public.seat_accessories sa
      join public.accessories a on a.id = sa.accessory_id
      where a.active and a.supplement_cents > 0
      group by sa.seat_id
    ) seat_supp on seat_supp.seat_id = hd.seat_id;
  end if;

  select coalesce(sum(l.price_cents), 0) into v_level_supplement
  from (
    select distinct
      r.level_id,
      date_trunc('day', r.starts_at at time zone v_tz)::date as day,
      case when extract(hour from r.starts_at at time zone v_tz) < 13 then 0 else 1 end as slot
    from public.reservations r
    where r.member_id = p_member_id
      and r.level_id is not null
      and r.status in ('reserved','checked_in','completed')
      and r.starts_at >= v_period_start and r.starts_at < v_period_end
  ) lh
  join public.levels l on l.id = lh.level_id;

  -- #office: price × distinct half-days per reserved office.
  select coalesce(sum(o.price_cents), 0) into v_office_supplement
  from (
    select distinct
      r.office_id,
      date_trunc('day', r.starts_at at time zone v_tz)::date as day,
      case when extract(hour from r.starts_at at time zone v_tz) < 13 then 0 else 1 end as slot
    from public.reservations r
    where r.member_id = p_member_id
      and r.office_id is not null
      and r.status in ('reserved','checked_in','completed')
      and r.starts_at >= v_period_start and r.starts_at < v_period_end
  ) oh
  join public.offices o on o.id = oh.office_id;

  -- #desk: price × distinct half-days per reserved desk (0059).
  select coalesce(sum(d.price_cents), 0) into v_desk_supplement
  from (
    select distinct
      r.desk_id,
      date_trunc('day', r.starts_at at time zone v_tz)::date as day,
      case when extract(hour from r.starts_at at time zone v_tz) < 13 then 0 else 1 end as slot
    from public.reservations r
    where r.member_id = p_member_id
      and r.desk_id is not null
      and r.status in ('reserved','checked_in','completed')
      and r.starts_at >= v_period_start and r.starts_at < v_period_end
  ) dh
  join public.desks d on d.id = dh.desk_id;

  select coalesce(sum(case when kind = 'credit' then amount_cents else -amount_cents end), 0)
  into v_credits
  from public.ledger_entries
  where member_id = p_member_id and period = p_period;

  return jsonb_build_object(
    'period', p_period,
    'subscription_pct', v_pct,
    'fee_cents', v_base,
    'included_half_days', v_included,
    'open_days', v_open_days,
    'used_half_days', v_used,
    'extra_half_days', v_extra_half_days,
    'overage_cents', v_overage,
    'accessory_supplement_cents', v_supplement,
    'level_supplement_cents', v_level_supplement,
    -- #office
    'office_supplement_cents', v_office_supplement,
    'desk_supplement_cents', v_desk_supplement,
    'credits_cents', v_credits,
    'balance_cents',
      v_credits - v_base - v_overage - v_supplement - v_level_supplement
        - v_office_supplement - v_desk_supplement,
    'overage_policy', coalesce(v_member.overage_policy, 'blocked'),
    'overage_rate_cents', v_overage_rate,
    'granted_half_days', v_granted,
    'remaining_half_days', v_remaining
  );
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- Invoices. NOT YET applied to the hosted reference project — the
-- orchestrator applies it after review.
--
-- Field request: the owner (or an admin the owner appointed via the
-- adminInvoicing delegation flag) creates INVOICES for members. An
-- invoice is an IMMUTABLE document in an archive readable by its
-- member and the workspace admins. Everything the PDF needs is
-- SNAPSHOTTED at issue time (names, addresses, issuer), so later
-- profile edits can never rewrite an issued document; a SHA-256
-- fingerprint over the canonical content is stored and printed as the
-- digital signature. Addresses are new: members carry one on their
-- profile, the workspace carries its own.

-- 1. Addresses.
alter table public.profiles
  add column if not exists address text not null default ''
    check (char_length(address) <= 400);
alter table public.workspaces
  add column if not exists address text not null default ''
    check (char_length(address) <= 400);

-- 2. The archive. RLS: SELECT for the member and admins; NO insert/
-- update/delete policies — writes only through the RPC below, and a
-- belt-and-braces trigger refuses mutation even for definer paths.
create table public.invoices (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  member_id uuid not null references public.members(id) on delete restrict,
  issuer_member_id uuid not null references public.members(id) on delete restrict,
  number text not null,
  issued_at timestamptz not null default now(),
  period text,
  title text not null check (char_length(title) between 1 and 200),
  -- [{"label": text, "amount_cents": int}, ...]
  lines jsonb not null,
  total_cents int not null,
  currency text not null,
  member_name text not null,
  member_address text not null default '',
  workspace_name text not null,
  workspace_address text not null default '',
  issuer_name text not null,
  signature text not null,
  unique (workspace_id, number)
);
create index invoices_member_idx on public.invoices (member_id);
create index invoices_workspace_idx on public.invoices (workspace_id);

alter table public.invoices enable row level security;
create policy invoices_select on public.invoices for select using (
  public.is_admin_of(workspace_id)
  or exists (select 1 from public.members m
              where m.id = invoices.member_id and m.user_id = auth.uid())
);

create or replace function public.invoices_immutable()
returns trigger language plpgsql as $$
begin
  raise exception 'invoices are immutable';
end;
$$;
create trigger invoices_no_mutation
before update or delete on public.invoices
for each row execute function public.invoices_immutable();

-- 3. Issue an invoice. Caller: owner (incl. active co-owners via
-- is_owner_of) always; admins only while the adminInvoicing delegation
-- flag is on. Numbering is per workspace and year under an advisory
-- lock, so concurrent issues never collide.
create or replace function public.create_invoice(
  p_workspace_id uuid,
  p_member_id uuid,
  p_title text,
  p_lines jsonb,
  p_period text default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_subject public.members;
  v_workspace public.workspaces;
  v_line jsonb;
  v_total int := 0;
  v_count int;
  v_number text;
  v_member_name text;
  v_member_address text;
  v_issuer_name text;
  v_id uuid;
  v_signature text;
begin
  select * into v_actor from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if not public.is_owner_of(p_workspace_id) and not coalesce(
    (select w.feature_flags -> 'adminInvoicing' = to_jsonb(true)
       from public.workspaces w where w.id = p_workspace_id), false) then
    raise exception 'admins may not issue invoices here';
  end if;

  select * into v_subject from public.members
    where id = p_member_id and workspace_id = p_workspace_id
      and status = 'active' and not is_kiosk;
  if v_subject.id is null then raise exception 'unknown subject member'; end if;

  if p_title is null or btrim(p_title) = '' then
    raise exception 'title required';
  end if;
  if jsonb_typeof(p_lines) <> 'array'
     or jsonb_array_length(p_lines) = 0 then
    raise exception 'at least one line required';
  end if;
  for v_line in select * from jsonb_array_elements(p_lines) loop
    if jsonb_typeof(v_line -> 'label') <> 'string'
       or jsonb_typeof(v_line -> 'amount_cents') <> 'number' then
      raise exception 'invalid invoice line';
    end if;
    v_total := v_total + (v_line ->> 'amount_cents')::int;
  end loop;

  select * into v_workspace from public.workspaces where id = p_workspace_id;
  select coalesce(display_name, ''), coalesce(address, '')
    into v_member_name, v_member_address
    from public.profiles where id = v_subject.user_id;
  select coalesce(display_name, '') into v_issuer_name
    from public.profiles where id = v_actor.user_id;

  -- Per-workspace/year sequence under an advisory lock.
  perform pg_advisory_xact_lock(hashtext(p_workspace_id::text));
  select count(*) into v_count from public.invoices
    where workspace_id = p_workspace_id
      and date_part('year', issued_at) = date_part('year', now());
  v_number := 'INV-' || date_part('year', now())::int || '-'
      || lpad((v_count + 1)::text, 4, '0');

  v_id := gen_random_uuid();
  -- The digital signature: a SHA-256 fingerprint over the canonical
  -- content — any later tampering breaks it, and the trigger above
  -- refuses tampering in the first place.
  v_signature := encode(extensions.digest(convert_to(concat_ws('|',
      v_id::text, v_number, p_workspace_id::text, v_subject.id::text,
      v_member_name, v_member_address, v_workspace.name,
      coalesce(v_workspace.address, ''), v_issuer_name,
      p_title, p_lines::text, v_total::text, v_workspace.currency_code,
      now()::date::text), 'UTF8'), 'sha256'), 'hex');

  insert into public.invoices
    (id, workspace_id, member_id, issuer_member_id, number, period, title,
     lines, total_cents, currency, member_name, member_address,
     workspace_name, workspace_address, issuer_name, signature)
  values
    (v_id, p_workspace_id, v_subject.id, v_actor.id, v_number, p_period,
     btrim(p_title), p_lines, v_total, v_workspace.currency_code,
     v_member_name, v_member_address, v_workspace.name,
     coalesce(v_workspace.address, ''), v_issuer_name, v_signature);
  return v_id;
end;
$$;
revoke execute on function public.create_invoice(uuid, uuid, text, jsonb, text)
  from public, anon;

-- SPDX-License-Identifier: 0BSD
-- Invoice correction (field request): a wrong invoice can be tagged
-- ERRONEOUS (voided) and re-issued as a REPLACEMENT that references the
-- invoice it replaces. Content stays immutable: the trigger now permits
-- exactly ONE narrow change — stamping voided_at/voided_by_name once,
-- with every other column untouched — and still refuses everything
-- else, including un-voiding and DELETE. The replacement carries the
-- replaced invoice's id (technical reference) and number (snapshot for
-- the PDF), covered by its own signature.

-- 1. Void stamp + replacement reference.
alter table public.invoices
  add column voided_at timestamptz,
  add column voided_by_name text not null default '',
  add column replaces_invoice_id uuid references public.invoices(id)
    on delete restrict,
  add column replaces_number text not null default '';

-- One direct replacement per invoice: a wrong REPLACEMENT is voided and
-- replaced itself, forming a chain — never a fork.
create unique index invoices_replaces_unique
  on public.invoices (replaces_invoice_id)
  where replaces_invoice_id is not null;

-- 2. Immutability, amended: the one-way void stamp is the sole
-- permitted UPDATE.
create or replace function public.invoices_immutable()
returns trigger language plpgsql as $$
begin
  if tg_op = 'UPDATE'
     and old.voided_at is null
     and new.voided_at is not null
     and (to_jsonb(old) - 'voided_at' - 'voided_by_name')
       = (to_jsonb(new) - 'voided_at' - 'voided_by_name') then
    return new;
  end if;
  raise exception 'invoices are immutable';
end;
$$;

-- 3. Tag an invoice erroneous. Same authorization as issuing: owner
-- (incl. active co-owners) always, admins via the adminInvoicing flag.
create or replace function public.void_invoice(p_invoice_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_invoice public.invoices;
  v_actor public.members;
  v_actor_name text;
begin
  select * into v_invoice from public.invoices where id = p_invoice_id;
  if v_invoice.id is null then raise exception 'unknown invoice'; end if;
  select * into v_actor from public.members
    where workspace_id = v_invoice.workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if not public.is_owner_of(v_invoice.workspace_id) and not coalesce(
    (select w.feature_flags -> 'adminInvoicing' = to_jsonb(true)
       from public.workspaces w where w.id = v_invoice.workspace_id), false) then
    raise exception 'admins may not issue invoices here';
  end if;
  if v_invoice.voided_at is not null then
    raise exception 'invoice already voided';
  end if;
  select coalesce(display_name, '') into v_actor_name
    from public.profiles where id = v_actor.user_id;
  update public.invoices
     set voided_at = now(), voided_by_name = v_actor_name
   where id = p_invoice_id;
end;
$$;
revoke execute on function public.void_invoice(uuid) from public, anon;

-- 4. create_invoice gains p_replaces: the replacement references the
-- erroneous invoice and, in the same transaction, voids it if the
-- caller had not tagged it yet — the reference always points at a
-- voided document. Postgres cannot change an argument list in place:
-- drop the 0060 signature first.
drop function public.create_invoice(uuid, uuid, text, jsonb, text);
create function public.create_invoice(
  p_workspace_id uuid,
  p_member_id uuid,
  p_title text,
  p_lines jsonb,
  p_period text default null,
  p_replaces uuid default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_subject public.members;
  v_workspace public.workspaces;
  v_replaced public.invoices;
  v_replaces_number text := '';
  v_line jsonb;
  v_total int := 0;
  v_count int;
  v_number text;
  v_member_name text;
  v_member_address text;
  v_issuer_name text;
  v_id uuid;
  v_signature text;
begin
  select * into v_actor from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if not public.is_owner_of(p_workspace_id) and not coalesce(
    (select w.feature_flags -> 'adminInvoicing' = to_jsonb(true)
       from public.workspaces w where w.id = p_workspace_id), false) then
    raise exception 'admins may not issue invoices here';
  end if;

  select * into v_subject from public.members
    where id = p_member_id and workspace_id = p_workspace_id
      and status = 'active' and not is_kiosk;
  if v_subject.id is null then raise exception 'unknown subject member'; end if;

  if p_title is null or btrim(p_title) = '' then
    raise exception 'title required';
  end if;
  if jsonb_typeof(p_lines) <> 'array'
     or jsonb_array_length(p_lines) = 0 then
    raise exception 'at least one line required';
  end if;
  for v_line in select * from jsonb_array_elements(p_lines) loop
    if jsonb_typeof(v_line -> 'label') <> 'string'
       or jsonb_typeof(v_line -> 'amount_cents') <> 'number' then
      raise exception 'invalid invoice line';
    end if;
    v_total := v_total + (v_line ->> 'amount_cents')::int;
  end loop;

  select * into v_workspace from public.workspaces where id = p_workspace_id;
  select coalesce(display_name, ''), coalesce(address, '')
    into v_member_name, v_member_address
    from public.profiles where id = v_subject.user_id;
  select coalesce(display_name, '') into v_issuer_name
    from public.profiles where id = v_actor.user_id;

  if p_replaces is not null then
    select * into v_replaced from public.invoices
      where id = p_replaces and workspace_id = p_workspace_id;
    if v_replaced.id is null then raise exception 'unknown invoice'; end if;
    if exists (select 1 from public.invoices
                where replaces_invoice_id = p_replaces) then
      raise exception 'invoice already replaced';
    end if;
    if v_replaced.voided_at is null then
      update public.invoices
         set voided_at = now(), voided_by_name = v_issuer_name
       where id = p_replaces;
    end if;
    v_replaces_number := v_replaced.number;
  end if;

  -- Per-workspace/year sequence under an advisory lock.
  perform pg_advisory_xact_lock(hashtext(p_workspace_id::text));
  select count(*) into v_count from public.invoices
    where workspace_id = p_workspace_id
      and date_part('year', issued_at) = date_part('year', now());
  v_number := 'INV-' || date_part('year', now())::int || '-'
      || lpad((v_count + 1)::text, 4, '0');

  v_id := gen_random_uuid();
  -- The digital signature: a SHA-256 fingerprint over the canonical
  -- content — the replacement reference is content and signs too.
  v_signature := encode(extensions.digest(convert_to(concat_ws('|',
      v_id::text, v_number, p_workspace_id::text, v_subject.id::text,
      v_member_name, v_member_address, v_workspace.name,
      coalesce(v_workspace.address, ''), v_issuer_name,
      p_title, p_lines::text, v_total::text, v_workspace.currency_code,
      now()::date::text, coalesce(p_replaces::text, ''),
      v_replaces_number), 'UTF8'), 'sha256'), 'hex');

  insert into public.invoices
    (id, workspace_id, member_id, issuer_member_id, number, period, title,
     lines, total_cents, currency, member_name, member_address,
     workspace_name, workspace_address, issuer_name, signature,
     replaces_invoice_id, replaces_number)
  values
    (v_id, p_workspace_id, v_subject.id, v_actor.id, v_number, p_period,
     btrim(p_title), p_lines, v_total, v_workspace.currency_code,
     v_member_name, v_member_address, v_workspace.name,
     coalesce(v_workspace.address, ''), v_issuer_name, v_signature,
     p_replaces, v_replaces_number);
  return v_id;
end;
$$;
revoke execute on function
  public.create_invoice(uuid, uuid, text, jsonb, text, uuid)
  from public, anon;

-- SPDX-License-Identifier: 0BSD
-- Invoice positions are DERIVED, never typed (field decision): the app
-- already tracks the subscription, consumption, supplements, services
-- and packages — the invoice is the payable summary of exactly that
-- month's positions. create_invoice therefore no longer accepts lines:
-- it builds them from member_statement + the period's confirmed ledger
-- charges, and creates NOTHING new. preview_invoice returns the same
-- lines without issuing, so the form can show what will be invoiced.
--
-- Line shape (structured, covered by the signature):
--   {"kind": text, "label": text, "quantity": int, "amount_cents": int}
-- kinds: subscription | overage | accessories | level | office | desk
--        | service | package | adjustment. The client renders localized
-- wording per kind; label carries data (pct, catalog names).

-- 1. The one line builder. Access control is inherited from
-- member_statement (admin of the workspace, or the member's own data —
-- it raises before anything else is read). Credits (payments, expense
-- reimbursements) are settlement, not positions; PENDING events are not
-- yet validated and are deliberately excluded — confirm them first.
create or replace function public.invoice_lines_for(
  p_member_id uuid,
  p_period text
) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_stmt jsonb;
  v_lines jsonb := '[]'::jsonb;
  v_row record;
begin
  v_stmt := public.member_statement(p_member_id, p_period);

  if (v_stmt->>'fee_cents')::int > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'subscription',
      'label', v_stmt->>'subscription_pct',
      'quantity', 1,
      'amount_cents', (v_stmt->>'fee_cents')::int);
  end if;
  if (v_stmt->>'overage_cents')::int > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'overage',
      'label', '',
      'quantity', (v_stmt->>'extra_half_days')::int,
      'amount_cents', (v_stmt->>'overage_cents')::int);
  end if;
  if coalesce((v_stmt->>'accessory_supplement_cents')::int, 0) > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'accessories', 'label', '', 'quantity', 1,
      'amount_cents', (v_stmt->>'accessory_supplement_cents')::int);
  end if;
  if coalesce((v_stmt->>'level_supplement_cents')::int, 0) > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'level', 'label', '', 'quantity', 1,
      'amount_cents', (v_stmt->>'level_supplement_cents')::int);
  end if;
  if coalesce((v_stmt->>'office_supplement_cents')::int, 0) > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'office', 'label', '', 'quantity', 1,
      'amount_cents', (v_stmt->>'office_supplement_cents')::int);
  end if;
  if coalesce((v_stmt->>'desk_supplement_cents')::int, 0) > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'desk', 'label', '', 'quantity', 1,
      'amount_cents', (v_stmt->>'desk_supplement_cents')::int);
  end if;

  -- Confirmed charge positions booked to the period, in booking order:
  -- consumed services, day packages, charging adjustments.
  for v_row in
    select category, description, amount_cents
      from public.ledger_entries
     where member_id = p_member_id
       and period = p_period
       and kind = 'charge'
       and category in ('service', 'package', 'adjustment')
     order by created_at
  loop
    v_lines := v_lines || jsonb_build_object(
      'kind', v_row.category,
      'label', v_row.description,
      'quantity', 1,
      'amount_cents', v_row.amount_cents);
  end loop;

  return v_lines;
end;
$$;
revoke execute on function public.invoice_lines_for(uuid, text)
  from public, anon;

-- 2. Preview: what create_invoice would issue, without issuing.
create or replace function public.preview_invoice(
  p_workspace_id uuid,
  p_member_id uuid,
  p_period text
) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_lines jsonb;
  v_total int;
begin
  if not exists (
    select 1 from public.members
     where id = p_member_id and workspace_id = p_workspace_id
  ) then
    raise exception 'unknown subject member';
  end if;
  v_lines := public.invoice_lines_for(p_member_id, p_period);
  select coalesce(sum((l->>'amount_cents')::int), 0) into v_total
    from jsonb_array_elements(v_lines) l;
  return jsonb_build_object('lines', v_lines, 'total_cents', v_total);
end;
$$;
revoke execute on function public.preview_invoice(uuid, uuid, text)
  from public, anon;

-- 3. create_invoice v3: member + period only. Title/period both carry
-- the period; positions come from invoice_lines_for. An empty month
-- refuses with a pinned error (nothing tracked = nothing to invoice).
drop function public.create_invoice(uuid, uuid, text, jsonb, text, uuid);
create function public.create_invoice(
  p_workspace_id uuid,
  p_member_id uuid,
  p_period text,
  p_replaces uuid default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_subject public.members;
  v_workspace public.workspaces;
  v_replaced public.invoices;
  v_replaces_number text := '';
  v_lines jsonb;
  v_total int := 0;
  v_count int;
  v_number text;
  v_member_name text;
  v_member_address text;
  v_issuer_name text;
  v_id uuid;
  v_signature text;
begin
  select * into v_actor from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if not public.is_owner_of(p_workspace_id) and not coalesce(
    (select w.feature_flags -> 'adminInvoicing' = to_jsonb(true)
       from public.workspaces w where w.id = p_workspace_id), false) then
    raise exception 'admins may not issue invoices here';
  end if;

  select * into v_subject from public.members
    where id = p_member_id and workspace_id = p_workspace_id
      and status = 'active' and not is_kiosk;
  if v_subject.id is null then raise exception 'unknown subject member'; end if;
  if p_period is null or p_period !~ '^[0-9]{4}-[0-9]{2}$' then
    raise exception 'invalid period';
  end if;

  -- The positions: exclusively what the month already tracked.
  v_lines := public.invoice_lines_for(p_member_id, p_period);
  if jsonb_array_length(v_lines) = 0 then
    raise exception 'nothing to invoice for this period';
  end if;
  select coalesce(sum((l->>'amount_cents')::int), 0) into v_total
    from jsonb_array_elements(v_lines) l;

  select * into v_workspace from public.workspaces where id = p_workspace_id;
  select coalesce(display_name, ''), coalesce(address, '')
    into v_member_name, v_member_address
    from public.profiles where id = v_subject.user_id;
  select coalesce(display_name, '') into v_issuer_name
    from public.profiles where id = v_actor.user_id;

  if p_replaces is not null then
    select * into v_replaced from public.invoices
      where id = p_replaces and workspace_id = p_workspace_id;
    if v_replaced.id is null then raise exception 'unknown invoice'; end if;
    if exists (select 1 from public.invoices
                where replaces_invoice_id = p_replaces) then
      raise exception 'invoice already replaced';
    end if;
    if v_replaced.voided_at is null then
      update public.invoices
         set voided_at = now(), voided_by_name = v_issuer_name
       where id = p_replaces;
    end if;
    v_replaces_number := v_replaced.number;
  end if;

  -- Per-workspace/year sequence under an advisory lock.
  perform pg_advisory_xact_lock(hashtext(p_workspace_id::text));
  select count(*) into v_count from public.invoices
    where workspace_id = p_workspace_id
      and date_part('year', issued_at) = date_part('year', now());
  v_number := 'INV-' || date_part('year', now())::int || '-'
      || lpad((v_count + 1)::text, 4, '0');

  v_id := gen_random_uuid();
  v_signature := encode(extensions.digest(convert_to(concat_ws('|',
      v_id::text, v_number, p_workspace_id::text, v_subject.id::text,
      v_member_name, v_member_address, v_workspace.name,
      coalesce(v_workspace.address, ''), v_issuer_name,
      p_period, v_lines::text, v_total::text, v_workspace.currency_code,
      now()::date::text, coalesce(p_replaces::text, ''),
      v_replaces_number), 'UTF8'), 'sha256'), 'hex');

  insert into public.invoices
    (id, workspace_id, member_id, issuer_member_id, number, period, title,
     lines, total_cents, currency, member_name, member_address,
     workspace_name, workspace_address, issuer_name, signature,
     replaces_invoice_id, replaces_number)
  values
    (v_id, p_workspace_id, v_subject.id, v_actor.id, v_number, p_period,
     p_period, v_lines, v_total, v_workspace.currency_code,
     v_member_name, v_member_address, v_workspace.name,
     coalesce(v_workspace.address, ''), v_issuer_name, v_signature,
     p_replaces, v_replaces_number);
  return v_id;
end;
$$;
revoke execute on function
  public.create_invoice(uuid, uuid, text, uuid)
  from public, anon;

-- SPDX-License-Identifier: 0BSD
-- Detailed invoices (field request): "if requested, a list of all
-- details (consumed services, payments and check-ins)". The annex is
-- part of the IMMUTABLE document, so it is SNAPSHOTTED at issue time
-- like everything else and covered by the signature:
--   details = {
--     'ledger':     [{on, category, description, amount_cents}],  -- signed
--     'attendance': [{starts_at, ends_at, space, status}]          -- local wall-clock
--   }
-- Compact invoices keep details null.

alter table public.invoices add column details jsonb;

-- create_invoice v4: + p_detailed. Postgres cannot change an argument
-- list in place — drop the 0062 signature first.
drop function public.create_invoice(uuid, uuid, text, uuid);
create function public.create_invoice(
  p_workspace_id uuid,
  p_member_id uuid,
  p_period text,
  p_replaces uuid default null,
  p_detailed boolean default false
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_subject public.members;
  v_workspace public.workspaces;
  v_replaced public.invoices;
  v_replaces_number text := '';
  v_lines jsonb;
  v_details jsonb := null;
  v_tz text;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_total int := 0;
  v_count int;
  v_number text;
  v_member_name text;
  v_member_address text;
  v_issuer_name text;
  v_id uuid;
  v_signature text;
begin
  select * into v_actor from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if not public.is_owner_of(p_workspace_id) and not coalesce(
    (select w.feature_flags -> 'adminInvoicing' = to_jsonb(true)
       from public.workspaces w where w.id = p_workspace_id), false) then
    raise exception 'admins may not issue invoices here';
  end if;

  select * into v_subject from public.members
    where id = p_member_id and workspace_id = p_workspace_id
      and status = 'active' and not is_kiosk;
  if v_subject.id is null then raise exception 'unknown subject member'; end if;
  if p_period is null or p_period !~ '^[0-9]{4}-[0-9]{2}$' then
    raise exception 'invalid period';
  end if;

  v_lines := public.invoice_lines_for(p_member_id, p_period);
  if jsonb_array_length(v_lines) = 0 then
    raise exception 'nothing to invoice for this period';
  end if;
  select coalesce(sum((l->>'amount_cents')::int), 0) into v_total
    from jsonb_array_elements(v_lines) l;

  select * into v_workspace from public.workspaces where id = p_workspace_id;
  select coalesce(display_name, ''), coalesce(address, '')
    into v_member_name, v_member_address
    from public.profiles where id = v_subject.user_id;
  select coalesce(display_name, '') into v_issuer_name
    from public.profiles where id = v_actor.user_id;

  if p_detailed then
    -- Same period window semantics as member_statement (workspace tz).
    v_tz := v_workspace.timezone;
    v_period_start := to_timestamp(p_period || '-01', 'YYYY-MM-DD') at time zone v_tz;
    v_period_end := (to_timestamp(p_period || '-01', 'YYYY-MM-DD') + interval '1 month') at time zone v_tz;
    v_details := jsonb_build_object(
      'ledger', coalesce((
        select jsonb_agg(jsonb_build_object(
            'on', le.created_at::date::text,
            'category', le.category,
            'description', le.description,
            'amount_cents', case when le.kind = 'credit'
                                 then -le.amount_cents
                                 else le.amount_cents end)
          order by le.created_at)
        from public.ledger_entries le
        where le.member_id = p_member_id and le.period = p_period
      ), '[]'::jsonb),
      'attendance', coalesce((
        select jsonb_agg(jsonb_build_object(
            'starts_at', to_char(r.starts_at at time zone v_tz,
                                 'YYYY-MM-DD"T"HH24:MI'),
            'ends_at', to_char(r.ends_at at time zone v_tz,
                               'YYYY-MM-DD"T"HH24:MI'),
            'status', r.status,
            'space', coalesce(
              (select s.name || ' · ' || d.name
                 from public.seats s
                 join public.desks d on d.id = s.desk_id
                where s.id = r.seat_id),
              (select d.name from public.desks d where d.id = r.desk_id),
              (select o.name from public.offices o where o.id = r.office_id),
              (select l.name from public.levels l where l.id = r.level_id),
              ''))
          order by r.starts_at)
        from public.reservations r
        where r.member_id = p_member_id
          and r.status in ('reserved', 'checked_in', 'completed')
          and r.starts_at >= v_period_start and r.starts_at < v_period_end
      ), '[]'::jsonb));
  end if;

  if p_replaces is not null then
    select * into v_replaced from public.invoices
      where id = p_replaces and workspace_id = p_workspace_id;
    if v_replaced.id is null then raise exception 'unknown invoice'; end if;
    if exists (select 1 from public.invoices
                where replaces_invoice_id = p_replaces) then
      raise exception 'invoice already replaced';
    end if;
    if v_replaced.voided_at is null then
      update public.invoices
         set voided_at = now(), voided_by_name = v_issuer_name
       where id = p_replaces;
    end if;
    v_replaces_number := v_replaced.number;
  end if;

  perform pg_advisory_xact_lock(hashtext(p_workspace_id::text));
  select count(*) into v_count from public.invoices
    where workspace_id = p_workspace_id
      and date_part('year', issued_at) = date_part('year', now());
  v_number := 'INV-' || date_part('year', now())::int || '-'
      || lpad((v_count + 1)::text, 4, '0');

  v_id := gen_random_uuid();
  -- The signature covers the annex too (empty string when compact).
  v_signature := encode(extensions.digest(convert_to(concat_ws('|',
      v_id::text, v_number, p_workspace_id::text, v_subject.id::text,
      v_member_name, v_member_address, v_workspace.name,
      coalesce(v_workspace.address, ''), v_issuer_name,
      p_period, v_lines::text, v_total::text, v_workspace.currency_code,
      now()::date::text, coalesce(p_replaces::text, ''),
      v_replaces_number, coalesce(v_details::text, '')),
      'UTF8'), 'sha256'), 'hex');

  insert into public.invoices
    (id, workspace_id, member_id, issuer_member_id, number, period, title,
     lines, total_cents, currency, member_name, member_address,
     workspace_name, workspace_address, issuer_name, signature,
     replaces_invoice_id, replaces_number, details)
  values
    (v_id, p_workspace_id, v_subject.id, v_actor.id, v_number, p_period,
     p_period, v_lines, v_total, v_workspace.currency_code,
     v_member_name, v_member_address, v_workspace.name,
     coalesce(v_workspace.address, ''), v_issuer_name, v_signature,
     p_replaces, v_replaces_number, v_details);
  return v_id;
end;
$$;
revoke execute on function
  public.create_invoice(uuid, uuid, text, uuid, boolean)
  from public, anon;

-- SPDX-License-Identifier: 0BSD
-- Whole-space SERIES (field request): tables and rooms/levels must
-- offer the same repetition as seats. create_series v2 accepts exactly
-- one of seat/desk/office/level. Whole-space targets pass the same
-- one-time gates as create_reservation (feature + personal grant +
-- bookable-as-whole) and each occurrence re-runs the same cross-scale
-- conflict checks; conflicting/closed/beyond-quota occurrences land in
-- the skipped report exactly like seat series. When the owner
-- configured a 'space_reservation' validation rule, every BOOKED
-- whole-space occurrence routes through the regular quorum (a reject
-- cancels just that occurrence via respond_to_event's existing branch).

drop function public.create_series(uuid, uuid, timestamptz, timestamptz, text, timestamptz);
create function public.create_series(
  p_workspace_id uuid,
  p_seat_id uuid,
  p_first_start timestamptz,
  p_first_end timestamptz,
  p_pattern text,
  p_until timestamptz,
  p_desk_id uuid default null,
  p_office_id uuid default null,
  p_level_id uuid default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_rules jsonb;
  v_max_days int;
  v_series_id uuid := gen_random_uuid();
  v_start timestamptz := p_first_start;
  v_end timestamptz := p_first_end;
  v_tz text;
  v_booked jsonb := '[]'::jsonb;
  v_skipped jsonb := '[]'::jsonb;
  v_step interval;
  v_dow int;
  v_office_of uuid;
  v_level_of uuid;
  v_space boolean;
  v_validated boolean := false;
  v_id uuid;
begin
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if p_pattern not in ('daily','weekdays','weekly') then
    raise exception 'unknown pattern';
  end if;
  if (case when p_seat_id is null then 0 else 1 end
      + case when p_desk_id is null then 0 else 1 end
      + case when p_office_id is null then 0 else 1 end
      + case when p_level_id is null then 0 else 1 end) <> 1 then
    raise exception 'exactly one of seat, desk, office or level required';
  end if;
  v_space := p_seat_id is null;

  select booking_rules, timezone into v_rules, v_tz
    from public.workspaces where id = p_workspace_id;
  v_max_days := coalesce((v_rules->>'max_series_days')::int, 180);
  if p_until > p_first_start + make_interval(days => v_max_days) then
    raise exception 'series exceeds the maximum of % days', v_max_days;
  end if;
  perform public.enforce_booking_rules(p_workspace_id, p_first_start, p_first_end);

  -- One-time whole-space gates — identical to create_reservation v7.
  if v_space then
    if not public.level_booking_enabled(p_workspace_id) then
      raise exception 'level booking is not enabled';
    end if;
    if not v_member.can_reserve_level then
      -- the client pins this substring (0050)
      raise exception 'not allowed to reserve a level';
    end if;
    if p_desk_id is not null then
      if not exists (
        select 1 from public.desks d
        where d.id = p_desk_id and d.workspace_id = p_workspace_id
          and d.bookable_as_whole
      ) then
        raise exception 'desk not bookable as a whole';
      end if;
      select d.office_id into v_office_of from public.desks d where d.id = p_desk_id;
      select o.level_id into v_level_of from public.offices o where o.id = v_office_of;
    elsif p_office_id is not null then
      if not exists (
        select 1 from public.offices o
        where o.id = p_office_id and o.workspace_id = p_workspace_id
          and o.bookable_as_whole
      ) then
        raise exception 'office not bookable as a whole';
      end if;
      select o.level_id into v_level_of from public.offices o where o.id = p_office_id;
    else
      if not exists (
        select 1 from public.levels l
        where l.id = p_level_id and l.workspace_id = p_workspace_id
          and l.bookable_as_whole
      ) then
        raise exception 'level not bookable as a whole';
      end if;
    end if;
    v_validated := exists (
      select 1 from public.validation_policies vp
      where vp.workspace_id = p_workspace_id
        and vp.event_type = 'space_reservation');
  end if;

  v_step := case when p_pattern = 'weekly' then interval '7 days' else interval '1 day' end;

  while v_start <= p_until loop
    -- weekday filter recurs in workspace-local time (spec §11 DST rule)
    v_dow := extract(isodow from v_start at time zone v_tz)::int;
    if p_pattern <> 'weekdays' or v_dow between 1 and 5 then
      begin
        -- closed days raise here and land in the skipped report, exactly
        -- like conflicts
        perform public.assert_workspace_open(p_workspace_id, v_start, v_end);
        if p_seat_id is not null then
          -- blocked seats too (#161)
          perform public.assert_seat_not_blocked(p_seat_id, v_start, v_end);
        elsif p_desk_id is not null then
          -- Cross-scale conflicts, desk scale (create_reservation v7).
          if exists (
            select 1 from public.reservations r
            join public.seats s on s.id = r.seat_id
            where s.desk_id = p_desk_id
              and r.status in ('reserved','checked_in')
              and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_start, v_end)
          ) then
            raise exception 'a seat on this desk is already reserved in that period';
          end if;
          if exists (
            select 1 from public.reservations r
            where r.office_id = v_office_of
              and r.status in ('reserved','checked_in')
              and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_start, v_end)
          ) then
            raise exception 'office is reserved as a whole in that period';
          end if;
          if exists (
            select 1 from public.reservations r
            where r.level_id = v_level_of
              and r.status in ('reserved','checked_in')
              and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_start, v_end)
          ) then
            raise exception 'level is reserved as a whole in that period';
          end if;
        elsif p_office_id is not null then
          if exists (
            select 1 from public.reservations r
            join public.seats s on s.id = r.seat_id
            join public.desks d on d.id = s.desk_id
            where d.office_id = p_office_id
              and r.status in ('reserved','checked_in')
              and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_start, v_end)
          ) then
            raise exception 'a seat in this office is already reserved in that period';
          end if;
          if exists (
            select 1 from public.reservations r
            join public.desks d on d.id = r.desk_id
            where d.office_id = p_office_id
              and r.status in ('reserved','checked_in')
              and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_start, v_end)
          ) then
            raise exception 'a desk in this office is already reserved in that period';
          end if;
          if exists (
            select 1 from public.reservations r
            where r.level_id = v_level_of
              and r.status in ('reserved','checked_in')
              and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_start, v_end)
          ) then
            raise exception 'level is reserved as a whole in that period';
          end if;
        else
          if public.level_has_conflict(p_level_id, v_start, v_end) then
            raise exception 'the level has reservations in that period';
          end if;
        end if;

        insert into public.reservations
          (workspace_id, seat_id, desk_id, office_id, level_id, member_id,
           starts_at, ends_at, status, series_id)
        values (p_workspace_id, p_seat_id, p_desk_id, p_office_id,
                p_level_id, v_member.id, v_start, v_end, 'reserved',
                v_series_id)
        returning id into v_id;
        -- beyond-quota instances are skipped, not booked
        perform public.assert_member_quota(v_member.id, v_start);
        if v_validated then
          update public.events
            set status = 'pending', type = 'space_reservation'
            where reservation_id = v_id and action = 'created';
        end if;
        v_booked := v_booked || to_jsonb(v_start);
      exception when others then
        v_skipped := v_skipped || to_jsonb(v_start);
      end;
    end if;
    v_start := v_start + v_step;
    v_end := v_end + v_step;
  end loop;

  return jsonb_build_object(
    'series_id', v_series_id,
    'booked', v_booked,
    'skipped', v_skipped
  );
end;
$$;
revoke execute on function public.create_series(
  uuid, uuid, timestamptz, timestamptz, text, timestamptz,
  uuid, uuid, uuid) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- Invoice payment reminders (field request). The invoice document
-- stays IMMUTABLE — reminders are collection metadata beside it, one
-- row per reminder sent, so the archive can show "reminded ×N · date".
-- Recording is gated exactly like issuing (owner always, admins via
-- the adminInvoicing flag); members see the reminders on their own
-- invoices like the invoices themselves.

create table public.invoice_reminders (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  invoice_id uuid not null references public.invoices(id) on delete cascade,
  sent_at timestamptz not null default now(),
  by_name text not null default ''
);
create index invoice_reminders_invoice_idx
  on public.invoice_reminders (invoice_id);
create index invoice_reminders_workspace_idx
  on public.invoice_reminders (workspace_id);

alter table public.invoice_reminders enable row level security;
create policy invoice_reminders_select on public.invoice_reminders
  for select using (
    public.is_admin_of(workspace_id)
    or exists (select 1
                 from public.invoices i
                 join public.members m on m.id = i.member_id
                where i.id = invoice_reminders.invoice_id
                  and m.user_id = auth.uid())
  );
-- No write policies: writes only through the RPC below.

create or replace function public.record_invoice_reminder(
  p_invoice_id uuid
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_invoice public.invoices;
  v_actor public.members;
  v_actor_name text;
begin
  select * into v_invoice from public.invoices where id = p_invoice_id;
  if v_invoice.id is null then raise exception 'unknown invoice'; end if;
  if v_invoice.voided_at is not null then
    raise exception 'invoice is voided';
  end if;
  select * into v_actor from public.members
    where workspace_id = v_invoice.workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if not public.is_owner_of(v_invoice.workspace_id) and not coalesce(
    (select w.feature_flags -> 'adminInvoicing' = to_jsonb(true)
       from public.workspaces w where w.id = v_invoice.workspace_id), false) then
    raise exception 'admins may not issue invoices here';
  end if;
  select coalesce(display_name, '') into v_actor_name
    from public.profiles where id = v_actor.user_id;
  insert into public.invoice_reminders (workspace_id, invoice_id, by_name)
  values (v_invoice.workspace_id, p_invoice_id, v_actor_name);
end;
$$;
revoke execute on function public.record_invoice_reminder(uuid)
  from public, anon;

-- SPDX-License-Identifier: 0BSD
-- Invoice LIFECYCLE (field decision):
--  * one ACTIVE invoice per member+month — a period becomes invoiceable
--    again only when its invoice was voided (erronée);
--  * an open invoice is closed by MATCHING it to its payment
--    (match_invoice): exact, overpaid (forced-OK with a mandatory note
--    OR a credit note over the excess), or underpaid accepted with a
--    mandatory note. Only matched invoices are archived.
--  * every match files an 'invoice_payment' event, so everyone with
--    invoicing access is notified; when the owner configures a
--    validation rule for it, the match stays PENDING until the quorum
--    confirms — a reject reopens the invoice (and reverts a credit
--    note).

-- 1. Event + policy vocabulary.
alter table public.events drop constraint events_type_check;
alter table public.events add constraint events_type_check check (type in
  ('reservation','payment','expense','adjustment','service_charge',
   'quota','role_change','member_join','space_reservation',
   'invoice_payment'));
alter table public.validation_policies
  drop constraint validation_policies_event_type_check;
alter table public.validation_policies
  add constraint validation_policies_event_type_check check (event_type in
  ('reservation','payment','expense','adjustment','service_charge',
   'quota','role_change','member_join','space_reservation',
   'invoice_payment'));

-- 2. One active invoice per member+month. Pre-0067 data may hold
-- duplicates (the rule did not exist): keep the NEWEST active invoice
-- per member+month and void the older ones (erronée) — the honest
-- backfill, visible in the archive like any other correction.
update public.invoices i
   set voided_at = now()
 where i.voided_at is null and i.period is not null
   and exists (
     select 1 from public.invoices j
     where j.member_id = i.member_id and j.period = i.period
       and j.voided_at is null
       and (j.issued_at > i.issued_at
            or (j.issued_at = i.issued_at and j.id > i.id)));

create unique index invoices_one_active_per_member_period
  on public.invoices (member_id, period)
  where voided_at is null and period is not null;

-- 3. The match — one per invoice, beside the immutable document.
create table public.invoice_matches (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  invoice_id uuid not null unique references public.invoices(id) on delete cascade,
  paid_cents int not null check (paid_cents >= 0),
  resolution text not null check (resolution in
    ('exact','over_forced','over_credit_note','under_accepted')),
  note text not null default '',
  status text not null default 'confirmed'
    check (status in ('pending','confirmed')),
  event_id uuid references public.events(id) on delete set null,
  credit_ledger_id uuid references public.ledger_entries(id) on delete set null,
  matched_at timestamptz not null default now(),
  by_name text not null default ''
);
create index invoice_matches_workspace_idx
  on public.invoice_matches (workspace_id);

alter table public.invoice_matches enable row level security;
create policy invoice_matches_select on public.invoice_matches
  for select using (
    public.is_admin_of(workspace_id)
    or exists (select 1
                 from public.invoices i
                 join public.members m on m.id = i.member_id
                where i.id = invoice_matches.invoice_id
                  and m.user_id = auth.uid())
  );
-- No write policies: writes only through match_invoice / respond_to_event.

-- 4. create_invoice v5: body = 0064 verbatim + the pinned uniqueness
-- refusal (the replaced invoice is excluded — it gets voided in this
-- very transaction).
create or replace function public.create_invoice(
  p_workspace_id uuid,
  p_member_id uuid,
  p_period text,
  p_replaces uuid default null,
  p_detailed boolean default false
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_subject public.members;
  v_workspace public.workspaces;
  v_replaced public.invoices;
  v_replaces_number text := '';
  v_lines jsonb;
  v_details jsonb := null;
  v_tz text;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_total int := 0;
  v_count int;
  v_number text;
  v_member_name text;
  v_member_address text;
  v_issuer_name text;
  v_id uuid;
  v_signature text;
begin
  select * into v_actor from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if not public.is_owner_of(p_workspace_id) and not coalesce(
    (select w.feature_flags -> 'adminInvoicing' = to_jsonb(true)
       from public.workspaces w where w.id = p_workspace_id), false) then
    raise exception 'admins may not issue invoices here';
  end if;

  select * into v_subject from public.members
    where id = p_member_id and workspace_id = p_workspace_id
      and status = 'active' and not is_kiosk;
  if v_subject.id is null then raise exception 'unknown subject member'; end if;
  if p_period is null or p_period !~ '^[0-9]{4}-[0-9]{2}$' then
    raise exception 'invalid period';
  end if;
  -- 0067: one ACTIVE invoice per member+month. Voided (erronée)
  -- invoices free their month; the one being replaced is voided below
  -- in this same transaction, so it does not count either.
  if exists (
    select 1 from public.invoices i
    where i.member_id = v_subject.id and i.period = p_period
      and i.voided_at is null and i.id is distinct from p_replaces
  ) then
    raise exception 'period already invoiced for this member';
  end if;

  v_lines := public.invoice_lines_for(p_member_id, p_period);
  if jsonb_array_length(v_lines) = 0 then
    raise exception 'nothing to invoice for this period';
  end if;
  select coalesce(sum((l->>'amount_cents')::int), 0) into v_total
    from jsonb_array_elements(v_lines) l;

  select * into v_workspace from public.workspaces where id = p_workspace_id;
  select coalesce(display_name, ''), coalesce(address, '')
    into v_member_name, v_member_address
    from public.profiles where id = v_subject.user_id;
  select coalesce(display_name, '') into v_issuer_name
    from public.profiles where id = v_actor.user_id;

  if p_detailed then
    v_tz := v_workspace.timezone;
    v_period_start := to_timestamp(p_period || '-01', 'YYYY-MM-DD') at time zone v_tz;
    v_period_end := (to_timestamp(p_period || '-01', 'YYYY-MM-DD') + interval '1 month') at time zone v_tz;
    v_details := jsonb_build_object(
      'ledger', coalesce((
        select jsonb_agg(jsonb_build_object(
            'on', le.created_at::date::text,
            'category', le.category,
            'description', le.description,
            'amount_cents', case when le.kind = 'credit'
                                 then -le.amount_cents
                                 else le.amount_cents end)
          order by le.created_at)
        from public.ledger_entries le
        where le.member_id = p_member_id and le.period = p_period
      ), '[]'::jsonb),
      'attendance', coalesce((
        select jsonb_agg(jsonb_build_object(
            'starts_at', to_char(r.starts_at at time zone v_tz,
                                 'YYYY-MM-DD"T"HH24:MI'),
            'ends_at', to_char(r.ends_at at time zone v_tz,
                               'YYYY-MM-DD"T"HH24:MI'),
            'status', r.status,
            'space', coalesce(
              (select s.name || ' · ' || d.name
                 from public.seats s
                 join public.desks d on d.id = s.desk_id
                where s.id = r.seat_id),
              (select d.name from public.desks d where d.id = r.desk_id),
              (select o.name from public.offices o where o.id = r.office_id),
              (select l.name from public.levels l where l.id = r.level_id),
              ''))
          order by r.starts_at)
        from public.reservations r
        where r.member_id = p_member_id
          and r.status in ('reserved', 'checked_in', 'completed')
          and r.starts_at >= v_period_start and r.starts_at < v_period_end
      ), '[]'::jsonb));
  end if;

  if p_replaces is not null then
    select * into v_replaced from public.invoices
      where id = p_replaces and workspace_id = p_workspace_id;
    if v_replaced.id is null then raise exception 'unknown invoice'; end if;
    if exists (select 1 from public.invoices
                where replaces_invoice_id = p_replaces) then
      raise exception 'invoice already replaced';
    end if;
    if v_replaced.voided_at is null then
      update public.invoices
         set voided_at = now(), voided_by_name = v_issuer_name
       where id = p_replaces;
    end if;
    v_replaces_number := v_replaced.number;
  end if;

  perform pg_advisory_xact_lock(hashtext(p_workspace_id::text));
  select count(*) into v_count from public.invoices
    where workspace_id = p_workspace_id
      and date_part('year', issued_at) = date_part('year', now());
  v_number := 'INV-' || date_part('year', now())::int || '-'
      || lpad((v_count + 1)::text, 4, '0');

  v_id := gen_random_uuid();
  v_signature := encode(extensions.digest(convert_to(concat_ws('|',
      v_id::text, v_number, p_workspace_id::text, v_subject.id::text,
      v_member_name, v_member_address, v_workspace.name,
      coalesce(v_workspace.address, ''), v_issuer_name,
      p_period, v_lines::text, v_total::text, v_workspace.currency_code,
      now()::date::text, coalesce(p_replaces::text, ''),
      v_replaces_number, coalesce(v_details::text, '')),
      'UTF8'), 'sha256'), 'hex');

  insert into public.invoices
    (id, workspace_id, member_id, issuer_member_id, number, period, title,
     lines, total_cents, currency, member_name, member_address,
     workspace_name, workspace_address, issuer_name, signature,
     replaces_invoice_id, replaces_number, details)
  values
    (v_id, p_workspace_id, v_subject.id, v_actor.id, v_number, p_period,
     p_period, v_lines, v_total, v_workspace.currency_code,
     v_member_name, v_member_address, v_workspace.name,
     coalesce(v_workspace.address, ''), v_issuer_name, v_signature,
     p_replaces, v_replaces_number, v_details);
  return v_id;
end;
$$;

-- 5. Match an open invoice to its payment.
create or replace function public.match_invoice(
  p_invoice_id uuid,
  p_paid_cents int,
  p_resolution text,
  p_note text default ''
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_invoice public.invoices;
  v_actor public.members;
  v_actor_name text;
  v_note text := btrim(coalesce(p_note, ''));
  v_has_policy boolean;
  v_event_id uuid;
  v_credit_id uuid := null;
begin
  select * into v_invoice from public.invoices where id = p_invoice_id;
  if v_invoice.id is null then raise exception 'unknown invoice'; end if;
  if v_invoice.voided_at is not null then
    raise exception 'invoice is voided';
  end if;
  if exists (select 1 from public.invoice_matches
              where invoice_id = p_invoice_id) then
    raise exception 'invoice already matched';
  end if;
  select * into v_actor from public.members
    where workspace_id = v_invoice.workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if not public.is_owner_of(v_invoice.workspace_id) and not coalesce(
    (select w.feature_flags -> 'adminInvoicing' = to_jsonb(true)
       from public.workspaces w where w.id = v_invoice.workspace_id), false) then
    raise exception 'admins may not issue invoices here';
  end if;

  if p_resolution not in
      ('exact','over_forced','over_credit_note','under_accepted') then
    raise exception 'unknown resolution';
  end if;
  if p_paid_cents < 0 then raise exception 'invalid amount'; end if;
  if p_resolution = 'exact' and p_paid_cents <> v_invoice.total_cents then
    raise exception 'amount does not match the invoice';
  end if;
  if p_resolution in ('over_forced','over_credit_note')
     and p_paid_cents <= v_invoice.total_cents then
    raise exception 'amount does not exceed the invoice';
  end if;
  if p_resolution = 'under_accepted'
     and p_paid_cents >= v_invoice.total_cents then
    raise exception 'amount is not below the invoice';
  end if;
  -- The mandatory message on both forced paths (field decision).
  if p_resolution in ('over_forced','under_accepted') and v_note = '' then
    raise exception 'a note is required';
  end if;

  select coalesce(display_name, '') into v_actor_name
    from public.profiles where id = v_actor.user_id;

  -- Overpayment as a CREDIT NOTE: the excess becomes an account credit
  -- for the member's current month, carried by the regular ledger.
  if p_resolution = 'over_credit_note' then
    insert into public.ledger_entries
      (workspace_id, member_id, kind, category, amount_cents,
       description, period)
    values
      (v_invoice.workspace_id, v_invoice.member_id, 'credit',
       'adjustment', p_paid_cents - v_invoice.total_cents,
       'Credit note ' || v_invoice.number
         || case when v_note = '' then '' else ' — ' || v_note end,
       to_char(now(), 'YYYY-MM'))
    returning id into v_credit_id;
  end if;

  v_has_policy := exists (
    select 1 from public.validation_policies vp
    where vp.workspace_id = v_invoice.workspace_id
      and vp.event_type = 'invoice_payment');

  -- The notification spine: everyone with invoicing access sees the
  -- paid invoice in the events feed; with a policy the match awaits
  -- the quorum (push fan-out fires on pending).
  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id,
     payload, status, decided_at)
  values
    (v_invoice.workspace_id, 'invoice_payment', 'submitted',
     v_actor.id, v_invoice.member_id,
     jsonb_build_object(
       'invoice_id', v_invoice.id,
       'number', v_invoice.number,
       'due_cents', v_invoice.total_cents,
       'paid_cents', p_paid_cents,
       'amount_cents', p_paid_cents,
       'resolution', p_resolution,
       'note', v_note),
     case when v_has_policy then 'pending' else 'confirmed' end,
     case when v_has_policy then null else now() end)
  returning id into v_event_id;

  insert into public.invoice_matches
    (workspace_id, invoice_id, paid_cents, resolution, note, status,
     event_id, credit_ledger_id, by_name)
  values
    (v_invoice.workspace_id, p_invoice_id, p_paid_cents, p_resolution,
     v_note, case when v_has_policy then 'pending' else 'confirmed' end,
     v_event_id, v_credit_id, v_actor_name);
end;
$$;
revoke execute on function
  public.match_invoice(uuid, int, text, text) from public, anon;

-- 6. respond_to_event: body = 0052 verbatim + the invoice_payment
-- branches — a reject REOPENS the invoice (deletes the match and
-- reverts its credit note), a confirm settles the match.
create or replace function public.respond_to_event(
  p_event_id uuid,
  p_accept boolean
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_event public.events;
  v_caller public.members;
  v_policy record;
  v_subject_decides boolean;
  v_in_pool boolean;
  v_pool_size int;
  v_required int;
  v_accepts int;
  v_subject_ok boolean;
  v_owner_ok boolean;
begin
  select e.* into v_event from public.events e where e.id = p_event_id;
  if v_event.id is null then raise exception 'unknown event'; end if;
  if v_event.status <> 'pending' then raise exception 'already decided'; end if;

  select m.* into v_caller from public.members m
    where m.workspace_id = v_event.workspace_id and m.user_id = auth.uid()
      and m.status = 'active';
  if v_caller.id is null then raise exception 'not a member'; end if;
  if exists (select 1 from public.event_decisions d
              where d.event_id = p_event_id and d.member_id = v_caller.id) then
    raise exception 'you already decided this event';
  end if;

  select * into v_policy from public.validation_policies
    where workspace_id = v_event.workspace_id and event_type = v_event.type;
  if v_policy is null then
    select * into v_policy from public.validation_policies
      where workspace_id = v_event.workspace_id and event_type is null;
  end if;
  if v_policy is null then
    select null::uuid as id, v_event.workspace_id as workspace_id,
           null::text as event_type, 1 as required_count,
           true as admins_may_validate, '{}'::uuid[] as eligible_admin_ids,
           false as owner_required
      into v_policy;
  end if;

  v_subject_decides := v_event.type = 'reservation'
    or (v_event.type in ('payment','service_charge')
        and v_event.actor_member_id <> v_event.subject_member_id);

  select count(*) into v_pool_size from public.members m
    where m.workspace_id = v_event.workspace_id and m.status = 'active'
      and m.id not in (v_event.actor_member_id, v_event.subject_member_id)
      and (m.is_owner or (m.is_admin and v_policy.admins_may_validate
           and (cardinality(v_policy.eligible_admin_ids) = 0
                or m.id = any(v_policy.eligible_admin_ids))));

  v_in_pool := (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate
                and (cardinality(v_policy.eligible_admin_ids) = 0
                     or v_caller.id = any(v_policy.eligible_admin_ids))))
    and (v_caller.id <> v_event.subject_member_id
         or (not v_subject_decides and v_pool_size = 0))
    and (v_caller.id <> v_event.actor_member_id or v_pool_size = 0);
  if v_pool_size = 0 and (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate)) then
    v_pool_size := 1;
  end if;

  if v_subject_decides and v_caller.id = v_event.subject_member_id then
    null;
  elsif v_in_pool then
    null;
  else
    raise exception 'you are not an eligible validator for this event';
  end if;

  insert into public.event_decisions (event_id, member_id, decision)
  values (p_event_id, v_caller.id, case when p_accept then 'accept' else 'reject' end);

  if not p_accept then
    update public.events set status = 'rejected', decided_at = now()
      where id = p_event_id;
    if v_event.reservation_id is not null then
      update public.reservations set status = 'cancelled'
        where id = v_event.reservation_id and status in ('reserved','checked_in');
    end if;
    if v_event.type = 'member_join' then
      -- a refused join exits the pending membership
      update public.members set status = 'exited'
        where id = v_event.subject_member_id and status = 'pending';
    end if;
    if v_event.type = 'invoice_payment' then
      -- 0067: the rejected match REOPENS the invoice — revert its
      -- credit note (if any) and drop the match.
      delete from public.ledger_entries
        where id = (select credit_ledger_id from public.invoice_matches
                     where event_id = v_event.id);
      delete from public.invoice_matches where event_id = v_event.id;
    end if;
    return;
  end if;

  select count(*) into v_accepts from public.event_decisions
    where event_id = p_event_id and decision = 'accept';
  v_required := greatest(1, least(v_policy.required_count,
    v_pool_size + case when v_subject_decides then 1 else 0 end));
  v_subject_ok := not v_subject_decides or exists (
    select 1 from public.event_decisions d
    where d.event_id = p_event_id and d.decision = 'accept'
      and d.member_id = v_event.subject_member_id);
  v_owner_ok := not v_policy.owner_required or exists (
    select 1 from public.event_decisions d
    join public.members m on m.id = d.member_id
    where d.event_id = p_event_id and d.decision = 'accept' and m.is_owner);

  if v_accepts >= v_required and v_subject_ok and v_owner_ok then
    update public.events set status = 'confirmed', decided_at = now()
      where id = p_event_id;

    if v_event.type in ('payment','expense') then
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description, period, event_id)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'credit',
        case when v_event.type = 'payment' then 'payment' else 'expense' end,
        (v_event.payload->>'amount_cents')::int,
        coalesce(v_event.payload->>'note', ''),
        to_char(now(), 'YYYY-MM'),
        v_event.id
      );
    elsif v_event.type = 'service_charge' then
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description, period, event_id)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'charge', 'service',
        (v_event.payload->>'amount_cents')::int,
        (v_event.payload->>'name') || ' x' || (v_event.payload->>'quantity'),
        coalesce(v_event.payload->>'period', to_char(now(), 'YYYY-MM')),
        v_event.id
      );
    elsif v_event.type = 'quota' then
      insert into public.quota_extensions
        (workspace_id, member_id, period, half_days, event_id)
      values (
        v_event.workspace_id, v_event.subject_member_id,
        v_event.payload->>'period',
        (v_event.payload->>'half_days')::int,
        v_event.id
      );
    elsif v_event.type = 'role_change' then
      update public.members
        set is_admin = (v_event.payload->>'make_admin')::boolean
        where id = v_event.subject_member_id;
    elsif v_event.type = 'member_join' then
      -- the validated welcome: the pending membership becomes active
      update public.members set status = 'active'
        where id = v_event.subject_member_id and status = 'pending';
    elsif v_event.type = 'invoice_payment' then
      -- 0067: the quorum stands behind the match.
      update public.invoice_matches set status = 'confirmed'
        where event_id = v_event.id;
    end if;
  end if;
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- Payment-LINKED matching (field decision): the user never types an
-- amount — the match maps the invoice to a REGISTERED payment (a
-- confirmed ledger payment credit, which is also where online payments
-- land after settlement). Each payment can settle at most one invoice.
-- And a PAID invoice is DEFINITIVE: it can no longer be voided or
-- replaced — corrections stop at the match.

-- 1. The consumed payment, one invoice per payment.
alter table public.invoice_matches
  add column payment_ledger_id uuid
    references public.ledger_entries(id) on delete restrict;
create unique index invoice_matches_payment_unique
  on public.invoice_matches (payment_ledger_id)
  where payment_ledger_id is not null;

-- 2. match_invoice v2: amount comes FROM the selected payment.
drop function public.match_invoice(uuid, int, text, text);
create function public.match_invoice(
  p_invoice_id uuid,
  p_payment_ledger_id uuid,
  p_resolution text,
  p_note text default ''
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_invoice public.invoices;
  v_payment public.ledger_entries;
  v_paid int;
  v_actor public.members;
  v_actor_name text;
  v_note text := btrim(coalesce(p_note, ''));
  v_has_policy boolean;
  v_event_id uuid;
  v_credit_id uuid := null;
begin
  select * into v_invoice from public.invoices where id = p_invoice_id;
  if v_invoice.id is null then raise exception 'unknown invoice'; end if;
  if v_invoice.voided_at is not null then
    raise exception 'invoice is voided';
  end if;
  if exists (select 1 from public.invoice_matches
              where invoice_id = p_invoice_id) then
    raise exception 'invoice already matched';
  end if;
  select * into v_actor from public.members
    where workspace_id = v_invoice.workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if not public.is_owner_of(v_invoice.workspace_id) and not coalesce(
    (select w.feature_flags -> 'adminInvoicing' = to_jsonb(true)
       from public.workspaces w where w.id = v_invoice.workspace_id), false) then
    raise exception 'admins may not issue invoices here';
  end if;

  -- The REGISTERED payment being mapped (field decision: never a typed
  -- amount). Must belong to the invoice's member, be a confirmed
  -- payment credit, and not already settle another invoice.
  select * into v_payment from public.ledger_entries
    where id = p_payment_ledger_id
      and workspace_id = v_invoice.workspace_id
      and member_id = v_invoice.member_id
      and kind = 'credit' and category = 'payment';
  if v_payment.id is null then raise exception 'unknown payment'; end if;
  if exists (select 1 from public.invoice_matches
              where payment_ledger_id = p_payment_ledger_id) then
    raise exception 'payment already matched';
  end if;
  v_paid := v_payment.amount_cents;

  if p_resolution not in
      ('exact','over_forced','over_credit_note','under_accepted') then
    raise exception 'unknown resolution';
  end if;
  if p_resolution = 'exact' and v_paid <> v_invoice.total_cents then
    raise exception 'amount does not match the invoice';
  end if;
  if p_resolution in ('over_forced','over_credit_note')
     and v_paid <= v_invoice.total_cents then
    raise exception 'amount does not exceed the invoice';
  end if;
  if p_resolution = 'under_accepted'
     and v_paid >= v_invoice.total_cents then
    raise exception 'amount is not below the invoice';
  end if;
  if p_resolution in ('over_forced','under_accepted') and v_note = '' then
    raise exception 'a note is required';
  end if;

  select coalesce(display_name, '') into v_actor_name
    from public.profiles where id = v_actor.user_id;

  if p_resolution = 'over_credit_note' then
    insert into public.ledger_entries
      (workspace_id, member_id, kind, category, amount_cents,
       description, period)
    values
      (v_invoice.workspace_id, v_invoice.member_id, 'credit',
       'adjustment', v_paid - v_invoice.total_cents,
       'Credit note ' || v_invoice.number
         || case when v_note = '' then '' else ' — ' || v_note end,
       to_char(now(), 'YYYY-MM'))
    returning id into v_credit_id;
  end if;

  v_has_policy := exists (
    select 1 from public.validation_policies vp
    where vp.workspace_id = v_invoice.workspace_id
      and vp.event_type = 'invoice_payment');

  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id,
     payload, status, decided_at)
  values
    (v_invoice.workspace_id, 'invoice_payment', 'submitted',
     v_actor.id, v_invoice.member_id,
     jsonb_build_object(
       'invoice_id', v_invoice.id,
       'number', v_invoice.number,
       'due_cents', v_invoice.total_cents,
       'paid_cents', v_paid,
       'amount_cents', v_paid,
       'payment_ledger_id', p_payment_ledger_id,
       'resolution', p_resolution,
       'note', v_note),
     case when v_has_policy then 'pending' else 'confirmed' end,
     case when v_has_policy then null else now() end)
  returning id into v_event_id;

  insert into public.invoice_matches
    (workspace_id, invoice_id, paid_cents, resolution, note, status,
     event_id, credit_ledger_id, payment_ledger_id, by_name)
  values
    (v_invoice.workspace_id, p_invoice_id, v_paid, p_resolution,
     v_note, case when v_has_policy then 'pending' else 'confirmed' end,
     v_event_id, v_credit_id, p_payment_ledger_id, v_actor_name);
end;
$$;
revoke execute on function
  public.match_invoice(uuid, uuid, text, text) from public, anon;

-- 3. A PAID invoice is definitive: voiding refuses (pinned substring).
create or replace function public.void_invoice(p_invoice_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_invoice public.invoices;
  v_actor public.members;
  v_actor_name text;
begin
  select * into v_invoice from public.invoices where id = p_invoice_id;
  if v_invoice.id is null then raise exception 'unknown invoice'; end if;
  if exists (select 1 from public.invoice_matches
              where invoice_id = p_invoice_id) then
    -- 0068: a paid (or awaiting-validation) invoice is definitive.
    raise exception 'invoice is matched';
  end if;
  select * into v_actor from public.members
    where workspace_id = v_invoice.workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if not public.is_owner_of(v_invoice.workspace_id) and not coalesce(
    (select w.feature_flags -> 'adminInvoicing' = to_jsonb(true)
       from public.workspaces w where w.id = v_invoice.workspace_id), false) then
    raise exception 'admins may not issue invoices here';
  end if;
  if v_invoice.voided_at is not null then
    raise exception 'invoice already voided';
  end if;
  select coalesce(display_name, '') into v_actor_name
    from public.profiles where id = v_actor.user_id;
  update public.invoices
     set voided_at = now(), voided_by_name = v_actor_name
   where id = p_invoice_id;
end;
$$;

-- 4. create_invoice v6: replacing a MATCHED invoice refuses too.
create or replace function public.create_invoice(
  p_workspace_id uuid,
  p_member_id uuid,
  p_period text,
  p_replaces uuid default null,
  p_detailed boolean default false
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_subject public.members;
  v_workspace public.workspaces;
  v_replaced public.invoices;
  v_replaces_number text := '';
  v_lines jsonb;
  v_details jsonb := null;
  v_tz text;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_total int := 0;
  v_count int;
  v_number text;
  v_member_name text;
  v_member_address text;
  v_issuer_name text;
  v_id uuid;
  v_signature text;
begin
  select * into v_actor from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if not public.is_owner_of(p_workspace_id) and not coalesce(
    (select w.feature_flags -> 'adminInvoicing' = to_jsonb(true)
       from public.workspaces w where w.id = p_workspace_id), false) then
    raise exception 'admins may not issue invoices here';
  end if;

  select * into v_subject from public.members
    where id = p_member_id and workspace_id = p_workspace_id
      and status = 'active' and not is_kiosk;
  if v_subject.id is null then raise exception 'unknown subject member'; end if;
  if p_period is null or p_period !~ '^[0-9]{4}-[0-9]{2}$' then
    raise exception 'invalid period';
  end if;
  -- 0067: one ACTIVE invoice per member+month. Voided (erronée)
  -- invoices free their month; the one being replaced is voided below
  -- in this same transaction, so it does not count either.
  if exists (
    select 1 from public.invoices i
    where i.member_id = v_subject.id and i.period = p_period
      and i.voided_at is null and i.id is distinct from p_replaces
  ) then
    raise exception 'period already invoiced for this member';
  end if;

  v_lines := public.invoice_lines_for(p_member_id, p_period);
  if jsonb_array_length(v_lines) = 0 then
    raise exception 'nothing to invoice for this period';
  end if;
  select coalesce(sum((l->>'amount_cents')::int), 0) into v_total
    from jsonb_array_elements(v_lines) l;

  select * into v_workspace from public.workspaces where id = p_workspace_id;
  select coalesce(display_name, ''), coalesce(address, '')
    into v_member_name, v_member_address
    from public.profiles where id = v_subject.user_id;
  select coalesce(display_name, '') into v_issuer_name
    from public.profiles where id = v_actor.user_id;

  if p_detailed then
    v_tz := v_workspace.timezone;
    v_period_start := to_timestamp(p_period || '-01', 'YYYY-MM-DD') at time zone v_tz;
    v_period_end := (to_timestamp(p_period || '-01', 'YYYY-MM-DD') + interval '1 month') at time zone v_tz;
    v_details := jsonb_build_object(
      'ledger', coalesce((
        select jsonb_agg(jsonb_build_object(
            'on', le.created_at::date::text,
            'category', le.category,
            'description', le.description,
            'amount_cents', case when le.kind = 'credit'
                                 then -le.amount_cents
                                 else le.amount_cents end)
          order by le.created_at)
        from public.ledger_entries le
        where le.member_id = p_member_id and le.period = p_period
      ), '[]'::jsonb),
      'attendance', coalesce((
        select jsonb_agg(jsonb_build_object(
            'starts_at', to_char(r.starts_at at time zone v_tz,
                                 'YYYY-MM-DD"T"HH24:MI'),
            'ends_at', to_char(r.ends_at at time zone v_tz,
                               'YYYY-MM-DD"T"HH24:MI'),
            'status', r.status,
            'space', coalesce(
              (select s.name || ' · ' || d.name
                 from public.seats s
                 join public.desks d on d.id = s.desk_id
                where s.id = r.seat_id),
              (select d.name from public.desks d where d.id = r.desk_id),
              (select o.name from public.offices o where o.id = r.office_id),
              (select l.name from public.levels l where l.id = r.level_id),
              ''))
          order by r.starts_at)
        from public.reservations r
        where r.member_id = p_member_id
          and r.status in ('reserved', 'checked_in', 'completed')
          and r.starts_at >= v_period_start and r.starts_at < v_period_end
      ), '[]'::jsonb));
  end if;

  if p_replaces is not null then
    select * into v_replaced from public.invoices
      where id = p_replaces and workspace_id = p_workspace_id;
    if v_replaced.id is null then raise exception 'unknown invoice'; end if;
    if exists (select 1 from public.invoices
                where replaces_invoice_id = p_replaces) then
      raise exception 'invoice already replaced';
    end if;
    if exists (select 1 from public.invoice_matches
                where invoice_id = p_replaces) then
      -- 0068: a paid invoice is definitive — no replacement either.
      raise exception 'invoice is matched';
    end if;
    if v_replaced.voided_at is null then
      update public.invoices
         set voided_at = now(), voided_by_name = v_issuer_name
       where id = p_replaces;
    end if;
    v_replaces_number := v_replaced.number;
  end if;

  perform pg_advisory_xact_lock(hashtext(p_workspace_id::text));
  select count(*) into v_count from public.invoices
    where workspace_id = p_workspace_id
      and date_part('year', issued_at) = date_part('year', now());
  v_number := 'INV-' || date_part('year', now())::int || '-'
      || lpad((v_count + 1)::text, 4, '0');

  v_id := gen_random_uuid();
  v_signature := encode(extensions.digest(convert_to(concat_ws('|',
      v_id::text, v_number, p_workspace_id::text, v_subject.id::text,
      v_member_name, v_member_address, v_workspace.name,
      coalesce(v_workspace.address, ''), v_issuer_name,
      p_period, v_lines::text, v_total::text, v_workspace.currency_code,
      now()::date::text, coalesce(p_replaces::text, ''),
      v_replaces_number, coalesce(v_details::text, '')),
      'UTF8'), 'sha256'), 'hex');

  insert into public.invoices
    (id, workspace_id, member_id, issuer_member_id, number, period, title,
     lines, total_cents, currency, member_name, member_address,
     workspace_name, workspace_address, issuer_name, signature,
     replaces_invoice_id, replaces_number, details)
  values
    (v_id, p_workspace_id, v_subject.id, v_actor.id, v_number, p_period,
     p_period, v_lines, v_total, v_workspace.currency_code,
     v_member_name, v_member_address, v_workspace.name,
     coalesce(v_workspace.address, ''), v_issuer_name, v_signature,
     p_replaces, v_replaces_number, v_details);
  return v_id;
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- The e-invoice was structurally invalid: EN 16931 rule BR-CO-26 is
-- FATAL and demands at least one seller identifier (BT-29 seller id,
-- BT-30 legal registration id, BT-31 VAT id) — the app carried none, so
-- every exported XML was rejected by any validator. And the tax coding
-- was a guess: category `O` (out of scope) forbids a seller tax
-- identifier (BR-O-02), while a small operator under a national VAT
-- exemption belongs in category `E` WITH an identifier and an exemption
-- reason (BR-E-02, BR-E-10).
--
-- So the workspace now carries a LEGAL IDENTITY (owner-edited), the
-- member profile carries the two buyer facts the norm needs, and every
-- invoice SNAPSHOTS both parties — an issued document must keep saying
-- what it said, even after the workspace changes its VAT regime.

-- 1. The seller's legal identity. Split address parts (BT-35/37/38)
-- beside the free-text `address` the PDF letterhead prints: national
-- CIUS profiles want the city and the post code as their own fields.
alter table public.workspaces
  add column vat_regime text not null default 'not_subject'
    check (vat_regime in ('not_subject', 'exempt', 'vat_registered')),
  add column vat_id text not null default ''
    check (char_length(vat_id) <= 20),
  add column legal_id text not null default ''
    check (char_length(legal_id) <= 30),
  add column tax_exemption_reason text not null default ''
    check (char_length(tax_exemption_reason) <= 120),
  add column street text not null default ''
    check (char_length(street) <= 120),
  add column city text not null default ''
    check (char_length(city) <= 60),
  add column postal_code text not null default ''
    check (char_length(postal_code) <= 12);

comment on column public.workspaces.vat_regime is
  'EN 16931 BT-151 mapping: not_subject → category O (no seller tax id '
  'allowed, BR-O-02), exempt → category E (seller tax id + exemption '
  'reason required, BR-E-02/BR-E-10), vat_registered → the app does not '
  'compute VAT yet, so the XML export refuses.';

-- 2. The buyer facts the norm needs beyond the name: the country (BT-55
-- is mandatory — defaulting it to the workspace country silently
-- mis-declares a foreign customer) and the VAT id of a business member
-- (BT-48).
alter table public.profiles
  add column country_code text not null default ''
    check (country_code = '' or country_code ~ '^[A-Z]{2}$'),
  add column vat_id text not null default ''
    check (char_length(vat_id) <= 20);

-- 3. The immutable snapshot. Legacy invoices keep `parties = null` and
-- render from the flat 0060 columns.
alter table public.invoices add column parties jsonb;

comment on column public.invoices.parties is
  'Issue-time snapshot of both parties for the e-invoice: seller legal '
  'identity + VAT regime, buyer country + VAT id. Frozen like every '
  'other invoice field.';

-- 4. create_invoice v7: the 0068 body plus the parties snapshot, which
