-- SPDX-License-Identifier: 0BSD
-- A recorded payment had no date and no target month: the ledger stamped
-- it the moment it was typed in and booked it to `to_char(now())`. A
-- transfer made on the 3rd and entered on the 26th therefore landed on the
-- wrong day AND — at a month boundary — on the wrong bill and the wrong
-- invoice, which the 0067/0068 matching then had to work around.
--
-- Two facts, declared by the payer:
--   * WHEN the money moved → `ledger_entries.occurred_on` (a DATE: what
--     matters is the day, in the payer's own calendar, not an instant);
--   * WHICH month it settles → the ledger `period`, which decides the
--     statement and the invoice the credit belongs to.
--
-- `created_at` stays exactly what it was: the audit stamp of the booking.
--
-- Applied to staging 2026-07-27 as two migration rows
-- (`payment_date_and_period` = sections 1–3, `invoice_annex_occurred_on`
-- = section 4); this file is the single source of truth for a rebuild.

-- 1. The business date beside the audit stamp. Nullable on purpose:
-- pre-0070 rows have none, and entries where booking IS the event (an
-- online payment settling, a credit note) keep falling back to created_at.
alter table public.ledger_entries add column occurred_on date;

comment on column public.ledger_entries.occurred_on is
  'The day the money actually moved, as declared by the payer. NULL = '
  'the booking date (created_at) is the truth. Never rewrites created_at, '
  'which stays the audit stamp.';

-- 2. record_payment v3: the two declared facts ride in the event payload
-- until the quorum confirms. Both optional — an old client keeps the old
-- behaviour exactly (today, current month).
drop function if exists public.record_payment(uuid, uuid, int, text, text);
create function public.record_payment(
  p_workspace_id uuid,
  p_member_id uuid,
  p_amount_cents int,
  p_note text default '',
  p_method text default '',
  p_paid_on date default null,
  p_period text default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_event_id uuid;
  v_paid_on date := coalesce(p_paid_on, current_date);
  v_period text := coalesce(p_period, to_char(now(), 'YYYY-MM'));
begin
  select * into v_actor from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_actor.id is null then raise exception 'not an active member'; end if;
  if p_amount_cents <= 0 then raise exception 'amount must be positive'; end if;
  if v_actor.id <> p_member_id and not (v_actor.is_admin or v_actor.is_owner) then
    raise exception 'only admins record payments for others';
  end if;
  -- Free-form-but-bounded method tag; the app sends one of the
  -- PaymentMethod enum wire names ('' = not specified, old clients).
  if length(p_method) > 32 then raise exception 'method too long'; end if;
  if v_period !~ '^[0-9]{4}-[0-9]{2}$' then raise exception 'invalid period'; end if;
  -- Money cannot have moved tomorrow. One day of slack absorbs the gap
  -- between the server's UTC date and a workspace east of it.
  if v_paid_on > current_date + 1 then
    raise exception 'payment date is in the future';
  end if;
  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id, payload, status)
  values (
    p_workspace_id, 'payment', 'submitted', v_actor.id, p_member_id,
    jsonb_build_object(
      'amount_cents', p_amount_cents,
      'note', p_note,
      'method', p_method,
      'paid_on', v_paid_on,
      'period', v_period
    ),
    'pending'
  ) returning id into v_event_id;
  return v_event_id;
end;
$$;

-- Same hardening as 0004/0008/0019: only signed-in members may call it.
revoke execute on function
  public.record_payment(uuid, uuid, int, text, text, date, text)
  from public, anon;

-- 3. respond_to_event: the 0067 body, with the payment/expense ledger
-- insert reading the two declared facts out of the payload. Everything
-- else is verbatim — a payload without them behaves exactly as before.
create or replace function public.respond_to_event(
  p_event_id uuid,
  p_accept boolean
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_event public.events;
  v_caller public.members;
  v_policy record;
  v_subject_decides boolean;
  v_in_pool boolean;
  v_pool_size int;
  v_required int;
  v_accepts int;
  v_subject_ok boolean;
  v_owner_ok boolean;
begin
  select e.* into v_event from public.events e where e.id = p_event_id;
  if v_event.id is null then raise exception 'unknown event'; end if;
  if v_event.status <> 'pending' then raise exception 'already decided'; end if;

  select m.* into v_caller from public.members m
    where m.workspace_id = v_event.workspace_id and m.user_id = auth.uid()
      and m.status = 'active';
  if v_caller.id is null then raise exception 'not a member'; end if;
  if exists (select 1 from public.event_decisions d
              where d.event_id = p_event_id and d.member_id = v_caller.id) then
    raise exception 'you already decided this event';
  end if;

  select * into v_policy from public.validation_policies
    where workspace_id = v_event.workspace_id and event_type = v_event.type;
  if v_policy is null then
    select * into v_policy from public.validation_policies
      where workspace_id = v_event.workspace_id and event_type is null;
  end if;
  if v_policy is null then
    select null::uuid as id, v_event.workspace_id as workspace_id,
           null::text as event_type, 1 as required_count,
           true as admins_may_validate, '{}'::uuid[] as eligible_admin_ids,
           false as owner_required
      into v_policy;
  end if;

  v_subject_decides := v_event.type = 'reservation'
    or (v_event.type in ('payment','service_charge')
        and v_event.actor_member_id <> v_event.subject_member_id);

  select count(*) into v_pool_size from public.members m
    where m.workspace_id = v_event.workspace_id and m.status = 'active'
      and m.id not in (v_event.actor_member_id, v_event.subject_member_id)
      and (m.is_owner or (m.is_admin and v_policy.admins_may_validate
           and (cardinality(v_policy.eligible_admin_ids) = 0
                or m.id = any(v_policy.eligible_admin_ids))));

  v_in_pool := (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate
                and (cardinality(v_policy.eligible_admin_ids) = 0
                     or v_caller.id = any(v_policy.eligible_admin_ids))))
    and (v_caller.id <> v_event.subject_member_id
         or (not v_subject_decides and v_pool_size = 0))
    and (v_caller.id <> v_event.actor_member_id or v_pool_size = 0);
  if v_pool_size = 0 and (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate)) then
    v_pool_size := 1;
  end if;

  if v_subject_decides and v_caller.id = v_event.subject_member_id then
    null;
  elsif v_in_pool then
    null;
  else
    raise exception 'you are not an eligible validator for this event';
  end if;

  insert into public.event_decisions (event_id, member_id, decision)
  values (p_event_id, v_caller.id, case when p_accept then 'accept' else 'reject' end);

  if not p_accept then
    update public.events set status = 'rejected', decided_at = now()
      where id = p_event_id;
    if v_event.reservation_id is not null then
      update public.reservations set status = 'cancelled'
        where id = v_event.reservation_id and status in ('reserved','checked_in');
    end if;
    if v_event.type = 'member_join' then
      update public.members set status = 'exited'
        where id = v_event.subject_member_id and status = 'pending';
    end if;
    if v_event.type = 'invoice_payment' then
      delete from public.ledger_entries
        where id = (select credit_ledger_id from public.invoice_matches
                     where event_id = v_event.id);
      delete from public.invoice_matches where event_id = v_event.id;
    end if;
    return;
  end if;

  select count(*) into v_accepts from public.event_decisions
    where event_id = p_event_id and decision = 'accept';
  v_required := greatest(1, least(v_policy.required_count,
    v_pool_size + case when v_subject_decides then 1 else 0 end));
  v_subject_ok := not v_subject_decides or exists (
    select 1 from public.event_decisions d
    where d.event_id = p_event_id and d.decision = 'accept'
      and d.member_id = v_event.subject_member_id);
  v_owner_ok := not v_policy.owner_required or exists (
    select 1 from public.event_decisions d
    join public.members m on m.id = d.member_id
    where d.event_id = p_event_id and d.decision = 'accept' and m.is_owner);

  if v_accepts >= v_required and v_subject_ok and v_owner_ok then
    update public.events set status = 'confirmed', decided_at = now()
      where id = p_event_id;

    if v_event.type in ('payment','expense') then
      -- 0070: the payer's own date and target month when the payload
      -- carries them; the old behaviour (today, current month) when not.
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description,
         period, event_id, occurred_on)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'credit',
        case when v_event.type = 'payment' then 'payment' else 'expense' end,
        (v_event.payload->>'amount_cents')::int,
        coalesce(v_event.payload->>'note', ''),
        coalesce(v_event.payload->>'period', to_char(now(), 'YYYY-MM')),
        v_event.id,
        (v_event.payload->>'paid_on')::date
      );
    elsif v_event.type = 'service_charge' then
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description, period, event_id)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'charge', 'service',
        (v_event.payload->>'amount_cents')::int,
        (v_event.payload->>'name') || ' x' || (v_event.payload->>'quantity'),
        coalesce(v_event.payload->>'period', to_char(now(), 'YYYY-MM')),
        v_event.id
      );
    elsif v_event.type = 'quota' then
      insert into public.quota_extensions
        (workspace_id, member_id, period, half_days, event_id)
      values (
        v_event.workspace_id, v_event.subject_member_id,
        v_event.payload->>'period',
        (v_event.payload->>'half_days')::int,
        v_event.id
      );
    elsif v_event.type = 'role_change' then
      update public.members
        set is_admin = (v_event.payload->>'make_admin')::boolean
        where id = v_event.subject_member_id;
    elsif v_event.type = 'member_join' then
      -- the validated welcome: the pending membership becomes active
      update public.members set status = 'active'
        where id = v_event.subject_member_id and status = 'pending';
    elsif v_event.type = 'invoice_payment' then
      update public.invoice_matches set status = 'confirmed'
        where event_id = v_event.id;
    end if;
  end if;
end;
$$;

-- 4. The invoice ANNEX (0064) dates its movements the same way: what the
-- member reads on the annex must be the day the money moved. Body = the
-- 0069 create_invoice v7 verbatim, with that one date expression changed.
create or replace function public.create_invoice(
  p_workspace_id uuid,
  p_member_id uuid,
  p_period text,
  p_replaces uuid default null,
  p_detailed boolean default false
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_subject public.members;
  v_workspace public.workspaces;
  v_replaced public.invoices;
  v_replaces_number text := '';
  v_lines jsonb;
  v_details jsonb := null;
  v_parties jsonb;
  v_tz text;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_total int := 0;
  v_count int;
  v_number text;
  v_member_name text;
  v_member_address text;
  v_member_country text;
  v_member_vat text;
  v_issuer_name text;
  v_id uuid;
  v_signature text;
begin
  select * into v_actor from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if not public.is_owner_of(p_workspace_id) and not coalesce(
    (select w.feature_flags -> 'adminInvoicing' = to_jsonb(true)
       from public.workspaces w where w.id = p_workspace_id), false) then
    raise exception 'admins may not issue invoices here';
  end if;

  select * into v_subject from public.members
    where id = p_member_id and workspace_id = p_workspace_id
      and status = 'active' and not is_kiosk;
  if v_subject.id is null then raise exception 'unknown subject member'; end if;
  if p_period is null or p_period !~ '^[0-9]{4}-[0-9]{2}$' then
    raise exception 'invalid period';
  end if;
  if exists (
    select 1 from public.invoices i
    where i.member_id = v_subject.id and i.period = p_period
      and i.voided_at is null and i.id is distinct from p_replaces
  ) then
    raise exception 'period already invoiced for this member';
  end if;

  v_lines := public.invoice_lines_for(p_member_id, p_period);
  if jsonb_array_length(v_lines) = 0 then
    raise exception 'nothing to invoice for this period';
  end if;
  select coalesce(sum((l->>'amount_cents')::int), 0) into v_total
    from jsonb_array_elements(v_lines) l;

  select * into v_workspace from public.workspaces where id = p_workspace_id;
  select coalesce(display_name, ''), coalesce(address, ''),
         coalesce(country_code, ''), coalesce(vat_id, '')
    into v_member_name, v_member_address, v_member_country, v_member_vat
    from public.profiles where id = v_subject.user_id;
  select coalesce(display_name, '') into v_issuer_name
    from public.profiles where id = v_actor.user_id;

  v_parties := jsonb_build_object(
    'seller', jsonb_build_object(
      'name', v_workspace.name,
      'street', coalesce(nullif(v_workspace.street, ''),
                         coalesce(v_workspace.address, '')),
      'city', coalesce(v_workspace.city, ''),
      'postal_code', coalesce(v_workspace.postal_code, ''),
      'country', v_workspace.country_code,
      'vat_id', coalesce(v_workspace.vat_id, ''),
      'legal_id', coalesce(v_workspace.legal_id, ''),
      'vat_regime', coalesce(v_workspace.vat_regime, 'not_subject'),
      'tax_exemption_reason',
        coalesce(v_workspace.tax_exemption_reason, '')),
    'buyer', jsonb_build_object(
      'name', v_member_name,
      'street', v_member_address,
      'country', coalesce(nullif(v_member_country, ''),
                          v_workspace.country_code),
      'vat_id', v_member_vat));

  if p_detailed then
    v_tz := v_workspace.timezone;
    v_period_start := to_timestamp(p_period || '-01', 'YYYY-MM-DD') at time zone v_tz;
    v_period_end := (to_timestamp(p_period || '-01', 'YYYY-MM-DD') + interval '1 month') at time zone v_tz;
    v_details := jsonb_build_object(
      'ledger', coalesce((
        select jsonb_agg(jsonb_build_object(
            -- 0070: the day the money moved, not the day it was booked.
            'on', coalesce(le.occurred_on, le.created_at::date)::text,
            'category', le.category,
            'description', le.description,
            'amount_cents', case when le.kind = 'credit'
                                 then -le.amount_cents
                                 else le.amount_cents end)
          order by coalesce(le.occurred_on, le.created_at::date), le.created_at)
        from public.ledger_entries le
        where le.member_id = p_member_id and le.period = p_period
      ), '[]'::jsonb),
      'attendance', coalesce((
        select jsonb_agg(jsonb_build_object(
            'starts_at', to_char(r.starts_at at time zone v_tz,
                                 'YYYY-MM-DD"T"HH24:MI'),
            'ends_at', to_char(r.ends_at at time zone v_tz,
                               'YYYY-MM-DD"T"HH24:MI'),
            'status', r.status,
            'space', coalesce(
              (select s.name || ' · ' || d.name
                 from public.seats s
                 join public.desks d on d.id = s.desk_id
                where s.id = r.seat_id),
              (select d.name from public.desks d where d.id = r.desk_id),
              (select o.name from public.offices o where o.id = r.office_id),
              (select l.name from public.levels l where l.id = r.level_id),
              ''))
          order by r.starts_at)
        from public.reservations r
        where r.member_id = p_member_id
          and r.status in ('reserved', 'checked_in', 'completed')
          and r.starts_at >= v_period_start and r.starts_at < v_period_end
      ), '[]'::jsonb));
  end if;

  if p_replaces is not null then
    select * into v_replaced from public.invoices
      where id = p_replaces and workspace_id = p_workspace_id;
    if v_replaced.id is null then raise exception 'unknown invoice'; end if;
    if exists (select 1 from public.invoices
                where replaces_invoice_id = p_replaces) then
      raise exception 'invoice already replaced';
    end if;
    if exists (select 1 from public.invoice_matches
                where invoice_id = p_replaces) then
      raise exception 'invoice is matched';
    end if;
    if v_replaced.voided_at is null then
      update public.invoices
         set voided_at = now(), voided_by_name = v_issuer_name
       where id = p_replaces;
    end if;
    v_replaces_number := v_replaced.number;
  end if;

  perform pg_advisory_xact_lock(hashtext(p_workspace_id::text));
  select count(*) into v_count from public.invoices
    where workspace_id = p_workspace_id
      and date_part('year', issued_at) = date_part('year', now());
  v_number := 'INV-' || date_part('year', now())::int || '-'
      || lpad((v_count + 1)::text, 4, '0');

  v_id := gen_random_uuid();
  v_signature := encode(extensions.digest(convert_to(concat_ws('|',
      v_id::text, v_number, p_workspace_id::text, v_subject.id::text,
      v_member_name, v_member_address, v_workspace.name,
      coalesce(v_workspace.address, ''), v_issuer_name,
      p_period, v_lines::text, v_total::text, v_workspace.currency_code,
      now()::date::text, coalesce(p_replaces::text, ''),
      v_replaces_number, coalesce(v_details::text, ''),
      v_parties::text),
      'UTF8'), 'sha256'), 'hex');

  insert into public.invoices
    (id, workspace_id, member_id, issuer_member_id, number, period, title,
     lines, total_cents, currency, member_name, member_address,
     workspace_name, workspace_address, issuer_name, signature,
     replaces_invoice_id, replaces_number, details, parties)
  values
    (v_id, p_workspace_id, v_subject.id, v_actor.id, v_number, p_period,
     p_period, v_lines, v_total, v_workspace.currency_code,
     v_member_name, v_member_address, v_workspace.name,
     coalesce(v_workspace.address, ''), v_issuer_name, v_signature,
     p_replaces, v_replaces_number, v_details, v_parties);
  return v_id;
end;
$$;
revoke execute on function
  public.create_invoice(uuid, uuid, text, uuid, boolean) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- Direct submission: the app stops handing out a file and SENDS it.
--
-- France has no free public channel any more (the PPF was cut back to a
-- directory in October 2024), so a workspace under the mandate works
-- through a plateforme agréée; elsewhere it is a Peppol access point or a
-- clearance platform's upload API. All of them come down to the same
-- shape: an endpoint, a credential, a document, and an id to track it by.
--
-- SECURITY mirrors 0047 (payment_credentials): the credentials table has
-- RLS enabled with NO policies — anon and authenticated are denied
-- entirely. Only the owner-gated SECURITY DEFINER RPCs below (which never
-- return a secret's value, just whether it is set) and the Edge Function
-- via the service role ever touch it.
--
-- NOT YET applied to the hosted reference project.

-- 1. Per-workspace platform credentials.
create table public.einvoice_credentials (
  workspace_id uuid primary key references public.workspaces(id)
    on delete cascade,
  -- 'generic' = any platform that accepts an HTTP upload with a bearer or
  -- basic credential. Named adapters join this list as they are written.
  provider text not null default 'generic'
    check (provider in ('generic')),
  -- endpoint, auth_header, auth_value, field_name, extra headers…
  -- Read only by the service role.
  config jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);

alter table public.einvoice_credentials enable row level security;
-- Intentionally NO policies: deny-all to client roles.

-- Which config fields may be echoed back to the owner UI. Everything else
-- is reported as PRESENT, never returned.
create or replace function public.einvoice_config_is_secret(p_key text)
returns boolean language sql immutable as $$
  select p_key not in ('endpoint', 'auth_header', 'field_name', 'provider');
$$;

-- 2. What was sent, and what came back. The audit trail beside the
-- immutable document — an invoice can be submitted more than once (a
-- platform outage, a rejected first attempt), so this is a LOG, not a
-- state column on the invoice.
create table public.invoice_transmissions (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id)
    on delete cascade,
  invoice_id uuid not null references public.invoices(id) on delete cascade,
  provider text not null,
  -- accepted = the platform took it; rejected = it answered no; failed =
  -- it could not be reached.
  status text not null check (status in ('accepted', 'rejected', 'failed')),
  -- The platform's own id for the document, when it returns one: the only
  -- handle for asking about it later.
  external_id text not null default '',
  -- SHA-256 of the bytes that left, so a later question ("which version
  -- did they get?") has an answer.
  document_hash text not null default '',
  detail text not null default '',
  sent_at timestamptz not null default now(),
  by_name text not null default ''
);
create index invoice_transmissions_invoice_idx
  on public.invoice_transmissions (invoice_id, sent_at desc);

alter table public.invoice_transmissions enable row level security;
-- Readable by the people who invoice; written only by the Edge Function
-- (service role) — a client cannot claim an invoice was sent.
create policy invoice_transmissions_select on public.invoice_transmissions
  for select using (public.is_admin_of(workspace_id));

-- 3. Owner-only: MERGE the config. Blank fields keep their stored value,
-- so the endpoint can change without re-typing a token nobody can read.
create or replace function public.set_einvoice_credentials(
  p_workspace_id uuid, p_config jsonb
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_clean jsonb;
begin
  if not public.is_owner_of(p_workspace_id) then
    raise exception 'not the owner of this workspace';
  end if;
  select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) into v_clean
    from jsonb_each(coalesce(p_config, '{}'::jsonb))
    where value is not null and trim(both '"' from value::text) <> '';
  if v_clean = '{}'::jsonb then return; end if;

  insert into public.einvoice_credentials
    (workspace_id, config, updated_at)
  values (p_workspace_id, v_clean, now())
  on conflict (workspace_id) do update
    set config = public.einvoice_credentials.config || v_clean,
        updated_at = now();
end;
$$;
revoke execute on function
  public.set_einvoice_credentials(uuid, jsonb) from public, anon;

-- 4. Owner-only: forget the platform entirely.
create or replace function public.clear_einvoice_credentials(
  p_workspace_id uuid
) returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_owner_of(p_workspace_id) then
    raise exception 'not the owner of this workspace';
  end if;
  delete from public.einvoice_credentials where workspace_id = p_workspace_id;
end;
$$;
revoke execute on function
  public.clear_einvoice_credentials(uuid) from public, anon;

-- 5. Owner-only status read-back: the non-secret fields as they are, and
-- the NAMES of the secrets that are set. A token never comes back out.
create or replace function public.einvoice_status(p_workspace_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_config jsonb;
  v_public jsonb;
  v_secrets text[];
begin
  if not public.is_owner_of(p_workspace_id) then
    raise exception 'not the owner of this workspace';
  end if;
  select config into v_config from public.einvoice_credentials
    where workspace_id = p_workspace_id;
  if v_config is null then
    return jsonb_build_object('configured', false, 'fields',
      '{}'::jsonb, 'secrets_set', '[]'::jsonb);
  end if;
  select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) into v_public
    from jsonb_each(v_config)
    where not public.einvoice_config_is_secret(key);
  select coalesce(array_agg(key), '{}') into v_secrets
    from jsonb_each(v_config)
    where public.einvoice_config_is_secret(key);
  return jsonb_build_object(
    'configured', true,
    'fields', v_public,
    'secrets_set', to_jsonb(v_secrets));
end;
$$;
revoke execute on function public.einvoice_status(uuid) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- VAT. Until now the app could only say "no VAT charged" — an EN 16931
-- export from a VAT-registered workspace was refused outright, because
-- declaring a zero a seller does owe is a false statement.
--
-- THE RULE, once and everywhere: **prices are VAT-INCLUSIVE**. What the
-- owner types on a service, a package or a fee band is what the member
-- pays; the tax is EXTRACTED from it for the documents. That choice is
-- deliberate:
--   * turning VAT on never changes what anyone owes — the same money, now
--     with the tax shown;
--   * the ledger, the statement and the quota machinery keep working on
--     the amounts they already hold, so there is one truth about money;
--   * a coworking advertises "250 €/month", not "208,33 € + VAT".
--
-- THE SPLIT, once and everywhere (mirrored in Dart, pinned by test):
--     net = round(gross × 100 / (100 + percent));  vat = gross − net
-- applied PER LINE. Every total is then a plain sum of lines, so the VAT
-- breakdown, the net total and the payable amount all tie back to the
-- ledger without a reconciliation step.
--
-- Credits (payments, reimbursements) carry no VAT: they are movements of
-- money, not supplies.
--
-- NOT YET applied to the hosted reference project.

-- 1. The rates a workspace charges. Member-readable (they appear on the
-- bill), owner-written through the RPC below.
create table public.vat_rates (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  label text not null check (char_length(label) between 1 and 40),
  -- 0.00–99.99; 0 means the rate itself carries no tax (zero-rated or the
  -- workspace's exemption, per its declared regime).
  percent numeric(5,2) not null check (percent >= 0 and percent < 100),
  -- EN 16931 BT-118 (UNCL5305): S for any taxed rate — reduced rates are
  -- still category S with their own percentage — Z zero-rated, E exempt,
  -- O outside the scope.
  category text not null default 'S' check (category in ('S','Z','E','O')),
  -- Exactly one default per workspace: what subscriptions, overage,
  -- supplements and adjustments use, and what a new service starts with.
  is_default boolean not null default false,
  active boolean not null default true,
  created_at timestamptz not null default now()
);
create index vat_rates_workspace_idx on public.vat_rates (workspace_id);
create unique index vat_rates_one_default
  on public.vat_rates (workspace_id) where is_default;

alter table public.vat_rates enable row level security;
create policy vat_rates_select on public.vat_rates
  for select using (public.is_member_of(workspace_id));
-- No write policies: writes go through set_vat_rates below.

-- 2. Owner-only, atomic replace of the whole rate set — the same shape as
-- replace_fee_bands. Rates a service still points at are kept alive by
-- their id, so re-saving the set never silently re-taxes a catalogue.
create or replace function public.set_vat_rates(
  p_workspace_id uuid, p_rates jsonb
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_rate jsonb;
  v_defaults int := 0;
  v_keep uuid[] := '{}';
  v_id uuid;
begin
  if not public.is_owner_of(p_workspace_id) then
    raise exception 'not the owner of this workspace';
  end if;
  if p_rates is null or jsonb_typeof(p_rates) <> 'array' then
    raise exception 'rates must be an array';
  end if;
  for v_rate in select * from jsonb_array_elements(p_rates) loop
    if coalesce((v_rate->>'is_default')::boolean, false) then
      v_defaults := v_defaults + 1;
    end if;
  end loop;
  if jsonb_array_length(p_rates) > 0 and v_defaults <> 1 then
    raise exception 'exactly one rate must be the default';
  end if;

  -- Upsert by id so a catalogue entry keeps pointing at the same rate.
  for v_rate in select * from jsonb_array_elements(p_rates) loop
    if (v_rate->>'id') is not null and (v_rate->>'id') <> '' then
      v_id := (v_rate->>'id')::uuid;
      update public.vat_rates
         set label = v_rate->>'label',
             percent = (v_rate->>'percent')::numeric,
             category = coalesce(v_rate->>'category', 'S'),
             -- defaults are cleared first, below, so this cannot collide
             is_default = false,
             active = coalesce((v_rate->>'active')::boolean, true)
       where id = v_id and workspace_id = p_workspace_id;
    else
      insert into public.vat_rates
        (workspace_id, label, percent, category, is_default, active)
      values (
        p_workspace_id,
        v_rate->>'label',
        (v_rate->>'percent')::numeric,
        coalesce(v_rate->>'category', 'S'),
        false,
        coalesce((v_rate->>'active')::boolean, true))
      returning id into v_id;
    end if;
    v_keep := v_keep || v_id;
  end loop;

  -- Rates the owner dropped: deactivate rather than delete when a
  -- catalogue entry or an invoice still refers to them.
  update public.vat_rates set active = false, is_default = false
   where workspace_id = p_workspace_id and not (id = any(v_keep));

  -- And now the single default.
  for v_rate in select * from jsonb_array_elements(p_rates) loop
    if coalesce((v_rate->>'is_default')::boolean, false) then
      update public.vat_rates set is_default = true
       where workspace_id = p_workspace_id
         and (case when (v_rate->>'id') is not null and (v_rate->>'id') <> ''
                   then id = (v_rate->>'id')::uuid
                   else label = v_rate->>'label'
                        and percent = (v_rate->>'percent')::numeric end);
    end if;
  end loop;
end;
$$;
revoke execute on function public.set_vat_rates(uuid, jsonb) from public, anon;

-- 3. The VAT account a FEC books collected tax to (PCG 44571 in France).
alter table public.workspaces
  add column vat_account text not null default ''
    check (char_length(vat_account) <= 20);

-- 4. What each priceable thing is taxed at. NULL = the workspace default,
-- which is also what subscriptions, overage and supplements use.
alter table public.services
  add column vat_rate_id uuid references public.vat_rates(id)
    on delete set null;
alter table public.packages
  add column vat_rate_id uuid references public.vat_rates(id)
    on delete set null;

-- 5. The rate a booked charge was taxed at — stamped when the charge is
-- recorded, like its price. A rate change afterwards must not rewrite
-- what already happened. NULL = resolve to the workspace default at
-- invoice time (pre-0072 rows, adjustments).
alter table public.ledger_entries
  add column vat_percent numeric(5,2)
    check (vat_percent is null or (vat_percent >= 0 and vat_percent < 100));

-- 6. The workspace's default percentage, or 0 when it charges no VAT.
create or replace function public.workspace_default_vat_percent(
  p_workspace_id uuid
) returns numeric language sql stable security definer set search_path = public as $$
  select coalesce(
    (select percent from public.vat_rates
      where workspace_id = p_workspace_id and is_default and active
      limit 1), 0);
$$;

-- 7. record_service_charge v3: the 0016 body plus the service's rate in
-- the payload, so the confirmation books what was agreed at the time.
create or replace function public.record_service_charge(
  p_workspace_id uuid,
  p_subject_member_id uuid,
  p_service_id uuid,
  p_quantity int,
  p_period text default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_service public.services;
  v_period text;
  v_event_id uuid;
  v_vat numeric;
begin
  select * into v_actor from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_actor.id is null then raise exception 'not an active member'; end if;
  if v_actor.id <> p_subject_member_id and not (v_actor.is_admin or v_actor.is_owner) then
    raise exception 'only admins may add services for other members';
  end if;
  if not exists (
    select 1 from public.members
    where id = p_subject_member_id and workspace_id = p_workspace_id and status = 'active'
  ) then raise exception 'unknown subject member'; end if;

  select * into v_service from public.services
    where id = p_service_id and workspace_id = p_workspace_id;
  if v_service.id is null then raise exception 'unknown service'; end if;
  if not v_service.active then raise exception 'service is inactive'; end if;
  if p_quantity is null or p_quantity < 1 or p_quantity > 999 then
    raise exception 'quantity must be between 1 and 999';
  end if;
  v_period := coalesce(p_period, to_char(now(), 'YYYY-MM'));
  if v_period !~ '^\d{4}-\d{2}$' then raise exception 'period must be YYYY-MM'; end if;

  -- The service's own rate, else the workspace default.
  select coalesce(
      (select percent from public.vat_rates
        where id = v_service.vat_rate_id and active),
      public.workspace_default_vat_percent(p_workspace_id))
    into v_vat;

  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id, payload, status)
  values (
    p_workspace_id, 'service_charge', 'submitted', v_actor.id, p_subject_member_id,
    jsonb_build_object(
      'service_id', v_service.id,
      'name', v_service.name,
      'price_cents', v_service.price_cents,
      'quantity', p_quantity,
      'amount_cents', v_service.price_cents * p_quantity,
      'vat_percent', v_vat,
      'period', v_period
    ),
    'pending'
  ) returning id into v_event_id;
  return v_event_id;
end;
$$;
revoke execute on function
  public.record_service_charge(uuid, uuid, uuid, int, text) from public, anon;

-- 8. buy_package v2: the 0042 body, stamping the package's rate onto the
-- charge it posts.
create or replace function public.buy_package(
  p_workspace_id uuid, p_package_id uuid
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_pkg public.packages;
  v_tz text;
  v_period text;
  v_ext_id uuid;
  v_vat numeric;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if coalesce(v_member.overage_policy, 'blocked') <> 'package' then
    raise exception 'member is not on the package plan';
  end if;

  select * into v_pkg from public.packages
    where id = p_package_id and workspace_id = p_workspace_id and active;
  if v_pkg.id is null then raise exception 'unknown or inactive package'; end if;

  select timezone into v_tz from public.workspaces where id = p_workspace_id;
  v_period := to_char(now() at time zone v_tz, 'YYYY-MM');

  insert into public.quota_extensions
    (workspace_id, member_id, period, half_days)
  values (p_workspace_id, v_member.id, v_period, v_pkg.days * 2)
  returning id into v_ext_id;

  select coalesce(
      (select percent from public.vat_rates
        where id = v_pkg.vat_rate_id and active),
      public.workspace_default_vat_percent(p_workspace_id))
    into v_vat;

  insert into public.ledger_entries
    (workspace_id, member_id, kind, category, amount_cents, description,
     period, vat_percent)
  values (
    p_workspace_id, v_member.id, 'charge', 'package', v_pkg.price_cents,
    v_pkg.name || ' (' || v_pkg.days || 'd)', v_period, v_vat
  );

  return v_ext_id;
end;
$$;
revoke execute on function public.buy_package(uuid, uuid) from public, anon;

-- 9. invoice_lines_for v-next: the 0063 body, every CHARGE line carrying
-- the rate it is taxed at. Credits carry none.
create or replace function public.invoice_lines_for(
  p_member_id uuid,
  p_period text
) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_stmt jsonb;
  v_lines jsonb := '[]'::jsonb;
  v_row record;
  v_workspace uuid;
  v_default numeric;
begin
  v_stmt := public.member_statement(p_member_id, p_period);
  select workspace_id into v_workspace from public.members where id = p_member_id;
  v_default := public.workspace_default_vat_percent(v_workspace);

  if (v_stmt->>'fee_cents')::int > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'subscription',
      'label', v_stmt->>'subscription_pct',
      'quantity', 1,
      'vat_percent', v_default,
      'amount_cents', (v_stmt->>'fee_cents')::int);
  end if;
  if (v_stmt->>'overage_cents')::int > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'overage',
      'label', '',
      'quantity', (v_stmt->>'extra_half_days')::int,
      'vat_percent', v_default,
      'amount_cents', (v_stmt->>'overage_cents')::int);
  end if;
  if coalesce((v_stmt->>'accessory_supplement_cents')::int, 0) > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'accessories', 'label', '', 'quantity', 1,
      'vat_percent', v_default,
      'amount_cents', (v_stmt->>'accessory_supplement_cents')::int);
  end if;
  if coalesce((v_stmt->>'level_supplement_cents')::int, 0) > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'level', 'label', '', 'quantity', 1,
      'vat_percent', v_default,
      'amount_cents', (v_stmt->>'level_supplement_cents')::int);
  end if;
  if coalesce((v_stmt->>'office_supplement_cents')::int, 0) > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'office', 'label', '', 'quantity', 1,
      'vat_percent', v_default,
      'amount_cents', (v_stmt->>'office_supplement_cents')::int);
  end if;
  if coalesce((v_stmt->>'desk_supplement_cents')::int, 0) > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'desk', 'label', '', 'quantity', 1,
      'vat_percent', v_default,
      'amount_cents', (v_stmt->>'desk_supplement_cents')::int);
  end if;

  for v_row in
    select kind, category, description, amount_cents, vat_percent
      from public.ledger_entries
     where member_id = p_member_id
       and period = p_period
       and ((kind = 'charge'
             and category in ('service', 'package', 'adjustment'))
         or (kind = 'credit'
             and category in ('payment', 'expense', 'adjustment')))
     order by created_at
  loop
    v_lines := v_lines || jsonb_build_object(
      'kind', v_row.category,
      'label', v_row.description,
      'quantity', 1,
      -- The rate stamped when the charge was booked; the workspace
      -- default for anything older than 0072 or unstamped. A credit is
      -- money moving, not a supply: no VAT.
      'vat_percent', case when v_row.kind = 'credit' then 0
                          else coalesce(v_row.vat_percent, v_default) end,
      'amount_cents', case when v_row.kind = 'credit'
                           then -v_row.amount_cents
                           else v_row.amount_cents end);
  end loop;

  return v_lines;
end;
$$;
revoke execute on function public.invoice_lines_for(uuid, text)
  from public, anon;

-- 10. The immutable VAT breakdown of an issued invoice.
alter table public.invoices add column vat_totals jsonb;

comment on column public.invoices.vat_totals is
  'Issue-time VAT breakdown, one entry per rate: percent, category, '
  'gross_cents, net_cents, vat_cents. Sums of the PER-LINE split '
  '(net = round(gross*100/(100+percent)); vat = gross-net), so the '
  'breakdown, the net total and the payable amount all tie to the ledger. '
  'NULL on pre-0072 invoices.';

-- 11. respond_to_event: the 0070 body, writing the agreed rate onto the
-- service charge it books.
create or replace function public.respond_to_event(
  p_event_id uuid,
  p_accept boolean
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_event public.events;
  v_caller public.members;
  v_policy record;
  v_subject_decides boolean;
  v_in_pool boolean;
  v_pool_size int;
  v_required int;
  v_accepts int;
  v_subject_ok boolean;
  v_owner_ok boolean;
begin
  select e.* into v_event from public.events e where e.id = p_event_id;
  if v_event.id is null then raise exception 'unknown event'; end if;
  if v_event.status <> 'pending' then raise exception 'already decided'; end if;

  select m.* into v_caller from public.members m
    where m.workspace_id = v_event.workspace_id and m.user_id = auth.uid()
      and m.status = 'active';
  if v_caller.id is null then raise exception 'not a member'; end if;
  if exists (select 1 from public.event_decisions d
              where d.event_id = p_event_id and d.member_id = v_caller.id) then
    raise exception 'you already decided this event';
  end if;

  select * into v_policy from public.validation_policies
    where workspace_id = v_event.workspace_id and event_type = v_event.type;
  if v_policy is null then
    select * into v_policy from public.validation_policies
      where workspace_id = v_event.workspace_id and event_type is null;
  end if;
  if v_policy is null then
    select null::uuid as id, v_event.workspace_id as workspace_id,
           null::text as event_type, 1 as required_count,
           true as admins_may_validate, '{}'::uuid[] as eligible_admin_ids,
           false as owner_required
      into v_policy;
  end if;

  v_subject_decides := v_event.type = 'reservation'
    or (v_event.type in ('payment','service_charge')
        and v_event.actor_member_id <> v_event.subject_member_id);

  select count(*) into v_pool_size from public.members m
    where m.workspace_id = v_event.workspace_id and m.status = 'active'
      and m.id not in (v_event.actor_member_id, v_event.subject_member_id)
      and (m.is_owner or (m.is_admin and v_policy.admins_may_validate
           and (cardinality(v_policy.eligible_admin_ids) = 0
                or m.id = any(v_policy.eligible_admin_ids))));

  v_in_pool := (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate
                and (cardinality(v_policy.eligible_admin_ids) = 0
                     or v_caller.id = any(v_policy.eligible_admin_ids))))
    and (v_caller.id <> v_event.subject_member_id
         or (not v_subject_decides and v_pool_size = 0))
    and (v_caller.id <> v_event.actor_member_id or v_pool_size = 0);
  if v_pool_size = 0 and (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate)) then
    v_pool_size := 1;
  end if;

  if v_subject_decides and v_caller.id = v_event.subject_member_id then
    null;
  elsif v_in_pool then
    null;
  else
    raise exception 'you are not an eligible validator for this event';
  end if;

  insert into public.event_decisions (event_id, member_id, decision)
  values (p_event_id, v_caller.id, case when p_accept then 'accept' else 'reject' end);

  if not p_accept then
    update public.events set status = 'rejected', decided_at = now()
      where id = p_event_id;
    if v_event.reservation_id is not null then
      update public.reservations set status = 'cancelled'
        where id = v_event.reservation_id and status in ('reserved','checked_in');
    end if;
    if v_event.type = 'member_join' then
      update public.members set status = 'exited'
        where id = v_event.subject_member_id and status = 'pending';
    end if;
    if v_event.type = 'invoice_payment' then
      delete from public.ledger_entries
        where id = (select credit_ledger_id from public.invoice_matches
                     where event_id = v_event.id);
      delete from public.invoice_matches where event_id = v_event.id;
    end if;
    return;
  end if;

  select count(*) into v_accepts from public.event_decisions
    where event_id = p_event_id and decision = 'accept';
  v_required := greatest(1, least(v_policy.required_count,
    v_pool_size + case when v_subject_decides then 1 else 0 end));
  v_subject_ok := not v_subject_decides or exists (
    select 1 from public.event_decisions d
    where d.event_id = p_event_id and d.decision = 'accept'
      and d.member_id = v_event.subject_member_id);
  v_owner_ok := not v_policy.owner_required or exists (
    select 1 from public.event_decisions d
    join public.members m on m.id = d.member_id
    where d.event_id = p_event_id and d.decision = 'accept' and m.is_owner);

  if v_accepts >= v_required and v_subject_ok and v_owner_ok then
    update public.events set status = 'confirmed', decided_at = now()
      where id = p_event_id;

    if v_event.type in ('payment','expense') then
      -- 0070: the payer's own date and target month when the payload
      -- carries them; the old behaviour (today, current month) when not.
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description,
         period, event_id, occurred_on)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'credit',
        case when v_event.type = 'payment' then 'payment' else 'expense' end,
        (v_event.payload->>'amount_cents')::int,
        coalesce(v_event.payload->>'note', ''),
        coalesce(v_event.payload->>'period', to_char(now(), 'YYYY-MM')),
        v_event.id,
        (v_event.payload->>'paid_on')::date
      );
    elsif v_event.type = 'service_charge' then
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description,
         period, event_id, vat_percent)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'charge', 'service',
        (v_event.payload->>'amount_cents')::int,
        (v_event.payload->>'name') || ' x' || (v_event.payload->>'quantity'),
        coalesce(v_event.payload->>'period', to_char(now(), 'YYYY-MM')),
        v_event.id,
        -- 0072: the rate agreed when the charge was recorded.
        (v_event.payload->>'vat_percent')::numeric
      );
    elsif v_event.type = 'quota' then
      insert into public.quota_extensions
        (workspace_id, member_id, period, half_days, event_id)
      values (
        v_event.workspace_id, v_event.subject_member_id,
        v_event.payload->>'period',
        (v_event.payload->>'half_days')::int,
        v_event.id
      );
    elsif v_event.type = 'role_change' then
      update public.members
        set is_admin = (v_event.payload->>'make_admin')::boolean
        where id = v_event.subject_member_id;
    elsif v_event.type = 'member_join' then
      -- the validated welcome: the pending membership becomes active
      update public.members set status = 'active'
        where id = v_event.subject_member_id and status = 'pending';
    elsif v_event.type = 'invoice_payment' then
      update public.invoice_matches set status = 'confirmed'
        where event_id = v_event.id;
    end if;
  end if;
end;
$$;

-- 12. create_invoice v9: the 0070 body plus the VAT breakdown, snapshotted
-- into the signed content. The split is per LINE and every total is a sum
-- of lines, so nothing needs reconciling afterwards.
create or replace function public.create_invoice(
  p_workspace_id uuid,
  p_member_id uuid,
  p_period text,
  p_replaces uuid default null,
  p_detailed boolean default false
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_subject public.members;
  v_workspace public.workspaces;
  v_replaced public.invoices;
  v_replaces_number text := '';
  v_lines jsonb;
  v_details jsonb := null;
  v_parties jsonb;
  v_vat_totals jsonb;
  v_zero_category text;
  v_tz text;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_total int := 0;
  v_count int;
  v_number text;
  v_member_name text;
  v_member_address text;
  v_member_country text;
  v_member_vat text;
  v_issuer_name text;
  v_id uuid;
  v_signature text;
begin
  select * into v_actor from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if not public.is_owner_of(p_workspace_id) and not coalesce(
    (select w.feature_flags -> 'adminInvoicing' = to_jsonb(true)
       from public.workspaces w where w.id = p_workspace_id), false) then
    raise exception 'admins may not issue invoices here';
  end if;

  select * into v_subject from public.members
    where id = p_member_id and workspace_id = p_workspace_id
      and status = 'active' and not is_kiosk;
  if v_subject.id is null then raise exception 'unknown subject member'; end if;
  if p_period is null or p_period !~ '^[0-9]{4}-[0-9]{2}$' then
    raise exception 'invalid period';
  end if;
  if exists (
    select 1 from public.invoices i
    where i.member_id = v_subject.id and i.period = p_period
      and i.voided_at is null and i.id is distinct from p_replaces
  ) then
    raise exception 'period already invoiced for this member';
  end if;

  v_lines := public.invoice_lines_for(p_member_id, p_period);
  if jsonb_array_length(v_lines) = 0 then
    raise exception 'nothing to invoice for this period';
  end if;
  select coalesce(sum((l->>'amount_cents')::int), 0) into v_total
    from jsonb_array_elements(v_lines) l;

  select * into v_workspace from public.workspaces where id = p_workspace_id;
  select coalesce(display_name, ''), coalesce(address, ''),
         coalesce(country_code, ''), coalesce(vat_id, '')
    into v_member_name, v_member_address, v_member_country, v_member_vat
    from public.profiles where id = v_subject.user_id;
  select coalesce(display_name, '') into v_issuer_name
    from public.profiles where id = v_actor.user_id;

  -- A 0% line is categorised by the workspace's declared regime, exactly
  -- as before VAT existed: outside the scope, or exempt.
  v_zero_category := case coalesce(v_workspace.vat_regime, 'not_subject')
                       when 'exempt' then 'E' else 'O' end;

  -- One entry per rate. Charges only: a credit is money moving.
  with charges as (
    select coalesce((l->>'vat_percent')::numeric, 0) as percent,
           (l->>'amount_cents')::int as gross,
           round((l->>'amount_cents')::int * 100.0
                 / (100 + coalesce((l->>'vat_percent')::numeric, 0)))::int as net
      from jsonb_array_elements(v_lines) l
     where (l->>'amount_cents')::int > 0
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'percent', percent,
      'category', case when percent > 0 then 'S' else v_zero_category end,
      'gross_cents', gross,
      'net_cents', net,
      'vat_cents', gross - net) order by percent desc), '[]'::jsonb)
    into v_vat_totals
    from (
      select percent, sum(gross)::int as gross, sum(net)::int as net
        from charges group by percent
    ) grouped;

  v_parties := jsonb_build_object(
    'seller', jsonb_build_object(
      'name', v_workspace.name,
      'street', coalesce(nullif(v_workspace.street, ''),
                         coalesce(v_workspace.address, '')),
      'city', coalesce(v_workspace.city, ''),
      'postal_code', coalesce(v_workspace.postal_code, ''),
      'country', v_workspace.country_code,
      'vat_id', coalesce(v_workspace.vat_id, ''),
      'legal_id', coalesce(v_workspace.legal_id, ''),
      'vat_regime', coalesce(v_workspace.vat_regime, 'not_subject'),
      'tax_exemption_reason',
        coalesce(v_workspace.tax_exemption_reason, '')),
    'buyer', jsonb_build_object(
      'name', v_member_name,
      'street', v_member_address,
      'country', coalesce(nullif(v_member_country, ''),
                          v_workspace.country_code),
      'vat_id', v_member_vat));

  if p_detailed then
    v_tz := v_workspace.timezone;
    v_period_start := to_timestamp(p_period || '-01', 'YYYY-MM-DD') at time zone v_tz;
    v_period_end := (to_timestamp(p_period || '-01', 'YYYY-MM-DD') + interval '1 month') at time zone v_tz;
    v_details := jsonb_build_object(
      'ledger', coalesce((
        select jsonb_agg(jsonb_build_object(
            'on', coalesce(le.occurred_on, le.created_at::date)::text,
            'category', le.category,
            'description', le.description,
            'amount_cents', case when le.kind = 'credit'
                                 then -le.amount_cents
                                 else le.amount_cents end)
          order by coalesce(le.occurred_on, le.created_at::date), le.created_at)
        from public.ledger_entries le
        where le.member_id = p_member_id and le.period = p_period
      ), '[]'::jsonb),
      'attendance', coalesce((
        select jsonb_agg(jsonb_build_object(
            'starts_at', to_char(r.starts_at at time zone v_tz,
                                 'YYYY-MM-DD"T"HH24:MI'),
            'ends_at', to_char(r.ends_at at time zone v_tz,
                               'YYYY-MM-DD"T"HH24:MI'),
            'status', r.status,
            'space', coalesce(
              (select s.name || ' · ' || d.name
                 from public.seats s
                 join public.desks d on d.id = s.desk_id
                where s.id = r.seat_id),
              (select d.name from public.desks d where d.id = r.desk_id),
              (select o.name from public.offices o where o.id = r.office_id),
              (select l.name from public.levels l where l.id = r.level_id),
              ''))
          order by r.starts_at)
        from public.reservations r
        where r.member_id = p_member_id
          and r.status in ('reserved', 'checked_in', 'completed')
          and r.starts_at >= v_period_start and r.starts_at < v_period_end
      ), '[]'::jsonb));
  end if;

  if p_replaces is not null then
    select * into v_replaced from public.invoices
      where id = p_replaces and workspace_id = p_workspace_id;
    if v_replaced.id is null then raise exception 'unknown invoice'; end if;
    if exists (select 1 from public.invoices
                where replaces_invoice_id = p_replaces) then
      raise exception 'invoice already replaced';
    end if;
    if exists (select 1 from public.invoice_matches
                where invoice_id = p_replaces) then
      raise exception 'invoice is matched';
    end if;
    if v_replaced.voided_at is null then
      update public.invoices
         set voided_at = now(), voided_by_name = v_issuer_name
       where id = p_replaces;
    end if;
    v_replaces_number := v_replaced.number;
  end if;

  perform pg_advisory_xact_lock(hashtext(p_workspace_id::text));
  select count(*) into v_count from public.invoices
    where workspace_id = p_workspace_id
      and date_part('year', issued_at) = date_part('year', now());
  v_number := 'INV-' || date_part('year', now())::int || '-'
      || lpad((v_count + 1)::text, 4, '0');

  v_id := gen_random_uuid();
  v_signature := encode(extensions.digest(convert_to(concat_ws('|',
      v_id::text, v_number, p_workspace_id::text, v_subject.id::text,
      v_member_name, v_member_address, v_workspace.name,
      coalesce(v_workspace.address, ''), v_issuer_name,
      p_period, v_lines::text, v_total::text, v_workspace.currency_code,
      now()::date::text, coalesce(p_replaces::text, ''),
      v_replaces_number, coalesce(v_details::text, ''),
      v_parties::text, v_vat_totals::text),
      'UTF8'), 'sha256'), 'hex');

  insert into public.invoices
    (id, workspace_id, member_id, issuer_member_id, number, period, title,
     lines, total_cents, currency, member_name, member_address,
     workspace_name, workspace_address, issuer_name, signature,
     replaces_invoice_id, replaces_number, details, parties, vat_totals)
  values
    (v_id, p_workspace_id, v_subject.id, v_actor.id, v_number, p_period,
     p_period, v_lines, v_total, v_workspace.currency_code,
     v_member_name, v_member_address, v_workspace.name,
     coalesce(v_workspace.address, ''), v_issuer_name, v_signature,
     p_replaces, v_replaces_number, v_details, v_parties, v_vat_totals);
  return v_id;
end;
$$;
revoke execute on function
  public.create_invoice(uuid, uuid, text, uuid, boolean) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- Check-in requires PRESENCE (#408). The RPC verified ownership and
-- workspace-open but never the clock: a member could check in to next
-- week's reservation today, or retroactively into one that ended.
-- Sign-in means "I am here and the seat is occupied, now" — for
-- oneself, or by an authorized admin for the member standing there.
--
-- Two changes to check_in_reservation, none to its signature:
--
--   * The spec §4.3 check-in window, until now unimplemented: allowed
--     iff now() ∈ [starts_at − 15 min, ends_at). Not before the window
--     opens (the future), never after the reservation ended (the past).
--     Walk-ups are untouched — they are created at now() by design.
--   * An admin/owner of the workspace may check in ANOTHER member's
--     reservation while the bookForOthers feature is on — DIRECT, no
--     pending event, the kiosk_act precedent: the subject already
--     confirmed the reservation, and their standing at the desk is the
--     presence this rule is about. The same window applies to everyone.

create or replace function public.check_in_reservation(p_reservation_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_res public.reservations;
  v_own boolean;
begin
  select r.* into v_res from public.reservations r
    where r.id = p_reservation_id;
  if v_res.id is null then raise exception 'not your reservation'; end if;

  select exists (
    select 1 from public.members m
    where m.id = v_res.member_id and m.user_id = auth.uid()
  ) into v_own;

  if not v_own then
    -- The authorized-for-others path: admin/owner + the bookForOthers
    -- feature (jsonb boolean check, junk counts as OFF — the 0021
    -- idiom; the feature defaults ON in the registry, so an ABSENT key
    -- must count as ON here, unlike the default-off flags).
    if not (
      public.is_admin_of(v_res.workspace_id)
      and coalesce((
        select w.feature_flags->'bookForOthers' is distinct from 'false'::jsonb
        from public.workspaces w where w.id = v_res.workspace_id
      ), true)
    ) then
      raise exception 'not your reservation';
    end if;
  end if;

  if v_res.status <> 'reserved' then raise exception 'not in reserved state'; end if;

  -- Presence: the check-in window (spec §4.3). Before it opens the
  -- member is checking into the FUTURE; after ends_at, into the PAST.
  if now() < v_res.starts_at - interval '15 minutes' then
    raise exception 'check-in window not open yet';
  end if;
  if now() >= v_res.ends_at then
    raise exception 'check-in window closed';
  end if;

  perform public.assert_workspace_open(v_res.workspace_id, now(), now() + interval '1 minute');
  update public.reservations
    set status = 'checked_in', checked_in_at = now()
    where id = p_reservation_id;
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- One place at a time, and whole-space booking the owner can use (#412).
--
-- Field evidence (2026-08-03, hosted): a member walked up and checked in
-- on one seat, then — still checked in there — walked up onto a second
-- seat, and also held overlapping reservations. Every RPC checks whether
-- the TARGET is taken; none ever asked whether the MEMBER is already
-- somewhere else. And the owner could not reserve a whole desk/office/
-- level: the 0050 grant defaults false and nobody self-grants ceremony.
--
-- Four changes:
--
--  1. enforce_one_place — BEFORE INSERT trigger on reservations: a new
--     active row overlapping another active row OF THE SAME MEMBER
--     refuses with a pinned substring. One definition covers walk-up,
--     create_reservation, series instances (the loop's exception
--     handler turns it into a skipped date, like any conflict),
--     admin_create_reservation_for, kiosk_act, and every future path.
--     INSERT only: status flips and check-out truncation never create
--     new overlap.
--
--  2. check_in_reservation v3 — keeps the 0077 presence window and
--     for-others path; additionally a member checked in ELSEWHERE on a
--     still-running reservation is refused (one body, one place), and
--     stale check-ins whose own end has passed are auto-completed
--     first, stamped at their own end (0075 semantics) — forgetting to
--     check out must not wedge tomorrow's check-in.
--
--  3. create_reservation v8 / create_series v3 — the whole-space right
--     accepts can_reserve_level OR is_owner OR is_admin. The grant
--     machinery stays what it is for regular members; owners and
--     admins stop having to grant themselves ceremony. (kiosk_act
--     deliberately keeps the strict stored grant: a badge at a kiosk
--     carries no role context worth trusting.)

-- 1. The one-place trigger.
create or replace function public.enforce_one_place()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.status in ('reserved', 'checked_in') and exists (
    select 1 from public.reservations r
    where r.member_id = new.member_id
      and r.id <> new.id
      and r.status in ('reserved', 'checked_in')
      and tstzrange(r.starts_at, r.ends_at)
          && tstzrange(new.starts_at, new.ends_at)
  ) then
    -- the client pins this substring
    raise exception 'you already have a reservation in that period';
  end if;
  return new;
end;
$$;

drop trigger if exists reservations_one_place on public.reservations;
create trigger reservations_one_place
  before insert on public.reservations
  for each row execute function public.enforce_one_place();

-- 2. check_in_reservation v3 (0077 body + the elsewhere guards).
create or replace function public.check_in_reservation(p_reservation_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_res public.reservations;
  v_own boolean;
begin
  select r.* into v_res from public.reservations r
    where r.id = p_reservation_id;
  if v_res.id is null then raise exception 'not your reservation'; end if;

  select exists (
    select 1 from public.members m
    where m.id = v_res.member_id and m.user_id = auth.uid()
  ) into v_own;

  if not v_own then
    -- The authorized-for-others path (0077): admin/owner + the
    -- bookForOthers feature (default ON, so ABSENT counts as ON).
    if not (
      public.is_admin_of(v_res.workspace_id)
      and coalesce((
        select w.feature_flags->'bookForOthers' is distinct from 'false'::jsonb
        from public.workspaces w where w.id = v_res.workspace_id
      ), true)
    ) then
      raise exception 'not your reservation';
    end if;
  end if;

  if v_res.status <> 'reserved' then raise exception 'not in reserved state'; end if;

  -- Presence window (0077, spec §4.3).
  if now() < v_res.starts_at - interval '15 minutes' then
    raise exception 'check-in window not open yet';
  end if;
  if now() >= v_res.ends_at then
    raise exception 'check-in window closed';
  end if;

  -- One place at a time (#412): a forgotten check-out whose own end has
  -- passed completes itself (stamped at its own end, 0075 semantics)...
  update public.reservations
    set status = 'completed', checked_out_at = ends_at
    where member_id = v_res.member_id
      and id <> v_res.id
      and status = 'checked_in'
      and ends_at <= now();
  -- ...but a check-in still RUNNING elsewhere means the member is
  -- physically somewhere else: refuse, check out there first.
  if exists (
    select 1 from public.reservations r
    where r.member_id = v_res.member_id
      and r.id <> v_res.id
      and r.status = 'checked_in'
      and r.ends_at > now()
  ) then
    -- the client pins this substring
    raise exception 'already checked in elsewhere';
  end if;

  perform public.assert_workspace_open(v_res.workspace_id, now(), now() + interval '1 minute');
  update public.reservations
    set status = 'checked_in', checked_in_at = now()
    where id = p_reservation_id;
end;
$$;

-- 3. create_reservation v8: 0059 body, whole-space right accepts
--    owner/admin.
create or replace function public.create_reservation(
  p_workspace_id uuid,
  p_seat_id uuid,
  p_office_id uuid,
  p_starts_at timestamptz,
  p_ends_at timestamptz,
  p_check_in boolean default false,
  p_level_id uuid default null,
  p_desk_id uuid default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_seat public.seats;
  v_office_id uuid;
  v_level_id uuid;
  v_id uuid;
begin
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if (case when p_seat_id is null then 0 else 1 end
      + case when p_desk_id is null then 0 else 1 end
      + case when p_office_id is null then 0 else 1 end
      + case when p_level_id is null then 0 else 1 end) <> 1 then
    raise exception 'exactly one of seat, desk, office or level required';
  end if;
  perform public.enforce_booking_rules(p_workspace_id, p_starts_at, p_ends_at, p_check_in);

  if p_seat_id is not null then
    select * into v_seat from public.seats
      where id = p_seat_id and workspace_id = p_workspace_id;
    if v_seat.id is null then raise exception 'unknown seat'; end if;
    if tstzrange(coalesce(v_seat.blocked_from, '-infinity'::timestamptz),
                 coalesce(v_seat.blocked_to, 'infinity'::timestamptz))
       && tstzrange(p_starts_at, p_ends_at)
       and (v_seat.blocked_from is not null or v_seat.blocked_to is not null) then
      raise exception 'seat is blocked in that period';
    end if;
    -- 0059: the seat's DESK reserved as a whole blocks the seat.
    if exists (
      select 1 from public.reservations r
      where r.desk_id = v_seat.desk_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'desk is reserved as a whole in that period';
    end if;
    select d.office_id into v_office_id from public.desks d where d.id = v_seat.desk_id;
    if exists (
      select 1 from public.reservations r
      where r.office_id = v_office_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'office is reserved as a whole in that period';
    end if;
    select o.level_id into v_level_id from public.offices o where o.id = v_office_id;
    if exists (
      select 1 from public.reservations r
      where r.level_id = v_level_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'level is reserved as a whole in that period';
    end if;
  elsif p_desk_id is not null then
    -- Whole-DESK path (0059): the level/office gates, desk-scale.
    if not public.level_booking_enabled(p_workspace_id) then
      raise exception 'level booking is not enabled';
    end if;
    if not (v_member.can_reserve_level or v_member.is_owner
            or v_member.is_admin) then
      -- the client pins this substring (0050)
      raise exception 'not allowed to reserve a level';
    end if;
    if not exists (
      select 1 from public.desks d
      where d.id = p_desk_id and d.workspace_id = p_workspace_id
        and d.bookable_as_whole
    ) then
      raise exception 'desk not bookable as a whole';
    end if;
    if exists (
      select 1 from public.reservations r
      join public.seats s on s.id = r.seat_id
      where s.desk_id = p_desk_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'a seat on this desk is already reserved in that period';
    end if;
    select d.office_id into v_office_id from public.desks d where d.id = p_desk_id;
    if exists (
      select 1 from public.reservations r
      where r.office_id = v_office_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'office is reserved as a whole in that period';
    end if;
    select o.level_id into v_level_id from public.offices o where o.id = v_office_id;
    if exists (
      select 1 from public.reservations r
      where r.level_id = v_level_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'level is reserved as a whole in that period';
    end if;
  elsif p_office_id is not null then
    -- Whole-space gates (0057): feature + personal grant, like levels.
    if not public.level_booking_enabled(p_workspace_id) then
      raise exception 'level booking is not enabled';
    end if;
    if not (v_member.can_reserve_level or v_member.is_owner
            or v_member.is_admin) then
      -- the client pins this substring (0050)
      raise exception 'not allowed to reserve a level';
    end if;
    if not exists (
      select 1 from public.offices o
      where o.id = p_office_id and o.workspace_id = p_workspace_id
        and o.bookable_as_whole
    ) then
      raise exception 'office not bookable as a whole';
    end if;
    if exists (
      select 1 from public.reservations r
      join public.seats s on s.id = r.seat_id
      join public.desks d on d.id = s.desk_id
      where d.office_id = p_office_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'a seat in this office is already reserved in that period';
    end if;
    -- 0059: a desk inside reserved as a whole blocks the office too.
    if exists (
      select 1 from public.reservations r
      join public.desks d on d.id = r.desk_id
      where d.office_id = p_office_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'a desk in this office is already reserved in that period';
    end if;
    select o.level_id into v_level_id from public.offices o where o.id = p_office_id;
    if exists (
      select 1 from public.reservations r
      where r.level_id = v_level_id
        and r.status in ('reserved','checked_in')
        and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
    ) then
      raise exception 'level is reserved as a whole in that period';
    end if;
  else
    -- Level path: feature on, level bookable, member personally allowed.
    if not public.level_booking_enabled(p_workspace_id) then
      raise exception 'level booking is not enabled';
    end if;
    if not exists (
      select 1 from public.levels l
      where l.id = p_level_id and l.workspace_id = p_workspace_id
        and l.bookable_as_whole
    ) then
      raise exception 'level not bookable as a whole';
    end if;
    if not (v_member.can_reserve_level or v_member.is_owner
            or v_member.is_admin) then
      -- the client pins this substring
      raise exception 'not allowed to reserve a level';
    end if;
    if public.level_has_conflict(p_level_id, p_starts_at, p_ends_at) then
      raise exception 'the level has reservations in that period';
    end if;
  end if;

  insert into public.reservations
    (workspace_id, seat_id, desk_id, office_id, level_id, member_id,
     starts_at, ends_at, status, checked_in_at)
  values (
    p_workspace_id, p_seat_id, p_desk_id, p_office_id, p_level_id,
    v_member.id, p_starts_at, p_ends_at,
    case when p_check_in then 'checked_in' else 'reserved' end,
    case when p_check_in then now() end
  )
  returning id into v_id;
  perform public.assert_member_quota(v_member.id, p_starts_at);

  -- 0059: whole-space bookings route through the REGULAR validation
  -- feature when the owner configured a rule for them — the reservation
  -- blocks the space immediately, validators confirm or reject (a
  -- reject cancels it via respond_to_event's existing branch).
  if p_desk_id is not null or p_office_id is not null
     or p_level_id is not null then
    if exists (
      select 1 from public.validation_policies vp
      where vp.workspace_id = p_workspace_id
        and vp.event_type = 'space_reservation'
    ) then
      update public.events
        set status = 'pending', type = 'space_reservation'
        where reservation_id = v_id and action = 'created';
    end if;
  end if;
  return v_id;
end;
$$;

-- 4. create_series v3: 0065 body, same exemption.
create or replace function public.create_series(
  p_workspace_id uuid,
  p_seat_id uuid,
  p_first_start timestamptz,
  p_first_end timestamptz,
  p_pattern text,
  p_until timestamptz,
  p_desk_id uuid default null,
  p_office_id uuid default null,
  p_level_id uuid default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_rules jsonb;
  v_max_days int;
  v_series_id uuid := gen_random_uuid();
  v_start timestamptz := p_first_start;
  v_end timestamptz := p_first_end;
  v_tz text;
  v_booked jsonb := '[]'::jsonb;
  v_skipped jsonb := '[]'::jsonb;
  v_step interval;
  v_dow int;
  v_office_of uuid;
  v_level_of uuid;
  v_space boolean;
  v_validated boolean := false;
  v_id uuid;
begin
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if p_pattern not in ('daily','weekdays','weekly') then
    raise exception 'unknown pattern';
  end if;
  if (case when p_seat_id is null then 0 else 1 end
      + case when p_desk_id is null then 0 else 1 end
      + case when p_office_id is null then 0 else 1 end
      + case when p_level_id is null then 0 else 1 end) <> 1 then
    raise exception 'exactly one of seat, desk, office or level required';
  end if;
  v_space := p_seat_id is null;

  select booking_rules, timezone into v_rules, v_tz
    from public.workspaces where id = p_workspace_id;
  v_max_days := coalesce((v_rules->>'max_series_days')::int, 180);
  if p_until > p_first_start + make_interval(days => v_max_days) then
    raise exception 'series exceeds the maximum of % days', v_max_days;
  end if;
  perform public.enforce_booking_rules(p_workspace_id, p_first_start, p_first_end);

  -- One-time whole-space gates — identical to create_reservation v7.
  if v_space then
    if not public.level_booking_enabled(p_workspace_id) then
      raise exception 'level booking is not enabled';
    end if;
    if not (v_member.can_reserve_level or v_member.is_owner
            or v_member.is_admin) then
      -- the client pins this substring (0050)
      raise exception 'not allowed to reserve a level';
    end if;
    if p_desk_id is not null then
      if not exists (
        select 1 from public.desks d
        where d.id = p_desk_id and d.workspace_id = p_workspace_id
          and d.bookable_as_whole
      ) then
        raise exception 'desk not bookable as a whole';
      end if;
      select d.office_id into v_office_of from public.desks d where d.id = p_desk_id;
      select o.level_id into v_level_of from public.offices o where o.id = v_office_of;
    elsif p_office_id is not null then
      if not exists (
        select 1 from public.offices o
        where o.id = p_office_id and o.workspace_id = p_workspace_id
          and o.bookable_as_whole
      ) then
        raise exception 'office not bookable as a whole';
      end if;
      select o.level_id into v_level_of from public.offices o where o.id = p_office_id;
    else
      if not exists (
        select 1 from public.levels l
        where l.id = p_level_id and l.workspace_id = p_workspace_id
          and l.bookable_as_whole
      ) then
        raise exception 'level not bookable as a whole';
      end if;
    end if;
    v_validated := exists (
      select 1 from public.validation_policies vp
      where vp.workspace_id = p_workspace_id
        and vp.event_type = 'space_reservation');
  end if;

  v_step := case when p_pattern = 'weekly' then interval '7 days' else interval '1 day' end;

  while v_start <= p_until loop
    -- weekday filter recurs in workspace-local time (spec §11 DST rule)
    v_dow := extract(isodow from v_start at time zone v_tz)::int;
    if p_pattern <> 'weekdays' or v_dow between 1 and 5 then
      begin
        -- closed days raise here and land in the skipped report, exactly
        -- like conflicts
        perform public.assert_workspace_open(p_workspace_id, v_start, v_end);
        if p_seat_id is not null then
          -- blocked seats too (#161)
          perform public.assert_seat_not_blocked(p_seat_id, v_start, v_end);
        elsif p_desk_id is not null then
          -- Cross-scale conflicts, desk scale (create_reservation v7).
          if exists (
            select 1 from public.reservations r
            join public.seats s on s.id = r.seat_id
            where s.desk_id = p_desk_id
              and r.status in ('reserved','checked_in')
              and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_start, v_end)
          ) then
            raise exception 'a seat on this desk is already reserved in that period';
          end if;
          if exists (
            select 1 from public.reservations r
            where r.office_id = v_office_of
              and r.status in ('reserved','checked_in')
              and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_start, v_end)
          ) then
            raise exception 'office is reserved as a whole in that period';
          end if;
          if exists (
            select 1 from public.reservations r
            where r.level_id = v_level_of
              and r.status in ('reserved','checked_in')
              and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_start, v_end)
          ) then
            raise exception 'level is reserved as a whole in that period';
          end if;
        elsif p_office_id is not null then
          if exists (
            select 1 from public.reservations r
            join public.seats s on s.id = r.seat_id
            join public.desks d on d.id = s.desk_id
            where d.office_id = p_office_id
              and r.status in ('reserved','checked_in')
              and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_start, v_end)
          ) then
            raise exception 'a seat in this office is already reserved in that period';
          end if;
          if exists (
            select 1 from public.reservations r
            join public.desks d on d.id = r.desk_id
            where d.office_id = p_office_id
              and r.status in ('reserved','checked_in')
              and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_start, v_end)
          ) then
            raise exception 'a desk in this office is already reserved in that period';
          end if;
          if exists (
            select 1 from public.reservations r
            where r.level_id = v_level_of
              and r.status in ('reserved','checked_in')
              and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_start, v_end)
          ) then
            raise exception 'level is reserved as a whole in that period';
          end if;
        else
          if public.level_has_conflict(p_level_id, v_start, v_end) then
            raise exception 'the level has reservations in that period';
          end if;
        end if;

        insert into public.reservations
          (workspace_id, seat_id, desk_id, office_id, level_id, member_id,
           starts_at, ends_at, status, series_id)
        values (p_workspace_id, p_seat_id, p_desk_id, p_office_id,
                p_level_id, v_member.id, v_start, v_end, 'reserved',
                v_series_id)
        returning id into v_id;
        -- beyond-quota instances are skipped, not booked
        perform public.assert_member_quota(v_member.id, v_start);
        if v_validated then
          update public.events
            set status = 'pending', type = 'space_reservation'
            where reservation_id = v_id and action = 'created';
        end if;
        v_booked := v_booked || to_jsonb(v_start);
      exception when others then
        v_skipped := v_skipped || to_jsonb(v_start);
      end;
    end if;
    v_start := v_start + v_step;
    v_end := v_end + v_step;
  end loop;

  return jsonb_build_object(
    'series_id', v_series_id,
    'booked', v_booked,
    'skipped', v_skipped
  );
end;
$$;

-- 5. Overrule (#412, owner follow-up): "no multiple reservations —
--    owner/admin only can overrule an existing reservation; the other
--    is removed and the user and all admins/owners are notified."
--    cancel_reservation v2 accepts an admin/owner of the workspace for
--    ANOTHER member's reservation. The reservations_log_event trigger
--    (0007) records the cancellation as an event the displaced member
--    sees in their feed (and admins see everything) — that IS the
--    notification channel, the same one every reservation change uses.
create or replace function public.cancel_reservation(p_reservation_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_res public.reservations;
  v_own boolean;
begin
  select r.* into v_res from public.reservations r
    where r.id = p_reservation_id;
  if v_res.id is null then raise exception 'not your reservation'; end if;

  select exists (
    select 1 from public.members m
    where m.id = v_res.member_id and m.user_id = auth.uid()
  ) into v_own;

  if not v_own and not public.is_admin_of(v_res.workspace_id) then
    raise exception 'not your reservation';
  end if;

  if v_res.status not in ('reserved','checked_in') then
    raise exception 'not cancellable';
  end if;
  update public.reservations set status = 'cancelled' where id = p_reservation_id;
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- Push-driven freshness (#413). The supabase_realtime publication was
-- EMPTY — no table was ever published, so no change was ever pushed to
-- any client: adding a member needed an app restart, and a settings
-- change did not even refresh on the device that made it.
--
-- Publish the tables the app renders. postgres_changes respects RLS
-- (WALRUS) for INSERT/UPDATE — each subscriber only receives rows their
-- SELECT policy grants. DELETEs broadcast the primary key only (bare
-- uuids); the client treats every event as an invalidation signal, so
-- that is all it needs. Deny-all tables (payment_credentials,
-- member_badges, push_endpoints) are deliberately NOT published.

alter publication supabase_realtime add table
  public.reservations,
  public.members,
  public.workspaces,
  public.profiles,
  public.levels,
  public.offices,
  public.desks,
  public.seats,
  public.plan_images,
  public.events,
  public.event_decisions,
  public.ledger_entries,
  public.payment_intents,
  public.invoices,
  public.services,
  public.accessories,
  public.seat_accessories,
  public.closure_days,
  public.quota_extensions,
  public.fee_bands,
  public.packages,
  public.validation_policies;

-- SPDX-License-Identifier: 0BSD
-- Workspace-wide developer mode (#419, owner directive): "the developer
-- mode is applicable on the entire workspace for all users; it can be
-- set by the owner or admins." Until now it was a device-local prefs
-- toggle any user could flip for themselves.
--
-- A column on the workspace row (published by 0080, so realtime pushes
-- a flip to every device live) plus an is_admin_of-gated setter — the
-- workspaces_update RLS stays owner-only, so admins go through the RPC.

alter table public.workspaces
  add column if not exists dev_mode boolean not null default false;

create or replace function public.set_dev_mode(
  p_workspace_id uuid,
  p_enabled boolean
) returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_admin_of(p_workspace_id) then
    raise exception 'not an admin of this workspace';
  end if;
  update public.workspaces set dev_mode = p_enabled
    where id = p_workspace_id;
end;
$$;

revoke execute on function public.set_dev_mode(uuid, boolean) from public, anon;
grant execute on function public.set_dev_mode(uuid, boolean) to authenticated;

-- SPDX-License-Identifier: 0BSD
-- FCM-only push (#426/#428, ADR 0011 — the F-Droid-era UnifiedPush leg
-- is fully removed). Three pieces:
--
--  * push_endpoints holds `fcm:<token>` rows only (the table was empty
--    in production, so the tightened check rewrites history for nobody).
--  * push_config (single row): where the send-push edge function lives.
--    Seeded with the committed publishable pair (ADR 0002 — the same
--    values every client binary ships); self-hosters update the row.
--  * notify_pending_event v3: computes the notifiable kind and pings
--    the send-push function with {event_id} ONLY — the function loads
--    the event itself, derives recipients (0082 rules), signs FCM v1
--    with the FCM_SERVICE_ACCOUNT secret and sets the APNs badge. The
--    direct pg_net POSTs to UnifiedPush endpoints are gone with the
--    transport.

alter table public.push_endpoints
  drop constraint if exists push_endpoints_endpoint_check;
alter table public.push_endpoints
  add constraint push_endpoints_endpoint_check
  check (endpoint ~ '^fcm:');

create table if not exists public.push_config (
  id boolean primary key default true check (id),
  functions_url text not null,
  anon_key text not null
);
alter table public.push_config enable row level security;
-- Deny-all: only the definer function below reads it.

insert into public.push_config (id, functions_url, anon_key)
values (
  true,
  'https://zwzbynivewivvjmripeb.supabase.co/functions/v1',
  'sb_publishable_PqXoa0tyQTjsZCPD_LrEQw_P7LJtalL'
)
on conflict (id) do nothing;

create or replace function public.notify_pending_event()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_kind text;
  v_cfg public.push_config;
begin
  if new.status = 'pending'
     and (tg_op = 'INSERT' or old.status <> 'pending') then
    v_kind := 'pending_request';
  elsif new.type = 'reservation' and new.action = 'cancelled'
     and new.actor_member_id <> new.subject_member_id
     and (tg_op = 'INSERT'
          or old.actor_member_id = old.subject_member_id) then
    v_kind := 'reservation_cancelled';
  end if;

  if v_kind is not null then
    select * into v_cfg from public.push_config where id;
    if v_cfg.functions_url is not null then
      begin
        perform net.http_post(
          url := v_cfg.functions_url || '/send-push',
          headers := jsonb_build_object(
            'Authorization', 'Bearer ' || v_cfg.anon_key,
            'Content-Type', 'application/json'
          ),
          body := jsonb_build_object('event_id', new.id),
          timeout_milliseconds := 5000
        );
      exception when others then
        null;  -- best-effort: push must never fail the event
      end;
    end if;
  end if;
  return new;
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- kiosk_act v4 (#430): the kiosk under the presence + one-place rules.
--
-- Field breakage: the check-in path found the member's own reservation
-- only once starts_at <= now(). Badging up to 15 minutes EARLY — the
-- exact leeway 0077 grants everywhere else — fell through to a walk-up
-- INSERT on the same seat, which the 0079 one-place trigger rightly
-- refuses: the member was blocked from checking into their own
-- imminent reservation. (Before 0079 the same fall-through silently
-- created the overlapping double-booking of #412.)
--
-- v4: both find queries use the 15-minute leeway, and the flip paths
-- carry check_in_reservation v3's guards — stale check-ins complete at
-- their own end, a still-running check-in elsewhere refuses with the
-- pinned substring.

create or replace function public.kiosk_act(
  p_workspace_id uuid,
  p_badge_token text,
  p_action text,             -- 'reserve' | 'check_in' | 'check_out'
  p_seat_id uuid default null,
  p_starts_at timestamptz default null,
  p_ends_at timestamptz default null,
  p_level_id uuid default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_kiosk public.members;
  v_badge public.member_badges;
  v_subject public.members;
  v_seat public.seats;
  v_office_id uuid;
  v_res public.reservations;
  v_id uuid;
begin
  select * into v_kiosk from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and is_kiosk;
  if v_kiosk.id is null then raise exception 'not a kiosk of this workspace'; end if;

  select * into v_badge from public.member_badges
    where workspace_id = p_workspace_id
      and token_hash = public.badge_token_hash(p_badge_token)
      and revoked_at is null;
  if v_badge.id is null then
    raise exception 'badge not recognized';
  end if;
  select * into v_subject from public.members
    where id = v_badge.member_id and status = 'active';
  if v_subject.id is null then raise exception 'badge member not active'; end if;

  if p_action = 'check_out' then
    select r.* into v_res from public.reservations r
      where r.member_id = v_subject.id and r.status = 'checked_in'
        and (p_seat_id is null or r.seat_id = p_seat_id)
        and (p_level_id is null or r.level_id = p_level_id)
      order by r.checked_in_at desc limit 1;
    if v_res.id is null then raise exception 'not checked in'; end if;
    update public.reservations
      set status = 'completed', checked_out_at = now(),
          ends_at = least(ends_at, now())
      where id = v_res.id;
    return jsonb_build_object('action', 'check_out', 'reservation_id', v_res.id);
  end if;

  if p_action not in ('reserve', 'check_in') then
    raise exception 'unknown kiosk action';
  end if;
  if (p_seat_id is null) = (p_level_id is null)
     or p_starts_at is null or p_ends_at is null then
    raise exception 'seat or level, and window required';
  end if;

  if p_level_id is not null then
    -- Level path: same gates as create_reservation — feature, bookable,
    -- the badge member's personal grant, no conflicts on the level.
    if not public.level_booking_enabled(p_workspace_id) then
      raise exception 'level booking is not enabled';
    end if;
    if not exists (
      select 1 from public.levels l
      where l.id = p_level_id and l.workspace_id = p_workspace_id
        and l.bookable_as_whole
    ) then
      raise exception 'level not bookable as a whole';
    end if;
    if not v_subject.can_reserve_level then
      raise exception 'not allowed to reserve a level';
    end if;

    if p_action = 'check_in' then
      select r.* into v_res from public.reservations r
        where r.member_id = v_subject.id and r.level_id = p_level_id
          and r.status = 'reserved'
          -- 0077 presence leeway (#430): badging up to 15 min early must
          -- find the reservation, not fall through to a walk-up insert
          -- the one-place trigger rightly refuses.
          and r.starts_at - interval '15 minutes' <= now()
          and r.ends_at > now()
        limit 1;
      if v_res.id is not null then
        -- One place (#430, mirroring check_in_reservation v3): stale
        -- check-ins complete at their own end; still-running elsewhere
        -- refuses with the pinned substring.
        update public.reservations
          set status = 'completed', checked_out_at = ends_at
          where member_id = v_subject.id and id <> v_res.id
            and status = 'checked_in' and ends_at <= now();
        if exists (
          select 1 from public.reservations r2
          where r2.member_id = v_subject.id and r2.id <> v_res.id
            and r2.status = 'checked_in' and r2.ends_at > now()
        ) then
          raise exception 'already checked in elsewhere';
        end if;
        update public.reservations
          set status = 'checked_in', checked_in_at = now()
          where id = v_res.id;
        return jsonb_build_object('action', 'check_in', 'reservation_id', v_res.id);
      end if;
    end if;

    perform public.enforce_booking_rules(
      p_workspace_id, p_starts_at, p_ends_at, p_action = 'check_in');
    if public.level_has_conflict(p_level_id, p_starts_at, p_ends_at) then
      raise exception 'the level has reservations in that period';
    end if;

    insert into public.reservations
      (workspace_id, level_id, member_id, starts_at, ends_at, status, checked_in_at)
    values (
      p_workspace_id, p_level_id, v_subject.id, p_starts_at, p_ends_at,
      case when p_action = 'check_in' then 'checked_in' else 'reserved' end,
      case when p_action = 'check_in' then now() end
    )
    returning id into v_id;
    perform public.assert_member_quota(v_subject.id, p_starts_at);
    return jsonb_build_object('action', p_action, 'reservation_id', v_id);
  end if;

  select * into v_seat from public.seats
    where id = p_seat_id and workspace_id = p_workspace_id;
  if v_seat.id is null then raise exception 'unknown seat'; end if;

  if p_action = 'check_in' then
    select r.* into v_res from public.reservations r
      where r.member_id = v_subject.id and r.seat_id = p_seat_id
        and r.status = 'reserved'
        -- 0077 presence leeway (#430), as on the level path above.
        and r.starts_at - interval '15 minutes' <= now()
        and r.ends_at > now()
      limit 1;
    if v_res.id is not null then
      -- One place (#430): same guards as the level path.
      update public.reservations
        set status = 'completed', checked_out_at = ends_at
        where member_id = v_subject.id and id <> v_res.id
          and status = 'checked_in' and ends_at <= now();
      if exists (
        select 1 from public.reservations r2
        where r2.member_id = v_subject.id and r2.id <> v_res.id
          and r2.status = 'checked_in' and r2.ends_at > now()
      ) then
        raise exception 'already checked in elsewhere';
      end if;
      update public.reservations
        set status = 'checked_in', checked_in_at = now()
        where id = v_res.id;
      return jsonb_build_object('action', 'check_in', 'reservation_id', v_res.id);
    end if;
  end if;

  perform public.enforce_booking_rules(
    p_workspace_id, p_starts_at, p_ends_at, p_action = 'check_in');
  if tstzrange(coalesce(v_seat.blocked_from, '-infinity'::timestamptz),
               coalesce(v_seat.blocked_to, 'infinity'::timestamptz))
     && tstzrange(p_starts_at, p_ends_at)
     and (v_seat.blocked_from is not null or v_seat.blocked_to is not null) then
    raise exception 'seat is blocked in that period';
  end if;
  -- 0059: the seat's DESK reserved as a whole blocks the walk-up too.
  if exists (
    select 1 from public.reservations r
    where r.desk_id = v_seat.desk_id
      and r.status in ('reserved','checked_in')
      and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
  ) then
    raise exception 'desk is reserved as a whole in that period';
  end if;
  select d.office_id into v_office_id from public.desks d where d.id = v_seat.desk_id;
  if exists (
    select 1 from public.reservations r
    where r.office_id = v_office_id
      and r.status in ('reserved','checked_in')
      and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
  ) then
    raise exception 'office is reserved as a whole in that period';
  end if;
  if exists (
    select 1 from public.reservations r
    where r.level_id = (select o.level_id from public.offices o where o.id = v_office_id)
      and r.status in ('reserved','checked_in')
      and tstzrange(r.starts_at, r.ends_at) && tstzrange(p_starts_at, p_ends_at)
  ) then
    raise exception 'level is reserved as a whole in that period';
  end if;

  insert into public.reservations
    (workspace_id, seat_id, member_id, starts_at, ends_at, status, checked_in_at)
  values (
    p_workspace_id, p_seat_id, v_subject.id, p_starts_at, p_ends_at,
    case when p_action = 'check_in' then 'checked_in' else 'reserved' end,
    case when p_action = 'check_in' then now() end
  )
  returning id into v_id;
  perform public.assert_member_quota(v_subject.id, p_starts_at);
  return jsonb_build_object('action', p_action, 'reservation_id', v_id);
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- No self-validation, ever (#434). Owner rule: "when validating, only
-- another person can validate; no person can validate himself his own
-- event." respond_to_event v-next drops the #107 solo escape hatch —
-- the actor was admitted to the pool when it was otherwise empty. The
-- subject-as-fallback path stays: the subject of someone ELSE's action
-- is another person. Everything below the eligibility check is the
-- 0072 body unchanged.

create or replace function public.respond_to_event(
  p_event_id uuid,
  p_accept boolean
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_event public.events;
  v_caller public.members;
  v_policy record;
  v_subject_decides boolean;
  v_in_pool boolean;
  v_pool_size int;
  v_required int;
  v_accepts int;
  v_subject_ok boolean;
  v_owner_ok boolean;
begin
  select e.* into v_event from public.events e where e.id = p_event_id;
  if v_event.id is null then raise exception 'unknown event'; end if;
  if v_event.status <> 'pending' then raise exception 'already decided'; end if;

  select m.* into v_caller from public.members m
    where m.workspace_id = v_event.workspace_id and m.user_id = auth.uid()
      and m.status = 'active';
  if v_caller.id is null then raise exception 'not a member'; end if;
  if exists (select 1 from public.event_decisions d
              where d.event_id = p_event_id and d.member_id = v_caller.id) then
    raise exception 'you already decided this event';
  end if;

  select * into v_policy from public.validation_policies
    where workspace_id = v_event.workspace_id and event_type = v_event.type;
  if v_policy is null then
    select * into v_policy from public.validation_policies
      where workspace_id = v_event.workspace_id and event_type is null;
  end if;
  if v_policy is null then
    select null::uuid as id, v_event.workspace_id as workspace_id,
           null::text as event_type, 1 as required_count,
           true as admins_may_validate, '{}'::uuid[] as eligible_admin_ids,
           false as owner_required
      into v_policy;
  end if;

  v_subject_decides := v_event.type = 'reservation'
    or (v_event.type in ('payment','service_charge')
        and v_event.actor_member_id <> v_event.subject_member_id);

  select count(*) into v_pool_size from public.members m
    where m.workspace_id = v_event.workspace_id and m.status = 'active'
      and m.id not in (v_event.actor_member_id, v_event.subject_member_id)
      and (m.is_owner or (m.is_admin and v_policy.admins_may_validate
           and (cardinality(v_policy.eligible_admin_ids) = 0
                or m.id = any(v_policy.eligible_admin_ids))));

  v_in_pool := (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate
                and (cardinality(v_policy.eligible_admin_ids) = 0
                     or v_caller.id = any(v_policy.eligible_admin_ids))))
    and (v_caller.id <> v_event.subject_member_id
         or (not v_subject_decides and v_pool_size = 0))
    -- #434 (owner rule): NOBODY validates their own event — the #107
    -- solo escape hatch (actor admitted when the pool was empty) is
    -- gone. A pool that collapses to the actor leaves the event pending
    -- until it expires: never granted silently, never self-granted.
    and v_caller.id <> v_event.actor_member_id;
  if v_pool_size = 0
     and v_caller.id <> v_event.actor_member_id
     and (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate)) then
    v_pool_size := 1;
  end if;

  if v_subject_decides and v_caller.id = v_event.subject_member_id then
    null;
  elsif v_in_pool then
    null;
  else
    raise exception 'you are not an eligible validator for this event';
  end if;

  insert into public.event_decisions (event_id, member_id, decision)
  values (p_event_id, v_caller.id, case when p_accept then 'accept' else 'reject' end);

  if not p_accept then
    update public.events set status = 'rejected', decided_at = now()
      where id = p_event_id;
    if v_event.reservation_id is not null then
      update public.reservations set status = 'cancelled'
        where id = v_event.reservation_id and status in ('reserved','checked_in');
    end if;
    if v_event.type = 'member_join' then
      update public.members set status = 'exited'
        where id = v_event.subject_member_id and status = 'pending';
    end if;
    if v_event.type = 'invoice_payment' then
      delete from public.ledger_entries
        where id = (select credit_ledger_id from public.invoice_matches
                     where event_id = v_event.id);
      delete from public.invoice_matches where event_id = v_event.id;
    end if;
    return;
  end if;

  select count(*) into v_accepts from public.event_decisions
    where event_id = p_event_id and decision = 'accept';
  v_required := greatest(1, least(v_policy.required_count,
    v_pool_size + case when v_subject_decides then 1 else 0 end));
  v_subject_ok := not v_subject_decides or exists (
    select 1 from public.event_decisions d
    where d.event_id = p_event_id and d.decision = 'accept'
      and d.member_id = v_event.subject_member_id);
  v_owner_ok := not v_policy.owner_required or exists (
    select 1 from public.event_decisions d
    join public.members m on m.id = d.member_id
    where d.event_id = p_event_id and d.decision = 'accept' and m.is_owner);

  if v_accepts >= v_required and v_subject_ok and v_owner_ok then
    update public.events set status = 'confirmed', decided_at = now()
      where id = p_event_id;

    if v_event.type in ('payment','expense') then
      -- 0070: the payer's own date and target month when the payload
      -- carries them; the old behaviour (today, current month) when not.
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description,
         period, event_id, occurred_on)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'credit',
        case when v_event.type = 'payment' then 'payment' else 'expense' end,
        (v_event.payload->>'amount_cents')::int,
        coalesce(v_event.payload->>'note', ''),
        coalesce(v_event.payload->>'period', to_char(now(), 'YYYY-MM')),
        v_event.id,
        (v_event.payload->>'paid_on')::date
      );
    elsif v_event.type = 'service_charge' then
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description,
         period, event_id, vat_percent)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'charge', 'service',
        (v_event.payload->>'amount_cents')::int,
        (v_event.payload->>'name') || ' x' || (v_event.payload->>'quantity'),
        coalesce(v_event.payload->>'period', to_char(now(), 'YYYY-MM')),
        v_event.id,
        -- 0072: the rate agreed when the charge was recorded.
        (v_event.payload->>'vat_percent')::numeric
      );
    elsif v_event.type = 'quota' then
      insert into public.quota_extensions
        (workspace_id, member_id, period, half_days, event_id)
      values (
        v_event.workspace_id, v_event.subject_member_id,
        v_event.payload->>'period',
        (v_event.payload->>'half_days')::int,
        v_event.id
      );
    elsif v_event.type = 'role_change' then
      update public.members
        set is_admin = (v_event.payload->>'make_admin')::boolean
        where id = v_event.subject_member_id;
    elsif v_event.type = 'member_join' then
      -- the validated welcome: the pending membership becomes active
      update public.members set status = 'active'
        where id = v_event.subject_member_id and status = 'pending';
    elsif v_event.type = 'invoice_payment' then
      update public.invoice_matches set status = 'confirmed'
        where event_id = v_event.id;
    end if;
  end if;
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- Configurable working hours + the 'hours' booking granularity (#446).
--
-- booking_rules learns five owner-set keys (WorkHours on the client):
--   * work_start_minutes    (default 480  = 08:00)
--   * half_boundary_minutes (default 720  = 12:00)
--   * work_end_minutes      (default 1020 = 17:00)
--   * half_day_hours        (default 4)  — hours billed as a half day
--   * full_day_hours        (default 8)  — hours billed as a full day
-- and granularity accepts 'hours' next to the 0032 values: free
-- from-to bookings with no server grid, billed as half-day equivalents.
--
-- Three functions are re-emitted:
--   * enforce_booking_rules v4 — the half/full-day canonical windows
--     are the configured working day instead of the hardwired
--     00:00/13:00/24:00; walk-ups end at the next canonical edge, and
--     at/after the end of the working day may run to local midnight
--     (late-arrival overtime). Error substrings unchanged (pinned by
--     the client): 'half-day', 'cover the full day', 'minute grid'.
--   * member_statement v8 (v7: 0059) — the slot pivot is the
--     configured boundary; under 'hours' the used half-days and the
--     seat/level/office/desk supplements convert booked time to
--     half-day equivalents (1 per started half_day_hours block,
--     capped at 2 per day).
--   * assert_member_quota v3 (v2: 0041) — same boundary + same
--     hours-mode conversion, so the quota cap and the bill agree.
--
-- Existing reservations keep their stored instants; only NEW inserts
-- are constrained. Workspaces that never touch the new keys get the
-- 8:00-17:00 defaults (this CHANGES the canonical windows from the old
-- 00:00-13:00-24:00 — the owner-requested new default working day).

create or replace function public.enforce_booking_rules(
  p_workspace_id uuid, p_starts_at timestamptz, p_ends_at timestamptz,
  p_walk_up boolean default false
) returns void language plpgsql stable security definer set search_path = public as $$
declare rules jsonb; horizon int; min_min int; max_min int; dur int;
        tz text; local_start timestamp; local_end timestamp;
        gran text; slot int;
        ws_start int; ws_bound int; ws_end int;
        d date; ts_start timestamp; ts_bound timestamp; ts_end timestamp;
        ts_midnight timestamp;
begin
  select booking_rules, timezone into rules, tz
    from public.workspaces where id = p_workspace_id;
  horizon := coalesce((rules->>'advance_horizon_days')::int, 90);
  min_min := coalesce((rules->>'min_duration_minutes')::int, 30);
  max_min := coalesce((rules->>'max_duration_minutes')::int, 1440);
  if p_starts_at > now() + make_interval(days => horizon) then
    raise exception 'beyond the advance-booking horizon of % days', horizon;
  end if;
  dur := extract(epoch from (p_ends_at - p_starts_at))::int / 60;
  if dur < min_min then
    raise exception 'below the minimum duration of % minutes', min_min;
  end if;
  if dur > max_min then
    raise exception 'above the maximum duration of % minutes', max_min;
  end if;

  gran := rules->>'granularity';
  local_start := p_starts_at at time zone tz;
  local_end := p_ends_at at time zone tz;

  -- #446: the working day comes from booking_rules (defaults 8:00 /
  -- 12:00 / 17:00 — WorkHours.defaults on the client). An inconsistent
  -- triple falls back to the defaults exactly like the client, so the
  -- constraint and the UI always agree on the canonical windows.
  ws_start := coalesce((rules->>'work_start_minutes')::int, 480);
  ws_bound := coalesce((rules->>'half_boundary_minutes')::int, 720);
  ws_end := coalesce((rules->>'work_end_minutes')::int, 1020);
  if not (ws_start >= 0 and ws_start < ws_bound
          and ws_bound < ws_end and ws_end <= 1440) then
    ws_start := 480; ws_bound := 720; ws_end := 1020;
  end if;
  d := local_start::date;
  ts_start := d::timestamp + make_interval(mins => ws_start);
  ts_bound := d::timestamp + make_interval(mins => ws_bound);
  ts_end := d::timestamp + make_interval(mins => ws_end);
  ts_midnight := d::timestamp + interval '1 day';

  -- Half-day granularity (#200/#201, #446): the three canonical
  -- windows are now the CONFIGURED working day — morning start-to-
  -- boundary, afternoon boundary-to-end, full day start-to-end.
  -- Walk-ups start "now" and end at the next canonical edge; at or
  -- after the end of the working day they may run to local midnight
  -- (overtime — the old 0026 behaviour for late arrivals). The client
  -- pins the substring 'half-day' (BookingGranularityError).
  if gran = 'half_day' then
    if p_walk_up then
      if not (
        (local_start < ts_bound and local_end = ts_bound)
        or (local_start >= ts_bound and local_start < ts_end
            and local_end = ts_end)
        or (local_start >= ts_end and local_end = ts_midnight)
      ) then
        raise exception 'walk-ups must end at the half-day boundary or the end of the working day';
      end if;
    elsif not (
      (local_start = ts_start and local_end = ts_bound)
      or (local_start = ts_bound and local_end = ts_end)
      or (local_start = ts_start and local_end = ts_end)
    ) then
      raise exception 'bookings must cover a half-day or the full working day';
    end if;

  -- Full-day granularity (0032, #446): exactly the working day. The
  -- client pins the substring 'cover the full day'.
  elsif gran = 'full_day' then
    if not (
      (local_end = ts_end and (p_walk_up or local_start = ts_start))
      or (p_walk_up and local_start >= ts_end and local_end = ts_midnight)
    ) then
      raise exception 'bookings must cover the full day (working hours)';
    end if;

  -- Minute grid (0032): unchanged. 'hours' (#446) deliberately matches
  -- no branch — free from-to times, no grid; billing converts booked
  -- time to half-day equivalents (member_statement v8).
  elsif gran in ('minutes_5','minutes_15','minutes_30','minutes_60') then
    slot := split_part(gran, '_', 2)::int;
    if not (
      extract(second from local_end) = 0
      and extract(minute from local_end)::int % slot = 0
      and (p_walk_up or (
        extract(second from local_start) = 0
        and extract(minute from local_start)::int % slot = 0))
    ) then
      raise exception 'bookings must start and end on the %-minute grid', slot;
    end if;
  end if;

  perform public.assert_workspace_open(p_workspace_id, p_starts_at, p_ends_at);
end;
$$;
revoke execute on function public.enforce_booking_rules(uuid, timestamptz, timestamptz, boolean) from public, anon, authenticated;

