-- member_statement v8 (body from 0059 v7; changes marked #446).
create or replace function public.member_statement(
  p_member_id uuid,
  p_period text
) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_member public.members;
  v_caller_is_admin boolean;
  v_band public.fee_bands;
  v_tz text;
  v_open int[];
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_month_first date;
  v_open_days int;
  v_pct int;
  v_included int;
  v_used int;
  v_base int := 0;
  v_overage int := 0;
  v_overage_rate int := 0;
  v_credits int;
  v_extra_half_days int := 0;
  v_supp_on boolean := false;
  v_supp_since timestamptz;
  v_supplement int := 0;
  v_granted int := 0;
  v_cap int := 0;
  v_remaining int := 0;
  v_level_supplement int := 0;
  v_office_supplement int := 0;
  -- #desk (0059)
  v_desk_supplement int := 0;
  -- #446 working hours
  v_rules jsonb;
  v_gran text;
  v_bound int;
  v_half_minutes numeric;
begin
  select * into v_member from public.members where id = p_member_id;
  if v_member.id is null then raise exception 'unknown member'; end if;
  v_caller_is_admin := public.is_admin_of(v_member.workspace_id);
  if not v_caller_is_admin and not exists (
    select 1 from public.members m
    where m.id = p_member_id and m.user_id = auth.uid()
  ) then
    raise exception 'not your statement';
  end if;

  select timezone,
         coalesce((select array_agg(x::int)
                     from jsonb_array_elements_text(booking_rules->'open_weekdays') x),
                  array[1,2,3,4,5]),
         coalesce(feature_flags -> 'accessorySupplements' = to_jsonb(true), false),
         accessory_supplements_since,
         booking_rules
    into v_tz, v_open, v_supp_on, v_supp_since, v_rules
    from public.workspaces where id = v_member.workspace_id;
  -- #446: the half-day boundary and the hours-mode billing equivalents
  -- come from booking_rules; inconsistent values fall back to the
  -- defaults exactly like the client (WorkHours.fromRules).
  v_gran := v_rules->>'granularity';
  v_bound := coalesce((v_rules->>'half_boundary_minutes')::int, 720);
  if v_bound <= 0 or v_bound >= 1440 then v_bound := 720; end if;
  v_half_minutes := greatest(1, coalesce((v_rules->>'half_day_hours')::int, 4)) * 60.0;
  v_period_start := to_timestamp(p_period || '-01', 'YYYY-MM-DD') at time zone v_tz;
  v_period_end := (to_timestamp(p_period || '-01', 'YYYY-MM-DD') + interval '1 month') at time zone v_tz;
  v_month_first := to_date(p_period || '-01', 'YYYY-MM-DD');

  v_pct := coalesce(v_member.subscription_pct, 100);
  select * into v_band from public.fee_bands
    where workspace_id = v_member.workspace_id
      and from_pct < v_pct and v_pct <= to_pct;
  if v_band.id is not null then
    v_base := v_band.fee_cents;
    v_overage_rate := v_band.overage_fee_cents;
  end if;

  select count(*) into v_open_days
  from generate_series(v_month_first,
                       (v_month_first + interval '1 month' - interval '1 day')::date,
                       interval '1 day') d
  where extract(isodow from d)::int = any(v_open)
    and not exists (select 1 from public.closure_days c
                     where c.workspace_id = v_member.workspace_id and c.day = d::date);
  v_included := ceil(v_open_days * 2 * v_pct / 100.0)::int;

  select count(distinct (date_trunc('day', r.starts_at at time zone v_tz)::date, s.slot))
  into v_used
  from public.reservations r
  cross join lateral (
    select case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
           then 0 else 1 end as slot
  ) s
  where r.member_id = p_member_id
    and r.status in ('reserved','checked_in','completed')
    and r.starts_at >= v_period_start and r.starts_at < v_period_end;

  -- #446 hours granularity: booked time per day converts to half-day
  -- equivalents — one half day per STARTED half_day_hours block,
  -- capped at 2 (a full day is two halves).
  if v_gran = 'hours' then
    select coalesce(sum(least(2, greatest(1,
             ceil(d.day_minutes / v_half_minutes)::int))), 0)
    into v_used
    from (
      select date_trunc('day', r.starts_at at time zone v_tz)::date as day,
             sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
               as day_minutes
      from public.reservations r
      where r.member_id = p_member_id
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start and r.starts_at < v_period_end
      group by 1
    ) d;
  end if;

  v_extra_half_days := greatest(0, v_used - v_included);
  v_overage := v_extra_half_days * v_overage_rate;

  select coalesce(sum(half_days), 0) into v_granted from public.quota_extensions
    where member_id = p_member_id and period = p_period;
  v_cap := v_included + v_granted;
  v_remaining := greatest(0, v_cap - v_used);

  if v_supp_on and v_supp_since is not null then
    if v_gran = 'hours' then
      -- #446: half-day-equivalent units per seat and day.
      select coalesce(sum(seat_supp.total_cents * hd.units), 0)
      into v_supplement
      from (
      select r.seat_id,
             least(2, greatest(1, ceil(
               sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
                 / v_half_minutes)::int)) as units
      from public.reservations r
      where r.member_id = p_member_id
        and r.seat_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= greatest(v_period_start, v_supp_since)
        and r.starts_at < v_period_end
      group by r.seat_id,
               date_trunc('day', r.starts_at at time zone v_tz)::date
    ) hd
      join (
      select sa.seat_id, sum(a.supplement_cents)::int as total_cents
      from public.seat_accessories sa
      join public.accessories a on a.id = sa.accessory_id
      where a.active and a.supplement_cents > 0
      group by sa.seat_id
    ) seat_supp on seat_supp.seat_id = hd.seat_id;
    else
      select coalesce(sum(seat_supp.total_cents), 0) into v_supplement
      from (
        select distinct
          r.seat_id,
          date_trunc('day', r.starts_at at time zone v_tz)::date as day,
          case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                  + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
             then 0 else 1 end as slot
        from public.reservations r
        where r.member_id = p_member_id
          and r.seat_id is not null
          and r.status in ('reserved','checked_in','completed')
          and r.starts_at >= greatest(v_period_start, v_supp_since)
          and r.starts_at < v_period_end
      ) hd
      join (
        select sa.seat_id, sum(a.supplement_cents)::int as total_cents
        from public.seat_accessories sa
        join public.accessories a on a.id = sa.accessory_id
        where a.active and a.supplement_cents > 0
        group by sa.seat_id
      ) seat_supp on seat_supp.seat_id = hd.seat_id;
    end if;
  end if;

  if v_gran = 'hours' then
    select coalesce(sum(l.price_cents * hx.units), 0) into v_level_supplement
    from (
      select r.level_id,
             least(2, greatest(1, ceil(
               sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
                 / v_half_minutes)::int)) as units
      from public.reservations r
      where r.member_id = p_member_id
        and r.level_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start
        and r.starts_at < v_period_end
      group by r.level_id,
               date_trunc('day', r.starts_at at time zone v_tz)::date
    ) hx
    join public.levels l on l.id = hx.level_id;
  else
    select coalesce(sum(l.price_cents), 0) into v_level_supplement
    from (
      select distinct
        r.level_id,
        date_trunc('day', r.starts_at at time zone v_tz)::date as day,
        case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                  + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
             then 0 else 1 end as slot
      from public.reservations r
      where r.member_id = p_member_id
        and r.level_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start and r.starts_at < v_period_end
    ) lh
    join public.levels l on l.id = lh.level_id;
  end if;

  -- #office: price × distinct half-days per reserved office.
  if v_gran = 'hours' then
    select coalesce(sum(o.price_cents * hx.units), 0) into v_office_supplement
    from (
      select r.office_id,
             least(2, greatest(1, ceil(
               sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
                 / v_half_minutes)::int)) as units
      from public.reservations r
      where r.member_id = p_member_id
        and r.office_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start
        and r.starts_at < v_period_end
      group by r.office_id,
               date_trunc('day', r.starts_at at time zone v_tz)::date
    ) hx
    join public.offices o on o.id = hx.office_id;
  else
    select coalesce(sum(o.price_cents), 0) into v_office_supplement
    from (
      select distinct
        r.office_id,
        date_trunc('day', r.starts_at at time zone v_tz)::date as day,
        case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                  + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
             then 0 else 1 end as slot
      from public.reservations r
      where r.member_id = p_member_id
        and r.office_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start and r.starts_at < v_period_end
    ) oh
    join public.offices o on o.id = oh.office_id;
  end if;

  -- #desk: price × distinct half-days per reserved desk (0059).
  if v_gran = 'hours' then
    select coalesce(sum(d.price_cents * hx.units), 0) into v_desk_supplement
    from (
      select r.desk_id,
             least(2, greatest(1, ceil(
               sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
                 / v_half_minutes)::int)) as units
      from public.reservations r
      where r.member_id = p_member_id
        and r.desk_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start
        and r.starts_at < v_period_end
      group by r.desk_id,
               date_trunc('day', r.starts_at at time zone v_tz)::date
    ) hx
    join public.desks d on d.id = hx.desk_id;
  else
    select coalesce(sum(d.price_cents), 0) into v_desk_supplement
    from (
      select distinct
        r.desk_id,
        date_trunc('day', r.starts_at at time zone v_tz)::date as day,
        case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                  + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
             then 0 else 1 end as slot
      from public.reservations r
      where r.member_id = p_member_id
        and r.desk_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start and r.starts_at < v_period_end
    ) dh
    join public.desks d on d.id = dh.desk_id;
  end if;

  select coalesce(sum(case when kind = 'credit' then amount_cents else -amount_cents end), 0)
  into v_credits
  from public.ledger_entries
  where member_id = p_member_id and period = p_period;

  return jsonb_build_object(
    'period', p_period,
    'subscription_pct', v_pct,
    'fee_cents', v_base,
    'included_half_days', v_included,
    'open_days', v_open_days,
    'used_half_days', v_used,
    'extra_half_days', v_extra_half_days,
    'overage_cents', v_overage,
    'accessory_supplement_cents', v_supplement,
    'level_supplement_cents', v_level_supplement,
    -- #office
    'office_supplement_cents', v_office_supplement,
    'desk_supplement_cents', v_desk_supplement,
    'credits_cents', v_credits,
    'balance_cents',
      v_credits - v_base - v_overage - v_supplement - v_level_supplement
        - v_office_supplement - v_desk_supplement,
    'overage_policy', coalesce(v_member.overage_policy, 'blocked'),
    'overage_rate_cents', v_overage_rate,
    'granted_half_days', v_granted,
    'remaining_half_days', v_remaining
  );
end;
$$;
revoke execute on function public.member_statement(uuid, text) from public, anon;

-- ---------------------------------------------------------------------

-- assert_member_quota v3 (body from 0041 v2; changes marked #446).
create or replace function public.assert_member_quota(
  p_member_id uuid, p_at timestamptz
) returns void language plpgsql stable security definer set search_path = public as $$
declare
  v_member public.members;
  v_tz text;
  v_open int[];
  v_pct int;
  v_period text;
  v_month_first date;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_open_days int;
  v_included int;
  v_ext int;
  v_used int;
  -- #446 working hours
  v_rules jsonb;
  v_gran text;
  v_bound int;
  v_half_minutes numeric;
begin
  select * into v_member from public.members where id = p_member_id;
  select timezone,
         coalesce((select array_agg(x::int)
                     from jsonb_array_elements_text(booking_rules->'open_weekdays') x),
                  array[1,2,3,4,5]),
         booking_rules
    into v_tz, v_open, v_rules
    from public.workspaces where id = v_member.workspace_id;
  -- #446: boundary + hours-mode equivalents, defaults like the client.
  v_gran := v_rules->>'granularity';
  v_bound := coalesce((v_rules->>'half_boundary_minutes')::int, 720);
  if v_bound <= 0 or v_bound >= 1440 then v_bound := 720; end if;
  v_half_minutes := greatest(1, coalesce((v_rules->>'half_day_hours')::int, 4)) * 60.0;

  v_period := to_char(p_at at time zone v_tz, 'YYYY-MM');
  v_month_first := to_date(v_period || '-01', 'YYYY-MM-DD');
  v_period_start := to_timestamp(v_period || '-01', 'YYYY-MM-DD') at time zone v_tz;
  v_period_end := (to_timestamp(v_period || '-01', 'YYYY-MM-DD') + interval '1 month') at time zone v_tz;

  v_pct := coalesce(v_member.subscription_pct, 100);
  select count(*) into v_open_days
  from generate_series(v_month_first,
                       (v_month_first + interval '1 month' - interval '1 day')::date,
                       interval '1 day') d
  where extract(isodow from d)::int = any(v_open)
    and not exists (select 1 from public.closure_days c
                     where c.workspace_id = v_member.workspace_id and c.day = d::date);
  v_included := ceil(v_open_days * 2 * v_pct / 100.0)::int;

  select coalesce(sum(half_days), 0) into v_ext from public.quota_extensions
    where member_id = p_member_id and period = v_period;

  select count(distinct (date_trunc('day', r.starts_at at time zone v_tz)::date, s.slot))
  into v_used
  from public.reservations r
  cross join lateral (
    select case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
           then 0 else 1 end as slot
  ) s
  where r.member_id = p_member_id
    and r.status in ('reserved','checked_in','completed')
    and r.starts_at >= v_period_start and r.starts_at < v_period_end;

  -- #446 hours granularity: same half-day-equivalent conversion as
  -- member_statement, so the cap and the bill agree.
  if v_gran = 'hours' then
    select coalesce(sum(least(2, greatest(1,
             ceil(d.day_minutes / v_half_minutes)::int))), 0)
    into v_used
    from (
      select date_trunc('day', r.starts_at at time zone v_tz)::date as day,
             sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
               as day_minutes
      from public.reservations r
      where r.member_id = p_member_id
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start and r.starts_at < v_period_end
      group by 1
    ) d;
  end if;

  if v_used > v_included + v_ext then
    -- pay-as-you-go members may go over; the overage bills at the band rate
    if coalesce(v_member.overage_policy, 'blocked') = 'payg' then
      return;
    end if;
    -- the client pins the substring 'half-day quota' of this message
    raise exception 'half-day quota exceeded — request additional half-days';
  end if;
end;
$$;
revoke execute on function public.assert_member_quota(uuid, timestamptz) from public, anon, authenticated;

-- SPDX-License-Identifier: 0BSD
-- Member-to-member notifications (#456): any active member can send a
-- short note to another member; admins (and the owner) can broadcast to
-- ALL admins including the owner. Delivery: the trigger pings the
-- send-push edge function (v2 understands {note_id}) — the push itself
-- stays content-free (0012 privacy doctrine, 'You have a new message');
-- the app reads the note over RLS and renders the localized
-- notification with sender and text on-device. Realtime (0080 pattern)
-- pushes the row to foregrounded apps.

create table public.member_notes (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id)
    on delete cascade,
  from_member_id uuid not null references public.members(id)
    on delete cascade,
  -- null = broadcast to all admins incl. the owner (sender must be an
  -- admin/owner — send_member_note enforces it).
  to_member_id uuid references public.members(id) on delete cascade,
  body text not null check (length(btrim(body)) between 1 and 500),
  created_at timestamptz not null default now()
);

create index member_notes_recipient
  on public.member_notes (to_member_id, created_at desc);
create index member_notes_workspace
  on public.member_notes (workspace_id, created_at desc);

alter table public.member_notes enable row level security;

-- Read: the recipient, the sender, and — for broadcasts — every
-- admin/owner of the workspace.
create policy member_notes_select on public.member_notes
  for select using (
    exists (
      select 1 from public.members m
      where m.user_id = auth.uid()
        and m.workspace_id = member_notes.workspace_id
        and m.status = 'active'
        and (
          m.id = member_notes.to_member_id
          or m.id = member_notes.from_member_id
          or (member_notes.to_member_id is null
              and (m.is_admin or m.is_owner))
        )
    )
  );
-- Writes go through send_member_note only (no insert/update/delete
-- policies): the RPC validates sender, target and broadcast rights.

create or replace function public.send_member_note(
  p_workspace_id uuid,
  p_to_member_id uuid,
  p_body text
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_sender public.members;
  v_target public.members;
  v_note_id uuid;
begin
  select * into v_sender from public.members
    where workspace_id = p_workspace_id
      and user_id = auth.uid() and status = 'active';
  if v_sender.id is null then
    raise exception 'not an active member of this workspace';
  end if;
  if length(btrim(coalesce(p_body, ''))) not between 1 and 500 then
    raise exception 'the message must be 1-500 characters';
  end if;

  if p_to_member_id is null then
    -- Broadcast to all admins incl. the owner: an admin surface.
    if not (v_sender.is_admin or v_sender.is_owner) then
      raise exception 'only admins may notify all admins';
    end if;
  else
    select * into v_target from public.members
      where id = p_to_member_id and workspace_id = p_workspace_id
        and status = 'active';
    if v_target.id is null then
      raise exception 'unknown recipient';
    end if;
    if v_target.id = v_sender.id then
      raise exception 'you cannot notify yourself';
    end if;
  end if;

  insert into public.member_notes
      (workspace_id, from_member_id, to_member_id, body)
    values (p_workspace_id, v_sender.id, p_to_member_id, btrim(p_body))
    returning id into v_note_id;
  return v_note_id;
end;
$$;
revoke execute on function public.send_member_note(uuid, uuid, text)
  from public, anon;

-- Push fanout: same best-effort ping as notify_pending_event (0084),
-- with {note_id} — send-push v2 loads the note itself and never trusts
-- the caller.
create or replace function public.notify_member_note()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_cfg public.push_config;
begin
  select * into v_cfg from public.push_config where id;
  if v_cfg.functions_url is not null then
    begin
      perform net.http_post(
        url := v_cfg.functions_url || '/send-push',
        headers := jsonb_build_object(
          'Authorization', 'Bearer ' || v_cfg.anon_key,
          'Content-Type', 'application/json'
        ),
        body := jsonb_build_object('note_id', new.id),
        timeout_milliseconds := 5000
      );
    exception when others then
      null;  -- best-effort: push must never fail the note
    end;
  end if;
  return new;
end;
$$;

create trigger member_notes_push
  after insert on public.member_notes
  for each row execute function public.notify_member_note();

-- Foregrounded apps learn about new notes live (0080 pattern; RLS
-- scopes what each client actually receives).
alter publication supabase_realtime add table public.member_notes;

-- SPDX-License-Identifier: 0BSD
-- VAT follows the DECLARED REGIME (#484): only a workspace declared
-- vat_registered ever stamps a rate onto a charge. Before this, VAT was
-- driven purely by whether rates existed — an exempt workspace (a
-- French association under art. 261-7-1° / 293 B CGI, a franchise en
-- base business…) with leftover rates would still tax its members. Now
-- the regime gates every chokepoint: statement-derived invoice lines
-- (via workspace_default_vat_percent), service charges and package
-- purchases (their per-item rate lookup). Already-issued invoices keep
-- their signed snapshots untouched.

-- 1. True only for a workspace that declared it charges VAT.
create or replace function public.workspace_charges_vat(
  p_workspace_id uuid
) returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.workspaces
    where id = p_workspace_id and vat_regime = 'vat_registered');
$$;
revoke execute on function public.workspace_charges_vat(uuid)
  from public, anon;

-- 2. workspace_default_vat_percent v2: 0 unless the regime charges VAT.
create or replace function public.workspace_default_vat_percent(
  p_workspace_id uuid
) returns numeric language sql stable security definer set search_path = public as $$
  select case when public.workspace_charges_vat(p_workspace_id) then
    coalesce(
      (select percent from public.vat_rates
        where workspace_id = p_workspace_id and is_default and active
        limit 1), 0)
  else 0 end;
$$;

-- 3. record_service_charge v4: the 0072 body, the service's own rate
-- honored only under a VAT-charging regime.
create or replace function public.record_service_charge(
  p_workspace_id uuid,
  p_subject_member_id uuid,
  p_service_id uuid,
  p_quantity int,
  p_period text default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_service public.services;
  v_period text;
  v_event_id uuid;
  v_vat numeric;
begin
  select * into v_actor from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_actor.id is null then raise exception 'not an active member'; end if;
  if v_actor.id <> p_subject_member_id and not (v_actor.is_admin or v_actor.is_owner) then
    raise exception 'only admins may add services for other members';
  end if;
  if not exists (
    select 1 from public.members
    where id = p_subject_member_id and workspace_id = p_workspace_id and status = 'active'
  ) then raise exception 'unknown subject member'; end if;

  select * into v_service from public.services
    where id = p_service_id and workspace_id = p_workspace_id;
  if v_service.id is null then raise exception 'unknown service'; end if;
  if not v_service.active then raise exception 'service is inactive'; end if;
  if p_quantity is null or p_quantity < 1 or p_quantity > 999 then
    raise exception 'quantity must be between 1 and 999';
  end if;
  v_period := coalesce(p_period, to_char(now(), 'YYYY-MM'));
  if v_period !~ '^\d{4}-\d{2}$' then raise exception 'period must be YYYY-MM'; end if;

  -- The service's own rate, else the workspace default — and 0 whenever
  -- the declared regime charges no VAT (0095).
  if public.workspace_charges_vat(p_workspace_id) then
    select coalesce(
        (select percent from public.vat_rates
          where id = v_service.vat_rate_id and active),
        public.workspace_default_vat_percent(p_workspace_id))
      into v_vat;
  else
    v_vat := 0;
  end if;

  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id, payload, status)
  values (
    p_workspace_id, 'service_charge', 'submitted', v_actor.id, p_subject_member_id,
    jsonb_build_object(
      'service_id', v_service.id,
      'name', v_service.name,
      'price_cents', v_service.price_cents,
      'quantity', p_quantity,
      'amount_cents', v_service.price_cents * p_quantity,
      'vat_percent', v_vat,
      'period', v_period
    ),
    'pending'
  ) returning id into v_event_id;
  return v_event_id;
end;
$$;
revoke execute on function
  public.record_service_charge(uuid, uuid, uuid, int, text) from public, anon;

-- 4. buy_package v3: same gate on the package's rate.
create or replace function public.buy_package(
  p_workspace_id uuid, p_package_id uuid
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_pkg public.packages;
  v_tz text;
  v_period text;
  v_ext_id uuid;
  v_vat numeric;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if coalesce(v_member.overage_policy, 'blocked') <> 'package' then
    raise exception 'member is not on the package plan';
  end if;

  select * into v_pkg from public.packages
    where id = p_package_id and workspace_id = p_workspace_id and active;
  if v_pkg.id is null then raise exception 'unknown or inactive package'; end if;

  select timezone into v_tz from public.workspaces where id = p_workspace_id;
  v_period := to_char(now() at time zone v_tz, 'YYYY-MM');

  insert into public.quota_extensions
    (workspace_id, member_id, period, half_days)
  values (p_workspace_id, v_member.id, v_period, v_pkg.days * 2)
  returning id into v_ext_id;

  if public.workspace_charges_vat(p_workspace_id) then
    select coalesce(
        (select percent from public.vat_rates
          where id = v_pkg.vat_rate_id and active),
        public.workspace_default_vat_percent(p_workspace_id))
      into v_vat;
  else
    v_vat := 0;
  end if;

  insert into public.ledger_entries
    (workspace_id, member_id, kind, category, amount_cents, description,
     period, vat_percent)
  values (
    p_workspace_id, v_member.id, 'charge', 'package', v_pkg.price_cents,
    v_pkg.name || ' (' || v_pkg.days || 'd)', v_period, v_vat
  );

  return v_ext_id;
end;
$$;
revoke execute on function public.buy_package(uuid, uuid) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- Deleting a PAST or CHECKED-IN reservation is a REQUEST, not an action
-- (#492): the member asks, an owner/admin decides — was the check-in
-- forgotten (keep it, it was attended) or was the booking simply unused
-- (confirm, it disappears)? Future untouched bookings keep the direct
-- cancel. Routed through the events spine as a new 'reservation_delete'
-- type under the standard validation policy.
--
-- The event deliberately does NOT set events.reservation_id: on that
-- column a REJECT cancels the reservation (the 0007 tentative-booking
-- contract) — here reject must KEEP it. The id travels in the payload.

alter table public.events drop constraint events_type_check;
alter table public.events add constraint events_type_check check (type in
  ('reservation','payment','expense','adjustment','service_charge',
   'quota','role_change','member_join','space_reservation',
   'invoice_payment','reservation_delete'));

create or replace function public.request_reservation_deletion(
  p_reservation_id uuid, p_reason text default ''
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_res public.reservations;
  v_member public.members;
  v_id uuid;
begin
  select * into v_res from public.reservations where id = p_reservation_id;
  if v_res.id is null then raise exception 'unknown reservation'; end if;
  select * into v_member from public.members
    where workspace_id = v_res.workspace_id and user_id = auth.uid()
      and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if v_res.member_id <> v_member.id then
    raise exception 'only your own reservation';
  end if;
  if v_res.status not in ('reserved','checked_in','completed') then
    raise exception 'nothing to delete';
  end if;
  if v_res.status = 'reserved' and v_res.starts_at > now() then
    raise exception 'cancel directly — this booking has not started';
  end if;
  if exists (select 1 from public.events
              where type = 'reservation_delete' and status = 'pending'
                and (payload->>'reservation_id')::uuid = p_reservation_id) then
    raise exception 'deletion already requested';
  end if;
  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id,
     payload, status)
  values (
    v_res.workspace_id, 'reservation_delete', 'submitted',
    v_member.id, v_member.id,
    jsonb_build_object(
      'reservation_id', v_res.id,
      'starts_at', v_res.starts_at,
      'ends_at', v_res.ends_at,
      'was_checked_in', v_res.status <> 'reserved',
      'reason', left(coalesce(p_reason, ''), 300)
    ),
    'pending'
  )
  returning id into v_id;
  return v_id;
end;
$$;
revoke execute on function
  public.request_reservation_deletion(uuid, text) from public, anon;

-- respond_to_event v-next: the 0086 body verbatim + the
-- reservation_delete apply branch (confirm → the booking is cancelled;
-- reject → nothing happens, the booking stays and bills).
create or replace function public.respond_to_event(
  p_event_id uuid,
  p_accept boolean
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_event public.events;
  v_caller public.members;
  v_policy record;
  v_subject_decides boolean;
  v_in_pool boolean;
  v_pool_size int;
  v_required int;
  v_accepts int;
  v_subject_ok boolean;
  v_owner_ok boolean;
begin
  select e.* into v_event from public.events e where e.id = p_event_id;
  if v_event.id is null then raise exception 'unknown event'; end if;
  if v_event.status <> 'pending' then raise exception 'already decided'; end if;

  select m.* into v_caller from public.members m
    where m.workspace_id = v_event.workspace_id and m.user_id = auth.uid()
      and m.status = 'active';
  if v_caller.id is null then raise exception 'not a member'; end if;
  if exists (select 1 from public.event_decisions d
              where d.event_id = p_event_id and d.member_id = v_caller.id) then
    raise exception 'you already decided this event';
  end if;

  select * into v_policy from public.validation_policies
    where workspace_id = v_event.workspace_id and event_type = v_event.type;
  if v_policy is null then
    select * into v_policy from public.validation_policies
      where workspace_id = v_event.workspace_id and event_type is null;
  end if;
  if v_policy is null then
    select null::uuid as id, v_event.workspace_id as workspace_id,
           null::text as event_type, 1 as required_count,
           true as admins_may_validate, '{}'::uuid[] as eligible_admin_ids,
           false as owner_required
      into v_policy;
  end if;

  v_subject_decides := v_event.type = 'reservation'
    or (v_event.type in ('payment','service_charge')
        and v_event.actor_member_id <> v_event.subject_member_id);

  select count(*) into v_pool_size from public.members m
    where m.workspace_id = v_event.workspace_id and m.status = 'active'
      and m.id not in (v_event.actor_member_id, v_event.subject_member_id)
      and (m.is_owner or (m.is_admin and v_policy.admins_may_validate
           and (cardinality(v_policy.eligible_admin_ids) = 0
                or m.id = any(v_policy.eligible_admin_ids))));

  v_in_pool := (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate
                and (cardinality(v_policy.eligible_admin_ids) = 0
                     or v_caller.id = any(v_policy.eligible_admin_ids))))
    and (v_caller.id <> v_event.subject_member_id
         or (not v_subject_decides and v_pool_size = 0))
    -- #434 (owner rule): NOBODY validates their own event — the #107
    -- solo escape hatch (actor admitted when the pool was empty) is
    -- gone. A pool that collapses to the actor leaves the event pending
    -- until it expires: never granted silently, never self-granted.
    and v_caller.id <> v_event.actor_member_id;
  if v_pool_size = 0
     and v_caller.id <> v_event.actor_member_id
     and (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate)) then
    v_pool_size := 1;
  end if;

  if v_subject_decides and v_caller.id = v_event.subject_member_id then
    null;
  elsif v_in_pool then
    null;
  else
    raise exception 'you are not an eligible validator for this event';
  end if;

  insert into public.event_decisions (event_id, member_id, decision)
  values (p_event_id, v_caller.id, case when p_accept then 'accept' else 'reject' end);

  if not p_accept then
    update public.events set status = 'rejected', decided_at = now()
      where id = p_event_id;
    if v_event.reservation_id is not null then
      update public.reservations set status = 'cancelled'
        where id = v_event.reservation_id and status in ('reserved','checked_in');
    end if;
    if v_event.type = 'member_join' then
      update public.members set status = 'exited'
        where id = v_event.subject_member_id and status = 'pending';
    end if;
    if v_event.type = 'invoice_payment' then
      delete from public.ledger_entries
        where id = (select credit_ledger_id from public.invoice_matches
                     where event_id = v_event.id);
      delete from public.invoice_matches where event_id = v_event.id;
    end if;
    return;
  end if;

  select count(*) into v_accepts from public.event_decisions
    where event_id = p_event_id and decision = 'accept';
  v_required := greatest(1, least(v_policy.required_count,
    v_pool_size + case when v_subject_decides then 1 else 0 end));
  v_subject_ok := not v_subject_decides or exists (
    select 1 from public.event_decisions d
    where d.event_id = p_event_id and d.decision = 'accept'
      and d.member_id = v_event.subject_member_id);
  v_owner_ok := not v_policy.owner_required or exists (
    select 1 from public.event_decisions d
    join public.members m on m.id = d.member_id
    where d.event_id = p_event_id and d.decision = 'accept' and m.is_owner);

  if v_accepts >= v_required and v_subject_ok and v_owner_ok then
    update public.events set status = 'confirmed', decided_at = now()
      where id = p_event_id;

    if v_event.type in ('payment','expense') then
      -- 0070: the payer's own date and target month when the payload
      -- carries them; the old behaviour (today, current month) when not.
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description,
         period, event_id, occurred_on)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'credit',
        case when v_event.type = 'payment' then 'payment' else 'expense' end,
        (v_event.payload->>'amount_cents')::int,
        coalesce(v_event.payload->>'note', ''),
        coalesce(v_event.payload->>'period', to_char(now(), 'YYYY-MM')),
        v_event.id,
        (v_event.payload->>'paid_on')::date
      );
    elsif v_event.type = 'service_charge' then
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description,
         period, event_id, vat_percent)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'charge', 'service',
        (v_event.payload->>'amount_cents')::int,
        (v_event.payload->>'name') || ' x' || (v_event.payload->>'quantity'),
        coalesce(v_event.payload->>'period', to_char(now(), 'YYYY-MM')),
        v_event.id,
        (v_event.payload->>'vat_percent')::numeric
      );
    elsif v_event.type = 'quota' then
      insert into public.quota_extensions
        (workspace_id, member_id, period, half_days, event_id)
      values (
        v_event.workspace_id, v_event.subject_member_id,
        v_event.payload->>'period',
        (v_event.payload->>'half_days')::int,
        v_event.id
      );
    elsif v_event.type = 'role_change' then
      update public.members
        set is_admin = (v_event.payload->>'make_admin')::boolean
        where id = v_event.subject_member_id;
    elsif v_event.type = 'member_join' then
      -- the validated welcome: the pending membership becomes active
      update public.members set status = 'active'
        where id = v_event.subject_member_id and status = 'pending';
    elsif v_event.type = 'invoice_payment' then
      update public.invoice_matches set status = 'confirmed'
        where event_id = v_event.id;
    elsif v_event.type = 'reservation_delete' then
      -- #492 — the validated deletion: the booking is cancelled and no
      -- longer bills; a forgotten check-in that was ATTENDED should be
      -- rejected instead, keeping the booking on the record.
      update public.reservations set status = 'cancelled'
        where id = (v_event.payload->>'reservation_id')::uuid
          and status in ('reserved','checked_in','completed');
    end if;
  end if;
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- Partially paid is NOT closed (#504). A partial payment used to
-- archive the invoice; the field rule is the opposite: the invoice
-- STAYS OPEN — the remainder is still owed — until the outstanding
-- amount is EXPLICITLY cancelled, and that write-off runs through the
-- validation framework like every money decision. Only the validated
-- write-off moves the invoice to the archive.

alter table public.invoice_matches
  add column if not exists writeoff_at timestamptz,
  add column if not exists writeoff_event_id uuid references public.events(id);

alter table public.events drop constraint events_type_check;
alter table public.events add constraint events_type_check check (type in
  ('reservation','payment','expense','adjustment','service_charge',
   'quota','role_change','member_join','space_reservation',
   'invoice_payment','reservation_delete','invoice_writeoff'));

-- Owner/admin asks to cancel the outstanding remainder of a PARTIALLY
-- PAID invoice. Lands as a pending 'invoice_writeoff' event; the
-- validators decide (never the actor, #434).
create or replace function public.request_invoice_writeoff(
  p_invoice_id uuid, p_reason text default ''
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_invoice public.invoices;
  v_match public.invoice_matches;
  v_actor public.members;
  v_id uuid;
begin
  select * into v_invoice from public.invoices where id = p_invoice_id;
  if v_invoice.id is null then raise exception 'unknown invoice'; end if;
  select * into v_actor from public.members
    where workspace_id = v_invoice.workspace_id and user_id = auth.uid()
      and status = 'active';
  if v_actor.id is null or not (v_actor.is_admin or v_actor.is_owner) then
    raise exception 'only admins may cancel outstanding amounts';
  end if;
  select * into v_match from public.invoice_matches
    where invoice_id = p_invoice_id;
  if v_match.invoice_id is null or v_match.status <> 'confirmed'
     or v_match.resolution <> 'under_accepted' then
    raise exception 'no partially paid match to write off';
  end if;
  if v_match.writeoff_at is not null then
    raise exception 'remainder already cancelled';
  end if;
  if exists (select 1 from public.events
              where type = 'invoice_writeoff' and status = 'pending'
                and (payload->>'invoice_id')::uuid = p_invoice_id) then
    raise exception 'write-off already requested';
  end if;
  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id,
     payload, status)
  values (
    v_invoice.workspace_id, 'invoice_writeoff', 'submitted',
    v_actor.id, v_invoice.member_id,
    jsonb_build_object(
      'invoice_id', v_invoice.id,
      'number', v_invoice.number,
      'amount_cents', v_invoice.total_cents - v_match.paid_cents,
      'reason', left(coalesce(p_reason, ''), 300)
    ),
    'pending'
  )
  returning id into v_id;
  return v_id;
end;
$$;
revoke execute on function
  public.request_invoice_writeoff(uuid, text) from public, anon;

-- respond_to_event v-next: the 0097 body verbatim + the
-- invoice_writeoff apply branch (confirm stamps the write-off — the
-- invoice then reads closed; reject leaves it open and owed).
create or replace function public.respond_to_event(
  p_event_id uuid,
  p_accept boolean
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_event public.events;
  v_caller public.members;
  v_policy record;
  v_subject_decides boolean;
  v_in_pool boolean;
  v_pool_size int;
  v_required int;
  v_accepts int;
  v_subject_ok boolean;
  v_owner_ok boolean;
begin
  select e.* into v_event from public.events e where e.id = p_event_id;
  if v_event.id is null then raise exception 'unknown event'; end if;
  if v_event.status <> 'pending' then raise exception 'already decided'; end if;

  select m.* into v_caller from public.members m
    where m.workspace_id = v_event.workspace_id and m.user_id = auth.uid()
      and m.status = 'active';
  if v_caller.id is null then raise exception 'not a member'; end if;
  if exists (select 1 from public.event_decisions d
              where d.event_id = p_event_id and d.member_id = v_caller.id) then
    raise exception 'you already decided this event';
  end if;

  select * into v_policy from public.validation_policies
    where workspace_id = v_event.workspace_id and event_type = v_event.type;
  if v_policy is null then
    select * into v_policy from public.validation_policies
      where workspace_id = v_event.workspace_id and event_type is null;
  end if;
  if v_policy is null then
    select null::uuid as id, v_event.workspace_id as workspace_id,
           null::text as event_type, 1 as required_count,
           true as admins_may_validate, '{}'::uuid[] as eligible_admin_ids,
           false as owner_required
      into v_policy;
  end if;

  v_subject_decides := v_event.type = 'reservation'
    or (v_event.type in ('payment','service_charge')
        and v_event.actor_member_id <> v_event.subject_member_id);

  select count(*) into v_pool_size from public.members m
    where m.workspace_id = v_event.workspace_id and m.status = 'active'
      and m.id not in (v_event.actor_member_id, v_event.subject_member_id)
      and (m.is_owner or (m.is_admin and v_policy.admins_may_validate
           and (cardinality(v_policy.eligible_admin_ids) = 0
                or m.id = any(v_policy.eligible_admin_ids))));

  v_in_pool := (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate
                and (cardinality(v_policy.eligible_admin_ids) = 0
                     or v_caller.id = any(v_policy.eligible_admin_ids))))
    and (v_caller.id <> v_event.subject_member_id
         or (not v_subject_decides and v_pool_size = 0))
    and v_caller.id <> v_event.actor_member_id;
  if v_pool_size = 0
     and v_caller.id <> v_event.actor_member_id
     and (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate)) then
    v_pool_size := 1;
  end if;

  if v_subject_decides and v_caller.id = v_event.subject_member_id then
    null;
  elsif v_in_pool then
    null;
  else
    raise exception 'you are not an eligible validator for this event';
  end if;

  insert into public.event_decisions (event_id, member_id, decision)
  values (p_event_id, v_caller.id, case when p_accept then 'accept' else 'reject' end);

  if not p_accept then
    update public.events set status = 'rejected', decided_at = now()
      where id = p_event_id;
    if v_event.reservation_id is not null then
      update public.reservations set status = 'cancelled'
        where id = v_event.reservation_id and status in ('reserved','checked_in');
    end if;
    if v_event.type = 'member_join' then
      update public.members set status = 'exited'
        where id = v_event.subject_member_id and status = 'pending';
    end if;
    if v_event.type = 'invoice_payment' then
      delete from public.ledger_entries
        where id = (select credit_ledger_id from public.invoice_matches
                     where event_id = v_event.id);
      delete from public.invoice_matches where event_id = v_event.id;
    end if;
    return;
  end if;

  select count(*) into v_accepts from public.event_decisions
    where event_id = p_event_id and decision = 'accept';
  v_required := greatest(1, least(v_policy.required_count,
    v_pool_size + case when v_subject_decides then 1 else 0 end));
  v_subject_ok := not v_subject_decides or exists (
    select 1 from public.event_decisions d
    where d.event_id = p_event_id and d.decision = 'accept'
      and d.member_id = v_event.subject_member_id);
  v_owner_ok := not v_policy.owner_required or exists (
    select 1 from public.event_decisions d
    join public.members m on m.id = d.member_id
    where d.event_id = p_event_id and d.decision = 'accept' and m.is_owner);

  if v_accepts >= v_required and v_subject_ok and v_owner_ok then
    update public.events set status = 'confirmed', decided_at = now()
      where id = p_event_id;

    if v_event.type in ('payment','expense') then
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description,
         period, event_id, occurred_on)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'credit',
        case when v_event.type = 'payment' then 'payment' else 'expense' end,
        (v_event.payload->>'amount_cents')::int,
        coalesce(v_event.payload->>'note', ''),
        coalesce(v_event.payload->>'period', to_char(now(), 'YYYY-MM')),
        v_event.id,
        (v_event.payload->>'paid_on')::date
      );
    elsif v_event.type = 'service_charge' then
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description,
         period, event_id, vat_percent)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'charge', 'service',
        (v_event.payload->>'amount_cents')::int,
        (v_event.payload->>'name') || ' x' || (v_event.payload->>'quantity'),
        coalesce(v_event.payload->>'period', to_char(now(), 'YYYY-MM')),
        v_event.id,
        (v_event.payload->>'vat_percent')::numeric
      );
    elsif v_event.type = 'quota' then
      insert into public.quota_extensions
        (workspace_id, member_id, period, half_days, event_id)
      values (
        v_event.workspace_id, v_event.subject_member_id,
        v_event.payload->>'period',
        (v_event.payload->>'half_days')::int,
        v_event.id
      );
    elsif v_event.type = 'role_change' then
      update public.members
        set is_admin = (v_event.payload->>'make_admin')::boolean
        where id = v_event.subject_member_id;
    elsif v_event.type = 'member_join' then
      update public.members set status = 'active'
        where id = v_event.subject_member_id and status = 'pending';
    elsif v_event.type = 'invoice_payment' then
      update public.invoice_matches set status = 'confirmed'
        where event_id = v_event.id;
    elsif v_event.type = 'reservation_delete' then
      update public.reservations set status = 'cancelled'
        where id = (v_event.payload->>'reservation_id')::uuid
          and status in ('reserved','checked_in','completed');
    elsif v_event.type = 'invoice_writeoff' then
      -- #504 — the validated write-off: the remainder is forgiven and
      -- the invoice finally reads CLOSED (partially paid, remainder
      -- cancelled).
      update public.invoice_matches
        set writeoff_at = now(), writeoff_event_id = v_event.id
        where invoice_id = (v_event.payload->>'invoice_id')::uuid
          and resolution = 'under_accepted' and writeoff_at is null;
    end if;
  end if;
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- Additional payments onto a PARTIALLY PAID invoice (#506). A partial
-- invoice stays open (#504); new payments keep coming in and must be
-- matchable against the REMAINING amount — maybe until fully paid,
-- maybe the rest is written off (#504). The invoice_matches row becomes
-- the AGGREGATE (paid_cents = everything applied so far); the new
-- invoice_match_payments table records every consumed payment for the
-- audit trail and the never-consume-twice guard.

create table public.invoice_match_payments (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id)
    on delete cascade,
  invoice_id uuid not null references public.invoices(id)
    on delete cascade,
  payment_ledger_id uuid not null unique
    references public.ledger_entries(id) on delete cascade,
  amount_cents int not null check (amount_cents >= 0),
  resolution text not null check (resolution in
    ('exact','over_forced','over_credit_note','under_accepted')),
  note text not null default '',
  event_id uuid references public.events(id) on delete set null,
  credit_ledger_id uuid references public.ledger_entries(id)
    on delete set null,
  matched_at timestamptz not null default now(),
  by_name text not null default ''
);
create index invoice_match_payments_invoice_idx
  on public.invoice_match_payments (invoice_id);
create index invoice_match_payments_workspace_idx
  on public.invoice_match_payments (workspace_id);

alter table public.invoice_match_payments enable row level security;
create policy invoice_match_payments_select
  on public.invoice_match_payments
  for select using (
    public.is_admin_of(workspace_id)
    or exists (select 1
                 from public.invoices i
                 join public.members m on m.id = i.member_id
                where i.id = invoice_match_payments.invoice_id
                  and m.user_id = auth.uid())
  );
-- No write policies: writes only through match_invoice /
-- respond_to_event.

-- Backfill: every existing match consumed exactly one payment.
insert into public.invoice_match_payments
  (workspace_id, invoice_id, payment_ledger_id, amount_cents,
   resolution, note, event_id, credit_ledger_id, matched_at, by_name)
select workspace_id, invoice_id, payment_ledger_id, paid_cents,
       resolution, note, event_id, credit_ledger_id, matched_at, by_name
  from public.invoice_matches
 where payment_ledger_id is not null
on conflict (payment_ledger_id) do nothing;

-- match_invoice v3: the 0068 body, generalized — an invoice with a
-- STANDING partial match accepts further payments against the
-- REMAINING amount. The junction row is written immediately (it
-- reserves the payment even while a quorum decides); the aggregate is
-- updated on confirmation (immediately when no policy applies).
create or replace function public.match_invoice(
  p_invoice_id uuid,
  p_payment_ledger_id uuid,
  p_resolution text,
  p_note text default ''
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_invoice public.invoices;
  v_existing public.invoice_matches;
  v_payment public.ledger_entries;
  v_paid int;
  v_due int;
  v_actor public.members;
  v_actor_name text;
  v_note text := btrim(coalesce(p_note, ''));
  v_has_policy boolean;
  v_event_id uuid;
  v_credit_id uuid := null;
  v_additional boolean := false;
begin
  select * into v_invoice from public.invoices where id = p_invoice_id;
  if v_invoice.id is null then raise exception 'unknown invoice'; end if;
  if v_invoice.voided_at is not null then
    raise exception 'invoice is voided';
  end if;
  select * into v_existing from public.invoice_matches
    where invoice_id = p_invoice_id;
  if v_existing.invoice_id is not null then
    -- #506 — only a STANDING partial (not written off) accepts more.
    if v_existing.status <> 'confirmed'
       or v_existing.resolution <> 'under_accepted'
       or v_existing.writeoff_at is not null then
      raise exception 'invoice already matched';
    end if;
    v_additional := true;
    v_due := v_invoice.total_cents - v_existing.paid_cents;
  else
    v_due := v_invoice.total_cents;
  end if;
  select * into v_actor from public.members
    where workspace_id = v_invoice.workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if not public.is_owner_of(v_invoice.workspace_id) and not coalesce(
    (select w.feature_flags -> 'adminInvoicing' = to_jsonb(true)
       from public.workspaces w where w.id = v_invoice.workspace_id), false) then
    raise exception 'admins may not issue invoices here';
  end if;

  select * into v_payment from public.ledger_entries
    where id = p_payment_ledger_id
      and workspace_id = v_invoice.workspace_id
      and member_id = v_invoice.member_id
      and kind = 'credit' and category = 'payment';
  if v_payment.id is null then raise exception 'unknown payment'; end if;
  if exists (select 1 from public.invoice_match_payments
              where payment_ledger_id = p_payment_ledger_id) then
    raise exception 'payment already matched';
  end if;
  v_paid := v_payment.amount_cents;

  if p_resolution not in
      ('exact','over_forced','over_credit_note','under_accepted') then
    raise exception 'unknown resolution';
  end if;
  -- All amount rules compare against what is STILL DUE (#506).
  if p_resolution = 'exact' and v_paid <> v_due then
    raise exception 'amount does not match the invoice';
  end if;
  if p_resolution in ('over_forced','over_credit_note')
     and v_paid <= v_due then
    raise exception 'amount does not exceed the invoice';
  end if;
  if p_resolution = 'under_accepted' and v_paid >= v_due then
    raise exception 'amount is not below the invoice';
  end if;
  if p_resolution in ('over_forced','under_accepted') and v_note = '' then
    raise exception 'a note is required';
  end if;

  select coalesce(display_name, '') into v_actor_name
    from public.profiles where id = v_actor.user_id;

  if p_resolution = 'over_credit_note' then
    insert into public.ledger_entries
      (workspace_id, member_id, kind, category, amount_cents,
       description, period)
    values
      (v_invoice.workspace_id, v_invoice.member_id, 'credit',
       'adjustment', v_paid - v_due,
       'Credit note ' || v_invoice.number
         || case when v_note = '' then '' else ' — ' || v_note end,
       to_char(now(), 'YYYY-MM'))
    returning id into v_credit_id;
  end if;

  v_has_policy := exists (
    select 1 from public.validation_policies vp
    where vp.workspace_id = v_invoice.workspace_id
      and vp.event_type = 'invoice_payment');

  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id,
     payload, status, decided_at)
  values
    (v_invoice.workspace_id, 'invoice_payment', 'submitted',
     v_actor.id, v_invoice.member_id,
     jsonb_build_object(
       'invoice_id', v_invoice.id,
       'number', v_invoice.number,
       'due_cents', v_due,
       'paid_cents', v_paid,
       'amount_cents', v_paid,
       'payment_ledger_id', p_payment_ledger_id,
       'resolution', p_resolution,
       'note', v_note,
       'additional', v_additional),
     case when v_has_policy then 'pending' else 'confirmed' end,
     case when v_has_policy then null else now() end)
  returning id into v_event_id;

  -- The junction row reserves the payment even while pending.
  insert into public.invoice_match_payments
    (workspace_id, invoice_id, payment_ledger_id, amount_cents,
     resolution, note, event_id, credit_ledger_id, by_name)
  values
    (v_invoice.workspace_id, p_invoice_id, p_payment_ledger_id, v_paid,
     p_resolution, v_note, v_event_id, v_credit_id, v_actor_name);

  if v_additional then
    -- The aggregate moves only when the payment stands.
    if not v_has_policy then
      update public.invoice_matches
        set paid_cents = paid_cents + v_paid,
            resolution = p_resolution,
            note = case when v_note = '' then note else v_note end,
            payment_ledger_id = p_payment_ledger_id,
            credit_ledger_id = coalesce(v_credit_id, credit_ledger_id),
            matched_at = now(),
            by_name = v_actor_name
        where invoice_id = p_invoice_id;
    end if;
  else
    insert into public.invoice_matches
      (workspace_id, invoice_id, paid_cents, resolution, note, status,
       event_id, credit_ledger_id, payment_ledger_id, by_name)
    values
      (v_invoice.workspace_id, p_invoice_id, v_paid, p_resolution,
       v_note, case when v_has_policy then 'pending' else 'confirmed' end,
       v_event_id, v_credit_id, p_payment_ledger_id, v_actor_name);
  end if;
end;
$$;
revoke execute on function
  public.match_invoice(uuid, uuid, text, text) from public, anon;

-- respond_to_event v-next: the 0100 body (generated from it verbatim)
-- + the #506 additional-payment branches: reject releases the reserved
-- payment (junction row + its credit note); confirm applies the
-- addition to the aggregate match.
create or replace function public.respond_to_event(
  p_event_id uuid,
  p_accept boolean
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_event public.events;
  v_caller public.members;
  v_policy record;
  v_subject_decides boolean;
  v_in_pool boolean;
  v_pool_size int;
  v_required int;
  v_accepts int;
  v_subject_ok boolean;
  v_owner_ok boolean;
begin
  select e.* into v_event from public.events e where e.id = p_event_id;
  if v_event.id is null then raise exception 'unknown event'; end if;
  if v_event.status <> 'pending' then raise exception 'already decided'; end if;

  select m.* into v_caller from public.members m
    where m.workspace_id = v_event.workspace_id and m.user_id = auth.uid()
      and m.status = 'active';
  if v_caller.id is null then raise exception 'not a member'; end if;
  if exists (select 1 from public.event_decisions d
              where d.event_id = p_event_id and d.member_id = v_caller.id) then
    raise exception 'you already decided this event';
  end if;

  select * into v_policy from public.validation_policies
    where workspace_id = v_event.workspace_id and event_type = v_event.type;
  if v_policy is null then
    select * into v_policy from public.validation_policies
      where workspace_id = v_event.workspace_id and event_type is null;
  end if;
  if v_policy is null then
    select null::uuid as id, v_event.workspace_id as workspace_id,
           null::text as event_type, 1 as required_count,
           true as admins_may_validate, '{}'::uuid[] as eligible_admin_ids,
           false as owner_required
      into v_policy;
  end if;

  v_subject_decides := v_event.type = 'reservation'
    or (v_event.type in ('payment','service_charge')
        and v_event.actor_member_id <> v_event.subject_member_id);

  select count(*) into v_pool_size from public.members m
    where m.workspace_id = v_event.workspace_id and m.status = 'active'
      and m.id not in (v_event.actor_member_id, v_event.subject_member_id)
      and (m.is_owner or (m.is_admin and v_policy.admins_may_validate
           and (cardinality(v_policy.eligible_admin_ids) = 0
                or m.id = any(v_policy.eligible_admin_ids))));

  v_in_pool := (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate
                and (cardinality(v_policy.eligible_admin_ids) = 0
                     or v_caller.id = any(v_policy.eligible_admin_ids))))
    and (v_caller.id <> v_event.subject_member_id
         or (not v_subject_decides and v_pool_size = 0))
    and v_caller.id <> v_event.actor_member_id;
  if v_pool_size = 0
     and v_caller.id <> v_event.actor_member_id
     and (v_caller.is_owner or (v_caller.is_admin and v_policy.admins_may_validate)) then
    v_pool_size := 1;
  end if;

  if v_subject_decides and v_caller.id = v_event.subject_member_id then
    null;
  elsif v_in_pool then
    null;
  else
    raise exception 'you are not an eligible validator for this event';
  end if;

  insert into public.event_decisions (event_id, member_id, decision)
  values (p_event_id, v_caller.id, case when p_accept then 'accept' else 'reject' end);

  if not p_accept then
    update public.events set status = 'rejected', decided_at = now()
      where id = p_event_id;
    if v_event.reservation_id is not null then
      update public.reservations set status = 'cancelled'
        where id = v_event.reservation_id and status in ('reserved','checked_in');
    end if;
    if v_event.type = 'member_join' then
      update public.members set status = 'exited'
        where id = v_event.subject_member_id and status = 'pending';
    end if;
    if v_event.type = 'invoice_payment' then
      delete from public.ledger_entries
        where id = (select credit_ledger_id from public.invoice_matches
                     where event_id = v_event.id);
      delete from public.invoice_matches where event_id = v_event.id;
      -- #506 — an ADDITIONAL payment leaves no match row; its credit
      -- note and its payment reservation are released here.
      delete from public.ledger_entries
        where id in (select credit_ledger_id
                       from public.invoice_match_payments
                      where event_id = v_event.id
                        and credit_ledger_id is not null);
      delete from public.invoice_match_payments
        where event_id = v_event.id;
    end if;
    return;
  end if;

  select count(*) into v_accepts from public.event_decisions
    where event_id = p_event_id and decision = 'accept';
  v_required := greatest(1, least(v_policy.required_count,
    v_pool_size + case when v_subject_decides then 1 else 0 end));
  v_subject_ok := not v_subject_decides or exists (
    select 1 from public.event_decisions d
    where d.event_id = p_event_id and d.decision = 'accept'
      and d.member_id = v_event.subject_member_id);
  v_owner_ok := not v_policy.owner_required or exists (
    select 1 from public.event_decisions d
    join public.members m on m.id = d.member_id
    where d.event_id = p_event_id and d.decision = 'accept' and m.is_owner);

  if v_accepts >= v_required and v_subject_ok and v_owner_ok then
    update public.events set status = 'confirmed', decided_at = now()
      where id = p_event_id;

    if v_event.type in ('payment','expense') then
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description,
         period, event_id, occurred_on)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'credit',
        case when v_event.type = 'payment' then 'payment' else 'expense' end,
        (v_event.payload->>'amount_cents')::int,
        coalesce(v_event.payload->>'note', ''),
        coalesce(v_event.payload->>'period', to_char(now(), 'YYYY-MM')),
        v_event.id,
        (v_event.payload->>'paid_on')::date
      );
    elsif v_event.type = 'service_charge' then
      insert into public.ledger_entries
        (workspace_id, member_id, kind, category, amount_cents, description,
         period, event_id, vat_percent)
      values (
        v_event.workspace_id, v_event.subject_member_id, 'charge', 'service',
        (v_event.payload->>'amount_cents')::int,
        (v_event.payload->>'name') || ' x' || (v_event.payload->>'quantity'),
        coalesce(v_event.payload->>'period', to_char(now(), 'YYYY-MM')),
        v_event.id,
        (v_event.payload->>'vat_percent')::numeric
      );
    elsif v_event.type = 'quota' then
      insert into public.quota_extensions
        (workspace_id, member_id, period, half_days, event_id)
      values (
        v_event.workspace_id, v_event.subject_member_id,
        v_event.payload->>'period',
        (v_event.payload->>'half_days')::int,
        v_event.id
      );
    elsif v_event.type = 'role_change' then
      update public.members
        set is_admin = (v_event.payload->>'make_admin')::boolean
        where id = v_event.subject_member_id;
    elsif v_event.type = 'member_join' then
      update public.members set status = 'active'
        where id = v_event.subject_member_id and status = 'pending';
    elsif v_event.type = 'invoice_payment' then
      update public.invoice_matches set status = 'confirmed'
        where event_id = v_event.id;
      -- #506 — a validated ADDITIONAL payment lands on the aggregate.
      if coalesce(v_event.payload->>'additional', 'false') = 'true' then
        update public.invoice_matches m
          set paid_cents = m.paid_cents + jr.amount_cents,
              resolution = jr.resolution,
              note = case when jr.note = '' then m.note else jr.note end,
              payment_ledger_id = jr.payment_ledger_id,
              credit_ledger_id =
                coalesce(jr.credit_ledger_id, m.credit_ledger_id),
              matched_at = now(),
              by_name = jr.by_name
          from public.invoice_match_payments jr
          where jr.event_id = v_event.id
            and m.invoice_id = jr.invoice_id;
      end if;
    elsif v_event.type = 'reservation_delete' then
      update public.reservations set status = 'cancelled'
        where id = (v_event.payload->>'reservation_id')::uuid
          and status in ('reserved','checked_in','completed');
    elsif v_event.type = 'invoice_writeoff' then
      -- #504 — the validated write-off: the remainder is forgiven and
      -- the invoice finally reads CLOSED (partially paid, remainder
      -- cancelled).
      update public.invoice_matches
        set writeoff_at = now(), writeoff_event_id = v_event.id
        where invoice_id = (v_event.payload->>'invoice_id')::uuid
          and resolution = 'under_accepted' and writeoff_at is null;
    end if;
  end if;
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- NEGATIVE invoices are CREDIT NOTES the WORKSPACE pays (#508). A month
-- where credits exceed charges derives a negative document — an avoir:
-- the workspace owes the member. Such a document cannot be settled by
-- matching a member payment; it is settled by RECORDING THE REFUND the
-- workspace paid out. The refund books a ledger CHARGE (offsetting the
-- member's credit) and closes the document with the new 'refunded'
-- resolution — through the same invoice_payment validation policy as
-- every settlement.

alter table public.invoice_matches
  drop constraint invoice_matches_resolution_check;
alter table public.invoice_matches
  add constraint invoice_matches_resolution_check check (resolution in
    ('exact','over_forced','over_credit_note','under_accepted',
     'refunded'));

create or replace function public.settle_credit_invoice(
  p_invoice_id uuid, p_note text default ''
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_invoice public.invoices;
  v_actor public.members;
  v_actor_name text;
  v_note text := btrim(coalesce(p_note, ''));
  v_has_policy boolean;
  v_event_id uuid;
  v_payout_id uuid;
  v_amount int;
begin
  select * into v_invoice from public.invoices where id = p_invoice_id;
  if v_invoice.id is null then raise exception 'unknown invoice'; end if;
  if v_invoice.voided_at is not null then
    raise exception 'invoice is voided';
  end if;
  if v_invoice.total_cents >= 0 then
    raise exception 'not a credit note';
  end if;
  if exists (select 1 from public.invoice_matches
              where invoice_id = p_invoice_id) then
    raise exception 'invoice already matched';
  end if;
  select * into v_actor from public.members
    where workspace_id = v_invoice.workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if not public.is_owner_of(v_invoice.workspace_id) and not coalesce(
    (select w.feature_flags -> 'adminInvoicing' = to_jsonb(true)
       from public.workspaces w where w.id = v_invoice.workspace_id), false) then
    raise exception 'admins may not issue invoices here';
  end if;

  v_amount := -v_invoice.total_cents;
  select coalesce(display_name, '') into v_actor_name
    from public.profiles where id = v_actor.user_id;

  -- The payout: a CHARGE that offsets the member's credit — their
  -- balance returns to zero because the money left the workspace.
  insert into public.ledger_entries
    (workspace_id, member_id, kind, category, amount_cents,
     description, period)
  values
    (v_invoice.workspace_id, v_invoice.member_id, 'charge',
     'adjustment', v_amount,
     'Refund ' || v_invoice.number
       || case when v_note = '' then '' else ' — ' || v_note end,
     to_char(now(), 'YYYY-MM'))
  returning id into v_payout_id;

  v_has_policy := exists (
    select 1 from public.validation_policies vp
    where vp.workspace_id = v_invoice.workspace_id
      and vp.event_type = 'invoice_payment');

  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id,
     payload, status, decided_at)
  values
    (v_invoice.workspace_id, 'invoice_payment', 'submitted',
     v_actor.id, v_invoice.member_id,
     jsonb_build_object(
       'invoice_id', v_invoice.id,
       'number', v_invoice.number,
       'due_cents', v_invoice.total_cents,
       'paid_cents', v_amount,
       'amount_cents', v_amount,
       'resolution', 'refunded',
       'note', v_note),
     case when v_has_policy then 'pending' else 'confirmed' end,
     case when v_has_policy then null else now() end)
  returning id into v_event_id;

  -- The payout entry rides credit_ledger_id: a REJECT deletes it
  -- through the existing invoice_payment reject branch, reopening the
  -- credit note with the member's balance restored.
  insert into public.invoice_matches
    (workspace_id, invoice_id, paid_cents, resolution, note, status,
     event_id, credit_ledger_id, by_name)
  values
    (v_invoice.workspace_id, p_invoice_id, v_amount, 'refunded',
     v_note, case when v_has_policy then 'pending' else 'confirmed' end,
     v_event_id, v_payout_id, v_actor_name);
end;
$$;
revoke execute on function
  public.settle_credit_invoice(uuid, text) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- #512 — the account becomes REAL. Three rules and one view:
--   1. A month fully before the membership begins owes nothing.
--   2. An account credit (avoir excess) settles any outstanding
--      invoice — imputation, past months included.
--   3. Every credit spends exactly once: baked into an issued invoice
--      OR consumed by a match, never both, never twice.
--   4. member_account(): the member's true position — credit on
--      account, open remainders, refunds due, net.
-- Bodies generated from 0087 (member_statement), 0072
-- (invoice_lines_for) and 0101 (match_invoice) — never hand-copied.

create or replace function public.member_statement(
  p_member_id uuid,
  p_period text
) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_member public.members;
  v_caller_is_admin boolean;
  v_band public.fee_bands;
  v_tz text;
  v_open int[];
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_month_first date;
  v_open_days int;
  v_pct int;
  v_included int;
  v_used int;
  v_base int := 0;
  v_overage int := 0;
  v_overage_rate int := 0;
  v_credits int;
  v_extra_half_days int := 0;
  v_supp_on boolean := false;
  v_supp_since timestamptz;
  v_supplement int := 0;
  v_granted int := 0;
  v_cap int := 0;
  v_remaining int := 0;
  v_level_supplement int := 0;
  v_office_supplement int := 0;
  -- #desk (0059)
  v_desk_supplement int := 0;
  -- #446 working hours
  v_rules jsonb;
  v_gran text;
  v_bound int;
  v_half_minutes numeric;
begin
  select * into v_member from public.members where id = p_member_id;
  if v_member.id is null then raise exception 'unknown member'; end if;
  v_caller_is_admin := public.is_admin_of(v_member.workspace_id);
  if not v_caller_is_admin and not exists (
    select 1 from public.members m
    where m.id = p_member_id and m.user_id = auth.uid()
  ) then
    raise exception 'not your statement';
  end if;

  select timezone,
         coalesce((select array_agg(x::int)
                     from jsonb_array_elements_text(booking_rules->'open_weekdays') x),
                  array[1,2,3,4,5]),
         coalesce(feature_flags -> 'accessorySupplements' = to_jsonb(true), false),
         accessory_supplements_since,
         booking_rules
    into v_tz, v_open, v_supp_on, v_supp_since, v_rules
    from public.workspaces where id = v_member.workspace_id;
  -- #446: the half-day boundary and the hours-mode billing equivalents
  -- come from booking_rules; inconsistent values fall back to the
  -- defaults exactly like the client (WorkHours.fromRules).
  v_gran := v_rules->>'granularity';
  v_bound := coalesce((v_rules->>'half_boundary_minutes')::int, 720);
  if v_bound <= 0 or v_bound >= 1440 then v_bound := 720; end if;
  v_half_minutes := greatest(1, coalesce((v_rules->>'half_day_hours')::int, 4)) * 60.0;
  v_period_start := to_timestamp(p_period || '-01', 'YYYY-MM-DD') at time zone v_tz;
  v_period_end := (to_timestamp(p_period || '-01', 'YYYY-MM-DD') + interval '1 month') at time zone v_tz;
  v_month_first := to_date(p_period || '-01', 'YYYY-MM-DD');

  -- #512 — a month fully before the membership begins owes NOTHING:
  -- no subscription, no entitlement. The workspace started when it
  -- started; earlier months must not read outstanding.
  if p_period < to_char(v_member.joined_at at time zone v_tz, 'YYYY-MM') then
    return jsonb_build_object(
      'period', p_period,
      'subscription_pct', coalesce(v_member.subscription_pct, 100),
      'fee_cents', 0, 'included_half_days', 0, 'open_days', 0,
      'used_half_days', 0, 'extra_half_days', 0, 'overage_cents', 0,
      'accessory_supplement_cents', 0, 'level_supplement_cents', 0,
      'office_supplement_cents', 0, 'desk_supplement_cents', 0,
      'credits_cents', 0, 'balance_cents', 0,
      'overage_policy', coalesce(v_member.overage_policy, 'blocked'),
      'overage_rate_cents', 0, 'granted_half_days', 0,
      'remaining_half_days', 0
    );
  end if;

  v_pct := coalesce(v_member.subscription_pct, 100);
  select * into v_band from public.fee_bands
    where workspace_id = v_member.workspace_id
      and from_pct < v_pct and v_pct <= to_pct;
  if v_band.id is not null then
    v_base := v_band.fee_cents;
    v_overage_rate := v_band.overage_fee_cents;
  end if;

  select count(*) into v_open_days
  from generate_series(v_month_first,
                       (v_month_first + interval '1 month' - interval '1 day')::date,
                       interval '1 day') d
  where extract(isodow from d)::int = any(v_open)
    and not exists (select 1 from public.closure_days c
                     where c.workspace_id = v_member.workspace_id and c.day = d::date);
  v_included := ceil(v_open_days * 2 * v_pct / 100.0)::int;

  select count(distinct (date_trunc('day', r.starts_at at time zone v_tz)::date, s.slot))
  into v_used
  from public.reservations r
  cross join lateral (
    select case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
           then 0 else 1 end as slot
  ) s
  where r.member_id = p_member_id
    and r.status in ('reserved','checked_in','completed')
    and r.starts_at >= v_period_start and r.starts_at < v_period_end;

  -- #446 hours granularity: booked time per day converts to half-day
  -- equivalents — one half day per STARTED half_day_hours block,
  -- capped at 2 (a full day is two halves).
  if v_gran = 'hours' then
    select coalesce(sum(least(2, greatest(1,
             ceil(d.day_minutes / v_half_minutes)::int))), 0)
    into v_used
    from (
      select date_trunc('day', r.starts_at at time zone v_tz)::date as day,
             sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
               as day_minutes
      from public.reservations r
      where r.member_id = p_member_id
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start and r.starts_at < v_period_end
      group by 1
    ) d;
  end if;

  v_extra_half_days := greatest(0, v_used - v_included);
  v_overage := v_extra_half_days * v_overage_rate;

  select coalesce(sum(half_days), 0) into v_granted from public.quota_extensions
    where member_id = p_member_id and period = p_period;
  v_cap := v_included + v_granted;
  v_remaining := greatest(0, v_cap - v_used);

  if v_supp_on and v_supp_since is not null then
    if v_gran = 'hours' then
      -- #446: half-day-equivalent units per seat and day.
      select coalesce(sum(seat_supp.total_cents * hd.units), 0)
      into v_supplement
      from (
      select r.seat_id,
             least(2, greatest(1, ceil(
               sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
                 / v_half_minutes)::int)) as units
      from public.reservations r
      where r.member_id = p_member_id
        and r.seat_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= greatest(v_period_start, v_supp_since)
        and r.starts_at < v_period_end
      group by r.seat_id,
               date_trunc('day', r.starts_at at time zone v_tz)::date
    ) hd
      join (
      select sa.seat_id, sum(a.supplement_cents)::int as total_cents
      from public.seat_accessories sa
      join public.accessories a on a.id = sa.accessory_id
      where a.active and a.supplement_cents > 0
      group by sa.seat_id
    ) seat_supp on seat_supp.seat_id = hd.seat_id;
    else
      select coalesce(sum(seat_supp.total_cents), 0) into v_supplement
      from (
        select distinct
          r.seat_id,
          date_trunc('day', r.starts_at at time zone v_tz)::date as day,
          case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                  + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
             then 0 else 1 end as slot
        from public.reservations r
        where r.member_id = p_member_id
          and r.seat_id is not null
          and r.status in ('reserved','checked_in','completed')
          and r.starts_at >= greatest(v_period_start, v_supp_since)
          and r.starts_at < v_period_end
      ) hd
      join (
        select sa.seat_id, sum(a.supplement_cents)::int as total_cents
        from public.seat_accessories sa
        join public.accessories a on a.id = sa.accessory_id
        where a.active and a.supplement_cents > 0
        group by sa.seat_id
      ) seat_supp on seat_supp.seat_id = hd.seat_id;
    end if;
  end if;

  if v_gran = 'hours' then
    select coalesce(sum(l.price_cents * hx.units), 0) into v_level_supplement
    from (
      select r.level_id,
             least(2, greatest(1, ceil(
               sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
                 / v_half_minutes)::int)) as units
      from public.reservations r
      where r.member_id = p_member_id
        and r.level_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start
        and r.starts_at < v_period_end
      group by r.level_id,
               date_trunc('day', r.starts_at at time zone v_tz)::date
    ) hx
    join public.levels l on l.id = hx.level_id;
  else
    select coalesce(sum(l.price_cents), 0) into v_level_supplement
    from (
      select distinct
        r.level_id,
        date_trunc('day', r.starts_at at time zone v_tz)::date as day,
        case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                  + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
             then 0 else 1 end as slot
      from public.reservations r
      where r.member_id = p_member_id
        and r.level_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start and r.starts_at < v_period_end
    ) lh
    join public.levels l on l.id = lh.level_id;
  end if;

  -- #office: price × distinct half-days per reserved office.
  if v_gran = 'hours' then
    select coalesce(sum(o.price_cents * hx.units), 0) into v_office_supplement
    from (
      select r.office_id,
             least(2, greatest(1, ceil(
               sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
                 / v_half_minutes)::int)) as units
      from public.reservations r
      where r.member_id = p_member_id
        and r.office_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start
        and r.starts_at < v_period_end
      group by r.office_id,
               date_trunc('day', r.starts_at at time zone v_tz)::date
    ) hx
    join public.offices o on o.id = hx.office_id;
  else
    select coalesce(sum(o.price_cents), 0) into v_office_supplement
    from (
      select distinct
        r.office_id,
        date_trunc('day', r.starts_at at time zone v_tz)::date as day,
        case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                  + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
             then 0 else 1 end as slot
      from public.reservations r
      where r.member_id = p_member_id
        and r.office_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start and r.starts_at < v_period_end
    ) oh
    join public.offices o on o.id = oh.office_id;
  end if;

  -- #desk: price × distinct half-days per reserved desk (0059).
  if v_gran = 'hours' then
    select coalesce(sum(d.price_cents * hx.units), 0) into v_desk_supplement
    from (
      select r.desk_id,
             least(2, greatest(1, ceil(
               sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
                 / v_half_minutes)::int)) as units
      from public.reservations r
      where r.member_id = p_member_id
        and r.desk_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start
        and r.starts_at < v_period_end
      group by r.desk_id,
               date_trunc('day', r.starts_at at time zone v_tz)::date
    ) hx
    join public.desks d on d.id = hx.desk_id;
  else
    select coalesce(sum(d.price_cents), 0) into v_desk_supplement
    from (
      select distinct
        r.desk_id,
        date_trunc('day', r.starts_at at time zone v_tz)::date as day,
        case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                  + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
             then 0 else 1 end as slot
      from public.reservations r
      where r.member_id = p_member_id
        and r.desk_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start and r.starts_at < v_period_end
    ) dh
    join public.desks d on d.id = dh.desk_id;
  end if;

  -- #512 — a credit CONSUMED by an invoice match settled that invoice;
  -- it must not ALSO improve its declared month's balance. Charges and
  -- unconsumed credits stay.
  select coalesce(sum(case when kind = 'credit' then amount_cents else -amount_cents end), 0)
  into v_credits
  from public.ledger_entries le
  where le.member_id = p_member_id and le.period = p_period
    and (le.kind <> 'credit' or not exists (
      select 1 from public.invoice_match_payments jr
      where jr.payment_ledger_id = le.id));

  return jsonb_build_object(
    'period', p_period,
    'subscription_pct', v_pct,
    'fee_cents', v_base,
    'included_half_days', v_included,
    'open_days', v_open_days,
    'used_half_days', v_used,
    'extra_half_days', v_extra_half_days,
    'overage_cents', v_overage,
    'accessory_supplement_cents', v_supplement,
    'level_supplement_cents', v_level_supplement,
    -- #office
    'office_supplement_cents', v_office_supplement,
    'desk_supplement_cents', v_desk_supplement,
    'credits_cents', v_credits,
    'balance_cents',
      v_credits - v_base - v_overage - v_supplement - v_level_supplement
        - v_office_supplement - v_desk_supplement,
    'overage_policy', coalesce(v_member.overage_policy, 'blocked'),
    'overage_rate_cents', v_overage_rate,
    'granted_half_days', v_granted,
    'remaining_half_days', v_remaining
  );
end;
$$;
revoke execute on function public.member_statement(uuid, text) from public, anon;

create or replace function public.invoice_lines_for(
  p_member_id uuid,
  p_period text
) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_stmt jsonb;
  v_lines jsonb := '[]'::jsonb;
  v_row record;
  v_workspace uuid;
  v_default numeric;
begin
  v_stmt := public.member_statement(p_member_id, p_period);
  select workspace_id into v_workspace from public.members where id = p_member_id;
  v_default := public.workspace_default_vat_percent(v_workspace);

  if (v_stmt->>'fee_cents')::int > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'subscription',
      'label', v_stmt->>'subscription_pct',
      'quantity', 1,
      'vat_percent', v_default,
      'amount_cents', (v_stmt->>'fee_cents')::int);
  end if;
  if (v_stmt->>'overage_cents')::int > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'overage',
      'label', '',
      'quantity', (v_stmt->>'extra_half_days')::int,
      'vat_percent', v_default,
      'amount_cents', (v_stmt->>'overage_cents')::int);
  end if;
  if coalesce((v_stmt->>'accessory_supplement_cents')::int, 0) > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'accessories', 'label', '', 'quantity', 1,
      'vat_percent', v_default,
      'amount_cents', (v_stmt->>'accessory_supplement_cents')::int);
  end if;
  if coalesce((v_stmt->>'level_supplement_cents')::int, 0) > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'level', 'label', '', 'quantity', 1,
      'vat_percent', v_default,
      'amount_cents', (v_stmt->>'level_supplement_cents')::int);
  end if;
  if coalesce((v_stmt->>'office_supplement_cents')::int, 0) > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'office', 'label', '', 'quantity', 1,
      'vat_percent', v_default,
      'amount_cents', (v_stmt->>'office_supplement_cents')::int);
  end if;
  if coalesce((v_stmt->>'desk_supplement_cents')::int, 0) > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'desk', 'label', '', 'quantity', 1,
      'vat_percent', v_default,
      'amount_cents', (v_stmt->>'desk_supplement_cents')::int);
  end if;

  for v_row in
    select kind, category, description, amount_cents, vat_percent
      from public.ledger_entries le
     where le.member_id = p_member_id
       and le.period = p_period
       and ((le.kind = 'charge'
             and le.category in ('service', 'package', 'adjustment'))
         or (le.kind = 'credit'
             and le.category in ('payment', 'expense', 'adjustment')
             -- #512 — a credit consumed by an invoice match already
             -- settled ANOTHER invoice; deducting it here too would
             -- spend it twice.
             and not exists (
               select 1 from public.invoice_match_payments jr
               where jr.payment_ledger_id = le.id)))
     order by le.created_at
  loop
    v_lines := v_lines || jsonb_build_object(
      'kind', v_row.category,
      'label', v_row.description,
      'quantity', 1,
      -- The rate stamped when the charge was booked; the workspace
      -- default for anything older than 0072 or unstamped. A credit is
      -- money moving, not a supply: no VAT.
      'vat_percent', case when v_row.kind = 'credit' then 0
                          else coalesce(v_row.vat_percent, v_default) end,
      'amount_cents', case when v_row.kind = 'credit'
                           then -v_row.amount_cents
                           else v_row.amount_cents end);
  end loop;

  return v_lines;
end;
$$;
revoke execute on function public.invoice_lines_for(uuid, text)
  from public, anon;

create or replace function public.match_invoice(
  p_invoice_id uuid,
  p_payment_ledger_id uuid,
  p_resolution text,
  p_note text default ''
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_invoice public.invoices;
  v_existing public.invoice_matches;
  v_payment public.ledger_entries;
  v_paid int;
  v_due int;
  v_actor public.members;
  v_actor_name text;
  v_note text := btrim(coalesce(p_note, ''));
  v_has_policy boolean;
  v_event_id uuid;
  v_credit_id uuid := null;
  v_additional boolean := false;
begin
  select * into v_invoice from public.invoices where id = p_invoice_id;
  if v_invoice.id is null then raise exception 'unknown invoice'; end if;
  if v_invoice.voided_at is not null then
    raise exception 'invoice is voided';
  end if;
  select * into v_existing from public.invoice_matches
    where invoice_id = p_invoice_id;
  if v_existing.invoice_id is not null then
    -- #506 — only a STANDING partial (not written off) accepts more.
    if v_existing.status <> 'confirmed'
       or v_existing.resolution <> 'under_accepted'
       or v_existing.writeoff_at is not null then
      raise exception 'invoice already matched';
    end if;
    v_additional := true;
    v_due := v_invoice.total_cents - v_existing.paid_cents;
  else
    v_due := v_invoice.total_cents;
  end if;
  select * into v_actor from public.members
    where workspace_id = v_invoice.workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if not public.is_owner_of(v_invoice.workspace_id) and not coalesce(
    (select w.feature_flags -> 'adminInvoicing' = to_jsonb(true)
       from public.workspaces w where w.id = v_invoice.workspace_id), false) then
    raise exception 'admins may not issue invoices here';
  end if;

  -- #512 — settlement sources: registered payments AND account credits
  -- (category 'adjustment': credit-note excess) — the imputation of an
  -- avoir on any outstanding invoice, past months included.
  select * into v_payment from public.ledger_entries
    where id = p_payment_ledger_id
      and workspace_id = v_invoice.workspace_id
      and member_id = v_invoice.member_id
      and kind = 'credit' and category in ('payment', 'adjustment');
  if v_payment.id is null then raise exception 'unknown payment'; end if;
  -- A credit already BAKED into an issued invoice (negative line at
  -- derivation) was spent there — it cannot settle a second document.
  if exists (
    select 1 from public.invoices i
    where i.member_id = v_invoice.member_id
      and i.period = v_payment.period
      and i.voided_at is null
      and i.issued_at > v_payment.created_at) then
    raise exception 'credit already deducted on an issued invoice';
  end if;
  if exists (select 1 from public.invoice_match_payments
              where payment_ledger_id = p_payment_ledger_id) then
    raise exception 'payment already matched';
  end if;
  v_paid := v_payment.amount_cents;

  if p_resolution not in
      ('exact','over_forced','over_credit_note','under_accepted') then
    raise exception 'unknown resolution';
  end if;
  -- All amount rules compare against what is STILL DUE (#506).
  if p_resolution = 'exact' and v_paid <> v_due then
    raise exception 'amount does not match the invoice';
  end if;
  if p_resolution in ('over_forced','over_credit_note')
     and v_paid <= v_due then
    raise exception 'amount does not exceed the invoice';
  end if;
  if p_resolution = 'under_accepted' and v_paid >= v_due then
    raise exception 'amount is not below the invoice';
  end if;
  if p_resolution in ('over_forced','under_accepted') and v_note = '' then
    raise exception 'a note is required';
  end if;

  select coalesce(display_name, '') into v_actor_name
    from public.profiles where id = v_actor.user_id;

  if p_resolution = 'over_credit_note' then
    insert into public.ledger_entries
      (workspace_id, member_id, kind, category, amount_cents,
       description, period)
    values
      (v_invoice.workspace_id, v_invoice.member_id, 'credit',
       'adjustment', v_paid - v_due,
       'Credit note ' || v_invoice.number
         || case when v_note = '' then '' else ' — ' || v_note end,
       to_char(now(), 'YYYY-MM'))
    returning id into v_credit_id;
  end if;

  v_has_policy := exists (
    select 1 from public.validation_policies vp
    where vp.workspace_id = v_invoice.workspace_id
      and vp.event_type = 'invoice_payment');

  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id,
     payload, status, decided_at)
  values
    (v_invoice.workspace_id, 'invoice_payment', 'submitted',
     v_actor.id, v_invoice.member_id,
     jsonb_build_object(
       'invoice_id', v_invoice.id,
       'number', v_invoice.number,
       'due_cents', v_due,
       'paid_cents', v_paid,
       'amount_cents', v_paid,
       'payment_ledger_id', p_payment_ledger_id,
       'resolution', p_resolution,
       'note', v_note,
       'additional', v_additional),
     case when v_has_policy then 'pending' else 'confirmed' end,
     case when v_has_policy then null else now() end)
  returning id into v_event_id;

  -- The junction row reserves the payment even while pending.
  insert into public.invoice_match_payments
    (workspace_id, invoice_id, payment_ledger_id, amount_cents,
     resolution, note, event_id, credit_ledger_id, by_name)
  values
    (v_invoice.workspace_id, p_invoice_id, p_payment_ledger_id, v_paid,
     p_resolution, v_note, v_event_id, v_credit_id, v_actor_name);

  if v_additional then
    -- The aggregate moves only when the payment stands.
    if not v_has_policy then
      update public.invoice_matches
        set paid_cents = paid_cents + v_paid,
            resolution = p_resolution,
            note = case when v_note = '' then note else v_note end,
            payment_ledger_id = p_payment_ledger_id,
            credit_ledger_id = coalesce(v_credit_id, credit_ledger_id),
            matched_at = now(),
            by_name = v_actor_name
        where invoice_id = p_invoice_id;
    end if;
  else
    insert into public.invoice_matches
      (workspace_id, invoice_id, paid_cents, resolution, note, status,
       event_id, credit_ledger_id, payment_ledger_id, by_name)
    values
      (v_invoice.workspace_id, p_invoice_id, v_paid, p_resolution,
       v_note, case when v_has_policy then 'pending' else 'confirmed' end,
       v_event_id, v_credit_id, p_payment_ledger_id, v_actor_name);
  end if;
end;
$$;
revoke execute on function public.match_invoice(uuid, uuid, text, text) from public, anon;

-- 4. The member's REAL position, cross-month (#512). RLS-equivalent
-- guard inline: the member themselves or a workspace admin/owner.
create or replace function public.member_account(
  p_member_id uuid
) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_member public.members;
  v_credit int;
  v_refunds int;
  v_open jsonb;
  v_open_total int;
begin
  select * into v_member from public.members where id = p_member_id;
  if v_member.id is null then raise exception 'unknown member'; end if;
  if not public.is_admin_of(v_member.workspace_id) and not exists (
    select 1 from public.members m
    where m.id = p_member_id and m.user_id = auth.uid()
  ) then
    raise exception 'not your account';
  end if;

  -- Credit on account: unconsumed, not baked into an issued invoice,
  -- and genuinely SPARE — an avoir (adjustment) of any month, or a
  -- payment left over from a PAST month. A payment declared for the
  -- running month is not spare: it offsets that month's upcoming
  -- invoice and stays an ordinary payment on the bill.
  select coalesce(sum(le.amount_cents), 0) into v_credit
  from public.ledger_entries le
  where le.member_id = p_member_id
    and le.kind = 'credit' and le.category in ('payment', 'adjustment')
    and (le.category = 'adjustment'
         or le.period < to_char(now(), 'YYYY-MM'))
    and not exists (
      select 1 from public.invoice_match_payments jr
      where jr.payment_ledger_id = le.id)
    and not exists (
      select 1 from public.invoices i
      where i.member_id = p_member_id
        and i.period = le.period
        and i.voided_at is null
        and i.issued_at > le.created_at);

  -- Open POSITIVE invoices (not voided, not replaced) at their
  -- remaining value; pending matches settle nothing yet.
  select coalesce(jsonb_agg(jsonb_build_object(
           'invoice_id', o.id, 'number', o.number, 'period', o.period,
           'total_cents', o.total_cents, 'paid_cents', o.paid,
           'remaining_cents', o.remaining) order by o.issued_at),
         '[]'::jsonb),
         coalesce(sum(o.remaining), 0)
    into v_open, v_open_total
  from (
    select i.id, i.number, i.period, i.total_cents, i.issued_at,
           coalesce(m.paid_cents, 0) as paid,
           i.total_cents - case
             when m.invoice_id is not null and m.status = 'confirmed'
                  and m.resolution = 'under_accepted'
                  and m.writeoff_at is null then m.paid_cents
             else 0 end as remaining
    from public.invoices i
    left join public.invoice_matches m on m.invoice_id = i.id
    where i.member_id = p_member_id
      and i.total_cents > 0
      and i.voided_at is null
      and not exists (select 1 from public.invoices r
                       where r.replaces_invoice_id = i.id
                         and r.voided_at is null)
      and (m.invoice_id is null
           or m.status = 'pending'
           or (m.resolution = 'under_accepted' and m.writeoff_at is null))
  ) o;

  -- Refunds due: open credit notes (negative, unmatched).
  select coalesce(sum(-i.total_cents), 0) into v_refunds
  from public.invoices i
  where i.member_id = p_member_id
    and i.total_cents < 0
    and i.voided_at is null
    and not exists (select 1 from public.invoice_matches m
                     where m.invoice_id = i.id);

  return jsonb_build_object(
    'credit_cents', v_credit,
    'open_invoices', v_open,
    'open_total_cents', v_open_total,
    'refunds_due_cents', v_refunds,
    'net_position_cents', v_credit + v_refunds - v_open_total
  );
end;
$$;
revoke execute on function public.member_account(uuid) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- #513 — CENTRALIZED role management. One permission catalog, one
-- matrix per workspace (role → granted permissions), one helper every
-- gate consults:
--   · the OWNER always holds every permission — not stored, not
--     editable;
--   · an ACTIVE co-owner defaults to all of them ("co-owner can have
--     less" — the owner may remove some);
--   · an admin defaults to today's admin abilities; the legacy
--     adminInvoicing feature flag keeps granting issueInvoices for
--     compatibility;
--   · a plain member defaults to none.
-- An absent role key in role_permissions means "the defaults" — a
-- workspace that never opens the matrix behaves exactly as before.
-- match_invoice/create_invoice bodies generated from 0103/0072.

alter table public.workspaces
  add column if not exists role_permissions jsonb not null default '{}'::jsonb;

create or replace function public.has_permission(ws uuid, perm text)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1
    from public.members m
    join public.workspaces w on w.id = ws
    where m.workspace_id = ws and m.user_id = auth.uid()
      and m.status = 'active'
      and (
        m.is_owner
        or (m.co_owner = 'active' and (
              case when w.role_permissions ? 'co_owner'
                   then w.role_permissions->'co_owner' ? perm
                   else true end))
        or (m.is_admin and (
              (case when w.role_permissions ? 'admin'
                    then w.role_permissions->'admin' ? perm
                    else perm in ('manageMembers','manageDocuments',
                                  'manageServices','approveExpenses',
                                  'viewFinances') end)
              or (perm = 'issueInvoices'
                  and coalesce(w.feature_flags -> 'adminInvoicing'
                                 = to_jsonb(true), false))))
        or (not m.is_admin and not m.is_owner and m.co_owner <> 'active'
            and w.role_permissions ? 'member'
            and w.role_permissions->'member' ? perm)
      )
  );
$$;
revoke execute on function public.has_permission(uuid, text) from public, anon;

-- The owner (or whoever holds manageRoles) shapes the matrix. The
-- 'owner' row does not exist: owners always hold everything.
create or replace function public.set_role_permissions(
  p_workspace_id uuid,
  p_role text,
  p_permissions text[]
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_catalog text[] := array[
    'manageRoles','manageMembers','manageValidation','workspaceSettings',
    'issueInvoices','viewFinances','manageDocuments','manageServices',
    'approveExpenses'];
  v_perm text;
begin
  if not public.has_permission(p_workspace_id, 'manageRoles') then
    raise exception 'only role managers may edit permissions';
  end if;
  if p_role not in ('co_owner','admin','member') then
    raise exception 'unknown role';
  end if;
  foreach v_perm in array coalesce(p_permissions, '{}') loop
    if not (v_perm = any(v_catalog)) then
      raise exception 'unknown permission %', v_perm;
    end if;
  end loop;
  update public.workspaces
    set role_permissions = jsonb_set(
      coalesce(role_permissions, '{}'::jsonb),
      array[p_role],
      coalesce(to_jsonb(p_permissions), '[]'::jsonb))
    where id = p_workspace_id;
end;
$$;
revoke execute on function public.set_role_permissions(uuid, text, text[])
  from public, anon;

create or replace function public.match_invoice(
  p_invoice_id uuid,
  p_payment_ledger_id uuid,
  p_resolution text,
  p_note text default ''
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_invoice public.invoices;
  v_existing public.invoice_matches;
  v_payment public.ledger_entries;
  v_paid int;
  v_due int;
  v_actor public.members;
  v_actor_name text;
  v_note text := btrim(coalesce(p_note, ''));
  v_has_policy boolean;
  v_event_id uuid;
  v_credit_id uuid := null;
  v_additional boolean := false;
begin
  select * into v_invoice from public.invoices where id = p_invoice_id;
  if v_invoice.id is null then raise exception 'unknown invoice'; end if;
  if v_invoice.voided_at is not null then
    raise exception 'invoice is voided';
  end if;
  select * into v_existing from public.invoice_matches
    where invoice_id = p_invoice_id;
  if v_existing.invoice_id is not null then
    -- #506 — only a STANDING partial (not written off) accepts more.
    if v_existing.status <> 'confirmed'
       or v_existing.resolution <> 'under_accepted'
       or v_existing.writeoff_at is not null then
      raise exception 'invoice already matched';
    end if;
    v_additional := true;
    v_due := v_invoice.total_cents - v_existing.paid_cents;
  else
    v_due := v_invoice.total_cents;
  end if;
  select * into v_actor from public.members
    where workspace_id = v_invoice.workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  -- #513 — the CENTRAL permission decides: owner always passes,
  -- co-owner/admin/member per the workspace's role matrix; the
  -- legacy adminInvoicing flag keeps granting inside
  -- has_permission for compatibility.
  if not public.has_permission(v_invoice.workspace_id, 'issueInvoices') then
    raise exception 'admins may not issue invoices here';
  end if;

  -- #512 — settlement sources: registered payments AND account credits
  -- (category 'adjustment': credit-note excess) — the imputation of an
  -- avoir on any outstanding invoice, past months included.
  select * into v_payment from public.ledger_entries
    where id = p_payment_ledger_id
      and workspace_id = v_invoice.workspace_id
      and member_id = v_invoice.member_id
      and kind = 'credit' and category in ('payment', 'adjustment');
  if v_payment.id is null then raise exception 'unknown payment'; end if;
  -- A credit already BAKED into an issued invoice (negative line at
  -- derivation) was spent there — it cannot settle a second document.
  if exists (
    select 1 from public.invoices i
    where i.member_id = v_invoice.member_id
      and i.period = v_payment.period
      and i.voided_at is null
      and i.issued_at > v_payment.created_at) then
    raise exception 'credit already deducted on an issued invoice';
  end if;
  if exists (select 1 from public.invoice_match_payments
              where payment_ledger_id = p_payment_ledger_id) then
    raise exception 'payment already matched';
  end if;
  v_paid := v_payment.amount_cents;

  if p_resolution not in
      ('exact','over_forced','over_credit_note','under_accepted') then
    raise exception 'unknown resolution';
  end if;
  -- All amount rules compare against what is STILL DUE (#506).
  if p_resolution = 'exact' and v_paid <> v_due then
    raise exception 'amount does not match the invoice';
  end if;
  if p_resolution in ('over_forced','over_credit_note')
     and v_paid <= v_due then
    raise exception 'amount does not exceed the invoice';
  end if;
  if p_resolution = 'under_accepted' and v_paid >= v_due then
    raise exception 'amount is not below the invoice';
  end if;
  if p_resolution in ('over_forced','under_accepted') and v_note = '' then
    raise exception 'a note is required';
  end if;

  select coalesce(display_name, '') into v_actor_name
    from public.profiles where id = v_actor.user_id;

  if p_resolution = 'over_credit_note' then
    insert into public.ledger_entries
      (workspace_id, member_id, kind, category, amount_cents,
       description, period)
    values
      (v_invoice.workspace_id, v_invoice.member_id, 'credit',
       'adjustment', v_paid - v_due,
       'Credit note ' || v_invoice.number
         || case when v_note = '' then '' else ' — ' || v_note end,
       to_char(now(), 'YYYY-MM'))
    returning id into v_credit_id;
  end if;

  v_has_policy := exists (
    select 1 from public.validation_policies vp
    where vp.workspace_id = v_invoice.workspace_id
      and vp.event_type = 'invoice_payment');

  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id,
     payload, status, decided_at)
  values
    (v_invoice.workspace_id, 'invoice_payment', 'submitted',
     v_actor.id, v_invoice.member_id,
     jsonb_build_object(
       'invoice_id', v_invoice.id,
       'number', v_invoice.number,
       'due_cents', v_due,
       'paid_cents', v_paid,
       'amount_cents', v_paid,
       'payment_ledger_id', p_payment_ledger_id,
       'resolution', p_resolution,
       'note', v_note,
       'additional', v_additional),
     case when v_has_policy then 'pending' else 'confirmed' end,
     case when v_has_policy then null else now() end)
  returning id into v_event_id;

  -- The junction row reserves the payment even while pending.
  insert into public.invoice_match_payments
    (workspace_id, invoice_id, payment_ledger_id, amount_cents,
     resolution, note, event_id, credit_ledger_id, by_name)
  values
    (v_invoice.workspace_id, p_invoice_id, p_payment_ledger_id, v_paid,
     p_resolution, v_note, v_event_id, v_credit_id, v_actor_name);

  if v_additional then
    -- The aggregate moves only when the payment stands.
    if not v_has_policy then
      update public.invoice_matches
        set paid_cents = paid_cents + v_paid,
            resolution = p_resolution,
            note = case when v_note = '' then note else v_note end,
            payment_ledger_id = p_payment_ledger_id,
            credit_ledger_id = coalesce(v_credit_id, credit_ledger_id),
            matched_at = now(),
            by_name = v_actor_name
        where invoice_id = p_invoice_id;
    end if;
  else
    insert into public.invoice_matches
      (workspace_id, invoice_id, paid_cents, resolution, note, status,
       event_id, credit_ledger_id, payment_ledger_id, by_name)
    values
      (v_invoice.workspace_id, p_invoice_id, v_paid, p_resolution,
       v_note, case when v_has_policy then 'pending' else 'confirmed' end,
       v_event_id, v_credit_id, p_payment_ledger_id, v_actor_name);
  end if;
end;
$$;
revoke execute on function public.match_invoice(uuid, uuid, text, text) from public, anon;

create or replace function public.create_invoice(
  p_workspace_id uuid,
  p_member_id uuid,
  p_period text,
  p_replaces uuid default null,
  p_detailed boolean default false
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_subject public.members;
  v_workspace public.workspaces;
  v_replaced public.invoices;
  v_replaces_number text := '';
  v_lines jsonb;
  v_details jsonb := null;
  v_parties jsonb;
  v_vat_totals jsonb;
  v_zero_category text;
  v_tz text;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_total int := 0;
  v_count int;
  v_number text;
  v_member_name text;
  v_member_address text;
  v_member_country text;
  v_member_vat text;
  v_issuer_name text;
  v_id uuid;
  v_signature text;
begin
  select * into v_actor from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  -- #513 — the CENTRAL permission decides: owner always passes,
  -- co-owner/admin/member per the workspace's role matrix; the
  -- legacy adminInvoicing flag keeps granting inside
  -- has_permission for compatibility.
  if not public.has_permission(p_workspace_id, 'issueInvoices') then
    raise exception 'admins may not issue invoices here';
  end if;

  select * into v_subject from public.members
    where id = p_member_id and workspace_id = p_workspace_id
      and status = 'active' and not is_kiosk;
  if v_subject.id is null then raise exception 'unknown subject member'; end if;
  if p_period is null or p_period !~ '^[0-9]{4}-[0-9]{2}$' then
    raise exception 'invalid period';
  end if;
  if exists (
    select 1 from public.invoices i
    where i.member_id = v_subject.id and i.period = p_period
      and i.voided_at is null and i.id is distinct from p_replaces
  ) then
    raise exception 'period already invoiced for this member';
  end if;

  v_lines := public.invoice_lines_for(p_member_id, p_period);
  if jsonb_array_length(v_lines) = 0 then
    raise exception 'nothing to invoice for this period';
  end if;
  select coalesce(sum((l->>'amount_cents')::int), 0) into v_total
    from jsonb_array_elements(v_lines) l;

  select * into v_workspace from public.workspaces where id = p_workspace_id;
  select coalesce(display_name, ''), coalesce(address, ''),
         coalesce(country_code, ''), coalesce(vat_id, '')
    into v_member_name, v_member_address, v_member_country, v_member_vat
    from public.profiles where id = v_subject.user_id;
  select coalesce(display_name, '') into v_issuer_name
    from public.profiles where id = v_actor.user_id;

  -- A 0% line is categorised by the workspace's declared regime, exactly
  -- as before VAT existed: outside the scope, or exempt.
  v_zero_category := case coalesce(v_workspace.vat_regime, 'not_subject')
                       when 'exempt' then 'E' else 'O' end;

  -- One entry per rate. Charges only: a credit is money moving.
  with charges as (
    select coalesce((l->>'vat_percent')::numeric, 0) as percent,
           (l->>'amount_cents')::int as gross,
           round((l->>'amount_cents')::int * 100.0
                 / (100 + coalesce((l->>'vat_percent')::numeric, 0)))::int as net
      from jsonb_array_elements(v_lines) l
     where (l->>'amount_cents')::int > 0
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'percent', percent,
      'category', case when percent > 0 then 'S' else v_zero_category end,
      'gross_cents', gross,
      'net_cents', net,
      'vat_cents', gross - net) order by percent desc), '[]'::jsonb)
    into v_vat_totals
    from (
      select percent, sum(gross)::int as gross, sum(net)::int as net
        from charges group by percent
    ) grouped;

  v_parties := jsonb_build_object(
    'seller', jsonb_build_object(
      'name', v_workspace.name,
      'street', coalesce(nullif(v_workspace.street, ''),
                         coalesce(v_workspace.address, '')),
      'city', coalesce(v_workspace.city, ''),
      'postal_code', coalesce(v_workspace.postal_code, ''),
      'country', v_workspace.country_code,
      'vat_id', coalesce(v_workspace.vat_id, ''),
      'legal_id', coalesce(v_workspace.legal_id, ''),
      'vat_regime', coalesce(v_workspace.vat_regime, 'not_subject'),
      'tax_exemption_reason',
        coalesce(v_workspace.tax_exemption_reason, '')),
    'buyer', jsonb_build_object(
      'name', v_member_name,
      'street', v_member_address,
      'country', coalesce(nullif(v_member_country, ''),
                          v_workspace.country_code),
      'vat_id', v_member_vat));

  if p_detailed then
    v_tz := v_workspace.timezone;
    v_period_start := to_timestamp(p_period || '-01', 'YYYY-MM-DD') at time zone v_tz;
    v_period_end := (to_timestamp(p_period || '-01', 'YYYY-MM-DD') + interval '1 month') at time zone v_tz;
    v_details := jsonb_build_object(
      'ledger', coalesce((
        select jsonb_agg(jsonb_build_object(
            'on', coalesce(le.occurred_on, le.created_at::date)::text,
            'category', le.category,
            'description', le.description,
            'amount_cents', case when le.kind = 'credit'
                                 then -le.amount_cents
                                 else le.amount_cents end)
          order by coalesce(le.occurred_on, le.created_at::date), le.created_at)
        from public.ledger_entries le
        where le.member_id = p_member_id and le.period = p_period
      ), '[]'::jsonb),
      'attendance', coalesce((
        select jsonb_agg(jsonb_build_object(
            'starts_at', to_char(r.starts_at at time zone v_tz,
                                 'YYYY-MM-DD"T"HH24:MI'),
            'ends_at', to_char(r.ends_at at time zone v_tz,
                               'YYYY-MM-DD"T"HH24:MI'),
            'status', r.status,
            'space', coalesce(
              (select s.name || ' · ' || d.name
                 from public.seats s
                 join public.desks d on d.id = s.desk_id
                where s.id = r.seat_id),
              (select d.name from public.desks d where d.id = r.desk_id),
              (select o.name from public.offices o where o.id = r.office_id),
              (select l.name from public.levels l where l.id = r.level_id),
              ''))
          order by r.starts_at)
        from public.reservations r
        where r.member_id = p_member_id
          and r.status in ('reserved', 'checked_in', 'completed')
          and r.starts_at >= v_period_start and r.starts_at < v_period_end
      ), '[]'::jsonb));
  end if;

  if p_replaces is not null then
    select * into v_replaced from public.invoices
      where id = p_replaces and workspace_id = p_workspace_id;
    if v_replaced.id is null then raise exception 'unknown invoice'; end if;
    if exists (select 1 from public.invoices
                where replaces_invoice_id = p_replaces) then
      raise exception 'invoice already replaced';
    end if;
    if exists (select 1 from public.invoice_matches
                where invoice_id = p_replaces) then
      raise exception 'invoice is matched';
    end if;
    if v_replaced.voided_at is null then
      update public.invoices
         set voided_at = now(), voided_by_name = v_issuer_name
       where id = p_replaces;
    end if;
    v_replaces_number := v_replaced.number;
  end if;

  perform pg_advisory_xact_lock(hashtext(p_workspace_id::text));
  select count(*) into v_count from public.invoices
    where workspace_id = p_workspace_id
      and date_part('year', issued_at) = date_part('year', now());
  v_number := 'INV-' || date_part('year', now())::int || '-'
      || lpad((v_count + 1)::text, 4, '0');

  v_id := gen_random_uuid();
  v_signature := encode(extensions.digest(convert_to(concat_ws('|',
      v_id::text, v_number, p_workspace_id::text, v_subject.id::text,
      v_member_name, v_member_address, v_workspace.name,
      coalesce(v_workspace.address, ''), v_issuer_name,
      p_period, v_lines::text, v_total::text, v_workspace.currency_code,
      now()::date::text, coalesce(p_replaces::text, ''),
      v_replaces_number, coalesce(v_details::text, ''),
      v_parties::text, v_vat_totals::text),
      'UTF8'), 'sha256'), 'hex');

  insert into public.invoices
    (id, workspace_id, member_id, issuer_member_id, number, period, title,
     lines, total_cents, currency, member_name, member_address,
     workspace_name, workspace_address, issuer_name, signature,
     replaces_invoice_id, replaces_number, details, parties, vat_totals)
  values
    (v_id, p_workspace_id, v_subject.id, v_actor.id, v_number, p_period,
     p_period, v_lines, v_total, v_workspace.currency_code,
     v_member_name, v_member_address, v_workspace.name,
     coalesce(v_workspace.address, ''), v_issuer_name, v_signature,
     p_replaces, v_replaces_number, v_details, v_parties, v_vat_totals);
  return v_id;
end;
$$;
revoke execute on function public.create_invoice(uuid, uuid, text, uuid, boolean) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- Read receipts for member notes (field request): the sender's message
-- list shows a small check — grey once delivered, blue once the DIRECT
-- recipient has read it. read_at is stamped by the recipient's app via
-- mark_member_notes_read when they open their messages; realtime (the
-- 0089 publication already carries updates) flips the sender's check
-- live. Broadcasts (to_member_id null) have many readers and no single
-- read state — they stay at the grey delivered check by design.

alter table public.member_notes add column read_at timestamptz;

create or replace function public.mark_member_notes_read(
  p_workspace_id uuid
) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_me public.members;
begin
  select * into v_me from public.members
    where workspace_id = p_workspace_id
      and user_id = auth.uid() and status = 'active';
  if v_me.id is null then
    raise exception 'not an active member of this workspace';
  end if;
  update public.member_notes
    set read_at = now()
    where workspace_id = p_workspace_id
      and to_member_id = v_me.id
      and read_at is null;
end;
$$;
revoke execute on function public.mark_member_notes_read(uuid)
  from public, anon;

-- SPDX-License-Identifier: 0BSD
-- #542: the VAT rate becomes CONFIGURABLE where it was hard-wired to
-- the workspace default — the subscription tariff (fee bands: monthly
-- fee + overage) gets one workspace-level rate, and each accessory gets
-- its own, both null = default (the services/packages resolution:
-- own ACTIVE rate, else the workspace default). Invoices tax
-- subscription/overage at the tariff rate and split the accessories
-- supplement into one line per rate when seats mix rates.
-- member_statement and invoice_lines_for are regenerated from 0103
-- with only those edits; level/office/desk supplements stay at the
-- workspace default (space pricing carries no own rate — yet).

alter table public.accessories
  add column vat_rate_id uuid references public.vat_rates(id)
    on delete set null;

alter table public.workspaces
  add column subscription_vat_rate_id uuid references public.vat_rates(id)
    on delete set null;

-- The tariff's percent: the workspace's chosen subscription rate when
-- it is still active, else the default (mirrors the services rule).
create or replace function public.workspace_tariff_vat_percent(
  p_workspace_id uuid
) returns numeric language sql stable security definer set search_path = public as $$
  select coalesce(
    (select vr.percent from public.vat_rates vr
      join public.workspaces w on w.subscription_vat_rate_id = vr.id
      where w.id = p_workspace_id and vr.active),
    public.workspace_default_vat_percent(p_workspace_id));
$$;
revoke execute on function public.workspace_tariff_vat_percent(uuid)
  from public, anon;

create or replace function public.member_statement(
  p_member_id uuid,
  p_period text
) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_member public.members;
  v_caller_is_admin boolean;
  v_band public.fee_bands;
  v_tz text;
  v_open int[];
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_month_first date;
  v_open_days int;
  v_pct int;
  v_included int;
  v_used int;
  v_base int := 0;
  v_overage int := 0;
  v_overage_rate int := 0;
  v_credits int;
  v_extra_half_days int := 0;
  v_supp_on boolean := false;
  v_supp_since timestamptz;
  v_supplement int := 0;
  -- #542: the same supplement broken down by VAT percent — accessories
  -- may carry different rates, and the invoice must tax each slice at
  -- its own rate.
  v_supp_by_rate jsonb := '[]'::jsonb;
  v_acc_default numeric;
  v_granted int := 0;
  v_cap int := 0;
  v_remaining int := 0;
  v_level_supplement int := 0;
  v_office_supplement int := 0;
  -- #desk (0059)
  v_desk_supplement int := 0;
  -- #446 working hours
  v_rules jsonb;
  v_gran text;
  v_bound int;
  v_half_minutes numeric;
begin
  select * into v_member from public.members where id = p_member_id;
  if v_member.id is null then raise exception 'unknown member'; end if;
  v_caller_is_admin := public.is_admin_of(v_member.workspace_id);
  if not v_caller_is_admin and not exists (
    select 1 from public.members m
    where m.id = p_member_id and m.user_id = auth.uid()
  ) then
    raise exception 'not your statement';
  end if;

  select timezone,
         coalesce((select array_agg(x::int)
                     from jsonb_array_elements_text(booking_rules->'open_weekdays') x),
                  array[1,2,3,4,5]),
         coalesce(feature_flags -> 'accessorySupplements' = to_jsonb(true), false),
         accessory_supplements_since,
         booking_rules
    into v_tz, v_open, v_supp_on, v_supp_since, v_rules
    from public.workspaces where id = v_member.workspace_id;
  -- #446: the half-day boundary and the hours-mode billing equivalents
  -- come from booking_rules; inconsistent values fall back to the
  -- defaults exactly like the client (WorkHours.fromRules).
  v_gran := v_rules->>'granularity';
  v_bound := coalesce((v_rules->>'half_boundary_minutes')::int, 720);
  if v_bound <= 0 or v_bound >= 1440 then v_bound := 720; end if;
  v_half_minutes := greatest(1, coalesce((v_rules->>'half_day_hours')::int, 4)) * 60.0;
  v_period_start := to_timestamp(p_period || '-01', 'YYYY-MM-DD') at time zone v_tz;
  v_period_end := (to_timestamp(p_period || '-01', 'YYYY-MM-DD') + interval '1 month') at time zone v_tz;
  v_month_first := to_date(p_period || '-01', 'YYYY-MM-DD');

  -- #512 — a month fully before the membership begins owes NOTHING:
  -- no subscription, no entitlement. The workspace started when it
  -- started; earlier months must not read outstanding.
  if p_period < to_char(v_member.joined_at at time zone v_tz, 'YYYY-MM') then
    return jsonb_build_object(
      'period', p_period,
      'subscription_pct', coalesce(v_member.subscription_pct, 100),
      'fee_cents', 0, 'included_half_days', 0, 'open_days', 0,
      'used_half_days', 0, 'extra_half_days', 0, 'overage_cents', 0,
      'accessory_supplement_cents', 0, 'level_supplement_cents', 0,
      'office_supplement_cents', 0, 'desk_supplement_cents', 0,
      'credits_cents', 0, 'balance_cents', 0,
      'overage_policy', coalesce(v_member.overage_policy, 'blocked'),
      'overage_rate_cents', 0, 'granted_half_days', 0,
      'remaining_half_days', 0
    );
  end if;

  v_pct := coalesce(v_member.subscription_pct, 100);
  select * into v_band from public.fee_bands
    where workspace_id = v_member.workspace_id
      and from_pct < v_pct and v_pct <= to_pct;
  if v_band.id is not null then
    v_base := v_band.fee_cents;
    v_overage_rate := v_band.overage_fee_cents;
  end if;

  select count(*) into v_open_days
  from generate_series(v_month_first,
                       (v_month_first + interval '1 month' - interval '1 day')::date,
                       interval '1 day') d
  where extract(isodow from d)::int = any(v_open)
    and not exists (select 1 from public.closure_days c
                     where c.workspace_id = v_member.workspace_id and c.day = d::date);
  v_included := ceil(v_open_days * 2 * v_pct / 100.0)::int;

  select count(distinct (date_trunc('day', r.starts_at at time zone v_tz)::date, s.slot))
  into v_used
  from public.reservations r
  cross join lateral (
    select case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
           then 0 else 1 end as slot
  ) s
  where r.member_id = p_member_id
    and r.status in ('reserved','checked_in','completed')
    and r.starts_at >= v_period_start and r.starts_at < v_period_end;

  -- #446 hours granularity: booked time per day converts to half-day
  -- equivalents — one half day per STARTED half_day_hours block,
  -- capped at 2 (a full day is two halves).
  if v_gran = 'hours' then
    select coalesce(sum(least(2, greatest(1,
             ceil(d.day_minutes / v_half_minutes)::int))), 0)
    into v_used
    from (
      select date_trunc('day', r.starts_at at time zone v_tz)::date as day,
             sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
               as day_minutes
      from public.reservations r
      where r.member_id = p_member_id
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start and r.starts_at < v_period_end
      group by 1
    ) d;
  end if;

  v_extra_half_days := greatest(0, v_used - v_included);
  v_overage := v_extra_half_days * v_overage_rate;

  select coalesce(sum(half_days), 0) into v_granted from public.quota_extensions
    where member_id = p_member_id and period = p_period;
  v_cap := v_included + v_granted;
  v_remaining := greatest(0, v_cap - v_used);

  if v_supp_on and v_supp_since is not null then
    v_acc_default := public.workspace_default_vat_percent(v_member.workspace_id);
    if v_gran = 'hours' then
      -- #446: half-day-equivalent units per seat and day. #542: seat
      -- totals split by each accessory's VAT percent (its own active
      -- rate, else the workspace default — the services resolution).
      select coalesce(jsonb_agg(jsonb_build_object(
               'percent', pr.percent, 'cents', pr.cents)
               order by pr.percent), '[]'::jsonb),
             coalesce(sum(pr.cents), 0)
      into v_supp_by_rate, v_supplement
      from (
        select rate.percent, sum(rate.unit_cents * hd.units)::int as cents
        from (
          select r.seat_id,
                 least(2, greatest(1, ceil(
                   sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
                     / v_half_minutes)::int)) as units
          from public.reservations r
          where r.member_id = p_member_id
            and r.seat_id is not null
            and r.status in ('reserved','checked_in','completed')
            and r.starts_at >= greatest(v_period_start, v_supp_since)
            and r.starts_at < v_period_end
          group by r.seat_id,
                   date_trunc('day', r.starts_at at time zone v_tz)::date
        ) hd
        join (
          select sa.seat_id,
                 coalesce((select vr.percent from public.vat_rates vr
                            where vr.id = a.vat_rate_id and vr.active),
                          v_acc_default) as percent,
                 sum(a.supplement_cents)::int as unit_cents
          from public.seat_accessories sa
          join public.accessories a on a.id = sa.accessory_id
          where a.active and a.supplement_cents > 0
          group by sa.seat_id, 2
        ) rate on rate.seat_id = hd.seat_id
        group by rate.percent
      ) pr;
    else
      select coalesce(jsonb_agg(jsonb_build_object(
               'percent', pr.percent, 'cents', pr.cents)
               order by pr.percent), '[]'::jsonb),
             coalesce(sum(pr.cents), 0)
      into v_supp_by_rate, v_supplement
      from (
        select rate.percent, sum(rate.unit_cents)::int as cents
        from (
          select distinct
            r.seat_id,
            date_trunc('day', r.starts_at at time zone v_tz)::date as day,
            case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                    + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
               then 0 else 1 end as slot
          from public.reservations r
          where r.member_id = p_member_id
            and r.seat_id is not null
            and r.status in ('reserved','checked_in','completed')
            and r.starts_at >= greatest(v_period_start, v_supp_since)
            and r.starts_at < v_period_end
        ) hd
        join (
          select sa.seat_id,
                 coalesce((select vr.percent from public.vat_rates vr
                            where vr.id = a.vat_rate_id and vr.active),
                          v_acc_default) as percent,
                 sum(a.supplement_cents)::int as unit_cents
          from public.seat_accessories sa
          join public.accessories a on a.id = sa.accessory_id
          where a.active and a.supplement_cents > 0
          group by sa.seat_id, 2
        ) rate on rate.seat_id = hd.seat_id
        group by rate.percent
      ) pr;
    end if;
  end if;

  if v_gran = 'hours' then
    select coalesce(sum(l.price_cents * hx.units), 0) into v_level_supplement
    from (
      select r.level_id,
             least(2, greatest(1, ceil(
               sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
                 / v_half_minutes)::int)) as units
      from public.reservations r
      where r.member_id = p_member_id
        and r.level_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start
        and r.starts_at < v_period_end
      group by r.level_id,
               date_trunc('day', r.starts_at at time zone v_tz)::date
    ) hx
    join public.levels l on l.id = hx.level_id;
  else
    select coalesce(sum(l.price_cents), 0) into v_level_supplement
    from (
      select distinct
        r.level_id,
        date_trunc('day', r.starts_at at time zone v_tz)::date as day,
        case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                  + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
             then 0 else 1 end as slot
      from public.reservations r
      where r.member_id = p_member_id
        and r.level_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start and r.starts_at < v_period_end
    ) lh
    join public.levels l on l.id = lh.level_id;
  end if;

  -- #office: price × distinct half-days per reserved office.
  if v_gran = 'hours' then
    select coalesce(sum(o.price_cents * hx.units), 0) into v_office_supplement
    from (
      select r.office_id,
             least(2, greatest(1, ceil(
               sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
                 / v_half_minutes)::int)) as units
      from public.reservations r
      where r.member_id = p_member_id
        and r.office_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start
        and r.starts_at < v_period_end
      group by r.office_id,
               date_trunc('day', r.starts_at at time zone v_tz)::date
    ) hx
    join public.offices o on o.id = hx.office_id;
  else
    select coalesce(sum(o.price_cents), 0) into v_office_supplement
    from (
      select distinct
        r.office_id,
        date_trunc('day', r.starts_at at time zone v_tz)::date as day,
        case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                  + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
             then 0 else 1 end as slot
      from public.reservations r
      where r.member_id = p_member_id
        and r.office_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start and r.starts_at < v_period_end
    ) oh
    join public.offices o on o.id = oh.office_id;
  end if;

  -- #desk: price × distinct half-days per reserved desk (0059).
  if v_gran = 'hours' then
    select coalesce(sum(d.price_cents * hx.units), 0) into v_desk_supplement
    from (
      select r.desk_id,
             least(2, greatest(1, ceil(
               sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
                 / v_half_minutes)::int)) as units
      from public.reservations r
      where r.member_id = p_member_id
        and r.desk_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start
        and r.starts_at < v_period_end
      group by r.desk_id,
               date_trunc('day', r.starts_at at time zone v_tz)::date
    ) hx
    join public.desks d on d.id = hx.desk_id;
  else
    select coalesce(sum(d.price_cents), 0) into v_desk_supplement
    from (
      select distinct
        r.desk_id,
        date_trunc('day', r.starts_at at time zone v_tz)::date as day,
        case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                  + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
             then 0 else 1 end as slot
      from public.reservations r
      where r.member_id = p_member_id
        and r.desk_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start and r.starts_at < v_period_end
    ) dh
    join public.desks d on d.id = dh.desk_id;
  end if;

  -- #512 — a credit CONSUMED by an invoice match settled that invoice;
  -- it must not ALSO improve its declared month's balance. Charges and
  -- unconsumed credits stay.
  select coalesce(sum(case when kind = 'credit' then amount_cents else -amount_cents end), 0)
  into v_credits
  from public.ledger_entries le
  where le.member_id = p_member_id and le.period = p_period
    and (le.kind <> 'credit' or not exists (
      select 1 from public.invoice_match_payments jr
      where jr.payment_ledger_id = le.id));

  return jsonb_build_object(
    'period', p_period,
    'subscription_pct', v_pct,
    'fee_cents', v_base,
    'included_half_days', v_included,
    'open_days', v_open_days,
    'used_half_days', v_used,
    'extra_half_days', v_extra_half_days,
    'overage_cents', v_overage,
    'accessory_supplement_cents', v_supplement,
    'accessory_supplement_by_rate', v_supp_by_rate,
    'level_supplement_cents', v_level_supplement,
    -- #office
    'office_supplement_cents', v_office_supplement,
    'desk_supplement_cents', v_desk_supplement,
    'credits_cents', v_credits,
    'balance_cents',
      v_credits - v_base - v_overage - v_supplement - v_level_supplement
        - v_office_supplement - v_desk_supplement,
    'overage_policy', coalesce(v_member.overage_policy, 'blocked'),
    'overage_rate_cents', v_overage_rate,
    'granted_half_days', v_granted,
    'remaining_half_days', v_remaining
  );
end;
$$;
revoke execute on function public.member_statement(uuid, text) from public, anon;

create or replace function public.invoice_lines_for(
  p_member_id uuid,
  p_period text
) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_stmt jsonb;
  v_lines jsonb := '[]'::jsonb;
  v_row record;
  v_workspace uuid;
  v_default numeric;
  -- #542: the tariff's own rate for subscription + overage, and the
  -- per-rate accessory slices.
  v_tariff numeric;
  v_acc record;
begin
  v_stmt := public.member_statement(p_member_id, p_period);
  select workspace_id into v_workspace from public.members where id = p_member_id;
  v_default := public.workspace_default_vat_percent(v_workspace);
  v_tariff := public.workspace_tariff_vat_percent(v_workspace);

  if (v_stmt->>'fee_cents')::int > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'subscription',
      'label', v_stmt->>'subscription_pct',
      'quantity', 1,
      'vat_percent', v_tariff,
      'amount_cents', (v_stmt->>'fee_cents')::int);
  end if;
  if (v_stmt->>'overage_cents')::int > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'overage',
      'label', '',
      'quantity', (v_stmt->>'extra_half_days')::int,
      'vat_percent', v_tariff,
      'amount_cents', (v_stmt->>'overage_cents')::int);
  end if;
  -- #542: one accessories line PER VAT RATE — the statement's
  -- breakdown sums to accessory_supplement_cents by construction.
  if jsonb_typeof(v_stmt->'accessory_supplement_by_rate') = 'array' then
    for v_acc in
      select (e.value->>'percent')::numeric as percent,
             (e.value->>'cents')::int as cents
        from jsonb_array_elements(v_stmt->'accessory_supplement_by_rate') e
    loop
      if v_acc.cents > 0 then
        v_lines := v_lines || jsonb_build_object(
          'kind', 'accessories', 'label', '', 'quantity', 1,
          'vat_percent', v_acc.percent,
          'amount_cents', v_acc.cents);
      end if;
    end loop;
  elsif coalesce((v_stmt->>'accessory_supplement_cents')::int, 0) > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'accessories', 'label', '', 'quantity', 1,
      'vat_percent', v_default,
      'amount_cents', (v_stmt->>'accessory_supplement_cents')::int);
  end if;
  if coalesce((v_stmt->>'level_supplement_cents')::int, 0) > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'level', 'label', '', 'quantity', 1,
      'vat_percent', v_default,
      'amount_cents', (v_stmt->>'level_supplement_cents')::int);
  end if;
  if coalesce((v_stmt->>'office_supplement_cents')::int, 0) > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'office', 'label', '', 'quantity', 1,
      'vat_percent', v_default,
      'amount_cents', (v_stmt->>'office_supplement_cents')::int);
  end if;
  if coalesce((v_stmt->>'desk_supplement_cents')::int, 0) > 0 then
    v_lines := v_lines || jsonb_build_object(
      'kind', 'desk', 'label', '', 'quantity', 1,
      'vat_percent', v_default,
      'amount_cents', (v_stmt->>'desk_supplement_cents')::int);
  end if;

  for v_row in
    select kind, category, description, amount_cents, vat_percent
      from public.ledger_entries le
     where le.member_id = p_member_id
       and le.period = p_period
       and ((le.kind = 'charge'
             and le.category in ('service', 'package', 'adjustment'))
         or (le.kind = 'credit'
             and le.category in ('payment', 'expense', 'adjustment')
             -- #512 — a credit consumed by an invoice match already
             -- settled ANOTHER invoice; deducting it here too would
             -- spend it twice.
             and not exists (
               select 1 from public.invoice_match_payments jr
               where jr.payment_ledger_id = le.id)))
     order by le.created_at
  loop
    v_lines := v_lines || jsonb_build_object(
      'kind', v_row.category,
      'label', v_row.description,
      'quantity', 1,
      -- The rate stamped when the charge was booked; the workspace
      -- default for anything older than 0072 or unstamped. A credit is
      -- money moving, not a supply: no VAT.
      'vat_percent', case when v_row.kind = 'credit' then 0
                          else coalesce(v_row.vat_percent, v_default) end,
      'amount_cents', case when v_row.kind = 'credit'
                           then -v_row.amount_cents
                           else v_row.amount_cents end);
  end loop;

  return v_lines;
end;
$$;
revoke execute on function public.invoice_lines_for(uuid, text)
  from public, anon;

-- SPDX-License-Identifier: 0BSD
-- #552: the WhatsApp channel becomes configurable FROM THE APP — the
-- 0106 mirror needed WHATSAPP_TOKEN + WHATSAPP_PHONE_ID as project env
-- secrets, an operator-only step no owner could perform (the #300
-- payment-credentials lesson, again). Per-workspace credentials live in
-- a deny-all table only the service-role edge function and the
-- owner-only RPC below ever touch; the send-whatsapp function reads the
-- workspace's channel first and falls back to the env secrets.

create table public.workspace_channels (
  workspace_id uuid primary key
    references public.workspaces(id) on delete cascade,
  -- {token, phone_id} — the WhatsApp Business Cloud API credentials.
  whatsapp jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);

-- RLS with ZERO policies = deny-all to every client role: secrets are
-- write-only from the app's perspective.
alter table public.workspace_channels enable row level security;

-- Owner-only: MERGE the channel config. Non-blank fields overwrite;
-- blank/absent fields keep the existing value — the owner can fix the
-- phone id without re-typing a token they can never read back.
create or replace function public.set_whatsapp_channel(
  p_workspace_id uuid, p_config jsonb
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_clean jsonb;
begin
  if not public.is_owner_of(p_workspace_id) then
    raise exception 'not the owner of this workspace';
  end if;
  select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) into v_clean
    from jsonb_each(coalesce(p_config, '{}'::jsonb))
    where key in ('token', 'phone_id')
      and value is not null and trim(both '"' from value::text) <> '';
  if v_clean = '{}'::jsonb then return; end if;

  insert into public.workspace_channels (workspace_id, whatsapp, updated_at)
  values (p_workspace_id, v_clean, now())
  on conflict (workspace_id)
    do update set whatsapp = public.workspace_channels.whatsapp || v_clean,
                  updated_at = now();
end;
$$;
revoke execute on function public.set_whatsapp_channel(uuid, jsonb)
  from public, anon;

-- Owner-only: remove the channel entirely (messages fall back to
-- in-app + push, or to the env secrets if the operator set them).
create or replace function public.clear_whatsapp_channel(
  p_workspace_id uuid
) returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_owner_of(p_workspace_id) then
    raise exception 'not the owner of this workspace';
  end if;
  delete from public.workspace_channels
    where workspace_id = p_workspace_id;
end;
$$;
revoke execute on function public.clear_whatsapp_channel(uuid)
  from public, anon;

-- SPDX-License-Identifier: 0BSD
-- #562: re-requesting a deletion SUPERSEDES the pending request instead
-- of erroring. 0097 raised 'deletion already requested' — but from the
-- member's side a second demand means "my reason changed / nobody
-- reacted, ask again". The old pending event now EXPIRES (validators'
-- pending lists drop it, the audit trail keeps it) and a fresh event is
-- inserted — which re-fires the 0012 pending-event notification, so the
-- validators are pinged again. Body regenerated from 0097 with only
-- that guard replaced.

create or replace function public.request_reservation_deletion(
  p_reservation_id uuid, p_reason text default ''
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_res public.reservations;
  v_member public.members;
  v_id uuid;
begin
  select * into v_res from public.reservations where id = p_reservation_id;
  if v_res.id is null then raise exception 'unknown reservation'; end if;
  select * into v_member from public.members
    where workspace_id = v_res.workspace_id and user_id = auth.uid()
      and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if v_res.member_id <> v_member.id then
    raise exception 'only your own reservation';
  end if;
  if v_res.status not in ('reserved','checked_in','completed') then
    raise exception 'nothing to delete';
  end if;
  if v_res.status = 'reserved' and v_res.starts_at > now() then
    raise exception 'cancel directly — this booking has not started';
  end if;
  -- #562: supersede, don't refuse — the fresh insert below re-triggers
  -- the validator notification.
  update public.events
     set status = 'expired'
   where type = 'reservation_delete' and status = 'pending'
     and (payload->>'reservation_id')::uuid = p_reservation_id;
  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id,
     payload, status)
  values (
    v_res.workspace_id, 'reservation_delete', 'submitted',
    v_member.id, v_member.id,
    jsonb_build_object(
      'reservation_id', v_res.id,
      'starts_at', v_res.starts_at,
      'ends_at', v_res.ends_at,
      'was_checked_in', v_res.status <> 'reserved',
      'reason', left(coalesce(p_reason, ''), 300)
    ),
    'pending'
  )
  returning id into v_id;
  return v_id;
end;
$$;
revoke execute on function
  public.request_reservation_deletion(uuid, text) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- #573 — a check-in RIDES a reservation, and the reservation is the
-- workspace's own slot, not the arrival instant.
--
-- canonical_walkup_start answers which slot start canonically pairs
-- with a chosen walk-up END under day-based granularity: arrive at
-- 10:00 in a half-day workspace and "morning" books 08:00-12:00 (not
-- 10:00-12:00), "full day" books 08:00-17:00, "afternoon" stays
-- 12:00-17:00. Overtime windows (after the working day) keep the old
-- now-to-local-midnight shape. create_reservation v9 and kiosk_act v5
-- snap a walk-up check-in's start back to that slot start; when the
-- early slot part is genuinely taken (someone else's active row, or the
-- member's own morning elsewhere), ONE retry anchors the start at now()
-- instead of refusing the check-in outright.
--
-- check_in_reservation v4: being early on your own reservation's DAY is
-- presence, not a violation — under day-based/hours granularity a
-- same-workspace-day check-in is allowed ahead of the 15-minute leeway;
-- minute grids widen the leeway to one grid step. The reserved period
-- is CONFIRMED as reserved — the flip never rewrites the window.
-- kiosk_act v5 uses the same rule in its own-reservation lookup (the
-- 15-minute leeway was the only bridge — outside it the kiosk fell
-- through to a walk-up INSERT the one-place trigger rightly refused:
-- the "impossible to check in" field reports).
--
-- update_reservation v2 (#574): a CHECKED-IN booking may move its END
-- to a later canonical edge (morning to full day while sitting in the
-- seat); the start of a running booking never moves. enforce_booking_
-- rules v5 relaxes the half-day walk-up arms so a full-day walk-up (or
-- extension) may START mid-morning — v4 made "check in for the whole
-- day" at 10:00 impossible.

-- 1. The canonical slot start for a chosen walk-up end. NULL for
-- non-day-based granularities and for overtime windows — the caller
-- keeps what it was given. Mirrors enforce_booking_rules' own fallback
-- triple so constraint and derivation can never disagree.
create or replace function public.canonical_walkup_start(
  p_workspace_id uuid, p_starts_at timestamptz, p_ends_at timestamptz
) returns timestamptz language plpgsql stable security definer
set search_path = public as $$
declare
  rules jsonb; tz text; gran text;
  ws_start int; ws_bound int; ws_end int;
  local_start timestamp; local_end timestamp; d date;
  ts_start timestamp; ts_bound timestamp; ts_end timestamp;
begin
  select booking_rules, timezone into rules, tz
    from public.workspaces where id = p_workspace_id;
  gran := rules->>'granularity';
  if gran not in ('half_day', 'full_day') then return null; end if;

  ws_start := coalesce((rules->>'work_start_minutes')::int, 480);
  ws_bound := coalesce((rules->>'half_boundary_minutes')::int, 720);
  ws_end := coalesce((rules->>'work_end_minutes')::int, 1020);
  if not (ws_start >= 0 and ws_start < ws_bound
          and ws_bound < ws_end and ws_end <= 1440) then
    ws_start := 480; ws_bound := 720; ws_end := 1020;
  end if;
  local_start := p_starts_at at time zone tz;
  local_end := p_ends_at at time zone tz;
  d := local_start::date;
  ts_start := d::timestamp + make_interval(mins => ws_start);
  ts_bound := d::timestamp + make_interval(mins => ws_bound);
  ts_end := d::timestamp + make_interval(mins => ws_end);

  if gran = 'half_day' then
    if local_end = ts_bound then
      return ts_start at time zone tz;                 -- morning slot
    elsif local_end = ts_end then
      if local_start >= ts_bound then
        return ts_bound at time zone tz;               -- afternoon slot
      end if;
      return ts_start at time zone tz;                 -- full day
    end if;
  elsif local_end = ts_end then
    return ts_start at time zone tz;                   -- full day
  end if;
  return null;  -- overtime or an odd window: keep the caller's shape.
end;
$$;
revoke execute on function
  public.canonical_walkup_start(uuid, timestamptz, timestamptz)
  from public, anon, authenticated;

-- 2. enforce_booking_rules v5 — the 0087 body with the half-day
-- WALK-UP arms relaxed: a walk-up may end at the boundary OR at the end
-- of the working day from ANY earlier start. v4 required a full-day
-- walk-up to start at/after the boundary, which made "check in for the
-- whole day" at 10:00 impossible (the field report), and would refuse
-- the #573 retry-anchored windows and checked-in extensions.
create or replace function public.enforce_booking_rules(
  p_workspace_id uuid, p_starts_at timestamptz, p_ends_at timestamptz,
  p_walk_up boolean default false
) returns void language plpgsql stable security definer set search_path = public as $$
declare rules jsonb; horizon int; min_min int; max_min int; dur int;
        tz text; local_start timestamp; local_end timestamp;
        gran text; slot int;
        ws_start int; ws_bound int; ws_end int;
        d date; ts_start timestamp; ts_bound timestamp; ts_end timestamp;
        ts_midnight timestamp;
begin
  select booking_rules, timezone into rules, tz
    from public.workspaces where id = p_workspace_id;
  horizon := coalesce((rules->>'advance_horizon_days')::int, 90);
  min_min := coalesce((rules->>'min_duration_minutes')::int, 30);
  max_min := coalesce((rules->>'max_duration_minutes')::int, 1440);
  if p_starts_at > now() + make_interval(days => horizon) then
    raise exception 'beyond the advance-booking horizon of % days', horizon;
  end if;
  dur := extract(epoch from (p_ends_at - p_starts_at))::int / 60;
  if dur < min_min then
    raise exception 'below the minimum duration of % minutes', min_min;
  end if;
  if dur > max_min then
    raise exception 'above the maximum duration of % minutes', max_min;
  end if;

  gran := rules->>'granularity';
  local_start := p_starts_at at time zone tz;
  local_end := p_ends_at at time zone tz;

  -- #446: the working day comes from booking_rules (defaults 8:00 /
  -- 12:00 / 17:00 — WorkHours.defaults on the client). An inconsistent
  -- triple falls back to the defaults exactly like the client, so the
  -- constraint and the UI always agree on the canonical windows.
  ws_start := coalesce((rules->>'work_start_minutes')::int, 480);
  ws_bound := coalesce((rules->>'half_boundary_minutes')::int, 720);
  ws_end := coalesce((rules->>'work_end_minutes')::int, 1020);
  if not (ws_start >= 0 and ws_start < ws_bound
          and ws_bound < ws_end and ws_end <= 1440) then
    ws_start := 480; ws_bound := 720; ws_end := 1020;
  end if;
  d := local_start::date;
  ts_start := d::timestamp + make_interval(mins => ws_start);
  ts_bound := d::timestamp + make_interval(mins => ws_bound);
  ts_end := d::timestamp + make_interval(mins => ws_end);
  ts_midnight := d::timestamp + interval '1 day';

  -- Half-day granularity (#200/#201, #446, #573): the three canonical
  -- windows are the CONFIGURED working day. Walk-ups end at a canonical
  -- edge — the boundary or the end of the day — from any earlier start
  -- (#573: a 10:00 arrival checking in for the whole day is a walk-up
  -- ending at the day's end); at or after the end of the working day
  -- they may run to local midnight (overtime, the 0026 behaviour). The
  -- client pins the substring 'half-day' (BookingGranularityError).
  if gran = 'half_day' then
    if p_walk_up then
      if not (
        (local_end = ts_bound and local_start < ts_bound)
        or (local_end = ts_end and local_start < ts_end)
        or (local_start >= ts_end and local_end = ts_midnight)
      ) then
        raise exception 'walk-ups must end at the half-day boundary or the end of the working day';
      end if;
    elsif not (
      (local_start = ts_start and local_end = ts_bound)
      or (local_start = ts_bound and local_end = ts_end)
      or (local_start = ts_start and local_end = ts_end)
    ) then
      raise exception 'bookings must cover a half-day or the full working day';
    end if;

  -- Full-day granularity (0032, #446): exactly the working day. The
  -- client pins the substring 'cover the full day'.
  elsif gran = 'full_day' then
    if not (
      (local_end = ts_end and (p_walk_up or local_start = ts_start))
      or (p_walk_up and local_start >= ts_end and local_end = ts_midnight)
    ) then
      raise exception 'bookings must cover the full day (working hours)';
    end if;

  -- Minute grid (0032): unchanged. 'hours' (#446) deliberately matches
  -- no branch — free from-to times, no grid; billing converts booked
  -- time to half-day equivalents (member_statement v8).
  elsif gran in ('minutes_5','minutes_15','minutes_30','minutes_60') then
    slot := split_part(gran, '_', 2)::int;
    if not (
      extract(second from local_end) = 0
      and extract(minute from local_end)::int % slot = 0
      and (p_walk_up or (
        extract(second from local_start) = 0
        and extract(minute from local_start)::int % slot = 0))
    ) then
      raise exception 'bookings must start and end on the %-minute grid', slot;
    end if;
  end if;

  perform public.assert_workspace_open(p_workspace_id, p_starts_at, p_ends_at);
end;
$$;
revoke execute on function public.enforce_booking_rules(uuid, timestamptz, timestamptz, boolean) from public, anon, authenticated;

-- 3. create_reservation v9 — the 0079 body with the canonical walk-up
-- slot and the one-retry anchor. The validate+insert section runs in a
-- two-attempt loop: attempt 1 uses the snapped-back slot; a refusal
-- whose cause can only be the slot's EARLY part retries once anchored
-- at now(). Anything else re-raises unchanged.
create or replace function public.create_reservation(
  p_workspace_id uuid,
  p_seat_id uuid,
  p_office_id uuid,
  p_starts_at timestamptz,
  p_ends_at timestamptz,
  p_check_in boolean default false,
  p_level_id uuid default null,
  p_desk_id uuid default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_seat public.seats;
  v_office_id uuid;
  v_level_id uuid;
  v_id uuid;
  v_canon timestamptz;
  v_snapped boolean := false;
  v_starts timestamptz := p_starts_at;
  v_ends timestamptz := p_ends_at;
  v_attempt int;
begin
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if (case when p_seat_id is null then 0 else 1 end
      + case when p_desk_id is null then 0 else 1 end
      + case when p_office_id is null then 0 else 1 end
      + case when p_level_id is null then 0 else 1 end) <> 1 then
    raise exception 'exactly one of seat, desk, office or level required';
  end if;

  -- #573: a day-based walk-up check-in books the SLOT the chosen end
  -- belongs to, not the arrival instant — the start snaps BACK to the
  -- slot start, the chosen end stays the member's choice.
  if p_check_in then
    v_canon := public.canonical_walkup_start(
      p_workspace_id, p_starts_at, p_ends_at);
    if v_canon is not null and v_canon < v_starts then
      v_starts := v_canon;
      v_snapped := true;
    end if;
  end if;

  for v_attempt in 1..2 loop
    begin
      perform public.enforce_booking_rules(p_workspace_id, v_starts, v_ends, p_check_in);

      if p_seat_id is not null then
        select * into v_seat from public.seats
          where id = p_seat_id and workspace_id = p_workspace_id;
        if v_seat.id is null then raise exception 'unknown seat'; end if;
        if tstzrange(coalesce(v_seat.blocked_from, '-infinity'::timestamptz),
                     coalesce(v_seat.blocked_to, 'infinity'::timestamptz))
           && tstzrange(v_starts, v_ends)
           and (v_seat.blocked_from is not null or v_seat.blocked_to is not null) then
          raise exception 'seat is blocked in that period';
        end if;
        -- 0059: the seat's DESK reserved as a whole blocks the seat.
        if exists (
          select 1 from public.reservations r
          where r.desk_id = v_seat.desk_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'desk is reserved as a whole in that period';
        end if;
        select d.office_id into v_office_id from public.desks d where d.id = v_seat.desk_id;
        if exists (
          select 1 from public.reservations r
          where r.office_id = v_office_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'office is reserved as a whole in that period';
        end if;
        select o.level_id into v_level_id from public.offices o where o.id = v_office_id;
        if exists (
          select 1 from public.reservations r
          where r.level_id = v_level_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'level is reserved as a whole in that period';
        end if;
      elsif p_desk_id is not null then
        -- Whole-DESK path (0059): the level/office gates, desk-scale.
        if not public.level_booking_enabled(p_workspace_id) then
          raise exception 'level booking is not enabled';
        end if;
        if not (v_member.can_reserve_level or v_member.is_owner
                or v_member.is_admin) then
          -- the client pins this substring (0050)
          raise exception 'not allowed to reserve a level';
        end if;
        if not exists (
          select 1 from public.desks d
          where d.id = p_desk_id and d.workspace_id = p_workspace_id
            and d.bookable_as_whole
        ) then
          raise exception 'desk not bookable as a whole';
        end if;
        if exists (
          select 1 from public.reservations r
          join public.seats s on s.id = r.seat_id
          where s.desk_id = p_desk_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'a seat on this desk is already reserved in that period';
        end if;
        select d.office_id into v_office_id from public.desks d where d.id = p_desk_id;
        if exists (
          select 1 from public.reservations r
          where r.office_id = v_office_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'office is reserved as a whole in that period';
        end if;
        select o.level_id into v_level_id from public.offices o where o.id = v_office_id;
        if exists (
          select 1 from public.reservations r
          where r.level_id = v_level_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'level is reserved as a whole in that period';
        end if;
      elsif p_office_id is not null then
        -- Whole-space gates (0057): feature + personal grant, like levels.
        if not public.level_booking_enabled(p_workspace_id) then
          raise exception 'level booking is not enabled';
        end if;
        if not (v_member.can_reserve_level or v_member.is_owner
                or v_member.is_admin) then
          -- the client pins this substring (0050)
          raise exception 'not allowed to reserve a level';
        end if;
        if not exists (
          select 1 from public.offices o
          where o.id = p_office_id and o.workspace_id = p_workspace_id
            and o.bookable_as_whole
        ) then
          raise exception 'office not bookable as a whole';
        end if;
        if exists (
          select 1 from public.reservations r
          join public.seats s on s.id = r.seat_id
          join public.desks d on d.id = s.desk_id
          where d.office_id = p_office_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'a seat in this office is already reserved in that period';
        end if;
        -- 0059: a desk inside reserved as a whole blocks the office too.
        if exists (
          select 1 from public.reservations r
          join public.desks d on d.id = r.desk_id
          where d.office_id = p_office_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'a desk in this office is already reserved in that period';
        end if;
        select o.level_id into v_level_id from public.offices o where o.id = p_office_id;
        if exists (
          select 1 from public.reservations r
          where r.level_id = v_level_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'level is reserved as a whole in that period';
        end if;
      else
        -- Level path: feature on, level bookable, member personally allowed.
        if not public.level_booking_enabled(p_workspace_id) then
          raise exception 'level booking is not enabled';
        end if;
        if not exists (
          select 1 from public.levels l
          where l.id = p_level_id and l.workspace_id = p_workspace_id
            and l.bookable_as_whole
        ) then
          raise exception 'level not bookable as a whole';
        end if;
        if not (v_member.can_reserve_level or v_member.is_owner
                or v_member.is_admin) then
          -- the client pins this substring
          raise exception 'not allowed to reserve a level';
        end if;
        if public.level_has_conflict(p_level_id, v_starts, v_ends) then
          raise exception 'the level has reservations in that period';
        end if;
      end if;

      insert into public.reservations
        (workspace_id, seat_id, desk_id, office_id, level_id, member_id,
         starts_at, ends_at, status, checked_in_at)
      values (
        p_workspace_id, p_seat_id, p_desk_id, p_office_id, p_level_id,
        v_member.id, v_starts, v_ends,
        case when p_check_in then 'checked_in' else 'reserved' end,
        case when p_check_in then now() end
      )
      returning id into v_id;
      exit; -- validated and inserted — leave the retry loop.
    exception when others then
      -- The one-retry anchor: only a snapped-back walk-up can retry,
      -- and only once — the early slot part was genuinely taken, so
      -- the reservation anchors at now() and keeps the slot's END.
      if v_attempt = 1 and v_snapped
         and v_starts < now() and now() < v_ends then
        v_starts := now();
      else
        raise;
      end if;
    end;
  end loop;

  perform public.assert_member_quota(v_member.id, v_starts);

  -- 0059: whole-space bookings route through the REGULAR validation
  -- feature when the owner configured a rule for them — the reservation
  -- blocks the space immediately, validators confirm or reject (a
  -- reject cancels it via respond_to_event's existing branch).
  if p_desk_id is not null or p_office_id is not null
     or p_level_id is not null then
    if exists (
      select 1 from public.validation_policies vp
      where vp.workspace_id = p_workspace_id
        and vp.event_type = 'space_reservation'
    ) then
      update public.events
        set status = 'pending', type = 'space_reservation'
        where reservation_id = v_id and action = 'created';
    end if;
  end if;
  return v_id;
end;
$$;

-- 4. check_in_reservation v4 — the 0079 body with the same-day presence
-- rule. The reserved window itself is never rewritten: the check-in
-- CONFIRMS the reservation, exactly as booked.
create or replace function public.check_in_reservation(p_reservation_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_res public.reservations;
  v_own boolean;
  v_rules jsonb;
  v_tz text;
  v_gran text;
  v_leeway interval := interval '15 minutes';
begin
  select r.* into v_res from public.reservations r
    where r.id = p_reservation_id;
  if v_res.id is null then raise exception 'not your reservation'; end if;

  select exists (
    select 1 from public.members m
    where m.id = v_res.member_id and m.user_id = auth.uid()
  ) into v_own;

  if not v_own then
    -- The authorized-for-others path (0077): admin/owner + the
    -- bookForOthers feature (default ON, so ABSENT counts as ON).
    if not (
      public.is_admin_of(v_res.workspace_id)
      and coalesce((
        select w.feature_flags->'bookForOthers' is distinct from 'false'::jsonb
        from public.workspaces w where w.id = v_res.workspace_id
      ), true)
    ) then
      raise exception 'not your reservation';
    end if;
  end if;

  if v_res.status <> 'reserved' then raise exception 'not in reserved state'; end if;

  -- Presence window (0077 → #573). Day-based and hours granularity: the
  -- slot IS the working day, so any same-workspace-day arrival counts
  -- as presence. Minute grids: the leeway widens to one grid step.
  select w.booking_rules, w.timezone into v_rules, v_tz
    from public.workspaces w where w.id = v_res.workspace_id;
  v_gran := v_rules->>'granularity';
  if v_gran in ('minutes_5','minutes_15','minutes_30','minutes_60') then
    v_leeway := greatest(v_leeway,
      make_interval(mins => split_part(v_gran, '_', 2)::int));
  end if;
  if now() < v_res.starts_at - v_leeway
     and not (v_gran in ('half_day','full_day','hours')
              and (v_res.starts_at at time zone v_tz)::date
                  = (now() at time zone v_tz)::date) then
    raise exception 'check-in window not open yet';
  end if;
  if now() >= v_res.ends_at then
    raise exception 'check-in window closed';
  end if;

  -- One place at a time (#412): a forgotten check-out whose own end has
  -- passed completes itself (stamped at its own end, 0075 semantics)...
  update public.reservations
    set status = 'completed', checked_out_at = ends_at
    where member_id = v_res.member_id
      and id <> v_res.id
      and status = 'checked_in'
      and ends_at <= now();
  -- ...but a check-in still RUNNING elsewhere means the member is
  -- physically somewhere else: refuse, check out there first.
  if exists (
    select 1 from public.reservations r
    where r.member_id = v_res.member_id
      and r.id <> v_res.id
      and r.status = 'checked_in'
      and r.ends_at > now()
  ) then
    -- the client pins this substring
    raise exception 'already checked in elsewhere';
  end if;

  perform public.assert_workspace_open(v_res.workspace_id, now(), now() + interval '1 minute');
  update public.reservations
    set status = 'checked_in', checked_in_at = now()
    where id = p_reservation_id;
end;
$$;

-- 5. kiosk_act v5 — the 0085 body with the same-day own-reservation
-- lookup and the canonical walk-up slot.
create or replace function public.kiosk_act(
  p_workspace_id uuid,
  p_badge_token text,
  p_action text,             -- 'reserve' | 'check_in' | 'check_out'
  p_seat_id uuid default null,
  p_starts_at timestamptz default null,
  p_ends_at timestamptz default null,
  p_level_id uuid default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_kiosk public.members;
  v_badge public.member_badges;
  v_subject public.members;
  v_seat public.seats;
  v_office_id uuid;
  v_res public.reservations;
  v_id uuid;
  v_rules jsonb;
  v_tz text;
  v_gran text;
  v_canon timestamptz;
  v_snapped boolean := false;
  v_starts timestamptz;
  v_ends timestamptz;
  v_attempt int;
begin
  select * into v_kiosk from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and is_kiosk;
  if v_kiosk.id is null then raise exception 'not a kiosk of this workspace'; end if;

  select * into v_badge from public.member_badges
    where workspace_id = p_workspace_id
      and token_hash = public.badge_token_hash(p_badge_token)
      and revoked_at is null;
  if v_badge.id is null then
    raise exception 'badge not recognized';
  end if;
  select * into v_subject from public.members
    where id = v_badge.member_id and status = 'active';
  if v_subject.id is null then raise exception 'badge member not active'; end if;

  select w.booking_rules, w.timezone into v_rules, v_tz
    from public.workspaces w where w.id = p_workspace_id;
  v_gran := v_rules->>'granularity';

  if p_action = 'check_out' then
    select r.* into v_res from public.reservations r
      where r.member_id = v_subject.id and r.status = 'checked_in'
        and (p_seat_id is null or r.seat_id = p_seat_id)
        and (p_level_id is null or r.level_id = p_level_id)
      order by r.checked_in_at desc limit 1;
    if v_res.id is null then raise exception 'not checked in'; end if;
    update public.reservations
      set status = 'completed', checked_out_at = now(),
          ends_at = least(ends_at, now())
      where id = v_res.id;
    return jsonb_build_object('action', 'check_out', 'reservation_id', v_res.id);
  end if;

  if p_action not in ('reserve', 'check_in') then
    raise exception 'unknown kiosk action';
  end if;
  if (p_seat_id is null) = (p_level_id is null)
     or p_starts_at is null or p_ends_at is null then
    raise exception 'seat or level, and window required';
  end if;

  v_starts := p_starts_at;
  v_ends := p_ends_at;
  -- #573: a day-based walk-up check-in books the SLOT the chosen end
  -- belongs to — the start snaps back, the member's chosen end stays.
  if p_action = 'check_in' then
    v_canon := public.canonical_walkup_start(
      p_workspace_id, p_starts_at, p_ends_at);
    if v_canon is not null and v_canon < v_starts then
      v_starts := v_canon;
      v_snapped := true;
    end if;
  end if;

  if p_level_id is not null then
    -- Level path: same gates as create_reservation — feature, bookable,
    -- the badge member's personal grant, no conflicts on the level.
    if not public.level_booking_enabled(p_workspace_id) then
      raise exception 'level booking is not enabled';
    end if;
    if not exists (
      select 1 from public.levels l
      where l.id = p_level_id and l.workspace_id = p_workspace_id
        and l.bookable_as_whole
    ) then
      raise exception 'level not bookable as a whole';
    end if;
    if not v_subject.can_reserve_level then
      raise exception 'not allowed to reserve a level';
    end if;

    if p_action = 'check_in' then
      select r.* into v_res from public.reservations r
        where r.member_id = v_subject.id and r.level_id = p_level_id
          and r.status = 'reserved'
          and r.ends_at > now()
          -- #573: the 15-minute leeway (0077/#430) OR the reservation's
          -- own workspace day under day-based/hours granularity — being
          -- early on your own slot's day is presence.
          and (r.starts_at - interval '15 minutes' <= now()
               or (v_gran in ('half_day','full_day','hours')
                   and (r.starts_at at time zone v_tz)::date
                       = (now() at time zone v_tz)::date))
        order by r.starts_at limit 1;
      if v_res.id is not null then
        -- One place (#430, mirroring check_in_reservation): stale
        -- check-ins complete at their own end; still-running elsewhere
        -- refuses with the pinned substring.
        update public.reservations
          set status = 'completed', checked_out_at = ends_at
          where member_id = v_subject.id and id <> v_res.id
            and status = 'checked_in' and ends_at <= now();
        if exists (
          select 1 from public.reservations r2
          where r2.member_id = v_subject.id and r2.id <> v_res.id
            and r2.status = 'checked_in' and r2.ends_at > now()
        ) then
          raise exception 'already checked in elsewhere';
        end if;
        update public.reservations
          set status = 'checked_in', checked_in_at = now()
          where id = v_res.id;
        return jsonb_build_object('action', 'check_in', 'reservation_id', v_res.id);
      end if;
    end if;

    for v_attempt in 1..2 loop
      begin
        perform public.enforce_booking_rules(
          p_workspace_id, v_starts, v_ends, p_action = 'check_in');
        if public.level_has_conflict(p_level_id, v_starts, v_ends) then
          raise exception 'the level has reservations in that period';
        end if;

        insert into public.reservations
          (workspace_id, level_id, member_id, starts_at, ends_at, status, checked_in_at)
        values (
          p_workspace_id, p_level_id, v_subject.id, v_starts, v_ends,
          case when p_action = 'check_in' then 'checked_in' else 'reserved' end,
          case when p_action = 'check_in' then now() end
        )
        returning id into v_id;
        exit;
      exception when others then
        if v_attempt = 1 and v_snapped
           and v_starts < now() and now() < v_ends then
          v_starts := now();
        else
          raise;
        end if;
      end;
    end loop;
    perform public.assert_member_quota(v_subject.id, v_starts);
    return jsonb_build_object('action', p_action, 'reservation_id', v_id);
  end if;

  select * into v_seat from public.seats
    where id = p_seat_id and workspace_id = p_workspace_id;
  if v_seat.id is null then raise exception 'unknown seat'; end if;

  if p_action = 'check_in' then
    select r.* into v_res from public.reservations r
      where r.member_id = v_subject.id and r.seat_id = p_seat_id
        and r.status = 'reserved'
        and r.ends_at > now()
        -- #573: leeway OR same workspace day, as on the level path.
        and (r.starts_at - interval '15 minutes' <= now()
             or (v_gran in ('half_day','full_day','hours')
                 and (r.starts_at at time zone v_tz)::date
                     = (now() at time zone v_tz)::date))
      order by r.starts_at limit 1;
    if v_res.id is not null then
      -- One place (#430): same guards as the level path.
      update public.reservations
        set status = 'completed', checked_out_at = ends_at
        where member_id = v_subject.id and id <> v_res.id
          and status = 'checked_in' and ends_at <= now();
      if exists (
        select 1 from public.reservations r2
        where r2.member_id = v_subject.id and r2.id <> v_res.id
          and r2.status = 'checked_in' and r2.ends_at > now()
      ) then
        raise exception 'already checked in elsewhere';
      end if;
      update public.reservations
        set status = 'checked_in', checked_in_at = now()
        where id = v_res.id;
      return jsonb_build_object('action', 'check_in', 'reservation_id', v_res.id);
    end if;
  end if;

  for v_attempt in 1..2 loop
    begin
      perform public.enforce_booking_rules(
        p_workspace_id, v_starts, v_ends, p_action = 'check_in');
      if tstzrange(coalesce(v_seat.blocked_from, '-infinity'::timestamptz),
                   coalesce(v_seat.blocked_to, 'infinity'::timestamptz))
         && tstzrange(v_starts, v_ends)
         and (v_seat.blocked_from is not null or v_seat.blocked_to is not null) then
        raise exception 'seat is blocked in that period';
      end if;
      -- 0059: the seat's DESK reserved as a whole blocks the walk-up too.
      if exists (
        select 1 from public.reservations r
        where r.desk_id = v_seat.desk_id
          and r.status in ('reserved','checked_in')
          and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
      ) then
        raise exception 'desk is reserved as a whole in that period';
      end if;
      select d.office_id into v_office_id from public.desks d where d.id = v_seat.desk_id;
      if exists (
        select 1 from public.reservations r
        where r.office_id = v_office_id
          and r.status in ('reserved','checked_in')
          and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
      ) then
        raise exception 'office is reserved as a whole in that period';
      end if;
      if exists (
        select 1 from public.reservations r
        where r.level_id = (select o.level_id from public.offices o where o.id = v_office_id)
          and r.status in ('reserved','checked_in')
          and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
      ) then
        raise exception 'level is reserved as a whole in that period';
      end if;

      insert into public.reservations
        (workspace_id, seat_id, member_id, starts_at, ends_at, status, checked_in_at)
      values (
        p_workspace_id, p_seat_id, v_subject.id, v_starts, v_ends,
        case when p_action = 'check_in' then 'checked_in' else 'reserved' end,
        case when p_action = 'check_in' then now() end
      )
      returning id into v_id;
      exit;
    exception when others then
      if v_attempt = 1 and v_snapped
         and v_starts < now() and now() < v_ends then
        v_starts := now();
      else
        raise;
      end if;
    end;
  end loop;
  perform public.assert_member_quota(v_subject.id, v_starts);
  return jsonb_build_object('action', p_action, 'reservation_id', v_id);
end;
$$;

-- 6. update_reservation v2 (#574) — the 0033 body plus the checked-in
-- extension: a RUNNING booking may move its end to a later canonical
-- edge (half day to full day from the seat), never its start. Day-based
-- granularities validate the strict canonical windows (morning to full
-- day IS canonical); grids/hours validate the end against the grid via
-- the walk-up branch, since a walk-up-born start may sit off-grid.
create or replace function public.update_reservation(
  p_reservation_id uuid, p_starts_at timestamptz, p_ends_at timestamptz
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_res public.reservations;
begin
  select r.* into v_res from public.reservations r
    join public.members m on m.id = r.member_id
    where r.id = p_reservation_id and m.user_id = auth.uid();
  if v_res.id is null then raise exception 'not your reservation'; end if;

  if v_res.status = 'checked_in' then
    if p_starts_at <> v_res.starts_at then
      raise exception 'a running booking keeps its start';
    end if;
    if p_ends_at <= now() then
      raise exception 'the new end must lie ahead';
    end if;
    -- Walk-up shape checks: the END must land on a canonical edge /
    -- the grid, the (immovable) start may sit anywhere — a running
    -- booking's start is often the anchored arrival instant.
    perform public.enforce_booking_rules(
      v_res.workspace_id, p_starts_at, p_ends_at, true);
  elsif v_res.status = 'reserved' then
    perform public.enforce_booking_rules(
      v_res.workspace_id, p_starts_at, p_ends_at);
  else
    raise exception 'only upcoming reservations can be edited';
  end if;

  if v_res.seat_id is not null then
    perform public.assert_seat_not_blocked(
      v_res.seat_id, p_starts_at, p_ends_at);
  end if;
  update public.reservations
    set starts_at = p_starts_at, ends_at = p_ends_at
    where id = p_reservation_id;
  perform public.assert_member_quota(v_res.member_id, p_starts_at);
end;
$$;
revoke execute on function public.update_reservation(uuid, timestamptz, timestamptz) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- #600 — reservation/check-in edge fixes + the owner-configurable
-- booking-behavior matrix, driven by a 60-case live-RPC test matrix.
--
-- Defects fixed:
--   1. A check-out BEFORE the reserved slot's start (possible since
--      0113's same-day early check-in) tried to write
--      ends_at = now() < starts_at and died on reservations_time_valid.
--      complete_check_out() now records the REAL presence
--      [checked_in_at, now), floored at one minute — used by both
--      check_out_reservation and kiosk_act.
--   2. validation_policies_event_type_check refused the two event types
--      the validation-settings screen offers cards for
--      (reservation_delete, invoice_writeoff) — widened.
--   3. create_reservation accepted p_check_in for a FUTURE day (a
--      "checked-in" reservation for tomorrow), inconsistent with
--      check_in_reservation's same-day rule — refused now.
--
-- New booking_rules policy keys (defaults keep today's behavior):
--   allow_past_bookings — OFF: fully-past bookings are refused
--                         (they silently succeeded before; a member
--                         could self-create attendance history);
--                         ON restores deliberate backfill.
--   grid_within_hours   — OFF: minute grids stay free-time (0032);
--                         ON confines them to the working day,
--                         overtime walk-ups excepted.
--   admin_check_out     — OFF: check-out stays owner-only; ON lets an
--                         admin check a member out (the #412 overrule
--                         family).

-- 1. The one truthful check-out.
create or replace function public.complete_check_out(p_reservation_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_res public.reservations;
  v_start timestamptz;
  v_end timestamptz;
begin
  select r.* into v_res from public.reservations r
    where r.id = p_reservation_id;
  -- The completed row must describe a real, forward-running presence:
  -- an early same-day check-in (0113) can sit BEFORE starts_at.
  v_start := least(v_res.starts_at, coalesce(v_res.checked_in_at, now()));
  v_end := least(v_res.ends_at, now());
  if v_end <= v_start then v_end := v_start + interval '1 minute'; end if;
  update public.reservations
    set status = 'completed', checked_out_at = now(),
        starts_at = v_start, ends_at = v_end
    where id = p_reservation_id;
end;
$$;
revoke execute on function public.complete_check_out(uuid)
  from public, anon, authenticated;

-- 2. check_out_reservation v2 — helper + the admin_check_out policy.
create or replace function public.check_out_reservation(p_reservation_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_res public.reservations;
  v_own boolean;
  v_rules jsonb;
begin
  select r.* into v_res from public.reservations r
    where r.id = p_reservation_id;
  if v_res.id is null then raise exception 'not your reservation'; end if;
  select exists (
    select 1 from public.members m
    where m.id = v_res.member_id and m.user_id = auth.uid()
  ) into v_own;
  if not v_own then
    -- #600: admins may check a member out only when the owner switched
    -- the admin_check_out policy on.
    select w.booking_rules into v_rules
      from public.workspaces w where w.id = v_res.workspace_id;
    if not (public.is_admin_of(v_res.workspace_id)
            and coalesce(v_rules->>'admin_check_out', 'false') = 'true') then
      raise exception 'not your reservation';
    end if;
  end if;
  if v_res.status <> 'checked_in' then raise exception 'not checked in'; end if;
  perform public.complete_check_out(p_reservation_id);
end;
$$;

-- 3. The validation-policy types the client already offers (#600).
alter table public.validation_policies
  drop constraint validation_policies_event_type_check;
alter table public.validation_policies
  add constraint validation_policies_event_type_check check (
    event_type is null or event_type in (
      'reservation','payment','expense','adjustment','service_charge',
      'quota','role_change','member_join','space_reservation',
      'invoice_payment','reservation_delete','invoice_writeoff'));

-- 4. enforce_booking_rules v6 — the 0113 body + grid_within_hours.
create or replace function public.enforce_booking_rules(
  p_workspace_id uuid, p_starts_at timestamptz, p_ends_at timestamptz,
  p_walk_up boolean default false
) returns void language plpgsql stable security definer set search_path = public as $$
declare rules jsonb; horizon int; min_min int; max_min int; dur int;
        tz text; local_start timestamp; local_end timestamp;
        gran text; slot int;
        ws_start int; ws_bound int; ws_end int;
        d date; ts_start timestamp; ts_bound timestamp; ts_end timestamp;
        ts_midnight timestamp;
begin
  select booking_rules, timezone into rules, tz
    from public.workspaces where id = p_workspace_id;
  horizon := coalesce((rules->>'advance_horizon_days')::int, 90);
  min_min := coalesce((rules->>'min_duration_minutes')::int, 30);
  max_min := coalesce((rules->>'max_duration_minutes')::int, 1440);
  if p_starts_at > now() + make_interval(days => horizon) then
    raise exception 'beyond the advance-booking horizon of % days', horizon;
  end if;
  dur := extract(epoch from (p_ends_at - p_starts_at))::int / 60;
  if dur < min_min then
    raise exception 'below the minimum duration of % minutes', min_min;
  end if;
  if dur > max_min then
    raise exception 'above the maximum duration of % minutes', max_min;
  end if;

  gran := rules->>'granularity';
  local_start := p_starts_at at time zone tz;
  local_end := p_ends_at at time zone tz;

  -- #446: the working day comes from booking_rules (defaults 8:00 /
  -- 12:00 / 17:00 — WorkHours.defaults on the client). An inconsistent
  -- triple falls back to the defaults exactly like the client, so the
  -- constraint and the UI always agree on the canonical windows.
  ws_start := coalesce((rules->>'work_start_minutes')::int, 480);
  ws_bound := coalesce((rules->>'half_boundary_minutes')::int, 720);
  ws_end := coalesce((rules->>'work_end_minutes')::int, 1020);
  if not (ws_start >= 0 and ws_start < ws_bound
          and ws_bound < ws_end and ws_end <= 1440) then
    ws_start := 480; ws_bound := 720; ws_end := 1020;
  end if;
  d := local_start::date;
  ts_start := d::timestamp + make_interval(mins => ws_start);
  ts_bound := d::timestamp + make_interval(mins => ws_bound);
  ts_end := d::timestamp + make_interval(mins => ws_end);
  ts_midnight := d::timestamp + interval '1 day';

  -- Half-day granularity (#200/#201, #446, #573): the three canonical
  -- windows are the CONFIGURED working day. Walk-ups end at a canonical
  -- edge — the boundary or the end of the day — from any earlier start
  -- (#573: a 10:00 arrival checking in for the whole day is a walk-up
  -- ending at the day's end); at or after the end of the working day
  -- they may run to local midnight (overtime, the 0026 behaviour). The
  -- client pins the substring 'half-day' (BookingGranularityError).
  if gran = 'half_day' then
    if p_walk_up then
      if not (
        (local_end = ts_bound and local_start < ts_bound)
        or (local_end = ts_end and local_start < ts_end)
        or (local_start >= ts_end and local_end = ts_midnight)
      ) then
        raise exception 'walk-ups must end at the half-day boundary or the end of the working day';
      end if;
    elsif not (
      (local_start = ts_start and local_end = ts_bound)
      or (local_start = ts_bound and local_end = ts_end)
      or (local_start = ts_start and local_end = ts_end)
    ) then
      raise exception 'bookings must cover a half-day or the full working day';
    end if;

  -- Full-day granularity (0032, #446): exactly the working day. The
  -- client pins the substring 'cover the full day'.
  elsif gran = 'full_day' then
    if not (
      (local_end = ts_end and (p_walk_up or local_start = ts_start))
      or (p_walk_up and local_start >= ts_end and local_end = ts_midnight)
    ) then
      raise exception 'bookings must cover the full day (working hours)';
    end if;

  -- Minute grid (0032): unchanged. 'hours' (#446) deliberately matches
  -- no branch — free from-to times, no grid; billing converts booked
  -- time to half-day equivalents (member_statement v8).
  elsif gran in ('minutes_5','minutes_15','minutes_30','minutes_60') then
    slot := split_part(gran, '_', 2)::int;
    if not (
      extract(second from local_end) = 0
      and extract(minute from local_end)::int % slot = 0
      and (p_walk_up or (
        extract(second from local_start) = 0
        and extract(minute from local_start)::int % slot = 0))
    ) then
      raise exception 'bookings must start and end on the %-minute grid', slot;
    end if;
    -- #600: grids are free-time by design (0032), but the owner may now
    -- confine them to the working day (booking_rules.grid_within_hours).
    -- Overtime walk-ups (at/after the working day's end, until local
    -- midnight) stay allowed — the same escape the day-based modes have.
    if coalesce(rules->>'grid_within_hours', 'false') = 'true'
       and not (p_walk_up and local_start >= ts_end
                and local_end <= ts_midnight)
       and (local_start < ts_start or local_end > ts_end) then
      raise exception 'bookings must stay within the working hours';
    end if;
  end if;

  perform public.assert_workspace_open(p_workspace_id, p_starts_at, p_ends_at);
end;
$$;

-- 5. create_reservation v10 — the 0113 body + the past and
-- walk-up-today guards.
create or replace function public.create_reservation(
  p_workspace_id uuid,
  p_seat_id uuid,
  p_office_id uuid,
  p_starts_at timestamptz,
  p_ends_at timestamptz,
  p_check_in boolean default false,
  p_level_id uuid default null,
  p_desk_id uuid default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_tz text;
  v_rules jsonb;
  v_seat public.seats;
  v_office_id uuid;
  v_level_id uuid;
  v_id uuid;
  v_canon timestamptz;
  v_snapped boolean := false;
  v_starts timestamptz := p_starts_at;
  v_ends timestamptz := p_ends_at;
  v_attempt int;
begin
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  select timezone, booking_rules into v_tz, v_rules
    from public.workspaces where id = p_workspace_id;
  -- #600: a booking on a DAY that already ended (workspace-local) is
  -- refused unless the owner switched allow_past_bookings on
  -- (deliberate backfill). Same-day retro windows stay legal — booking
  -- this morning at 15:00 records same-day attendance, the sweep's own
  -- semantics.
  if ((p_ends_at - interval '1 second') at time zone v_tz)::date
       < (now() at time zone v_tz)::date
     and coalesce(v_rules->>'allow_past_bookings', 'false') <> 'true' then
    raise exception 'the booking lies entirely in the past';
  end if;
  -- #600: a walk-up check-in means "I am here NOW" — its slot must
  -- start on the workspace-local TODAY (check_in_reservation already
  -- refuses other days; creation now mirrors it on every granularity).
  if p_check_in
     and (p_starts_at at time zone v_tz)::date
         <> (now() at time zone v_tz)::date then
    raise exception 'a walk-up check-in must start today';
  end if;
  if (case when p_seat_id is null then 0 else 1 end
      + case when p_desk_id is null then 0 else 1 end
      + case when p_office_id is null then 0 else 1 end
      + case when p_level_id is null then 0 else 1 end) <> 1 then
    raise exception 'exactly one of seat, desk, office or level required';
  end if;

  -- #573: a day-based walk-up check-in books the SLOT the chosen end
  -- belongs to, not the arrival instant — the start snaps BACK to the
  -- slot start, the chosen end stays the member's choice.
  if p_check_in then
    v_canon := public.canonical_walkup_start(
      p_workspace_id, p_starts_at, p_ends_at);
    if v_canon is not null and v_canon < v_starts then
      v_starts := v_canon;
      v_snapped := true;
    end if;
  end if;

  for v_attempt in 1..2 loop
    begin
      perform public.enforce_booking_rules(p_workspace_id, v_starts, v_ends, p_check_in);

      if p_seat_id is not null then
        select * into v_seat from public.seats
          where id = p_seat_id and workspace_id = p_workspace_id;
        if v_seat.id is null then raise exception 'unknown seat'; end if;
        if tstzrange(coalesce(v_seat.blocked_from, '-infinity'::timestamptz),
                     coalesce(v_seat.blocked_to, 'infinity'::timestamptz))
           && tstzrange(v_starts, v_ends)
           and (v_seat.blocked_from is not null or v_seat.blocked_to is not null) then
          raise exception 'seat is blocked in that period';
        end if;
        -- 0059: the seat's DESK reserved as a whole blocks the seat.
        if exists (
          select 1 from public.reservations r
          where r.desk_id = v_seat.desk_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'desk is reserved as a whole in that period';
        end if;
        select d.office_id into v_office_id from public.desks d where d.id = v_seat.desk_id;
        if exists (
          select 1 from public.reservations r
          where r.office_id = v_office_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'office is reserved as a whole in that period';
        end if;
        select o.level_id into v_level_id from public.offices o where o.id = v_office_id;
        if exists (
          select 1 from public.reservations r
          where r.level_id = v_level_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'level is reserved as a whole in that period';
        end if;
      elsif p_desk_id is not null then
        -- Whole-DESK path (0059): the level/office gates, desk-scale.
        if not public.level_booking_enabled(p_workspace_id) then
          raise exception 'level booking is not enabled';
        end if;
        if not (v_member.can_reserve_level or v_member.is_owner
                or v_member.is_admin) then
          -- the client pins this substring (0050)
          raise exception 'not allowed to reserve a level';
        end if;
        if not exists (
          select 1 from public.desks d
          where d.id = p_desk_id and d.workspace_id = p_workspace_id
            and d.bookable_as_whole
        ) then
          raise exception 'desk not bookable as a whole';
        end if;
        if exists (
          select 1 from public.reservations r
          join public.seats s on s.id = r.seat_id
          where s.desk_id = p_desk_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'a seat on this desk is already reserved in that period';
        end if;
        select d.office_id into v_office_id from public.desks d where d.id = p_desk_id;
        if exists (
          select 1 from public.reservations r
          where r.office_id = v_office_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'office is reserved as a whole in that period';
        end if;
        select o.level_id into v_level_id from public.offices o where o.id = v_office_id;
        if exists (
          select 1 from public.reservations r
          where r.level_id = v_level_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'level is reserved as a whole in that period';
        end if;
      elsif p_office_id is not null then
        -- Whole-space gates (0057): feature + personal grant, like levels.
        if not public.level_booking_enabled(p_workspace_id) then
          raise exception 'level booking is not enabled';
        end if;
        if not (v_member.can_reserve_level or v_member.is_owner
                or v_member.is_admin) then
          -- the client pins this substring (0050)
          raise exception 'not allowed to reserve a level';
        end if;
        if not exists (
          select 1 from public.offices o
          where o.id = p_office_id and o.workspace_id = p_workspace_id
            and o.bookable_as_whole
        ) then
          raise exception 'office not bookable as a whole';
        end if;
        if exists (
          select 1 from public.reservations r
          join public.seats s on s.id = r.seat_id
          join public.desks d on d.id = s.desk_id
          where d.office_id = p_office_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'a seat in this office is already reserved in that period';
        end if;
        -- 0059: a desk inside reserved as a whole blocks the office too.
        if exists (
          select 1 from public.reservations r
          join public.desks d on d.id = r.desk_id
          where d.office_id = p_office_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'a desk in this office is already reserved in that period';
        end if;
        select o.level_id into v_level_id from public.offices o where o.id = p_office_id;
        if exists (
          select 1 from public.reservations r
          where r.level_id = v_level_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'level is reserved as a whole in that period';
        end if;
      else
        -- Level path: feature on, level bookable, member personally allowed.
        if not public.level_booking_enabled(p_workspace_id) then
          raise exception 'level booking is not enabled';
        end if;
        if not exists (
          select 1 from public.levels l
          where l.id = p_level_id and l.workspace_id = p_workspace_id
            and l.bookable_as_whole
        ) then
          raise exception 'level not bookable as a whole';
        end if;
        if not (v_member.can_reserve_level or v_member.is_owner
                or v_member.is_admin) then
          -- the client pins this substring
          raise exception 'not allowed to reserve a level';
        end if;
        if public.level_has_conflict(p_level_id, v_starts, v_ends) then
          raise exception 'the level has reservations in that period';
        end if;
      end if;

      insert into public.reservations
        (workspace_id, seat_id, desk_id, office_id, level_id, member_id,
         starts_at, ends_at, status, checked_in_at)
      values (
        p_workspace_id, p_seat_id, p_desk_id, p_office_id, p_level_id,
        v_member.id, v_starts, v_ends,
        case when p_check_in then 'checked_in' else 'reserved' end,
        case when p_check_in then now() end
      )
      returning id into v_id;
      exit; -- validated and inserted — leave the retry loop.
    exception when others then
      -- The one-retry anchor: only a snapped-back walk-up can retry,
      -- and only once — the early slot part was genuinely taken, so
      -- the reservation anchors at now() and keeps the slot's END.
      if v_attempt = 1 and v_snapped
         and v_starts < now() and now() < v_ends then
        v_starts := now();
      else
        raise;
      end if;
    end;
  end loop;

  perform public.assert_member_quota(v_member.id, v_starts);

  -- 0059: whole-space bookings route through the REGULAR validation
  -- feature when the owner configured a rule for them — the reservation
  -- blocks the space immediately, validators confirm or reject (a
  -- reject cancels it via respond_to_event's existing branch).
  if p_desk_id is not null or p_office_id is not null
     or p_level_id is not null then
    if exists (
      select 1 from public.validation_policies vp
      where vp.workspace_id = p_workspace_id
        and vp.event_type = 'space_reservation'
    ) then
      update public.events
        set status = 'pending', type = 'space_reservation'
        where reservation_id = v_id and action = 'created';
    end if;
  end if;
  return v_id;
end;
$$;

-- 6. kiosk_act v6 — the 0113 body, check-out through the helper.
create or replace function public.kiosk_act(
  p_workspace_id uuid,
  p_badge_token text,
  p_action text,             -- 'reserve' | 'check_in' | 'check_out'
  p_seat_id uuid default null,
  p_starts_at timestamptz default null,
  p_ends_at timestamptz default null,
  p_level_id uuid default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_kiosk public.members;
  v_badge public.member_badges;
  v_subject public.members;
  v_seat public.seats;
  v_office_id uuid;
  v_res public.reservations;
  v_id uuid;
  v_rules jsonb;
  v_tz text;
  v_gran text;
  v_canon timestamptz;
  v_snapped boolean := false;
  v_starts timestamptz;
  v_ends timestamptz;
  v_attempt int;
begin
  select * into v_kiosk from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and is_kiosk;
  if v_kiosk.id is null then raise exception 'not a kiosk of this workspace'; end if;

  select * into v_badge from public.member_badges
    where workspace_id = p_workspace_id
      and token_hash = public.badge_token_hash(p_badge_token)
      and revoked_at is null;
  if v_badge.id is null then
    raise exception 'badge not recognized';
  end if;
  select * into v_subject from public.members
    where id = v_badge.member_id and status = 'active';
  if v_subject.id is null then raise exception 'badge member not active'; end if;

  select w.booking_rules, w.timezone into v_rules, v_tz
    from public.workspaces w where w.id = p_workspace_id;
  v_gran := v_rules->>'granularity';

  if p_action = 'check_out' then
    select r.* into v_res from public.reservations r
      where r.member_id = v_subject.id and r.status = 'checked_in'
        and (p_seat_id is null or r.seat_id = p_seat_id)
        and (p_level_id is null or r.level_id = p_level_id)
      order by r.checked_in_at desc limit 1;
    if v_res.id is null then raise exception 'not checked in'; end if;
    perform public.complete_check_out(v_res.id);
    return jsonb_build_object('action', 'check_out', 'reservation_id', v_res.id);
  end if;

  if p_action not in ('reserve', 'check_in') then
    raise exception 'unknown kiosk action';
  end if;
  if (p_seat_id is null) = (p_level_id is null)
     or p_starts_at is null or p_ends_at is null then
    raise exception 'seat or level, and window required';
  end if;

  v_starts := p_starts_at;
  v_ends := p_ends_at;
  -- #573: a day-based walk-up check-in books the SLOT the chosen end
  -- belongs to — the start snaps back, the member's chosen end stays.
  if p_action = 'check_in' then
    v_canon := public.canonical_walkup_start(
      p_workspace_id, p_starts_at, p_ends_at);
    if v_canon is not null and v_canon < v_starts then
      v_starts := v_canon;
      v_snapped := true;
    end if;
  end if;

  if p_level_id is not null then
    -- Level path: same gates as create_reservation — feature, bookable,
    -- the badge member's personal grant, no conflicts on the level.
    if not public.level_booking_enabled(p_workspace_id) then
      raise exception 'level booking is not enabled';
    end if;
    if not exists (
      select 1 from public.levels l
      where l.id = p_level_id and l.workspace_id = p_workspace_id
        and l.bookable_as_whole
    ) then
      raise exception 'level not bookable as a whole';
    end if;
    if not v_subject.can_reserve_level then
      raise exception 'not allowed to reserve a level';
    end if;

    if p_action = 'check_in' then
      select r.* into v_res from public.reservations r
        where r.member_id = v_subject.id and r.level_id = p_level_id
          and r.status = 'reserved'
          and r.ends_at > now()
          -- #573: the 15-minute leeway (0077/#430) OR the reservation's
          -- own workspace day under day-based/hours granularity — being
          -- early on your own slot's day is presence.
          and (r.starts_at - interval '15 minutes' <= now()
               or (v_gran in ('half_day','full_day','hours')
                   and (r.starts_at at time zone v_tz)::date
                       = (now() at time zone v_tz)::date))
        order by r.starts_at limit 1;
      if v_res.id is not null then
        -- One place (#430, mirroring check_in_reservation): stale
        -- check-ins complete at their own end; still-running elsewhere
        -- refuses with the pinned substring.
        update public.reservations
          set status = 'completed', checked_out_at = ends_at
          where member_id = v_subject.id and id <> v_res.id
            and status = 'checked_in' and ends_at <= now();
        if exists (
          select 1 from public.reservations r2
          where r2.member_id = v_subject.id and r2.id <> v_res.id
            and r2.status = 'checked_in' and r2.ends_at > now()
        ) then
          raise exception 'already checked in elsewhere';
        end if;
        update public.reservations
          set status = 'checked_in', checked_in_at = now()
          where id = v_res.id;
        return jsonb_build_object('action', 'check_in', 'reservation_id', v_res.id);
      end if;
    end if;

    for v_attempt in 1..2 loop
      begin
        perform public.enforce_booking_rules(
          p_workspace_id, v_starts, v_ends, p_action = 'check_in');
        if public.level_has_conflict(p_level_id, v_starts, v_ends) then
          raise exception 'the level has reservations in that period';
        end if;

        insert into public.reservations
          (workspace_id, level_id, member_id, starts_at, ends_at, status, checked_in_at)
        values (
          p_workspace_id, p_level_id, v_subject.id, v_starts, v_ends,
          case when p_action = 'check_in' then 'checked_in' else 'reserved' end,
          case when p_action = 'check_in' then now() end
        )
        returning id into v_id;
        exit;
      exception when others then
        if v_attempt = 1 and v_snapped
           and v_starts < now() and now() < v_ends then
          v_starts := now();
        else
          raise;
        end if;
      end;
    end loop;
    perform public.assert_member_quota(v_subject.id, v_starts);
    return jsonb_build_object('action', p_action, 'reservation_id', v_id);
  end if;

  select * into v_seat from public.seats
    where id = p_seat_id and workspace_id = p_workspace_id;
  if v_seat.id is null then raise exception 'unknown seat'; end if;

  if p_action = 'check_in' then
    select r.* into v_res from public.reservations r
      where r.member_id = v_subject.id and r.seat_id = p_seat_id
        and r.status = 'reserved'
        and r.ends_at > now()
        -- #573: leeway OR same workspace day, as on the level path.
        and (r.starts_at - interval '15 minutes' <= now()
             or (v_gran in ('half_day','full_day','hours')
                 and (r.starts_at at time zone v_tz)::date
                     = (now() at time zone v_tz)::date))
      order by r.starts_at limit 1;
    if v_res.id is not null then
      -- One place (#430): same guards as the level path.
      update public.reservations
        set status = 'completed', checked_out_at = ends_at
        where member_id = v_subject.id and id <> v_res.id
          and status = 'checked_in' and ends_at <= now();
      if exists (
        select 1 from public.reservations r2
        where r2.member_id = v_subject.id and r2.id <> v_res.id
          and r2.status = 'checked_in' and r2.ends_at > now()
      ) then
        raise exception 'already checked in elsewhere';
      end if;
      update public.reservations
        set status = 'checked_in', checked_in_at = now()
        where id = v_res.id;
      return jsonb_build_object('action', 'check_in', 'reservation_id', v_res.id);
    end if;
  end if;

  for v_attempt in 1..2 loop
    begin
      perform public.enforce_booking_rules(
        p_workspace_id, v_starts, v_ends, p_action = 'check_in');
      if tstzrange(coalesce(v_seat.blocked_from, '-infinity'::timestamptz),
                   coalesce(v_seat.blocked_to, 'infinity'::timestamptz))
         && tstzrange(v_starts, v_ends)
         and (v_seat.blocked_from is not null or v_seat.blocked_to is not null) then
        raise exception 'seat is blocked in that period';
      end if;
      -- 0059: the seat's DESK reserved as a whole blocks the walk-up too.
      if exists (
        select 1 from public.reservations r
        where r.desk_id = v_seat.desk_id
          and r.status in ('reserved','checked_in')
          and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
      ) then
        raise exception 'desk is reserved as a whole in that period';
      end if;
      select d.office_id into v_office_id from public.desks d where d.id = v_seat.desk_id;
      if exists (
        select 1 from public.reservations r
        where r.office_id = v_office_id
          and r.status in ('reserved','checked_in')
          and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
      ) then
        raise exception 'office is reserved as a whole in that period';
      end if;
      if exists (
        select 1 from public.reservations r
        where r.level_id = (select o.level_id from public.offices o where o.id = v_office_id)
          and r.status in ('reserved','checked_in')
          and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
      ) then
        raise exception 'level is reserved as a whole in that period';
      end if;

      insert into public.reservations
        (workspace_id, seat_id, member_id, starts_at, ends_at, status, checked_in_at)
      values (
        p_workspace_id, p_seat_id, v_subject.id, v_starts, v_ends,
        case when p_action = 'check_in' then 'checked_in' else 'reserved' end,
        case when p_action = 'check_in' then now() end
      )
      returning id into v_id;
      exit;
    exception when others then
      if v_attempt = 1 and v_snapped
         and v_starts < now() and now() < v_ends then
        v_starts := now();
      else
        raise;
      end if;
    end;
  end loop;
  perform public.assert_member_quota(v_subject.id, v_starts);
  return jsonb_build_object('action', p_action, 'reservation_id', v_id);
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- #616 — the kiosk receipt shows the member's own photo: kiosk_identify
-- v2 returns the subject's user_id and whether their profile carries an
-- avatar. The photo itself downloads through the 0038 avatars bucket,
-- whose select policy already admits workspace co-members — the kiosk
-- member included; this only tells the client WHERE to look, and only
-- after the badge resolved.
create or replace function public.kiosk_identify(
  p_workspace_id uuid, p_badge_token text
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_kiosk public.members;
  v_badge public.member_badges;
  v_subject public.members;
  v_name text;
  v_avatar text;
begin
  select * into v_kiosk from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and is_kiosk;
  if v_kiosk.id is null then raise exception 'not a kiosk of this workspace'; end if;

  select * into v_badge from public.member_badges
    where workspace_id = p_workspace_id
      and token_hash = public.badge_token_hash(p_badge_token)
      and revoked_at is null;
  if v_badge.id is null then
    -- the client pins this substring (same as kiosk_act)
    raise exception 'badge not recognized';
  end if;
  select * into v_subject from public.members
    where id = v_badge.member_id and status = 'active';
  if v_subject.id is null then raise exception 'badge member not active'; end if;

  select display_name, avatar_path into v_name, v_avatar
    from public.profiles where id = v_subject.user_id;
  return jsonb_build_object(
    'member_id', v_subject.id,
    'display_name', coalesce(v_name, ''),
    'user_id', v_subject.user_id,
    'has_avatar', coalesce(v_avatar, '') <> ''
  );
end;
$$;
revoke execute on function public.kiosk_identify(uuid, text) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- #624 — the outside-opening-hours booking policy. One booking_rules
-- string key, outside_hours_mode ('off' | 'free' | 'charged', absent =
-- 'charged' — the closest to today's behavior), governing bookings and
-- walk-up check-ins whose window lies ENTIRELY outside the configured
-- working day (the overtime walk-up 17:00→midnight is the canonical
-- case; early mornings before the day start likewise). A window that
-- touches the working hours at all is a REGULAR booking — untouched.
--
--   off     — creating an outside-only booking is refused in
--             enforce_booking_rules v7 (pinned substring 'outside the
--             opening hours') on EVERY granularity, including the
--             previously-always-allowed overtime walk-up midnight
--             windows and out-of-hours grid windows.
--   free    — allowed but NEVER counted: excluded from the
--             assert_member_quota usage and from every member_statement
--             usage/supplement aggregation. The reservation still
--             occupies the space and check-ins work — pure presence.
--   charged — counts like today, EXCEPT when the member holds a regular
--             (inside-hours-overlapping) reservation on the same
--             workspace-local day: then the outside-only booking rides
--             free. Kills the book-only-outside-hours dodge without
--             double-charging a member who already consumed the day.
--
-- ONE predicate — reservation_counts_for_usage — feeds BOTH
-- assert_member_quota v4 AND member_statement v11, so the cap and the
-- bill agree (the #446 doctrine). Bodies are GENERATED from their
-- latest prior definitions (enforce_booking_rules v6: 0116;
-- assert_member_quota v3: 0087; member_statement v10: 0109) with only
-- the #624 lines added.

-- 1. The one definition of "entirely outside the working day": the
-- window intersects NO day's [ws_start, ws_end) among the local days it
-- touches (a window may cross midnight under minute grids).
create or replace function public.window_outside_working_hours(
  p_local_start timestamp, p_local_end timestamp,
  p_ws_start int, p_ws_end int
) returns boolean language sql immutable as $$
  select not exists (
    select 1
    from generate_series(p_local_start::date::timestamp,
                         (p_local_end - interval '1 second')::date::timestamp,
                         interval '1 day') gd
    where p_local_start < gd + make_interval(mins => p_ws_end)
      and p_local_end   > gd + make_interval(mins => p_ws_start)
  );
$$;
revoke execute on function
  public.window_outside_working_hours(timestamp, timestamp, int, int)
  from public, anon, authenticated;

-- 2. THE shared usage predicate: does reservation [r] count toward the
-- quota and the bill? Regular window → yes. Outside-only + mode 'free'
-- → no. Outside-only + mode 'charged' (or absent/unknown) → yes,
-- UNLESS the member holds a regular reservation intersecting the same
-- workspace-local day's working hours. Same fallback triple as
-- enforce_booking_rules (#446), so every reader agrees on the windows.
create or replace function public.reservation_counts_for_usage(
  r public.reservations, rules jsonb, tz text
) returns boolean language plpgsql stable security definer
  set search_path = public as $$
declare
  v_mode text;
  ws_start int; ws_bound int; ws_end int;
  local_start timestamp; local_end timestamp;
  d date;
begin
  v_mode := coalesce(rules->>'outside_hours_mode', 'charged');
  ws_start := coalesce((rules->>'work_start_minutes')::int, 480);
  ws_bound := coalesce((rules->>'half_boundary_minutes')::int, 720);
  ws_end := coalesce((rules->>'work_end_minutes')::int, 1020);
  if not (ws_start >= 0 and ws_start < ws_bound
          and ws_bound < ws_end and ws_end <= 1440) then
    ws_start := 480; ws_bound := 720; ws_end := 1020;
  end if;
  local_start := r.starts_at at time zone tz;
  local_end := r.ends_at at time zone tz;
  if not public.window_outside_working_hours(
           local_start, local_end, ws_start, ws_end) then
    return true; -- regular booking: always counts
  end if;
  if v_mode = 'free' then
    return false; -- pure presence info, never counted
  end if;
  -- 'charged' (and any unknown value, like the absent default): the
  -- outside-only booking rides free only next to a regular reservation
  -- of the same member on the same workspace-local day.
  d := local_start::date;
  return not exists (
    select 1 from public.reservations r2
    where r2.member_id = r.member_id
      and r2.id is distinct from r.id
      and r2.status in ('reserved','checked_in','completed')
      and (r2.starts_at at time zone tz)
            < d::timestamp + make_interval(mins => ws_end)
      and (r2.ends_at at time zone tz)
            > d::timestamp + make_interval(mins => ws_start)
  );
end;
$$;
revoke execute on function
  public.reservation_counts_for_usage(public.reservations, jsonb, text)
  from public, anon, authenticated;

-- 3. enforce_booking_rules v7 — the 0116 v6 body + the 'off' refusal.
create or replace function public.enforce_booking_rules(
  p_workspace_id uuid, p_starts_at timestamptz, p_ends_at timestamptz,
  p_walk_up boolean default false
) returns void language plpgsql stable security definer set search_path = public as $$
declare rules jsonb; horizon int; min_min int; max_min int; dur int;
        tz text; local_start timestamp; local_end timestamp;
        gran text; slot int;
        ws_start int; ws_bound int; ws_end int;
        d date; ts_start timestamp; ts_bound timestamp; ts_end timestamp;
        ts_midnight timestamp;
begin
  select booking_rules, timezone into rules, tz
    from public.workspaces where id = p_workspace_id;
  horizon := coalesce((rules->>'advance_horizon_days')::int, 90);
  min_min := coalesce((rules->>'min_duration_minutes')::int, 30);
  max_min := coalesce((rules->>'max_duration_minutes')::int, 1440);
  if p_starts_at > now() + make_interval(days => horizon) then
    raise exception 'beyond the advance-booking horizon of % days', horizon;
  end if;
  dur := extract(epoch from (p_ends_at - p_starts_at))::int / 60;
  if dur < min_min then
    raise exception 'below the minimum duration of % minutes', min_min;
  end if;
  if dur > max_min then
    raise exception 'above the maximum duration of % minutes', max_min;
  end if;

  gran := rules->>'granularity';
  local_start := p_starts_at at time zone tz;
  local_end := p_ends_at at time zone tz;

  -- #446: the working day comes from booking_rules (defaults 8:00 /
  -- 12:00 / 17:00 — WorkHours.defaults on the client). An inconsistent
  -- triple falls back to the defaults exactly like the client, so the
  -- constraint and the UI always agree on the canonical windows.
  ws_start := coalesce((rules->>'work_start_minutes')::int, 480);
  ws_bound := coalesce((rules->>'half_boundary_minutes')::int, 720);
  ws_end := coalesce((rules->>'work_end_minutes')::int, 1020);
  if not (ws_start >= 0 and ws_start < ws_bound
          and ws_bound < ws_end and ws_end <= 1440) then
    ws_start := 480; ws_bound := 720; ws_end := 1020;
  end if;
  d := local_start::date;
  ts_start := d::timestamp + make_interval(mins => ws_start);
  ts_bound := d::timestamp + make_interval(mins => ws_bound);
  ts_end := d::timestamp + make_interval(mins => ws_end);
  ts_midnight := d::timestamp + interval '1 day';

  -- #624: a window ENTIRELY outside the working day. Mode 'off' refuses
  -- it on EVERY granularity — before the shape arms, so the overtime
  -- walk-up midnight windows (half_day/full_day) and out-of-hours grid
  -- windows all route through this one gate; under 'free'/'charged'
  -- (the absent default) the arms below behave exactly as before. The
  -- client pins the substring 'outside the opening hours'.
  if coalesce(rules->>'outside_hours_mode', 'charged') = 'off'
     and public.window_outside_working_hours(
           local_start, local_end, ws_start, ws_end) then
    raise exception 'bookings outside the opening hours are not allowed';
  end if;

  -- Half-day granularity (#200/#201, #446, #573): the three canonical
  -- windows are the CONFIGURED working day. Walk-ups end at a canonical
  -- edge — the boundary or the end of the day — from any earlier start
  -- (#573: a 10:00 arrival checking in for the whole day is a walk-up
  -- ending at the day's end); at or after the end of the working day
  -- they may run to local midnight (overtime, the 0026 behaviour). The
  -- client pins the substring 'half-day' (BookingGranularityError).
  if gran = 'half_day' then
    if p_walk_up then
      if not (
        (local_end = ts_bound and local_start < ts_bound)
        or (local_end = ts_end and local_start < ts_end)
        or (local_start >= ts_end and local_end = ts_midnight)
      ) then
        raise exception 'walk-ups must end at the half-day boundary or the end of the working day';
      end if;
    elsif not (
      (local_start = ts_start and local_end = ts_bound)
      or (local_start = ts_bound and local_end = ts_end)
      or (local_start = ts_start and local_end = ts_end)
    ) then
      raise exception 'bookings must cover a half-day or the full working day';
    end if;

  -- Full-day granularity (0032, #446): exactly the working day. The
  -- client pins the substring 'cover the full day'.
  elsif gran = 'full_day' then
    if not (
      (local_end = ts_end and (p_walk_up or local_start = ts_start))
      or (p_walk_up and local_start >= ts_end and local_end = ts_midnight)
    ) then
      raise exception 'bookings must cover the full day (working hours)';
    end if;

  -- Minute grid (0032): unchanged. 'hours' (#446) deliberately matches
  -- no branch — free from-to times, no grid; billing converts booked
  -- time to half-day equivalents (member_statement v8).
  elsif gran in ('minutes_5','minutes_15','minutes_30','minutes_60') then
    slot := split_part(gran, '_', 2)::int;
    if not (
      extract(second from local_end) = 0
      and extract(minute from local_end)::int % slot = 0
      and (p_walk_up or (
        extract(second from local_start) = 0
        and extract(minute from local_start)::int % slot = 0))
    ) then
      raise exception 'bookings must start and end on the %-minute grid', slot;
    end if;
    -- #600: grids are free-time by design (0032), but the owner may now
    -- confine them to the working day (booking_rules.grid_within_hours).
    -- Overtime walk-ups (at/after the working day's end, until local
    -- midnight) stay allowed — the same escape the day-based modes have.
    if coalesce(rules->>'grid_within_hours', 'false') = 'true'
       and not (p_walk_up and local_start >= ts_end
                and local_end <= ts_midnight)
       and (local_start < ts_start or local_end > ts_end) then
      raise exception 'bookings must stay within the working hours';
    end if;
  end if;

  perform public.assert_workspace_open(p_workspace_id, p_starts_at, p_ends_at);
end;
$$;

-- 4. assert_member_quota v4 (body from 0087 v3; changes marked #624):
-- both usage counts filter through reservation_counts_for_usage.
create or replace function public.assert_member_quota(
  p_member_id uuid, p_at timestamptz
) returns void language plpgsql stable security definer set search_path = public as $$
declare
  v_member public.members;
  v_tz text;
  v_open int[];
  v_pct int;
  v_period text;
  v_month_first date;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_open_days int;
  v_included int;
  v_ext int;
  v_used int;
  -- #446 working hours
  v_rules jsonb;
  v_gran text;
  v_bound int;
  v_half_minutes numeric;
begin
  select * into v_member from public.members where id = p_member_id;
  select timezone,
         coalesce((select array_agg(x::int)
                     from jsonb_array_elements_text(booking_rules->'open_weekdays') x),
                  array[1,2,3,4,5]),
         booking_rules
    into v_tz, v_open, v_rules
    from public.workspaces where id = v_member.workspace_id;
  -- #446: boundary + hours-mode equivalents, defaults like the client.
  v_gran := v_rules->>'granularity';
  v_bound := coalesce((v_rules->>'half_boundary_minutes')::int, 720);
  if v_bound <= 0 or v_bound >= 1440 then v_bound := 720; end if;
  v_half_minutes := greatest(1, coalesce((v_rules->>'half_day_hours')::int, 4)) * 60.0;

  v_period := to_char(p_at at time zone v_tz, 'YYYY-MM');
  v_month_first := to_date(v_period || '-01', 'YYYY-MM-DD');
  v_period_start := to_timestamp(v_period || '-01', 'YYYY-MM-DD') at time zone v_tz;
  v_period_end := (to_timestamp(v_period || '-01', 'YYYY-MM-DD') + interval '1 month') at time zone v_tz;

  v_pct := coalesce(v_member.subscription_pct, 100);
  select count(*) into v_open_days
  from generate_series(v_month_first,
                       (v_month_first + interval '1 month' - interval '1 day')::date,
                       interval '1 day') d
  where extract(isodow from d)::int = any(v_open)
    and not exists (select 1 from public.closure_days c
                     where c.workspace_id = v_member.workspace_id and c.day = d::date);
  v_included := ceil(v_open_days * 2 * v_pct / 100.0)::int;

  select coalesce(sum(half_days), 0) into v_ext from public.quota_extensions
    where member_id = p_member_id and period = v_period;

  select count(distinct (date_trunc('day', r.starts_at at time zone v_tz)::date, s.slot))
  into v_used
  from public.reservations r
  cross join lateral (
    select case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
           then 0 else 1 end as slot
  ) s
  where r.member_id = p_member_id
    and r.status in ('reserved','checked_in','completed')
    and r.starts_at >= v_period_start and r.starts_at < v_period_end
    -- #624: outside-only bookings may be free or exempt
    and public.reservation_counts_for_usage(r, v_rules, v_tz);

  -- #446 hours granularity: same half-day-equivalent conversion as
  -- member_statement, so the cap and the bill agree.
  if v_gran = 'hours' then
    select coalesce(sum(least(2, greatest(1,
             ceil(d.day_minutes / v_half_minutes)::int))), 0)
    into v_used
    from (
      select date_trunc('day', r.starts_at at time zone v_tz)::date as day,
             sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
               as day_minutes
      from public.reservations r
      where r.member_id = p_member_id
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start and r.starts_at < v_period_end
        -- #624: outside-only bookings may be free or exempt
        and public.reservation_counts_for_usage(r, v_rules, v_tz)
      group by 1
    ) d;
  end if;

  if v_used > v_included + v_ext then
    -- pay-as-you-go members may go over; the overage bills at the band rate
    if coalesce(v_member.overage_policy, 'blocked') = 'payg' then
      return;
    end if;
    -- the client pins the substring 'half-day quota' of this message
    raise exception 'half-day quota exceeded — request additional half-days';
  end if;
end;
$$;
revoke execute on function public.assert_member_quota(uuid, timestamptz) from public, anon, authenticated;
-- 5. member_statement v11 (body from 0109 v10; changes marked #624):
-- every reservation aggregation — usage, accessory, level, office and
-- desk supplements — filters through the SAME predicate. Layout,
-- lines and VAT logic untouched.
create or replace function public.member_statement(
  p_member_id uuid,
  p_period text
) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_member public.members;
  v_caller_is_admin boolean;
  v_band public.fee_bands;
  v_tz text;
  v_open int[];
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_month_first date;
  v_open_days int;
  v_pct int;
  v_included int;
  v_used int;
  v_base int := 0;
  v_overage int := 0;
  v_overage_rate int := 0;
  v_credits int;
  v_extra_half_days int := 0;
  v_supp_on boolean := false;
  v_supp_since timestamptz;
  v_supplement int := 0;
  -- #542: the same supplement broken down by VAT percent — accessories
  -- may carry different rates, and the invoice must tax each slice at
  -- its own rate.
  v_supp_by_rate jsonb := '[]'::jsonb;
  v_acc_default numeric;
  v_granted int := 0;
  v_cap int := 0;
  v_remaining int := 0;
  v_level_supplement int := 0;
  v_office_supplement int := 0;
  -- #desk (0059)
  v_desk_supplement int := 0;
  -- #446 working hours
  v_rules jsonb;
  v_gran text;
  v_bound int;
  v_half_minutes numeric;
begin
  select * into v_member from public.members where id = p_member_id;
  if v_member.id is null then raise exception 'unknown member'; end if;
  v_caller_is_admin := public.is_admin_of(v_member.workspace_id);
  if not v_caller_is_admin and not exists (
    select 1 from public.members m
    where m.id = p_member_id and m.user_id = auth.uid()
  ) then
    raise exception 'not your statement';
  end if;

  select timezone,
         coalesce((select array_agg(x::int)
                     from jsonb_array_elements_text(booking_rules->'open_weekdays') x),
                  array[1,2,3,4,5]),
         coalesce(feature_flags -> 'accessorySupplements' = to_jsonb(true), false),
         accessory_supplements_since,
         booking_rules
    into v_tz, v_open, v_supp_on, v_supp_since, v_rules
    from public.workspaces where id = v_member.workspace_id;
  -- #446: the half-day boundary and the hours-mode billing equivalents
  -- come from booking_rules; inconsistent values fall back to the
  -- defaults exactly like the client (WorkHours.fromRules).
  v_gran := v_rules->>'granularity';
  v_bound := coalesce((v_rules->>'half_boundary_minutes')::int, 720);
  if v_bound <= 0 or v_bound >= 1440 then v_bound := 720; end if;
  v_half_minutes := greatest(1, coalesce((v_rules->>'half_day_hours')::int, 4)) * 60.0;
  v_period_start := to_timestamp(p_period || '-01', 'YYYY-MM-DD') at time zone v_tz;
  v_period_end := (to_timestamp(p_period || '-01', 'YYYY-MM-DD') + interval '1 month') at time zone v_tz;
  v_month_first := to_date(p_period || '-01', 'YYYY-MM-DD');

  -- #512 — a month fully before the membership begins owes NOTHING:
  -- no subscription, no entitlement. The workspace started when it
  -- started; earlier months must not read outstanding.
  if p_period < to_char(v_member.joined_at at time zone v_tz, 'YYYY-MM') then
    return jsonb_build_object(
      'period', p_period,
      'subscription_pct', coalesce(v_member.subscription_pct, 100),
      'fee_cents', 0, 'included_half_days', 0, 'open_days', 0,
      'used_half_days', 0, 'extra_half_days', 0, 'overage_cents', 0,
      'accessory_supplement_cents', 0, 'level_supplement_cents', 0,
      'office_supplement_cents', 0, 'desk_supplement_cents', 0,
      'credits_cents', 0, 'balance_cents', 0,
      'overage_policy', coalesce(v_member.overage_policy, 'blocked'),
      'overage_rate_cents', 0, 'granted_half_days', 0,
      'remaining_half_days', 0
    );
  end if;

  v_pct := coalesce(v_member.subscription_pct, 100);
  select * into v_band from public.fee_bands
    where workspace_id = v_member.workspace_id
      and from_pct < v_pct and v_pct <= to_pct;
  if v_band.id is not null then
    v_base := v_band.fee_cents;
    v_overage_rate := v_band.overage_fee_cents;
  end if;

  select count(*) into v_open_days
  from generate_series(v_month_first,
                       (v_month_first + interval '1 month' - interval '1 day')::date,
                       interval '1 day') d
  where extract(isodow from d)::int = any(v_open)
    and not exists (select 1 from public.closure_days c
                     where c.workspace_id = v_member.workspace_id and c.day = d::date);
  v_included := ceil(v_open_days * 2 * v_pct / 100.0)::int;

  select count(distinct (date_trunc('day', r.starts_at at time zone v_tz)::date, s.slot))
  into v_used
  from public.reservations r
  cross join lateral (
    select case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
           then 0 else 1 end as slot
  ) s
  where r.member_id = p_member_id
    and r.status in ('reserved','checked_in','completed')
    and r.starts_at >= v_period_start and r.starts_at < v_period_end
    -- #624: outside-only bookings may be free or exempt
    and public.reservation_counts_for_usage(r, v_rules, v_tz);

  -- #446 hours granularity: booked time per day converts to half-day
  -- equivalents — one half day per STARTED half_day_hours block,
  -- capped at 2 (a full day is two halves).
  if v_gran = 'hours' then
    select coalesce(sum(least(2, greatest(1,
             ceil(d.day_minutes / v_half_minutes)::int))), 0)
    into v_used
    from (
      select date_trunc('day', r.starts_at at time zone v_tz)::date as day,
             sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
               as day_minutes
      from public.reservations r
      where r.member_id = p_member_id
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start and r.starts_at < v_period_end
        -- #624: outside-only bookings may be free or exempt
        and public.reservation_counts_for_usage(r, v_rules, v_tz)
      group by 1
    ) d;
  end if;

  v_extra_half_days := greatest(0, v_used - v_included);
  v_overage := v_extra_half_days * v_overage_rate;

  select coalesce(sum(half_days), 0) into v_granted from public.quota_extensions
    where member_id = p_member_id and period = p_period;
  v_cap := v_included + v_granted;
  v_remaining := greatest(0, v_cap - v_used);

  if v_supp_on and v_supp_since is not null then
    v_acc_default := public.workspace_default_vat_percent(v_member.workspace_id);
    if v_gran = 'hours' then
      -- #446: half-day-equivalent units per seat and day. #542: seat
      -- totals split by each accessory's VAT percent (its own active
      -- rate, else the workspace default — the services resolution).
      select coalesce(jsonb_agg(jsonb_build_object(
               'percent', pr.percent, 'cents', pr.cents)
               order by pr.percent), '[]'::jsonb),
             coalesce(sum(pr.cents), 0)
      into v_supp_by_rate, v_supplement
      from (
        select rate.percent, sum(rate.unit_cents * hd.units)::int as cents
        from (
          select r.seat_id,
                 least(2, greatest(1, ceil(
                   sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
                     / v_half_minutes)::int)) as units
          from public.reservations r
          where r.member_id = p_member_id
            and r.seat_id is not null
            and r.status in ('reserved','checked_in','completed')
            and r.starts_at >= greatest(v_period_start, v_supp_since)
            and r.starts_at < v_period_end
            -- #624: outside-only bookings may be free or exempt
            and public.reservation_counts_for_usage(r, v_rules, v_tz)
          group by r.seat_id,
                   date_trunc('day', r.starts_at at time zone v_tz)::date
        ) hd
        join (
          select sa.seat_id,
                 coalesce((select vr.percent from public.vat_rates vr
                            where vr.id = a.vat_rate_id and vr.active),
                          v_acc_default) as percent,
                 sum(a.supplement_cents)::int as unit_cents
          from public.seat_accessories sa
          join public.accessories a on a.id = sa.accessory_id
          where a.active and a.supplement_cents > 0
          group by sa.seat_id, 2
        ) rate on rate.seat_id = hd.seat_id
        group by rate.percent
      ) pr;
    else
      select coalesce(jsonb_agg(jsonb_build_object(
               'percent', pr.percent, 'cents', pr.cents)
               order by pr.percent), '[]'::jsonb),
             coalesce(sum(pr.cents), 0)
      into v_supp_by_rate, v_supplement
      from (
        select rate.percent, sum(rate.unit_cents)::int as cents
        from (
          select distinct
            r.seat_id,
            date_trunc('day', r.starts_at at time zone v_tz)::date as day,
            case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                    + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
               then 0 else 1 end as slot
          from public.reservations r
          where r.member_id = p_member_id
            and r.seat_id is not null
            and r.status in ('reserved','checked_in','completed')
            and r.starts_at >= greatest(v_period_start, v_supp_since)
            and r.starts_at < v_period_end
            -- #624: outside-only bookings may be free or exempt
            and public.reservation_counts_for_usage(r, v_rules, v_tz)
        ) hd
        join (
          select sa.seat_id,
                 coalesce((select vr.percent from public.vat_rates vr
                            where vr.id = a.vat_rate_id and vr.active),
                          v_acc_default) as percent,
                 sum(a.supplement_cents)::int as unit_cents
          from public.seat_accessories sa
          join public.accessories a on a.id = sa.accessory_id
          where a.active and a.supplement_cents > 0
          group by sa.seat_id, 2
        ) rate on rate.seat_id = hd.seat_id
        group by rate.percent
      ) pr;
    end if;
  end if;

  if v_gran = 'hours' then
    select coalesce(sum(l.price_cents * hx.units), 0) into v_level_supplement
    from (
      select r.level_id,
             least(2, greatest(1, ceil(
               sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
                 / v_half_minutes)::int)) as units
      from public.reservations r
      where r.member_id = p_member_id
        and r.level_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start
        and r.starts_at < v_period_end
        -- #624: outside-only bookings may be free or exempt
        and public.reservation_counts_for_usage(r, v_rules, v_tz)
      group by r.level_id,
               date_trunc('day', r.starts_at at time zone v_tz)::date
    ) hx
    join public.levels l on l.id = hx.level_id;
  else
    select coalesce(sum(l.price_cents), 0) into v_level_supplement
    from (
      select distinct
        r.level_id,
        date_trunc('day', r.starts_at at time zone v_tz)::date as day,
        case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                  + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
             then 0 else 1 end as slot
      from public.reservations r
      where r.member_id = p_member_id
        and r.level_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start and r.starts_at < v_period_end
        -- #624: outside-only bookings may be free or exempt
        and public.reservation_counts_for_usage(r, v_rules, v_tz)
    ) lh
    join public.levels l on l.id = lh.level_id;
  end if;

  -- #office: price × distinct half-days per reserved office.
  if v_gran = 'hours' then
    select coalesce(sum(o.price_cents * hx.units), 0) into v_office_supplement
    from (
      select r.office_id,
             least(2, greatest(1, ceil(
               sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
                 / v_half_minutes)::int)) as units
      from public.reservations r
      where r.member_id = p_member_id
        and r.office_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start
        and r.starts_at < v_period_end
        -- #624: outside-only bookings may be free or exempt
        and public.reservation_counts_for_usage(r, v_rules, v_tz)
      group by r.office_id,
               date_trunc('day', r.starts_at at time zone v_tz)::date
    ) hx
    join public.offices o on o.id = hx.office_id;
  else
    select coalesce(sum(o.price_cents), 0) into v_office_supplement
    from (
      select distinct
        r.office_id,
        date_trunc('day', r.starts_at at time zone v_tz)::date as day,
        case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                  + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
             then 0 else 1 end as slot
      from public.reservations r
      where r.member_id = p_member_id
        and r.office_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start and r.starts_at < v_period_end
        -- #624: outside-only bookings may be free or exempt
        and public.reservation_counts_for_usage(r, v_rules, v_tz)
    ) oh
    join public.offices o on o.id = oh.office_id;
  end if;

  -- #desk: price × distinct half-days per reserved desk (0059).
  if v_gran = 'hours' then
    select coalesce(sum(d.price_cents * hx.units), 0) into v_desk_supplement
    from (
      select r.desk_id,
             least(2, greatest(1, ceil(
               sum(extract(epoch from (r.ends_at - r.starts_at)) / 60.0)
                 / v_half_minutes)::int)) as units
      from public.reservations r
      where r.member_id = p_member_id
        and r.desk_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start
        and r.starts_at < v_period_end
        -- #624: outside-only bookings may be free or exempt
        and public.reservation_counts_for_usage(r, v_rules, v_tz)
      group by r.desk_id,
               date_trunc('day', r.starts_at at time zone v_tz)::date
    ) hx
    join public.desks d on d.id = hx.desk_id;
  else
    select coalesce(sum(d.price_cents), 0) into v_desk_supplement
    from (
      select distinct
        r.desk_id,
        date_trunc('day', r.starts_at at time zone v_tz)::date as day,
        case when extract(hour from r.starts_at at time zone v_tz)::int * 60
                  + extract(minute from r.starts_at at time zone v_tz)::int < v_bound
             then 0 else 1 end as slot
      from public.reservations r
      where r.member_id = p_member_id
        and r.desk_id is not null
        and r.status in ('reserved','checked_in','completed')
        and r.starts_at >= v_period_start and r.starts_at < v_period_end
        -- #624: outside-only bookings may be free or exempt
        and public.reservation_counts_for_usage(r, v_rules, v_tz)
    ) dh
    join public.desks d on d.id = dh.desk_id;
  end if;

  -- #512 — a credit CONSUMED by an invoice match settled that invoice;
  -- it must not ALSO improve its declared month's balance. Charges and
  -- unconsumed credits stay.
  select coalesce(sum(case when kind = 'credit' then amount_cents else -amount_cents end), 0)
  into v_credits
  from public.ledger_entries le
  where le.member_id = p_member_id and le.period = p_period
    and (le.kind <> 'credit' or not exists (
      select 1 from public.invoice_match_payments jr
      where jr.payment_ledger_id = le.id));

  return jsonb_build_object(
    'period', p_period,
    'subscription_pct', v_pct,
    'fee_cents', v_base,
    'included_half_days', v_included,
    'open_days', v_open_days,
    'used_half_days', v_used,
    'extra_half_days', v_extra_half_days,
    'overage_cents', v_overage,
    'accessory_supplement_cents', v_supplement,
    'accessory_supplement_by_rate', v_supp_by_rate,
    'level_supplement_cents', v_level_supplement,
    -- #office
    'office_supplement_cents', v_office_supplement,
    'desk_supplement_cents', v_desk_supplement,
    'credits_cents', v_credits,
    'balance_cents',
      v_credits - v_base - v_overage - v_supplement - v_level_supplement
        - v_office_supplement - v_desk_supplement,
    'overage_policy', coalesce(v_member.overage_policy, 'blocked'),
    'overage_rate_cents', v_overage_rate,
    'granted_half_days', v_granted,
    'remaining_half_days', v_remaining
  );
end;
$$;
revoke execute on function public.member_statement(uuid, text) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- #628 configurable SIMULTANEOUS reservations + #629 auto-validated
-- delete requests for admins/owners. APPLIED to the hosted reference
-- project and live-verified there.
--
-- ============================ #628 ============================
-- "One place at a time" (#412, migration 0079) was a constant. Three
-- call sites hard-coded it: enforce_one_place (0079/0083),
-- check_in_reservation's still-running-elsewhere guard (v4, 0113) and
-- kiosk_act's twin guards on the level and seat paths (v6, 0116). Some
-- workspaces legitimately want a member to hold two or three places at
-- once (a desk plus a meeting room, a coach plus their room).
--
-- The allowance is now resolved by ONE helper,
-- member_simultaneous_allowance, and all three call sites ask it:
--
--   1. members.max_simultaneous_reservations — the explicit per-member
--      permission (null = follow the workspace), sanity-bounded 1..20,
--      set through set_member_simultaneous_limit, modeled exactly on
--      set_member_reservation_limit (0044): owner/admin of that
--      workspace, never for themselves.
--   2. booking_rules.simultaneous_reservations — the workspace default.
--   3. absent or invalid at both levels → 1, today's behavior EXACTLY:
--      at allowance 1 `count(*) >= 1` is the old `exists` test and
--      every pinned refusal fires on the same input as before.
--
-- The two pinned substrings the client maps
-- ('you already have a reservation in that period',
--  'already checked in elsewhere') are preserved verbatim.
--
-- ============================ #629 ============================
-- validation_policies gains auto_validate_admin / auto_validate_owner
-- (both default false) and request_reservation_deletion v3 settles its
-- own event when the requester's role is auto-validated.
--
-- DESIGN NOTE — READ BEFORE GENERALIZING. This is a DELIBERATE,
-- owner-configured exception to the 0086 rule that nobody validates
-- their own event. Three fences keep it honest:
--   * it is scoped to reservation deletions ONLY — the lookup below
--     reads the workspace's own 'reservation_delete' policy row and
--     deliberately ignores the null fallback row, so switching it on
--     can never spill onto payments, expenses, role changes or joins;
--   * both booleans default FALSE, so nothing changes until an owner
--     turns one on in the validation-rules screen;
--   * the settled event carries payload.auto_validated = true, so the
--     feed and the audit trail can always tell a self-settled deletion
--     from a peer-reviewed one.
-- It must NEVER be generalized silently to other event types. Widening
-- it needs its own issue, its own migration and its own review.
--
-- Bodies are GENERATED from their latest prior definitions with only
-- the patches above:
--   check_in_reservation        v4 → v5   from 0113
--   kiosk_act                   v6 → v7   from 0116
--   request_reservation_deletion v2 → v3  from 0111
--   enforce_one_place           v1 → v2   from 0079 (rewritten: the
--                               exists test becomes a count test)

-- ---------------------------------------------------------------- #628
-- 1. The per-member permission. 1..20 is a sanity fence, not a policy:
-- a workspace wanting more has a data-entry bug, not a use case.
alter table public.members
  add column max_simultaneous_reservations int
  check (max_simultaneous_reservations between 1 and 20);

-- 2. The setter — set_member_reservation_limit (0044) with the column
-- and the bounds swapped, same authorization, same self-service ban.
create or replace function public.set_member_simultaneous_limit(
  p_member_id uuid, p_limit int
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_target public.members;
  v_caller public.members;
begin
  select * into v_target from public.members where id = p_member_id;
  if v_target.id is null then raise exception 'unknown member'; end if;
  select * into v_caller from public.members
    where workspace_id = v_target.workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_caller.id is null then
    raise exception 'not an admin of this workspace';
  end if;
  if v_caller.id = v_target.id then
    -- governance, not self-service: nobody tunes their own allowance
    raise exception 'cannot set your own simultaneous limit';
  end if;
  if p_limit is not null and (p_limit < 1 or p_limit > 20) then
    raise exception 'limit must be between 1 and 20 (or null for the workspace default)';
  end if;
  update public.members set max_simultaneous_reservations = p_limit
    where id = p_member_id;
end;
$$;
revoke execute on function public.set_member_simultaneous_limit(uuid, int)
  from public, anon;

-- 3. THE allowance resolver — the single definition every enforcement
-- site below asks. Member override, else the workspace default, else 1.
-- "Invalid" is generous on purpose: the client writes a jsonb number,
-- but a hand-edited string of digits reads the same, and anything else
-- (null, text, 0, negative, absent) falls back to 1 rather than
-- accidentally opening the workspace up.
create or replace function public.member_simultaneous_allowance(
  p_member_id uuid
) returns int language plpgsql stable security definer
  set search_path = public as $$
declare
  v_override int;
  v_raw text;
  v_ws int;
begin
  select m.max_simultaneous_reservations,
         w.booking_rules->>'simultaneous_reservations'
    into v_override, v_raw
    from public.members m
    join public.workspaces w on w.id = m.workspace_id
   where m.id = p_member_id;
  if v_override is not null then
    return least(greatest(v_override, 1), 20);
  end if;
  if v_raw is not null and trim(v_raw) ~ '^[0-9]+$' then
    v_ws := trim(v_raw)::int;
    if v_ws >= 1 then return least(v_ws, 20); end if;
  end if;
  return 1;
end;
$$;
revoke execute on function public.member_simultaneous_allowance(uuid)
  from public, anon, authenticated;

-- 4. enforce_one_place v2 — the 0079 trigger, counting instead of
-- existence-testing. At allowance 1 the two are the same predicate.
create or replace function public.enforce_one_place()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_allowance int;
  v_overlaps int;
begin
  if new.status in ('reserved', 'checked_in') then
    v_allowance := public.member_simultaneous_allowance(new.member_id);
    select count(*) into v_overlaps from public.reservations r
      where r.member_id = new.member_id
        and r.id <> new.id
        and r.status in ('reserved', 'checked_in')
        and tstzrange(r.starts_at, r.ends_at)
            && tstzrange(new.starts_at, new.ends_at);
    if v_overlaps >= v_allowance then
      -- the client pins the leading substring; the count is context
      raise exception
        'you already have a reservation in that period (at most % at a time)',
        v_allowance;
    end if;
  end if;
  return new;
end;
$$;
revoke execute on function public.enforce_one_place()
  from public, anon, authenticated;

-- 5. check_in_reservation v5 — the 0113 body, the still-running
-- guard counting against the allowance.
create or replace function public.check_in_reservation(p_reservation_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_res public.reservations;
  v_own boolean;
  v_rules jsonb;
  v_tz text;
  v_gran text;
  v_leeway interval := interval '15 minutes';
begin
  select r.* into v_res from public.reservations r
    where r.id = p_reservation_id;
  if v_res.id is null then raise exception 'not your reservation'; end if;

  select exists (
    select 1 from public.members m
    where m.id = v_res.member_id and m.user_id = auth.uid()
  ) into v_own;

  if not v_own then
    -- The authorized-for-others path (0077): admin/owner + the
    -- bookForOthers feature (default ON, so ABSENT counts as ON).
    if not (
      public.is_admin_of(v_res.workspace_id)
      and coalesce((
        select w.feature_flags->'bookForOthers' is distinct from 'false'::jsonb
        from public.workspaces w where w.id = v_res.workspace_id
      ), true)
    ) then
      raise exception 'not your reservation';
    end if;
  end if;

  if v_res.status <> 'reserved' then raise exception 'not in reserved state'; end if;

  -- Presence window (0077 → #573). Day-based and hours granularity: the
  -- slot IS the working day, so any same-workspace-day arrival counts
  -- as presence. Minute grids: the leeway widens to one grid step.
  select w.booking_rules, w.timezone into v_rules, v_tz
    from public.workspaces w where w.id = v_res.workspace_id;
  v_gran := v_rules->>'granularity';
  if v_gran in ('minutes_5','minutes_15','minutes_30','minutes_60') then
    v_leeway := greatest(v_leeway,
      make_interval(mins => split_part(v_gran, '_', 2)::int));
  end if;
  if now() < v_res.starts_at - v_leeway
     and not (v_gran in ('half_day','full_day','hours')
              and (v_res.starts_at at time zone v_tz)::date
                  = (now() at time zone v_tz)::date) then
    raise exception 'check-in window not open yet';
  end if;
  if now() >= v_res.ends_at then
    raise exception 'check-in window closed';
  end if;

  -- One place at a time (#412): a forgotten check-out whose own end has
  -- passed completes itself (stamped at its own end, 0075 semantics)...
  update public.reservations
    set status = 'completed', checked_out_at = ends_at
    where member_id = v_res.member_id
      and id <> v_res.id
      and status = 'checked_in'
      and ends_at <= now();
  -- ...but check-ins still RUNNING elsewhere mean the member is
  -- physically somewhere else. #628: how many "elsewhere" the member
  -- may hold is the configured allowance — at allowance 1 the count
  -- test below IS the historical `exists` test, unchanged.
  if (
    select count(*) from public.reservations r
    where r.member_id = v_res.member_id
      and r.id <> v_res.id
      and r.status = 'checked_in'
      and r.ends_at > now()
  ) >= public.member_simultaneous_allowance(v_res.member_id) then
    -- the client pins this substring
    raise exception 'already checked in elsewhere';
  end if;

  perform public.assert_workspace_open(v_res.workspace_id, now(), now() + interval '1 minute');
  update public.reservations
    set status = 'checked_in', checked_in_at = now()
    where id = p_reservation_id;
end;
$$;

-- 6. kiosk_act v7 — the 0116 body, the same allowance on BOTH the
-- level path and the seat path.
create or replace function public.kiosk_act(
  p_workspace_id uuid,
  p_badge_token text,
  p_action text,             -- 'reserve' | 'check_in' | 'check_out'
  p_seat_id uuid default null,
  p_starts_at timestamptz default null,
  p_ends_at timestamptz default null,
  p_level_id uuid default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_kiosk public.members;
  v_badge public.member_badges;
  v_subject public.members;
  v_seat public.seats;
  v_office_id uuid;
  v_res public.reservations;
  v_id uuid;
  v_rules jsonb;
  v_tz text;
  v_gran text;
  v_canon timestamptz;
  v_snapped boolean := false;
  v_starts timestamptz;
  v_ends timestamptz;
  v_attempt int;
begin
  select * into v_kiosk from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and is_kiosk;
  if v_kiosk.id is null then raise exception 'not a kiosk of this workspace'; end if;

  select * into v_badge from public.member_badges
    where workspace_id = p_workspace_id
      and token_hash = public.badge_token_hash(p_badge_token)
      and revoked_at is null;
  if v_badge.id is null then
    raise exception 'badge not recognized';
  end if;
  select * into v_subject from public.members
    where id = v_badge.member_id and status = 'active';
  if v_subject.id is null then raise exception 'badge member not active'; end if;

  select w.booking_rules, w.timezone into v_rules, v_tz
    from public.workspaces w where w.id = p_workspace_id;
  v_gran := v_rules->>'granularity';

  if p_action = 'check_out' then
    select r.* into v_res from public.reservations r
      where r.member_id = v_subject.id and r.status = 'checked_in'
        and (p_seat_id is null or r.seat_id = p_seat_id)
        and (p_level_id is null or r.level_id = p_level_id)
      order by r.checked_in_at desc limit 1;
    if v_res.id is null then raise exception 'not checked in'; end if;
    perform public.complete_check_out(v_res.id);
    return jsonb_build_object('action', 'check_out', 'reservation_id', v_res.id);
  end if;

  if p_action not in ('reserve', 'check_in') then
    raise exception 'unknown kiosk action';
  end if;
  if (p_seat_id is null) = (p_level_id is null)
     or p_starts_at is null or p_ends_at is null then
    raise exception 'seat or level, and window required';
  end if;

  v_starts := p_starts_at;
  v_ends := p_ends_at;
  -- #573: a day-based walk-up check-in books the SLOT the chosen end
  -- belongs to — the start snaps back, the member's chosen end stays.
  if p_action = 'check_in' then
    v_canon := public.canonical_walkup_start(
      p_workspace_id, p_starts_at, p_ends_at);
    if v_canon is not null and v_canon < v_starts then
      v_starts := v_canon;
      v_snapped := true;
    end if;
  end if;

  if p_level_id is not null then
    -- Level path: same gates as create_reservation — feature, bookable,
    -- the badge member's personal grant, no conflicts on the level.
    if not public.level_booking_enabled(p_workspace_id) then
      raise exception 'level booking is not enabled';
    end if;
    if not exists (
      select 1 from public.levels l
      where l.id = p_level_id and l.workspace_id = p_workspace_id
        and l.bookable_as_whole
    ) then
      raise exception 'level not bookable as a whole';
    end if;
    if not v_subject.can_reserve_level then
      raise exception 'not allowed to reserve a level';
    end if;

    if p_action = 'check_in' then
      select r.* into v_res from public.reservations r
        where r.member_id = v_subject.id and r.level_id = p_level_id
          and r.status = 'reserved'
          and r.ends_at > now()
          -- #573: the 15-minute leeway (0077/#430) OR the reservation's
          -- own workspace day under day-based/hours granularity — being
          -- early on your own slot's day is presence.
          and (r.starts_at - interval '15 minutes' <= now()
               or (v_gran in ('half_day','full_day','hours')
                   and (r.starts_at at time zone v_tz)::date
                       = (now() at time zone v_tz)::date))
        order by r.starts_at limit 1;
      if v_res.id is not null then
        -- One place (#430, mirroring check_in_reservation): stale
        -- check-ins complete at their own end; still-running elsewhere
        -- refuses with the pinned substring once the #628
        -- allowance is reached.
        update public.reservations
          set status = 'completed', checked_out_at = ends_at
          where member_id = v_subject.id and id <> v_res.id
            and status = 'checked_in' and ends_at <= now();
        if (
          select count(*) from public.reservations r2
          where r2.member_id = v_subject.id and r2.id <> v_res.id
            and r2.status = 'checked_in' and r2.ends_at > now()
        ) >= public.member_simultaneous_allowance(v_subject.id) then
          raise exception 'already checked in elsewhere';
        end if;
        update public.reservations
          set status = 'checked_in', checked_in_at = now()
          where id = v_res.id;
        return jsonb_build_object('action', 'check_in', 'reservation_id', v_res.id);
      end if;
    end if;

    for v_attempt in 1..2 loop
      begin
        perform public.enforce_booking_rules(
          p_workspace_id, v_starts, v_ends, p_action = 'check_in');
        if public.level_has_conflict(p_level_id, v_starts, v_ends) then
          raise exception 'the level has reservations in that period';
        end if;

        insert into public.reservations
          (workspace_id, level_id, member_id, starts_at, ends_at, status, checked_in_at)
        values (
          p_workspace_id, p_level_id, v_subject.id, v_starts, v_ends,
          case when p_action = 'check_in' then 'checked_in' else 'reserved' end,
          case when p_action = 'check_in' then now() end
        )
        returning id into v_id;
        exit;
      exception when others then
        if v_attempt = 1 and v_snapped
           and v_starts < now() and now() < v_ends then
          v_starts := now();
        else
          raise;
        end if;
      end;
    end loop;
    perform public.assert_member_quota(v_subject.id, v_starts);
    return jsonb_build_object('action', p_action, 'reservation_id', v_id);
  end if;

  select * into v_seat from public.seats
    where id = p_seat_id and workspace_id = p_workspace_id;
  if v_seat.id is null then raise exception 'unknown seat'; end if;

  if p_action = 'check_in' then
    select r.* into v_res from public.reservations r
      where r.member_id = v_subject.id and r.seat_id = p_seat_id
        and r.status = 'reserved'
        and r.ends_at > now()
        -- #573: leeway OR same workspace day, as on the level path.
        and (r.starts_at - interval '15 minutes' <= now()
             or (v_gran in ('half_day','full_day','hours')
                 and (r.starts_at at time zone v_tz)::date
                     = (now() at time zone v_tz)::date))
      order by r.starts_at limit 1;
    if v_res.id is not null then
      -- One place (#430) + the #628 allowance: same guards as the
      -- level path.
      update public.reservations
        set status = 'completed', checked_out_at = ends_at
        where member_id = v_subject.id and id <> v_res.id
          and status = 'checked_in' and ends_at <= now();
      if (
        select count(*) from public.reservations r2
        where r2.member_id = v_subject.id and r2.id <> v_res.id
          and r2.status = 'checked_in' and r2.ends_at > now()
      ) >= public.member_simultaneous_allowance(v_subject.id) then
        raise exception 'already checked in elsewhere';
      end if;
      update public.reservations
        set status = 'checked_in', checked_in_at = now()
        where id = v_res.id;
      return jsonb_build_object('action', 'check_in', 'reservation_id', v_res.id);
    end if;
  end if;

  for v_attempt in 1..2 loop
    begin
      perform public.enforce_booking_rules(
        p_workspace_id, v_starts, v_ends, p_action = 'check_in');
      if tstzrange(coalesce(v_seat.blocked_from, '-infinity'::timestamptz),
                   coalesce(v_seat.blocked_to, 'infinity'::timestamptz))
         && tstzrange(v_starts, v_ends)
         and (v_seat.blocked_from is not null or v_seat.blocked_to is not null) then
        raise exception 'seat is blocked in that period';
      end if;
      -- 0059: the seat's DESK reserved as a whole blocks the walk-up too.
      if exists (
        select 1 from public.reservations r
        where r.desk_id = v_seat.desk_id
          and r.status in ('reserved','checked_in')
          and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
      ) then
        raise exception 'desk is reserved as a whole in that period';
      end if;
      select d.office_id into v_office_id from public.desks d where d.id = v_seat.desk_id;
      if exists (
        select 1 from public.reservations r
        where r.office_id = v_office_id
          and r.status in ('reserved','checked_in')
          and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
      ) then
        raise exception 'office is reserved as a whole in that period';
      end if;
      if exists (
        select 1 from public.reservations r
        where r.level_id = (select o.level_id from public.offices o where o.id = v_office_id)
          and r.status in ('reserved','checked_in')
          and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
      ) then
        raise exception 'level is reserved as a whole in that period';
      end if;

      insert into public.reservations
        (workspace_id, seat_id, member_id, starts_at, ends_at, status, checked_in_at)
      values (
        p_workspace_id, p_seat_id, v_subject.id, v_starts, v_ends,
        case when p_action = 'check_in' then 'checked_in' else 'reserved' end,
        case when p_action = 'check_in' then now() end
      )
      returning id into v_id;
      exit;
    exception when others then
      if v_attempt = 1 and v_snapped
         and v_starts < now() and now() < v_ends then
        v_starts := now();
      else
        raise;
      end if;
    end;
  end loop;
  perform public.assert_member_quota(v_subject.id, v_starts);
  return jsonb_build_object('action', p_action, 'reservation_id', v_id);
end;
$$;

-- ---------------------------------------------------------------- #629
-- 7. The two auto-validation switches. Both default false: an existing
-- workspace behaves exactly as before this migration.
alter table public.validation_policies
  add column auto_validate_admin boolean not null default false,
  add column auto_validate_owner boolean not null default false;

-- 8. request_reservation_deletion v3 — the 0111 body plus the
-- auto-validation branch. Read the DESIGN NOTE at the top of this file
-- before touching it.
create or replace function public.request_reservation_deletion(
  p_reservation_id uuid, p_reason text default ''
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_res public.reservations;
  v_member public.members;
  v_id uuid;
  v_policy public.validation_policies;
  v_auto boolean := false;
begin
  select * into v_res from public.reservations where id = p_reservation_id;
  if v_res.id is null then raise exception 'unknown reservation'; end if;
  select * into v_member from public.members
    where workspace_id = v_res.workspace_id and user_id = auth.uid()
      and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  if v_res.member_id <> v_member.id then
    raise exception 'only your own reservation';
  end if;
  if v_res.status not in ('reserved','checked_in','completed') then
    raise exception 'nothing to delete';
  end if;
  if v_res.status = 'reserved' and v_res.starts_at > now() then
    raise exception 'cancel directly — this booking has not started';
  end if;
  -- #629 — the owner-configured auto-validation exception, decided
  -- BEFORE the insert. Scoped to the workspace's OWN reservation_delete
  -- policy row: the null fallback row is deliberately NOT consulted, so
  -- the exception can never leak to another event type.
  select * into v_policy from public.validation_policies
    where workspace_id = v_res.workspace_id
      and event_type = 'reservation_delete';
  v_auto := (v_member.is_owner and coalesce(v_policy.auto_validate_owner, false))
         or (v_member.is_admin and coalesce(v_policy.auto_validate_admin, false));

  -- #562: supersede, don't refuse — a fresh PENDING insert re-triggers
  -- the validator notification (an auto-validated request never asks).
  update public.events
     set status = 'expired'
   where type = 'reservation_delete' and status = 'pending'
     and (payload->>'reservation_id')::uuid = p_reservation_id;

  -- Auto-validated requests are born SETTLED. Inserting them pending
  -- and confirming a statement later would emit a real "please
  -- validate" ping (realtime + the pending push mirror) for something
  -- already decided — validators chasing a closed question. The audit
  -- keeps everything that matters: the event, its actor, a system
  -- decision row and the payload flag.
  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id,
     payload, status, decided_at)
  values (
    v_res.workspace_id, 'reservation_delete', 'submitted',
    v_member.id, v_member.id,
    jsonb_build_object(
      'reservation_id', v_res.id,
      'starts_at', v_res.starts_at,
      'ends_at', v_res.ends_at,
      'was_checked_in', v_res.status <> 'reserved',
      'reason', left(coalesce(p_reason, ''), 300)
    ) || case when v_auto
           then jsonb_build_object('auto_validated', true)
           else '{}'::jsonb end,
    case when v_auto then 'confirmed' else 'pending' end,
    case when v_auto then now() end
  )
  returning id into v_id;

  if v_auto then
    -- The 0017 idiom for a decision no human made: member_id null,
    -- decided_by_system true. Attributing it to the requester would
    -- forge exactly the peer review that 0086 forbids — the rule
    -- settled this, not a colleague.
    insert into public.event_decisions
      (event_id, member_id, decision, decided_by_system)
      values (v_id, null, 'accept', true);
    -- Same effect as respond_to_event's reservation_delete confirm
    -- branch (0101): the booking goes away.
    update public.reservations set status = 'cancelled'
      where id = v_res.id
        and status in ('reserved','checked_in','completed');
  end if;
  return v_id;
end;
$$;

revoke execute on function
  public.request_reservation_deletion(uuid, text) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- #634 — ONE outside-hours policy with four mutually exclusive answers
-- to ONE question: what may happen outside the configured working day?
-- NOT YET applied to the hosted reference project — the orchestrator
-- applies it after review.
--
-- Two settings used to answer that question side by side, with
-- different scopes and different verbs:
--   * booking_rules.grid_within_hours (#600, 0116/0118) — a bool INSIDE
--     the minute-grid arm: it refused a grid window starting before the
--     day start or ending after the day end (partial spill included),
--     except the walk-up starting at/after the day end and ending by
--     local midnight. Minute grids only.
--   * booking_rules.outside_hours_mode (#624, 0118) — a gate BEFORE the
--     granularity arms: 'off' refused windows lying ENTIRELY outside the
--     working day, on every granularity.
-- A workspace could therefore display "grids are free-time (book 6:00)"
-- and "outside hours: refused" at the same time.
--
-- The wire key stays outside_hours_mode; it gains a fourth value:
--
--   off         — nothing outside the working day: no booking ahead, no
--                 walk-up, and a window that merely SPILLS past the day
--                 end (or starts before the day start) is refused too.
--                 DELIBERATELY stricter than #624's 'off', which only
--                 caught entirely-outside windows: if the space closes
--                 at 17:00, a booking until 18:00 is not sensible.
--   walkup_only — the spontaneous check-in outside the hours stays
--                 possible, evening overtime to local midnight
--                 included; RESERVING AHEAD outside the hours is
--                 refused, and so are spilling windows. Exactly what
--                 grid_within_hours = true did, generalized to EVERY
--                 granularity.
--   free        — allowed (ahead or walk-up), never counted or charged.
--   charged     — the absent default: allowed and counted, with the
--                 #624 same-day exemption.
--
-- LEGACY MAPPING — no data migration. The effective mode is
--
--   coalesce(rules->>'outside_hours_mode',
--            case when coalesce(rules->>'grid_within_hours', 'false')
--                      = 'true' then 'walkup_only' else 'charged' end)
--
-- resolved ONCE, by the single gate below (the client mirrors it in
-- BookingPolicies.fromRules). An explicit outside_hours_mode always
-- wins; the old key is never written again, only read as a fallback.
--
-- BILLING SCOPE IS UNCHANGED. reservation_counts_for_usage,
-- assert_member_quota and member_statement are NOT touched here: free
-- and exempt treatment stays keyed on ENTIRELY-outside windows
-- (window_outside_working_hours, 0118). Only the ENFORCEMENT gate now
-- also catches SPILL. Say it plainly, because "enforcement catches
-- spill, billing does not" is the kind of asymmetry a later reader
-- calls a bug: a window that touches the working hours at all is an
-- ordinary, fully counted booking — under 'off' and 'walkup_only' such
-- a window is simply never created in the first place, and under
-- 'free'/'charged' it bills exactly as it always did.
--
-- enforce_booking_rules v8 is GENERATED from its latest definition
-- (v7, 0118) with two hunks only: the #624 'off' gate becomes the
-- unified gate, and the #600 grid_within_hours block inside the
-- minute-grid arm is deleted — its behavior now lives in the gate.
-- Every other line (the half-day/full-day/grid shape arms, the horizon
-- and duration guards, assert_workspace_open) is byte-identical.

create or replace function public.enforce_booking_rules(
  p_workspace_id uuid, p_starts_at timestamptz, p_ends_at timestamptz,
  p_walk_up boolean default false
) returns void language plpgsql stable security definer set search_path = public as $$
declare rules jsonb; horizon int; min_min int; max_min int; dur int;
        tz text; local_start timestamp; local_end timestamp;
        gran text; slot int;
        ws_start int; ws_bound int; ws_end int;
        d date; ts_start timestamp; ts_bound timestamp; ts_end timestamp;
        ts_midnight timestamp;
        v_mode text; v_touches_outside boolean; v_spontaneous boolean;
begin
  select booking_rules, timezone into rules, tz
    from public.workspaces where id = p_workspace_id;
  horizon := coalesce((rules->>'advance_horizon_days')::int, 90);
  min_min := coalesce((rules->>'min_duration_minutes')::int, 30);
  max_min := coalesce((rules->>'max_duration_minutes')::int, 1440);
  if p_starts_at > now() + make_interval(days => horizon) then
    raise exception 'beyond the advance-booking horizon of % days', horizon;
  end if;
  dur := extract(epoch from (p_ends_at - p_starts_at))::int / 60;
  if dur < min_min then
    raise exception 'below the minimum duration of % minutes', min_min;
  end if;
  if dur > max_min then
    raise exception 'above the maximum duration of % minutes', max_min;
  end if;

  gran := rules->>'granularity';
  local_start := p_starts_at at time zone tz;
  local_end := p_ends_at at time zone tz;

  -- #446: the working day comes from booking_rules (defaults 8:00 /
  -- 12:00 / 17:00 — WorkHours.defaults on the client). An inconsistent
  -- triple falls back to the defaults exactly like the client, so the
  -- constraint and the UI always agree on the canonical windows.
  ws_start := coalesce((rules->>'work_start_minutes')::int, 480);
  ws_bound := coalesce((rules->>'half_boundary_minutes')::int, 720);
  ws_end := coalesce((rules->>'work_end_minutes')::int, 1020);
  if not (ws_start >= 0 and ws_start < ws_bound
          and ws_bound < ws_end and ws_end <= 1440) then
    ws_start := 480; ws_bound := 720; ws_end := 1020;
  end if;
  d := local_start::date;
  ts_start := d::timestamp + make_interval(mins => ws_start);
  ts_bound := d::timestamp + make_interval(mins => ws_bound);
  ts_end := d::timestamp + make_interval(mins => ws_end);
  ts_midnight := d::timestamp + interval '1 day';

  -- #634: THE outside-hours gate — one resolution, four answers, every
  -- granularity, before the shape arms. The legacy #600 key is read
  -- (never written) as the fallback: grid_within_hours = true IS
  -- 'walkup_only'.
  v_mode := coalesce(
    rules->>'outside_hours_mode',
    case when coalesce(rules->>'grid_within_hours', 'false') = 'true'
         then 'walkup_only' else 'charged' end);
  -- "Touches outside" — the window leaves the working day at either
  -- edge, in workspace-local time. It strictly CONTAINS the 0118
  -- predicate window_outside_working_hours(local_start, local_end,
  -- ws_start, ws_end): a window with no intersection at all is before
  -- ts_start or after ts_end by definition. Enforcement uses the wider
  -- predicate (spill is refused); BILLING keeps the narrow one — see
  -- the header note on that deliberate asymmetry.
  v_touches_outside := local_start < ts_start or local_end > ts_end;
  -- The one spontaneous shape 'walkup_only' still allows: the walk-up
  -- starting at/after the day's end and ending by local midnight —
  -- exactly the escape grid_within_hours had (evening overtime).
  v_spontaneous := p_walk_up and local_start >= ts_end
                   and local_end <= ts_midnight;
  -- The client pins the substring 'outside the opening hours' in BOTH
  -- messages (bookingErrorText); the walkup_only one additionally says
  -- that a spontaneous check-in is still possible.
  if v_mode = 'off' and v_touches_outside then
    raise exception 'bookings outside the opening hours are not allowed';
  elsif v_mode = 'walkup_only' and v_touches_outside
        and not v_spontaneous then
    raise exception 'only spontaneous check-ins are possible outside the opening hours — booking ahead is not';
  end if;

  -- Half-day granularity (#200/#201, #446, #573): the three canonical
  -- windows are the CONFIGURED working day. Walk-ups end at a canonical
  -- edge — the boundary or the end of the day — from any earlier start
  -- (#573: a 10:00 arrival checking in for the whole day is a walk-up
  -- ending at the day's end); at or after the end of the working day
  -- they may run to local midnight (overtime, the 0026 behaviour). The
  -- client pins the substring 'half-day' (BookingGranularityError).
  if gran = 'half_day' then
    if p_walk_up then
      if not (
        (local_end = ts_bound and local_start < ts_bound)
        or (local_end = ts_end and local_start < ts_end)
        or (local_start >= ts_end and local_end = ts_midnight)
      ) then
        raise exception 'walk-ups must end at the half-day boundary or the end of the working day';
      end if;
    elsif not (
      (local_start = ts_start and local_end = ts_bound)
      or (local_start = ts_bound and local_end = ts_end)
      or (local_start = ts_start and local_end = ts_end)
    ) then
      raise exception 'bookings must cover a half-day or the full working day';
    end if;

  -- Full-day granularity (0032, #446): exactly the working day. The
  -- client pins the substring 'cover the full day'.
  elsif gran = 'full_day' then
    if not (
      (local_end = ts_end and (p_walk_up or local_start = ts_start))
      or (p_walk_up and local_start >= ts_end and local_end = ts_midnight)
    ) then
      raise exception 'bookings must cover the full day (working hours)';
    end if;

  -- Minute grid (0032): unchanged. 'hours' (#446) deliberately matches
  -- no branch — free from-to times, no grid; billing converts booked
  -- time to half-day equivalents (member_statement v8).
  elsif gran in ('minutes_5','minutes_15','minutes_30','minutes_60') then
    slot := split_part(gran, '_', 2)::int;
    if not (
      extract(second from local_end) = 0
      and extract(minute from local_end)::int % slot = 0
      and (p_walk_up or (
        extract(second from local_start) = 0
        and extract(minute from local_start)::int % slot = 0))
    ) then
      raise exception 'bookings must start and end on the %-minute grid', slot;
    end if;
  end if;

  perform public.assert_workspace_open(p_workspace_id, p_starts_at, p_ends_at);
end;
$$;

