  -- no branch — free from-to times, no grid; billing converts booked
  -- time to half-day equivalents (member_statement v8).
  elsif gran in ('minutes_5','minutes_15','minutes_30','minutes_60') then
    slot := split_part(gran, '_', 2)::int;
    if not (
      extract(second from local_end) = 0
      and extract(minute from local_end)::int % slot = 0
      and (p_walk_up or (
        extract(second from local_start) = 0
        and extract(minute from local_start)::int % slot = 0))
    ) then
      raise exception 'bookings must start and end on the %-minute grid', slot;
    end if;
  end if;

  perform public.assert_workspace_open(p_workspace_id, p_starts_at, p_ends_at);
end;
$$;

-- 2. create_reservation v11 — the 0116 v10 body with the two guard
-- blocks deleted; enforce_booking_rules enforces them for it now.
create or replace function public.create_reservation(
  p_workspace_id uuid,
  p_seat_id uuid,
  p_office_id uuid,
  p_starts_at timestamptz,
  p_ends_at timestamptz,
  p_check_in boolean default false,
  p_level_id uuid default null,
  p_desk_id uuid default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_tz text;
  v_rules jsonb;
  v_seat public.seats;
  v_office_id uuid;
  v_level_id uuid;
  v_id uuid;
  v_canon timestamptz;
  v_snapped boolean := false;
  v_starts timestamptz := p_starts_at;
  v_ends timestamptz := p_ends_at;
  v_attempt int;
begin
  select * into v_member from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_member.id is null then raise exception 'not an active member'; end if;
  select timezone, booking_rules into v_tz, v_rules
    from public.workspaces where id = p_workspace_id;
  if (case when p_seat_id is null then 0 else 1 end
      + case when p_desk_id is null then 0 else 1 end
      + case when p_office_id is null then 0 else 1 end
      + case when p_level_id is null then 0 else 1 end) <> 1 then
    raise exception 'exactly one of seat, desk, office or level required';
  end if;

  -- #573: a day-based walk-up check-in books the SLOT the chosen end
  -- belongs to, not the arrival instant — the start snaps BACK to the
  -- slot start, the chosen end stays the member's choice.
  if p_check_in then
    v_canon := public.canonical_walkup_start(
      p_workspace_id, p_starts_at, p_ends_at);
    if v_canon is not null and v_canon < v_starts then
      v_starts := v_canon;
      v_snapped := true;
    end if;
  end if;

  for v_attempt in 1..2 loop
    begin
      perform public.enforce_booking_rules(p_workspace_id, v_starts, v_ends, p_check_in);

      if p_seat_id is not null then
        select * into v_seat from public.seats
          where id = p_seat_id and workspace_id = p_workspace_id;
        if v_seat.id is null then raise exception 'unknown seat'; end if;
        if tstzrange(coalesce(v_seat.blocked_from, '-infinity'::timestamptz),
                     coalesce(v_seat.blocked_to, 'infinity'::timestamptz))
           && tstzrange(v_starts, v_ends)
           and (v_seat.blocked_from is not null or v_seat.blocked_to is not null) then
          raise exception 'seat is blocked in that period';
        end if;
        -- 0059: the seat's DESK reserved as a whole blocks the seat.
        if exists (
          select 1 from public.reservations r
          where r.desk_id = v_seat.desk_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'desk is reserved as a whole in that period';
        end if;
        select d.office_id into v_office_id from public.desks d where d.id = v_seat.desk_id;
        if exists (
          select 1 from public.reservations r
          where r.office_id = v_office_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'office is reserved as a whole in that period';
        end if;
        select o.level_id into v_level_id from public.offices o where o.id = v_office_id;
        if exists (
          select 1 from public.reservations r
          where r.level_id = v_level_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'level is reserved as a whole in that period';
        end if;
      elsif p_desk_id is not null then
        -- Whole-DESK path (0059): the level/office gates, desk-scale.
        if not public.level_booking_enabled(p_workspace_id) then
          raise exception 'level booking is not enabled';
        end if;
        if not (v_member.can_reserve_level or v_member.is_owner
                or v_member.is_admin) then
          -- the client pins this substring (0050)
          raise exception 'not allowed to reserve a level';
        end if;
        if not exists (
          select 1 from public.desks d
          where d.id = p_desk_id and d.workspace_id = p_workspace_id
            and d.bookable_as_whole
        ) then
          raise exception 'desk not bookable as a whole';
        end if;
        if exists (
          select 1 from public.reservations r
          join public.seats s on s.id = r.seat_id
          where s.desk_id = p_desk_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'a seat on this desk is already reserved in that period';
        end if;
        select d.office_id into v_office_id from public.desks d where d.id = p_desk_id;
        if exists (
          select 1 from public.reservations r
          where r.office_id = v_office_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'office is reserved as a whole in that period';
        end if;
        select o.level_id into v_level_id from public.offices o where o.id = v_office_id;
        if exists (
          select 1 from public.reservations r
          where r.level_id = v_level_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'level is reserved as a whole in that period';
        end if;
      elsif p_office_id is not null then
        -- Whole-space gates (0057): feature + personal grant, like levels.
        if not public.level_booking_enabled(p_workspace_id) then
          raise exception 'level booking is not enabled';
        end if;
        if not (v_member.can_reserve_level or v_member.is_owner
                or v_member.is_admin) then
          -- the client pins this substring (0050)
          raise exception 'not allowed to reserve a level';
        end if;
        if not exists (
          select 1 from public.offices o
          where o.id = p_office_id and o.workspace_id = p_workspace_id
            and o.bookable_as_whole
        ) then
          raise exception 'office not bookable as a whole';
        end if;
        if exists (
          select 1 from public.reservations r
          join public.seats s on s.id = r.seat_id
          join public.desks d on d.id = s.desk_id
          where d.office_id = p_office_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'a seat in this office is already reserved in that period';
        end if;
        -- 0059: a desk inside reserved as a whole blocks the office too.
        if exists (
          select 1 from public.reservations r
          join public.desks d on d.id = r.desk_id
          where d.office_id = p_office_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'a desk in this office is already reserved in that period';
        end if;
        select o.level_id into v_level_id from public.offices o where o.id = p_office_id;
        if exists (
          select 1 from public.reservations r
          where r.level_id = v_level_id
            and r.status in ('reserved','checked_in')
            and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
        ) then
          raise exception 'level is reserved as a whole in that period';
        end if;
      else
        -- Level path: feature on, level bookable, member personally allowed.
        if not public.level_booking_enabled(p_workspace_id) then
          raise exception 'level booking is not enabled';
        end if;
        if not exists (
          select 1 from public.levels l
          where l.id = p_level_id and l.workspace_id = p_workspace_id
            and l.bookable_as_whole
        ) then
          raise exception 'level not bookable as a whole';
        end if;
        if not (v_member.can_reserve_level or v_member.is_owner
                or v_member.is_admin) then
          -- the client pins this substring
          raise exception 'not allowed to reserve a level';
        end if;
        if public.level_has_conflict(p_level_id, v_starts, v_ends) then
          raise exception 'the level has reservations in that period';
        end if;
      end if;

      insert into public.reservations
        (workspace_id, seat_id, desk_id, office_id, level_id, member_id,
         starts_at, ends_at, status, checked_in_at)
      values (
        p_workspace_id, p_seat_id, p_desk_id, p_office_id, p_level_id,
        v_member.id, v_starts, v_ends,
        case when p_check_in then 'checked_in' else 'reserved' end,
        case when p_check_in then now() end
      )
      returning id into v_id;
      exit; -- validated and inserted — leave the retry loop.
    exception when others then
      -- The one-retry anchor: only a snapped-back walk-up can retry,
      -- and only once — the early slot part was genuinely taken, so
      -- the reservation anchors at now() and keeps the slot's END.
      if v_attempt = 1 and v_snapped
         and v_starts < now() and now() < v_ends then
        v_starts := now();
      else
        raise;
      end if;
    end;
  end loop;

  perform public.assert_member_quota(v_member.id, v_starts);

  -- 0059: whole-space bookings route through the REGULAR validation
  -- feature when the owner configured a rule for them — the reservation
  -- blocks the space immediately, validators confirm or reject (a
  -- reject cancels it via respond_to_event's existing branch).
  if p_desk_id is not null or p_office_id is not null
     or p_level_id is not null then
    if exists (
      select 1 from public.validation_policies vp
      where vp.workspace_id = p_workspace_id
        and vp.event_type = 'space_reservation'
    ) then
      update public.events
        set status = 'pending', type = 'space_reservation'
        where reservation_id = v_id and action = 'created';
    end if;
  end if;
  return v_id;
end;
$$;

-- 3. kiosk_act v8 — the 0119 v7 body with the level grant aligned
-- to create_reservation's (owners and admins may reserve a level).
create or replace function public.kiosk_act(
  p_workspace_id uuid,
  p_badge_token text,
  p_action text,             -- 'reserve' | 'check_in' | 'check_out'
  p_seat_id uuid default null,
  p_starts_at timestamptz default null,
  p_ends_at timestamptz default null,
  p_level_id uuid default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_kiosk public.members;
  v_badge public.member_badges;
  v_subject public.members;
  v_seat public.seats;
  v_office_id uuid;
  v_res public.reservations;
  v_id uuid;
  v_rules jsonb;
  v_tz text;
  v_gran text;
  v_canon timestamptz;
  v_snapped boolean := false;
  v_starts timestamptz;
  v_ends timestamptz;
  v_attempt int;
begin
  select * into v_kiosk from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and is_kiosk;
  if v_kiosk.id is null then raise exception 'not a kiosk of this workspace'; end if;

  select * into v_badge from public.member_badges
    where workspace_id = p_workspace_id
      and token_hash = public.badge_token_hash(p_badge_token)
      and revoked_at is null;
  if v_badge.id is null then
    raise exception 'badge not recognized';
  end if;
  select * into v_subject from public.members
    where id = v_badge.member_id and status = 'active';
  if v_subject.id is null then raise exception 'badge member not active'; end if;

  select w.booking_rules, w.timezone into v_rules, v_tz
    from public.workspaces w where w.id = p_workspace_id;
  v_gran := v_rules->>'granularity';

  if p_action = 'check_out' then
    select r.* into v_res from public.reservations r
      where r.member_id = v_subject.id and r.status = 'checked_in'
        and (p_seat_id is null or r.seat_id = p_seat_id)
        and (p_level_id is null or r.level_id = p_level_id)
      order by r.checked_in_at desc limit 1;
    if v_res.id is null then raise exception 'not checked in'; end if;
    perform public.complete_check_out(v_res.id);
    return jsonb_build_object('action', 'check_out', 'reservation_id', v_res.id);
  end if;

  if p_action not in ('reserve', 'check_in') then
    raise exception 'unknown kiosk action';
  end if;
  if (p_seat_id is null) = (p_level_id is null)
     or p_starts_at is null or p_ends_at is null then
    raise exception 'seat or level, and window required';
  end if;

  v_starts := p_starts_at;
  v_ends := p_ends_at;
  -- #573: a day-based walk-up check-in books the SLOT the chosen end
  -- belongs to — the start snaps back, the member's chosen end stays.
  if p_action = 'check_in' then
    v_canon := public.canonical_walkup_start(
      p_workspace_id, p_starts_at, p_ends_at);
    if v_canon is not null and v_canon < v_starts then
      v_starts := v_canon;
      v_snapped := true;
    end if;
  end if;

  if p_level_id is not null then
    -- Level path: same gates as create_reservation — feature, bookable,
    -- the badge member's personal grant, no conflicts on the level.
    if not public.level_booking_enabled(p_workspace_id) then
      raise exception 'level booking is not enabled';
    end if;
    if not exists (
      select 1 from public.levels l
      where l.id = p_level_id and l.workspace_id = p_workspace_id
        and l.bookable_as_whole
    ) then
      raise exception 'level not bookable as a whole';
    end if;
    if not (v_subject.can_reserve_level or v_subject.is_owner
            or v_subject.is_admin) then
      raise exception 'not allowed to reserve a level';
    end if;

    if p_action = 'check_in' then
      select r.* into v_res from public.reservations r
        where r.member_id = v_subject.id and r.level_id = p_level_id
          and r.status = 'reserved'
          and r.ends_at > now()
          -- #573: the 15-minute leeway (0077/#430) OR the reservation's
          -- own workspace day under day-based/hours granularity — being
          -- early on your own slot's day is presence.
          and (r.starts_at - interval '15 minutes' <= now()
               or (v_gran in ('half_day','full_day','hours')
                   and (r.starts_at at time zone v_tz)::date
                       = (now() at time zone v_tz)::date))
        order by r.starts_at limit 1;
      if v_res.id is not null then
        -- One place (#430, mirroring check_in_reservation): stale
        -- check-ins complete at their own end; still-running elsewhere
        -- refuses with the pinned substring once the #628
        -- allowance is reached.
        update public.reservations
          set status = 'completed', checked_out_at = ends_at
          where member_id = v_subject.id and id <> v_res.id
            and status = 'checked_in' and ends_at <= now();
        if (
          select count(*) from public.reservations r2
          where r2.member_id = v_subject.id and r2.id <> v_res.id
            and r2.status = 'checked_in' and r2.ends_at > now()
        ) >= public.member_simultaneous_allowance(v_subject.id) then
          raise exception 'already checked in elsewhere';
        end if;
        update public.reservations
          set status = 'checked_in', checked_in_at = now()
          where id = v_res.id;
        return jsonb_build_object('action', 'check_in', 'reservation_id', v_res.id);
      end if;
    end if;

    for v_attempt in 1..2 loop
      begin
        perform public.enforce_booking_rules(
          p_workspace_id, v_starts, v_ends, p_action = 'check_in');
        if public.level_has_conflict(p_level_id, v_starts, v_ends) then
          raise exception 'the level has reservations in that period';
        end if;

        insert into public.reservations
          (workspace_id, level_id, member_id, starts_at, ends_at, status, checked_in_at)
        values (
          p_workspace_id, p_level_id, v_subject.id, v_starts, v_ends,
          case when p_action = 'check_in' then 'checked_in' else 'reserved' end,
          case when p_action = 'check_in' then now() end
        )
        returning id into v_id;
        exit;
      exception when others then
        if v_attempt = 1 and v_snapped
           and v_starts < now() and now() < v_ends then
          v_starts := now();
        else
          raise;
        end if;
      end;
    end loop;
    perform public.assert_member_quota(v_subject.id, v_starts);
    return jsonb_build_object('action', p_action, 'reservation_id', v_id);
  end if;

  select * into v_seat from public.seats
    where id = p_seat_id and workspace_id = p_workspace_id;
  if v_seat.id is null then raise exception 'unknown seat'; end if;

  if p_action = 'check_in' then
    select r.* into v_res from public.reservations r
      where r.member_id = v_subject.id and r.seat_id = p_seat_id
        and r.status = 'reserved'
        and r.ends_at > now()
        -- #573: leeway OR same workspace day, as on the level path.
        and (r.starts_at - interval '15 minutes' <= now()
             or (v_gran in ('half_day','full_day','hours')
                 and (r.starts_at at time zone v_tz)::date
                     = (now() at time zone v_tz)::date))
      order by r.starts_at limit 1;
    if v_res.id is not null then
      -- One place (#430) + the #628 allowance: same guards as the
      -- level path.
      update public.reservations
        set status = 'completed', checked_out_at = ends_at
        where member_id = v_subject.id and id <> v_res.id
          and status = 'checked_in' and ends_at <= now();
      if (
        select count(*) from public.reservations r2
        where r2.member_id = v_subject.id and r2.id <> v_res.id
          and r2.status = 'checked_in' and r2.ends_at > now()
      ) >= public.member_simultaneous_allowance(v_subject.id) then
        raise exception 'already checked in elsewhere';
      end if;
      update public.reservations
        set status = 'checked_in', checked_in_at = now()
        where id = v_res.id;
      return jsonb_build_object('action', 'check_in', 'reservation_id', v_res.id);
    end if;
  end if;

  for v_attempt in 1..2 loop
    begin
      perform public.enforce_booking_rules(
        p_workspace_id, v_starts, v_ends, p_action = 'check_in');
      if tstzrange(coalesce(v_seat.blocked_from, '-infinity'::timestamptz),
                   coalesce(v_seat.blocked_to, 'infinity'::timestamptz))
         && tstzrange(v_starts, v_ends)
         and (v_seat.blocked_from is not null or v_seat.blocked_to is not null) then
        raise exception 'seat is blocked in that period';
      end if;
      -- 0059: the seat's DESK reserved as a whole blocks the walk-up too.
      if exists (
        select 1 from public.reservations r
        where r.desk_id = v_seat.desk_id
          and r.status in ('reserved','checked_in')
          and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
      ) then
        raise exception 'desk is reserved as a whole in that period';
      end if;
      select d.office_id into v_office_id from public.desks d where d.id = v_seat.desk_id;
      if exists (
        select 1 from public.reservations r
        where r.office_id = v_office_id
          and r.status in ('reserved','checked_in')
          and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
      ) then
        raise exception 'office is reserved as a whole in that period';
      end if;
      if exists (
        select 1 from public.reservations r
        where r.level_id = (select o.level_id from public.offices o where o.id = v_office_id)
          and r.status in ('reserved','checked_in')
          and tstzrange(r.starts_at, r.ends_at) && tstzrange(v_starts, v_ends)
      ) then
        raise exception 'level is reserved as a whole in that period';
      end if;

      insert into public.reservations
        (workspace_id, seat_id, member_id, starts_at, ends_at, status, checked_in_at)
      values (
        p_workspace_id, p_seat_id, v_subject.id, v_starts, v_ends,
        case when p_action = 'check_in' then 'checked_in' else 'reserved' end,
        case when p_action = 'check_in' then now() end
      )
      returning id into v_id;
      exit;
    exception when others then
      if v_attempt = 1 and v_snapped
         and v_starts < now() and now() < v_ends then
        v_starts := now();
      else
        raise;
      end if;
    end;
  end loop;
  perform public.assert_member_quota(v_subject.id, v_starts);
  return jsonb_build_object('action', p_action, 'reservation_id', v_id);
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- #662 — sign in by scanning an RFID badge: the tag IDENTIFIES, a PIN
-- CONFIRMS. Two steps behind one form; the sequencing is what lets the
-- PIN belong to the user rather than to a workspace, because sign-in
-- happens before anyone knows which workspace is being entered.
--
-- WHY A PIN AT ALL. An RFID UID is not a secret: it is broadcast to any
-- reader a few centimetres away and clonable with hardware costing about
-- thirty euros. Until now that was contained — a badge only worked at a
-- device already authenticated as a workspace kiosk, standing in the
-- space, and only to book. Turning the UID into a login credential would
-- make it a password anyone can copy off a member in a lift and replay
-- from any device, with the member unable to tell. The PIN is what keeps
-- a cloned tag worthless.
--
-- WHAT THIS MIGRATION DOES AND DELIBERATELY DOES NOT DO. It stores the
-- PIN, marks which badges may sign in, and records attempts so the PIN
-- can be rate limited. It does NOT mint sessions: no SQL function here
-- can turn a tag into a login, because a function that could would be
-- one `grant` away from being callable by `anon`. The exchange lives in
-- the `badge-signin` Edge Function under the service role, and the
-- helpers below are REVOKED from public and anon so only it can reach
-- them.

-- ---------------------------------------------------------------- 1
-- A badge is a booking credential until its owner deliberately makes it
-- a sign-in credential. Every badge that exists today keeps exactly the
-- powers it has now.
alter table public.member_badges
  add column if not exists auth_enabled boolean not null default false;

comment on column public.member_badges.auth_enabled is
  '#662 — may this badge be used to SIGN IN (not just to act at a '
  'kiosk)? Default false: enabling it is an explicit act by the badge''s '
  'own member, because it turns a tag into a key.';

-- ---------------------------------------------------------------- 2
-- The PIN lives on the ACCOUNT. Sign-in precedes knowing the workspace,
-- so a per-workspace PIN could not be resolved at the moment it is
-- needed. One PIN therefore covers every space the member belongs to —
-- stated plainly because it is a real consequence: compromise reaches
-- all of them.
--
-- Stored as a bcrypt hash via pgcrypto, never reversible, never returned
-- by any query below. pgcrypto lives in the `extensions` schema on this
-- project, and every function here pins `search_path = public`, so the
-- calls are SCHEMA-QUALIFIED: `extensions.crypt(...)`. An unqualified
-- call parses fine and fails at RUN time — the DDL applies, and the
-- first real sign-in is what discovers it.
alter table public.profiles
  add column if not exists pin_hash text not null default '',
  add column if not exists pin_set_at timestamptz;

comment on column public.profiles.pin_hash is
  '#662 — bcrypt hash of the badge sign-in PIN, or empty when unset. '
  'Never selected by any client-facing function.';

-- ---------------------------------------------------------------- 3
-- Attempts, so a four-digit PIN cannot simply be enumerated: ~5 000
-- tries would otherwise walk the space. Keyed on the BADGE rather than
-- the account, because the attacker holds a tag, not an e-mail.
create table if not exists public.badge_auth_attempts (
  id uuid primary key default gen_random_uuid(),
  token_hash text not null,
  succeeded boolean not null,
  attempted_at timestamptz not null default now()
);

create index if not exists badge_auth_attempts_recent
  on public.badge_auth_attempts (token_hash, attempted_at desc);

-- Deny-all: the attempt log is an attack signal, and reading it would
-- tell an attacker which tags exist. Only the service role touches it.
alter table public.badge_auth_attempts enable row level security;

-- ---------------------------------------------------------------- 4
-- The member's own PIN management. `security definer` so the write
-- reaches profiles.pin_hash, which no RLS policy exposes; scoped hard to
-- auth.uid() so it can only ever set the caller's own.
create or replace function public.set_badge_pin(p_pin text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    raise exception 'not signed in';
  end if;
  -- 4 to 8 digits. Short enough to type at a door, long enough that the
  -- lockout below does the rest of the work.
  if p_pin !~ '^[0-9]{4,8}$' then
    -- the client pins this substring
    raise exception 'the PIN must be 4 to 8 digits';
  end if;
  -- Reject the sequences people reach for first; a lockout protects a
  -- guessed PIN, but not one an attacker tries FIRST.
  if p_pin in ('0000','1111','2222','3333','4444','5555','6666','7777',
               '8888','9999','1234','12345','123456','1234567','12345678',
               '4321','0123') then
    -- the client pins this substring
    raise exception 'that PIN is too easy to guess';
  end if;
  update public.profiles
     set pin_hash = extensions.crypt(p_pin, extensions.gen_salt('bf', 10)),
         pin_set_at = now()
   where id = auth.uid();
end;
$$;

create or replace function public.clear_badge_pin()
returns void language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  update public.profiles
     set pin_hash = '', pin_set_at = null
   where id = auth.uid();
  -- Without a PIN nothing may sign in with a tag: clearing the PIN
  -- disarms every badge at once, which is the behaviour someone
  -- clearing it expects.
  update public.member_badges b
     set auth_enabled = false
    from public.members m
   where b.member_id = m.id and m.user_id = auth.uid()
     and b.auth_enabled;
end;
$$;

-- Whether the CALLER has a PIN — a boolean, never the hash. The settings
-- screen needs to say "set" or "not set" without ever reading it.
create or replace function public.has_badge_pin()
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select pin_hash <> '' from public.profiles
                    where id = auth.uid()), false);
$$;

-- Arm or disarm ONE of the caller's own badges. A member may only ever
-- reach a badge that belongs to a membership of theirs.
create or replace function public.set_badge_auth_enabled(
  p_badge_id uuid, p_enabled boolean
) returns void language plpgsql security definer set search_path = public as $$
declare v_owned boolean;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select exists (
    select 1 from public.member_badges b
    join public.members m on m.id = b.member_id
    where b.id = p_badge_id and m.user_id = auth.uid()
      and b.revoked_at is null
  ) into v_owned;
  if not v_owned then raise exception 'not your badge'; end if;
  -- Arming a badge without a PIN would be exactly the "UID is the
  -- password" design this feature exists to avoid.
  if p_enabled and not public.has_badge_pin() then
    -- the client pins this substring
    raise exception 'set a PIN before a badge can sign you in';
  end if;
  update public.member_badges
     set auth_enabled = p_enabled
   where id = p_badge_id;
end;
$$;

revoke execute on function public.set_badge_pin(text) from public, anon;
revoke execute on function public.clear_badge_pin() from public, anon;
revoke execute on function public.has_badge_pin() from public, anon;
revoke execute on function public.set_badge_auth_enabled(uuid, boolean)
  from public, anon;

-- ---------------------------------------------------------------- 5
-- THE verification, for the Edge Function alone.
--
-- One function does identify AND verify so the two can never drift
-- apart, and so the attempt is recorded on the same code path that
-- decides. It returns a uniform failure — unknown tag, disarmed badge,
-- wrong PIN and lockout are indistinguishable to the caller — because
-- telling them apart is how an attacker learns which tags are real.
--
-- p_pin null = the IDENTIFY step: it resolves who the tag belongs to
-- WITHOUT consuming an attempt, so a member fumbling their PIN is not
-- locked out by the scan itself. It reveals a display name and whether
-- an avatar exists; deliberately never an e-mail.
create or replace function public.badge_auth_verify(
  p_uid text, p_pin text default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_hash text;
  v_badge public.member_badges;
  v_member public.members;
  v_profile public.profiles;
  v_recent int;
begin
  v_hash := public.badge_token_hash(p_uid);

  select * into v_badge from public.member_badges
   where token_hash = v_hash and revoked_at is null and auth_enabled
   order by created_at limit 1;

  -- Lockout is checked BEFORE the PIN, and on the tag alone, so an
  -- attacker cannot use the response time or shape to tell a real tag
  -- from a fake one.
  select count(*) into v_recent from public.badge_auth_attempts
   where token_hash = v_hash
     and not succeeded
     and attempted_at > now() - interval '15 minutes';
  if v_recent >= 5 then
    return jsonb_build_object('ok', false, 'reason', 'locked');
  end if;

  if v_badge.id is null then
    if p_pin is not null then
      insert into public.badge_auth_attempts (token_hash, succeeded)
        values (v_hash, false);
    end if;
    return jsonb_build_object('ok', false, 'reason', 'refused');
  end if;

  select * into v_member from public.members
   where id = v_badge.member_id and status = 'active';
  if v_member.id is null then
    if p_pin is not null then
      insert into public.badge_auth_attempts (token_hash, succeeded)
        values (v_hash, false);
    end if;
    return jsonb_build_object('ok', false, 'reason', 'refused');
  end if;

  select * into v_profile from public.profiles where id = v_member.user_id;

  -- IDENTIFY: who is this? No attempt consumed, no e-mail returned.
  if p_pin is null then
    return jsonb_build_object(
      'ok', true,
      'user_id', v_member.user_id,
      'display_name', coalesce(v_profile.display_name, ''),
      'has_avatar', coalesce(v_profile.avatar_path, '') <> ''
    );
  end if;

  -- AUTHENTICATE. A profile with no PIN can never match, whatever is
  -- presented: crypt('', '') is not a valid hash and `= ''` would let an
  -- empty PIN through.
  if coalesce(v_profile.pin_hash, '') = ''
     or v_profile.pin_hash <> extensions.crypt(p_pin, v_profile.pin_hash) then
    insert into public.badge_auth_attempts (token_hash, succeeded)
      values (v_hash, false);
    return jsonb_build_object('ok', false, 'reason', 'refused');
  end if;

  insert into public.badge_auth_attempts (token_hash, succeeded)
    values (v_hash, true);
  return jsonb_build_object('ok', true, 'user_id', v_member.user_id);
end;
$$;

-- The Edge Function calls this as the service role. Nobody else may:
-- reaching it directly would hand out a "does this tag exist" oracle,
-- and — with a PIN — the ability to brute force one outside any client.
revoke execute on function public.badge_auth_verify(text, text)
  from public, anon, authenticated;

-- ...but the Edge Function DOES need it, and `revoke ... from public`
-- strips the grant `service_role` inherits through PUBLIC as well. Found
-- the hard way: without this line the function refused every badge,
-- including valid ones, with the same `refused` a stranger gets — the
-- uniform failure shape that protects members also hid this bug.
grant execute on function public.badge_auth_verify(text, text)
  to service_role;

-- PostgREST caches the schema; without this the new functions are
-- invisible until the next pool recycle.
notify pgrst, 'reload schema';

-- SPDX-License-Identifier: 0BSD
-- 0124 — badge sign-in obeys the workspace's own feature flag (#662).
--
-- THE PROBLEM THE CLIENT CANNOT SOLVE. Every other feature flag is
-- checked in the app: the widget asks `enabledFeatures` and hides
-- itself. That does not work here, because the gate has to be decided
-- BEFORE anyone is signed in — and before sign-in the app has no
-- workspace, so it has no flags. `enabledFeatures` falls back to the
-- registry defaults with no workspace, which would make the decision on
-- behalf of a workspace it has never read.
--
-- Only the server can answer, and only after the scan: the badge is
-- what names the workspace. So the flag is enforced here, and the
-- login button on the auth screen is just an affordance — a workspace
-- that has not opted in refuses at the badge, and the refusal is the
-- same `refused` a stranger's card gets.
--
-- Default OFF, matching the registry: a workspace opts IN to its shared
-- tablet becoming a login surface. `coalesce(... , false)` is what makes
-- a workspace that has never heard of the flag refuse rather than allow,
-- which is the right way round for a credential.

create or replace function public.badge_auth_verify(
  p_uid text, p_pin text default null
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_hash text;
  v_badge public.member_badges;
  v_member public.members;
  v_profile public.profiles;
  v_enabled boolean;
  v_recent int;
begin
  v_hash := public.badge_token_hash(p_uid);

  select * into v_badge from public.member_badges
   where token_hash = v_hash and revoked_at is null and auth_enabled
   order by created_at limit 1;

  -- Lockout is checked BEFORE the PIN, and on the tag alone, so an
  -- attacker cannot use the response time or shape to tell a real tag
  -- from a fake one.
  select count(*) into v_recent from public.badge_auth_attempts
   where token_hash = v_hash
     and not succeeded
     and attempted_at > now() - interval '15 minutes';
  if v_recent >= 5 then
    return jsonb_build_object('ok', false, 'reason', 'locked');
  end if;

  if v_badge.id is null then
    if p_pin is not null then
      insert into public.badge_auth_attempts (token_hash, succeeded)
        values (v_hash, false);
    end if;
    return jsonb_build_object('ok', false, 'reason', 'refused');
  end if;

  select * into v_member from public.members
   where id = v_badge.member_id and status = 'active';
  if v_member.id is null then
    if p_pin is not null then
      insert into public.badge_auth_attempts (token_hash, succeeded)
        values (v_hash, false);
    end if;
    return jsonb_build_object('ok', false, 'reason', 'refused');
  end if;

  -- THE FLAG. Checked on the workspace the BADGE belongs to, not on any
  -- workspace the caller claims — the caller is anonymous here and has
  -- nothing to claim with. Both parents must be on: `badgeSignIn` sits
  -- under `nfcBadges` in the registry, and a hierarchy the client
  -- enforces but the server ignores is not a hierarchy.
  select coalesce(w.feature_flags -> 'badgeSignIn' = to_jsonb(true), false)
     and coalesce(w.feature_flags -> 'nfcBadges' = to_jsonb(true), true)
     and coalesce(w.feature_flags -> 'kioskMode' = to_jsonb(true), true)
    into v_enabled
    from public.workspaces w
   where w.id = v_member.workspace_id;

  if not coalesce(v_enabled, false) then
    -- Deliberately the same shape and the same attempt row as a wrong
    -- PIN. A distinct answer here would tell whoever is holding a card
    -- that the card is REAL and only the workspace setting is in the
    -- way, which is exactly what the uniform refusal exists to withhold.
    if p_pin is not null then
      insert into public.badge_auth_attempts (token_hash, succeeded)
        values (v_hash, false);
    end if;
    return jsonb_build_object('ok', false, 'reason', 'refused');
  end if;

  select * into v_profile from public.profiles where id = v_member.user_id;

  -- IDENTIFY: who is this? No attempt consumed, no e-mail returned.
  if p_pin is null then
    return jsonb_build_object(
      'ok', true,
      'user_id', v_member.user_id,
      'display_name', coalesce(v_profile.display_name, ''),
      'has_avatar', coalesce(v_profile.avatar_path, '') <> ''
    );
  end if;

  -- AUTHENTICATE. A profile with no PIN can never match, whatever is
  -- presented: crypt('', '') is not a valid hash and `= ''` would let an
  -- empty PIN through.
  if coalesce(v_profile.pin_hash, '') = ''
     or v_profile.pin_hash <> extensions.crypt(p_pin, v_profile.pin_hash) then
    insert into public.badge_auth_attempts (token_hash, succeeded)
      values (v_hash, false);
    return jsonb_build_object('ok', false, 'reason', 'refused');
  end if;

  insert into public.badge_auth_attempts (token_hash, succeeded)
    values (v_hash, true);
  return jsonb_build_object('ok', true, 'user_id', v_member.user_id);
end;
$$;

revoke execute on function public.badge_auth_verify(text, text)
  from public, anon, authenticated;
grant execute on function public.badge_auth_verify(text, text)
  to service_role;

notify pgrst, 'reload schema';

-- SPDX-License-Identifier: 0BSD
-- 0126 — the conversation write path and the list query (#687).
--
-- Every mutation is an RPC because the rules are not expressible as row
-- policies without repeating them: "only a group admin may add someone",
-- "a direct thread has exactly two participants and is created on
-- demand", "you may only leave a group you are in". A client that could
-- INSERT into conversation_participants directly would be one bug away
-- from adding itself to someone else's group.

-- ---------------------------------------------------------------- 1
-- My active membership in a workspace, or an exception. Every RPC below
-- starts here, so the check is written once.

create or replace function public.my_active_member(p_workspace_id uuid)
returns public.members language plpgsql stable security definer
set search_path = public as $$
declare v_member public.members;
begin
  select * into v_member from public.members
   where workspace_id = p_workspace_id
     and user_id = auth.uid()
     and status = 'active';
  if v_member.id is null then
    raise exception 'not a member of this workspace';
  end if;
  return v_member;
end;
$$;

-- ---------------------------------------------------------------- 2
-- The direct thread with one other member, created if it does not exist.
--
-- Idempotent by construction: two people opening each other at the same
-- moment must not end up with two threads, so the lookup is by the
-- PARTICIPANT PAIR rather than by anything a client passes in.

create or replace function public.direct_conversation(
  p_workspace_id uuid, p_other_member_id uuid
) returns uuid language plpgsql security definer
set search_path = public as $$
declare
  v_me public.members;
  v_other public.members;
  v_id uuid;
begin
  v_me := public.my_active_member(p_workspace_id);
  if p_other_member_id = v_me.id then
    raise exception 'cannot open a thread with yourself';
  end if;
  select * into v_other from public.members
   where id = p_other_member_id
     and workspace_id = p_workspace_id
     and status = 'active';
  if v_other.id is null then raise exception 'no such member'; end if;

  -- Exactly two participants, both of them these two.
  select c.id into v_id
    from public.conversations c
   where c.workspace_id = p_workspace_id
     and c.kind = 'direct'
     and (select count(*) from public.conversation_participants p
           where p.conversation_id = c.id) = 2
     and exists (select 1 from public.conversation_participants p
                  where p.conversation_id = c.id and p.member_id = v_me.id)
     and exists (select 1 from public.conversation_participants p
                  where p.conversation_id = c.id
                    and p.member_id = p_other_member_id)
   limit 1;
  if v_id is not null then return v_id; end if;

  insert into public.conversations (workspace_id, kind, created_by)
    values (p_workspace_id, 'direct', v_me.id)
    returning id into v_id;
  insert into public.conversation_participants (conversation_id, member_id)
    values (v_id, v_me.id), (v_id, p_other_member_id);
  return v_id;
end;
$$;

-- ---------------------------------------------------------------- 3
-- Create a group. The creator is its first admin.

create or replace function public.create_group_conversation(
  p_workspace_id uuid, p_title text, p_member_ids uuid[]
) returns uuid language plpgsql security definer
set search_path = public as $$
declare
  v_me public.members;
  v_id uuid;
  v_member uuid;
begin
  v_me := public.my_active_member(p_workspace_id);
  if length(btrim(coalesce(p_title, ''))) = 0 then
    raise exception 'a group needs a name';
  end if;

  insert into public.conversations (workspace_id, kind, title, created_by)
    values (p_workspace_id, 'group', btrim(p_title), v_me.id)
    returning id into v_id;
  insert into public.conversation_participants
    (conversation_id, member_id, is_admin)
    values (v_id, v_me.id, true);

  -- Silently skips anyone who is not an active member of THIS workspace,
  -- rather than failing the whole call: a stale picker entry should not
  -- lose the group someone just named.
  foreach v_member in array coalesce(p_member_ids, '{}')
  loop
    if v_member <> v_me.id and exists (
      select 1 from public.members
       where id = v_member and workspace_id = p_workspace_id
         and status = 'active'
    ) then
      insert into public.conversation_participants (conversation_id, member_id)
        values (v_id, v_member)
        on conflict do nothing;
    end if;
  end loop;
  return v_id;
end;
$$;

-- ---------------------------------------------------------------- 4
-- Am I an admin of this group?

create or replace function public.is_conversation_admin(p_conversation_id uuid)
returns boolean language sql stable security definer
set search_path = public as $$
  select exists (
    select 1
      from public.conversation_participants p
      join public.members m on m.id = p.member_id
     where p.conversation_id = p_conversation_id
       and m.user_id = auth.uid()
       and m.status = 'active'
       and p.left_at is null
       and p.is_admin
  );
$$;

-- ---------------------------------------------------------------- 5
-- Roster changes.

create or replace function public.add_conversation_participant(
  p_conversation_id uuid, p_member_id uuid
) returns void language plpgsql security definer
set search_path = public as $$
declare v_conversation public.conversations;
begin
  select * into v_conversation from public.conversations
   where id = p_conversation_id;
  if v_conversation.id is null then raise exception 'no such conversation'; end if;
  if v_conversation.kind <> 'group' then
    raise exception 'a direct thread has exactly two people';
  end if;
  if not public.is_conversation_admin(p_conversation_id) then
    raise exception 'only a group admin can add people';
  end if;
  if not exists (
    select 1 from public.members
     where id = p_member_id
       and workspace_id = v_conversation.workspace_id
       and status = 'active'
  ) then
    raise exception 'no such member';
  end if;
  -- Re-adding someone who left clears their exit rather than making a
  -- second row: they get the group back, history included.
  insert into public.conversation_participants (conversation_id, member_id)
    values (p_conversation_id, p_member_id)
    on conflict (conversation_id, member_id)
      do update set left_at = null;
end;
$$;

create or replace function public.remove_conversation_participant(
  p_conversation_id uuid, p_member_id uuid
) returns void language plpgsql security definer
set search_path = public as $$
declare v_me public.members;
begin
  if not public.is_conversation_admin(p_conversation_id) then
    raise exception 'only a group admin can remove people';
  end if;
  select m.* into v_me from public.members m
    join public.conversation_participants p on p.member_id = m.id
   where p.conversation_id = p_conversation_id and m.user_id = auth.uid();
  -- An admin removing themselves is a LEAVE, and leave() has the
  -- last-admin rule. Routing it here would let the last admin strand the
  -- group with nobody able to manage it.
  if v_me.id = p_member_id then
    raise exception 'use leave_conversation to remove yourself';
  end if;
  update public.conversation_participants
     set left_at = now()
   where conversation_id = p_conversation_id
     and member_id = p_member_id
     and left_at is null;
end;
$$;

create or replace function public.leave_conversation(p_conversation_id uuid)
returns void language plpgsql security definer
set search_path = public as $$
declare
  v_me uuid;
  v_was_admin boolean;
  v_remaining int;
begin
  select p.member_id, p.is_admin into v_me, v_was_admin
    from public.conversation_participants p
    join public.members m on m.id = p.member_id
   where p.conversation_id = p_conversation_id
     and m.user_id = auth.uid()
     and p.left_at is null;
  if v_me is null then raise exception 'not in this conversation'; end if;

  update public.conversation_participants
     set left_at = now()
   where conversation_id = p_conversation_id and member_id = v_me;

  -- If the last admin walks out, promote whoever has been there longest
  -- rather than leaving a group nobody can manage. Silent on purpose:
  -- the alternative is refusing to let someone leave, which is worse.
  if v_was_admin and not exists (
    select 1 from public.conversation_participants
     where conversation_id = p_conversation_id
       and left_at is null and is_admin
  ) then
    select count(*) into v_remaining
      from public.conversation_participants
     where conversation_id = p_conversation_id and left_at is null;
    if v_remaining > 0 then
      update public.conversation_participants
         set is_admin = true
       where conversation_id = p_conversation_id
         and member_id = (
           select member_id from public.conversation_participants
            where conversation_id = p_conversation_id and left_at is null
            order by joined_at limit 1
         );
    end if;
  end if;
end;
$$;

-- ---------------------------------------------------------------- 6
-- Group metadata: name and photo, admins only.

create or replace function public.set_conversation_meta(
  p_conversation_id uuid, p_title text, p_avatar_path text
) returns void language plpgsql security definer
set search_path = public as $$
begin
  if not public.is_conversation_admin(p_conversation_id) then
    raise exception 'only a group admin can change the group';
  end if;
  update public.conversations
     set title = coalesce(nullif(btrim(coalesce(p_title, '')), ''), title),
         -- '' clears the photo; null leaves it alone. Without the
         -- distinction there is no way to REMOVE a group photo.
         avatar_path = case
           when p_avatar_path is null then avatar_path
           when p_avatar_path = '' then null
           else p_avatar_path
         end
   where id = p_conversation_id and kind = 'group';
end;
$$;

-- ---------------------------------------------------------------- 7
-- Send into a conversation.

create or replace function public.send_conversation_message(
  p_conversation_id uuid, p_body text
) returns uuid language plpgsql security definer
set search_path = public as $$
declare
  v_conversation public.conversations;
  v_me uuid;
  v_other uuid;
  v_id uuid;
begin
  select * into v_conversation from public.conversations
   where id = p_conversation_id;
  if v_conversation.id is null then raise exception 'no such conversation'; end if;
  if length(btrim(coalesce(p_body, ''))) = 0 then
    raise exception 'empty message';
  end if;

  select p.member_id into v_me
    from public.conversation_participants p
    join public.members m on m.id = p.member_id
   where p.conversation_id = p_conversation_id
     and m.user_id = auth.uid()
     and m.status = 'active'
     and p.left_at is null;
  if v_me is null then raise exception 'not in this conversation'; end if;

  -- A DIRECT message keeps its `to_member_id`, so every path that has
  -- read it since 0089 — the push trigger, the read receipts, the
  -- recipient's RLS — keeps working unchanged. A GROUP message has no
  -- single recipient and leaves it null; group delivery reads the
  -- roster.
  if v_conversation.kind = 'direct' then
    select member_id into v_other from public.conversation_participants
     where conversation_id = p_conversation_id and member_id <> v_me
     limit 1;
  end if;

  insert into public.member_notes
    (workspace_id, from_member_id, to_member_id, body, conversation_id)
    values (v_conversation.workspace_id, v_me, v_other, btrim(p_body),
            p_conversation_id)
    returning id into v_id;
  return v_id;
end;
$$;

-- ---------------------------------------------------------------- 8
-- The conversation LIST: one row per thread, newest activity first.
--
-- Returned by an RPC rather than assembled client-side because the
-- unread count and the last message are per-viewer, and doing that in
-- Dart means one query per conversation.

create or replace function public.my_conversations(p_workspace_id uuid)
returns table (
  id uuid,
  kind text,
  title text,
  avatar_path text,
  other_member_id uuid,
  last_body text,
  last_at timestamptz,
  last_from_member_id uuid,
  unread int,
  participant_count int
) language plpgsql stable security definer
set search_path = public as $$
declare v_me public.members;
begin
  v_me := public.my_active_member(p_workspace_id);
  return query
  select c.id,
         c.kind,
         c.title,
         c.avatar_path,
         -- Direct threads render the OTHER person; the client has no
         -- other way to know who that is without the roster.
         (select p2.member_id from public.conversation_participants p2
           where p2.conversation_id = c.id and p2.member_id <> v_me.id
           limit 1) as other_member_id,
         last.body,
         last.created_at,
         last.from_member_id,
         -- Unread = messages from someone else that I have not read.
         -- Group messages carry no per-reader receipt, so a group's
         -- count is "since I last opened it" — see mark_conversation_read.
         (select count(*)::int from public.member_notes n
           where n.conversation_id = c.id
             and n.from_member_id <> v_me.id
             and n.created_at > coalesce(mine.last_read_at, '-infinity'))
           as unread,
         (select count(*)::int from public.conversation_participants p3
           where p3.conversation_id = c.id and p3.left_at is null)
           as participant_count
    from public.conversations c
    join public.conversation_participants mine
      on mine.conversation_id = c.id and mine.member_id = v_me.id
    left join lateral (
      select n.body, n.created_at, n.from_member_id
        from public.member_notes n
       where n.conversation_id = c.id
       order by n.created_at desc
       limit 1
    ) last on true
   where c.workspace_id = p_workspace_id
     and mine.left_at is null
     -- A direct thread with nothing in it is an artefact of opening a
     -- profile, not a conversation. Groups show from the moment they
     -- exist: someone made one and is about to write in it.
     and (c.kind = 'group' or last.created_at is not null)
   order by c.last_message_at desc;
end;
$$;

revoke execute on function public.my_active_member(uuid) from public, anon;

-- ---------------------------------------------------------------- 9
-- Opening a conversation clears its unread.
--
-- Moves the watermark AND stamps the direct read receipts (0105), so a
-- 1:1 sender still sees their check turn blue. Two mechanisms, one call,
-- because "I opened it" is one event and splitting it is how they drift.

create or replace function public.mark_conversation_read(p_conversation_id uuid)
returns void language plpgsql security definer
set search_path = public as $$
declare v_me uuid;
begin
  select p.member_id into v_me
    from public.conversation_participants p
    join public.members m on m.id = p.member_id
   where p.conversation_id = p_conversation_id
     and m.user_id = auth.uid()
     and m.status = 'active';
  if v_me is null then return; end if;

  update public.conversation_participants
     set last_read_at = now()
   where conversation_id = p_conversation_id and member_id = v_me;

  -- Only messages addressed TO me, and only once: re-opening a thread
  -- must not move a receipt that already exists, or the sender sees the
  -- read time drift every time the reader glances at it.
  update public.member_notes
     set read_at = now()
   where conversation_id = p_conversation_id
     and to_member_id = v_me
     and read_at is null;
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- 0131 — who may read another member's money is a PERMISSION, not a
-- role (#709).
--
-- THE CLIENT AND THE SERVER DISAGREED ABOUT WHO MAY LOOK. The profile's
-- money card (#704) checks the `viewFinances` permission, the one the
-- owner grants and revokes per role in the matrix (#513). The server
-- guarded the same data with `is_admin_of()` — admin OR owner, full
-- stop. Two consequences, opposite directions:
--
--   * an admin whose role had *View finances* REVOKED saw no card, and
--     could still be served by `member_account` — the client gate was
--     the only thing standing between them and the figures;
--   * a plain member whose role was GRANTED it saw the card, and the
--     RPC refused them — a silent empty card, and the owner's decision
--     honoured by nobody.
--
-- `has_permission()` (0104) already knows the matrix, owners, active
-- co-owners and the admin defaults. This makes the money layer ask it.
--
-- ONE HELPER, so the rule lives in one place. Self always; otherwise
-- `viewFinances` OR `issueInvoices` — the invoicing role reads the
-- statement, the ledger and the invoices it issues from, and an owner
-- who grants one without the other has still granted the reading.

create or replace function public.may_view_member_finances(p_member_id uuid)
returns boolean language sql stable security definer
set search_path = public as $$
  select exists (
    select 1 from public.members m
     where m.id = p_member_id
       and (m.user_id = auth.uid()
            or public.has_permission(m.workspace_id, 'viewFinances')
            or public.has_permission(m.workspace_id, 'issueInvoices'))
  );
$$;

-- ---------------------------------------------------------------- 1
-- The two RPCs. Their bodies are long and change often; this swaps the
-- ONE guard line in place and refuses to run if the line it expects is
-- not there — a drifted body fails loudly instead of quietly keeping
-- the old rule.

do $swap$
declare
  v_def text;
  v_old text;
  v_new text;
begin
  -- member_account
  v_def := pg_get_functiondef('public.member_account(uuid)'::regprocedure);
  v_old := 'if not public.is_admin_of(v_member.workspace_id) and not exists (
    select 1 from public.members m
    where m.id = p_member_id and m.user_id = auth.uid()
  ) then
    raise exception ''not your account'';
  end if;';
  v_new := 'if not public.may_view_member_finances(p_member_id) then
    raise exception ''not your account'';
  end if;';
  if position(v_old in v_def) = 0 then
    raise exception '0131: member_account guard not found — body drifted';
  end if;
  execute replace(v_def, v_old, v_new);

  -- member_statement
  v_def := pg_get_functiondef('public.member_statement(uuid, text)'::regprocedure);
  v_old := 'v_caller_is_admin := public.is_admin_of(v_member.workspace_id);
  if not v_caller_is_admin and not exists (
    select 1 from public.members m
    where m.id = p_member_id and m.user_id = auth.uid()
  ) then
    raise exception ''not your statement'';
  end if;';
  v_new := 'v_caller_is_admin := public.is_admin_of(v_member.workspace_id);
  if not public.may_view_member_finances(p_member_id) then
    raise exception ''not your statement'';
  end if;';
  if position(v_old in v_def) = 0 then
    raise exception '0131: member_statement guard not found — body drifted';
  end if;
  execute replace(v_def, v_old, v_new);
end;
$swap$;

-- ---------------------------------------------------------------- 2
-- The row policies the ledger and the invoice list are read through.
-- Same rule, so a screen that lists what the RPC summarises cannot show
-- a different audience a different subset.

alter policy ledger_select on public.ledger_entries
  using (public.may_view_member_finances(member_id));

alter policy invoices_select on public.invoices
  using (public.may_view_member_finances(member_id));

-- ---------------------------------------------------------------- 3
-- E-mail addresses: the `manageMembers` permission, for the same reason.
