-- ---------------------------------------------------------------- the band, for context
-- The workspace default for a member: their band's fee and overage.
create or replace function public.default_tariff_of(p_member_id uuid)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(
    (select jsonb_build_object('fee_cents', b.fee_cents, 'overage_fee_cents', b.overage_fee_cents)
       from public.members m
       join public.fee_bands b on b.workspace_id = m.workspace_id
        and b.from_pct < coalesce(m.subscription_pct, 100)
        and coalesce(m.subscription_pct, 100) <= b.to_pct
      where m.id = p_member_id
      limit 1),
    jsonb_build_object('fee_cents', 0, 'overage_fee_cents', 0));
$$;
revoke execute on function public.default_tariff_of(uuid) from public, anon;
grant execute on function public.default_tariff_of(uuid) to authenticated;

-- ---------------------------------------------------------------- propose
create or replace function public.propose_price_negotiation(
  p_member_id uuid,
  p_fee_cents int default null,
  p_overage_fee_cents int default null,
  p_discount_percent numeric default null,
  p_note text default '',
  p_valid_from date default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_actor public.members;
  v_valid_from date;
  v_event_id uuid;
  v_id uuid;
begin
  select * into v_member from public.members where id = p_member_id;
  if v_member.id is null then raise exception 'unknown member'; end if;
  select * into v_actor from public.members
    where workspace_id = v_member.workspace_id and user_id = auth.uid() and status = 'active';
  if v_actor.id is null then raise exception 'not an active member'; end if;
  if not (v_actor.is_owner or public.has_permission(v_member.workspace_id, 'viewFinances')) then
    raise exception 'only the owner or a finance admin may propose a deal';
  end if;
  if v_actor.id = v_member.id then
    raise exception 'a deal is proposed for someone else';
  end if;
  if not coalesce((select w.feature_flags ->> 'priceNegotiations' from public.workspaces w
                    where w.id = v_member.workspace_id)::boolean, true) then
    raise exception 'price negotiations are off in this workspace';
  end if;
  if p_fee_cents is null and p_overage_fee_cents is null and p_discount_percent is null then
    raise exception 'nothing negotiated';
  end if;
  if exists (select 1 from public.price_negotiations
              where member_id = p_member_id and status = 'pending') then
    raise exception 'a proposal is already awaiting validation';
  end if;
  v_valid_from := coalesce(p_valid_from, date_trunc('month', now())::date);

  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id, payload, status)
  values (
    v_member.workspace_id, 'price_negotiation', 'submitted', v_actor.id, v_member.id,
    jsonb_build_object(
      'fee_cents', p_fee_cents,
      'overage_fee_cents', p_overage_fee_cents,
      'discount_percent', p_discount_percent,
      'note', coalesce(p_note, ''),
      'valid_from', v_valid_from,
      'default', public.default_tariff_of(p_member_id)),
    'pending')
  returning id into v_event_id;

  insert into public.price_negotiations
    (workspace_id, member_id, fee_cents, overage_fee_cents, discount_percent,
     note, valid_from, status, event_id, proposed_by)
  values (v_member.workspace_id, v_member.id, p_fee_cents, p_overage_fee_cents,
          p_discount_percent, coalesce(p_note, ''), v_valid_from, 'pending',
          v_event_id, v_actor.id)
  returning id into v_id;
  return v_id;
end;
$$;
revoke execute on function public.propose_price_negotiation(uuid, int, int, numeric, text, date) from public, anon;
grant execute on function public.propose_price_negotiation(uuid, int, int, numeric, text, date) to authenticated;

-- ---------------------------------------------------------------- decide → activate
create or replace function public.apply_negotiation_on_decision()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.type <> 'price_negotiation' or new.status = old.status then return new; end if;
  if new.status = 'confirmed' then
    update public.price_negotiations set status = 'superseded', decided_at = now()
     where member_id = new.subject_member_id and status = 'active';
    update public.price_negotiations set status = 'active', decided_at = now()
     where event_id = new.id and status = 'pending';
  elsif new.status in ('rejected', 'expired') then
    update public.price_negotiations set status = 'rejected', decided_at = now()
     where event_id = new.id and status = 'pending';
  end if;
  return new;
end;
$$;
drop trigger if exists events_apply_negotiation on public.events;
create trigger events_apply_negotiation
  after update of status on public.events
  for each row execute function public.apply_negotiation_on_decision();

-- ---------------------------------------------------------------- read, logged
-- The member's deal as the app shows it: default, active, pending. A
-- read by anyone but the member is on the record.
create or replace function public.member_price_negotiation(p_member_id uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_member public.members;
  v_me public.members;
begin
  select * into v_member from public.members where id = p_member_id;
  if v_member.id is null then raise exception 'unknown member'; end if;
  if not public.may_view_member_finances(p_member_id) then
    raise exception 'not allowed to see this member''s deal';
  end if;
  select * into v_me from public.members
    where workspace_id = v_member.workspace_id and user_id = auth.uid() and status = 'active';
  if v_me.id is not null and v_me.id <> v_member.id then
    insert into public.data_access_log
      (workspace_id, actor_member_id, subject_member_id, category)
    values (v_member.workspace_id, v_me.id, v_member.id, 'negotiations');
  end if;
  return jsonb_build_object(
    'default', public.default_tariff_of(p_member_id),
    'active', (select to_jsonb(n) from public.price_negotiations n
                where n.member_id = p_member_id and n.status = 'active'),
    'pending', (select to_jsonb(n) from public.price_negotiations n
                 where n.member_id = p_member_id and n.status = 'pending'));
end;
$$;
revoke execute on function public.member_price_negotiation(uuid) from public, anon;
grant execute on function public.member_price_negotiation(uuid) to authenticated;

-- ---------------------------------------------------------------- who can see me
do $$
declare
  v_def text;
  v_old text := $o$    'reservations', 'all_members',$o$;
  v_new text := $n$    'negotiations', (
      select coalesce(jsonb_agg(m.id), '[]'::jsonb) from public.members m
       where m.workspace_id = p_workspace_id and m.status = 'active' and m.id <> v_me.id
         and (m.is_owner or m.co_owner = 'active' or m.is_admin)
    ),
    'reservations', 'all_members',$n$;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'who_can_access_me';
  if v_def is null then raise exception 'who_can_access_me missing'; end if;
  if position(v_old in v_def) = 0 then raise exception 'who_can_access_me anchor not found'; end if;
  execute replace(v_def, v_old, v_new);
end $$;

-- ---------------------------------------------------------------- statement v13
-- The active deal overrides the band; the discount trims the
-- supplements; the JSON carries default + negotiated for the UI.
do $$
declare
  v_def text;
  v_old_band text := $o$  if v_band.id is not null then
    v_base := v_band.fee_cents;
    v_overage_rate := v_band.overage_fee_cents;
  end if;$o$;
  v_new_band text := $n$  if v_band.id is not null then
    v_base := v_band.fee_cents;
    v_overage_rate := v_band.overage_fee_cents;
  end if;
  -- #739 — the member's own deal, when active for this month.
  declare
    v_neg public.price_negotiations;
    v_default_fee int := v_base;
    v_default_overage int := v_overage_rate;
  begin
    select * into v_neg from public.price_negotiations n
     where n.member_id = p_member_id and n.status = 'active'
       and n.valid_from <= v_month_first;
    if v_neg.id is not null then
      if v_neg.fee_cents is not null then v_base := v_neg.fee_cents; end if;
      if v_neg.overage_fee_cents is not null then v_overage_rate := v_neg.overage_fee_cents; end if;
    end if;
    v_negotiated := jsonb_build_object(
      'default_fee_cents', v_default_fee,
      'default_overage_fee_cents', v_default_overage,
      'fee_cents', v_neg.fee_cents,
      'overage_fee_cents', v_neg.overage_fee_cents,
      'discount_percent', v_neg.discount_percent,
      'valid_from', v_neg.valid_from,
      'active', v_neg.id is not null);
    v_discount := coalesce(v_neg.discount_percent, 0);
  end;$n$;
  v_old_ret text := $o$    'overage_policy', coalesce(v_member.overage_policy, 'blocked'),
    'overage_rate_cents', v_overage_rate,$o$;
  v_new_ret text := $n$    'negotiated', v_negotiated,
    'overage_policy', coalesce(v_member.overage_policy, 'blocked'),
    'overage_rate_cents', v_overage_rate,$n$;
  v_old_bal text := $o$    'balance_cents',
      v_credits - v_base - v_overage - v_supplement - v_level_supplement
        - v_office_supplement - v_desk_supplement,$o$;
  v_new_bal text := $n$    'balance_cents',
      v_credits - v_base - v_overage - v_supplement - v_level_supplement
        - v_office_supplement - v_desk_supplement,
    'discount_percent', v_discount,$n$;
  v_old_decl text := $o$  v_overage_rate int := 0;$o$;
  v_new_decl text := $n$  v_overage_rate int := 0;
  v_negotiated jsonb := '{}'::jsonb;
  v_discount numeric := 0;$n$;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'member_statement';
  if v_def is null then raise exception 'member_statement missing'; end if;
  if position(v_old_band in v_def) = 0 then raise exception 'band anchor not found'; end if;
  if position(v_old_ret in v_def) = 0 then raise exception 'return anchor not found'; end if;
  if position(v_old_bal in v_def) = 0 then raise exception 'balance anchor not found'; end if;
  if position(v_old_decl in v_def) = 0 then raise exception 'declare anchor not found'; end if;
  v_def := replace(v_def, v_old_decl, v_new_decl);
  v_def := replace(v_def, v_old_band, v_new_band);
  v_def := replace(v_def, v_old_ret, v_new_ret);
  v_def := replace(v_def, v_old_bal, v_new_bal);
  execute v_def;
end $$;

-- The discount on the supplements: applied where they are summed is
-- four different places; applying it once, on the way out, is the same
-- arithmetic and one anchor. The four supplement variables are rounded
-- AFTER the discount, on the returned figures.
do $$
declare
  v_def text;
  v_old text := $o$  return jsonb_build_object(
    'period', p_period,$o$;
  v_new text := $n$  if v_discount > 0 then
    v_supplement := round(v_supplement * (100 - v_discount) / 100)::int;
    v_level_supplement := round(v_level_supplement * (100 - v_discount) / 100)::int;
    v_office_supplement := round(v_office_supplement * (100 - v_discount) / 100)::int;
    v_desk_supplement := round(v_desk_supplement * (100 - v_discount) / 100)::int;
  end if;
  return jsonb_build_object(
    'period', p_period,$n$;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'member_statement';
  if position(v_old in v_def) = 0 then raise exception 'discount anchor not found'; end if;
  execute replace(v_def, v_old, v_new);
end $$;

-- SPDX-License-Identifier: 0BSD
--
-- #744 PRICE NEGOTIATIONS v2 — the deal reaches the two things #739 left
-- at the catalogue: the OCCUPATION (the member's subscription percentage,
-- negotiated together with its monthly price — the tariff IS
-- percentage × price) and the ITEMS (a unit price per service and per
-- package). Items apply where the price is fixed — record_service_charge
-- and buy_package take the member's active deal into account — so the
-- ledger, the bill and the invoice carry the negotiated amount without
-- any of them knowing why. The percentage is applied to the member on
-- validation, the previous one kept on the deal for the comparison.

alter table public.price_negotiations
  add column if not exists subscription_pct int
    check (subscription_pct is null or subscription_pct between 1 and 100),
  add column if not exists previous_subscription_pct int,
  add column if not exists items jsonb not null default '{}'::jsonb;

alter table public.price_negotiations
  drop constraint if exists price_negotiations_check;
alter table public.price_negotiations add constraint price_negotiations_check
  check (fee_cents is not null or overage_fee_cents is not null
         or discount_percent is not null or subscription_pct is not null
         or items <> '{}'::jsonb);

-- The unit price of [p_item] ('services'/'packages' × id) for a member:
-- the active deal's, or null.
create or replace function public.negotiated_item_price(
  p_member_id uuid, p_kind text, p_item_id uuid
) returns int language sql stable security definer set search_path = public as $$
  select (n.items -> p_kind ->> p_item_id::text)::int
    from public.price_negotiations n
   where n.member_id = p_member_id and n.status = 'active'
     and n.valid_from <= current_date
   limit 1;
$$;
revoke execute on function public.negotiated_item_price(uuid, text, uuid) from public, anon;
grant execute on function public.negotiated_item_price(uuid, text, uuid) to authenticated;

-- ---------------------------------------------------------------- propose v2
drop function if exists public.propose_price_negotiation(uuid, int, int, numeric, text, date);
create or replace function public.propose_price_negotiation(
  p_member_id uuid,
  p_fee_cents int default null,
  p_overage_fee_cents int default null,
  p_discount_percent numeric default null,
  p_note text default '',
  p_valid_from date default null,
  p_subscription_pct int default null,
  p_items jsonb default '{}'::jsonb
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_actor public.members;
  v_valid_from date;
  v_event_id uuid;
  v_id uuid;
  v_items jsonb := coalesce(p_items, '{}'::jsonb);
  v_kind text;
  v_key text;
  v_val jsonb;
begin
  select * into v_member from public.members where id = p_member_id;
  if v_member.id is null then raise exception 'unknown member'; end if;
  select * into v_actor from public.members
    where workspace_id = v_member.workspace_id and user_id = auth.uid() and status = 'active';
  if v_actor.id is null then raise exception 'not an active member'; end if;
  if not (v_actor.is_owner or public.has_permission(v_member.workspace_id, 'viewFinances')) then
    raise exception 'only the owner or a finance admin may propose a deal';
  end if;
  if v_actor.id = v_member.id then
    raise exception 'a deal is proposed for someone else';
  end if;
  if not coalesce((select w.feature_flags ->> 'priceNegotiations' from public.workspaces w
                    where w.id = v_member.workspace_id)::boolean, true) then
    raise exception 'price negotiations are off in this workspace';
  end if;
  if p_subscription_pct is not null and p_subscription_pct not between 1 and 100 then
    raise exception 'occupation must be between 1 and 100 percent';
  end if;
  -- Items: only services/packages of this workspace, whole non-negative cents.
  for v_kind, v_val in select * from jsonb_each(v_items) loop
    if v_kind not in ('services', 'packages') then
      raise exception 'unknown item kind %', v_kind;
    end if;
    for v_key in select jsonb_object_keys(v_val) loop
      if (v_val ->> v_key) !~ '^\d+$' then
        raise exception 'item price must be whole cents';
      end if;
      if v_kind = 'services' and not exists (select 1 from public.services s
           where s.id = v_key::uuid and s.workspace_id = v_member.workspace_id) then
        raise exception 'unknown service %', v_key;
      end if;
      if v_kind = 'packages' and not exists (select 1 from public.packages p
           where p.id = v_key::uuid and p.workspace_id = v_member.workspace_id) then
        raise exception 'unknown package %', v_key;
      end if;
    end loop;
  end loop;
  if p_fee_cents is null and p_overage_fee_cents is null and p_discount_percent is null
     and p_subscription_pct is null and v_items = '{}'::jsonb then
    raise exception 'nothing negotiated';
  end if;
  if exists (select 1 from public.price_negotiations
              where member_id = p_member_id and status = 'pending') then
    raise exception 'a proposal is already awaiting validation';
  end if;
  v_valid_from := coalesce(p_valid_from, date_trunc('month', now())::date);

  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id, payload, status)
  values (
    v_member.workspace_id, 'price_negotiation', 'submitted', v_actor.id, v_member.id,
    jsonb_build_object(
      'fee_cents', p_fee_cents,
      'overage_fee_cents', p_overage_fee_cents,
      'discount_percent', p_discount_percent,
      'subscription_pct', p_subscription_pct,
      'previous_subscription_pct', v_member.subscription_pct,
      'items', v_items,
      'item_count', (select count(*) from jsonb_each(coalesce(v_items -> 'services', '{}'::jsonb)))
                  + (select count(*) from jsonb_each(coalesce(v_items -> 'packages', '{}'::jsonb))),
      'note', coalesce(p_note, ''),
      'valid_from', v_valid_from,
      'default', public.default_tariff_of(p_member_id)),
    'pending')
  returning id into v_event_id;

  insert into public.price_negotiations
    (workspace_id, member_id, fee_cents, overage_fee_cents, discount_percent,
     subscription_pct, previous_subscription_pct, items,
     note, valid_from, status, event_id, proposed_by)
  values (v_member.workspace_id, v_member.id, p_fee_cents, p_overage_fee_cents,
          p_discount_percent, p_subscription_pct, v_member.subscription_pct, v_items,
          coalesce(p_note, ''), v_valid_from, 'pending', v_event_id, v_actor.id)
  returning id into v_id;
  return v_id;
end;
$$;
revoke execute on function public.propose_price_negotiation(uuid, int, int, numeric, text, date, int, jsonb) from public, anon;
grant execute on function public.propose_price_negotiation(uuid, int, int, numeric, text, date, int, jsonb) to authenticated;

-- ---------------------------------------------------------------- decide → activate (+ occupation)
create or replace function public.apply_negotiation_on_decision()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_deal public.price_negotiations;
begin
  if new.type <> 'price_negotiation' or new.status = old.status then return new; end if;
  if new.status = 'confirmed' then
    update public.price_negotiations set status = 'superseded', decided_at = now()
     where member_id = new.subject_member_id and status = 'active';
    update public.price_negotiations set status = 'active', decided_at = now()
     where event_id = new.id and status = 'pending'
     returning * into v_deal;
    -- #744 — the occupation is part of the deal: applied on validation,
    -- the previous value kept for the comparison.
    if v_deal.id is not null and v_deal.subscription_pct is not null then
      update public.price_negotiations
         set previous_subscription_pct = (select subscription_pct from public.members where id = v_deal.member_id)
       where id = v_deal.id;
      update public.members set subscription_pct = v_deal.subscription_pct
       where id = v_deal.member_id;
    end if;
  elsif new.status in ('rejected', 'expired') then
    update public.price_negotiations set status = 'rejected', decided_at = now()
     where event_id = new.id and status = 'pending';
  end if;
  return new;
end;
$$;

-- ---------------------------------------------------------------- items applied where the price is fixed
do $$
declare
  v_def text;
  v_old_decl text := $o$  v_service public.services;$o$;
  v_new_decl text := $n$  v_service public.services;
  v_unit int;$n$;
  v_old_price text := $o$      'price_cents', v_service.price_cents,
      'quantity', p_quantity,
      'amount_cents', v_service.price_cents * p_quantity,$o$;
  v_new_price text := $n$      'price_cents', v_unit,
      'catalogue_price_cents', v_service.price_cents,
      'quantity', p_quantity,
      'amount_cents', v_unit * p_quantity,$n$;
  v_old_period text := $o$  v_period := coalesce(p_period, to_char(now(), 'YYYY-MM'));$o$;
  v_new_period text := $n$  -- #744 — the member's negotiated unit price, the catalogue otherwise.
  v_unit := coalesce(public.negotiated_item_price(p_subject_member_id, 'services', v_service.id),
                     v_service.price_cents);
  v_period := coalesce(p_period, to_char(now(), 'YYYY-MM'));$n$;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'record_service_charge';
  if v_def is null then raise exception 'record_service_charge missing'; end if;
  if position(v_old_decl in v_def) = 0 then raise exception 'declare anchor not found'; end if;
  if position(v_old_price in v_def) = 0 then raise exception 'price anchor not found'; end if;
  if position(v_old_period in v_def) = 0 then raise exception 'period anchor not found'; end if;
  v_def := replace(v_def, v_old_decl, v_new_decl);
  v_def := replace(v_def, v_old_price, v_new_price);
  v_def := replace(v_def, v_old_period, v_new_period);
  execute v_def;
end $$;

do $$
declare
  v_def text;
  v_old_decl text := $o$  v_vat numeric;$o$;
  v_new_decl text := $n$  v_vat numeric;
  v_unit int;$n$;
  v_old_ins text := $o$    p_workspace_id, v_member.id, 'charge', 'package', v_pkg.price_cents,$o$;
  v_new_ins text := $n$    p_workspace_id, v_member.id, 'charge', 'package', v_unit,$n$;
  v_old_tz text := $o$  select timezone into v_tz from public.workspaces where id = p_workspace_id;$o$;
  v_new_tz text := $n$  -- #744 — the member's negotiated package price, the catalogue otherwise.
  v_unit := coalesce(public.negotiated_item_price(v_member.id, 'packages', v_pkg.id),
                     v_pkg.price_cents);
  select timezone into v_tz from public.workspaces where id = p_workspace_id;$n$;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'buy_package';
  if v_def is null then raise exception 'buy_package missing'; end if;
  if position(v_old_decl in v_def) = 0 then raise exception 'buy_package declare anchor not found'; end if;
  if position(v_old_ins in v_def) = 0 then raise exception 'buy_package insert anchor not found'; end if;
  if position(v_old_tz in v_def) = 0 then raise exception 'buy_package tz anchor not found'; end if;
  v_def := replace(v_def, v_old_decl, v_new_decl);
  v_def := replace(v_def, v_old_ins, v_new_ins);
  v_def := replace(v_def, v_old_tz, v_new_tz);
  execute v_def;
end $$;

-- SPDX-License-Identifier: 0BSD
--
-- #749 — two permissions of their own for the commercial agreements:
--   viewNegotiations   — read a member's deal (the sheet, the access list);
--   manageNegotiations — propose / change a member's deal.
-- Until now both rode 'viewFinances'. The owner always holds both; a
-- co-owner starts with everything; an admin starts with both (today's
-- behaviour, so nothing changes for a workspace that never opens the
-- matrix) and the owner removes what they want, per role.

-- ---------------------------------------------------------------- a member's permission
-- has_permission() answers for auth.uid(); the "who can see me" list
-- needs the same answer for ANY member.
create or replace function public.member_has_permission(p_member_id uuid, perm text)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1
    from public.members m
    join public.workspaces w on w.id = m.workspace_id
    where m.id = p_member_id
      and m.status = 'active'
      and (
        m.is_owner
        or (m.co_owner = 'active' and (
              case when w.role_permissions ? 'co_owner'
                   then w.role_permissions->'co_owner' ? perm
                   else true end))
        or (m.is_admin and (
              case when w.role_permissions ? 'admin'
                   then w.role_permissions->'admin' ? perm
                   else perm in ('manageMembers','manageDocuments',
                                 'manageServices','approveExpenses',
                                 'viewFinances','viewNegotiations',
                                 'manageNegotiations') end))
        or (not m.is_admin and not m.is_owner and m.co_owner <> 'active'
            and w.role_permissions ? 'member'
            and w.role_permissions->'member' ? perm)
      )
  );
$$;
revoke execute on function public.member_has_permission(uuid, text) from public, anon;
grant execute on function public.member_has_permission(uuid, text) to authenticated;

-- ---------------------------------------------------------------- has_permission: admin defaults
do $$
declare
  v_def text;
  v_old text := $o$                    else perm in ('manageMembers','manageDocuments',
                                  'manageServices','approveExpenses',
                                  'viewFinances') end)$o$;
  v_new text := $n$                    else perm in ('manageMembers','manageDocuments',
                                  'manageServices','approveExpenses',
                                  'viewFinances','viewNegotiations',
                                  'manageNegotiations') end)$n$;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'has_permission';
  if v_def is null then raise exception 'has_permission missing'; end if;
  if position(v_old in v_def) = 0 then raise exception 'has_permission default anchor not found'; end if;
  execute replace(v_def, v_old, v_new);
end $$;

-- ---------------------------------------------------------------- who may read a deal
create or replace function public.may_view_member_negotiations(p_member_id uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.members m
     where m.id = p_member_id
       and (m.user_id = auth.uid()
            or public.has_permission(m.workspace_id, 'viewNegotiations')
            or public.has_permission(m.workspace_id, 'manageNegotiations'))
  );
$$;
revoke execute on function public.may_view_member_negotiations(uuid) from public, anon;
grant execute on function public.may_view_member_negotiations(uuid) to authenticated;

drop policy if exists price_negotiations_select on public.price_negotiations;
create policy price_negotiations_select on public.price_negotiations
  for select using (public.may_view_member_negotiations(member_id));

-- member_price_negotiation: the read guard follows the new permission.
do $$
declare
  v_def text;
  v_old text := $o$  if not public.may_view_member_finances(p_member_id) then raise exception 'not allowed to see this member''s deal'; end if;$o$;
  v_new text := $n$  if not public.may_view_member_negotiations(p_member_id) then raise exception 'not allowed to see this member''s deal'; end if;$n$;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'member_price_negotiation';
  if v_def is null then raise exception 'member_price_negotiation missing'; end if;
  if position(v_old in v_def) = 0 then raise exception 'read guard anchor not found'; end if;
  execute replace(v_def, v_old, v_new);
end $$;

-- propose_price_negotiation: proposing follows manageNegotiations.
do $$
declare
  v_def text;
  v_old text := $o$  if not (v_actor.is_owner or public.has_permission(v_member.workspace_id, 'viewFinances')) then raise exception 'only the owner or a finance admin may propose a deal'; end if;$o$;
  v_new text := $n$  if not (v_actor.is_owner or public.has_permission(v_member.workspace_id, 'manageNegotiations')) then raise exception 'only the owner or a member with the manageNegotiations permission may propose a deal'; end if;$n$;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'propose_price_negotiation';
  if v_def is null then raise exception 'propose_price_negotiation missing'; end if;
  if position(v_old in v_def) = 0 then raise exception 'propose guard anchor not found'; end if;
  execute replace(v_def, v_old, v_new);
end $$;

-- who_can_access_me: the negotiations list names who actually holds the
-- permission, per the matrix, not a role guess.
do $$
declare
  v_def text;
  v_old text := $o$    'negotiations', (
      select coalesce(jsonb_agg(m.id), '[]'::jsonb) from public.members m
       where m.workspace_id = p_workspace_id and m.status = 'active' and m.id <> v_me.id
         and (m.is_owner or m.co_owner = 'active' or m.is_admin)
    ),$o$;
  v_new text := $n$    'negotiations', (
      select coalesce(jsonb_agg(m.id), '[]'::jsonb) from public.members m
       where m.workspace_id = p_workspace_id and m.status = 'active' and m.id <> v_me.id
         and (public.member_has_permission(m.id, 'viewNegotiations')
              or public.member_has_permission(m.id, 'manageNegotiations'))
    ),$n$;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'who_can_access_me';
  if v_def is null then raise exception 'who_can_access_me missing'; end if;
  if position(v_old in v_def) = 0 then raise exception 'who_can_access_me negotiations anchor not found'; end if;
  execute replace(v_def, v_old, v_new);
end $$;

-- SPDX-License-Identifier: 0BSD
--
-- #751 — the GDPR consent, recorded on the ACCOUNT. Every signed-in
-- user passes the consent screen once; the accepted policy VERSION is
-- stored with a server-side timestamp, so the acceptance follows the
-- account across devices and reinstalls, and a change of the policy
-- text (a new version string in the app) asks again. Nothing else in
-- the app is reachable until the current version is accepted.

alter table public.profiles
  add column if not exists privacy_accepted_version text,
  add column if not exists privacy_accepted_at timestamptz;

create or replace function public.accept_privacy_policy(p_version text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if coalesce(trim(p_version), '') = '' then raise exception 'version required'; end if;
  update public.profiles
     set privacy_accepted_version = p_version,
         privacy_accepted_at = now()
   where id = auth.uid();
  if not found then
    insert into public.profiles (id, privacy_accepted_version, privacy_accepted_at)
    values (auth.uid(), p_version, now());
  end if;
end;
$$;
revoke execute on function public.accept_privacy_policy(text) from public, anon;
grant execute on function public.accept_privacy_policy(text) to authenticated;

-- SPDX-License-Identifier: 0BSD
--
-- #767 — scheduled (recurring) expenses: internet, phone, electricity…
-- Any active member, whatever their role, SCHEDULES an expense: amount,
-- start date, a recurrence rule (every X days / weeks / months / years),
-- and how long it runs (X times, until a date, or both — whichever ends
-- first; neither = until cancelled). The SCHEDULE itself goes through
-- the validation rules (new domain 'expense_schedule'). Once active, a
-- sweep (pg_cron + any member opening Finances) materialises each due
-- occurrence and presents it to the member:
--   · confirmed at the validated amount  → the expense is born settled
--     (confirmed event + ledger credit, 0017 system idiom);
--   · confirmed at a DIFFERENT amount    → a mandatory explanation, and
--     the expense goes through the normal expense validation; a reject
--     hands it back to the member, who may change amount and/or note
--     and resend.

-- ---------------------------------------------------------------- schema
create table public.expense_schedules (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  member_id uuid not null references public.members(id) on delete cascade,
  title text not null check (char_length(title) between 1 and 80),
  description text not null default '',
  amount_cents int not null check (amount_cents > 0),
  starts_on date not null,
  ends_on date,
  unit text not null check (unit in ('day', 'week', 'month', 'year')),
  every int not null default 1 check (every between 1 and 365),
  repeat_count int check (repeat_count between 1 and 500),
  status text not null default 'pending'
    check (status in ('pending', 'active', 'rejected', 'ended')),
  occurrences_done int not null default 0,
  next_due date,
  event_id uuid references public.events(id),
  created_at timestamptz not null default now(),
  check (ends_on is null or ends_on >= starts_on)
);
create index expense_schedules_ws on public.expense_schedules (workspace_id);
create index expense_schedules_due
  on public.expense_schedules (next_due) where status = 'active';

create table public.expense_occurrences (
  id uuid primary key default gen_random_uuid(),
  schedule_id uuid not null references public.expense_schedules(id) on delete cascade,
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  member_id uuid not null references public.members(id) on delete cascade,
  due_on date not null,
  amount_cents int not null check (amount_cents > 0),
  note text not null default '',
  deviation_reason text not null default '',
  status text not null default 'awaiting_member'
    check (status in ('awaiting_member', 'pending_validation', 'added', 'rejected')),
  event_id uuid references public.events(id),
  created_at timestamptz not null default now(),
  unique (schedule_id, due_on)
);
create index expense_occurrences_member
  on public.expense_occurrences (member_id, status);

alter table public.expense_schedules enable row level security;
alter table public.expense_occurrences enable row level security;

-- The member sees their own; whoever may approve expenses or view the
-- finances sees the workspace's (validators decide on real data).
create policy expense_schedules_select on public.expense_schedules
  for select using (
    exists (select 1 from public.members m
             where m.id = member_id and m.user_id = auth.uid())
    or public.has_permission(workspace_id, 'approveExpenses')
    or public.has_permission(workspace_id, 'viewFinances'));
create policy expense_occurrences_select on public.expense_occurrences
  for select using (
    exists (select 1 from public.members m
             where m.id = member_id and m.user_id = auth.uid())
    or public.has_permission(workspace_id, 'approveExpenses')
    or public.has_permission(workspace_id, 'viewFinances'));

-- ---------------------------------------------------------------- event domain
alter table public.events drop constraint events_type_check;
alter table public.events add constraint events_type_check check (type in
  ('reservation','payment','expense','adjustment','service_charge',
   'quota','role_change','member_join','space_reservation',
   'invoice_payment','reservation_delete','invoice_writeoff',
   'invoice_reminder','price_negotiation','expense_schedule'));
alter table public.validation_policies
  drop constraint validation_policies_event_type_check;
alter table public.validation_policies
  add constraint validation_policies_event_type_check check (
    event_type is null or event_type in (
      'reservation','payment','expense','adjustment','service_charge',
      'quota','role_change','member_join','space_reservation',
      'invoice_payment','reservation_delete','invoice_writeoff',
      'price_negotiation','expense_schedule'));

-- ---------------------------------------------------------------- create
create or replace function public.create_expense_schedule(
  p_workspace_id uuid,
  p_title text,
  p_amount_cents int,
  p_starts_on date,
  p_unit text,
  p_every int default 1,
  p_repeat_count int default null,
  p_ends_on date default null,
  p_description text default ''
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_id uuid;
  v_event_id uuid;
begin
  if not coalesce((select w.feature_flags ->> 'scheduledExpenses'
                     from public.workspaces w where w.id = p_workspace_id)::boolean, true) then
    raise exception 'scheduled expenses are disabled in this workspace';
  end if;
  select * into v_actor from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid() and status = 'active';
  if v_actor.id is null then raise exception 'not an active member'; end if;
  if p_amount_cents <= 0 then raise exception 'amount must be positive'; end if;
  if char_length(trim(p_title)) not between 1 and 80 then
    raise exception 'title must be 1–80 characters';
  end if;
  if p_unit not in ('day','week','month','year') then raise exception 'unknown unit'; end if;
  if p_every is null or p_every not between 1 and 365 then
    raise exception 'interval must be between 1 and 365';
  end if;
  if p_repeat_count is not null and p_repeat_count not between 1 and 500 then
    raise exception 'repetitions must be between 1 and 500';
  end if;
  if p_ends_on is not null and p_ends_on < p_starts_on then
    raise exception 'the end date lies before the start';
  end if;

  insert into public.expense_schedules
    (workspace_id, member_id, title, description, amount_cents,
     starts_on, ends_on, unit, every, repeat_count)
  values (p_workspace_id, v_actor.id, trim(p_title), coalesce(p_description, ''),
          p_amount_cents, p_starts_on, p_ends_on, p_unit, p_every, p_repeat_count)
  returning id into v_id;

  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id, payload, status)
  values (p_workspace_id, 'expense_schedule', 'submitted', v_actor.id, v_actor.id,
          jsonb_build_object(
            'schedule_id', v_id, 'title', trim(p_title),
            'amount_cents', p_amount_cents, 'note', coalesce(p_description, ''),
            'starts_on', p_starts_on, 'ends_on', p_ends_on,
            'unit', p_unit, 'every', p_every, 'repeat_count', p_repeat_count),
          'pending')
  returning id into v_event_id;
  update public.expense_schedules set event_id = v_event_id where id = v_id;
  return v_id;
end;
$$;
revoke execute on function public.create_expense_schedule(uuid, text, int, date, text, int, int, date, text) from public, anon;
grant execute on function public.create_expense_schedule(uuid, text, int, date, text, int, int, date, text) to authenticated;

-- ---------------------------------------------------------------- cancel
create or replace function public.cancel_expense_schedule(p_schedule_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_s public.expense_schedules;
begin
  select * into v_s from public.expense_schedules where id = p_schedule_id;
  if v_s.id is null then raise exception 'unknown schedule'; end if;
  if not (exists (select 1 from public.members m
                   where m.id = v_s.member_id and m.user_id = auth.uid())
          or public.has_permission(v_s.workspace_id, 'approveExpenses')) then
    raise exception 'not allowed';
  end if;
  update public.expense_schedules set status = 'ended' where id = p_schedule_id;
end;
$$;
revoke execute on function public.cancel_expense_schedule(uuid) from public, anon;
grant execute on function public.cancel_expense_schedule(uuid) to authenticated;

-- ---------------------------------------------------------------- apply on decision
-- The schedule follows its validation event: confirmed → active (the
-- sweep takes over), rejected → rejected.
create or replace function public.apply_expense_schedule_decision()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.type <> 'expense_schedule' or new.status = old.status then return new; end if;
  if new.status = 'confirmed' then
    update public.expense_schedules
       set status = 'active', next_due = starts_on
     where id = (new.payload ->> 'schedule_id')::uuid and status = 'pending';
  elsif new.status = 'rejected' then
    update public.expense_schedules
       set status = 'rejected'
     where id = (new.payload ->> 'schedule_id')::uuid and status = 'pending';
  end if;
  return new;
end;
$$;
drop trigger if exists events_apply_expense_schedule on public.events;
create trigger events_apply_expense_schedule
  after update on public.events
  for each row execute function public.apply_expense_schedule_decision();

-- A DEVIATED occurrence rides the normal 'expense' validation; its
-- occurrence row follows the event's fate.
create or replace function public.apply_expense_occurrence_decision()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.type <> 'expense' or new.status = old.status then return new; end if;
  if not (new.payload ? 'occurrence_id') then return new; end if;
  if new.status = 'confirmed' then
    update public.expense_occurrences
       set status = 'added' where id = (new.payload ->> 'occurrence_id')::uuid;
  elsif new.status = 'rejected' then
    update public.expense_occurrences
       set status = 'rejected' where id = (new.payload ->> 'occurrence_id')::uuid;
  end if;
  return new;
end;
$$;
drop trigger if exists events_apply_expense_occurrence on public.events;
create trigger events_apply_expense_occurrence
  after update on public.events
  for each row execute function public.apply_expense_occurrence_decision();

-- ---------------------------------------------------------------- sweep
-- Materialise every due occurrence of every ACTIVE schedule, up to
-- today. Any active member may sweep their own workspace (opening
-- Finances is the second clock); the scheduler (no auth.uid()) sweeps
-- all. Returns how many occurrences it created.
create or replace function public.sweep_expense_schedules(
  p_workspace_id uuid default null
) returns int language plpgsql security definer set search_path = public as $$
declare
  v_s record;
  v_due date;
  v_done int;
  v_total int := 0;
  v_ended boolean;
begin
  if auth.uid() is not null then
    if p_workspace_id is null then raise exception 'workspace required'; end if;
    if not exists (select 1 from public.members m
                    where m.workspace_id = p_workspace_id
                      and m.user_id = auth.uid() and m.status = 'active') then
      raise exception 'not an active member';
    end if;
  end if;

  for v_s in
    select s.* from public.expense_schedules s
      join public.workspaces w on w.id = s.workspace_id
     where s.status = 'active'
       and s.next_due is not null and s.next_due <= current_date
       and (p_workspace_id is null or s.workspace_id = p_workspace_id)
       and coalesce((w.feature_flags ->> 'moneyTab')::boolean, true)
       and coalesce((w.feature_flags ->> 'scheduledExpenses')::boolean, true)
  loop
    v_due := v_s.next_due;
    v_done := v_s.occurrences_done;
    v_ended := false;
    while v_due <= current_date loop
      if (v_s.ends_on is not null and v_due > v_s.ends_on)
         or (v_s.repeat_count is not null and v_done >= v_s.repeat_count) then
        v_ended := true; exit;
      end if;
      insert into public.expense_occurrences
        (schedule_id, workspace_id, member_id, due_on, amount_cents, note)
      values (v_s.id, v_s.workspace_id, v_s.member_id, v_due,
              v_s.amount_cents, v_s.description)
      on conflict (schedule_id, due_on) do nothing;
      v_total := v_total + 1;
      v_done := v_done + 1;
      v_due := (v_due + (v_s.every || ' ' || v_s.unit)::interval)::date;
    end loop;
    -- Bounds may also close BETWEEN sweeps (a date-bound rule whose next
    -- occurrence lies past the end): settle the status now.
    if not v_ended then
      v_ended := (v_s.ends_on is not null and v_due > v_s.ends_on)
              or (v_s.repeat_count is not null and v_done >= v_s.repeat_count);
    end if;
    update public.expense_schedules
       set occurrences_done = v_done,
           next_due = case when v_ended then null else v_due end,
           status = case when v_ended then 'ended' else status end
     where id = v_s.id;
  end loop;
  return v_total;
end;
$$;
revoke execute on function public.sweep_expense_schedules(uuid) from public, anon;
grant execute on function public.sweep_expense_schedules(uuid) to authenticated;

-- ---------------------------------------------------------------- confirm / resend
-- The member answers a presented occurrence. At the validated amount →
-- born settled (confirmed event + ledger credit, the 0017 system
-- idiom). At a different amount → the explanation is mandatory and the
-- expense goes through the 'expense' validation rules. A rejected
-- occurrence comes back through the same door (amount and/or note
-- changed, resent).
create or replace function public.confirm_expense_occurrence(
  p_occurrence_id uuid,
  p_amount_cents int,
  p_reason text default '',
  p_note text default null
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_o public.expense_occurrences;
  v_s public.expense_schedules;
  v_actor public.members;
  v_event_id uuid;
  v_note text;
begin
  select * into v_o from public.expense_occurrences where id = p_occurrence_id;
  if v_o.id is null then raise exception 'unknown occurrence'; end if;
  select * into v_s from public.expense_schedules where id = v_o.schedule_id;
  select * into v_actor from public.members
    where id = v_o.member_id and user_id = auth.uid() and status = 'active';
  if v_actor.id is null then raise exception 'only the member who scheduled it'; end if;
  if v_o.status not in ('awaiting_member', 'rejected') then
    raise exception 'occurrence already handled';
  end if;
  if p_amount_cents is null or p_amount_cents <= 0 then
    raise exception 'amount must be positive';
  end if;
  v_note := coalesce(p_note, v_o.note);

  if p_amount_cents = v_s.amount_cents and v_o.status = 'awaiting_member' then
    -- Exactly what the validated schedule says: born settled.
    insert into public.events
      (workspace_id, type, action, actor_member_id, subject_member_id,
       payload, status, decided_at)
    values (v_o.workspace_id, 'expense', 'submitted', v_actor.id, v_actor.id,
            jsonb_build_object(
              'amount_cents', p_amount_cents,
              'category', 'scheduled',
              'note', v_s.title || case when v_note = '' then '' else ' — ' || v_note end,
              'schedule_id', v_s.id,
              'occurrence_id', v_o.id,
              'auto_validated', true),
            'confirmed', now())
    returning id into v_event_id;
    insert into public.ledger_entries
      (workspace_id, member_id, kind, category, amount_cents, description,
       period, event_id, occurred_on)
    values (v_o.workspace_id, v_o.member_id, 'credit', 'expense',
            p_amount_cents,
            v_s.title || case when v_note = '' then '' else ' — ' || v_note end,
            to_char(v_o.due_on, 'YYYY-MM'), v_event_id, v_o.due_on);
    update public.expense_occurrences
       set status = 'added', amount_cents = p_amount_cents,
           note = v_note, event_id = v_event_id
     where id = v_o.id;
  else
    -- A different amount (or a resend after a reject): explain, then the
    -- expense validation rules decide.
    if char_length(trim(coalesce(p_reason, ''))) = 0 then
      raise exception 'a different amount needs an explanation';
    end if;
    insert into public.events
      (workspace_id, type, action, actor_member_id, subject_member_id, payload, status)
    values (v_o.workspace_id, 'expense', 'submitted', v_actor.id, v_actor.id,
            jsonb_build_object(
              'amount_cents', p_amount_cents,
              'category', 'scheduled',
              'note', v_s.title || case when v_note = '' then '' else ' — ' || v_note end,
              'schedule_id', v_s.id,
              'occurrence_id', v_o.id,
              'scheduled_amount_cents', v_s.amount_cents,
              'deviation_reason', trim(p_reason),
              'period', to_char(v_o.due_on, 'YYYY-MM'),
              'paid_on', v_o.due_on),
            'pending')
    returning id into v_event_id;
    update public.expense_occurrences
       set status = 'pending_validation', amount_cents = p_amount_cents,
           note = v_note, deviation_reason = trim(p_reason), event_id = v_event_id
     where id = v_o.id;
  end if;
end;
$$;
revoke execute on function public.confirm_expense_occurrence(uuid, int, text, text) from public, anon;
grant execute on function public.confirm_expense_occurrence(uuid, int, text, text) to authenticated;

-- ---------------------------------------------------------------- the morning clock
do $$
begin
  create extension if not exists pg_cron;
  perform cron.unschedule('deskilo-expense-schedules')
    from cron.job where jobname = 'deskilo-expense-schedules';
  perform cron.schedule('deskilo-expense-schedules', '20 6 * * *',
    $job$select public.sweep_expense_schedules()$job$);
exception when others then
  raise notice 'pg_cron unavailable (%): the client-side sweep stays the only clock', sqlerrm;
end $$;

-- SPDX-License-Identifier: 0BSD
-- #802 — the subscription is invoiced BEFORE the month it pays for, and
-- what the month actually cost is invoiced after it.
--
-- Until now a month produced exactly one invoice, issued by hand once the
-- month was over, carrying the subscription and everything else together.
-- That is the wrong shape for a subscription: a member pays for a month in
-- advance, so the document has to exist before the month starts — and the
-- extras (overage, accessories, services, packages, adjustments) cannot be
-- known until it ends.
--
-- An invoice therefore gains a KIND:
--
--   subscription  the monthly fee, issued ahead of the period it covers
--   usage         everything else, issued once that period is over
--   full          the historical whole-month document — every existing
--                 row, and still what issuing by hand produces
--
-- The PERIOD stays the month the invoice is about, never the month it was
-- issued in: a subscription invoice cut on 28 August for September carries
-- '2025-09'. Anything else would make a member's statement disagree with
-- the document that charged them.
--
-- Configurable per workspace (workspaces.billing_rules):
--   subscription_auto          bool  issue subscription invoices on a clock
--   subscription_advance_days  int   how many days before the month starts
--   usage_auto                 bool  issue the difference invoice on a clock
--   usage_when_zero            bool  issue it even when nothing is owed, so
--                                    the member gets the confirmation that
--                                    the month cost them nothing extra
--
-- Dunning needs no change: sweep_payment_reminders already walks every
-- unmatched invoice with a positive total, so both new kinds are chased
-- the day they fall due, exactly like any other invoice.

-- ---------------------------------------------------------------- the kind
alter table public.invoices
  add column if not exists kind text not null default 'full';

alter table public.invoices drop constraint if exists invoices_kind_check;
alter table public.invoices add constraint invoices_kind_check
  check (kind in ('full', 'subscription', 'usage', 'settlement'));

-- One live invoice per member per period PER KIND. The old rule lived only
-- inside create_invoice; a subscription and a usage invoice for the same
-- month are two documents by design, and a duplicate of either is not.
create unique index if not exists invoices_member_period_kind_uniq
  on public.invoices (member_id, period, kind)
  where voided_at is null and period is not null;

-- The index this REPLACES: (member_id, period) with no kind, which is the
-- literal statement "a month produces one invoice". Caught by the live
-- harness — create_invoice's own check was kind-aware from the first
-- draft, and the constraint underneath it silently was not, so a usage
-- invoice was refused beside the subscription invoice it complements.
drop index if exists public.invoices_one_active_per_member_period;

-- ---------------------------------------------------------------- the rules
alter table public.workspaces
  add column if not exists billing_rules jsonb not null default '{}'::jsonb;

comment on column public.workspaces.billing_rules is
  '#802 — subscription_auto, subscription_advance_days, usage_auto, usage_when_zero.';

-- ---------------------------------------------------------------- the lines
-- The three-argument form SPLITS what the two-argument one returns whole.
-- 'subscription' is one line kind in that output, so the split is exact and
-- the two halves cannot drift apart: usage is defined as "everything
-- invoice_lines_for produces that is not the subscription".
create or replace function public.invoice_lines_for(
  p_member_id uuid,
  p_period text,
  p_kind text
) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_all jsonb;
  v_out jsonb := '[]'::jsonb;
  v_line jsonb;
begin
  v_all := public.invoice_lines_for(p_member_id, p_period);
  if p_kind = 'full' then return v_all; end if;
  for v_line in select * from jsonb_array_elements(v_all) loop
    if p_kind = 'subscription' and v_line->>'kind' = 'subscription' then
      v_out := v_out || v_line;
    elsif p_kind = 'usage' and v_line->>'kind' is distinct from 'subscription' then
      v_out := v_out || v_line;
    end if;
  end loop;
  return v_out;
end;
$$;
revoke execute on function public.invoice_lines_for(uuid, text, text)
  from public, anon;

-- ---------------------------------------------------------------- issuing
-- Regenerated from 0104 with the kind threaded through: one implementation,
-- so a manual invoice and a scheduled one can never diverge in numbering,
-- signature, parties or VAT.
drop function if exists public.create_invoice(uuid, uuid, text, uuid, boolean);

create or replace function public.create_invoice(
  p_workspace_id uuid,
  p_member_id uuid,
  p_period text,
  p_replaces uuid default null,
  p_detailed boolean default false,
  -- #802 — which HALF of the month this document charges.
  p_kind text default 'full',
  -- Only a usage invoice may be empty, and only when the owner asked for
  -- the "nothing further to pay" confirmation.
  p_allow_zero boolean default false
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_subject public.members;
  v_workspace public.workspaces;
  v_replaced public.invoices;
  v_replaces_number text := '';
  v_lines jsonb;
  v_details jsonb := null;
  v_parties jsonb;
  v_vat_totals jsonb;
  v_zero_category text;
  v_tz text;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_total int := 0;
  v_count int;
  v_number text;
  v_member_name text;
  v_member_address text;
  v_member_country text;
  v_member_vat text;
  v_issuer_name text;
  v_id uuid;
  v_signature text;
begin
  if p_kind not in ('full', 'subscription', 'usage') then
    raise exception 'unknown invoice kind';
  end if;
  -- #802 — the nightly run calls this with no session. It still writes a
  -- real issuer on the row (the owner), because issuer_member_id is NOT
  -- NULL and an invoice with no issuer is not a document anyone can
  -- answer for.
  if auth.uid() is null then
    select * into v_actor from public.members
      where workspace_id = p_workspace_id and is_owner and status = 'active'
      order by joined_at limit 1;
    if v_actor.id is null then raise exception 'workspace has no owner'; end if;
  else
    select * into v_actor from public.members
      where workspace_id = p_workspace_id and user_id = auth.uid()
        and status = 'active' and (is_admin or is_owner);
    if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  end if;
  -- #513 — the CENTRAL permission decides: owner always passes,
  -- co-owner/admin/member per the workspace's role matrix; the
  -- legacy adminInvoicing flag keeps granting inside
  -- has_permission for compatibility.
  if auth.uid() is not null
     and not public.has_permission(p_workspace_id, 'issueInvoices') then
    raise exception 'admins may not issue invoices here';
  end if;

  select * into v_subject from public.members
    where id = p_member_id and workspace_id = p_workspace_id
      and status = 'active' and not is_kiosk;
  if v_subject.id is null then raise exception 'unknown subject member'; end if;
  if p_period is null or p_period !~ '^[0-9]{4}-[0-9]{2}$' then
    raise exception 'invalid period';
  end if;
  if exists (
    select 1 from public.invoices i
    where i.member_id = v_subject.id and i.period = p_period
      and i.kind = p_kind
      and i.voided_at is null and i.id is distinct from p_replaces
  ) then
    raise exception 'period already invoiced for this member';
  end if;

  v_lines := public.invoice_lines_for(p_member_id, p_period, p_kind);
  if jsonb_array_length(v_lines) = 0 and not p_allow_zero then
    raise exception 'nothing to invoice for this period';
  end if;
  select coalesce(sum((l->>'amount_cents')::int), 0) into v_total
    from jsonb_array_elements(v_lines) l;

  select * into v_workspace from public.workspaces where id = p_workspace_id;
  select coalesce(display_name, ''), coalesce(address, ''),
         coalesce(country_code, ''), coalesce(vat_id, '')
    into v_member_name, v_member_address, v_member_country, v_member_vat
    from public.profiles where id = v_subject.user_id;
  select coalesce(display_name, '') into v_issuer_name
    from public.profiles where id = v_actor.user_id;

  -- A 0% line is categorised by the workspace's declared regime, exactly
  -- as before VAT existed: outside the scope, or exempt.
  v_zero_category := case coalesce(v_workspace.vat_regime, 'not_subject')
                       when 'exempt' then 'E' else 'O' end;

  -- One entry per rate. Charges only: a credit is money moving.
  with charges as (
    select coalesce((l->>'vat_percent')::numeric, 0) as percent,
           (l->>'amount_cents')::int as gross,
           round((l->>'amount_cents')::int * 100.0
                 / (100 + coalesce((l->>'vat_percent')::numeric, 0)))::int as net
      from jsonb_array_elements(v_lines) l
     where (l->>'amount_cents')::int > 0
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'percent', percent,
      'category', case when percent > 0 then 'S' else v_zero_category end,
      'gross_cents', gross,
      'net_cents', net,
      'vat_cents', gross - net) order by percent desc), '[]'::jsonb)
    into v_vat_totals
    from (
      select percent, sum(gross)::int as gross, sum(net)::int as net
        from charges group by percent
    ) grouped;

  v_parties := jsonb_build_object(
    'seller', jsonb_build_object(
      'name', v_workspace.name,
      'street', coalesce(nullif(v_workspace.street, ''),
                         coalesce(v_workspace.address, '')),
      'city', coalesce(v_workspace.city, ''),
      'postal_code', coalesce(v_workspace.postal_code, ''),
      'country', v_workspace.country_code,
      'vat_id', coalesce(v_workspace.vat_id, ''),
      'legal_id', coalesce(v_workspace.legal_id, ''),
      'vat_regime', coalesce(v_workspace.vat_regime, 'not_subject'),
      'tax_exemption_reason',
        coalesce(v_workspace.tax_exemption_reason, '')),
    'buyer', jsonb_build_object(
      'name', v_member_name,
      'street', v_member_address,
      'country', coalesce(nullif(v_member_country, ''),
                          v_workspace.country_code),
      'vat_id', v_member_vat));

  if p_detailed then
    v_tz := v_workspace.timezone;
    v_period_start := to_timestamp(p_period || '-01', 'YYYY-MM-DD') at time zone v_tz;
    v_period_end := (to_timestamp(p_period || '-01', 'YYYY-MM-DD') + interval '1 month') at time zone v_tz;
    v_details := jsonb_build_object(
      'ledger', coalesce((
        select jsonb_agg(jsonb_build_object(
            'on', coalesce(le.occurred_on, le.created_at::date)::text,
            'category', le.category,
            'description', le.description,
            'amount_cents', case when le.kind = 'credit'
                                 then -le.amount_cents
                                 else le.amount_cents end)
          order by coalesce(le.occurred_on, le.created_at::date), le.created_at)
        from public.ledger_entries le
        where le.member_id = p_member_id and le.period = p_period
      ), '[]'::jsonb),
      'attendance', coalesce((
        select jsonb_agg(jsonb_build_object(
            'starts_at', to_char(r.starts_at at time zone v_tz,
                                 'YYYY-MM-DD"T"HH24:MI'),
            'ends_at', to_char(r.ends_at at time zone v_tz,
                               'YYYY-MM-DD"T"HH24:MI'),
            'status', r.status,
            'space', coalesce(
              (select s.name || ' · ' || d.name
                 from public.seats s
                 join public.desks d on d.id = s.desk_id
                where s.id = r.seat_id),
              (select d.name from public.desks d where d.id = r.desk_id),
              (select o.name from public.offices o where o.id = r.office_id),
              (select l.name from public.levels l where l.id = r.level_id),
              ''))
          order by r.starts_at)
        from public.reservations r
        where r.member_id = p_member_id
          and r.status in ('reserved', 'checked_in', 'completed')
          and r.starts_at >= v_period_start and r.starts_at < v_period_end
      ), '[]'::jsonb));
  end if;

  if p_replaces is not null then
    select * into v_replaced from public.invoices
      where id = p_replaces and workspace_id = p_workspace_id;
    if v_replaced.id is null then raise exception 'unknown invoice'; end if;
    if exists (select 1 from public.invoices
                where replaces_invoice_id = p_replaces) then
      raise exception 'invoice already replaced';
    end if;
    if exists (select 1 from public.invoice_matches
                where invoice_id = p_replaces) then
      raise exception 'invoice is matched';
    end if;
    if v_replaced.voided_at is null then
      update public.invoices
         set voided_at = now(), voided_by_name = v_issuer_name
       where id = p_replaces;
    end if;
    v_replaces_number := v_replaced.number;
  end if;

  perform pg_advisory_xact_lock(hashtext(p_workspace_id::text));
  select count(*) into v_count from public.invoices
    where workspace_id = p_workspace_id
      and date_part('year', issued_at) = date_part('year', now());
  v_number := 'INV-' || date_part('year', now())::int || '-'
      || lpad((v_count + 1)::text, 4, '0');

  v_id := gen_random_uuid();
  v_signature := encode(extensions.digest(convert_to(concat_ws('|',
      v_id::text, v_number, p_workspace_id::text, v_subject.id::text,
      v_member_name, v_member_address, v_workspace.name,
      coalesce(v_workspace.address, ''), v_issuer_name,
      p_period, v_lines::text, v_total::text, v_workspace.currency_code,
      now()::date::text, coalesce(p_replaces::text, ''),
      v_replaces_number, coalesce(v_details::text, ''),
      v_parties::text, v_vat_totals::text, p_kind),
      'UTF8'), 'sha256'), 'hex');

  insert into public.invoices
    (id, workspace_id, member_id, issuer_member_id, number, period, title,
     lines, total_cents, currency, member_name, member_address,
     workspace_name, workspace_address, issuer_name, signature,
     replaces_invoice_id, replaces_number, details, parties, vat_totals,
     kind)
  values
    (v_id, p_workspace_id, v_subject.id, v_actor.id, v_number, p_period,
     p_period, v_lines, v_total, v_workspace.currency_code,
     v_member_name, v_member_address, v_workspace.name,
     coalesce(v_workspace.address, ''), v_issuer_name, v_signature,
     p_replaces, v_replaces_number, v_details, v_parties, v_vat_totals,
     p_kind);
  return v_id;
end;
$$;
revoke execute on function
  public.create_invoice(uuid, uuid, text, uuid, boolean, text, boolean)
  from public, anon;
grant execute on function
  public.create_invoice(uuid, uuid, text, uuid, boolean, text, boolean)
  to authenticated;

-- ---------------------------------------------------------------- the clock
-- One sweep for both runs: the same walk over the same members, a month
-- apart. Runs daily and is idempotent — the unique index above is what
-- makes a second run of the day a no-op rather than a duplicate.
create or replace function public.sweep_billing_invoices(
  p_workspace_id uuid default null
) returns int language plpgsql security definer set search_path = public as $$
declare
  v_ws record;
  v_member record;
  v_rules jsonb;
  v_flags jsonb;
  v_tz text;
  v_today date;
  v_next_start date;
  v_next_period text;
  v_last_period text;
  v_advance int;
  v_total int := 0;
begin
  if auth.uid() is not null then
    if p_workspace_id is null then raise exception 'workspace required'; end if;
    if not public.is_admin_of(p_workspace_id) then
      raise exception 'not an admin of this workspace';
    end if;
  end if;

  for v_ws in
    select w.id, w.billing_rules, w.timezone, w.feature_flags
      from public.workspaces w
     where (p_workspace_id is null or w.id = p_workspace_id)
       and coalesce((w.feature_flags ->> 'moneyTab')::boolean, true)
       and coalesce((w.feature_flags ->> 'invoicing')::boolean, true)
  loop
    v_rules := coalesce(v_ws.billing_rules, '{}'::jsonb);
    v_flags := coalesce(v_ws.feature_flags, '{}'::jsonb);
    -- The WORKSPACE's calendar decides when a month starts, not UTC's:
    -- east of UTC the first of the month arrives hours earlier, and a
    -- subscription invoice that lands a day late is a late invoice.
    v_tz := coalesce(nullif(v_ws.timezone, ''), 'UTC');
    v_today := (now() at time zone v_tz)::date;
    v_next_start := date_trunc('month', v_today + interval '1 month')::date;
    v_next_period := to_char(v_next_start, 'YYYY-MM');
    v_last_period :=
      to_char(date_trunc('month', v_today) - interval '1 month', 'YYYY-MM');
    v_advance := least(greatest(
      coalesce((v_rules ->> 'subscription_advance_days')::int, 3), 0), 28);

    for v_member in
      select m.id from public.members m
       where m.workspace_id = v_ws.id and m.status = 'active' and not m.is_kiosk
       order by m.id
    loop
      -- SUBSCRIPTION, for the month AHEAD, once we are inside the advance
      -- window. Every failure here is expected traffic — already issued,
      -- or this member has no fee — and must not abort the workspace.
      if coalesce((v_rules ->> 'subscription_auto')::boolean, true)
         and coalesce((v_flags ->> 'subscriptionInvoices')::boolean, true)
         and v_today >= v_next_start - make_interval(days => v_advance)
      then
        begin
          perform public.create_invoice(
            v_ws.id, v_member.id, v_next_period, null, false,
            'subscription', false);
          v_total := v_total + 1;
        exception when others then
          null;
        end;
      end if;

      -- USAGE, for the month just FINISHED, so the figures can no longer
      -- move. `usage_when_zero` decides whether a member who owes nothing
      -- extra still receives the document that says so.
      if coalesce((v_rules ->> 'usage_auto')::boolean, true)
         and coalesce((v_flags ->> 'usageInvoices')::boolean, true)
      then
        begin
          perform public.create_invoice(
            v_ws.id, v_member.id, v_last_period, null, false, 'usage',
            coalesce((v_rules ->> 'usage_when_zero')::boolean, false));
          v_total := v_total + 1;
        exception when others then
          null;
        end;
      end if;
    end loop;
  end loop;
  return v_total;
end;
$$;
revoke execute on function public.sweep_billing_invoices(uuid) from public, anon;
grant execute on function public.sweep_billing_invoices(uuid) to authenticated;

do $$
begin
  create extension if not exists pg_cron;
  perform cron.unschedule('deskilo-billing-invoices')
    from cron.job where jobname = 'deskilo-billing-invoices';
  -- 06:40, after the expense sweep at 06:20: a scheduled expense
  -- confirmed this morning belongs on this morning's usage invoice.
  perform cron.schedule('deskilo-billing-invoices', '40 6 * * *',
    $job$select public.sweep_billing_invoices()$job$);
exception when others then
  raise notice 'pg_cron unavailable (%): the client sweep stays the only clock', sqlerrm;
end $$;

-- SPDX-License-Identifier: 0BSD
-- #804 — several open invoices regrouped into ONE the member pays.
--
-- A member with a subscription invoice, an end-of-month invoice and last
-- month's leftover receives three demands for one relationship. Settling
-- them produces a single document that carries their sum, and the three
-- stop being separately owed: payment matches the settlement, and dunning
-- chases the settlement instead of chasing each source.
--
-- WHAT A SETTLEMENT IS NOT. The sources are not voided and not replaced.
-- They stay in the archive exactly as issued — that is the whole point of
-- an immutable invoice — and each gains a pointer to the document that
-- settled it. So the trail runs both ways: from a source to the demand
-- that now covers it, and from the settlement to every position of every
-- invoice inside it, snapshotted at the moment of regrouping.
--
-- VAT IS NOT RESTATED. Each source already declared its own tax, and a
-- settlement that taxed the same supply again would double-declare it.
-- The settlement is a consolidation of AMOUNTS OWED, so its lines carry
-- 0% and its vat_totals are empty; the tax lives on the sources, which
-- the document names.

alter table public.invoices
  add column if not exists settled_by_invoice_id uuid
    references public.invoices(id) on delete restrict;

-- The positions of every source, frozen when they were regrouped, so the
-- settlement remains readable even if a source is later corrected.
alter table public.invoices
  add column if not exists settles jsonb;

create index if not exists invoices_settled_by_idx
  on public.invoices (settled_by_invoice_id)
  where settled_by_invoice_id is not null;

comment on column public.invoices.settled_by_invoice_id is
  '#804 - the settlement invoice that now carries this one''s balance.';
comment on column public.invoices.settles is
  '#804 - snapshot of the sources: number, period, kind, total and lines.';

-- ---------------------------------------------------------------- immutability
-- An invoice may be updated in exactly one way today: voiding stamps a
-- date on it. Settling stamps a POINTER, and for the same reason — the
-- document itself does not change, its lifecycle does. The trigger has to
-- be told, or settle_invoices cannot write its own back-reference.
--
-- Caught by the live harness on the first run of settle_invoices.
create or replace function public.invoices_immutable()
returns trigger language plpgsql as $$
begin
  if tg_op = 'UPDATE'
     and old.voided_at is null
     and new.voided_at is not null
     and (to_jsonb(old) - 'voided_at' - 'voided_by_name')
       = (to_jsonb(new) - 'voided_at' - 'voided_by_name') then
    return new;
  end if;
  -- #804 — the settlement back-pointer, once, and nothing else with it.
  if tg_op = 'UPDATE'
     and old.settled_by_invoice_id is null
     and new.settled_by_invoice_id is not null
     and (to_jsonb(old) - 'settled_by_invoice_id')
       = (to_jsonb(new) - 'settled_by_invoice_id') then
    return new;
  end if;
  raise exception 'invoices are immutable';
end;
$$;

-- ---------------------------------------------------------------- settling
create or replace function public.settle_invoices(
  p_workspace_id uuid,
  p_member_id uuid,
  p_invoice_ids uuid[],
  p_note text default ''
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_subject public.members;
  v_workspace public.workspaces;
  v_latest public.invoices;
  v_lines jsonb := '[]'::jsonb;
  v_settles jsonb := '[]'::jsonb;
  v_total int := 0;
  v_count int;
  v_number text;
  v_id uuid;
  v_signature text;
  v_issuer_name text;
  v_src public.invoices;
  v_n int := 0;
begin
  select * into v_actor from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;
  if not public.has_permission(p_workspace_id, 'issueInvoices') then
    raise exception 'admins may not issue invoices here';
  end if;

  select * into v_subject from public.members
    where id = p_member_id and workspace_id = p_workspace_id;
  if v_subject.id is null then raise exception 'unknown subject member'; end if;

  if p_invoice_ids is null or array_length(p_invoice_ids, 1) is null
     or array_length(p_invoice_ids, 1) < 2 then
    -- One invoice is not a regrouping; it is the invoice.
    raise exception 'settle at least two invoices';
  end if;

  perform pg_advisory_xact_lock(hashtext(p_workspace_id::text));

  for v_src in
    select * from public.invoices
     where id = any(p_invoice_ids)
     order by issued_at, number
  loop
    v_n := v_n + 1;
    if v_src.workspace_id <> p_workspace_id then
      raise exception 'invoice % is not in this workspace', v_src.number;
    end if;
    if v_src.member_id <> p_member_id then
      -- Regrouping across members would produce a demand nobody owes.
      raise exception 'invoice % belongs to another member', v_src.number;
    end if;
    if v_src.voided_at is not null then
      raise exception 'invoice % is void', v_src.number;
    end if;
    if v_src.settled_by_invoice_id is not null then
      raise exception 'invoice % is already settled', v_src.number;
    end if;
    if v_src.kind = 'settlement' then
      raise exception 'invoice % is itself a settlement', v_src.number;
    end if;
    if exists (select 1 from public.invoice_matches m
                where m.invoice_id = v_src.id) then
      -- A paid or part-paid invoice has a match to honour; folding it in
      -- would orphan that payment.
      raise exception 'invoice % already has a payment', v_src.number;
    end if;

    v_total := v_total + v_src.total_cents;
    -- One line per source: what it was, and what it left owing.
    v_lines := v_lines || jsonb_build_object(
      'kind', 'settled_invoice',
      'label', v_src.number,
      'quantity', 1,
      'vat_percent', 0,
      'amount_cents', v_src.total_cents);
    -- …and the whole of it, so the positions stay readable here.
    v_settles := v_settles || jsonb_build_object(
      'invoice_id', v_src.id,
      'number', v_src.number,
      'period', v_src.period,
      'kind', v_src.kind,
      'issued_at', v_src.issued_at,
      'total_cents', v_src.total_cents,
      'currency', v_src.currency,
      'lines', v_src.lines,
      'vat_totals', v_src.vat_totals);
    v_latest := v_src;
  end loop;

  if v_n <> array_length(p_invoice_ids, 1) then
    raise exception 'unknown invoice in the selection';
  end if;

  select * into v_workspace from public.workspaces where id = p_workspace_id;
  select coalesce(display_name, '') into v_issuer_name
    from public.profiles where id = v_actor.user_id;

  select count(*) into v_count from public.invoices
    where workspace_id = p_workspace_id
      and date_part('year', issued_at) = date_part('year', now());
  v_number := 'INV-' || date_part('year', now())::int || '-'
      || lpad((v_count + 1)::text, 4, '0');

  v_id := gen_random_uuid();
  v_signature := encode(extensions.digest(convert_to(concat_ws('|',
      v_id::text, v_number, p_workspace_id::text, v_subject.id::text,
      v_lines::text, v_total::text, v_settles::text,
      now()::date::text, 'settlement'),
      'UTF8'), 'sha256'), 'hex');

  insert into public.invoices
    (id, workspace_id, member_id, issuer_member_id, number, period, title,
     lines, total_cents, currency, member_name, member_address,
     workspace_name, workspace_address, issuer_name, signature,
     parties, vat_totals, kind, settles)
  values
    (v_id, p_workspace_id, p_member_id, v_actor.id, v_number,
     -- No period: a settlement can span months, and pinning it to one
     -- would collide with that month's own invoice in the kind index.
     null, coalesce(nullif(p_note, ''), v_number),
     v_lines, v_total, v_latest.currency,
     v_latest.member_name, v_latest.member_address,
     v_latest.workspace_name, v_latest.workspace_address,
     v_issuer_name, v_signature,
     v_latest.parties,
     -- Empty on purpose: the tax was declared on the sources.
     '[]'::jsonb, 'settlement', v_settles);

  update public.invoices
     set settled_by_invoice_id = v_id
   where id = any(p_invoice_ids);

  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id,
     payload, status)
  values
    (p_workspace_id, 'invoice_payment', 'created', v_actor.id, p_member_id,
     jsonb_build_object(
       'invoice_id', v_id, 'number', v_number, 'kind', 'settlement',
       'amount_cents', v_total, 'currency', v_latest.currency,
       'settled_count', v_n,
       'settled_numbers', (select jsonb_agg(s->>'number')
                             from jsonb_array_elements(v_settles) s)),
     'applied');

  return v_id;
end;
$$;
revoke execute on function
  public.settle_invoices(uuid, uuid, uuid[], text) from public, anon;
grant execute on function
  public.settle_invoices(uuid, uuid, uuid[], text) to authenticated;

-- ---------------------------------------------------------------- dunning
-- A settled invoice is no longer separately owed: the settlement carries
-- its balance, and chasing both would demand the same money twice.
--
-- Patched IN PLACE rather than regenerated. sweep_payment_reminders is
-- ninety lines of push plumbing this change does not touch, and copying
-- it forward to alter one WHERE clause is how a function acquires a
-- transcription bug. The guard makes it idempotent and it fails loudly
-- if 0134's shape ever moves out from under it.
do $patch$
declare
  v_def text;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'sweep_payment_reminders';
  if v_def is null then
    raise exception 'sweep_payment_reminders not found (0134 missing?)';
  end if;
  if position('settled_by_invoice_id is null' in v_def) > 0 then
    raise notice 'dunning already skips settled invoices';
    return;
  end if;
  if position('and not exists (select 1 from public.invoice_matches m' in v_def) = 0 then
    raise exception 'sweep_payment_reminders no longer has the shape 0143 patches';
  end if;
  execute replace(v_def,
    'and not exists (select 1 from public.invoice_matches m',
    'and i.settled_by_invoice_id is null
         and not exists (select 1 from public.invoice_matches m');
  raise notice 'dunning now skips settled invoices';
end $patch$;

-- SPDX-License-Identifier: 0BSD
-- 0144 — #816: the validation framework and the role gates on the money
-- flows, made to keep what the guide promises: the server enforces the
-- SAME matrix the UI shows, nobody validates their own event, and a
-- request that expires grants nothing silently.
--
-- What the audit found (2026-09-01) and what this migration does:
--
--  1. sweep_pending_events EXPIRED a pending invoice_payment without the
--     compensation the reject branch runs — the match row stayed pending
--     forever, the payment stayed reserved, the invoice fell out of
--     dunning. → release_invoice_payment(), ONE helper, called by the
--     reject branch (patched in place) AND by sweep_pending_events v2.
--  2. settle_invoices wrote its own invoice_payment event already
--     'applied' — self-validated, no quorum. → v2 honours the
--     invoice_payment policy; a reject voids the settlement and releases
--     its sources.
--  3. A settled source could still be voided, replaced or matched, and
--     voiding a settlement stranded its sources. → guards in
--     void_invoice / create_invoice / match_invoice; voiding a
--     settlement releases its sources (the immutability trigger learns
--     that one more transition).
--  4. set_role_permissions rejected the client's own payload (the two
--     negotiation permissions were missing from its catalog).
--  5. void_invoice, record_invoice_reminder, settle_credit_invoice ran the
--     pre-#513 gate (is_owner_of or the adminInvoicing flag);
--     request_invoice_writeoff checked no permission at all;
--     create_invoice, match_invoice and settle_invoices demanded
--     (is_admin or is_owner) BEFORE consulting the matrix. → every one of
--     them now asks has_permission(ws, 'issueInvoices') and nothing else.
--  6. A manual reminder wrote a row and no event — the member never
--     learned of it; its level was always 1. → v2 computes the level and
--     emits the same invoice_reminder event the sweep does.
--  7. invoice_matches, invoice_match_payments, invoice_reminders and
--     invoice_transmissions never moved to may_view_member_finances
--     (0131). → they do now; a member also sees their own transmissions.
--  8. Scoped validators ('listed' / 'members', 0135) could not SEE the
--     events they must decide. → events_select widened.
--  9. manageValidation and workspaceSettings were decorative. → the
--     validation_policies write policy asks manageValidation; dunning
--     and billing rules go through RPCs gated on workspaceSettings.
--
-- Every RPC below is re-created in full where its body is short, and
-- patched IN PLACE (pg_get_functiondef + replace, anchors asserted)
-- where it is long and owned by a later migration — 0131/0135/0139/0143
-- set the idiom.

-- ---------------------------------------------------------------- 4. the catalog
create or replace function public.set_role_permissions(
  p_workspace_id uuid,
  p_role text,
  p_permissions text[]
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_catalog text[] := array[
    'manageRoles','manageMembers','manageValidation','workspaceSettings',
    'issueInvoices','viewFinances','manageDocuments','manageServices',
    'approveExpenses','viewNegotiations','manageNegotiations'];
  v_perm text;
begin
  if not public.has_permission(p_workspace_id, 'manageRoles') then
    raise exception 'only role managers may edit permissions';
  end if;
  if p_role not in ('co_owner','admin','member') then
    raise exception 'unknown role';
  end if;
  foreach v_perm in array coalesce(p_permissions, '{}') loop
    if not (v_perm = any(v_catalog)) then
      raise exception 'unknown permission %', v_perm;
    end if;
  end loop;
  update public.workspaces
    set role_permissions = jsonb_set(
      coalesce(role_permissions, '{}'::jsonb),
      array[p_role],
      coalesce(to_jsonb(p_permissions), '[]'::jsonb))
    where id = p_workspace_id;
end;
$$;
revoke execute on function public.set_role_permissions(uuid, text, text[])
  from public, anon;
grant execute on function public.set_role_permissions(uuid, text, text[])
  to authenticated;

-- ---------------------------------------------------------------- 5. ONE issuer gate
-- The caller as an ACTIVE member holding issueInvoices — owner, co-owner,
-- admin or member, exactly as the matrix says. Raises the message every
-- invoicing RPC has always raised, so the client's mapping stays valid.
create or replace function public.issuing_member(p_workspace_id uuid)
returns public.members language plpgsql stable security definer
set search_path = public as $$
declare
  v_actor public.members;
begin
  select * into v_actor from public.members
    where workspace_id = p_workspace_id and user_id = auth.uid()
      and status = 'active';
  if v_actor.id is null then raise exception 'not a member'; end if;
  if not public.has_permission(p_workspace_id, 'issueInvoices') then
    raise exception 'admins may not issue invoices here';
  end if;
  return v_actor;
end;
$$;
revoke execute on function public.issuing_member(uuid) from public, anon;

-- ---------------------------------------------------------------- 3. immutability v3
-- Two more transitions, both for the settlement lifecycle: a source's
-- pointer may be CLEARED (the settlement was voided or rejected), and
-- voiding may stamp a settlement whose sources are released in the same
-- statement batch.
create or replace function public.invoices_immutable()
returns trigger language plpgsql as $$
begin
  if tg_op = 'UPDATE'
     and old.voided_at is null
     and new.voided_at is not null
     and (to_jsonb(old) - 'voided_at' - 'voided_by_name')
       = (to_jsonb(new) - 'voided_at' - 'voided_by_name') then
    return new;
  end if;
  -- #804 — the settlement back-pointer, set once…
  if tg_op = 'UPDATE'
     and old.settled_by_invoice_id is null
     and new.settled_by_invoice_id is not null
     and (to_jsonb(old) - 'settled_by_invoice_id')
       = (to_jsonb(new) - 'settled_by_invoice_id') then
    return new;
  end if;
  -- #816 — …and cleared once, when the settlement did not stand.
  if tg_op = 'UPDATE'
     and old.settled_by_invoice_id is not null
     and new.settled_by_invoice_id is null
     and (to_jsonb(old) - 'settled_by_invoice_id')
       = (to_jsonb(new) - 'settled_by_invoice_id') then
    return new;
  end if;
  raise exception 'invoices are immutable';
end;
$$;

-- ---------------------------------------------------------------- 1. the release
-- Everything a NOT-STANDING invoice_payment leaves behind, undone: the
-- credit note it minted, the match row, the payment reservations of an
-- additional payment (#506) — and, for a settlement, the settlement
-- document voided and its sources released. The reject branch and the
-- expiry sweep both call this; before #816 only the reject branch knew.
create or replace function public.release_invoice_payment(p_event_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_event public.events;
  v_settlement uuid;
begin
  select * into v_event from public.events where id = p_event_id;
  if v_event.id is null then return; end if;
  delete from public.ledger_entries
    where id = (select credit_ledger_id from public.invoice_matches
                 where event_id = p_event_id);
  delete from public.invoice_matches where event_id = p_event_id;
  delete from public.ledger_entries
    where id in (select credit_ledger_id
                   from public.invoice_match_payments
                  where event_id = p_event_id
                    and credit_ledger_id is not null);
  delete from public.invoice_match_payments where event_id = p_event_id;
  if coalesce(v_event.payload->>'kind', '') = 'settlement' then
    v_settlement := (v_event.payload->>'invoice_id')::uuid;
    update public.invoices set settled_by_invoice_id = null
      where settled_by_invoice_id = v_settlement;
    update public.invoices
       set voided_at = now(), voided_by_name = 'validation'
     where id = v_settlement and voided_at is null;
  end if;
end;
$$;
revoke execute on function public.release_invoice_payment(uuid) from public, anon;

-- respond_to_event: the reject branch delegates to the helper (in place —
-- 0135 patched this body last; the block below is the 0101 text AS THE
-- HOSTED PROJECT HOLDS IT: without the two #506 comment lines the file
-- carries — pg_get_functiondef returned the body comment-free there, and
-- the live harness caught the mismatch on the first run).
do $patch$
declare
  v_def text;
  v_old text := $o$    if v_event.type = 'invoice_payment' then
      delete from public.ledger_entries
        where id = (select credit_ledger_id from public.invoice_matches
                     where event_id = v_event.id);
      delete from public.invoice_matches where event_id = v_event.id;
      delete from public.ledger_entries
        where id in (select credit_ledger_id
                       from public.invoice_match_payments
                      where event_id = v_event.id
                        and credit_ledger_id is not null);
      delete from public.invoice_match_payments
        where event_id = v_event.id;
    end if;$o$;
  v_new text := $n$    if v_event.type = 'invoice_payment' then
      -- #816 — ONE release, shared with the expiry sweep.
      perform public.release_invoice_payment(v_event.id);
    end if;$n$;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'respond_to_event';
  if v_def is null then raise exception 'respond_to_event missing'; end if;
  if position('release_invoice_payment' in v_def) > 0 then
    raise notice 'respond_to_event already releases through the helper';
    return;
  end if;
  if position(v_old in v_def) = 0 then
    raise exception '0144: respond_to_event reject block not found — body drifted';
  end if;
  execute replace(v_def, v_old, v_new);
end $patch$;

-- sweep_pending_events v2: the money events it expires are released
-- exactly as a reject releases them.
create or replace function public.sweep_pending_events(p_workspace_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_id uuid;
begin
  if not public.is_member_of(p_workspace_id) then
    raise exception 'not a member';
  end if;
  -- non-destructive (creations/modifications): auto-confirm
  insert into public.event_decisions (event_id, member_id, decision, decided_by_system)
  select e.id, null, 'accept', true from public.events e
    where e.workspace_id = p_workspace_id and e.status = 'pending'
      and e.action in ('created','modified')
      and e.created_at < now() - interval '7 days';
  update public.events
    set status = 'confirmed', decided_at = now()
    where workspace_id = p_workspace_id and status = 'pending'
      and action in ('created','modified')
      and created_at < now() - interval '7 days';
  -- destructive (cancellations) or debits: auto-expire and undo tentative
  update public.reservations r set status = 'cancelled'
    from public.events e
    where e.workspace_id = p_workspace_id and e.status = 'pending'
      and e.action not in ('created','modified')
      and e.created_at < now() - interval '7 days'
      and r.id = e.reservation_id and r.status in ('reserved','checked_in');
  -- #816 — an expired invoice_payment releases what it held, like a reject.
  for v_id in
    select e.id from public.events e
     where e.workspace_id = p_workspace_id and e.status = 'pending'
       and e.type = 'invoice_payment'
       and e.action not in ('created','modified')
       and e.created_at < now() - interval '7 days'
  loop
    perform public.release_invoice_payment(v_id);
  end loop;
  insert into public.event_decisions (event_id, member_id, decision, decided_by_system)
  select e.id, null, 'reject', true from public.events e
    where e.workspace_id = p_workspace_id and e.status = 'pending'
      and e.action not in ('created','modified')
      and e.created_at < now() - interval '7 days';
  update public.events
    set status = 'expired', decided_at = now()
    where workspace_id = p_workspace_id and status = 'pending'
      and action not in ('created','modified')
      and created_at < now() - interval '7 days';
end;
$$;
revoke execute on function public.sweep_pending_events(uuid) from public, anon;

-- ---------------------------------------------------------------- 5+3. void_invoice v3
create or replace function public.void_invoice(p_invoice_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_invoice public.invoices;
  v_actor public.members;
  v_actor_name text;
begin
  select * into v_invoice from public.invoices where id = p_invoice_id;
  if v_invoice.id is null then raise exception 'unknown invoice'; end if;
  if exists (select 1 from public.invoice_matches
              where invoice_id = p_invoice_id) then
    -- 0068: a paid (or awaiting-validation) invoice is definitive.
    raise exception 'invoice is matched';
  end if;
  -- #816 — a source folded into a settlement is owed THROUGH the
  -- settlement; correct the settlement, not the source.
  if v_invoice.settled_by_invoice_id is not null then
    raise exception 'invoice is settled';
  end if;
  v_actor := public.issuing_member(v_invoice.workspace_id);
  if v_invoice.voided_at is not null then
    raise exception 'invoice already voided';
  end if;
  select coalesce(display_name, '') into v_actor_name
    from public.profiles where id = v_actor.user_id;
  update public.invoices
     set voided_at = now(), voided_by_name = v_actor_name
   where id = p_invoice_id;
  -- #816 — voiding a settlement releases its sources: they are owed
  -- separately again and dunning sees them again.
  if v_invoice.kind = 'settlement' then
    update public.invoices set settled_by_invoice_id = null
      where settled_by_invoice_id = p_invoice_id;
  end if;
end;
$$;
revoke execute on function public.void_invoice(uuid) from public, anon;
grant execute on function public.void_invoice(uuid) to authenticated;

-- ---------------------------------------------------------------- 5+6. record_invoice_reminder v2
create or replace function public.record_invoice_reminder(
  p_invoice_id uuid
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_invoice public.invoices;
  v_actor public.members;
  v_actor_name text;
  v_rules jsonb;
  v_levels int;
  v_first int;
  v_count int;
  v_level int;
  v_event_id uuid;
  v_cfg public.push_config;
begin
  select * into v_invoice from public.invoices where id = p_invoice_id;
  if v_invoice.id is null then raise exception 'unknown invoice'; end if;
  if v_invoice.voided_at is not null then
    raise exception 'invoice is voided';
  end if;
  v_actor := public.issuing_member(v_invoice.workspace_id);
  select coalesce(display_name, '') into v_actor_name
    from public.profiles where id = v_actor.user_id;
  -- #816 — the level of THIS send, the way the sweep and the client
  -- letter count it: one past what was already sent, capped at the
  -- configured maximum (extra sends reuse the last level).
  select coalesce(w.dunning_rules, '{}'::jsonb) into v_rules
    from public.workspaces w where w.id = v_invoice.workspace_id;
  v_levels := least(greatest(coalesce((v_rules ->> 'levels')::int, 3), 1), 9);
  v_first := least(greatest(coalesce((v_rules ->> 'first_after_days')::int, 14), 1), 365);
  select count(*) into v_count
    from public.invoice_reminders r where r.invoice_id = p_invoice_id;
  v_level := least(v_count + 1, v_levels);
  insert into public.invoice_reminders
    (workspace_id, invoice_id, by_name, automatic, level)
  values (v_invoice.workspace_id, p_invoice_id, v_actor_name, false, v_level);
  -- The SAME feed entry the automatic sweep files (0134): the member
  -- learns of a manual reminder too.
  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id, payload, status)
  values
    (v_invoice.workspace_id, 'invoice_reminder', 'created', v_actor.id,
     v_invoice.member_id,
     jsonb_build_object(
       'invoice_id', v_invoice.id,
       'number', v_invoice.number,
       'level', v_level,
       'levels', v_levels,
       'amount_cents', v_invoice.total_cents,
       'currency', v_invoice.currency,
       'issued_at', v_invoice.issued_at,
       'days_overdue', greatest(0, (extract(epoch from now() - v_invoice.issued_at) / 86400)::int - v_first),
       'automatic', false),
     'applied')
  returning id into v_event_id;
  select * into v_cfg from public.push_config where id;
  if v_cfg.functions_url is not null then
    begin
      perform net.http_post(
        url := v_cfg.functions_url || '/send-push',
        headers := jsonb_build_object(
          'Authorization', 'Bearer ' || v_cfg.anon_key,
          'Content-Type', 'application/json'),
        body := jsonb_build_object('event_id', v_event_id),
        timeout_milliseconds := 5000);
    exception when others then
      null;
    end;
  end if;
end;
$$;
revoke execute on function public.record_invoice_reminder(uuid)
  from public, anon;
grant execute on function public.record_invoice_reminder(uuid) to authenticated;

-- ---------------------------------------------------------------- 5. settle_credit_invoice v2
create or replace function public.settle_credit_invoice(
  p_invoice_id uuid, p_note text default ''
) returns void language plpgsql security definer set search_path = public as $$
declare
  v_invoice public.invoices;
  v_actor public.members;
  v_actor_name text;
  v_note text := btrim(coalesce(p_note, ''));
  v_has_policy boolean;
  v_event_id uuid;
  v_payout_id uuid;
  v_amount int;
begin
  select * into v_invoice from public.invoices where id = p_invoice_id;
  if v_invoice.id is null then raise exception 'unknown invoice'; end if;
  if v_invoice.voided_at is not null then
    raise exception 'invoice is voided';
  end if;
  if v_invoice.total_cents >= 0 then
    raise exception 'not a credit note';
  end if;
  if exists (select 1 from public.invoice_matches
              where invoice_id = p_invoice_id) then
    raise exception 'invoice already matched';
  end if;
  v_actor := public.issuing_member(v_invoice.workspace_id);

  v_amount := -v_invoice.total_cents;
  select coalesce(display_name, '') into v_actor_name
    from public.profiles where id = v_actor.user_id;

  insert into public.ledger_entries
    (workspace_id, member_id, kind, category, amount_cents,
     description, period)
  values
    (v_invoice.workspace_id, v_invoice.member_id, 'charge',
     'adjustment', v_amount,
     'Refund ' || v_invoice.number
       || case when v_note = '' then '' else ' — ' || v_note end,
     to_char(now(), 'YYYY-MM'))
  returning id into v_payout_id;

  v_has_policy := exists (
    select 1 from public.validation_policies vp
    where vp.workspace_id = v_invoice.workspace_id
      and vp.event_type = 'invoice_payment');

  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id,
     payload, status, decided_at)
  values
    (v_invoice.workspace_id, 'invoice_payment', 'submitted',
     v_actor.id, v_invoice.member_id,
     jsonb_build_object(
       'invoice_id', v_invoice.id,
       'number', v_invoice.number,
       'due_cents', v_invoice.total_cents,
       'paid_cents', v_amount,
       'amount_cents', v_amount,
       'resolution', 'refunded',
       'note', v_note),
     case when v_has_policy then 'pending' else 'confirmed' end,
     case when v_has_policy then null else now() end)
  returning id into v_event_id;

  insert into public.invoice_matches
    (workspace_id, invoice_id, paid_cents, resolution, note, status,
     event_id, credit_ledger_id, by_name)
  values
    (v_invoice.workspace_id, p_invoice_id, v_amount, 'refunded',
     v_note, case when v_has_policy then 'pending' else 'confirmed' end,
     v_event_id, v_payout_id, v_actor_name);
end;
$$;
revoke execute on function
  public.settle_credit_invoice(uuid, text) from public, anon;
grant execute on function
  public.settle_credit_invoice(uuid, text) to authenticated;

-- ---------------------------------------------------------------- 5. request_invoice_writeoff v2
create or replace function public.request_invoice_writeoff(
  p_invoice_id uuid, p_reason text default ''
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_invoice public.invoices;
  v_match public.invoice_matches;
  v_actor public.members;
  v_id uuid;
begin
  select * into v_invoice from public.invoices where id = p_invoice_id;
  if v_invoice.id is null then raise exception 'unknown invoice'; end if;
  -- #816 — the same permission as every other invoicing act; the
  -- message the client already maps.
  begin
    v_actor := public.issuing_member(v_invoice.workspace_id);
  exception when others then
    raise exception 'only admins may cancel outstanding amounts';
  end;
  select * into v_match from public.invoice_matches
    where invoice_id = p_invoice_id;
  if v_match.invoice_id is null or v_match.status <> 'confirmed'
     or v_match.resolution <> 'under_accepted' then
    raise exception 'no partially paid match to write off';
  end if;
  if v_match.writeoff_at is not null then
    raise exception 'remainder already cancelled';
  end if;
  if exists (select 1 from public.events
              where type = 'invoice_writeoff' and status = 'pending'
                and (payload->>'invoice_id')::uuid = p_invoice_id) then
    raise exception 'write-off already requested';
  end if;
  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id,
     payload, status)
  values (
    v_invoice.workspace_id, 'invoice_writeoff', 'submitted',
    v_actor.id, v_invoice.member_id,
    jsonb_build_object(
      'invoice_id', v_invoice.id,
      'number', v_invoice.number,
      'amount_cents', v_invoice.total_cents - v_match.paid_cents,
      'reason', left(coalesce(p_reason, ''), 300)
    ),
    'pending'
  )
  returning id into v_id;
  return v_id;
end;
$$;
revoke execute on function
  public.request_invoice_writeoff(uuid, text) from public, anon;
grant execute on function
  public.request_invoice_writeoff(uuid, text) to authenticated;

-- ---------------------------------------------------------------- 5+3. create_invoice (in place)
do $patch$
declare
  v_def text;
  v_old_gate text := $o$    select * into v_actor from public.members
      where workspace_id = p_workspace_id and user_id = auth.uid()
        and status = 'active' and (is_admin or is_owner);
    if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;$o$;
  v_new_gate text := $n$    -- #816 — the matrix alone decides who issues.
    v_actor := public.issuing_member(p_workspace_id);$n$;
  v_old_replace text := $o$    if exists (select 1 from public.invoice_matches
                where invoice_id = p_replaces) then
      raise exception 'invoice is matched';
    end if;$o$;
  v_new_replace text := $n$    if exists (select 1 from public.invoice_matches
                where invoice_id = p_replaces) then
      raise exception 'invoice is matched';
    end if;
    if v_replaced.settled_by_invoice_id is not null then
      raise exception 'invoice is settled';
    end if;$n$;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'create_invoice';
  if v_def is null then raise exception 'create_invoice missing'; end if;
  if position('issuing_member' in v_def) > 0 then
    raise notice 'create_invoice already gates through issuing_member';
    return;
  end if;
  if position(v_old_gate in v_def) = 0 then
    raise exception '0144: create_invoice gate not found — body drifted';
  end if;
  if position(v_old_replace in v_def) = 0 then
    raise exception '0144: create_invoice replace guard not found — body drifted';
  end if;
  v_def := replace(v_def, v_old_gate, v_new_gate);
  v_def := replace(v_def, v_old_replace, v_new_replace);
  execute v_def;
end $patch$;

-- ---------------------------------------------------------------- 5+3. match_invoice (in place)
do $patch$
declare
  v_def text;
  v_old_gate text := $o$  select * into v_actor from public.members
    where workspace_id = v_invoice.workspace_id and user_id = auth.uid()
      and status = 'active' and (is_admin or is_owner);
  if v_actor.id is null then raise exception 'not an admin of this workspace'; end if;$o$;
  v_new_gate text := $n$  -- #816 — the matrix alone decides who matches.
  v_actor := public.issuing_member(v_invoice.workspace_id);$n$;
  v_old_void text := $o$  if v_invoice.voided_at is not null then
    raise exception 'invoice is voided';
  end if;
  select * into v_existing from public.invoice_matches$o$;
  v_new_void text := $n$  if v_invoice.voided_at is not null then
    raise exception 'invoice is voided';
  end if;
  if v_invoice.settled_by_invoice_id is not null then
    raise exception 'invoice is settled';
  end if;
  select * into v_existing from public.invoice_matches$n$;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'match_invoice';
  if v_def is null then raise exception 'match_invoice missing'; end if;
  if position('issuing_member' in v_def) > 0 then
    raise notice 'match_invoice already gates through issuing_member';
    return;
  end if;
  if position(v_old_gate in v_def) = 0 then
    raise exception '0144: match_invoice gate not found — body drifted';
  end if;
  if position(v_old_void in v_def) = 0 then
    raise exception '0144: match_invoice void guard not found — body drifted';
  end if;
  v_def := replace(v_def, v_old_gate, v_new_gate);
  v_def := replace(v_def, v_old_void, v_new_void);
  execute v_def;
end $patch$;

-- ---------------------------------------------------------------- 2. settle_invoices v2
create or replace function public.settle_invoices(
  p_workspace_id uuid,
  p_member_id uuid,
  p_invoice_ids uuid[],
  p_note text default ''
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_actor public.members;
  v_subject public.members;
  v_workspace public.workspaces;
  v_latest public.invoices;
  v_lines jsonb := '[]'::jsonb;
  v_settles jsonb := '[]'::jsonb;
  v_total int := 0;
  v_count int;
  v_number text;
  v_id uuid;
  v_signature text;
  v_issuer_name text;
  v_src public.invoices;
  v_n int := 0;
  v_has_policy boolean;
begin
  -- #816 — the matrix alone decides; the feature must be on.
  v_actor := public.issuing_member(p_workspace_id);
  select * into v_workspace from public.workspaces where id = p_workspace_id;
  if not coalesce((v_workspace.feature_flags ->> 'invoiceSettlement')::boolean, true) then
    raise exception 'invoice settlement is not enabled';
  end if;

  select * into v_subject from public.members
    where id = p_member_id and workspace_id = p_workspace_id
      and status = 'active' and not is_kiosk;
  if v_subject.id is null then raise exception 'unknown subject member'; end if;

  if p_invoice_ids is null or array_length(p_invoice_ids, 1) is null
     or array_length(p_invoice_ids, 1) < 2 then
    raise exception 'settle at least two invoices';
  end if;

  perform pg_advisory_xact_lock(hashtext(p_workspace_id::text));

  for v_src in
    select * from public.invoices
     where id = any(p_invoice_ids)
     order by issued_at, number
  loop
    v_n := v_n + 1;
    if v_src.workspace_id <> p_workspace_id then
      raise exception 'invoice % is not in this workspace', v_src.number;
    end if;
    if v_src.member_id <> p_member_id then
      raise exception 'invoice % belongs to another member', v_src.number;
    end if;
    if v_src.voided_at is not null then
      raise exception 'invoice % is void', v_src.number;
    end if;
    if v_src.settled_by_invoice_id is not null then
      raise exception 'invoice % is already settled', v_src.number;
    end if;
    if v_src.kind = 'settlement' then
      raise exception 'invoice % is itself a settlement', v_src.number;
    end if;
    if exists (select 1 from public.invoice_matches m
                where m.invoice_id = v_src.id) then
      raise exception 'invoice % already has a payment', v_src.number;
    end if;

    v_total := v_total + v_src.total_cents;
    v_lines := v_lines || jsonb_build_object(
      'kind', 'settled_invoice',
      'label', v_src.number,
      'quantity', 1,
      'vat_percent', 0,
      'amount_cents', v_src.total_cents);
    v_settles := v_settles || jsonb_build_object(
      'invoice_id', v_src.id,
      'number', v_src.number,
      'period', v_src.period,
      'kind', v_src.kind,
      'issued_at', v_src.issued_at,
      'total_cents', v_src.total_cents,
      'currency', v_src.currency,
      'lines', v_src.lines,
      'vat_totals', v_src.vat_totals);
    v_latest := v_src;
  end loop;

  if v_n <> array_length(p_invoice_ids, 1) then
    raise exception 'unknown invoice in the selection';
  end if;

  select coalesce(display_name, '') into v_issuer_name
    from public.profiles where id = v_actor.user_id;

  select count(*) into v_count from public.invoices
    where workspace_id = p_workspace_id
      and date_part('year', issued_at) = date_part('year', now());
  v_number := 'INV-' || date_part('year', now())::int || '-'
      || lpad((v_count + 1)::text, 4, '0');

  v_id := gen_random_uuid();
  v_signature := encode(extensions.digest(convert_to(concat_ws('|',
      v_id::text, v_number, p_workspace_id::text, v_subject.id::text,
      v_lines::text, v_total::text, v_settles::text,
      now()::date::text, 'settlement'),
      'UTF8'), 'sha256'), 'hex');

  insert into public.invoices
    (id, workspace_id, member_id, issuer_member_id, number, period, title,
     lines, total_cents, currency, member_name, member_address,
     workspace_name, workspace_address, issuer_name, signature,
     parties, vat_totals, kind, settles)
  values
    (v_id, p_workspace_id, p_member_id, v_actor.id, v_number,
     null, coalesce(nullif(p_note, ''), v_number),
     v_lines, v_total, v_latest.currency,
     v_latest.member_name, v_latest.member_address,
     v_latest.workspace_name, v_latest.workspace_address,
     v_issuer_name, v_signature,
     v_latest.parties,
     '[]'::jsonb, 'settlement', v_settles);

  update public.invoices
     set settled_by_invoice_id = v_id
   where id = any(p_invoice_ids);

  -- #816 — the SAME rule every other invoice_payment obeys: a policy on
  -- the domain makes the regrouping wait for the validators (the sources
  -- are already held, like a pending match); a reject voids the
  -- settlement and releases them. No policy: confirmed on the spot, but
  -- never 'applied' by its own author.
  v_has_policy := exists (
    select 1 from public.validation_policies vp
    where vp.workspace_id = p_workspace_id
      and vp.event_type = 'invoice_payment');
  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id,
     payload, status, decided_at)
  values
    (p_workspace_id, 'invoice_payment', 'submitted', v_actor.id, p_member_id,
     jsonb_build_object(
       'invoice_id', v_id, 'number', v_number, 'kind', 'settlement',
       'amount_cents', v_total, 'currency', v_latest.currency,
       'settled_count', v_n,
       'settled_numbers', (select jsonb_agg(s->>'number')
                             from jsonb_array_elements(v_settles) s)),
     case when v_has_policy then 'pending' else 'confirmed' end,
     case when v_has_policy then null else now() end);

  return v_id;
end;
$$;
revoke execute on function
  public.settle_invoices(uuid, uuid, uuid[], text) from public, anon;
grant execute on function
  public.settle_invoices(uuid, uuid, uuid[], text) to authenticated;

