-- Copyright (c) 2026 Florian DITTGEN
-- SPDX-License-Identifier: 0BSD
--
-- #840 — the configured validation rule must actually hold.
--
-- Three holes sat around a sound rule. `respond_to_event` has refused the
-- actor since 0086 and still does, so nobody validates an event they
-- created. But:
--
--   1. The four money operations that write their own event
--      (match_invoice, settle_credit_invoice, settle_invoices,
--      distribute_expense) looked for a policy row of their exact type
--      and nothing else. A workspace-wide default rule governed every
--      other event and not those, so marking an invoice paid, refunding
--      it or regrouping it stayed confirmed on the spot by its author.
--      They now consult the default row too.
--
--   2. `v_required` was clamped to the size of the eligible pool. A rule
--      asking for two validations quietly became one whenever the pool
--      shrank to a single person. The configured number now holds; a
--      pool too small to reach it leaves the event pending until it
--      expires, which is the safe outcome, not a silent downgrade.
--
--   3. There was no way to say whether the owner may sign off on their
--      own act. `owner_may_self_validate` says it, and it is the only
--      exception: false by default, and never available to an admin.
--
-- `sequential` asks for the validations one at a time. Each accept that
-- does not complete the quorum raises `payload.validation_stage`, so the
-- next validator is asked for a numbered step instead of joining an
-- open quorum.

alter table public.validation_policies
  add column if not exists owner_may_self_validate boolean not null default false,
  add column if not exists sequential boolean not null default false;

comment on column public.validation_policies.owner_may_self_validate is
  '#840 — the owner, and only the owner, may validate their own event.';
comment on column public.validation_policies.sequential is
  '#840 — validations are requested one after another, not as one quorum.';

-- The money RPCs: a workspace default rule governs them too.
do $patch$
declare
  v_name text;
  v_type text;
  v_def text;
  v_new text;
begin
  for v_name, v_type in
    select * from (values
      ('match_invoice', 'invoice_payment'),
      ('settle_credit_invoice', 'invoice_payment'),
      ('settle_invoices', 'invoice_payment'),
      ('distribute_expense', 'expense_repartition')) as t(n, y)
  loop
    select pg_get_functiondef(p.oid) into v_def
      from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public' and p.proname = v_name;
    if v_def is null then
      raise exception 'missing %', v_name;
    end if;
    if position('vp.event_type = ''' || v_type || '''' in v_def) = 0 then
      raise exception '% no longer looks up a % policy', v_name, v_type;
    end if;
    v_new := replace(v_def,
      'vp.event_type = ''' || v_type || ''')',
      '(vp.event_type = ''' || v_type || ''' or vp.event_type is null))');
    if v_new = v_def then
      raise exception '% policy lookup did not change', v_name;
    end if;
    execute v_new;
  end loop;
end;
$patch$;

-- respond_to_event: the owner exception, and the count that holds.
do $patch$
declare
  v_def text;
  v_new text;
  v_actor_guard constant text := 'v_caller.id <> v_event.actor_member_id';
  v_owner_ok constant text :=
    '(v_caller.id <> v_event.actor_member_id'
    || ' or (v_caller.is_owner'
    || ' and coalesce(v_policy.owner_may_self_validate, false)))';
  v_clamp constant text :=
    'v_required := greatest(1, least(v_policy.required_count,' || E'\n'
    || '    v_pool_size + case when v_subject_decides then 1 else 0 end));';
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'respond_to_event';
  if v_def is null then
    raise exception 'respond_to_event is missing';
  end if;
  if position('owner_may_self_validate' in v_def) > 0 then
    return;  -- already patched
  end if;
  if (length(v_def) - length(replace(v_def, v_actor_guard, '')))
     / length(v_actor_guard) <> 2 then
    raise exception 'expected exactly two self-validation guards';
  end if;
  if position(v_clamp in v_def) = 0 then
    raise exception 'the required-count clamp is not where it was';
  end if;

  -- The no-row fallback builds v_policy by hand: it has to carry the new
  -- fields, or reading them raises "record has no field".
  v_new := replace(v_def,
    'false as owner_required, ''admins''::text as validator_scope',
    'false as owner_required, ''admins''::text as validator_scope,' || E'\n'
    || '           false as owner_may_self_validate, false as sequential');
  if v_new = v_def then
    raise exception 'the no-policy fallback is not where it was';
  end if;
  v_new := replace(v_new, v_actor_guard, v_owner_ok);
  v_new := replace(v_new, v_clamp,
    '-- #840 — the configured number holds.' || E'\n'
    || '  v_required := greatest(1, v_policy.required_count);');
  -- #840 — sequential rules number the step that is now being asked for.
  v_new := replace(v_new,
    'select count(*) into v_accepts from public.event_decisions' || E'\n'
    || '    where event_id = p_event_id and decision = ''accept'';',
    'select count(*) into v_accepts from public.event_decisions' || E'\n'
    || '    where event_id = p_event_id and decision = ''accept'';' || E'\n'
    || '  if coalesce(v_policy.sequential, false) then' || E'\n'
    || '    update public.events set payload = payload' || E'\n'
    || '      || jsonb_build_object(''validation_stage'', v_accepts + 1)' || E'\n'
    || '     where id = p_event_id;' || E'\n'
    || '  end if;');
  if v_new = v_def then
    raise exception 'respond_to_event did not change';
  end if;
  execute v_new;
end;
$patch$;

-- Copyright (c) 2026 Florian DITTGEN
-- SPDX-License-Identifier: 0BSD
--
-- #843 — the calendar carried eleven kinds and none of them was a
-- validation. A decision that released or refused an invoice, a refund
-- or a deletion left no mark on the timeline: the alert said an event
-- had happened, the calendar never said when somebody decided about it.
--
-- A validation item sits at the MOMENT OF THE DECISION, not at the
-- moment of the event, which is the whole point — the two are often days
-- apart, and "when was this released" is the question being asked.
--
-- Patched in place (pg_get_functiondef + replace, anchors asserted): the
-- body is long and its access rules must not be retyped. The rules are
-- unchanged here — a validation is visible to exactly whoever could see
-- the event it decided.
do $patch$
declare
  v_def text;
  v_new text;
  v_old_want text := $o$'due','scheduled']);$o$;
  v_new_want text := $n$'due','scheduled','validation']);$n$;
  -- The deployed body carries no comments (0145 patched it through
  -- pg_get_functiondef), so the anchor has to be code.
  v_anchor text := $a$  if 'message' = any(v_want) then$a$;
  v_branch text := $b$  -- #843 validations: the decision, at the moment it was taken.
  -- Same reach as the event it decided; a decision nobody may see is
  -- not listed, and 'locked' says so.
  if 'validation' = any(v_want) then
    select coalesce(jsonb_agg(jsonb_build_object(
      'kind', 'validation', 'id', d.id, 'at', d.decided_at,
      'member_id', d.member_id,
      'title', e.type || '.' || case when d.decision = 'accept'
                 then 'validated' else 'refused' end,
      'status', d.decision,
      'payload', jsonb_build_object(
        'event_id', e.id, 'event_type', e.type, 'event_action', e.action,
        'by_system', d.decided_by_system,
        'subject_member_id', e.subject_member_id),
      'link', jsonb_build_object('type','event','id', e.id))
      order by d.decided_at), '[]'::jsonb)
      into v_rows
      from public.event_decisions d
      join public.events e on e.id = d.event_id
     where e.workspace_id = p_workspace_id
       and d.decided_at >= p_from and d.decided_at < p_to
       and (e.actor_member_id = v_subject or e.subject_member_id = v_subject
            or d.member_id = v_subject)
       and (v_admin or e.actor_member_id = v_me.id
            or e.subject_member_id = v_me.id or d.member_id = v_me.id);
    v_items := v_items || v_rows;
  end if;

$b$;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'calendar_items';
  if v_def is null then
    raise exception 'calendar_items is missing — 0133/0145 must run first';
  end if;
  if position('''validation''' in v_def) > 0 then
    return;  -- already patched
  end if;
  if position(v_old_want in v_def) = 0 then
    raise exception 'the default kind list is not where 0145 left it';
  end if;
  if position(v_anchor in v_def) = 0 then
    raise exception 'the messages branch is not where 0133 left it';
  end if;
  v_new := replace(v_def, v_old_want, v_new_want);
  v_new := replace(v_new, v_anchor, v_branch || v_anchor);
  if v_new = v_def then
    raise exception 'calendar_items did not change';
  end if;
  execute v_new;
end;
$patch$;

-- Copyright (c) 2026 Florian DITTGEN
-- SPDX-License-Identifier: 0BSD
--
-- #833 — a check-out leaves a trace, and the trace is readable.
--
-- Until now a check-out closed the reservation and the month's statement
-- counted what it counted. Which reservation a line came from, how long
-- the member was actually there, whether they turned up at all, whether
-- they left early — none of it was anything a member, an admin or an
-- owner could open and read.
--
-- Three things this settles, and one of them is already true today:
--
--   * A RESERVATION THAT WAS NEVER CHECKED INTO STILL BILLS. That is
--     already the behaviour — reservation_counts_for_usage (0118) never
--     looked at checked_in_at — but nothing said so out loud. The record
--     says it: reserved minutes counted, nobody came.
--
--   * WHAT BILLS IS THE RESERVED WINDOW. Booking is the commitment; a
--     short visit is not a discount. The record keeps the actual
--     presence beside it so the two can be compared.
--
--   * AN EARLY DEPARTURE CAN BE CORRECTED, through the validation
--     framework and never by the person asking. Accepting one moves the
--     RESERVATION'S OWN END to the moment of check-out, so the statement,
--     the quota and every derived line follow with no change to the
--     billing engine at all — and the record keeps the original window,
--     so both numbers stay readable side by side.
--
-- Writing the record is a TRIGGER on reservations rather than a patch to
-- complete_check_out and kiosk_act, because there are two check-out
-- paths today and the next one would silently write no record.
--
-- ONE EXISTING BEHAVIOUR HAD TO GO. complete_check_out (0116) shrank the
-- booking to the moment of check-out — `ends_at = least(ends_at, now())`
-- — so an early departure already reduced the bill, silently, with
-- nobody asked and the booked window destroyed. That is the opposite of
-- what #833 describes, and it made this correction impossible: there
-- would be no original left to correct FROM. Check-out now records the
-- departure and leaves the booking alone. Leaving early costs what was
-- booked until somebody validates otherwise — the same rule a no-show
-- already lived under.

-- Check-out v3: record the departure, keep the commitment.
create or replace function public.complete_check_out(p_reservation_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_res public.reservations;
  v_start timestamptz;
begin
  select r.* into v_res from public.reservations r where r.id = p_reservation_id;
  if v_res.id is null then return; end if;
  -- The completed row must still describe a forward-running presence: an
  -- early same-day check-in (0113) can sit BEFORE starts_at, and that
  -- widening stays. What is gone is the narrowing of ends_at.
  v_start := least(v_res.starts_at, coalesce(v_res.checked_in_at, now()));
  update public.reservations
     set status = 'completed', checked_out_at = now(), starts_at = v_start
   where id = p_reservation_id;
end;
$$;
revoke execute on function public.complete_check_out(uuid)
  from public, anon, authenticated;

create table if not exists public.usage_records (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  member_id uuid not null references public.members(id) on delete cascade,
  reservation_id uuid unique references public.reservations(id) on delete cascade,
  period text not null,
  -- The window as it was RESERVED. A correction never rewrites these.
  reserved_from timestamptz not null,
  reserved_to timestamptz not null,
  checked_in_at timestamptz,
  checked_out_at timestamptz,
  -- What bills, in minutes. Starts as the reserved window.
  counted_minutes int not null,
  reserved_minutes int not null,
  -- Time actually present; null when nobody checked in.
  actual_minutes int,
  basis text not null default 'reserved'
    check (basis in ('reserved', 'corrected')),
  corrected_from_minutes int,
  corrected_at timestamptz,
  corrected_event_id uuid references public.events(id) on delete set null,
  space_label text not null default '',
  created_at timestamptz not null default now()
);

comment on table public.usage_records is
  '#833 — one row per counted reservation: reserved window, actual '
  'presence, what bills, and how a correction changed it.';

create index if not exists usage_records_member_period_idx
  on public.usage_records (member_id, period);
create index if not exists usage_records_workspace_period_idx
  on public.usage_records (workspace_id, period);

alter table public.usage_records enable row level security;

-- Everything is written through the SECURITY DEFINER functions below;
-- the policy exists so a direct read can never see somebody else's
-- presence. Money-visibility is the same gate the statement uses.
drop policy if exists usage_records_read on public.usage_records;
create policy usage_records_read on public.usage_records
  for select using (
    exists (select 1 from public.members m
             where m.id = usage_records.member_id
               and m.user_id = auth.uid())
    or public.may_view_member_finances(usage_records.member_id));

grant select on public.usage_records to authenticated;

-- Two new decided events: the member asking for their early departure to
-- count, and an admin removing a record.
alter table public.events drop constraint if exists events_type_check;
alter table public.events add constraint events_type_check
  check (type = any (array[
    'reservation', 'payment', 'expense', 'adjustment', 'service_charge',
    'quota', 'role_change', 'member_join', 'space_reservation',
    'invoice_payment', 'reservation_delete', 'invoice_writeoff',
    'invoice_reminder', 'price_negotiation', 'expense_schedule',
    'expense_repartition', 'usage_correction', 'usage_record_delete']));

-- The policy list had drifted from the event list: 0147 rebuilt it and
-- dropped 'expense_schedule', so a rule could not be configured for a
-- type that emits events. Both lists are written here, together, from
-- the same source.
alter table public.validation_policies
  drop constraint if exists validation_policies_event_type_check;
alter table public.validation_policies
  add constraint validation_policies_event_type_check
  check (event_type is null or event_type = any (array[
    'reservation', 'payment', 'expense', 'adjustment', 'service_charge',
    'quota', 'role_change', 'member_join', 'space_reservation',
    'invoice_payment', 'reservation_delete', 'invoice_writeoff',
    'invoice_reminder', 'price_negotiation', 'expense_schedule',
    'expense_repartition', 'usage_correction', 'usage_record_delete']));

-- A deletion is the ADMIN's act on the MEMBER's record, so the member is
-- the one who decides it — the same shape a payment recorded on someone
-- else's behalf already has.
do $patch$
declare
  v_def text;
  v_new text;
  v_old constant text :=
    '  v_subject_decides := v_event.type = ''reservation''' || E'\n'
    || '    or (v_event.type in (''payment'',''service_charge'')';
  v_ins constant text :=
    '  v_subject_decides := v_event.type = ''reservation''' || E'\n'
    || '    or (v_event.type in (''payment'',''service_charge'',''usage_record_delete'')';
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'respond_to_event';
  if v_def is null then
    raise exception 'respond_to_event is missing';
  end if;
  if position('usage_record_delete' in v_def) > 0 then
    return;
  end if;
  if position(v_old in v_def) = 0 then
    raise exception 'the subject-decides rule is not where 0086 left it';
  end if;
  v_new := replace(v_def, v_old, v_ins);
  if v_new = v_def then
    raise exception 'respond_to_event did not change';
  end if;
  execute v_new;
end;
$patch$;

-- The record, written or refreshed for one reservation.
create or replace function public.upsert_usage_record(p_reservation_id uuid)
returns uuid language plpgsql security definer
set search_path = public as $$
declare
  v_res public.reservations;
  v_rules jsonb;
  v_tz text;
  v_actual int;
  v_reserved int;
  v_id uuid;
begin
  select * into v_res from public.reservations where id = p_reservation_id;
  if v_res.id is null then return null; end if;
  select booking_rules, timezone into v_rules, v_tz
    from public.workspaces where id = v_res.workspace_id;
  v_tz := coalesce(v_tz, 'UTC');
  -- The same predicate the statement and the quota use (0118): a booking
  -- that does not count for usage leaves no record either, or the two
  -- would disagree about the same month.
  if not public.reservation_counts_for_usage(
           v_res, coalesce(v_rules, '{}'::jsonb), v_tz) then
    return null;
  end if;
  if v_res.status not in ('reserved', 'checked_in', 'completed') then
    return null;
  end if;

  v_reserved := greatest(0, (extract(epoch from
    (v_res.ends_at - v_res.starts_at)) / 60)::int);
  v_actual := case
    when v_res.checked_in_at is null then null
    else greatest(0, (extract(epoch from
      (coalesce(v_res.checked_out_at, v_res.ends_at)
       - v_res.checked_in_at)) / 60)::int)
  end;

  insert into public.usage_records
    (workspace_id, member_id, reservation_id, period,
     reserved_from, reserved_to, checked_in_at, checked_out_at,
     counted_minutes, reserved_minutes, actual_minutes, space_label)
  values
    (v_res.workspace_id, v_res.member_id, v_res.id,
     to_char(v_res.starts_at at time zone v_tz, 'YYYY-MM'),
     v_res.starts_at, v_res.ends_at, v_res.checked_in_at,
     v_res.checked_out_at, v_reserved, v_reserved, v_actual,
     coalesce(v_res.space_label, ''))
  on conflict (reservation_id) do update
    set checked_in_at = excluded.checked_in_at,
        checked_out_at = excluded.checked_out_at,
        actual_minutes = excluded.actual_minutes,
        space_label = excluded.space_label,
        -- A corrected record keeps its counted time; an uncorrected one
        -- tracks the reservation, which a validated correction moves.
        counted_minutes = case
          when public.usage_records.basis = 'corrected'
            then public.usage_records.counted_minutes
          else excluded.reserved_minutes end,
        reserved_minutes = case
          when public.usage_records.basis = 'corrected'
            then public.usage_records.reserved_minutes
          else excluded.reserved_minutes end
  returning id into v_id;
  return v_id;
end;
$$;

create or replace function public.usage_record_on_reservation()
returns trigger language plpgsql security definer
set search_path = public as $$
begin
  -- Presence changed, or the booking did: refresh the trace either way.
  if new.checked_in_at is distinct from old.checked_in_at
     or new.checked_out_at is distinct from old.checked_out_at
     or new.status is distinct from old.status then
    perform public.upsert_usage_record(new.id);
  end if;
  return new;
end;
$$;

drop trigger if exists reservations_usage_record on public.reservations;
create trigger reservations_usage_record
  after update on public.reservations
  for each row execute function public.usage_record_on_reservation();

-- Backfill: every ENDED reservation of a period that has no record yet.
-- Lazy, like the pending-event sweep, so reading a month is enough to
-- make its no-shows appear.
create or replace function public.ensure_usage_records(
  p_workspace_id uuid, p_period text)
returns int language plpgsql security definer
set search_path = public as $$
declare
  v_tz text;
  v_n int := 0;
  v_res public.reservations;
begin
  select timezone into v_tz from public.workspaces where id = p_workspace_id;
  v_tz := coalesce(v_tz, 'UTC');
  for v_res in
    select r.* from public.reservations r
     where r.workspace_id = p_workspace_id
       and r.ends_at < now()
       and r.status in ('reserved', 'checked_in', 'completed')
       and to_char(r.starts_at at time zone v_tz, 'YYYY-MM') = p_period
       and not exists (select 1 from public.usage_records u
                        where u.reservation_id = r.id)
  loop
    if public.upsert_usage_record(v_res.id) is not null then
      v_n := v_n + 1;
    end if;
  end loop;
  return v_n;
end;
$$;

-- The read. One month, one member or everybody the caller may see.
create or replace function public.usage_records_for(
  p_workspace_id uuid, p_period text, p_member_id uuid default null)
returns jsonb language plpgsql security definer
set search_path = public as $$
declare
  v_me public.members;
  v_rows jsonb;
begin
  select m.* into v_me from public.members m
   where m.workspace_id = p_workspace_id and m.user_id = auth.uid()
     and m.status = 'active';
  if v_me.id is null then raise exception 'not a member'; end if;

  perform public.ensure_usage_records(p_workspace_id, p_period);

  select coalesce(jsonb_agg(to_jsonb(u) order by u.reserved_from desc),
                  '[]'::jsonb)
    into v_rows
    from public.usage_records u
   where u.workspace_id = p_workspace_id
     and u.period = p_period
     and (p_member_id is null or u.member_id = p_member_id)
     -- Own records always; anybody else's only through the money gate.
     and (u.member_id = v_me.id
          or public.may_view_member_finances(u.member_id));
  return jsonb_build_object('records', v_rows);
end;
$$;

-- "I left early — bill the time I was actually here."
create or replace function public.request_usage_correction(
  p_record_id uuid, p_reason text default '')
returns uuid language plpgsql security definer
set search_path = public as $$
declare
  v_rec public.usage_records;
  v_me public.members;
  v_has_policy boolean;
  v_event uuid;
begin
  select * into v_rec from public.usage_records where id = p_record_id;
  if v_rec.id is null then raise exception 'unknown usage record'; end if;
  select m.* into v_me from public.members m
   where m.workspace_id = v_rec.workspace_id and m.user_id = auth.uid()
     and m.status = 'active';
  if v_me.id is null then raise exception 'not a member'; end if;
  -- Only the person who was there may ask for their own presence to
  -- count. An admin correcting somebody else's time is a different act
  -- and does not exist.
  if v_me.id <> v_rec.member_id then
    raise exception 'only the member concerned may ask for this';
  end if;
  if v_rec.basis = 'corrected' then
    raise exception 'already corrected';
  end if;
  if v_rec.checked_out_at is null or v_rec.actual_minutes is null then
    raise exception 'no check-out to correct to';
  end if;
  if v_rec.actual_minutes >= v_rec.reserved_minutes then
    raise exception 'nothing to reduce';
  end if;
  if exists (select 1 from public.events e
              where e.type = 'usage_correction' and e.status = 'pending'
                and (e.payload->>'record_id')::uuid = p_record_id) then
    raise exception 'already requested';
  end if;

  v_has_policy := exists (
    select 1 from public.validation_policies vp
     where vp.workspace_id = v_rec.workspace_id
       and (vp.event_type = 'usage_correction' or vp.event_type is null));

  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id,
     reservation_id, payload, status, decided_at)
  values
    (v_rec.workspace_id, 'usage_correction', 'submitted', v_me.id, v_me.id,
     null,
     jsonb_build_object(
       'record_id', p_record_id,
       'reservation_id', v_rec.reservation_id,
       'from_minutes', v_rec.counted_minutes,
       'to_minutes', v_rec.actual_minutes,
       'reason', btrim(coalesce(p_reason, ''))),
     case when v_has_policy then 'pending' else 'confirmed' end,
     case when v_has_policy then null else now() end)
  returning id into v_event;

  -- No rule: the correction stands at once. #840 keeps the actor out of
  -- the decision either way — with a rule, somebody else decides.
  if not v_has_policy then
    perform public.apply_usage_correction(p_record_id, v_event);
  end if;
  return v_event;
end;
$$;

-- Applying one: the RESERVATION's end moves, so every aggregation that
-- already reads reservations follows without being touched.
create or replace function public.apply_usage_correction(
  p_record_id uuid, p_event_id uuid default null)
returns void language plpgsql security definer
set search_path = public as $$
declare
  v_rec public.usage_records;
begin
  select * into v_rec from public.usage_records where id = p_record_id;
  if v_rec.id is null or v_rec.basis = 'corrected' then return; end if;
  if v_rec.checked_out_at is null or v_rec.actual_minutes is null then
    return;
  end if;

  update public.usage_records
     set counted_minutes = v_rec.actual_minutes,
         corrected_from_minutes = v_rec.counted_minutes,
         basis = 'corrected',
         corrected_at = now(),
         corrected_event_id = p_event_id
   where id = p_record_id;

  -- The billed period IS the reservation. Moving its end is what makes
  -- the statement, the quota and the invoice lines agree with the record
  -- without a single one of them learning about usage records.
  if v_rec.reservation_id is not null then
    update public.reservations
       set ends_at = v_rec.checked_out_at
     where id = v_rec.reservation_id
       and ends_at > v_rec.checked_out_at;
  end if;
end;
$$;

-- An admin removing a record; the member concerned decides it when a
-- rule says so (respond_to_event's subject-decides path, patched above).
create or replace function public.request_usage_record_delete(
  p_record_id uuid, p_reason text default '')
returns uuid language plpgsql security definer
set search_path = public as $$
declare
  v_rec public.usage_records;
  v_me public.members;
  v_has_policy boolean;
  v_event uuid;
begin
  select * into v_rec from public.usage_records where id = p_record_id;
  if v_rec.id is null then raise exception 'unknown usage record'; end if;
  select m.* into v_me from public.members m
   where m.workspace_id = v_rec.workspace_id and m.user_id = auth.uid()
     and m.status = 'active';
  if v_me.id is null then raise exception 'not a member'; end if;
  if not (v_me.is_owner or v_me.is_admin) then
    raise exception 'not allowed';
  end if;

  v_has_policy := exists (
    select 1 from public.validation_policies vp
     where vp.workspace_id = v_rec.workspace_id
       and (vp.event_type = 'usage_record_delete' or vp.event_type is null));

  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id,
     payload, status, decided_at)
  values
    (v_rec.workspace_id, 'usage_record_delete', 'submitted', v_me.id,
     v_rec.member_id,
     jsonb_build_object(
       'record_id', p_record_id,
       'reservation_id', v_rec.reservation_id,
       'counted_minutes', v_rec.counted_minutes,
       'reason', btrim(coalesce(p_reason, ''))),
     case when v_has_policy then 'pending' else 'confirmed' end,
     case when v_has_policy then null else now() end)
  returning id into v_event;

  if not v_has_policy then
    delete from public.usage_records where id = p_record_id;
  end if;
  return v_event;
end;
$$;

create or replace function public.apply_usage_decision()
returns trigger language plpgsql security definer
set search_path = public as $$
begin
  if new.status = old.status then return new; end if;
  if new.type = 'usage_correction' and new.status = 'confirmed' then
    perform public.apply_usage_correction(
      (new.payload->>'record_id')::uuid, new.id);
  elsif new.type = 'usage_record_delete' and new.status = 'confirmed' then
    delete from public.usage_records
     where id = (new.payload->>'record_id')::uuid;
  end if;
  return new;
end;
$$;

drop trigger if exists events_apply_usage on public.events;
create trigger events_apply_usage
  after update on public.events
  for each row execute function public.apply_usage_decision();

revoke execute on function public.upsert_usage_record(uuid) from public, anon, authenticated;
revoke execute on function public.apply_usage_correction(uuid, uuid) from public, anon, authenticated;
revoke execute on function public.ensure_usage_records(uuid, text) from public, anon, authenticated;
grant execute on function public.usage_records_for(uuid, text, uuid) to authenticated;
grant execute on function public.request_usage_correction(uuid, text) to authenticated;
grant execute on function public.request_usage_record_delete(uuid, text) to authenticated;

-- SPDX-License-Identifier: 0BSD
-- 0153 — #887: managed profiles — a member an admin runs until the
-- person claims it with a bound invitation.
--
-- An association onboards people before they have the app: the admin
-- creates the member, books and invoices for them, manages their
-- subscription. Until now a member could not exist without an account
-- (members.user_id NOT NULL). From here a member may be MANAGED: no
-- user, the identity (the PersonalInfo wire keys of 0152) held in
-- managed_identity, created by an admin. The handover is a personal
-- invitation BOUND to that member: when the person — with an account
-- they may have created a minute ago — redeems the code,
-- join_workspace sets user_id, copies the identity into the EMPTY
-- fields of their own profile (the user owns the data from then on),
-- clears the managed copy, and raises the ordinary member_join
-- validation. Reservations, invoices, subscriptions and documents were
-- always keyed by the member id, so nothing moves.

-- 1. A member may exist without an account — but never without an admin.
alter table public.members alter column user_id drop not null;
alter table public.members
  add column if not exists managed_identity jsonb not null default '{}'::jsonb,
  add column if not exists managed_by uuid references auth.users(id) on delete set null,
  add column if not exists claimed_at timestamptz;
alter table public.members drop constraint if exists members_managed_has_admin;
alter table public.members add constraint members_managed_has_admin
  check (user_id is not null or managed_by is not null);

-- 2. An invitation may be bound to the member it hands over; one open
--    handover per member at a time.
alter table public.invitations
  add column if not exists member_id uuid references public.members(id) on delete cascade;
create unique index if not exists invitations_open_handover_idx
  on public.invitations (member_id) where member_id is not null and redeemed_at is null;

-- 3. Only the PersonalInfo keys survive, trimmed, blanks dropped.
create or replace function public.managed_identity_clean(p jsonb) returns jsonb
language sql immutable as $$
  select coalesce((
    select jsonb_object_agg(key, left(btrim(value), 254))
      from jsonb_each_text(coalesce(p, '{}'::jsonb))
     where key in ('first_name','last_name','company','street','postal_code',
                   'city','country_code','phone','email','vat_id','legal_id')
       and btrim(value) <> ''), '{}'::jsonb);
$$;

-- 4. The admin creates the member — active at once: the admin books
--    and invoices for them from the first day.
create or replace function public.create_managed_member(p_workspace_id uuid, p_identity jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_identity jsonb;
  v_id uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if not public.is_admin_of(p_workspace_id) then
    raise exception 'only admins may add managed profiles';
  end if;
  v_identity := public.managed_identity_clean(p_identity);
  if coalesce(v_identity->>'first_name', '') = ''
     and coalesce(v_identity->>'last_name', '') = ''
     and coalesce(v_identity->>'company', '') = '' then
    raise exception 'a managed profile needs a name';
  end if;
  insert into public.members
    (workspace_id, user_id, is_admin, status, managed_identity, managed_by)
  values (p_workspace_id, null, false, 'active', v_identity, auth.uid())
  returning id into v_id;
  return v_id;
end;
$$;

-- 5. The admin edits the identity — only while nobody owns it.
create or replace function public.update_managed_identity(p_member_id uuid, p_identity jsonb)
returns void language plpgsql security definer set search_path = public as $$
declare v_member public.members;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select * into v_member from public.members where id = p_member_id;
  if not found then raise exception 'member not found'; end if;
  if v_member.user_id is not null then raise exception 'profile already claimed'; end if;
  if not public.is_admin_of(v_member.workspace_id) then
    raise exception 'only admins may edit managed profiles';
  end if;
  update public.members
     set managed_identity = public.managed_identity_clean(p_identity)
   where id = p_member_id;
end;
$$;

-- 6. create_invitation gains the member it hands over. A new defaulted
--    parameter would leave the old overload beside it and make every
--    four-argument call ambiguous, so the old one goes first.
drop function if exists public.create_invitation(uuid, boolean, text, text);
create function public.create_invitation(
  p_workspace_id uuid, p_is_admin boolean,
  p_first_name text default '', p_last_name text default '',
  p_member_id uuid default null
) returns text language plpgsql security definer set search_path = public as $$
declare
  v_code text;
  v_member public.members;
  v_first text := left(coalesce(p_first_name, ''), 120);
  v_last text := left(coalesce(p_last_name, ''), 120);
begin
  if p_is_admin then
    if not public.is_owner_of(p_workspace_id) then
      raise exception 'only owners may invite admins';
    end if;
  elsif not public.is_admin_of(p_workspace_id) then
    raise exception 'only admins may invite members';
  end if;
  if p_member_id is not null then
    select * into v_member from public.members
     where id = p_member_id and workspace_id = p_workspace_id;
    if not found then raise exception 'member not found'; end if;
    if v_member.user_id is not null then raise exception 'profile already claimed'; end if;
    if p_is_admin then raise exception 'a handover grants membership, not admin'; end if;
    if v_first = '' then v_first := left(coalesce(v_member.managed_identity->>'first_name', ''), 120); end if;
    if v_last = '' then v_last := left(coalesce(v_member.managed_identity->>'last_name', ''), 120); end if;
    -- a fresh handover retires the previous open one: one code is live.
    delete from public.invitations where member_id = p_member_id and redeemed_at is null;
  end if;
  insert into public.invitations
    (workspace_id, is_admin, invited_first_name, invited_last_name, created_by, member_id)
  values (p_workspace_id, p_is_admin, v_first, v_last, auth.uid(), p_member_id)
  returning code into v_code;
  return v_code;
end;
$$;

-- 7. The admin takes a handover back while it is unredeemed.
create or replace function public.revoke_handover(p_member_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare v_member public.members;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select * into v_member from public.members where id = p_member_id;
  if not found then raise exception 'member not found'; end if;
  if not public.is_admin_of(v_member.workspace_id) then
    raise exception 'only admins may revoke a handover';
  end if;
  delete from public.invitations where member_id = p_member_id and redeemed_at is null;
end;
$$;

-- 8. join_workspace: a bound code claims the member instead of
--    inserting a new one — the identity becomes the person's, the
--    membership goes through the ordinary member_join validation.
create or replace function public.join_workspace(p_invite_code text)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  ws_id uuid;
  v_code text;
  v_admin boolean := false;
  v_member_id uuid;
  v_bound uuid;
  v_target public.members;
  v_mi jsonb;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  v_code := upper(trim(p_invite_code));
  select id into ws_id from public.workspaces where invite_code = v_code;
  if ws_id is null then
    update public.invitations
       set redeemed_by = auth.uid(), redeemed_at = now()
     where code = v_code
       and redeemed_at is null
       and expires_at > now()
    returning workspace_id, is_admin, member_id into ws_id, v_admin, v_bound;
  end if;
  if ws_id is null then raise exception 'invalid invite code'; end if;

  if v_bound is not null then
    select * into v_target from public.members where id = v_bound for update;
    if not found then raise exception 'invalid invite code'; end if;
    if v_target.user_id is not null then raise exception 'profile already claimed'; end if;
    if exists (select 1 from public.members
                where workspace_id = ws_id and user_id = auth.uid()) then
      raise exception 'already a member of this workspace';
    end if;
    -- #887 — the person owns the data: it lands in the EMPTY fields of
    -- their profile; what they already wrote about themselves wins.
    v_mi := v_target.managed_identity;
    update public.profiles p set
      first_name   = case when coalesce(p.first_name, '') = ''   then coalesce(v_mi->>'first_name', '')   else p.first_name end,
      last_name    = case when coalesce(p.last_name, '') = ''    then coalesce(v_mi->>'last_name', '')    else p.last_name end,
      company      = case when coalesce(p.company, '') = ''      then coalesce(v_mi->>'company', '')      else p.company end,
      street       = case when coalesce(p.street, '') = ''       then coalesce(v_mi->>'street', '')       else p.street end,
      postal_code  = case when coalesce(p.postal_code, '') = ''  then coalesce(v_mi->>'postal_code', '')  else p.postal_code end,
      city         = case when coalesce(p.city, '') = ''         then coalesce(v_mi->>'city', '')         else p.city end,
      country_code = case when coalesce(p.country_code, '') = '' then coalesce(v_mi->>'country_code', '') else p.country_code end,
      phone        = case when coalesce(p.phone, '') = ''        then coalesce(v_mi->>'phone', '')        else p.phone end,
      email        = case when coalesce(p.email, '') = ''        then coalesce(v_mi->>'email', '')        else p.email end,
      vat_id       = case when coalesce(p.vat_id, '') = ''       then coalesce(v_mi->>'vat_id', '')       else p.vat_id end,
      legal_id     = case when coalesce(p.legal_id, '') = ''     then coalesce(v_mi->>'legal_id', '')     else p.legal_id end
    where p.id = auth.uid();
    update public.members
       set user_id = auth.uid(), claimed_at = now(),
           managed_identity = '{}'::jsonb, status = 'pending'
     where id = v_bound
    returning id into v_member_id;
  else
    insert into public.members (workspace_id, user_id, is_admin, status)
    values (ws_id, auth.uid(), v_admin, 'pending')
    on conflict (workspace_id, user_id) do update
      set status = case when public.members.status = 'exited'
                        then 'pending' else public.members.status end,
          is_admin = public.members.is_admin or excluded.is_admin
    returning id into v_member_id;
  end if;

  if exists (select 1 from public.members
              where id = v_member_id and status = 'pending')
     and not exists (
       select 1 from public.events
       where subject_member_id = v_member_id
         and type = 'member_join' and status = 'pending') then
    insert into public.events
      (workspace_id, type, action, actor_member_id, subject_member_id,
       payload, status)
    values (ws_id, 'member_join', 'submitted', v_member_id, v_member_id,
            jsonb_build_object('as_admin', v_admin, 'claimed', v_bound is not null),
            'pending');
  end if;
  return ws_id;
end;
$$;

-- 9. create_invoice names a managed member from managed_identity: the
--    profile row (as jsonb) or the managed copy, poured into ONE
--    profiles-shaped record so profile_full_name / profile_postal_block
--    (0152) serve both. Patched at the 0152 anchor; a silent no-op
--    would invoice a managed member as nobody.
do $patch$
declare
  v_def text;
  v_anchor text;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'create_invoice';
  if v_def is null then raise exception '0153: create_invoice not found'; end if;
  v_anchor := E'    from public.profiles pr where pr.id = v_subject.user_id;\n';
  if position(v_anchor in v_def) = 0 then raise exception '0153: anchor missing'; end if;
  v_def := replace(v_def, v_anchor,
       E'    from jsonb_populate_record(null::public.profiles,\n'
    || E'           coalesce((select to_jsonb(p) from public.profiles p where p.id = v_subject.user_id),\n'
    || E'                    v_subject.managed_identity)) pr;\n');
  execute v_def;
end
$patch$;

-- SPDX-License-Identifier: 0BSD
-- 0154 — #881: payment conditions — the workspace's default, a member's
-- own, changed only through validation with a permission.
--
-- The conditions printed on an invoice (payment terms, early-payment
-- discount, late penalty, recovery indemnity) lived only on
-- workspaces.invoice_legal. A member may now carry an OVERRIDE
-- (members.payment_terms, null = inherit). The member sees theirs and
-- cannot change them; an admin holding the paymentTermsEdit permission
-- REQUESTS a change, which is a validation event
-- (payment_terms_change) decided like every other domain; the decision
-- applies through an AFTER UPDATE trigger on events — never a branch in
-- respond_to_event (the 0151 idiom).

-- 1. The override.
alter table public.members
  add column if not exists payment_terms jsonb;

-- 2. The domain, on both check constraints.
alter table public.events drop constraint if exists events_type_check;
alter table public.events add constraint events_type_check
  check (type = any (array[
    'reservation', 'payment', 'expense', 'adjustment', 'service_charge',
    'quota', 'role_change', 'member_join', 'space_reservation',
    'invoice_payment', 'reservation_delete', 'invoice_writeoff',
    'invoice_reminder', 'price_negotiation', 'expense_schedule',
    'expense_repartition', 'usage_correction', 'usage_record_delete',
    'payment_terms_change']));
alter table public.validation_policies
  drop constraint if exists validation_policies_event_type_check;
alter table public.validation_policies
  add constraint validation_policies_event_type_check
  check (event_type is null or event_type = any (array[
    'reservation', 'payment', 'expense', 'adjustment', 'service_charge',
    'quota', 'role_change', 'member_join', 'space_reservation',
    'invoice_payment', 'reservation_delete', 'invoice_writeoff',
    'invoice_reminder', 'price_negotiation', 'expense_schedule',
    'expense_repartition', 'usage_correction', 'usage_record_delete',
    'payment_terms_change']));

-- 3. The policy row: the owner decides, admins may validate, one
--    decision — seeded where absent so the domain is never ungoverned.
insert into public.validation_policies
  (workspace_id, event_type, required_count, admins_may_validate,
   owner_required, validator_scope, sequential)
select w.id, 'payment_terms_change', 1, true, true, 'admins', false
  from public.workspaces w
 where not exists (select 1 from public.validation_policies p
                    where p.workspace_id = w.id
                      and p.event_type = 'payment_terms_change');

-- 4. Only the condition keys survive, trimmed; '{}' means "inherit".
create or replace function public.payment_terms_clean(p jsonb) returns jsonb
language sql immutable as $$
  select coalesce((
    select jsonb_object_agg(key, left(btrim(value), 2000))
      from jsonb_each_text(coalesce(p, '{}'::jsonb))
     where key in ('payment_terms', 'escompte', 'late_penalty', 'recovery_indemnity')
       and btrim(value) <> ''), '{}'::jsonb);
$$;

-- 5. What a member's documents print: the workspace's conditions, the
--    member's keys on top, `source` saying whether anything is theirs.
create or replace function public.effective_payment_terms(p_member_id uuid)
returns jsonb language sql stable security definer set search_path = public as $$
  select public.payment_terms_clean(w.invoice_legal)
         || coalesce(m.payment_terms, '{}'::jsonb)
         || jsonb_build_object('source',
              case when m.payment_terms is not null then 'member' else 'workspace' end)
    from public.members m join public.workspaces w on w.id = m.workspace_id
   where m.id = p_member_id;
$$;

-- 6. The permission: admins hold it by default, like the other
--    finance delegations; the matrix may take it away.
do $patch$
declare v_def text; v_anchor text;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'has_permission';
  if v_def is null then raise exception '0154: has_permission not found'; end if;
  v_anchor := E'''manageNegotiations'') end)';
  if position(v_anchor in v_def) = 0 then raise exception '0154: anchor missing'; end if;
  execute replace(v_def, v_anchor, E'''manageNegotiations'',''paymentTermsEdit'') end)');
end
$patch$;

-- 7. The request: a validation event carrying before/after.
create or replace function public.request_payment_terms_change(
  p_member_id uuid, p_terms jsonb, p_reason text default ''
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_actor public.members;
  v_after jsonb;
  v_before jsonb;
  v_id uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select * into v_member from public.members where id = p_member_id;
  if v_member.id is null then raise exception 'member not found'; end if;
  select * into v_actor from public.members
   where workspace_id = v_member.workspace_id and user_id = auth.uid()
     and status = 'active';
  if v_actor.id is null then raise exception 'not an active member'; end if;
  if not public.has_permission(v_member.workspace_id, 'paymentTermsEdit') then
    raise exception 'payment conditions are changed by an authorised admin';
  end if;
  v_after := public.payment_terms_clean(p_terms);
  v_before := public.effective_payment_terms(p_member_id) - 'source';
  -- Supersede: one open request per member.
  update public.events set status = 'expired'
   where type = 'payment_terms_change' and status = 'pending'
     and subject_member_id = p_member_id;
  insert into public.events
    (workspace_id, type, action, actor_member_id, subject_member_id, payload, status)
  values (v_member.workspace_id, 'payment_terms_change', 'submitted',
          v_actor.id, p_member_id,
          jsonb_build_object('member_id', p_member_id, 'before', v_before,
                             'after', v_after, 'inherit', v_after = '{}'::jsonb,
                             'reason', left(coalesce(p_reason, ''), 300)),
          'pending')
  returning id into v_id;
  return v_id;
end;
$$;

-- 8. Apply on confirm — the trigger, never a respond_to_event branch.
create or replace function public.apply_payment_terms_decision()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.status = old.status then return new; end if;
  if new.type = 'payment_terms_change' and new.status = 'confirmed' then
    update public.members
       set payment_terms = case when public.payment_terms_clean(new.payload->'after') = '{}'::jsonb
                                then null
                                else public.payment_terms_clean(new.payload->'after') end
     where id = (new.payload->>'member_id')::uuid;
  end if;
  return new;
end;
$$;
drop trigger if exists events_apply_payment_terms on public.events;
create trigger events_apply_payment_terms
  after update on public.events
  for each row execute function public.apply_payment_terms_decision();

-- SPDX-License-Identifier: 0BSD
-- 0155 — #881: the paymentTermsEdit permission joins the catalog
-- set_role_permissions accepts (0144 refused every payload that named
-- a permission outside its array — #816). Full body, so the catalog
-- literal below IS the latest one the client test mirrors.
create or replace function public.set_role_permissions(p_workspace_id uuid, p_role text, p_permissions text[])
returns void language plpgsql security definer set search_path = public as $$
declare
  v_catalog text[] := array[
    'manageRoles','manageMembers','manageValidation','workspaceSettings',
    'issueInvoices','viewFinances','manageDocuments','manageServices',
    'approveExpenses','viewNegotiations','manageNegotiations',
    'paymentTermsEdit'];
  v_perm text;
begin
  if not public.has_permission(p_workspace_id, 'manageRoles') then
    raise exception 'only role managers may edit permissions';
  end if;
  if p_role not in ('co_owner','admin','member') then
    raise exception 'unknown role';
  end if;
  foreach v_perm in array coalesce(p_permissions, '{}') loop
    if not (v_perm = any(v_catalog)) then
      raise exception 'unknown permission %', v_perm;
    end if;
  end loop;
  update public.workspaces
    set role_permissions = jsonb_set(
      coalesce(role_permissions, '{}'::jsonb),
      array[p_role],
      coalesce(to_jsonb(p_permissions), '[]'::jsonb))
    where id = p_workspace_id;
end;
$$;

-- SPDX-License-Identifier: 0BSD
-- 0156 — #894: a reversal carries the VAT it gives back.
--
-- The breakdown counted CHARGES only (`amount_cents > 0`), and a credit
-- was stamped 0 % because a credit is money moving, not a supply. True
-- of a payment; false of a document that CANCELS a VAT-bearing charge:
-- art. 219 of the VAT Directive wants the reversing document to state
-- the tax it reverses. From here a credit may name the rate it gives
-- back, that rate reaches the invoice line, and a line that names a rate
-- counts in the breakdown even when it is negative — so the VAT of an
-- avoir is negative per rate and the declaration nets out.
-- Harness-verified 2026-09-05 (charge 120,00 @20 % + avoir 20,00 @20 %
-- + payment 50,00 → one 20 % entry: gross 100,00, net 83,33, VAT 16,67).
do $patch$
declare v_def text; v_anchor text;
begin
  -- 1. A credit keeps the rate it was stamped with; a payment has none
  --    and stays at 0 %.
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname='public' and p.proname='invoice_lines_for'
     and pg_get_function_identity_arguments(p.oid) = 'p_member_id uuid, p_period text';
  if v_def is null then raise exception '0156: invoice_lines_for not found'; end if;
  v_anchor := E'      ''vat_percent'', case when v_row.kind = ''credit'' then 0\n';
  if position(v_anchor in v_def) = 0 then raise exception '0156: anchor A missing'; end if;
  v_def := replace(v_def, v_anchor,
    E'      ''vat_percent'', case when v_row.kind = ''credit''\n'
 || E'                          then coalesce(v_row.vat_percent, 0)\n');
  execute v_def;

  -- 2. A line that NAMES a rate counts even when negative. A payment
  --    (0 %, negative) still never reaches the breakdown.
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname='public' and p.proname='create_invoice';
  v_anchor := E'     where (l->>''amount_cents'')::int > 0\n';
  if position(v_anchor in v_def) = 0 then raise exception '0156: anchor B missing'; end if;
  v_def := replace(v_def, v_anchor,
    E'     where (l->>''amount_cents'')::int > 0\n'
 || E'        or coalesce((l->>''vat_percent'')::numeric, 0) > 0\n');
  execute v_def;

  -- 3. A distributed expense stamps the workspace's rate on BOTH sides,
  --    so a reversal (#828) gives back the tax it charged.
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname='public' and p.proname='apply_expense_repartition';
  v_anchor := E'      (workspace_id, member_id, kind, category, amount_cents, description,\n       period, event_id)\n';
  if position(v_anchor in v_def) = 0 then raise exception '0156: anchor C missing'; end if;
  v_def := replace(v_def, v_anchor,
    E'      (workspace_id, member_id, kind, category, amount_cents, description,\n       period, event_id, vat_percent)\n');
  v_anchor := E'       v_r.event_id);\n';
  if position(v_anchor in v_def) = 0 then raise exception '0156: anchor D missing'; end if;
  v_def := replace(v_def, v_anchor,
    E'       v_r.event_id,\n'
 || E'       public.workspace_default_vat_percent(v_r.workspace_id));\n');
  execute v_def;
end
$patch$;

-- SPDX-License-Identifier: 0BSD
-- 0160 — #917: a workspace says whether it is real.
--
-- Nothing distinguished a space used for trying things out from a space
-- billing real people. The same app, the same documents, the same
-- numbering — and an invoice printed while exploring is indistinguishable
-- from one that is owed. So a workspace now carries its ENVIRONMENT.
--
-- 'dev' is the default, and every workspace that already exists becomes
-- one: the safe answer to "is this real?" is no until somebody says
-- otherwise. Declaring a space PROD is a deliberate act by its owner.
alter table public.workspaces
  add column if not exists environment text not null default 'dev'
    check (environment in ('dev', 'prod'));

-- The environment is chosen AT CREATION and defaults to dev. The 4-arg
-- overload is dropped rather than kept beside it: two candidates make a
-- 4-argument call ambiguous, and PostgREST resolves the named-parameter
-- call against this one, so a client that does not send p_environment
-- still lands on the default.
drop function if exists public.create_workspace(text, text, text, text);
create or replace function public.create_workspace(
  p_name text, p_country_code text, p_currency_code text, p_timezone text,
  p_environment text default 'dev'
) returns uuid language plpgsql security definer set search_path = public as $$
declare ws_id uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if coalesce(p_environment, 'dev') not in ('dev', 'prod') then
    raise exception 'unknown environment %', p_environment;
  end if;
  insert into public.workspaces
    (name, country_code, currency_code, timezone, created_by, environment)
  values (p_name, upper(p_country_code), upper(p_currency_code), p_timezone,
          auth.uid(), coalesce(p_environment, 'dev'))
  returning id into ws_id;
  insert into public.members (workspace_id, user_id, is_admin, is_owner)
  values (ws_id, auth.uid(), true, true);
  return ws_id;
end;
$$;

-- Only the OWNER may declare a space real — an admin cannot quietly
-- take the development mark off the documents they issue.
create or replace function public.set_workspace_environment(
  p_workspace_id uuid,
  p_environment text
) returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_owner_of(p_workspace_id) then
    raise exception 'only owners may change the environment';
  end if;
  if p_environment not in ('dev', 'prod') then
    raise exception 'unknown environment %', p_environment;
  end if;
  update public.workspaces set environment = p_environment
    where id = p_workspace_id;
end;
$$;
revoke execute on function public.set_workspace_environment(uuid, text) from public, anon;
grant execute on function public.set_workspace_environment(uuid, text) to authenticated;

-- SPDX-License-Identifier: 0BSD
-- 0161 — #914/#915: who may administer a managed profile, and what the
-- person sees when they take it over.
--
-- An admin-managed profile (#887) holds a real person's identity — name,
-- address, telephone, e-mail, tax identifiers — before that person has
-- an account. Two things were wrong with where it lived.
--
-- FIRST, `members_select` (0002) is row-agnostic: every member of the
-- workspace could read the row, so a co-member could read contact and
-- tax details of someone who never agreed to show them. The interface
-- only ever showed them to admins, which is why nobody noticed. Row-level
-- security cannot fix that in place — the same row must stay readable by
-- everyone, because the members list needs the name. So the identity
-- moves to its own table behind a predicate, and the row keeps only the
-- name, which is what a co-member legitimately sees.
--
-- SECOND, ANY admin could read, edit and hand over any managed profile.
-- Each profile now carries its own rule: roles, named people, or both.
-- '{}' is the rule nobody has narrowed — owner and admin, exactly what
-- #887 shipped — so nothing changes until someone narrows it.
--
-- The rule gates the personal data and the handover. Booking a seat and
-- issuing an invoice stay ordinary workspace bookkeeping: gating those
-- would block everyday work in ways nobody could diagnose.
--
-- The workspace OWNER may always CHANGE a rule — a profile must never
-- become unadministrable when its only named admin leaves — but is only
-- an administrator of the person's data when the rule says so. Governance
-- of the rule and access to the data are separate powers, and every
-- change of either is written to the access log the person reads once
-- they claim the profile.

-- 1. The rule, and the public projection of the name.
alter table public.members
  add column if not exists managed_access jsonb not null default '{}'::jsonb,
  add column if not exists managed_name text not null default '';

-- 2. The identity leaves the widely-readable row.
create table if not exists public.managed_identities (
  member_id uuid primary key references public.members(id) on delete cascade,
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  identity jsonb not null default '{}'::jsonb
);
create index if not exists managed_identities_workspace_idx
  on public.managed_identities (workspace_id);
alter table public.managed_identities enable row level security;

-- 3. The addressee line, derived — company first (0159), else the person.
create or replace function public.managed_identity_name(p jsonb)
returns text language sql immutable as $$
  select coalesce(
    nullif(btrim(coalesce(p->>'company', '')), ''),
    nullif(case
      when btrim(coalesce(p->>'first_name','')) = ''
        then upper(btrim(coalesce(p->>'last_name','')))
      when btrim(coalesce(p->>'last_name','')) = ''
        then btrim(coalesce(p->>'first_name',''))
      else btrim(coalesce(p->>'first_name','')) || ' ' ||
           upper(btrim(coalesce(p->>'last_name','')))
    end, ''),
    '');
$$;

-- 4. Carry what exists across, then empty the exposed column.
-- What a CO-MEMBER may legitimately see: who this is. The members
-- list, the plan and every reservation row need a name, so the name
-- stays on the widely-readable row. The contact and tax fields do not
-- belong there and move behind the rule.
--
-- Keeping the public half in place also means a client that has not
-- been updated yet still shows managed members by name instead of
-- blanking them: the migration removes the exposure without breaking
-- the app in the window before the new build ships.
create or replace function public.managed_identity_public(p jsonb)
returns jsonb language sql immutable as $$
  select coalesce((
    select jsonb_object_agg(key, value)
      from jsonb_each_text(coalesce(p, '{}'::jsonb))
     where key in ('courtesy','first_name','last_name','company','country_code')
       and btrim(value) <> ''), '{}'::jsonb);
$$;

insert into public.managed_identities (member_id, workspace_id, identity)
select m.id, m.workspace_id, m.managed_identity
  from public.members m
 where m.user_id is null and m.managed_identity <> '{}'::jsonb
on conflict (member_id) do nothing;
update public.members m
   set managed_name = public.managed_identity_name(m.managed_identity)
 where m.user_id is null and m.managed_name = '';
update public.members m
   set managed_identity = public.managed_identity_public(m.managed_identity)
 where m.managed_identity <> '{}'::jsonb;

-- 5. WHO may administer one profile.
--
-- '{}' means the rule nobody has narrowed: owner and admin, which is
-- exactly what #887 shipped. A rule names roles, member ids, or both.
-- The workspace OWNER may always CHANGE a rule (a profile must never
-- become unadministrable when its only named admin leaves) but is only
-- an administrator of the person's data when the rule says so.
create or replace function public.can_manage_managed_profile(p_member_id uuid)
returns boolean language sql stable security definer
set search_path = public as $$
  select exists (
    select 1
      from public.members target
      join public.members me
        on me.workspace_id = target.workspace_id
       and me.user_id = auth.uid()
       and me.status = 'active'
     where target.id = p_member_id
       and (
         case when coalesce(target.managed_access->'roles', 'null'::jsonb) = 'null'::jsonb
              then (me.is_owner or me.co_owner = 'active' or me.is_admin)
              else ((target.managed_access->'roles' ? 'owner'
                     and (me.is_owner or me.co_owner = 'active'))
                 or (target.managed_access->'roles' ? 'admin' and me.is_admin))
         end
         or coalesce(target.managed_access->'members', '[]'::jsonb) ? me.id::text
       )
  );
$$;
revoke execute on function public.can_manage_managed_profile(uuid) from public, anon;
grant execute on function public.can_manage_managed_profile(uuid) to authenticated;

-- 6. Reading the identity is an ACCESS: gated, and written down.
drop policy if exists managed_identities_select on public.managed_identities;
create policy managed_identities_select on public.managed_identities
  for select using (
    public.can_manage_managed_profile(member_id)
    or exists (select 1 from public.members m
                where m.id = member_id and m.user_id = auth.uid())
  );
-- No insert/update/delete policy: the definer functions below own writes.

create or replace function public.managed_identity_of(p_member_id uuid)
returns jsonb language plpgsql volatile security definer
set search_path = public as $$
declare
  v_member public.members;
  v_me public.members;
  v_identity jsonb;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select * into v_member from public.members where id = p_member_id;
  if not found then raise exception 'member not found'; end if;
  if not public.can_manage_managed_profile(p_member_id) then
    raise exception 'not allowed to read this profile';
  end if;
  select identity into v_identity
    from public.managed_identities where member_id = p_member_id;
  select * into v_me from public.members
   where workspace_id = v_member.workspace_id and user_id = auth.uid();
  if v_me.id is not null and v_me.id <> p_member_id then
    insert into public.data_access_log
      (workspace_id, actor_member_id, subject_member_id, category)
    values (v_member.workspace_id, v_me.id, p_member_id, 'profile');
  end if;
  return coalesce(v_identity, '{}'::jsonb);
end;
$$;
revoke execute on function public.managed_identity_of(uuid) from public, anon;
grant execute on function public.managed_identity_of(uuid) to authenticated;

-- 7. The log learns the word.
alter table public.data_access_log drop constraint if exists data_access_log_category_check;
alter table public.data_access_log add constraint data_access_log_category_check
  check (category in ('finances', 'messages', 'export', 'negotiations', 'profile'));

-- 8. Creating, editing and handing over all obey the rule.
-- The 2-arg overload is dropped rather than kept beside it: two
-- candidates make a two-argument call ambiguous, and PostgREST
-- resolves the named-parameter call against this one, so a client
-- that does not send p_access still lands on the default rule.
drop function if exists public.create_managed_member(uuid, jsonb);
create or replace function public.create_managed_member(
  p_workspace_id uuid, p_identity jsonb, p_access jsonb default '{}'::jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_identity jsonb;
  v_id uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if not public.is_admin_of(p_workspace_id) then
    raise exception 'only admins may add managed profiles';
  end if;
  v_identity := public.managed_identity_clean(p_identity);
  if public.managed_identity_name(v_identity) = '' then
    raise exception 'a managed profile needs a name';
  end if;
  insert into public.members
    (workspace_id, user_id, is_admin, status, managed_identity, managed_by,
     managed_access, managed_name)
  values (p_workspace_id, null, false, 'active',
          public.managed_identity_public(v_identity), auth.uid(),
          coalesce(p_access, '{}'::jsonb),
          public.managed_identity_name(v_identity))
  returning id into v_id;
  insert into public.managed_identities (member_id, workspace_id, identity)
  values (v_id, p_workspace_id, v_identity);
  insert into public.data_access_log
    (workspace_id, actor_member_id, subject_member_id, category)
  select p_workspace_id, me.id, v_id, 'profile' from public.members me
   where me.workspace_id = p_workspace_id and me.user_id = auth.uid();
  return v_id;
end;
$$;

create or replace function public.update_managed_identity(p_member_id uuid, p_identity jsonb)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_member public.members;
  v_identity jsonb;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select * into v_member from public.members where id = p_member_id;
  if not found then raise exception 'member not found'; end if;
  if v_member.user_id is not null then raise exception 'profile already claimed'; end if;
  if not public.can_manage_managed_profile(p_member_id) then
    raise exception 'not allowed to manage this profile';
  end if;
  v_identity := public.managed_identity_clean(p_identity);
  insert into public.managed_identities (member_id, workspace_id, identity)
  values (p_member_id, v_member.workspace_id, v_identity)
  on conflict (member_id) do update set identity = excluded.identity;
  update public.members
     set managed_name = public.managed_identity_name(v_identity),
         managed_identity = public.managed_identity_public(v_identity)
   where id = p_member_id;
  insert into public.data_access_log
    (workspace_id, actor_member_id, subject_member_id, category)
  select v_member.workspace_id, me.id, p_member_id, 'profile'
    from public.members me
   where me.workspace_id = v_member.workspace_id and me.user_id = auth.uid();
end;
$$;

-- 9. The rule itself: changed by anyone the rule already allows, and
--    ALWAYS by the workspace owner — otherwise a profile whose only
--    named admin leaves can never be administered again.
create or replace function public.set_managed_access(p_member_id uuid, p_access jsonb)
returns void language plpgsql security definer set search_path = public as $$
declare v_member public.members;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select * into v_member from public.members where id = p_member_id;
  if not found then raise exception 'member not found'; end if;
  if v_member.user_id is not null then raise exception 'profile already claimed'; end if;
  if not (public.is_owner_of(v_member.workspace_id)
          or public.can_manage_managed_profile(p_member_id)) then
    raise exception 'not allowed to manage this profile';
  end if;
  update public.members set managed_access = coalesce(p_access, '{}'::jsonb)
   where id = p_member_id;
  insert into public.data_access_log
    (workspace_id, actor_member_id, subject_member_id, category)
  select v_member.workspace_id, me.id, p_member_id, 'profile'
    from public.members me
   where me.workspace_id = v_member.workspace_id and me.user_id = auth.uid();
end;
$$;
revoke execute on function public.set_managed_access(uuid, jsonb) from public, anon;
grant execute on function public.set_managed_access(uuid, jsonb) to authenticated;

-- 10. The handover is administering the profile too.
create or replace function public.revoke_handover(p_member_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare v_member public.members;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select * into v_member from public.members where id = p_member_id;
  if not found then raise exception 'member not found'; end if;
  if not public.can_manage_managed_profile(p_member_id) then
    raise exception 'not allowed to manage this profile';
  end if;
  delete from public.invitations
   where member_id = p_member_id and redeemed_at is null;
end;
$$;

-- 11. create_invitation: the handover obeys the rule, and reads the
--     name from where the identity now lives.
do $patch$
declare v_def text;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'create_invitation';
  if v_def is null then raise exception '0161: create_invitation not found'; end if;
  if position(E'    if p_is_admin then raise exception ''a handover grants membership, not admin''; end if;\n' in v_def) = 0
    then raise exception '0161: invitation anchor A missing'; end if;
  v_def := replace(v_def,
    E'    if p_is_admin then raise exception ''a handover grants membership, not admin''; end if;\n',
    E'    if p_is_admin then raise exception ''a handover grants membership, not admin''; end if;\n'
 || E'    if not public.can_manage_managed_profile(p_member_id) then\n'
 || E'      raise exception ''not allowed to manage this profile'';\n'
 || E'    end if;\n');
  if position(E'v_member.managed_identity->>''first_name''' in v_def) = 0
    then raise exception '0161: invitation anchor B missing'; end if;
  v_def := replace(v_def, E'v_member.managed_identity->>''first_name''',
    E'(select mi.identity->>''first_name'' from public.managed_identities mi where mi.member_id = p_member_id)');
  v_def := replace(v_def, E'v_member.managed_identity->>''last_name''',
    E'(select mi.identity->>''last_name'' from public.managed_identities mi where mi.member_id = p_member_id)');
  execute v_def;
end
$patch$;

-- 12. join_workspace: the claim copies the identity from its new home,
--     then removes it — the person owns the data from that moment.
do $patch$
declare v_def text;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'join_workspace';
  if v_def is null then raise exception '0161: join_workspace not found'; end if;
  if position(E'    v_mi := v_target.managed_identity;\n' in v_def) = 0
    then raise exception '0161: join anchor A missing'; end if;
  v_def := replace(v_def, E'    v_mi := v_target.managed_identity;\n',
       E'    select coalesce(mi.identity, ''{}''::jsonb) into v_mi\n'
    || E'      from public.managed_identities mi where mi.member_id = v_bound;\n'
    || E'    v_mi := coalesce(v_mi, ''{}''::jsonb);\n'
    || E'    delete from public.managed_identities where member_id = v_bound;\n');
  if position(E'           managed_identity = ''{}''::jsonb, status = ''pending''\n' in v_def) = 0
    then raise exception '0161: join anchor B missing'; end if;
  v_def := replace(v_def,
    E'           managed_identity = ''{}''::jsonb, status = ''pending''\n',
    E'           managed_identity = ''{}''::jsonb, managed_name = '''',\n'
 || E'           managed_access = ''{}''::jsonb, status = ''pending''\n');
  execute v_def;
end
$patch$;

-- 13. create_invoice names a managed member from the identity's new
--     home. It is SECURITY DEFINER and the caller already passed the
--     invoicing gate: issuing is workspace bookkeeping, not a reading
--     of the person's contact details.
do $patch$
declare v_def text;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'create_invoice';
  if v_def is null then raise exception '0161: create_invoice not found'; end if;
  if position(E'                    v_subject.managed_identity)) pr;\n' in v_def) = 0
    then raise exception '0161: invoice anchor missing'; end if;
  v_def := replace(v_def, E'                    v_subject.managed_identity)) pr;\n',
    E'                    coalesce((select mi.identity from public.managed_identities mi\n'
 || E'                               where mi.member_id = v_subject.id), ''{}''::jsonb))) pr;\n');
  execute v_def;
end
$patch$;

-- 14. "Who can see this" learns to answer for the profile too.
do $patch$
declare
  v_def text;
  v_anchor text := E'    ''reservations'', ''all_members'',\n';
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'who_can_access_me';
  if v_def is null then raise exception '0161: who_can_access_me missing'; end if;
  if position(v_anchor in v_def) = 0 then raise exception '0161: access anchor missing'; end if;
  v_def := replace(v_def, v_anchor,
       E'    ''profile'', (\n'
    || E'      select coalesce(jsonb_agg(m.id), ''[]''::jsonb) from public.members m\n'
    || E'       where m.workspace_id = p_workspace_id and m.status = ''active''\n'
    || E'         and m.id <> v_me.id\n'
    || E'         and public.can_manage_managed_profile(v_me.id)\n'
    || E'         and (case when coalesce((select t.managed_access->''roles'' from public.members t where t.id = v_me.id), ''null''::jsonb) = ''null''::jsonb\n'
    || E'                   then (m.is_owner or m.co_owner = ''active'' or m.is_admin)\n'
    || E'                   else true end)\n'
    || E'    ),\n'
    || v_anchor);
  execute v_def;
end
$patch$;

-- SPDX-License-Identifier: 0BSD
-- 0163 — #922: the two references Chorus Pro will not accept a deposit
-- without.
--
-- Factur-X is sound (PDF/A-3, CII embedded, EN 16931 conformance), and
-- the upload posts it to the platform. What the document did not carry
-- were two fields of the norm that the French public-sector portal
-- REQUIRES for most public entities: BT-13, the purchase-order
-- reference — the numéro d'engagement — and BT-10, the buyer reference
-- — the code service exécutant. The app would accept the deposit, the
-- portal would refuse it, and nothing had warned the issuer.
--
-- Both are captured AT ISSUE and frozen on the document, under the
-- buyer party: an engagement number belongs to one order, not to a
-- member for ever, and an issued invoice does not change. The 7-argument
-- overload is dropped rather than kept beside the new one: two
-- candidates make the old call ambiguous, and PostgREST resolves the
-- named-parameter call against this one, so a client that sends neither
-- reference lands on the empty default.
do $patch$
declare v_def text; v_anchor text;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'create_invoice';
  if v_def is null then raise exception '0163: create_invoice not found'; end if;
  v_anchor := 'p_allow_zero boolean DEFAULT false)';
  if position(v_anchor in v_def) = 0 then raise exception '0163: signature anchor missing'; end if;
  v_def := replace(v_def, v_anchor,
    'p_allow_zero boolean DEFAULT false, p_buyer_reference text DEFAULT ''''::text, p_purchase_order text DEFAULT ''''::text)');
  v_anchor := E'      ''vat_id'', v_member_vat));\n';
  if position(v_anchor in v_def) = 0 then raise exception '0163: buyer anchor missing'; end if;
  v_def := replace(v_def, v_anchor,
       E'      ''reference'', left(btrim(coalesce(p_buyer_reference, '''')), 120),\n'
    || E'      ''order'', left(btrim(coalesce(p_purchase_order, '''')), 120),\n'
    || v_anchor);
  drop function if exists public.create_invoice(uuid, uuid, text, uuid, boolean, text, boolean);
  execute v_def;
end
$patch$;

-- SPDX-License-Identifier: 0BSD
-- 0164 — #925: one number-sequence framework, per workspace, generated
-- in the database.
--
-- The only human-facing number the app generated was the invoice
-- number, produced by copy-pasted SQL in create_invoice and
-- settle_invoices: count(*) over the year's invoices, plus one, under a
-- workspace-wide advisory lock, with the year taken in UTC. That was
-- gapless by accident (a rolled-back issue takes its count with it),
-- O(n) per issue, serialised every issuer of a workspace behind one
-- lock, rolled the year at UTC midnight while every other billing
-- boundary uses the workspace's clock, and could not be configured.
--
-- A Postgres SEQUENCE is the textbook answer and would have broken the
-- one thing worth keeping: nextval is deliberately non-transactional, so
-- every failed issue would burn a number for good. French law (CGI art.
-- 289) requires a continuous chronological series per journal.
--
-- So: one narrow row per (workspace, journal), locked FOR UPDATE for the
-- microseconds it takes to increment, inside the caller's transaction.
-- Gapless — the increment rolls back with the issue. O(1). Serialised
-- only against writers of the same series. The period key is resolved on
-- the WORKSPACE clock. And the format is the owner's to set: prefix,
-- date part, digits, suffix, reset policy.
--
-- `gapless` is constrained to true. Caching blocks of numbers is
-- incompatible with a gapless series (an unconsumed block IS the hole
-- the law forbids), and no journal needs a gapped mode today; the column
-- exists so a later journal that does can ask for one explicitly.
--
-- Values are per workspace by construction: the primary key carries the
-- workspace and row-level security restricts reads to its members.
-- Writes go only through the definer functions below.
--
-- Every workspace is seeded so its invoice series continues unbroken:
-- next_value is the same count(*)+1 the old code would have produced
-- for the current year, keyed to the workspace's own year.
create table if not exists public.number_sequences (
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  journal      text not null check (journal ~ '^[a-z_]{1,32}$'),
  prefix       text not null default '' check (char_length(prefix) <= 16),
  suffix       text not null default '' check (char_length(suffix) <= 16),
  date_part    text not null default 'year' check (date_part in ('none','year','year_month')),
  digits       int  not null default 4 check (digits between 1 and 9),
  reset        text not null default 'yearly' check (reset in ('never','yearly','monthly')),
  gapless      boolean not null default true check (gapless),
  period_key   text not null default '',
  next_value   bigint not null default 1 check (next_value >= 1),
  primary key (workspace_id, journal)
);
alter table public.number_sequences enable row level security;
drop policy if exists number_sequences_select on public.number_sequences;
create policy number_sequences_select on public.number_sequences
  for select using (public.is_member_of(workspace_id));

-- The period a counter belongs to, on the workspace clock — never UTC.
create or replace function public.number_sequence_period_key(
  p_workspace_id uuid, p_reset text, p_at timestamptz default now())
returns text language sql stable as $$
  select case p_reset
    when 'yearly'  then to_char(p_at at time zone coalesce(w.timezone, 'UTC'), 'YYYY')
    when 'monthly' then to_char(p_at at time zone coalesce(w.timezone, 'UTC'), 'YYYY-MM')
    else '' end
  from public.workspaces w where w.id = p_workspace_id;
$$;

create or replace function public.number_sequence_format(
  p_workspace_id uuid, p_seq public.number_sequences, p_value bigint, p_at timestamptz default now())
returns text language sql stable as $$
  select p_seq.prefix
      || case p_seq.date_part
           when 'year'       then to_char(p_at at time zone coalesce(w.timezone,'UTC'), 'YYYY') || '-'
           when 'year_month' then to_char(p_at at time zone coalesce(w.timezone,'UTC'), 'YYYY-MM') || '-'
           else '' end
      || lpad(p_value::text, p_seq.digits, '0')
      || p_seq.suffix
  from public.workspaces w where w.id = p_workspace_id;
$$;

-- The one way a number is taken. Definer, and NOT callable by clients:
-- a number is drawn by the function that issues the document, inside
-- its transaction, so it can never be drawn and then not used.
create or replace function public.next_document_number(p_workspace_id uuid, p_journal text)
returns text language plpgsql volatile security definer set search_path = public as $$
declare v_seq public.number_sequences; v_key text; v_value bigint;
begin
  insert into public.number_sequences (workspace_id, journal)
  values (p_workspace_id, p_journal) on conflict (workspace_id, journal) do nothing;
  select * into v_seq from public.number_sequences
   where workspace_id = p_workspace_id and journal = p_journal for update;
  v_key := public.number_sequence_period_key(p_workspace_id, v_seq.reset);
  if v_seq.period_key <> v_key then
    v_value := 1;
    update public.number_sequences set period_key = v_key, next_value = 2
     where workspace_id = p_workspace_id and journal = p_journal;
  else
    v_value := v_seq.next_value;
    update public.number_sequences set next_value = next_value + 1
     where workspace_id = p_workspace_id and journal = p_journal;
  end if;
  return public.number_sequence_format(p_workspace_id, v_seq, v_value);
end;
$$;
revoke execute on function public.next_document_number(uuid, text) from public, anon, authenticated;

-- What the next number WOULD be, without taking it — the live preview
-- on the settings screen.
create or replace function public.preview_document_number(p_workspace_id uuid, p_journal text)
returns text language plpgsql stable security definer set search_path = public as $$
declare v_seq public.number_sequences; v_key text;
begin
  if not public.is_member_of(p_workspace_id) then raise exception 'not a member'; end if;
  select * into v_seq from public.number_sequences
   where workspace_id = p_workspace_id and journal = p_journal;
  if not found then
    v_seq.prefix := ''; v_seq.suffix := ''; v_seq.date_part := 'year';
    v_seq.digits := 4; v_seq.reset := 'yearly'; v_seq.period_key := ''; v_seq.next_value := 1;
  end if;
  v_key := public.number_sequence_period_key(p_workspace_id, v_seq.reset);
  return public.number_sequence_format(p_workspace_id, v_seq,
    case when v_seq.period_key = v_key then v_seq.next_value else 1 end);
end;
$$;
grant execute on function public.preview_document_number(uuid, text) to authenticated;

-- Owner only. A format change applies to what comes next and never
-- rewrites an issued document. The counter may be raised (to continue a
-- series kept elsewhere) and never lowered: lowering would reissue a
-- number that already names a document.
create or replace function public.set_number_sequence(
  p_workspace_id uuid, p_journal text, p_prefix text, p_suffix text,
  p_date_part text, p_digits int, p_reset text, p_next_value bigint default null)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_seq public.number_sequences;
begin
  if not public.is_owner_of(p_workspace_id) then
    raise exception 'only owners may configure number sequences';
  end if;
  insert into public.number_sequences (workspace_id, journal)
  values (p_workspace_id, p_journal) on conflict (workspace_id, journal) do nothing;
  select * into v_seq from public.number_sequences
   where workspace_id = p_workspace_id and journal = p_journal for update;
  if p_next_value is not null and p_next_value < v_seq.next_value then
    raise exception 'a sequence never goes backwards: % is below %', p_next_value, v_seq.next_value;
  end if;
  update public.number_sequences
     set prefix = coalesce(p_prefix, prefix), suffix = coalesce(p_suffix, suffix),
         date_part = coalesce(p_date_part, date_part), digits = coalesce(p_digits, digits),
         reset = coalesce(p_reset, reset), next_value = coalesce(p_next_value, next_value)
   where workspace_id = p_workspace_id and journal = p_journal;
end;
$$;
revoke execute on function public.set_number_sequence(uuid, text, text, text, text, int, text, bigint) from public, anon;
grant execute on function public.set_number_sequence(uuid, text, text, text, text, int, text, bigint) to authenticated;

insert into public.number_sequences (workspace_id, journal, prefix, date_part, digits, reset, period_key, next_value)
select w.id, 'invoice', 'INV-', 'year', 4, 'yearly',
       to_char(now() at time zone coalesce(w.timezone,'UTC'), 'YYYY'),
       coalesce((select count(*) from public.invoices i
                  where i.workspace_id = w.id
                    and date_part('year', i.issued_at) = date_part('year', now())), 0) + 1
  from public.workspaces w
on conflict (workspace_id, journal) do nothing;

-- The two issuers draw from the framework; the duplicated count is gone.
do $patch$
declare v_def text; v_old text;
begin
  select pg_get_functiondef(p.oid) into v_def from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname='public' and p.proname='create_invoice';
  v_old := E'  select count(*) into v_count from public.invoices\n'
        || E'    where workspace_id = p_workspace_id\n'
        || E'      and date_part(''year'', issued_at) = date_part(''year'', now());\n'
        || E'  v_number := ''INV-'' || date_part(''year'', now())::int || ''-''\n'
        || E'      || lpad((v_count + 1)::text, 4, ''0'');\n';
  if position(v_old in v_def) = 0 then raise exception '0164: create_invoice numbering anchor missing'; end if;
  execute replace(v_def, v_old, E'  v_number := public.next_document_number(p_workspace_id, ''invoice'');\n');
  select pg_get_functiondef(p.oid) into v_def from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname='public' and p.proname='settle_invoices';
  v_old := E'  select count(*) into v_count from public.invoices\n'
        || E'    where workspace_id = p_workspace_id and date_part(''year'', issued_at) = date_part(''year'', now());\n'
        || E'  v_number := ''INV-'' || date_part(''year'', now())::int || ''-'' || lpad((v_count + 1)::text, 4, ''0'');\n';
  if position(v_old in v_def) = 0 then raise exception '0164: settle_invoices numbering anchor missing'; end if;
  execute replace(v_def, v_old, E'  v_number := public.next_document_number(p_workspace_id, ''invoice'');\n');
end
$patch$;

-- SPDX-License-Identifier: 0BSD
-- 0165 — #928: three documents that carried no number take one from the
-- framework of 0164.
--
--   member          M-0001        drawn when a membership is created —
--                                 the owner's own at create_workspace, a
--                                 join, a managed profile — and frozen
--                                 into every invoice's buyer party as
--                                 "N° adhérent". Existing members are
--                                 numbered in join order so nobody's
--                                 number is younger than a newer member's.
--   vat_declaration DECL-2026-0001 drawn the moment a declaration is
--                                 FILED (a draft is not a document yet);
--                                 already-filed ones are numbered in
--                                 filing order per workspace-year.
--   payment         PAY-2026-0001 drawn inside the intent's own insert by
--                                 open_payment_intent, which the
--                                 create-payment-order function calls
--                                 instead of inserting itself — so the
--                                 reference the provider shows the payer
--                                 is the one the treasurer reconciles.
--
-- Each journal has its own defaults (number_sequence_defaults): a member
-- number never resets and carries no year; the others follow the invoice.
-- Both lazy paths (drawing and previewing) take them, so an owner who
-- never opened the settings screen still gets sensible series.
alter table public.members add column if not exists member_number text not null default '';
alter table public.vat_declarations add column if not exists number text not null default '';
alter table public.payment_intents add column if not exists reference text not null default '';

create or replace function public.number_sequence_defaults(p_journal text)
returns table(prefix text, date_part text, reset text) language sql immutable as $$
  select case p_journal when 'invoice' then 'INV-' when 'credit_note' then 'CN-'
                        when 'vat_declaration' then 'DECL-' when 'member' then 'M-'
                        when 'payment' then 'PAY-' else '' end,
         case p_journal when 'member' then 'none' else 'year' end,
         case p_journal when 'member' then 'never' else 'yearly' end;
$$;

create or replace function public.next_document_number(p_workspace_id uuid, p_journal text)
returns text language plpgsql volatile security definer set search_path = public as $$
declare v_seq public.number_sequences; v_key text; v_value bigint;
begin
  insert into public.number_sequences (workspace_id, journal, prefix, date_part, reset)
  select p_workspace_id, p_journal, d.prefix, d.date_part, d.reset from public.number_sequence_defaults(p_journal) d
  on conflict (workspace_id, journal) do nothing;
  select * into v_seq from public.number_sequences
   where workspace_id = p_workspace_id and journal = p_journal for update;
  v_key := public.number_sequence_period_key(p_workspace_id, v_seq.reset);
  if v_seq.period_key <> v_key then
    v_value := 1;
    update public.number_sequences set period_key = v_key, next_value = 2
     where workspace_id = p_workspace_id and journal = p_journal;
  else
    v_value := v_seq.next_value;
    update public.number_sequences set next_value = next_value + 1
     where workspace_id = p_workspace_id and journal = p_journal;
  end if;
  return public.number_sequence_format(p_workspace_id, v_seq, v_value);
end;
$$;

create or replace function public.preview_document_number(p_workspace_id uuid, p_journal text)
returns text language plpgsql stable security definer set search_path = public as $$
declare v_seq public.number_sequences; v_key text;
begin
  if not public.is_member_of(p_workspace_id) then raise exception 'not a member'; end if;
  select * into v_seq from public.number_sequences
   where workspace_id = p_workspace_id and journal = p_journal;
  if not found then
    select d.prefix, d.date_part, d.reset into v_seq.prefix, v_seq.date_part, v_seq.reset
      from public.number_sequence_defaults(p_journal) d;
    v_seq.suffix := ''; v_seq.digits := 4; v_seq.period_key := ''; v_seq.next_value := 1;
  end if;
  v_key := public.number_sequence_period_key(p_workspace_id, v_seq.reset);
  return public.number_sequence_format(p_workspace_id, v_seq,
    case when v_seq.period_key = v_key then v_seq.next_value else 1 end);
end;
$$;

with numbered as (
  select id, row_number() over (partition by workspace_id order by joined_at, id) rn from public.members
)
update public.members m set member_number = 'M-' || lpad(n.rn::text, 4, '0')
  from numbered n where n.id = m.id and m.member_number = '';
insert into public.number_sequences (workspace_id, journal, prefix, date_part, digits, reset, period_key, next_value)
select w.id, 'member', 'M-', 'none', 4, 'never', '',
       coalesce((select count(*) from public.members m where m.workspace_id = w.id), 0) + 1
  from public.workspaces w
on conflict (workspace_id, journal) do nothing;

with numbered as (
  select d.id, to_char(d.submitted_at at time zone coalesce(w.timezone,'UTC'), 'YYYY') yr,
         row_number() over (partition by d.workspace_id, to_char(d.submitted_at at time zone coalesce(w.timezone,'UTC'), 'YYYY')
                            order by d.submitted_at, d.id) rn
    from public.vat_declarations d join public.workspaces w on w.id = d.workspace_id
   where d.status = 'submitted'
)
update public.vat_declarations d set number = 'DECL-' || n.yr || '-' || lpad(n.rn::text, 4, '0')
  from numbered n where n.id = d.id and d.number = '';
insert into public.number_sequences (workspace_id, journal, prefix, date_part, digits, reset, period_key, next_value)
select w.id, 'vat_declaration', 'DECL-', 'year', 4, 'yearly',
       to_char(now() at time zone coalesce(w.timezone,'UTC'), 'YYYY'),
       coalesce((select count(*) from public.vat_declarations d
                  where d.workspace_id = w.id and d.status = 'submitted'
                    and to_char(d.submitted_at at time zone coalesce(w.timezone,'UTC'), 'YYYY')
                      = to_char(now() at time zone coalesce(w.timezone,'UTC'), 'YYYY')), 0) + 1
  from public.workspaces w
on conflict (workspace_id, journal) do nothing;

create or replace function public.open_payment_intent(
  p_workspace_id uuid, p_member_id uuid, p_provider text, p_period text, p_amount_cents int, p_currency text)
returns table(id uuid, reference text) language plpgsql volatile security definer set search_path = public as $$
declare v_id uuid := gen_random_uuid(); v_ref text;
begin
  v_ref := public.next_document_number(p_workspace_id, 'payment');
  -- (provider, order_id) is unique; until the provider answers, the
  -- intent's own id stands in for the order id it does not have yet.
  insert into public.payment_intents (id, workspace_id, member_id, provider, order_id, period, amount_cents, currency, reference)
  values (v_id, p_workspace_id, p_member_id, p_provider, 'pending:' || v_id::text, p_period, p_amount_cents, p_currency, v_ref);
  return query select v_id, v_ref;
end;
$$;
revoke execute on function public.open_payment_intent(uuid, uuid, text, text, int, text) from public, anon, authenticated;
grant execute on function public.open_payment_intent(uuid, uuid, text, text, int, text) to service_role;

do $patch$
declare v_def text; v_old text;
begin
  select pg_get_functiondef(p.oid) into v_def from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='create_workspace';
  v_old := E'  insert into public.members (workspace_id, user_id, is_admin, is_owner)\n  values (ws_id, auth.uid(), true, true);\n';
  if position(v_old in v_def) = 0 then raise exception '0165: create_workspace anchor missing'; end if;
  execute replace(v_def, v_old, v_old || E'  update public.members set member_number = public.next_document_number(ws_id, ''member'')\n    where workspace_id = ws_id and user_id = auth.uid();\n');

  select pg_get_functiondef(p.oid) into v_def from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='join_workspace';
  v_old := E'          is_admin = public.members.is_admin or excluded.is_admin\n    returning id into v_member_id;\n';
  if position(v_old in v_def) = 0 then raise exception '0165: join_workspace anchor missing'; end if;
  execute replace(v_def, v_old, v_old || E'  update public.members set member_number = public.next_document_number(ws_id, ''member'')\n    where id = v_member_id and member_number = '''';\n');

  select pg_get_functiondef(p.oid) into v_def from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='create_managed_member';
  v_old := E'          public.managed_identity_name(v_identity))\n  returning id into v_id;\n';
  if position(v_old in v_def) = 0 then raise exception '0165: create_managed_member anchor missing'; end if;
  execute replace(v_def, v_old, v_old || E'  update public.members set member_number = public.next_document_number(p_workspace_id, ''member'')\n    where id = v_id and member_number = '''';\n');

  select pg_get_functiondef(p.oid) into v_def from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='create_invoice';
  v_old := E'      ''legal_id'', v_member_legal,\n';
  if position(v_old in v_def) = 0 then raise exception '0165: create_invoice anchor missing'; end if;
  execute replace(v_def, v_old, v_old || E'      ''member_number'', coalesce(v_subject.member_number, ''''),\n');

  select pg_get_functiondef(p.oid) into v_def from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='mark_vat_declaration_submitted';
  v_old := E'     set status = ''submitted'',\n';
  if position(v_old in v_def) = 0 then raise exception '0165: mark_vat_declaration_submitted anchor missing'; end if;
  execute replace(v_def, v_old, v_old || E'         number = case when number = '''' then public.next_document_number(workspace_id, ''vat_declaration'') else number end,\n');
end
$patch$;

-- SPDX-License-Identifier: 0BSD
-- 0166 — #937: the platform owner sees every workspace, and who owns
-- the ones they are not in.
--
-- The account that operates the deployment needs an overview of the
-- whole database from inside the app. That is a PLATFORM role, not a
-- workspace one: it is held server-side in platform_admins (never an
-- e-mail check in a client), it bypasses no workspace rule, and every
-- read of another workspace's owners is written to platform_access_log,
-- which the workspace's own owners can read — the same transparency a
-- managed profile gets over who looked at it (0161).
--
-- An owner must always have an e-mail address: the operator's overview
-- is useless without one, and so is every notice the app sends. Every
-- current owner has one (199/199 at the time of writing), so the rule is
-- enforced from here on where ownership is granted — create_workspace
-- and activate_co_owner — with no backfill needed.
create table if not exists public.platform_admins (
  user_id  uuid primary key references auth.users(id) on delete cascade,
  added_at timestamptz not null default now()
);
alter table public.platform_admins enable row level security;
drop policy if exists platform_admins_self on public.platform_admins;
create policy platform_admins_self on public.platform_admins for select using (user_id = auth.uid());
insert into public.platform_admins (user_id) select id from auth.users where email = 'fdittgen@gmail.com' on conflict do nothing;

create or replace function public.is_platform_owner()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.platform_admins where user_id = auth.uid());
$$;
grant execute on function public.is_platform_owner() to authenticated;

-- The sign-in e-mail or the profile's billing e-mail — either satisfies
-- the rule. Definer because auth.users is not readable by clients; not
-- callable by clients either, it is a guard's helper.
create or replace function public.user_has_email(p_user_id uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from auth.users u where u.id = p_user_id and coalesce(u.email, '') <> '')
      or exists (select 1 from public.profiles p where p.id = p_user_id and coalesce(p.email, '') <> '');
$$;
revoke execute on function public.user_has_email(uuid) from public, anon, authenticated;

create table if not exists public.platform_access_log (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null,
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  category     text not null check (category in ('owners')),
  at           timestamptz not null default now()
);
alter table public.platform_access_log enable row level security;
drop policy if exists platform_access_log_select on public.platform_access_log;
create policy platform_access_log_select on public.platform_access_log for select
  using (user_id = auth.uid() or public.is_owner_of(workspace_id));

-- Every workspace, with whether the caller is in it. Refuses — rather
-- than returning nothing — for anyone else, so an empty list can never
-- be mistaken for an empty database.
create or replace function public.list_all_workspaces()
returns table(id uuid, name text, environment text, member_count bigint, owner_count bigint, is_member boolean)
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_platform_owner() then raise exception 'platform owners only'; end if;
  return query
    select w.id, w.name, w.environment,
           (select count(*) from public.members m where m.workspace_id = w.id and m.status = 'active'),
           (select count(*) from public.members m where m.workspace_id = w.id and m.is_owner),
           exists (select 1 from public.members m where m.workspace_id = w.id and m.user_id = auth.uid())
      from public.workspaces w
     order by w.name;
end;
$$;
grant execute on function public.list_all_workspaces() to authenticated;

-- The owners of one workspace, name and e-mail. Volatile: the read is
-- logged before it is answered.
create or replace function public.workspace_owners(p_workspace_id uuid)
returns table(member_id uuid, name text, email text)
language plpgsql volatile security definer set search_path = public as $$
begin
  if not public.is_platform_owner() then raise exception 'platform owners only'; end if;
  insert into public.platform_access_log (user_id, workspace_id, category)
  values (auth.uid(), p_workspace_id, 'owners');
  return query
    select m.id,
           coalesce(nullif(public.profile_full_name(p), ''), p.display_name, ''),
           coalesce(nullif(p.email, ''), u.email, '')
      from public.members m
      left join public.profiles p on p.id = m.user_id
      left join auth.users u on u.id = m.user_id
     where m.workspace_id = p_workspace_id and m.is_owner
     order by 2;
end;
$$;
grant execute on function public.workspace_owners(uuid) to authenticated;

-- Ownership is granted in two places; both now insist on an e-mail.
do $patch$
declare v_def text; v_old text;
begin
  select pg_get_functiondef(p.oid) into v_def from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='create_workspace';
  v_old := E'raise exception ''not authenticated''; end if;\n';
  if position(v_old in v_def) = 0 then raise exception '0166: create_workspace anchor missing'; end if;
  execute replace(v_def, v_old, v_old || E'  if not public.user_has_email(auth.uid()) then raise exception ''an owner must have an e-mail address''; end if;\n');

  select pg_get_functiondef(p.oid) into v_def from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='activate_co_owner';
  v_old := E'  update public.members\n    set is_owner = true, is_admin = true, co_owner = ''none''\n    where id = p_member_id;\n';
  if position(v_old in v_def) = 0 then raise exception '0166: activate_co_owner anchor missing'; end if;
  execute replace(v_def, v_old,
    E'  if not public.user_has_email((select user_id from public.members where id = p_member_id)) then\n    raise exception ''an owner must have an e-mail address'';\n  end if;\n' || v_old);
end
$patch$;

-- SPDX-License-Identifier: 0BSD
-- 0168 — #945: sites. The unit of address.
--
-- A workspace had one address, and every level, booking and document
-- stood at it. A workspace that opens a second building needs each
-- level to belong to a SITE with its own address and its own SIRET (the
-- establishment's, under the entity's SIREN), each member to have a home
-- site, and each document to name the site it concerns (#946).
--
-- Every workspace gets its default site from the address it already
-- has, so nothing changes until a second site is created: a null
-- levels.site_id or members.home_site_id means "the default site".
create table if not exists public.sites (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  name         text not null check (char_length(name) between 1 and 80),
  street       text not null default '' check (char_length(street) <= 200),
  postal_code  text not null default '' check (char_length(postal_code) <= 16),
  city         text not null default '' check (char_length(city) <= 120),
  country_code text not null default '' check (char_length(country_code) <= 2),
  legal_id     text not null default '' check (char_length(legal_id) <= 40),
  is_default   boolean not null default false,
  sort_order   int not null default 0,
  created_at   timestamptz not null default now()
);
create unique index if not exists sites_one_default_per_workspace on public.sites (workspace_id) where is_default;
alter table public.sites enable row level security;
drop policy if exists sites_select on public.sites;
create policy sites_select on public.sites for select using (public.is_member_of(workspace_id));
alter table public.levels add column if not exists site_id uuid references public.sites(id) on delete set null;
alter table public.members add column if not exists home_site_id uuid references public.sites(id) on delete set null;

insert into public.sites (workspace_id, name, street, postal_code, city, country_code, legal_id, is_default, sort_order)
select w.id, coalesce(nullif(w.name, ''), 'Site'), coalesce(w.street, ''), coalesce(w.postal_code, ''), coalesce(w.city, ''),
       coalesce(w.country_code, ''), coalesce(w.legal_id, ''), true, 0
  from public.workspaces w
 where not exists (select 1 from public.sites s where s.workspace_id = w.id and s.is_default);

create or replace function public.default_site(p_workspace_id uuid) returns public.sites
language sql stable security definer set search_path = public as $$
  select s from public.sites s where s.workspace_id = p_workspace_id and s.is_default limit 1;
$$;

-- The site a member's documents name: their home site, else the default.
create or replace function public.document_site_for_member(p_member_id uuid) returns public.sites
language sql stable security definer set search_path = public as $$
  select coalesce((select s from public.sites s join public.members m on m.home_site_id = s.id where m.id = p_member_id),
                  (select public.default_site(m.workspace_id) from public.members m where m.id = p_member_id));
$$;
grant execute on function public.document_site_for_member(uuid) to authenticated;

create or replace function public.upsert_site(
  p_workspace_id uuid, p_id uuid, p_name text, p_street text, p_postal_code text, p_city text,
  p_country_code text, p_legal_id text, p_sort_order int default 0)
returns uuid language plpgsql volatile security definer set search_path = public as $$
declare v_id uuid;
begin
  if not public.is_admin_of(p_workspace_id) then raise exception 'admins only'; end if;
  if p_id is null then
    insert into public.sites (workspace_id, name, street, postal_code, city, country_code, legal_id, sort_order)
    values (p_workspace_id, btrim(p_name), btrim(coalesce(p_street,'')), btrim(coalesce(p_postal_code,'')), btrim(coalesce(p_city,'')),
            upper(btrim(coalesce(p_country_code,''))), btrim(coalesce(p_legal_id,'')), coalesce(p_sort_order, 0))
    returning id into v_id;
  else
    update public.sites
       set name = btrim(p_name), street = btrim(coalesce(p_street,'')), postal_code = btrim(coalesce(p_postal_code,'')),
           city = btrim(coalesce(p_city,'')), country_code = upper(btrim(coalesce(p_country_code,''))),
           legal_id = btrim(coalesce(p_legal_id,'')), sort_order = coalesce(p_sort_order, sort_order)
     where id = p_id and workspace_id = p_workspace_id
    returning id into v_id;
    if v_id is null then raise exception 'unknown site'; end if;
  end if;
  return v_id;
end;
$$;
grant execute on function public.upsert_site(uuid, uuid, text, text, text, text, text, text, int) to authenticated;

-- Levels and members of a deleted site fall back to the default (null).
create or replace function public.delete_site(p_site_id uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_site public.sites;
begin
  select * into v_site from public.sites where id = p_site_id;
  if v_site.id is null then raise exception 'unknown site'; end if;
  if not public.is_admin_of(v_site.workspace_id) then raise exception 'admins only'; end if;
  if v_site.is_default then raise exception 'the default site cannot be deleted'; end if;
  update public.levels set site_id = null where site_id = p_site_id;
  update public.members set home_site_id = null where home_site_id = p_site_id;
  delete from public.sites where id = p_site_id;
end;
$$;
grant execute on function public.delete_site(uuid) to authenticated;

create or replace function public.set_level_site(p_level_id uuid, p_site_id uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_ws uuid;
begin
  select workspace_id into v_ws from public.levels where id = p_level_id;
  if v_ws is null then raise exception 'unknown level'; end if;
  if not public.is_admin_of(v_ws) then raise exception 'admins only'; end if;
  if p_site_id is not null and not exists (select 1 from public.sites where id = p_site_id and workspace_id = v_ws) then
    raise exception 'site is not in this workspace';
  end if;
  update public.levels set site_id = p_site_id where id = p_level_id;
end;
$$;
grant execute on function public.set_level_site(uuid, uuid) to authenticated;

create or replace function public.set_member_home_site(p_member_id uuid, p_site_id uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_ws uuid;
begin
  select workspace_id into v_ws from public.members where id = p_member_id;
  if v_ws is null then raise exception 'unknown member'; end if;
  if not public.is_admin_of(v_ws) then raise exception 'admins only'; end if;
  if p_site_id is not null and not exists (select 1 from public.sites where id = p_site_id and workspace_id = v_ws) then
    raise exception 'site is not in this workspace';
  end if;
  update public.members set home_site_id = p_site_id where id = p_member_id;
end;
$$;
grant execute on function public.set_member_home_site(uuid, uuid) to authenticated;

-- SPDX-License-Identifier: 0BSD
-- 0169 — #946: a document names the site it concerns.
--
-- With sites (0168), the seller's address on a document is the address
-- of the member's HOME site when that site has one of its own — with the
-- establishment's registration beside it — and the workspace's
-- otherwise. Each attendance row of the details names the site the
-- reservation stood at, so a member who worked from another site sees
-- it on the invoice. The frozen legacy address column follows the same
-- rule, so older readers print the same address as newer ones.
--
-- create_invoice is patched at five asserted anchors; a silent no-op
-- would freeze the wrong address on a real document.
create or replace function public.reservation_site(r public.reservations) returns public.sites
language sql stable security definer set search_path = public as $$
  select st from public.sites st
   where st.id = coalesce(
     (select l.site_id from public.levels l where l.id = r.level_id),
     (select l.site_id from public.offices o join public.levels l on l.id = o.level_id where o.id = r.office_id),
     (select l.site_id from public.desks d join public.offices o on o.id = d.office_id join public.levels l on l.id = o.level_id where d.id = r.desk_id),
     (select l.site_id from public.seats s join public.desks d on d.id = s.desk_id join public.offices o on o.id = d.office_id join public.levels l on l.id = o.level_id where s.id = r.seat_id));
$$;

do $patch$
declare v_def text; v_old text;
begin
  select pg_get_functiondef(p.oid) into v_def from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='create_invoice';
  v_old := E'  v_signature text;\n';
  if position(v_old in v_def) = 0 then raise exception '0169: anchor A missing'; end if;
  v_def := replace(v_def, v_old, v_old || E'  v_site public.sites;\n');
  v_old := E'  v_parties := jsonb_build_object(\n';
  if position(v_old in v_def) = 0 then raise exception '0169: anchor B missing'; end if;
  v_def := replace(v_def, v_old, E'  v_site := public.document_site_for_member(v_subject.id);\n' || v_old);
  v_old := E'    ''seller'', jsonb_build_object(\n      ''name'', v_workspace.name,\n      ''street'', coalesce(nullif(v_workspace.street, ''''),\n                         coalesce(v_workspace.address, '''')),\n      ''city'', coalesce(v_workspace.city, ''''),\n      ''postal_code'', coalesce(v_workspace.postal_code, ''''),\n      ''country'', v_workspace.country_code,\n      ''vat_id'', coalesce(v_workspace.vat_id, ''''),\n      ''legal_id'', coalesce(v_workspace.legal_id, ''''),\n';
  if position(v_old in v_def) = 0 then raise exception '0169: anchor C missing'; end if;
  v_def := replace(v_def, v_old,
       E'    ''seller'', jsonb_build_object(\n      ''name'', v_workspace.name,\n'
    || E'      ''site'', coalesce(v_site.name, ''''),\n'
    || E'      ''site_default'', coalesce(v_site.is_default, true),\n'
    || E'      ''street'', case when v_site.id is not null and not v_site.is_default and (v_site.street <> '''' or v_site.city <> '''') then v_site.street\n'
    || E'                       else coalesce(nullif(v_workspace.street, ''''), coalesce(v_workspace.address, '''')) end,\n'
    || E'      ''city'', case when v_site.id is not null and not v_site.is_default and (v_site.street <> '''' or v_site.city <> '''') then v_site.city else coalesce(v_workspace.city, '''') end,\n'
    || E'      ''postal_code'', case when v_site.id is not null and not v_site.is_default and (v_site.street <> '''' or v_site.city <> '''') then v_site.postal_code else coalesce(v_workspace.postal_code, '''') end,\n'
    || E'      ''country'', case when v_site.id is not null and not v_site.is_default and v_site.country_code <> '''' then v_site.country_code else v_workspace.country_code end,\n'
    || E'      ''vat_id'', coalesce(v_workspace.vat_id, ''''),\n'
    || E'      ''legal_id'', case when v_site.id is not null and not v_site.is_default and v_site.legal_id <> '''' then v_site.legal_id else coalesce(v_workspace.legal_id, '''') end,\n');
  v_old := E'              (select l.name from public.levels l where l.id = r.level_id),\n              ''''))\n';
  if position(v_old in v_def) = 0 then raise exception '0169: anchor D missing'; end if;
  v_def := replace(v_def, v_old, v_old || E'            , ''site'', coalesce((public.reservation_site(r)).name, '''')\n');
  v_old := E'     coalesce(v_workspace.address, ''''), v_issuer_name, v_signature,\n';
  if position(v_old in v_def) = 0 then raise exception '0169: anchor E missing'; end if;
  v_def := replace(v_def, v_old,
       E'     case when v_site.id is not null and not v_site.is_default and (v_site.street <> '''' or v_site.city <> '''')\n'
    || E'          then btrim(v_site.street || '', '' || v_site.postal_code || '' '' || v_site.city, '', '')\n'
    || E'          else coalesce(v_workspace.address, '''') end, v_issuer_name, v_signature,\n');
