-- SPDX-License-Identifier: 0BSD
-- 0174 — #956: verify an invoice's fingerprint on demand.
--
-- create_invoice has signed every document since 0060 (SHA-256 over the
-- frozen columns) and the invoices_no_mutation trigger refuses any edit
-- of a signed row; nothing ever CHECKED the fingerprint. Now every new
-- document is stamped with the formula that signed it (signature_algo
-- 7, the concatenation of 0142 onwards) and verify_invoice_signature
-- recomputes it from the stored columns:
--
--   verified      the fingerprint matches;
--   altered       a stamped row that no longer matches — the only case
--                 that means what an auditor fears;
--   unverifiable  a row signed before the stamp whose fingerprint no
--                 longer matches. Migrations up to 0152 rewrote signed
--                 columns of existing rows (every pilot invoice issued
--                 before 2026-09-04 is in that case); the verifier must
--                 not call that an alteration nobody made.
alter table public.invoices add column if not exists signature_algo int;

do $patch$
declare v_def text; v_old text;
begin
  select pg_get_functiondef(p.oid) into v_def from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='create_invoice' and p.prokind='f';
  v_old := E'     kind)\n  values\n    (v_id,';
  if position(v_old in v_def) = 0 then raise exception '0174: anchor A missing'; end if;
  v_def := replace(v_def, v_old, E'     kind, signature_algo)\n  values\n    (v_id,');
  v_old := E'     p_kind);\n  return v_id;';
  if position(v_old in v_def) = 0 then raise exception '0174: anchor B missing'; end if;
  v_def := replace(v_def, v_old, E'     p_kind, 7);\n  return v_id;');
  execute v_def;
end
$patch$;

create or replace function public.verify_invoice_signature(p_invoice_id uuid) returns text
language plpgsql stable security definer set search_path = public as $$
declare v public.invoices; v_sig text;
begin
  select * into v from public.invoices where id = p_invoice_id;
  if v.id is null then raise exception 'unknown invoice'; end if;
  if not public.is_member_of(v.workspace_id) then raise exception 'not a member'; end if;
  v_sig := encode(extensions.digest(convert_to(concat_ws('|',
      v.id::text, v.number, v.workspace_id::text, v.member_id::text,
      v.member_name, v.member_address, v.workspace_name,
      coalesce(v.workspace_address, ''), v.issuer_name,
      v.period, v.lines::text, v.total_cents::text, v.currency,
      v.issued_at::date::text, coalesce(v.replaces_invoice_id::text, ''),
      coalesce(v.replaces_number, ''), coalesce(v.details::text, ''),
      v.parties::text, v.vat_totals::text, v.kind),
      'UTF8'), 'sha256'), 'hex');
  if v_sig = v.signature then return 'verified'; end if;
  if v.signature_algo is null then return 'unverifiable'; end if;
  return 'altered';
end;
$$;
grant execute on function public.verify_invoice_signature(uuid) to authenticated;

-- SPDX-License-Identifier: 0BSD
-- 0175 — #960: detailed invoices issue again.
--
-- 0169 added the site name to each attendance row of a detailed invoice
-- by inserting the pair after the anchor that closes the `space`
-- coalesce. That parenthesis also closes jsonb_build_object, so the pair
-- became two extra arguments of jsonb_agg and every detailed invoice
-- failed with 42883 (`function jsonb_agg(jsonb, unknown, text) does not
-- exist`). A plain invoice never reaches the block, which is why 0169's
-- harness passed. The pair moves inside the object at an asserted
-- anchor; from here on the harness issues a DETAILED invoice in a
-- rolled-back transaction.
do $patch$
declare v_def text; v_old text; v_new text;
begin
  select pg_get_functiondef(p.oid) into v_def from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='create_invoice' and p.prokind='f';
  v_old := E'              ''''))\n            , ''site'', coalesce((public.reservation_site(r)).name, '''')\n          order by r.starts_at)\n';
  v_new := E'              ''''),\n            ''site'', coalesce((public.reservation_site(r)).name, ''''))\n          order by r.starts_at)\n';
  if position(v_old in v_def) = 0 then raise exception '0175: anchor missing'; end if;
  v_def := replace(v_def, v_old, v_new);
  execute v_def;
end
$patch$;

-- SPDX-License-Identifier: 0BSD
-- 0176 — #963: a feature toggle writes ONE key, never a snapshot.
--
-- Three screens rewrote workspaces.feature_flags wholesale from their
-- own copy of the row (the Features screen, the NFC screen from the
-- EFFECTIVE set, the settings import from a file). Any copy older than
-- the row put the row back to what the copy remembered: the pilot
-- switched three features on and the third write turned the first two
-- off again. From here on the owner merges through this function; the
-- row keeps every key the write does not name.
create or replace function public.set_feature_flags(p_workspace_id uuid, p_flags jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_key text; v_val jsonb; v_flags jsonb;
begin
  if auth.uid() is null or not public.is_owner_of(p_workspace_id) then
    raise exception 'only an owner changes the features';
  end if;
  if p_flags is null or jsonb_typeof(p_flags) <> 'object' then
    raise exception 'feature flags must be an object';
  end if;
  for v_key, v_val in select * from jsonb_each(p_flags) loop
    if v_key !~ '^[A-Za-z][A-Za-z0-9]{0,63}$' then
      raise exception 'unknown feature key %', v_key;
    end if;
    if jsonb_typeof(v_val) <> 'boolean' then
      raise exception 'feature % must be true or false', v_key;
    end if;
  end loop;
  update public.workspaces
     set feature_flags = coalesce(feature_flags, '{}'::jsonb) || p_flags
   where id = p_workspace_id
   returning feature_flags into v_flags;
  return v_flags;
end $$;
revoke execute on function public.set_feature_flags(uuid, jsonb) from public, anon;
grant execute on function public.set_feature_flags(uuid, jsonb) to authenticated;

-- SPDX-License-Identifier: 0BSD
-- 0178 — #974: a member picks their own home site.
--
-- set_member_home_site (0168) was admins-only. The home site decides
-- which address the person's documents carry and which levels are
-- theirs by default — their own affair on a multi-site workspace, so
-- the person now sets it from their profile; an admin still sets
-- anyone's. Harnessed: a plain member sets their own, is refused
-- another's; the owner sets anyone's.
create or replace function public.set_member_home_site(p_member_id uuid, p_site_id uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_ws uuid; v_user uuid;
begin
  select workspace_id, user_id into v_ws, v_user from public.members where id = p_member_id;
  if v_ws is null then raise exception 'unknown member'; end if;
  -- #974 — a member picks their OWN home site; an admin picks anyone's.
  if not (public.is_admin_of(v_ws) or (v_user is not null and v_user = auth.uid())) then
    raise exception 'admins only';
  end if;
  if p_site_id is not null and not exists (select 1 from public.sites where id = p_site_id and workspace_id = v_ws) then
    raise exception 'site is not in this workspace';
  end if;
  update public.members set home_site_id = p_site_id where id = p_member_id;
end;
$$;

