-- SPDX-License-Identifier: 0BSD
-- 0183 — #992: system columns on every table.
--
-- Six technical columns the core relies on, on every table of the public
-- schema, existing and future: created_datetime, modified_datetime,
-- company_id (the workspace), site_id, created_by_user, modified_by_user.
-- One trigger stamps them on every write; one helper adds them to a
-- table together with the trigger and the backfill. Every CREATE TABLE
-- from now on calls ensure_system_columns() in the same migration — a
-- lint pins it. Existing columns (created_at, workspace_id, created_by…)
-- stay: the six are additions, never replacements.

-- The six, as one list every guard can subtract.
create or replace function public.system_column_names()
returns text[] language sql immutable as $fn$
  select array['created_datetime', 'modified_datetime', 'company_id', 'site_id',
               'created_by_user', 'modified_by_user'];
$fn$;

create or replace function public.system_columns_stamp()
returns trigger language plpgsql as $fn$
declare
  j jsonb := to_jsonb(new);
  patch jsonb := '{}'::jsonb;
begin
  if tg_op = 'INSERT' then
    if j->>'created_datetime' is null then
      patch := patch || jsonb_build_object('created_datetime', now());
    end if;
    if j->>'created_by_user' is null then
      patch := patch || jsonb_build_object('created_by_user', auth.uid());
    end if;
  end if;
  patch := patch || jsonb_build_object('modified_datetime', now(), 'modified_by_user', auth.uid());
  if tg_table_name = 'workspaces' then
    patch := patch || jsonb_build_object('company_id', j->'id');
  elsif j ? 'workspace_id' and j->>'workspace_id' is not null then
    patch := patch || jsonb_build_object('company_id', j->'workspace_id');
  end if;
  if tg_table_name = 'sites' then
    patch := patch || jsonb_build_object('site_id', j->'id');
  elsif tg_table_name = 'members' and j->>'home_site_id' is not null then
    patch := patch || jsonb_build_object('site_id', j->'home_site_id');
  elsif j ? 'level_id' and j->>'level_id' is not null and j->>'site_id' is null then
    patch := patch || jsonb_build_object('site_id',
      (select l.site_id from public.levels l where l.id = (j->>'level_id')::uuid));
  end if;
  new := jsonb_populate_record(new, patch);
  return new;
end;
$fn$;

create or replace function public.ensure_system_columns(p_table text)
returns void language plpgsql as $fn$
declare
  has_created_at boolean;
  has_workspace boolean;
  has_level boolean;
begin
  execute format('alter table public.%I add column if not exists created_datetime timestamptz not null default now()', p_table);
  execute format('alter table public.%I add column if not exists modified_datetime timestamptz not null default now()', p_table);
  execute format('alter table public.%I add column if not exists company_id uuid', p_table);
  execute format('alter table public.%I add column if not exists site_id uuid', p_table);
  execute format('alter table public.%I add column if not exists created_by_user uuid', p_table);
  execute format('alter table public.%I add column if not exists modified_by_user uuid', p_table);

  select exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = p_table and column_name = 'created_at'),
         exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = p_table and column_name = 'workspace_id'),
         exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = p_table and column_name = 'level_id')
    into has_created_at, has_workspace, has_level;
  -- The backfill runs with every user trigger silent: the guards
  -- (invoices are immutable) would refuse the columns they never knew,
  -- and no AFTER trigger queues an event that would block the ALTER
  -- TABLE below.
  execute format('alter table public.%I disable trigger user', p_table);
  if has_created_at then
    execute format('update public.%I set created_datetime = created_at, modified_datetime = created_at where created_at is not null', p_table);
  end if;
  if p_table = 'workspaces' then
    execute 'update public.workspaces set company_id = id where company_id is null';
  elsif has_workspace then
    execute format('update public.%I set company_id = workspace_id where company_id is null', p_table);
  end if;
  if p_table = 'sites' then
    execute 'update public.sites set site_id = id where site_id is null';
  elsif p_table = 'members' then
    execute 'update public.members set site_id = home_site_id where site_id is null and home_site_id is not null';
  elsif has_level then
    execute format('update public.%I t set site_id = l.site_id from public.levels l where l.id = t.level_id and t.site_id is null', p_table);
  end if;
  execute format('alter table public.%I enable trigger user', p_table);
  -- zz_: BEFORE triggers fire in name order; the stamp goes last, after
  -- every guard has judged the row.
  execute format('drop trigger if exists zz_system_columns_stamp on public.%I', p_table);
  execute format('create trigger zz_system_columns_stamp before insert or update on public.%I for each row execute function public.system_columns_stamp()', p_table);
end;
$fn$;
revoke execute on function public.ensure_system_columns(text) from public, anon, authenticated;

-- The invoice guard compares whole rows; the stamp must not count.
create or replace function public.invoices_immutable()
returns trigger language plpgsql as $fn$
declare
  o jsonb := to_jsonb(old) - public.system_column_names();
  n jsonb := to_jsonb(new) - public.system_column_names();
begin
  if tg_op = 'UPDATE'
     and old.voided_at is null
     and new.voided_at is not null
     and (o - 'voided_at' - 'voided_by_name') = (n - 'voided_at' - 'voided_by_name') then
    return new;
  end if;
  -- #804 — the settlement back-pointer, set once…
  if tg_op = 'UPDATE'
     and old.settled_by_invoice_id is null
     and new.settled_by_invoice_id is not null
     and (o - 'settled_by_invoice_id') = (n - 'settled_by_invoice_id') then
    return new;
  end if;
  -- #816 — …and cleared once, when the settlement did not stand.
  if tg_op = 'UPDATE'
     and old.settled_by_invoice_id is not null
     and new.settled_by_invoice_id is null
     and (o - 'settled_by_invoice_id') = (n - 'settled_by_invoice_id') then
    return new;
  end if;
  raise exception 'invoices are immutable';
end;
$fn$;

-- Every table of the public schema, existing today.
do $all$
declare t record;
begin
  for t in select table_name from information_schema.tables
            where table_schema = 'public' and table_type = 'BASE TABLE'
            order by table_name loop
    perform public.ensure_system_columns(t.table_name);
  end loop;
end;
$all$;

-- SPDX-License-Identifier: 0BSD
-- 0184 — #992: the system columns are the core's — owned, never forged.
--
-- 0183 added the six and stamped what was missing. This makes them the
-- server's alone: on INSERT the creation stamp is always now() and the
-- caller, whatever the row said; on UPDATE the creation stamp is kept
-- from the stored row and the modification stamp is always now() and
-- the caller; company_id and site_id are always recomputed from the
-- row's own keys. Two constraints state the invariants: a row is never
-- modified before it was created, and a row that belongs to a workspace
-- always says which one. A client value for any of the six is ignored.

create or replace function public.system_columns_stamp()
returns trigger language plpgsql as $fn$
declare
  j jsonb := to_jsonb(new);
  patch jsonb := '{}'::jsonb;
begin
  if tg_op = 'INSERT' then
    patch := patch || jsonb_build_object(
      'created_datetime', now(), 'created_by_user', auth.uid());
  else
    -- The creation stamp never moves.
    patch := patch || jsonb_build_object(
      'created_datetime', old.created_datetime,
      'created_by_user', old.created_by_user);
  end if;
  patch := patch || jsonb_build_object(
    'modified_datetime', now(), 'modified_by_user', auth.uid());
  if tg_table_name = 'workspaces' then
    patch := patch || jsonb_build_object('company_id', j->'id');
  elsif j ? 'workspace_id' then
    patch := patch || jsonb_build_object('company_id', j->'workspace_id');
  end if;
  if tg_table_name = 'sites' then
    patch := patch || jsonb_build_object('site_id', j->'id');
  elsif tg_table_name = 'members' then
    patch := patch || jsonb_build_object('site_id', j->'home_site_id');
  elsif j ? 'level_id' then
    patch := patch || jsonb_build_object('site_id',
      (select l.site_id from public.levels l where l.id = (j->>'level_id')::uuid));
  end if;
  new := jsonb_populate_record(new, patch);
  return new;
end;
$fn$;

-- The helper now states the invariants too, and its backfill only
-- touches rows the default stamped later than their true creation.
create or replace function public.ensure_system_columns(p_table text)
returns void language plpgsql as $fn$
declare
  has_created_at boolean;
  has_workspace boolean;
  has_level boolean;
begin
  execute format('alter table public.%I add column if not exists created_datetime timestamptz not null default now()', p_table);
  execute format('alter table public.%I add column if not exists modified_datetime timestamptz not null default now()', p_table);
  execute format('alter table public.%I add column if not exists company_id uuid', p_table);
  execute format('alter table public.%I add column if not exists site_id uuid', p_table);
  execute format('alter table public.%I add column if not exists created_by_user uuid', p_table);
  execute format('alter table public.%I add column if not exists modified_by_user uuid', p_table);
  select exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = p_table and column_name = 'created_at'),
         exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = p_table and column_name = 'workspace_id'),
         exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = p_table and column_name = 'level_id')
    into has_created_at, has_workspace, has_level;
  execute format('alter table public.%I disable trigger user', p_table);
  if has_created_at then
    execute format('update public.%I set created_datetime = created_at, modified_datetime = created_at where created_at is not null and created_datetime > created_at', p_table);
  end if;
  if p_table = 'workspaces' then
    execute 'update public.workspaces set company_id = id where company_id is distinct from id';
  elsif has_workspace then
    execute format('update public.%I set company_id = workspace_id where company_id is distinct from workspace_id', p_table);
  end if;
  if p_table = 'sites' then
    execute 'update public.sites set site_id = id where site_id is distinct from id';
  elsif p_table = 'members' then
    execute 'update public.members set site_id = home_site_id where site_id is distinct from home_site_id';
  elsif has_level then
    execute format('update public.%I t set site_id = l.site_id from public.levels l where l.id = t.level_id and t.site_id is distinct from l.site_id', p_table);
  end if;
  execute format('alter table public.%I enable trigger user', p_table);
  execute format('drop trigger if exists zz_system_columns_stamp on public.%I', p_table);
  execute format('create trigger zz_system_columns_stamp before insert or update on public.%I for each row execute function public.system_columns_stamp()', p_table);
  -- The invariants.
  execute format('alter table public.%I drop constraint if exists system_columns_order', p_table);
  execute format('alter table public.%I add constraint system_columns_order check (modified_datetime >= created_datetime)', p_table);
  execute format('alter table public.%I drop constraint if exists system_company_present', p_table);
  if has_workspace or p_table = 'workspaces' then
    execute format('alter table public.%I add constraint system_company_present check (company_id is not null)', p_table);
  end if;
end;
$fn$;
revoke execute on function public.ensure_system_columns(text) from public, anon, authenticated;

do $all$
declare t record;
begin
  for t in select table_name from information_schema.tables
            where table_schema = 'public' and table_type = 'BASE TABLE'
            order by table_name loop
    perform public.ensure_system_columns(t.table_name);
  end loop;
end;
$all$;

-- SPDX-License-Identifier: 0BSD
-- 0185 — #987/#989: environment pairs, and the permissions to deploy
-- and to enter the production side.
--
-- A workspace is created together with its twin: the dev and the prod
-- share a pair_id, the same name, country, currency and timezone, and
-- the creator owns both. A lone workspace gets its twin on demand, with
-- its configuration copied once. Three permissions join the matrix:
-- deployToProd (implies deployToDev), deployToDev, accessProd. Owner
-- and co-owner hold all three by default, admin holds deployToDev and
-- accessProd, member holds none. A member of the prod is always a
-- member of the dev (a trigger mirrors the row), and a role enters the
-- prod only while it holds accessProd.

alter table public.workspaces add column if not exists pair_id uuid;
create index if not exists workspaces_pair_idx on public.workspaces (pair_id);

-- ── the matrix ──────────────────────────────────────────────────────
create or replace function public.has_permission_raw(ws uuid, perm text)
returns boolean language sql stable security definer set search_path = public as $fn$
  select exists (
    select 1 from public.members m join public.workspaces w on w.id = ws
    where m.workspace_id = ws and m.user_id = auth.uid() and m.status = 'active'
      and ( m.is_owner
        or (m.co_owner = 'active' and (case when w.role_permissions ? 'co_owner' then w.role_permissions->'co_owner' ? perm else true end))
        or (m.is_admin and (
             (case when w.role_permissions ? 'admin' then w.role_permissions->'admin' ? perm
                   else perm in ('manageMembers','manageDocuments','manageServices','approveExpenses',
                                 'viewFinances','viewNegotiations','manageNegotiations','paymentTermsEdit',
                                 'manageSites','manageReservations','operateKiosk','exportData','viewPersonalData',
                                 'deployToDev','accessProd') end)
             or (perm = 'issueInvoices' and coalesce(w.feature_flags -> 'adminInvoicing' = to_jsonb(true), false))))
        or (not m.is_admin and not m.is_owner and m.co_owner <> 'active' and w.role_permissions ? 'member' and w.role_permissions->'member' ? perm)));
$fn$;

-- deployToProd implies deployToDev: whoever may push to the real side
-- may always refresh the working one.
create or replace function public.has_permission(ws uuid, perm text)
returns boolean language sql stable security definer set search_path = public as $fn$
  select public.has_permission_raw(ws, perm)
      or (perm = 'deployToDev' and public.has_permission_raw(ws, 'deployToProd'));
$fn$;

create or replace function public.member_has_permission(p_member_id uuid, perm text)
returns boolean language sql stable security definer set search_path = public as $fn$
  select exists (select 1 from public.members m join public.workspaces w on w.id = m.workspace_id
    where m.id = p_member_id and m.status = 'active'
      and ( m.is_owner
        or (m.co_owner = 'active' and (case when w.role_permissions ? 'co_owner' then w.role_permissions->'co_owner' ? perm else true end))
        or (m.is_admin and (case when w.role_permissions ? 'admin' then w.role_permissions->'admin' ? perm
              else perm in ('manageMembers','manageDocuments','manageServices','approveExpenses','viewFinances','viewNegotiations','manageNegotiations',
                            'manageSites','manageReservations','operateKiosk','exportData','viewPersonalData','deployToDev','accessProd') end))
        or (not m.is_admin and not m.is_owner and m.co_owner <> 'active' and w.role_permissions ? 'member' and w.role_permissions->'member' ? perm)))
    or (perm = 'deployToDev' and public.member_has_permission(p_member_id, 'deployToProd'));
$fn$;

-- What a ROLE holds in a workspace — for a row that is not a member yet.
create or replace function public.role_holds(ws uuid, p_role text, perm text)
returns boolean language sql stable security definer set search_path = public as $fn$
  select case p_role
    when 'owner' then true
    when 'co_owner' then (case when w.role_permissions ? 'co_owner' then w.role_permissions->'co_owner' ? perm else true end)
    when 'admin' then (case when w.role_permissions ? 'admin' then w.role_permissions->'admin' ? perm
                            else perm in ('manageMembers','manageDocuments','manageServices','approveExpenses','viewFinances',
                                          'viewNegotiations','manageNegotiations','paymentTermsEdit','manageSites','manageReservations',
                                          'operateKiosk','exportData','viewPersonalData','deployToDev','accessProd') end)
    else (w.role_permissions ? 'member' and w.role_permissions->'member' ? perm) end
  from public.workspaces w where w.id = ws;
$fn$;

do $patch$
declare v_def text; v_old text;
begin
  select pg_get_functiondef(p.oid) into v_def from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'set_role_permissions';
  v_old := '''designDocuments'',''viewPersonalData'',''manageIntegrations'',''manageConfiguration''];';
  if position(v_old in v_def) = 0 then raise exception 'catalog anchor missing'; end if;
  v_def := replace(v_def, v_old, '''designDocuments'',''viewPersonalData'',''manageIntegrations'',''manageConfiguration'',' || E'\n' ||
    '    ''deployToProd'',''deployToDev'',''accessProd''];');
  execute v_def;
end;
$patch$;

-- ── the pair ────────────────────────────────────────────────────────
drop function if exists public.create_workspace(text, text, text, text, text);
create or replace function public.create_workspace(
  p_name text, p_country_code text, p_currency_code text, p_timezone text,
  p_environment text default 'dev', p_with_twin boolean default true
) returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  ws_id uuid;
  twin_id uuid;
  v_pair uuid;
  v_other text;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if coalesce(p_environment, 'dev') not in ('dev', 'prod') then
    raise exception 'unknown environment %', p_environment;
  end if;
  v_pair := case when p_with_twin then gen_random_uuid() else null end;
  insert into public.workspaces
    (name, country_code, currency_code, timezone, created_by, environment, pair_id)
  values (p_name, upper(p_country_code), upper(p_currency_code), p_timezone,
          auth.uid(), coalesce(p_environment, 'dev'), v_pair)
  returning id into ws_id;
  insert into public.members (workspace_id, user_id, is_admin, is_owner)
  values (ws_id, auth.uid(), true, true);
  if p_with_twin then
    v_other := case when coalesce(p_environment, 'dev') = 'dev' then 'prod' else 'dev' end;
    insert into public.workspaces
      (name, country_code, currency_code, timezone, created_by, environment, pair_id)
    values (p_name, upper(p_country_code), upper(p_currency_code), p_timezone,
            auth.uid(), v_other, v_pair)
    returning id into twin_id;
    insert into public.members (workspace_id, user_id, is_admin, is_owner)
    values (twin_id, auth.uid(), true, true);
  end if;
  return ws_id;
end;
$fn$;

-- The twin of a lone workspace, its configuration copied once.
create or replace function public.workspace_twin_id(p_workspace_id uuid)
returns uuid language sql stable security definer set search_path = public as $fn$
  select t.id from public.workspaces w join public.workspaces t
    on t.pair_id = w.pair_id and t.id <> w.id
   where w.id = p_workspace_id and w.pair_id is not null
   limit 1;
$fn$;

create or replace function public.create_workspace_twin(p_workspace_id uuid)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_ws public.workspaces;
  twin_id uuid;
  v_pair uuid;
begin
  if not public.is_owner_of(p_workspace_id) then
    raise exception 'only owners may create the twin';
  end if;
  select * into v_ws from public.workspaces where id = p_workspace_id;
  if public.workspace_twin_id(p_workspace_id) is not null then
    raise exception 'this workspace already has its twin';
  end if;
  v_pair := coalesce(v_ws.pair_id, gen_random_uuid());
  update public.workspaces set pair_id = v_pair where id = p_workspace_id;
  insert into public.workspaces
    (name, country_code, currency_code, timezone, created_by, environment, pair_id)
  values (v_ws.name, v_ws.country_code, v_ws.currency_code, v_ws.timezone,
          auth.uid(), case when v_ws.environment = 'dev' then 'prod' else 'dev' end, v_pair)
  returning id into twin_id;
  insert into public.members (workspace_id, user_id, is_admin, is_owner)
  values (twin_id, auth.uid(), true, true);
  perform public.import_workspace_configuration(twin_id, public.export_workspace_configuration(p_workspace_id));
  return twin_id;
end;
$fn$;
revoke execute on function public.create_workspace_twin(uuid) from public, anon;

-- ── membership across the pair ──────────────────────────────────────
-- A role enters the production side only while it holds accessProd.
create or replace function public.members_prod_access_guard()
returns trigger language plpgsql security definer set search_path = public as $fn$
declare
  v_ws public.workspaces;
  v_role text;
begin
  select * into v_ws from public.workspaces where id = new.workspace_id;
  if v_ws.environment <> 'prod' or v_ws.pair_id is null or new.is_owner or new.user_id is null then
    return new;
  end if;
  v_role := case when new.co_owner = 'active' then 'co_owner'
                 when new.is_admin then 'admin' else 'member' end;
  if not public.role_holds(new.workspace_id, v_role, 'accessProd') then
    raise exception 'this role has no access to the production workspace';
  end if;
  return new;
end;
$fn$;
drop trigger if exists members_prod_access_guard on public.members;
create trigger members_prod_access_guard before insert on public.members
  for each row execute function public.members_prod_access_guard();

-- A member of the prod is always a member of the dev: the row is
-- mirrored (same role, same status) and follows role and status changes.
create or replace function public.members_mirror_to_dev()
returns trigger language plpgsql security definer set search_path = public as $fn$
declare
  v_ws public.workspaces;
  v_dev uuid;
begin
  if new.user_id is null then return new; end if;
  select * into v_ws from public.workspaces where id = new.workspace_id;
  if v_ws.environment <> 'prod' or v_ws.pair_id is null then return new; end if;
  select id into v_dev from public.workspaces where pair_id = v_ws.pair_id and environment = 'dev' and id <> v_ws.id limit 1;
  if v_dev is null then return new; end if;
  if exists (select 1 from public.members where workspace_id = v_dev and user_id = new.user_id) then
    update public.members
       set is_admin = new.is_admin, co_owner = new.co_owner, status = new.status
     where workspace_id = v_dev and user_id = new.user_id
       and (is_admin, co_owner, status) is distinct from (new.is_admin, new.co_owner, new.status)
       and not is_owner;
  else
    insert into public.members (workspace_id, user_id, is_admin, is_owner, co_owner, status, subscription_pct)
    values (v_dev, new.user_id, new.is_admin, false, new.co_owner, new.status, new.subscription_pct);
  end if;
  return new;
end;
$fn$;
drop trigger if exists members_mirror_to_dev on public.members;
create trigger members_mirror_to_dev after insert or update of is_admin, co_owner, status on public.members
  for each row execute function public.members_mirror_to_dev();

-- SPDX-License-Identifier: 0BSD
-- 0186 — #988: deployable entities, the preview, the deploy, the journal.
--
-- An ENTITY is a named slice of the configuration transfer (#916): the
-- workspace keys and the tables it owns, what it depends on, and its
-- kind (configuration or master data). The registry is one function;
-- export_entities filters the transfer document to the chosen entities;
-- preview_deployment diffs the two sides per entity by natural key;
-- deploy_entities applies the slice to the twin in one transaction and
-- journals it with what the target held before, so a deployment can be
-- rolled back. Transactional data never moves: the registry does not
-- know members, reservations, ledgers, invoices, payments or events.
--
-- Direction follows the side the actor stands on: into the prod needs
-- deployToProd on the source; into the dev needs deployToDev. The
-- transfer guards (exportData, manageConfiguration) are satisfied by
-- the deployment itself, through a transaction-local setting.

-- ── the registry ───────────────────────────────────────────────────
create or replace function public.deployable_entities()
returns jsonb language sql immutable as $fn$
  select jsonb_build_array(
    jsonb_build_object('key', 'identity', 'kind', 'configuration', 'requires', '[]'::jsonb,
      'workspace_keys', '["address","street","postal_code","city","default_locale","vat_regime","vat_id","legal_id","tax_exemption_reason","vat_account","invoice_legal"]'::jsonb,
      'tables', '[]'::jsonb),
    jsonb_build_object('key', 'vat', 'kind', 'master_data', 'requires', '[]'::jsonb,
      'workspace_keys', '["subscription_vat_rate"]'::jsonb, 'tables', '["vat_rates"]'::jsonb),
    jsonb_build_object('key', 'tariffs', 'kind', 'master_data', 'requires', '["vat"]'::jsonb,
      'workspace_keys', '["subscription_levels","billing_rules"]'::jsonb, 'tables', '["fee_bands","plans"]'::jsonb),
    jsonb_build_object('key', 'services', 'kind', 'master_data', 'requires', '["vat"]'::jsonb,
      'workspace_keys', '[]'::jsonb, 'tables', '["services"]'::jsonb),
    jsonb_build_object('key', 'packages', 'kind', 'master_data', 'requires', '["vat"]'::jsonb,
      'workspace_keys', '[]'::jsonb, 'tables', '["packages"]'::jsonb),
    jsonb_build_object('key', 'accessories', 'kind', 'master_data', 'requires', '["vat"]'::jsonb,
      'workspace_keys', '[]'::jsonb, 'tables', '["accessories"]'::jsonb),
    jsonb_build_object('key', 'sites', 'kind', 'master_data', 'requires', '[]'::jsonb,
      'workspace_keys', '[]'::jsonb, 'tables', '["sites"]'::jsonb),
    jsonb_build_object('key', 'booking_rules', 'kind', 'configuration', 'requires', '[]'::jsonb,
      'workspace_keys', '["booking_rules","desk_opacity"]'::jsonb, 'tables', '[]'::jsonb),
    jsonb_build_object('key', 'validation_rules', 'kind', 'configuration', 'requires', '[]'::jsonb,
      'workspace_keys', '[]'::jsonb, 'tables', '["validation_policies"]'::jsonb),
    jsonb_build_object('key', 'roles', 'kind', 'configuration', 'requires', '[]'::jsonb,
      'workspace_keys', '["role_permissions"]'::jsonb, 'tables', '[]'::jsonb),
    jsonb_build_object('key', 'reminders', 'kind', 'configuration', 'requires', '[]'::jsonb,
      'workspace_keys', '["dunning_rules"]'::jsonb, 'tables', '[]'::jsonb),
    jsonb_build_object('key', 'document_design', 'kind', 'configuration', 'requires', '[]'::jsonb,
      'workspace_keys', '["invoice_pdf_template"]'::jsonb, 'tables', '[]'::jsonb),
    jsonb_build_object('key', 'document_links', 'kind', 'configuration', 'requires', '[]'::jsonb,
      'workspace_keys', '[]'::jsonb, 'tables', '["workspace_documents"]'::jsonb),
    jsonb_build_object('key', 'closure_days', 'kind', 'configuration', 'requires', '[]'::jsonb,
      'workspace_keys', '[]'::jsonb, 'tables', '["closure_days"]'::jsonb),
    jsonb_build_object('key', 'invitations', 'kind', 'configuration', 'requires', '[]'::jsonb,
      'workspace_keys', '["invitation_template","invitation_templates","whatsapp_group"]'::jsonb, 'tables', '[]'::jsonb),
    jsonb_build_object('key', 'features', 'kind', 'configuration', 'requires', '[]'::jsonb,
      'workspace_keys', '["feature_flags"]'::jsonb, 'tables', '[]'::jsonb));
$fn$;

-- The natural key of each table's rows, for the diff.
create or replace function public.entity_row_key(p_table text, p_row jsonb)
returns text language sql immutable as $fn$
  select case p_table
    when 'vat_rates' then (p_row->>'label') || '@' || (p_row->>'percent')
    when 'fee_bands' then p_row->>'from_pct'
    when 'closure_days' then p_row->>'day'
    when 'validation_policies' then coalesce(p_row->>'event_type', 'default')
    when 'workspace_documents' then (p_row->>'title') || '@' || (p_row->>'url')
    else p_row->>'name' end;
$fn$;

-- ── the transfer learns features and accessories ───────────────────
do $patch$
declare v_def text; v_old text;
begin
  select pg_get_functiondef(p.oid) into v_def from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'export_workspace_configuration';
  v_old := '  if auth.uid() is null or not public.has_permission(p_workspace_id, ''exportData'') then';
  if position(v_old in v_def) = 0 then raise exception 'export guard anchor missing'; end if;
  v_def := replace(v_def, v_old, '  if auth.uid() is null or not (public.has_permission(p_workspace_id, ''exportData'') or public.deploying_touches(p_workspace_id)) then');
  v_old := '      ''invoice_pdf_template'', coalesce(w.invoice_pdf_template, ''{}''::jsonb)),';
  if position(v_old in v_def) = 0 then raise exception 'export keys anchor missing'; end if;
  v_def := replace(v_def, v_old, '      ''invoice_pdf_template'', coalesce(w.invoice_pdf_template, ''{}''::jsonb),' || E'\n' ||
    '      ''feature_flags'', coalesce(w.feature_flags, ''{}''::jsonb)),');
  v_old := '      ''workspace_documents'', coalesce((select jsonb_agg(jsonb_build_object(';
  if position(v_old in v_def) = 0 then raise exception 'export tables anchor missing'; end if;
  v_def := replace(v_def, v_old,
    '      ''accessories'', coalesce((select jsonb_agg(jsonb_build_object(' || E'\n' ||
    '          ''name'', a.name, ''supplement_cents'', a.supplement_cents, ''active'', a.active, ''sort_order'', a.sort_order,' || E'\n' ||
    '          ''vat_rate'', (select r.label from public.vat_rates r where r.id = a.vat_rate_id))' || E'\n' ||
    '          order by a.sort_order, a.name) from public.accessories a where a.workspace_id = p_workspace_id), ''[]''::jsonb),' || E'\n' ||
    v_old);
  execute v_def;

  select pg_get_functiondef(p.oid) into v_def from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'import_workspace_configuration';
  v_old := '  if auth.uid() is null or not public.has_permission(p_workspace_id, ''manageConfiguration'') then';
  if position(v_old in v_def) = 0 then raise exception 'import guard anchor missing'; end if;
  v_def := replace(v_def, v_old, '  if auth.uid() is null or not (public.has_permission(p_workspace_id, ''manageConfiguration'') or public.deploying_touches(p_workspace_id)) then');
  v_old := '    invoice_pdf_template = case when v_ws ? ''invoice_pdf_template'' then v_ws->''invoice_pdf_template'' else w.invoice_pdf_template end';
  if position(v_old in v_def) = 0 then raise exception 'import keys anchor missing'; end if;
  v_def := replace(v_def, v_old, v_old || ',' || E'\n' ||
    '    feature_flags = case when v_ws ? ''feature_flags'' then v_ws->''feature_flags'' else w.feature_flags end');
  v_old := '  if v_t ? ''workspace_documents'' then';
  if position(v_old in v_def) = 0 then raise exception 'import tables anchor missing'; end if;
  v_def := replace(v_def, v_old,
    '  if v_t ? ''accessories'' then' || E'\n' ||
    '    for v_row in select value from jsonb_array_elements(v_t->''accessories'') loop' || E'\n' ||
    '      select id into v_id from public.accessories where workspace_id = p_workspace_id and name = v_row->>''name'' order by created_at limit 1;' || E'\n' ||
    '      if v_id is null then' || E'\n' ||
    '        insert into public.accessories (workspace_id, name, supplement_cents, active, sort_order, vat_rate_id)' || E'\n' ||
    '        values (p_workspace_id, v_row->>''name'', coalesce((v_row->>''supplement_cents'')::int, 0), coalesce((v_row->>''active'')::boolean, true),' || E'\n' ||
    '                coalesce((v_row->>''sort_order'')::int, 0), public.vat_rate_id_by_label(p_workspace_id, v_row->>''vat_rate''));' || E'\n' ||
    '      else' || E'\n' ||
    '        update public.accessories set supplement_cents = coalesce((v_row->>''supplement_cents'')::int, 0),' || E'\n' ||
    '               active = coalesce((v_row->>''active'')::boolean, true), sort_order = coalesce((v_row->>''sort_order'')::int, 0),' || E'\n' ||
    '               vat_rate_id = public.vat_rate_id_by_label(p_workspace_id, v_row->>''vat_rate'')' || E'\n' ||
    '         where id = v_id;' || E'\n' ||
    '      end if;' || E'\n' ||
    '    end loop;' || E'\n' ||
    '    update public.accessories a set active = false where a.workspace_id = p_workspace_id' || E'\n' ||
    '       and not exists (select 1 from jsonb_array_elements(v_t->''accessories'') e where e.value->>''name'' = a.name);' || E'\n' ||
    '  end if;' || E'\n\n' || v_old);
  execute v_def;
end;
$patch$;

-- True while a deployment of this transaction touches the workspace.
create or replace function public.deploying_touches(p_workspace_id uuid)
returns boolean language sql stable as $fn$
  select p_workspace_id::text = any (string_to_array(coalesce(current_setting('deskilo.deploying', true), ''), ':'));
$fn$;

-- ── the slice ──────────────────────────────────────────────────────
create or replace function public.export_entities(p_workspace_id uuid, p_entities text[])
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_full jsonb;
  v_ws jsonb := '{}'::jsonb;
  v_t jsonb := '{}'::jsonb;
  v_e jsonb;
  v_k text;
begin
  v_full := public.export_workspace_configuration(p_workspace_id);
  for v_e in select value from jsonb_array_elements(public.deployable_entities()) loop
    if (v_e->>'key') = any (p_entities) then
      for v_k in select jsonb_array_elements_text(v_e->'workspace_keys') loop
        if v_full->'workspace' ? v_k then v_ws := v_ws || jsonb_build_object(v_k, v_full->'workspace'->v_k); end if;
      end loop;
      for v_k in select jsonb_array_elements_text(v_e->'tables') loop
        if v_full->'tables' ? v_k then v_t := v_t || jsonb_build_object(v_k, v_full->'tables'->v_k); end if;
      end loop;
    end if;
  end loop;
  return jsonb_build_object('entities', to_jsonb(p_entities), 'workspace', v_ws, 'tables', v_t);
end;
$fn$;

-- The pair check and the direction, in one place.
create or replace function public.deployment_direction(p_from uuid, p_to uuid)
returns text language plpgsql stable security definer set search_path = public as $fn$
declare v_from public.workspaces; v_to public.workspaces;
begin
  select * into v_from from public.workspaces where id = p_from;
  select * into v_to from public.workspaces where id = p_to;
  if v_from.id is null or v_to.id is null then raise exception 'unknown workspace'; end if;
  if v_from.id = v_to.id or v_from.pair_id is null or v_from.pair_id is distinct from v_to.pair_id then
    raise exception 'the two workspaces are not a pair';
  end if;
  return case when v_to.environment = 'prod' then 'dev_to_prod' else 'prod_to_dev' end;
end;
$fn$;

create or replace function public.may_deploy(p_from uuid, p_to uuid)
returns boolean language sql stable security definer set search_path = public as $fn$
  select case public.deployment_direction(p_from, p_to)
    when 'dev_to_prod' then public.has_permission(p_from, 'deployToProd')
    else public.has_permission(p_from, 'deployToDev') end;
$fn$;

-- ── the preview ────────────────────────────────────────────────────
create or replace function public.preview_deployment(p_from uuid, p_to uuid, p_entities text[])
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_src jsonb; v_dst jsonb; v_e jsonb; v_k text; v_out jsonb := '[]'::jsonb;
  v_added int; v_changed int; v_removed int; v_keys text[]; v_row jsonb; v_other jsonb; v_key text;
begin
  if not public.may_deploy(p_from, p_to) then raise exception 'not allowed to deploy in this direction'; end if;
  perform set_config('deskilo.deploying', p_from::text || ':' || p_to::text, true);
  v_src := public.export_entities(p_from, p_entities);
  v_dst := public.export_entities(p_to, p_entities);
  for v_e in select value from jsonb_array_elements(public.deployable_entities()) loop
    if not ((v_e->>'key') = any (p_entities)) then continue; end if;
    v_added := 0; v_changed := 0; v_removed := 0; v_keys := '{}';
    for v_k in select jsonb_array_elements_text(v_e->'workspace_keys') loop
      if (v_src->'workspace'->v_k) is distinct from (v_dst->'workspace'->v_k) then
        v_changed := v_changed + 1; v_keys := v_keys || v_k;
      end if;
    end loop;
    for v_k in select jsonb_array_elements_text(v_e->'tables') loop
      for v_row in select value from jsonb_array_elements(coalesce(v_src->'tables'->v_k, '[]'::jsonb)) loop
        v_key := public.entity_row_key(v_k, v_row);
        select value into v_other from jsonb_array_elements(coalesce(v_dst->'tables'->v_k, '[]'::jsonb)) o
         where public.entity_row_key(v_k, o.value) = v_key limit 1;
        if v_other is null then v_added := v_added + 1; v_keys := v_keys || ('+' || v_key);
        elsif v_other <> v_row then v_changed := v_changed + 1; v_keys := v_keys || ('~' || v_key); end if;
        v_other := null;
      end loop;
      for v_row in select value from jsonb_array_elements(coalesce(v_dst->'tables'->v_k, '[]'::jsonb)) loop
        v_key := public.entity_row_key(v_k, v_row);
        if not exists (select 1 from jsonb_array_elements(coalesce(v_src->'tables'->v_k, '[]'::jsonb)) s
                        where public.entity_row_key(v_k, s.value) = v_key) then
          v_removed := v_removed + 1; v_keys := v_keys || ('-' || v_key);
        end if;
      end loop;
    end loop;
    v_out := v_out || jsonb_build_object('key', v_e->>'key', 'kind', v_e->>'kind',
      'added', v_added, 'changed', v_changed, 'removed', v_removed, 'details', to_jsonb(v_keys));
  end loop;
  return jsonb_build_object('direction', public.deployment_direction(p_from, p_to), 'entities', v_out);
end;
$fn$;

-- ── the journal and the deploy ─────────────────────────────────────
create table if not exists public.deployments (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  pair_id uuid not null,
  from_workspace_id uuid not null references public.workspaces(id) on delete cascade,
  to_workspace_id uuid not null references public.workspaces(id) on delete cascade,
  direction text not null check (direction in ('dev_to_prod', 'prod_to_dev')),
  entities text[] not null,
  snapshot jsonb not null,
  before jsonb not null,
  summary jsonb not null default '[]'::jsonb,
  actor_user_id uuid,
  actor_name text not null default '',
  rolled_back_at timestamptz,
  created_at timestamptz not null default now()
);
select public.ensure_system_columns('deployments');
create index if not exists deployments_pair_idx on public.deployments (pair_id, created_at desc);
alter table public.deployments enable row level security;
drop policy if exists deployments_select on public.deployments;
create policy deployments_select on public.deployments for select to authenticated
  using (public.has_permission(from_workspace_id, 'deployToDev') or public.has_permission(to_workspace_id, 'deployToDev'));

create or replace function public.deploy_entities(p_from uuid, p_to uuid, p_entities text[])
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_direction text; v_preview jsonb; v_snapshot jsonb; v_before jsonb; v_id uuid; v_pair uuid; v_name text;
begin
  if p_entities is null or array_length(p_entities, 1) is null then raise exception 'nothing to deploy'; end if;
  v_direction := public.deployment_direction(p_from, p_to);
  if not public.may_deploy(p_from, p_to) then raise exception 'not allowed to deploy in this direction'; end if;
  perform set_config('deskilo.deploying', p_from::text || ':' || p_to::text, true);
  v_preview := public.preview_deployment(p_from, p_to, p_entities);
  v_before := public.export_entities(p_to, p_entities);
  v_snapshot := public.export_entities(p_from, p_entities);
  perform public.import_workspace_configuration(p_to, v_snapshot);
  select pair_id into v_pair from public.workspaces where id = p_from;
  select coalesce(display_name, '') into v_name from public.profiles where id = auth.uid();
  insert into public.deployments (workspace_id, pair_id, from_workspace_id, to_workspace_id, direction, entities, snapshot, before, summary, actor_user_id, actor_name)
  values (p_to, v_pair, p_from, p_to, v_direction, p_entities, v_snapshot, v_before, v_preview->'entities', auth.uid(), v_name)
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'direction', v_direction, 'entities', v_preview->'entities');
end;
$fn$;

-- Undo the last deployment of a pair: what the target held before goes back.
create or replace function public.rollback_deployment(p_deployment_id uuid)
returns void language plpgsql security definer set search_path = public as $fn$
declare v_d public.deployments;
begin
  select * into v_d from public.deployments where id = p_deployment_id;
  if v_d.id is null then raise exception 'unknown deployment'; end if;
  if v_d.rolled_back_at is not null then raise exception 'already rolled back'; end if;
  if not public.may_deploy(v_d.from_workspace_id, v_d.to_workspace_id) then raise exception 'not allowed to deploy in this direction'; end if;
  if exists (select 1 from public.deployments d where d.pair_id = v_d.pair_id and d.to_workspace_id = v_d.to_workspace_id
              and d.created_at > v_d.created_at and d.rolled_back_at is null) then
    raise exception 'a later deployment stands on this side; roll that one back first';
  end if;
  perform set_config('deskilo.deploying', v_d.from_workspace_id::text || ':' || v_d.to_workspace_id::text, true);
  perform public.import_workspace_configuration(v_d.to_workspace_id, v_d.before);
  update public.deployments set rolled_back_at = now() where id = p_deployment_id;
end;
$fn$;
revoke execute on function public.deploy_entities(uuid, uuid, text[]) from public, anon;
revoke execute on function public.rollback_deployment(uuid) from public, anon;
revoke execute on function public.preview_deployment(uuid, uuid, text[]) from public, anon;
revoke execute on function public.export_entities(uuid, text[]) from public, anon;

-- SPDX-License-Identifier: 0BSD
-- 0187 — #998: the deployment started from either side.
--
-- The permission is the DIRECTION's, and the actor holds it on the side
-- they stand on — which may be the target: pulling the dev into the
-- prod from the prod needs deployToProd there. So may_deploy asks
-- either side of the pair. The document designs — every report kind,
-- preset and language — form the reports group of the registry.
create or replace function public.may_deploy(p_from uuid, p_to uuid)
returns boolean language sql stable security definer set search_path = public as $fn$
  select case public.deployment_direction(p_from, p_to)
    when 'dev_to_prod' then public.has_permission(p_from, 'deployToProd') or public.has_permission(p_to, 'deployToProd')
    else public.has_permission(p_from, 'deployToDev') or public.has_permission(p_to, 'deployToDev') end;
$fn$;

do $patch$
declare v_def text; v_old text;
begin
  select pg_get_functiondef(p.oid) into v_def from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'deployable_entities';
  v_old := 'jsonb_build_object(''key'', ''document_design'', ''kind'', ''configuration'',';
  if position(v_old in v_def) = 0 then raise exception 'registry anchor missing'; end if;
  v_def := replace(v_def, v_old, 'jsonb_build_object(''key'', ''document_design'', ''kind'', ''reports'',');
  execute v_def;
end;
$patch$;

