// SPDX-License-Identifier: 0BSD
//
// #662 — sign in by scanning an RFID badge. The tag IDENTIFIES, a PIN
// CONFIRMS, and only this function can turn the pair into a session.
//
// WHY HERE AND NOT IN SQL. A database function that mints a login would
// be one `grant` away from being callable by `anon`, and an RFID UID is
// not a secret — it is broadcast to any reader a few centimetres away
// and clonable for about thirty euros. So `badge_auth_verify` is REVOKED
// from public, anon and authenticated (migration 0123), and reachable
// only by the service role that lives in this function's environment.
//
// TWO STEPS, ONE FORM.
//   {uid}        -> who is this? display name + avatar flag. No e-mail,
//                   no attempt consumed: a fumbled scan must not lock a
//                   member out before they have typed anything.
//   {uid, pin}   -> a one-time token the client exchanges for a session
//                   via supabase.auth.verifyOtp. The session is minted by
//                   GoTrue from an e-mail this function never returns.
//
// FAILURES ARE UNIFORM. Unknown tag, disarmed badge, wrong PIN and
// lockout all answer the same way, because telling them apart is how an
// attacker learns which tags are real. The distinction lives in the
// attempt log, which nothing outside the service role can read.

import { createClient } from "npm:@supabase/supabase-js@2";

const supabase = createClient(
  Deno.env.get("SUPABASE_URL")!,
  Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
);

const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...CORS, "Content-Type": "application/json" },
  });
}

/// The single refusal. Deliberately says nothing about WHY — see the
/// header. `locked` is separated only so the client can tell the member
/// to wait rather than keep trying; it reveals nothing about the tag,
/// because a lockout is reported for unknown tags too.
function refused(reason: "refused" | "locked"): Response {
  return json({ ok: false, reason }, 200);
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: CORS });
  if (req.method !== "POST") return json({ ok: false, reason: "refused" }, 405);

  let uid: string | undefined;
  let pin: string | undefined;
  try {
    const body = await req.json();
    uid = typeof body?.uid === "string" ? body.uid.trim() : undefined;
    pin = typeof body?.pin === "string" ? body.pin.trim() : undefined;
  } catch (_) {
    return refused("refused");
  }
  // A UID is lowercase hex without separators — the same normalization
  // register_nfc_badge applies. Reject anything else before it reaches
  // the database rather than hashing arbitrary input.
  if (!uid || !/^[0-9a-f]{4,64}$/.test(uid)) return refused("refused");
  if (pin !== undefined && !/^[0-9]{4,8}$/.test(pin)) return refused("refused");

  const { data, error } = await supabase.rpc("badge_auth_verify", {
    p_uid: uid,
    p_pin: pin ?? null,
  });
  if (error) {
    console.error("badge_auth_verify failed", error.message);
    return refused("refused");
  }
  if (!data?.ok) return refused(data?.reason === "locked" ? "locked" : "refused");

  // IDENTIFY — hand back just enough for the form to say whose PIN it is
  // asking for. Never the e-mail: that would make a scanned tag a way to
  // harvest addresses.
  if (pin === undefined) {
    return json({
      ok: true,
      step: "identify",
      display_name: data.display_name ?? "",
      has_avatar: data.has_avatar === true,
      user_id: data.user_id,
    });
  }

  // AUTHENTICATE — the PIN matched. Turn the verified user into a
  // one-time link and return only its token hash; the client exchanges
  // that for a session itself, so no access token is ever assembled here.
  const { data: userData, error: userError } =
    await supabase.auth.admin.getUserById(data.user_id);
  if (userError || !userData?.user?.email) {
    console.error("no e-mail for verified badge user", userError?.message);
    return refused("refused");
  }

  const { data: link, error: linkError } = await supabase.auth.admin.generateLink({
    type: "magiclink",
    email: userData.user.email,
  });
  if (linkError || !link?.properties?.hashed_token) {
    console.error("generateLink failed", linkError?.message);
    return refused("refused");
  }

  return json({
    ok: true,
    step: "authenticate",
    // Exchanged client-side with verifyOtp({ type: 'email', token_hash }).
    token_hash: link.properties.hashed_token,
  });
});

// SPDX-License-Identifier: 0BSD
//
// create-payment-order — starts a REAL online payment for a member's bill
// (docs/design/payments-integration.md). Providers: PayPal (Orders v2),
// Stripe (Checkout), Mollie (Payments).
//
// Credentials are PER WORKSPACE, configured from the owner UI and stored in
// the deny-all `payment_credentials` table (read here via the service role);
// deployment-wide env vars are the fallback. A provider whose required
// config is absent is not offered: {action:'config', workspace_id} lists the
// configured providers and, per provider, the missing config fields.

import { createClient, SupabaseClient } from "npm:@supabase/supabase-js@2";

type Provider = "paypal" | "stripe" | "mollie" | "wero";

/** Config field → env-var fallback, per provider. */
const FIELD_ENV: Record<Provider, Record<string, string>> = {
  paypal: {
    client_id: "PAYPAL_CLIENT_ID",
    secret: "PAYPAL_SECRET",
    env: "PAYPAL_ENV",
    webhook_id: "PAYPAL_WEBHOOK_ID",
    return_url: "PAYMENT_RETURN_URL",
  },
  stripe: {
    secret_key: "STRIPE_SECRET_KEY",
    webhook_secret: "STRIPE_WEBHOOK_SECRET",
    return_url: "PAYMENT_RETURN_URL",
  },
  mollie: {
    api_key: "MOLLIE_API_KEY",
    return_url: "PAYMENT_RETURN_URL",
  },
  // Wero rides Mollie (same API key), a distinct provider for the chooser.
  wero: {
    api_key: "MOLLIE_API_KEY",
    return_url: "PAYMENT_RETURN_URL",
  },
};

/** Fields a provider must have before it can be offered. */
const REQUIRED: Record<Provider, string[]> = {
  paypal: ["client_id", "secret", "return_url"],
  stripe: ["secret_key", "return_url"],
  mollie: ["api_key", "return_url"],
  wero: ["api_key", "return_url"],
};

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json" },
  });

/** Minor digits per ISO 4217 code (#711). The app stores every amount
 * in MINOR units; PayPal and Mollie want a major-unit decimal string,
 * and `/ 100` was only ever right for two-decimal currencies — a yen
 * order came out 100× too small, a dinar one 10×. Stripe takes minor
 * units directly and needs no conversion. */
const ZERO_DECIMAL = new Set(["BIF","CLP","DJF","GNF","ISK","JPY","KMF","KRW","PYG","RWF","UGX","VND","VUV","XAF","XOF","XPF"]);
const THREE_DECIMAL = new Set(["BHD","IQD","JOD","KWD","LYD","OMR","TND"]);
const minorDigits = (currency: string) =>
  ZERO_DECIMAL.has(currency.toUpperCase()) ? 0 : THREE_DECIMAL.has(currency.toUpperCase()) ? 3 : 2;
const major = (minor: number, currency: string) =>
  (minor / 10 ** minorDigits(currency)).toFixed(minorDigits(currency));

/** The effective config of a provider for a workspace: table row (owner UI)
 * overlaid on env-var fallbacks, per field. */
async function effectiveConfig(
  admin: SupabaseClient,
  workspaceId: string,
  provider: Provider,
): Promise<Record<string, string>> {
  const { data } = await admin
    .from("payment_credentials")
    .select("config")
    .eq("workspace_id", workspaceId)
    .eq("provider", provider)
    .maybeSingle();
  const stored = (data?.config ?? {}) as Record<string, string>;
  const out: Record<string, string> = {};
  for (const [field, envVar] of Object.entries(FIELD_ENV[provider])) {
    const value = stored[field] ?? Deno.env.get(envVar) ?? "";
    if (value) out[field] = value;
  }
  return out;
}

const missingFields = (config: Record<string, string>, provider: Provider) =>
  REQUIRED[provider].filter((f) => !config[f]);

const paypalApi = (env?: string) =>
  env === "live"
    ? "https://api-m.paypal.com"
    : "https://api-m.sandbox.paypal.com";

// ── providers ─────────────────────────────────────────────────────────

async function createPaypalOrder(
  cfg: Record<string, string>,
  amountCents: number,
  currency: string,
  reference: string,
): Promise<{ orderId: string; approveUrl: string }> {
  const auth = btoa(`${cfg.client_id}:${cfg.secret}`);
  const tokenRes = await fetch(`${paypalApi(cfg.env)}/v1/oauth2/token`, {
    method: "POST",
    headers: {
      Authorization: `Basic ${auth}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: "grant_type=client_credentials",
  });
  if (!tokenRes.ok) {
    throw new Error(`paypal oauth ${tokenRes.status}: ${await tokenRes.text()}`);
  }
  const { access_token } = await tokenRes.json();
  const orderRes = await fetch(`${paypalApi(cfg.env)}/v2/checkout/orders`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${access_token}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      intent: "CAPTURE",
      purchase_units: [{
        amount: { currency_code: currency, value: major(amountCents, currency) },
        custom_id: reference,
      }],
      application_context: {
        return_url: cfg.return_url,
        cancel_url: cfg.return_url,
        user_action: "PAY_NOW",
      },
    }),
  });
  if (!orderRes.ok) {
    throw new Error(`paypal order ${orderRes.status}: ${await orderRes.text()}`);
  }
  const order = await orderRes.json();
  const approve = (order.links ?? []).find(
    (l: { rel: string }) => l.rel === "approve",
  );
  if (!approve) throw new Error("paypal order has no approve link");
  return { orderId: order.id, approveUrl: approve.href };
}

async function createStripeSession(
  cfg: Record<string, string>,
  amountCents: number,
  currency: string,
  reference: string,
): Promise<{ orderId: string; approveUrl: string }> {
  const params = new URLSearchParams({
    mode: "payment",
    success_url: cfg.return_url,
    cancel_url: cfg.return_url,
    client_reference_id: reference,
    "line_items[0][quantity]": "1",
    "line_items[0][price_data][currency]": currency.toLowerCase(),
    "line_items[0][price_data][unit_amount]": String(amountCents),
    "line_items[0][price_data][product_data][name]": `DesKilo ${reference}`,
  });
  const res = await fetch("https://api.stripe.com/v1/checkout/sessions", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${cfg.secret_key}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: params,
  });
  if (!res.ok) {
    throw new Error(`stripe session ${res.status}: ${await res.text()}`);
  }
  const session = await res.json();
  return { orderId: session.id, approveUrl: session.url };
}

async function createMolliePayment(
  cfg: Record<string, string>,
  amountCents: number,
  currency: string,
  reference: string,
  method?: string,
): Promise<{ orderId: string; approveUrl: string }> {
  const res = await fetch("https://api.mollie.com/v2/payments", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${cfg.api_key}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      amount: { currency, value: major(amountCents, currency) },
      description: `DesKilo ${reference}`,
      redirectUrl: cfg.return_url,
      metadata: { reference },
      ...(method ? { method } : {}),
    }),
  });
  if (!res.ok) {
    throw new Error(`mollie payment ${res.status}: ${await res.text()}`);
  }
  const payment = await res.json();
  return { orderId: payment.id, approveUrl: payment._links.checkout.href };
}

// ── handler ───────────────────────────────────────────────────────────

Deno.serve(async (req: Request): Promise<Response> => {
  if (req.method !== "POST") return json({ error: "method_not_allowed" }, 405);
  let body: Record<string, unknown>;
  try {
    body = await req.json();
  } catch {
    return json({ error: "invalid_json" }, 400);
  }

  const admin = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
  );
  const workspaceId = body.workspace_id as string;
  if (!workspaceId) return json({ error: "invalid_request" }, 400);

  // AuthN for EVERY action (security audit): the config probe used to
  // answer unauthenticated callers, disclosing which payment providers
  // a workspace has configured. Membership is checked per action below.
  const token = (req.headers.get("Authorization") ?? "").replace(
    "Bearer ",
    "",
  );
  const { data: userData, error: userError } = await admin.auth.getUser(token);
  if (userError || !userData?.user) {
    console.error("payment auth failed", userError?.message);
    return json({ error: "unauthorized" }, 401);
  }

  // Config probe: which providers can THIS workspace charge with?
  if (body.action === "config") {
    const { data: caller } = await admin
      .from("members")
      .select("id")
      .eq("workspace_id", workspaceId)
      .eq("user_id", userData.user.id)
      .eq("status", "active")
      .maybeSingle();
    if (!caller) return json({ error: "unauthorized" }, 403);
    const providers: Provider[] = [];
    const missing: Record<string, string[]> = {};
    for (const provider of Object.keys(REQUIRED) as Provider[]) {
      const cfg = await effectiveConfig(admin, workspaceId, provider);
      const gap = missingFields(cfg, provider);
      missing[provider] = gap;
      if (gap.length === 0) providers.push(provider);
    }
    console.log("payment config probe", { workspaceId, providers, missing });
    return json({ providers, missing });
  }

  // #917 — a DEVELOPMENT workspace never opens a payment order: the
  // providers below take real money from a real card. Probing the
  // configuration above stays allowed, so a rehearsal space can be set
  // up exactly like the real one; only the charge is refused.
  const { data: ws } = await admin
    .from("workspaces")
    .select("environment")
    .eq("id", workspaceId)
    .maybeSingle();
  if ((ws?.environment ?? "dev") !== "prod") {
    return json({
      error: "development_workspace",
      detail:
        "This workspace is a development one: it does not take payments. " +
        "Declare it production to charge for real.",
    }, 409);
  }

  const provider = body.provider as Provider;
  const memberId = body.member_id as string;
  const amountCents = body.amount_cents as number;
  const currency = ((body.currency as string) ?? "EUR").toUpperCase();
  const period = body.period as string;
  if (
    !provider || !(provider in REQUIRED) || !memberId ||
    typeof amountCents !== "number" || amountCents <= 0 || !period
  ) {
    return json({ error: "invalid_request" }, 400);
  }

  const cfg = await effectiveConfig(admin, workspaceId, provider);
  const gap = missingFields(cfg, provider);
  if (gap.length > 0) {
    console.log("payment provider not configured", { provider, gap });
    return json({ status: "not_configured", provider, missing: gap });
  }

  // AuthZ: the JWT's user (verified above) must BE the member they pay
  // for.
  const { data: member } = await admin
    .from("members")
    .select("id, user_id, workspace_id, status")
    .eq("id", memberId)
    .single();
  if (
    !member || member.user_id !== userData.user.id ||
    member.workspace_id !== workspaceId || member.status !== "active"
  ) {
    console.error("payment member mismatch", { memberId, workspaceId });
    return json({ error: "not_your_bill" }, 403);
  }

  // #928 — a readable per-workspace reference (PAY-2026-0117) drawn by
  // the number-sequence framework inside the intent's own insert; the
  // provider's order id is patched in once the provider has answered.
  const { data: opened, error: openError } = await admin.rpc(
    "open_payment_intent",
    {
      p_workspace_id: workspaceId,
      p_member_id: memberId,
      p_provider: provider,
      p_period: period,
      p_amount_cents: amountCents,
      p_currency: currency,
    },
  );
  const intent = Array.isArray(opened) ? opened[0] : opened;
  if (openError || !intent?.reference) {
    console.error("payment intent open failed", openError?.message);
    return json({ error: "intent_open_failed" }, 500);
  }
  const reference: string = intent.reference;
  try {
    const order = provider === "paypal"
      ? await createPaypalOrder(cfg, amountCents, currency, reference)
      : provider === "stripe"
      ? await createStripeSession(cfg, amountCents, currency, reference)
      : provider === "wero"
      ? await createMolliePayment(cfg, amountCents, currency, reference, "wero")
      : await createMolliePayment(cfg, amountCents, currency, reference);

    const { error: insertError } = await admin
      .from("payment_intents")
      .update({ order_id: order.orderId })
      .eq("id", intent.id);
    if (insertError) {
      console.error("payment intent update failed", insertError.message);
      return json({ error: "intent_insert_failed" }, 500);
    }
    console.log("payment order created", {
      provider,
      orderId: order.orderId,
      amountCents,
      currency,
      period,
    });
    return json({
      status: "created",
      provider,
      order_id: order.orderId,
      approve_url: order.approveUrl,
    });
  } catch (e) {
    // The provider refused or timed out: the intent stays as the honest
    // record of a failed attempt — its number is not reused.
    await admin.from("payment_intents").update({ status: "failed" }).eq("id", intent.id);
    const detail = e instanceof Error ? e.message : String(e);
    console.error("payment order failed", { provider, detail });
    return json({ error: "provider_error", provider, detail }, 502);
  }
});

// SPDX-License-Identifier: 0BSD
//
// mollie-webhook — verify_jwt OFF; authenticity from FETCHING the payment
// back from Mollie with the workspace's API key (the body is untrusted).
// Credentials are PER WORKSPACE: the payment id resolves the
// payment_intents row → workspace → that workspace's Mollie key (table
// first, env fallback). Settlement is idempotent.

import { createClient, SupabaseClient } from "npm:@supabase/supabase-js@2";

// The key of the provider the intent was created with — Wero is offered
// through Mollie but stores its own credentials (this is what is deployed
// as v3; the repo had lagged behind it).
async function apiKey(
  admin: SupabaseClient,
  workspaceId: string,
  provider: string,
): Promise<string> {
  const { data } = await admin
    .from("payment_credentials")
    .select("config")
    .eq("workspace_id", workspaceId)
    .eq("provider", provider)
    .maybeSingle();
  const stored = (data?.config ?? {}) as Record<string, string>;
  return stored.api_key ?? Deno.env.get("MOLLIE_API_KEY") ?? "";
}

Deno.serve(async (req: Request): Promise<Response> => {
  if (req.method !== "POST") return new Response("method_not_allowed", { status: 405 });

  const form = await req.formData().catch((error) => {
    console.warn("mollie-webhook: unreadable form body", error);
    return null;
  });
  const paymentId = form?.get("id");
  if (typeof paymentId !== "string" || paymentId.length === 0) {
    return new Response("invalid_request", { status: 400 });
  }

  const admin = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
  );
  // Mollie's webhook covers all its payments, including Wero (offered
  // through Mollie). Match either provider and settle with the actual one.
  const { data: intent } = await admin
    .from("payment_intents")
    .select("workspace_id, provider")
    .in("provider", ["mollie", "wero"])
    .eq("order_id", paymentId)
    .maybeSingle();
  if (!intent) {
    console.log("mollie webhook: unknown payment, ignoring", paymentId);
    return new Response("ok", { status: 200 });
  }
  const settleProvider = intent.provider as string;
  const key = await apiKey(admin, intent.workspace_id, settleProvider);
  if (!key) {
    console.log("mollie webhook not configured for workspace", intent.workspace_id);
    return new Response("not_configured", { status: 200 });
  }

  const res = await fetch(
    `https://api.mollie.com/v2/payments/${encodeURIComponent(paymentId)}`,
    { headers: { Authorization: `Bearer ${key}` } },
  );
  if (!res.ok) {
    console.error("mollie payment fetch failed", res.status);
    return new Response("fetch_failed", { status: 500 });
  }
  const payment = await res.json();

  if (payment.status === "paid") {
    const cents = payment.amount?.value
      ? Math.round(parseFloat(payment.amount.value) * 100)
      : null;
    const { error } = await admin.rpc("settle_online_payment", {
      p_provider: settleProvider,
      p_order_id: paymentId,
      p_capture_id: paymentId,
      p_amount_cents: cents,
    });
    if (error) {
      console.error("mollie settle failed", error.message);
      return new Response("settle_failed", { status: 500 });
    }
    console.log("mollie payment settled", { paymentId, settleProvider });
  } else if (
    ["failed", "canceled", "expired"].includes(payment.status as string)
  ) {
    await admin.rpc("mark_payment_failed", {
      p_provider: settleProvider,
      p_order_id: paymentId,
    });
    console.log("mollie payment marked failed", { paymentId, status: payment.status });
  } else {
    console.log("mollie webhook ignored status", payment.status);
  }
  return new Response("ok", { status: 200 });
});

// SPDX-License-Identifier: 0BSD
//
// paypal-webhook — verify_jwt OFF; authenticity from PayPal's own
// webhook-signature verification. Credentials are PER WORKSPACE: the
// event's order id resolves the payment_intents row → workspace →
// that workspace's PayPal config (table first, env fallback). Settlement
// goes through the service-role settle_online_payment RPC (idempotent).

import { createClient, SupabaseClient } from "npm:@supabase/supabase-js@2";

async function paypalConfig(
  admin: SupabaseClient,
  workspaceId: string,
): Promise<Record<string, string>> {
  const { data } = await admin
    .from("payment_credentials")
    .select("config")
    .eq("workspace_id", workspaceId)
    .eq("provider", "paypal")
    .maybeSingle();
  const stored = (data?.config ?? {}) as Record<string, string>;
  return {
    client_id: stored.client_id ?? Deno.env.get("PAYPAL_CLIENT_ID") ?? "",
    secret: stored.secret ?? Deno.env.get("PAYPAL_SECRET") ?? "",
    env: stored.env ?? Deno.env.get("PAYPAL_ENV") ?? "sandbox",
    webhook_id: stored.webhook_id ?? Deno.env.get("PAYPAL_WEBHOOK_ID") ?? "",
  };
}

const paypalApi = (env: string) =>
  env === "live"
    ? "https://api-m.paypal.com"
    : "https://api-m.sandbox.paypal.com";

async function accessToken(cfg: Record<string, string>): Promise<string> {
  const auth = btoa(`${cfg.client_id}:${cfg.secret}`);
  const res = await fetch(`${paypalApi(cfg.env)}/v1/oauth2/token`, {
    method: "POST",
    headers: {
      Authorization: `Basic ${auth}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: "grant_type=client_credentials",
  });
  if (!res.ok) throw new Error(`paypal oauth ${res.status}`);
  return (await res.json()).access_token;
}

Deno.serve(async (req: Request): Promise<Response> => {
  if (req.method !== "POST") return new Response("method_not_allowed", { status: 405 });

  let event: Record<string, unknown>;
  try {
    event = JSON.parse(await req.text());
  } catch {
    return new Response("invalid_json", { status: 400 });
  }

  const admin = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
  );
  const resource = (event.resource ?? {}) as Record<string, unknown>;
  const orderId = String(
    ((resource.supplementary_data as Record<string, unknown> | undefined)
      ?.related_ids as Record<string, unknown> | undefined)?.order_id ??
      resource.id ?? "",
  );

  // Resolve the workspace from the intent, then load ITS PayPal config.
  const { data: intent } = await admin
    .from("payment_intents")
    .select("workspace_id")
    .eq("provider", "paypal")
    .eq("order_id", orderId)
    .maybeSingle();
  if (!intent) {
    console.log("paypal webhook: unknown order, ignoring", orderId);
    return new Response("ok", { status: 200 });
  }
  const cfg = await paypalConfig(admin, intent.workspace_id);
  if (!cfg.webhook_id || !cfg.client_id) {
    console.log("paypal webhook not configured for workspace", intent.workspace_id);
    return new Response("not_configured", { status: 200 });
  }

  // Verify the transmission against PayPal before trusting anything.
  try {
    const token = await accessToken(cfg);
    const verifyRes = await fetch(
      `${paypalApi(cfg.env)}/v1/notifications/verify-webhook-signature`,
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          transmission_id: req.headers.get("paypal-transmission-id"),
          transmission_time: req.headers.get("paypal-transmission-time"),
          cert_url: req.headers.get("paypal-cert-url"),
          auth_algo: req.headers.get("paypal-auth-algo"),
          transmission_sig: req.headers.get("paypal-transmission-sig"),
          webhook_id: cfg.webhook_id,
          webhook_event: event,
        }),
      },
    );
    const verification = await verifyRes.json();
    if (verification.verification_status !== "SUCCESS") {
      console.error("paypal webhook verification FAILED", verification);
      return new Response("verification_failed", { status: 400 });
    }
  } catch (e) {
    console.error("paypal webhook verification error", String(e));
    return new Response("verification_error", { status: 500 });
  }

  const type = event.event_type as string;
  if (type === "PAYMENT.CAPTURE.COMPLETED") {
    const amount = resource.amount as { value?: string } | undefined;
    const cents = amount?.value
      ? Math.round(parseFloat(amount.value) * 100)
      : null;
    const { error } = await admin.rpc("settle_online_payment", {
      p_provider: "paypal",
      p_order_id: orderId,
      p_capture_id: String(resource.id),
      p_amount_cents: cents,
    });
    if (error) {
      console.error("paypal settle failed", error.message);
      return new Response("settle_failed", { status: 500 });
    }
    console.log("paypal capture settled", { orderId, capture: resource.id });
  } else if (
    type === "PAYMENT.CAPTURE.DENIED" || type === "CHECKOUT.ORDER.VOIDED"
  ) {
    await admin.rpc("mark_payment_failed", {
      p_provider: "paypal",
      p_order_id: orderId,
    });
    console.log("paypal payment marked failed", { orderId, type });
  } else {
    console.log("paypal webhook ignored event", type);
  }
  return new Response("ok", { status: 200 });
});

// SPDX-License-Identifier: 0BSD
//
// send-e-invoice — posts an issued invoice to the workspace's e-invoicing
// platform, so "Envoyer" sends instead of handing the user a file.
//
// The CLIENT builds the document (Factur-X PDF or EN 16931 XML) with the
// same builders that produce the download, and posts the bytes here; this
// function holds the credential and does the transmission. That split is
// deliberate: the platform token must never reach a phone, and the
// document must never be rebuilt from a second, divergent code path.
//
// Providers: 'generic' — any platform that accepts an HTTP upload with a
// bearer/basic credential (that covers most plateformes agréées, Peppol
// access points and clearance-platform upload APIs). Named adapters can
// join REQUIRED/submit() without touching the client.
//
// Every attempt is logged to invoice_transmissions, accepted or not: a
// document that may or may not have left is worse than one that failed.

import { createClient, SupabaseClient } from "npm:@supabase/supabase-js@2";

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json" },
  });

/** Fields the generic adapter needs before it can send anything. */
const REQUIRED = ["endpoint", "auth_value"];

/** Where a document may be sent. 'prod' is the unsuffixed key set that
 * predates environments; 'uat'/'dev' read the suffixed keys (0074). */
const ENVIRONMENTS = ["prod", "uat", "dev"] as const;
type Environment = (typeof ENVIRONMENTS)[number];

/** WHO receives the document (#568): the platform the government mandate
 * points at, or the customer's own delivery service. 'government' is the
 * unprefixed key set that predates destinations; 'customer' reads the
 * customer_-prefixed keys. */
const DESTINATIONS = ["government", "customer"] as const;
type Destination = (typeof DESTINATIONS)[number];

type Config = Record<string, string>;

/** The config as one destination sees it. The customer channel is a
 * SEPARATE endpoint and credential — never a fallback to the government
 * ones, because an invoice quietly landing on the wrong platform is the
 * accident this split exists to prevent. */
function configForDestination(cfg: Config, dest: Destination): Config {
  if (dest === "government") {
    return Object.fromEntries(
      Object.entries(cfg).filter(([key]) => !key.startsWith("customer_")),
    );
  }
  return Object.fromEntries(
    Object.entries(cfg)
      .filter(([key]) => key.startsWith("customer_"))
      .map(([key, value]) => [key.slice("customer_".length), value]),
  );
}

/** The config as one environment sees it. endpoint and auth_value are
 * STRICTLY per-environment — no fallback to prod, because a UAT document
 * silently reaching the production platform is the exact accident this
 * feature exists to prevent. Header and field name fall back to the
 * production values, then to the adapter defaults: they describe the
 * upload shape, not the destination. */
function configFor(cfg: Config, env: Environment): Config {
  if (env === "prod") return cfg;
  return {
    ...cfg,
    endpoint: cfg[`endpoint_${env}`] ?? "",
    auth_value: cfg[`auth_value_${env}`] ?? "",
    auth_header: cfg[`auth_header_${env}`] || cfg.auth_header || "",
    field_name: cfg[`field_name_${env}`] || cfg.field_name || "",
  };
}

function missingFor(cfg: Config, env: Environment): string[] {
  const scoped = configFor(cfg, env);
  return REQUIRED.filter((field) => !scoped[field]);
}

async function sha256(bytes: Uint8Array): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return [...new Uint8Array(digest)]
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

/** POSTs the document as multipart/form-data — the shape upload endpoints
 * agree on. `auth_header` defaults to Authorization, `field_name` to file. */
async function submitGeneric(
  cfg: Config,
  fileName: string,
  mimeType: string,
  bytes: Uint8Array,
): Promise<{ status: "accepted" | "rejected"; externalId: string; detail: string }> {
  const form = new FormData();
  form.append(
    cfg.field_name || "file",
    new Blob([bytes], { type: mimeType }),
    fileName,
  );
  const res = await fetch(cfg.endpoint, {
    method: "POST",
    headers: { [cfg.auth_header || "Authorization"]: cfg.auth_value },
    body: form,
  });
  const text = await res.text();
  if (!res.ok) {
    return {
      status: "rejected",
      externalId: "",
      detail: `${res.status} ${text}`.slice(0, 500),
    };
  }
  // Most platforms answer JSON with an id under one of these names.
  let externalId = "";
  try {
    const body = JSON.parse(text);
    externalId = String(
      body.id ?? body.documentId ?? body.document_id ?? body.guid ??
        body.transmissionId ?? "",
    );
  } catch {
    // A plain-text acknowledgement is still an acknowledgement.
    externalId = text.trim().slice(0, 120);
  }
  return { status: "accepted", externalId, detail: text.slice(0, 500) };
}

Deno.serve(async (req) => {
  if (req.method !== "POST") return json({ error: "method not allowed" }, 405);

  const url = Deno.env.get("SUPABASE_URL")!;
  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
  const anonKey = Deno.env.get("SUPABASE_ANON_KEY")!;
  const authorization = req.headers.get("Authorization") ?? "";

  let payload: {
    workspace_id?: string;
    invoice_id?: string;
    declaration_id?: string;
    file_name?: string;
    mime_type?: string;
    content_base64?: string;
    action?: string;
    environment?: string;
    destination?: string;
  };
  try {
    payload = await req.json();
  } catch (error) {
    console.warn("send-e-invoice: invalid body", error);
    return json({ error: "invalid body" }, 400);
  }
  const workspaceId = payload.workspace_id ?? "";
  if (!workspaceId) return json({ error: "workspace_id required" }, 400);

  const admin: SupabaseClient = createClient(url, serviceKey);
  const { data: credentials } = await admin
    .from("einvoice_credentials")
    .select("provider, config")
    .eq("workspace_id", workspaceId)
    .maybeSingle();
  const fullCfg = (credentials?.config ?? {}) as Config;
  const environment = (
    ENVIRONMENTS as readonly string[]
  ).includes(payload.environment ?? "")
    ? (payload.environment as Environment)
    : "prod";
  const destination = (
    DESTINATIONS as readonly string[]
  ).includes(payload.destination ?? "")
    ? (payload.destination as Destination)
    : "government";
  const cfg = configForDestination(fullCfg, destination);
  const missing = missingFor(cfg, environment);

  // The client asks first whether sending is even possible, so it can hide
  // the affordance instead of offering a button that cannot work. The
  // per-environment map doubles as the deployment probe: a client only
  // offers the UAT/dev choice when this function demonstrably understands
  // it — an older function would ignore the parameter and send to prod.
  // The per-destination map (#568) is the same latch for the customer leg.
  if (payload.action === "config") {
    const govCfg = configForDestination(fullCfg, "government");
    return json({
      configured: missingFor(govCfg, "prod").length === 0,
      provider: credentials?.provider ?? "generic",
      missing: missingFor(govCfg, "prod"),
      environments: Object.fromEntries(
        ENVIRONMENTS.map((env) => [env, missingFor(govCfg, env).length === 0]),
      ),
      destinations: Object.fromEntries(
        DESTINATIONS.map((dest) => {
          const scoped = configForDestination(fullCfg, dest);
          return [dest, {
            configured: missingFor(scoped, "prod").length === 0,
            missing: missingFor(scoped, "prod"),
            environments: Object.fromEntries(
              ENVIRONMENTS.map(
                (env) => [env, missingFor(scoped, env).length === 0],
              ),
            ),
          }];
        }),
      ),
    });
  }

  // #917 — a DEVELOPMENT workspace does not talk to the outside world.
  // Reading configuration is fine — the owner sets a rehearsal space up
  // exactly as the real one — but nothing leaves it: the government
  // platform and the customer's service both receive documents that are
  // legal instruments, and a rehearsal document is not one. Checked
  // AFTER the config branch above, which only reports what is set, and
  // before any credential is used.
  const { data: ws } = await admin
    .from("workspaces")
    .select("environment")
    .eq("id", workspaceId)
    .maybeSingle();
  if ((ws?.environment ?? "dev") !== "prod") {
    return json({
      error: "development_workspace",
      detail:
        "This workspace is a development one: it does not send documents " +
        "to a government platform or to a customer. Declare it production " +
        "to send for real.",
    }, 409);
  }

  if (missing.length > 0) {
    return json({ error: "not_configured", missing, environment }, 409);
  }

  // WHO is asking: the caller's own JWT, checked against the workspace.
  // The service role must never send on behalf of a stranger.
  const caller = createClient(url, anonKey, {
    global: { headers: { Authorization: authorization } },
  });
  const { data: me } = await caller
    .from("members")
    .select("id, is_admin, is_owner, status")
    .eq("workspace_id", workspaceId)
    .maybeSingle();
  if (!me || me.status !== "active" || !(me.is_admin || me.is_owner)) {
    return json({ error: "not an admin of this workspace" }, 403);
  }

  // #534 — VAT declarations ride the SAME configured channel: the owner
  // (only) posts the declaration document to the platform; an accepted
  // upload stamps the declaration submitted with the platform's receipt.
  const declarationId = payload.declaration_id ?? "";
  if (declarationId) {
    if (!me.is_owner) {
      return json({ error: "only the owner files VAT declarations" }, 403);
    }
    const content2 = payload.content_base64 ?? "";
    if (!content2) return json({ error: "content_base64 required" }, 400);
    const { data: declaration } = await admin
      .from("vat_declarations")
      .select("id, workspace_id, status, period_start")
      .eq("id", declarationId)
      .maybeSingle();
    if (!declaration || declaration.workspace_id !== workspaceId) {
      return json({ error: "unknown declaration" }, 404);
    }
    if (declaration.status === "submitted") {
      return json({ error: "already submitted" }, 409);
    }
    const bytes2 = Uint8Array.from(atob(content2), (c) => c.charCodeAt(0));
    let outcome2: {
      status: "accepted" | "rejected" | "failed";
      externalId: string;
      detail: string;
    };
    try {
      // A declaration is a filing: it goes to the government platform no
      // matter what destination a client claims.
      outcome2 = await submitGeneric(
        configFor(configForDestination(fullCfg, "government"), environment),
        payload.file_name || `vat-${declaration.period_start}.pdf`,
        payload.mime_type || "application/pdf",
        bytes2,
      );
    } catch (error) {
      console.error("send-e-invoice: VAT declaration transmission failed", error);
      outcome2 = {
        status: "failed",
        externalId: "",
        detail: String(error).slice(0, 500),
      };
    }
    if (outcome2.status === "accepted") {
      await admin.from("vat_declarations").update({
        status: "submitted",
        submitted_at: new Date().toISOString(),
        submitted_channel: "platform",
        submitted_receipt:
          (outcome2.externalId || outcome2.detail).slice(0, 500),
      }).eq("id", declarationId);
    }
    return json({
      status: outcome2.status,
      external_id: outcome2.externalId,
      detail: outcome2.detail,
      environment,
    }, outcome2.status === "accepted" ? 200 : 502);
  }

  const invoiceId = payload.invoice_id ?? "";
  const content = payload.content_base64 ?? "";
  if (!invoiceId || !content) {
    return json({ error: "invoice_id and content_base64 required" }, 400);
  }
  const { data: invoice } = await admin
    .from("invoices")
    .select("id, number, workspace_id")
    .eq("id", invoiceId)
    .maybeSingle();
  if (!invoice || invoice.workspace_id !== workspaceId) {
    return json({ error: "unknown invoice" }, 404);
  }

  const bytes = Uint8Array.from(atob(content), (c) => c.charCodeAt(0));
  const hash = await sha256(bytes);
  const fileName = payload.file_name || `${invoice.number}.pdf`;
  const mimeType = payload.mime_type || "application/pdf";

  let outcome: {
    status: "accepted" | "rejected" | "failed";
    externalId: string;
    detail: string;
  };
  try {
    outcome = await submitGeneric(
      configFor(cfg, environment),
      fileName,
      mimeType,
      bytes,
    );
  } catch (error) {
    console.error("send-e-invoice: transmission failed", error);
    outcome = {
      status: "failed",
      externalId: "",
      detail: String(error).slice(0, 500),
    };
  }

  const { data: profile } = await admin
    .from("profiles")
    .select("display_name")
    .eq("id", (await caller.auth.getUser()).data.user?.id ?? "")
    .maybeSingle();

  await admin.from("invoice_transmissions").insert({
    workspace_id: workspaceId,
    invoice_id: invoiceId,
    provider: credentials?.provider ?? "generic",
    status: outcome.status,
    external_id: outcome.externalId,
    document_hash: hash,
    detail: outcome.detail,
    by_name: profile?.display_name ?? "",
    environment,
    destination,
  });

  return json({
    status: outcome.status,
    external_id: outcome.externalId,
    detail: outcome.detail,
    environment,
    destination,
  }, outcome.status === "accepted" ? 200 : 502);
});

// SPDX-License-Identifier: 0BSD
//
// FCM fanout (#426): the 0084 events trigger POSTs {event_id} here; this
// function loads the event ITSELF with the service role and computes the
// recipients — the caller is never trusted with recipients or content, so
// a spoofed call can at worst re-announce a real event. UnifiedPush
// endpoints are still POSTed directly from the trigger; this function
// handles the fcm:<token> rows, which need an OAuth2-signed FCM v1 call
// pg_net cannot make.
//
// Secrets: FCM_SERVICE_ACCOUNT — the Firebase service-account JSON
// (docs/guides/push-setup.md). Absent -> the function no-ops politely so
// the trigger never fails.

import { createClient } from "npm:@supabase/supabase-js@2";

const supabase = createClient(
  Deno.env.get("SUPABASE_URL")!,
  Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
);

// Generic English notification text per kind (the 0012 privacy doctrine:
// no names, no times; a foregrounded app replaces this with its own
// localized notification).
const TEXTS: Record<string, { title: string; body: string }> = {
  pending_request: {
    title: "DesKilo",
    body: "Someone needs your confirmation.",
  },
  reservation_cancelled: {
    title: "Reservation removed",
    body: "A reservation was removed by an admin.",
  },
  member_note: {
    title: "DesKilo",
    body: "You have a new message.",
  },
  // #726 — automatic dunning: the subject member, nobody else.
  invoice_reminder: {
    title: "DesKilo",
    body: "A payment reminder is waiting for you.",
  },
};

async function fcmAccessToken(sa: {
  client_email: string;
  private_key: string;
}): Promise<string> {
  const now = Math.floor(Date.now() / 1000);
  const header = { alg: "RS256", typ: "JWT" };
  const claims = {
    iss: sa.client_email,
    scope: "https://www.googleapis.com/auth/firebase.messaging",
    aud: "https://oauth2.googleapis.com/token",
    iat: now,
    exp: now + 3600,
  };
  const enc = (o: unknown) =>
    btoa(JSON.stringify(o)).replace(/\+/g, "-").replace(/\//g, "_")
      .replace(/=+$/, "");
  const unsigned = `${enc(header)}.${enc(claims)}`;
  const pem = sa.private_key.replace(/-----[^-]+-----/g, "").replace(/\s/g, "");
  const key = await crypto.subtle.importKey(
    "pkcs8",
    Uint8Array.from(atob(pem), (c) => c.charCodeAt(0)),
    { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const sig = await crypto.subtle.sign(
    "RSASSA-PKCS1-v1_5",
    key,
    new TextEncoder().encode(unsigned),
  );
  const sigB64 = btoa(String.fromCharCode(...new Uint8Array(sig)))
    .replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  const res = await fetch("https://oauth2.googleapis.com/token", {
    method: "POST",
    headers: { "content-type": "application/x-www-form-urlencoded" },
    body: `grant_type=urn%3Aietf%3Aparams%3Aoauth%3Agrant-type%3Ajwt-bearer&assertion=${unsigned}.${sigB64}`,
  });
  if (!res.ok) throw new Error(`token exchange failed: ${await res.text()}`);
  return (await res.json()).access_token as string;
}

Deno.serve(async (req) => {
  const saRaw = Deno.env.get("FCM_SERVICE_ACCOUNT");
  if (!saRaw) {
    return Response.json({ skipped: "FCM_SERVICE_ACCOUNT not set" });
  }
  const sa = JSON.parse(saRaw);

  const { event_id, note_id } = await req.json().catch(() => ({}));
  if (!event_id && !note_id) {
    return Response.json({ error: "event_id or note_id required" }, { status: 400 });
  }

  let kind: string;
  let recipients: { id: string }[];
  if (note_id) {
    // Member note (#456): load it ourselves — recipient is the target,
    // or every active admin/owner except the sender for broadcasts.
    const { data: note } = await supabase
      .from("member_notes")
      .select("id, workspace_id, from_member_id, to_member_id")
      .eq("id", note_id)
      .maybeSingle();
    if (!note) return Response.json({ error: "unknown note" }, { status: 404 });
    kind = "member_note";
    if (note.to_member_id) {
      recipients = [{ id: note.to_member_id }];
    } else {
      const { data: admins } = await supabase
        .from("members")
        .select("id, is_admin, is_owner")
        .eq("workspace_id", note.workspace_id)
        .eq("status", "active")
        .neq("id", note.from_member_id);
      recipients = (admins ?? []).filter((m) => m.is_admin || m.is_owner);
    }
  } else {
    // Load the event ourselves — never trust the caller's content.
    const { data: event } = await supabase
      .from("events")
      .select("id, workspace_id, type, action, status, actor_member_id, subject_member_id")
      .eq("id", event_id)
      .maybeSingle();
    if (!event) return Response.json({ error: "unknown event" }, { status: 404 });

    const eventKind = event.status === "pending"
      ? "pending_request"
      : event.type === "reservation" && event.action === "cancelled"
      ? "reservation_cancelled"
      : event.type === "invoice_reminder"
      ? "invoice_reminder"
      : null;
    if (!eventKind) return Response.json({ skipped: "kind not pushed" });
    kind = eventKind;

    // Recipients — the 0082 rules, re-derived here for fcm rows.
    const { data: members } = await supabase
      .from("members")
      .select("id, is_admin, is_owner")
      .eq("workspace_id", event.workspace_id)
      .eq("status", "active")
      .neq("id", event.actor_member_id);
    recipients = (members ?? []).filter((m) =>
      kind === "reservation_cancelled"
        ? m.id === event.subject_member_id || m.is_admin || m.is_owner
        : m.id === event.subject_member_id
    );
    // The sweep acts AS the owner; a reminder for the owner's own
    // invoice must still reach them.
    if (kind === "invoice_reminder" && recipients.length === 0) {
      recipients = [{ id: event.subject_member_id }];
    }
  }
  if (recipients.length === 0) return Response.json({ sent: 0 });

  const { data: endpoints } = await supabase
    .from("push_endpoints")
    .select("member_id, endpoint")
    .in("member_id", recipients.map((m) => m.id))
    .like("endpoint", "fcm:%");
  if (!endpoints || endpoints.length === 0) return Response.json({ sent: 0 });

  const token = await fcmAccessToken(sa);
  const text = TEXTS[kind];
  let sent = 0;
  for (const ep of endpoints) {
    // iOS/macOS badge: the recipient's live pending count.
    const { count } = await supabase
      .from("events")
      .select("id", { count: "exact", head: true })
      .eq("subject_member_id", ep.member_id)
      .eq("status", "pending");
    const message = {
      message: {
        token: ep.endpoint.slice(4),
        notification: { title: text.title, body: text.body },
        data: { kind },
        apns: { payload: { aps: { badge: count ?? 0 } } },
      },
    };
    const res = await fetch(
      `https://fcm.googleapis.com/v1/projects/${sa.project_id}/messages:send`,
      {
        method: "POST",
        headers: {
          authorization: `Bearer ${token}`,
          "content-type": "application/json",
        },
        body: JSON.stringify(message),
      },
    );
    if (res.ok) sent++;
    else if (res.status === 404 || res.status === 410) {
      // Dead token: prune the endpoint row.
      await supabase.from("push_endpoints").delete().eq("endpoint", ep.endpoint);
    }
  }
  return Response.json({ sent });
});

// SPDX-License-Identifier: 0BSD
//
// WhatsApp delivery of member notes (field request): the 0106 trigger
// POSTs {note_id}; this function loads the note ITSELF with the service
// role and computes the recipients — the caller is never trusted with
// recipients or content. Each opted-in recipient (profiles.whatsapp set
// AND profiles.whatsapp_notes true) gets the message as the in-app
// messenger reads it: reference tokens replaced by their labels, each
// reference as a tappable web link, and a final link that opens the app
// directly on the conversation.
//
// Credentials (#552): the workspace's own channel from the deny-all
// workspace_channels table (owner-configured in the app), else the
// WHATSAPP_TOKEN + WHATSAPP_PHONE_ID env secrets. Neither present ->
// the function no-ops politely so the trigger never fails. NOTE:
// WhatsApp only delivers free-form messages inside the 24h service
// window; outside it the API rejects and the send is logged and
// dropped (the in-app message and push are the source of truth,
// WhatsApp is a mirror).

import { createClient } from "npm:@supabase/supabase-js@2";

const supabase = createClient(
  Deno.env.get("SUPABASE_URL")!,
  Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
);

// The published web app — the same Flutter app, hash routing.
const APP_URL = "https://fdittgen-png.github.io/deskilo/#";

// Mirror of lib/features/workspace/domain/member_note_refs.dart.
const REF = /\[(?:res:([A-Za-z0-9-]{4,})|space:(seat|desk|office|level):([A-Za-z0-9-]{4,}))\|([^\]]+)\]/g;

/// Body as the reader sees it (labels), plus one web link per reference.
function render(body: string, noteId: string): string {
  const links: string[] = [];
  const plain = body.replace(
    REF,
    (_m, resId: string, kind: string, spaceId: string, label: string) => {
      links.push(
        resId
          ? `↗ ${label}: ${APP_URL}/res/${resId}`
          : `↗ ${label}: ${APP_URL}/space/${kind}/${spaceId}`,
      );
      return label;
    },
  );
  const parts = [plain];
  if (links.length > 0) parts.push("", ...links);
  parts.push("", `DesKilo: ${APP_URL}/msg/${noteId}`);
  return parts.join("\n");
}

/// The workspace's own channel (#552), else the env secrets, else null.
async function channelFor(
  workspaceId: string | null,
): Promise<{ token: string; phoneId: string } | null> {
  if (workspaceId) {
    const { data } = await supabase
      .from("workspace_channels")
      .select("whatsapp")
      .eq("workspace_id", workspaceId)
      .maybeSingle();
    const cfg = (data?.whatsapp ?? {}) as {
      token?: string;
      phone_id?: string;
    };
    if (cfg.token && cfg.phone_id) {
      return { token: cfg.token, phoneId: cfg.phone_id };
    }
  }
  const token = Deno.env.get("WHATSAPP_TOKEN");
  const phoneId = Deno.env.get("WHATSAPP_PHONE_ID");
  return token && phoneId ? { token, phoneId } : null;
}

Deno.serve(async (req) => {
  const payload = await req.json().catch(() => ({}));
  // The client probes BEFORE offering the opt-in switch as functional —
  // a silently dead channel reads as "not working" (field report).
  // #552: the probe is per WORKSPACE when the client names one.
  if (payload.action === "config") {
    const channel = await channelFor(payload.workspace_id ?? null);
    return new Response(
      JSON.stringify({ configured: channel !== null }),
      { status: 200, headers: { "Content-Type": "application/json" } },
    );
  }

  const note_id = payload.note_id;
  if (!note_id) return new Response("missing note_id", { status: 400 });

  const { data: note } = await supabase
    .from("member_notes")
    .select("id, workspace_id, from_member_id, to_member_id, body")
    .eq("id", note_id)
    .maybeSingle();
  if (!note) return new Response("unknown note", { status: 200 });

  const channel = await channelFor(note.workspace_id);
  if (!channel) {
    return new Response("whatsapp not configured", { status: 200 });
  }
  const { token, phoneId } = channel;

  // Recipients: the direct addressee, or — broadcast — every admin and
  // the owner except the sender.
  let memberQuery = supabase
    .from("members")
    .select("id, user_id")
    .eq("workspace_id", note.workspace_id)
    .eq("status", "active");
  memberQuery = note.to_member_id
    ? memberQuery.eq("id", note.to_member_id)
    : memberQuery.or("is_admin.eq.true,is_owner.eq.true")
        .neq("id", note.from_member_id);
  const { data: recipients } = await memberQuery;
  if (!recipients || recipients.length === 0) {
    return new Response("no recipients", { status: 200 });
  }

  const { data: senderRow } = await supabase
    .from("members")
    .select("user_id")
    .eq("id", note.from_member_id)
    .maybeSingle();
  const { data: senderProfile } = senderRow
    ? await supabase
        .from("profiles")
        .select("display_name")
        .eq("id", senderRow.user_id)
        .maybeSingle()
    : { data: null };
  const sender = senderProfile?.display_name || "DesKilo";

  const { data: profiles } = await supabase
    .from("profiles")
    .select("id, whatsapp, whatsapp_notes")
    .in("id", recipients.map((r: { user_id: string }) => r.user_id));

  const text = `\u{1F4AC} ${sender}\n${render(note.body, note.id)}`;
  let sent = 0;
  for (const p of profiles ?? []) {
    if (!p.whatsapp || !p.whatsapp_notes) continue;
    const to = String(p.whatsapp).replace(/^\+/, "");
    const res = await fetch(
      `https://graph.facebook.com/v20.0/${phoneId}/messages`,
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          messaging_product: "whatsapp",
          to,
          type: "text",
          text: { body: text, preview_url: false },
        }),
      },
    );
    if (res.ok) {
      sent += 1;
    } else {
      // Outside the 24h window / bad number: log and move on — the
      // in-app message and the push already delivered.
      console.error("whatsapp send failed", to, await res.text());
    }
  }
  return new Response(JSON.stringify({ sent }), { status: 200 });
});

// SPDX-License-Identifier: 0BSD
//
// stripe-webhook — verify_jwt OFF; authenticity from the Stripe-Signature
// header (HMAC-SHA256). Credentials are PER WORKSPACE: the session id
// resolves the payment_intents row → workspace → that workspace's Stripe
// webhook secret (table first, env fallback). Settlement is idempotent.

import { createClient, SupabaseClient } from "npm:@supabase/supabase-js@2";

async function webhookSecret(
  admin: SupabaseClient,
  workspaceId: string,
): Promise<string> {
  const { data } = await admin
    .from("payment_credentials")
    .select("config")
    .eq("workspace_id", workspaceId)
    .eq("provider", "stripe")
    .maybeSingle();
  const stored = (data?.config ?? {}) as Record<string, string>;
  return stored.webhook_secret ?? Deno.env.get("STRIPE_WEBHOOK_SECRET") ?? "";
}

async function validSignature(
  payload: string,
  header: string,
  secret: string,
): Promise<boolean> {
  const parts = Object.fromEntries(
    header.split(",").map((p) => p.split("=") as [string, string]),
  );
  const timestamp = parts["t"];
  const signature = parts["v1"];
  if (!timestamp || !signature) return false;
  if (Math.abs(Date.now() / 1000 - Number(timestamp)) > 300) return false;
  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const mac = await crypto.subtle.sign(
    "HMAC",
    key,
    new TextEncoder().encode(`${timestamp}.${payload}`),
  );
  const expected = [...new Uint8Array(mac)]
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
  // Constant-time compare (security audit): `===` short-circuits on the
  // first mismatched byte, leaking a timing side-channel on the one
  // auth-critical comparison in this function.
  if (expected.length !== signature.length) return false;
  let diff = 0;
  for (let i = 0; i < expected.length; i++) {
    diff |= expected.charCodeAt(i) ^ signature.charCodeAt(i);
  }
  return diff === 0;
}

Deno.serve(async (req: Request): Promise<Response> => {
  if (req.method !== "POST") return new Response("method_not_allowed", { status: 405 });

  const payload = await req.text();
  let event: Record<string, unknown>;
  try {
    event = JSON.parse(payload);
  } catch {
    return new Response("invalid_json", { status: 400 });
  }
  const object = ((event.data as Record<string, unknown>)?.object ??
    {}) as Record<string, unknown>;
  const sessionId = String(object.id ?? "");

  const admin = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
  );
  const { data: intent } = await admin
    .from("payment_intents")
    .select("workspace_id")
    .eq("provider", "stripe")
    .eq("order_id", sessionId)
    .maybeSingle();
  if (!intent) {
    console.log("stripe webhook: unknown session, ignoring", sessionId);
    return new Response("ok", { status: 200 });
  }
  const secret = await webhookSecret(admin, intent.workspace_id);
  if (!secret) {
    console.log("stripe webhook not configured for workspace", intent.workspace_id);
    return new Response("not_configured", { status: 200 });
  }
  if (
    !(await validSignature(
      payload,
      req.headers.get("stripe-signature") ?? "",
      secret,
    ))
  ) {
    console.error("stripe webhook signature verification FAILED");
    return new Response("verification_failed", { status: 400 });
  }

  if (event.type === "checkout.session.completed") {
    const { error } = await admin.rpc("settle_online_payment", {
      p_provider: "stripe",
      p_order_id: sessionId,
      p_capture_id: String(object.payment_intent ?? sessionId),
      p_amount_cents: object.amount_total ?? null,
    });
    if (error) {
      console.error("stripe settle failed", error.message);
      return new Response("settle_failed", { status: 500 });
    }
    console.log("stripe session settled", { session: sessionId });
  } else if (event.type === "checkout.session.expired") {
    await admin.rpc("mark_payment_failed", {
      p_provider: "stripe",
      p_order_id: sessionId,
    });
    console.log("stripe session marked failed", sessionId);
  } else {
    console.log("stripe webhook ignored event", event.type);
  }
  return new Response("ok", { status: 200 });
});
